    /// <summary>
    /// Gets the runtime-derived default active-writer budget for this process.<br/>
    /// The effective processor count reflects runtime CPU and container limits; the half-width budget leaves execution capacity for routing, publication, readers, and the host application.<br/>
    /// </summary>
    internal static int DefaultConcurrentWriterCount => Math.Max(1, (Environment.ProcessorCount + 1) / 2);

    /// <summary>
    /// Enters the file-session concurrent-write scheduler with either the automatic budget or an expert override.<br/>
    /// </summary>
    /// <param name="maximumActiveWriters">The optional expert writer-count override.<br/></param>
    /// <param name="cancellationToken">A token that may cancel this request while it is queued.<br/></param>
    /// <returns>An active admission lease.<br/></returns>
    internal LibraDexWriteAdmissionLease EnterConcurrentWriteAdmission(
        int? maximumActiveWriters,
        int maximumQueuedWriters,
        TimeSpan queueTimeout,
        CancellationToken cancellationToken)
    {
        int resolvedMaximum = maximumActiveWriters ?? DefaultConcurrentWriterCount;
        if (resolvedMaximum <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(maximumActiveWriters),
                resolvedMaximum,
                "The concurrent writer limit must be positive.");
        }

        return concurrentWriteAdmission.Enter(
            resolvedMaximum,
            maximumQueuedWriters,
            queueTimeout,
            cancellationToken);
    }

    /// <summary>
    /// Asynchronously enters the file-session concurrent-write scheduler without occupying a blocked caller thread.<br/>
    /// </summary>
    internal ValueTask<LibraDexWriteAdmissionLease> EnterConcurrentWriteAdmissionAsync(
        int? maximumActiveWriters,
        int maximumQueuedWriters,
        TimeSpan queueTimeout,
        CancellationToken cancellationToken)
    {
        int resolvedMaximum = maximumActiveWriters ?? DefaultConcurrentWriterCount;
        if (resolvedMaximum <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maximumActiveWriters));
        }

        return concurrentWriteAdmission.EnterAsync(
            resolvedMaximum,
            maximumQueuedWriters,
            queueTimeout,
            cancellationToken);
    }

    /// <summary>
    /// Gets the current concurrent-write admission and shelf-wait snapshot.<br/>
    /// </summary>
    internal LibraDexWriteAdmissionDiagnostics GetConcurrentWriteAdmissionDiagnostics()
    {
        return concurrentWriteAdmission.GetDiagnostics() with
        {
            ShelfWaitCount = Interlocked.Read(ref writeContextShelfWaitCount),
            ShelfWaitTicks = Interlocked.Read(ref writeContextShelfWaitTicks)
        };
    }

    /// <summary>
    /// Enters a coherent raw-read scope used by a logical streaming cursor.<br/>
    /// Memory sessions receive a copy-on-write snapshot, while file sessions retain their existing per-read storage gate without holding a lock across caller code.<br/>
    /// </summary>
    /// <returns>A thread-affine scope that must be disposed with the owning cursor.<br/></returns>
    internal DataKernel.CoherentReadLease EnterCoherentRead()
        => kernel.EnterCoherentRead();

    /// <summary>
    /// Waits until a conflicting writer context releases one physical shelf offset.<br/>
    /// A shelf-targeted completion signal parks only threads blocked by that physical shelf, avoiding both unbounded CPU spin and unrelated monitor wakeups.<br/>
    /// </summary>
    /// <param name="shelfOffset">The physical shelf offset reported by the ownership exception.<br/></param>
    /// <param name="cancellationToken">A token that may stop the wait before a retry begins.<br/></param>
    internal void WaitForWriteContextShelfRelease(long shelfOffset, CancellationToken cancellationToken)
    {
        long started = Stopwatch.GetTimestamp();
        Interlocked.Increment(ref writeContextShelfWaitCount);
        try
        {
            while (true)
            {
                cancellationToken.ThrowIfCancellationRequested();
                Task releaseTask;
                lock (writeContextAdmissionSync)
                {
                    if (!IsWriteContextShelfOwned(shelfOffset))
                    {
                        return;
                    }

                    if (!writeContextShelfReleaseSignals.TryGetValue(shelfOffset, out TaskCompletionSource<bool>? signal))
                    {
                        signal = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
                        writeContextShelfReleaseSignals.Add(shelfOffset, signal);
                    }

                    releaseTask = signal.Task;
                }

                releaseTask.Wait(cancellationToken);
            }
        }
        finally
        {
            Interlocked.Add(ref writeContextShelfWaitTicks, Math.Max(0, Stopwatch.GetTimestamp() - started));
        }
    }

    private bool IsWriteContextShelfOwned(long shelfOffset)
    {
        return scalar8Scalar8WriterShelfOwners.ContainsKey(shelfOffset) ||
            scalar16Scalar8WriterShelfOwners.ContainsKey(shelfOffset) ||
            scalar8Scalar16WriterShelfOwners.ContainsKey(shelfOffset) ||
            scalar16Scalar16WriterShelfOwners.ContainsKey(shelfOffset) ||
            fixed32Scalar8WriterShelfOwners.ContainsKey(shelfOffset) ||
            fixed32Scalar16WriterShelfOwners.ContainsKey(shelfOffset) ||
            fixedNScalar8WriterShelfOwners.ContainsKey(shelfOffset) ||
            fixedNScalar16WriterShelfOwners.ContainsKey(shelfOffset) ||
            varKeyScalar8WriterShelfOwners.ContainsKey(shelfOffset) ||
            varKeyScalar16WriterShelfOwners.ContainsKey(shelfOffset) ||
            varKeyVarIdentityWriterShelfOwners.ContainsKey(shelfOffset) ||
            scalar8VarIdentityWriterShelfOwners.ContainsKey(shelfOffset) ||
            scalar16VarIdentityWriterShelfOwners.ContainsKey(shelfOffset) ||
            terminalIdentity8WriterShelfOwners.ContainsKey(shelfOffset);
    }

    /// <summary>
    /// Completes shelf-targeted wait signals whose owner entries were removed by the current release operation.<br/>
    /// The caller must hold <see cref="writeContextAdmissionSync"/> so ownership inspection, signal removal, and completion form one lost-wakeup-free state transition.<br/>
    /// </summary>
    private void SignalReleasedWriteContextShelves()
    {
        releasedWriteContextShelfSignals.Clear();
        foreach ((long shelfOffset, TaskCompletionSource<bool> _) in writeContextShelfReleaseSignals)
        {
            if (!IsWriteContextShelfOwned(shelfOffset))
            {
                releasedWriteContextShelfSignals.Add(shelfOffset);
            }
        }

        for (int i = 0; i < releasedWriteContextShelfSignals.Count; i++)
        {
            long shelfOffset = releasedWriteContextShelfSignals[i];
            if (writeContextShelfReleaseSignals.Remove(shelfOffset, out TaskCompletionSource<bool>? signal))
            {
                signal.TrySetResult(true);
            }
        }

        releasedWriteContextShelfSignals.Clear();
    }

