    private LibraDexFileSession(
        DataKernel kernel,
        SuperblockSnapshot superblock,
        IndexDirectorySnapshot indexDirectory,
        LibraDexDiagnosticsLevel diagnosticsLevel)
    {
        this.kernel = kernel;
        detailedWriteWindowOwnershipDiagnostics = diagnosticsLevel == LibraDexDiagnosticsLevel.Detailed;
        Superblock = superblock;
        IndexDirectory = indexDirectory;
    }

