    /// <summary>
    /// Records one `VS8` route-walker diagnostic slice against the current thread-local reindex diagnostics.<br/>
    /// The helper exists so route internals can be instrumented without allocating closures, delegates, generic state, or per-call label objects.<br/>
    /// </summary>
    /// <param name="phaseName">The stable diagnostic phase name.</param>
    /// <param name="startTicks">The timestamp captured before the measured work began.</param>
    /// <param name="startAllocatedBytes">The thread allocation counter captured before the measured work began.</param>
    private static void RecordVarKeyScalar8RouteAllocation(string phaseName, long startTicks, long startAllocatedBytes)
    {
        if (varKeyScalar8PhaseDiagnostics is null)
        {
            return;
        }

        varKeyScalar8PhaseDiagnostics.Record(
            phaseName,
            Stopwatch.GetTimestamp() - startTicks,
            GC.GetAllocatedBytesForCurrentThread() - startAllocatedBytes);
    }

    private Scalar8Scalar8RoutedInsertResult InsertOrConvertScalar8Scalar8DuplicateRun(
        Scalar8Scalar8RoutePathTarget pathTarget,
        ReadOnlySpan<byte> existingShelfBytes,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long headShelfOffset = pathTarget.Target.Offset;
        Scalar8Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid)
        {
            throw new InvalidDataException("The SS8-8 duplicate-run source shelf is invalid.");
        }

        if (existingShelf.IsDuplicateRun)
        {
            return InsertIntoScalar8Scalar8DuplicateRun(headShelfOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys);
        }

        int existingCount = existingShelf.ItemCount;
        if (existingCount == 0 || !allowDuplicateKeys)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                allowDuplicateKeys ? Scalar8Scalar8RoutedInsertKind.NoOp : Scalar8Scalar8RoutedInsertKind.KeyConflict,
                allowDuplicateKeys ? Scalar8Scalar8InsertResult.Full : Scalar8Scalar8InsertResult.KeyConflict,
                headShelfOffset,
                0,
                0,
                default);
        }

        int matchingCount = 0;
        int otherCount = 0;
        for (int i = 0; i < existingCount; i++)
        {
            if (existingShelf.ReadKeyAt(i) == encodedKey)
            {
                matchingCount++;
            }
            else
            {
                otherCount++;
            }
        }

        if (matchingCount == 0)
        {
            throw new InvalidDataException("The SS8-8 duplicate-run conversion did not find the routed key in the source shelf.");
        }

        ulong[] identities = new ulong[matchingCount + 1];
        bool inserted = false;
        int writeIndex = 0;
        for (int i = 0; i < existingCount; i++)
        {
            if (existingShelf.ReadKeyAt(i) != encodedKey)
            {
                continue;
            }

            ulong currentIdentity = existingShelf.ReadIdentityAt(i);
            if (!inserted && currentIdentity > encodedIdentity)
            {
                identities[writeIndex++] = encodedIdentity;
                inserted = true;
            }

            if (currentIdentity == encodedIdentity)
            {
                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.NoOp,
                    Scalar8Scalar8InsertResult.AlreadyPresent,
                    headShelfOffset,
                    0,
                    0,
                    default);
            }

            identities[writeIndex++] = currentIdentity;
        }

        if (!inserted)
        {
            identities[writeIndex] = encodedIdentity;
        }

        Span<byte> keyBytes = stackalloc byte[Scalar8Scalar8Layout.KeySize];
        BinaryPrimitives.WriteUInt64BigEndian(keyBytes, encodedKey);
        DiscardScalar8Scalar8MutableBatchShelfBytes(headShelfOffset);
        long terminalRootOffset = otherCount == 0
            ? headShelfOffset
            : kernel.Reserve(TerminalIdentityRootLayout.Size).Extent.Offset;
        DataKernelCommitTelemetry telemetry = RewriteTerminalIdentity8Route(
            terminalRootOffset,
            TerminalIdentityRootLayout.ShapeScalar8,
            keyBytes,
            profile.ShelfExtentSize,
            identities,
            obsoleteFirstShelfOffset: 0);

        bool linked = otherCount == 0
            ? TryReplaceSingleByteRouterPrefixOnlyIfCurrent(pathTarget.ParentRouterOffset, pathTarget.RoutePrefixByte, headShelfOffset, terminalRootOffset, obsoleteTargetLength: 0, out _)
            : TryReplaceScalar8Scalar8MixedDuplicateShelfRoute(
                pathTarget,
                existingShelf,
                profile,
                encodedKey,
                terminalRootOffset,
                headShelfOffset,
                out _);
        if (!linked)
        {
            throw new InvalidDataException("The SS8-8 duplicate-run terminal route parent changed before the terminal root could be linked.");
        }

        return new Scalar8Scalar8RoutedInsertResult(
            Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
            Scalar8Scalar8InsertResult.Inserted,
            terminalRootOffset,
            terminalRootOffset,
            0,
            telemetry);
    }

    private Scalar8Scalar8RoutedInsertResult InsertIntoScalar8Scalar8TerminalIdentityRoute(
        long rootOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        Span<byte> expectedKey = stackalloc byte[Scalar8Scalar8Layout.KeySize];
        BinaryPrimitives.WriteUInt64BigEndian(expectedKey, encodedKey);
        if (TryAppendTerminalIdentity8Tail(rootOffset, expectedKey, profile.ShelfExtentSize, encodedIdentity, allowDuplicateKeys, out DataKernelCommitTelemetry appendTelemetry))
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                Scalar8Scalar8InsertResult.Inserted,
                rootOffset,
                rootOffset,
                0,
                appendTelemetry);
        }

        long obsoleteFirstShelfOffset = ReadTerminalIdentityFirstShelfOffset(rootOffset, expectedKey);
        List<ulong> identities = ReadTerminalIdentity8RouteIdentities(rootOffset, expectedKey, profile.ShelfExtentSize);
        if (!allowDuplicateKeys && identities.Count != 0)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                Scalar8Scalar8InsertResult.KeyConflict,
                rootOffset,
                0,
                0,
                default);
        }

        int insertIndex = identities.BinarySearch(encodedIdentity);
        if (insertIndex >= 0)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                Scalar8Scalar8InsertResult.AlreadyPresent,
                rootOffset,
                0,
                0,
                default);
        }

        identities.Insert(~insertIndex, encodedIdentity);
        DataKernelCommitTelemetry telemetry = RewriteTerminalIdentity8Route(
            rootOffset,
            TerminalIdentityRootLayout.ShapeScalar8,
            expectedKey,
            profile.ShelfExtentSize,
            identities,
            obsoleteFirstShelfOffset);
        return new Scalar8Scalar8RoutedInsertResult(
            Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
            Scalar8Scalar8InsertResult.Inserted,
            rootOffset,
            rootOffset,
            0,
            telemetry);
    }

    private Scalar8Scalar8RoutedInsertResult InsertIntoUnsetScalar8Scalar8Route(
        long rootRouterOffset,
        Scalar8Scalar8RoutePathTarget pathTarget,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        bool retryOnChangedRoute)
    {
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        Scalar8Scalar8InsertResult insertResult = shelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);
        if (insertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected SS8-8 unset-route shelf insert, got {insertResult}.");
        }

        if (!TryUpdateSingleByteRouterPrefixTargetIfCurrent(pathTarget.ParentRouterOffset, pathTarget.RoutePrefixByte, 0, shelfReservation.Extent.Offset, 0, out DataKernelCommitTelemetry telemetry))
        {
            if (retryOnChangedRoute)
            {
                ClearRouterReadCaches();
                return InsertWalkedRoutedScalar8Scalar8(rootRouterOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy, retryUnsetRouteChanges: false);
            }

            throw new InvalidDataException("The SS8-8 unset route changed before the new shelf could be linked.");
        }

        return new Scalar8Scalar8RoutedInsertResult(
            Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
            Scalar8Scalar8InsertResult.Inserted,
            shelfReservation.Extent.Offset,
            shelfReservation.Extent.Offset,
            0,
            telemetry);
    }

    private Scalar8Scalar8RoutedInsertResult InsertIntoScalar8Scalar8DuplicateRun(
        long headShelfOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        if (TryAppendScalar8Scalar8DuplicateRunTail(headShelfOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8RoutedInsertResult appendResult))
        {
            return appendResult;
        }

        List<long> offsets = new();
        List<ulong> identities = new();
        long currentOffset = headShelfOffset;
        ulong runKey = 0;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(currentOffset, shelfBytes);
            Scalar8Scalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                throw new InvalidDataException("The SS8-8 duplicate-run chain contains an invalid shelf.");
            }

            ulong shelfKey = shelf.ReadKeyAt(0);
            if (offsets.Count == 0)
            {
                runKey = shelfKey;
            }
            else if (shelfKey != runKey)
            {
                throw new InvalidDataException("The SS8-8 duplicate-run chain changed key between shelves.");
            }

            offsets.Add(currentOffset);
            for (int i = 0; i < shelf.ItemCount; i++)
            {
                identities.Add(shelf.ReadIdentityAt(i));
            }

            currentOffset = shelf.DuplicateRunNextOffset;
        }

        if (runKey != encodedKey)
        {
            throw new InvalidDataException("The routed SS8-8 duplicate-run key does not match the incoming key.");
        }

        if (!allowDuplicateKeys && identities.Count != 0)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.KeyConflict,
                Scalar8Scalar8InsertResult.KeyConflict,
                headShelfOffset,
                0,
                0,
                default);
        }

        int insertIndex = identities.BinarySearch(encodedIdentity);
        if (insertIndex >= 0)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                Scalar8Scalar8InsertResult.AlreadyPresent,
                headShelfOffset,
                0,
                0,
                default);
        }

        identities.Insert(~insertIndex, encodedIdentity);
        DataKernelCommitTelemetry telemetry = RewriteScalar8Scalar8DuplicateRun(headShelfOffset, profile, runKey, identities);
        return new Scalar8Scalar8RoutedInsertResult(
            Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
            Scalar8Scalar8InsertResult.Inserted,
            headShelfOffset,
            headShelfOffset,
            0,
            telemetry);
    }

    private bool TryAppendScalar8Scalar8DuplicateRunTail(
        long headShelfOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar8Scalar8RoutedInsertResult result)
    {
        result = default;
        long currentOffset = headShelfOffset;
        byte[] currentBytes = new byte[profile.ShelfExtentSize];
        while (true)
        {
            kernel.Read(currentOffset, currentBytes);
            Scalar8Scalar8ReadOnly shelf = new(currentBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                throw new InvalidDataException("The SS8-8 duplicate-run append path found an invalid shelf.");
            }

            if (shelf.ReadKeyAt(0) != encodedKey)
            {
                throw new InvalidDataException("The routed SS8-8 duplicate-run key does not match the incoming key.");
            }

            if (shelf.DuplicateRunNextOffset != 0)
            {
                currentOffset = shelf.DuplicateRunNextOffset;
                continue;
            }

            if (!allowDuplicateKeys && shelf.ItemCount != 0)
            {
                result = new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.KeyConflict,
                    Scalar8Scalar8InsertResult.KeyConflict,
                    headShelfOffset,
                    0,
                    0,
                    default);
                return true;
            }

            if (shelf.ItemCount != 0 && shelf.ReadIdentityAt(shelf.ItemCount - 1) >= encodedIdentity)
            {
                return false;
            }

            int capacity = Scalar8Scalar8Layout.GetDuplicateRunCapacity(profile);
            if (shelf.ItemCount < capacity)
            {
                scalar8Scalar8CleanShelfCache.Remove(currentOffset);
                RawDataReservation identityRewrite = kernel.ReserveAt(
                    currentOffset + Scalar8Scalar8Layout.DuplicateRunIdentityOffset + (shelf.ItemCount * Scalar8Scalar8Layout.IdentitySize),
                    Scalar8Scalar8Layout.IdentitySize);
                BinaryPrimitives.WriteUInt64BigEndian(identityRewrite.Span, encodedIdentity);

                RawDataReservation countRewrite = kernel.ReserveAt(
                    currentOffset + Scalar8Scalar8Layout.ItemCountOffset,
                    sizeof(ushort));
                BinaryPrimitives.WriteUInt16LittleEndian(countRewrite.Span, checked((ushort)(shelf.ItemCount + 1)));
                DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
                result = new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                    Scalar8Scalar8InsertResult.Inserted,
                    headShelfOffset,
                    currentOffset,
                    0,
                    telemetry);
                return true;
            }

            RawDataReservation append = kernel.Reserve(profile.ShelfExtentSize);
            WriteScalar8Scalar8DuplicateRunSingleIdentityShelf(append.Span, profile, encodedKey, encodedIdentity, nextOffset: 0);
            scalar8Scalar8CleanShelfCache.Remove(currentOffset);
            RawDataReservation tailNextRewrite = kernel.ReserveAt(
                currentOffset + Scalar8Scalar8Layout.DuplicateRunNextOffset,
                sizeof(long));
            BinaryPrimitives.WriteInt64LittleEndian(tailNextRewrite.Span, append.Extent.Offset);
            DataKernelCommitTelemetry appendTelemetry = CommitAndInvalidateRouterReadCache();
            result = new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                Scalar8Scalar8InsertResult.Inserted,
                headShelfOffset,
                append.Extent.Offset,
                0,
                appendTelemetry);
            return true;
        }
    }

    /// <summary>
    /// Initializes a duplicate-run `SS8-8` shelf with one identity without allocating a temporary identity list.<br/>
    /// This is used by append-heavy duplicate-key paths where the caller already has the single encoded identity in a register.<br/>
    /// </summary>
    /// <param name="target">The full shelf extent to initialize.<br/></param>
    /// <param name="profile">The shelf profile used for extent validation by callers.<br/></param>
    /// <param name="encodedKey">The duplicate key stored once in the shelf header.<br/></param>
    /// <param name="encodedIdentity">The first identity in the duplicate run shelf.<br/></param>
    /// <param name="nextOffset">The next duplicate-run shelf offset, or zero.<br/></param>
    private static void WriteScalar8Scalar8DuplicateRunSingleIdentityShelf(
        Span<byte> target,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        long nextOffset)
    {
        target.Clear();
        Scalar8Scalar8Layout.WriteMagic(target, Scalar8Scalar8Layout.Magic);
        Scalar8Scalar8Layout.WriteFormatVersion(target, Scalar8Scalar8Layout.FormatVersion);
        Scalar8Scalar8Layout.WriteHeaderSize(target, Scalar8Scalar8Layout.HeaderSize);
        Scalar8Scalar8Layout.WriteFlags(target, Scalar8Scalar8Layout.DuplicateRunFlag);
        Scalar8Scalar8Layout.WriteItemCount(target, 1);
        Scalar8Scalar8Layout.WriteDuplicateRunKey(target, encodedKey);
        Scalar8Scalar8Layout.WriteDuplicateRunNextOffset(target, nextOffset);
        Scalar8Scalar8Layout.WriteDuplicateRunIdentity(target, 0, encodedIdentity);
        _ = profile;
    }

    private DataKernelCommitTelemetry RewriteScalar8Scalar8DuplicateRun(
        long headShelfOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        IReadOnlyList<ulong> identities)
    {
        long obsoleteTailOffset = ReadScalar8Scalar8DuplicateRunNextOffset(headShelfOffset, profile);
        int capacity = Scalar8Scalar8Layout.GetDuplicateRunCapacity(profile);
        int remaining = identities.Count;
        int identityIndex = 0;
        long currentOffset = headShelfOffset;
        while (remaining > 0)
        {
            int take = Math.Min(capacity, remaining);
            remaining -= take;
            long nextOffset = remaining > 0 ? kernel.Reserve(profile.ShelfExtentSize).Extent.Offset : 0;
            RawDataReservation rewrite = kernel.ReserveAt(currentOffset, profile.ShelfExtentSize);
            WriteScalar8Scalar8DuplicateRunShelf(rewrite.Span, profile, encodedKey, identities, identityIndex, take, nextOffset);
            currentOffset = nextOffset;
            identityIndex += take;
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        ReleaseScalar8Scalar8DuplicateRunChain(obsoleteTailOffset, profile);
        return telemetry;
    }

    /// <summary>
    /// Replaces a full same-key `SS8-8` shelf with one deeper router level while preserving the existing tuple shelf behind the exact next key byte.<br/>
    /// This is the required intermediate state for duplicate-key runs whose key bytes have not been fully routed yet.<br/>
    /// Terminal identity roots are only safe after every key byte is consumed, because earlier routes can still receive neighboring keys that share the same prefix.<br/>
    /// </summary>
    /// <param name="shelfOffset">The existing shelf offset that will become the deeper router page.</param>
    /// <param name="existingShelfBytes">The full existing same-key shelf bytes to append behind the new router.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The same-key run key that selects the only populated route in the new router.</param>
    /// <param name="routerKeyDepth">The key byte depth owned by the new router.</param>
    /// <param name="allocationClassId">The allocation class identifier persisted in the new router header.</param>
    /// <returns>The DataKernel commit telemetry for the structural rewrite.</returns>
    private DataKernelCommitTelemetry DeepenScalar8Scalar8DuplicateKeyRoute(
        long shelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ushort routerKeyDepth,
        ushort allocationClassId)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS8-8 shelf extent size.", nameof(existingShelfBytes));
        }

        DiscardScalar8Scalar8MutableBatchShelfBytes(shelfOffset);
        RawDataReservation shelfAppend = kernel.Reserve(profile.ShelfExtentSize);
        existingShelfBytes.CopyTo(shelfAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(shelfOffset, RouterLayout.Size);
        long[] routeTargets = new long[RouterLayout.MaxOneByteRouteCount];
        routeTargets[GetScalar8Scalar8Prefix(encodedKey, routerKeyDepth)] = shelfAppend.Extent.Offset;
        RouterWriter routerWriter = new(routerRewrite.Span);
        routerWriter.InitializeExpandedOneByte(
            routerKeyDepth,
            allocationClassId,
            routeTargets);
        routerWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(shelfOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        return telemetry;
    }

    /// <summary>
    /// Deepens an `SS8-8` route when a terminal identity root is reached by a different incoming key.<br/>
    /// Terminal identity roots are valid only behind an exact exhausted-key route; this repairs broader parent routes by moving the existing root behind a newly inserted child router.<br/>
    /// </summary>
    /// <param name="pathTarget">The walked route target that reached a terminal identity root.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for empty fallback shelves.</param>
    /// <param name="encodedKey">The incoming encoded key that selected the terminal root route.</param>
    /// <param name="telemetry">Receives DataKernel telemetry when route deepening writes storage.</param>
    /// <returns>True when the route was deepened and the caller should retry the insert; false when the terminal root already matches the incoming key.</returns>
    /// <exception cref="InvalidDataException">Thrown when the terminal root is invalid or routing bytes are already exhausted for two different keys.</exception>
    private bool TryDeepenMismatchedScalar8Scalar8TerminalIdentityRoute(
        Scalar8Scalar8RoutePathTarget pathTarget,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeScalar8)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity root has the wrong shape.");
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        if (keyLength != Scalar8Scalar8Layout.KeySize)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity root key has an invalid length.");
        }

        ulong rootKey = BinaryPrimitives.ReadUInt64BigEndian(rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, Scalar8Scalar8Layout.KeySize));
        if (rootKey == encodedKey)
        {
            return false;
        }

        if (target.RouterDepth + 1 >= Scalar8Scalar8Layout.KeySize)
        {
            throw new InvalidDataException($"The routed SS8-8 terminal identity root reached a different key after all key bytes were consumed. IncomingKey=0x{encodedKey:X16}; RootKey=0x{rootKey:X16}; RouterDepth={target.RouterDepth}; ParentRouterOffset={pathTarget.ParentRouterOffset}; RoutePrefix=0x{pathTarget.RoutePrefixByte:X2}; RootOffset={target.Offset}.");
        }

        ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        RawDataReservation existingRootAppend = kernel.Reserve(TerminalIdentityRootLayout.Size);
        rootBytes.CopyTo(existingRootAppend.Span);

        long[] routeTargets = new long[RouterLayout.MaxOneByteRouteCount];
        routeTargets[GetScalar8Scalar8Prefix(rootKey, childRouterKeyDepth)] = existingRootAppend.Extent.Offset;

        RawDataReservation routerRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
        RouterWriter writer = new(routerRewrite.Span);
        writer.InitializeExpandedOneByte(
            childRouterKeyDepth,
            target.AllocationClassId,
            routeTargets);

        InvalidateRouterReadCacheForRouterRewrite(target.Offset);
        telemetry = CommitAndDeferRouterReadCacheInvalidation();
        return true;
    }

    /// <summary>
    /// Deepens a `VS8` route when a terminal identity root is reached by a different incoming raw key.<br/>
    /// The existing terminal root is moved behind the first divergent raw-key byte and a new empty shelf is routed to the incoming side so the caller can retry through ordinary shelf insertion.<br/>
    /// This keeps duplicate-key terminal roots exact-key only while preserving the broad routed-shelf behavior needed by future non-duplicate keys.<br/>
    /// </summary>
    /// <param name="pathTarget">The walked route target that reached a terminal identity root.<br/></param>
    /// <param name="profile">The `VS8` shelf profile used for the new empty incoming-key shelf.<br/></param>
    /// <param name="key">The incoming raw key bytes that selected the terminal root route.<br/></param>
    /// <param name="telemetry">Receives DataKernel telemetry when route deepening writes storage.<br/></param>
    /// <returns>True when the route was deepened and the caller should retry the insert; false when the terminal root already matches the incoming key.<br/></returns>
    /// <exception cref="InvalidDataException">Thrown when the terminal root is invalid or two different keys cannot be separated within the configured raw-key length.<br/></exception>
    private bool TryDeepenMismatchedVarKeyScalar8TerminalIdentityRoute(
        VarKeyScalar8RoutePathTarget pathTarget,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
        {
            throw new InvalidDataException("The routed VS8 terminal identity root has the wrong shape.");
        }

        int rootKeyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        ReadOnlySpan<byte> rootKey = rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, rootKeyLength);
        if (rootKey.SequenceEqual(key))
        {
            return false;
        }

        ushort childRouterKeyDepth = 0;
        byte rootPrefixByte = 0;
        byte incomingPrefixByte = 0;
        bool foundDivergence = false;
        int firstPreferredDepth = target.RouterDepth + 1;
        for (int i = firstPreferredDepth; i < profile.MaxKeyLength; i++)
        {
            rootPrefixByte = GetVarKeyScalar8Prefix(rootKey, i);
            incomingPrefixByte = GetVarKeyScalar8Prefix(key, i);
            if (rootPrefixByte != incomingPrefixByte)
            {
                childRouterKeyDepth = checked((ushort)i);
                foundDivergence = true;
                break;
            }
        }

        if (!foundDivergence)
        {
            int earlierDepthLimit = Math.Min(firstPreferredDepth, profile.MaxKeyLength);
            for (int i = 0; i < earlierDepthLimit; i++)
            {
                rootPrefixByte = GetVarKeyScalar8Prefix(rootKey, i);
                incomingPrefixByte = GetVarKeyScalar8Prefix(key, i);
                if (rootPrefixByte != incomingPrefixByte)
                {
                    childRouterKeyDepth = checked((ushort)i);
                    foundDivergence = true;
                    break;
                }
            }
        }

        if (!foundDivergence)
        {
            throw new InvalidDataException($"The routed VS8 terminal identity root reached a different key that cannot be separated by the remaining raw-key route bytes. IncomingKeyLength={key.Length}; RootKeyLength={rootKeyLength}; RouterDepth={target.RouterDepth}; ParentRouterOffset={pathTarget.ParentRouterOffset}; RoutePrefix=0x{pathTarget.RoutePrefixByte:X2}; RootOffset={target.Offset}.");
        }

        RawDataReservation existingRootAppend = kernel.Reserve(TerminalIdentityRootLayout.Size);
        rootBytes.CopyTo(existingRootAppend.Span);

        RawDataReservation incomingShelfAppend = kernel.Reserve(profile.ShelfExtentSize);
        VarKeyScalar8Layout.Initialize(incomingShelfAppend.Span, profile);

        long leftOffset;
        long rightOffset;
        byte rightPrefixByte;
        if (incomingPrefixByte < rootPrefixByte)
        {
            leftOffset = incomingShelfAppend.Extent.Offset;
            rightOffset = existingRootAppend.Extent.Offset;
            rightPrefixByte = rootPrefixByte;
        }
        else
        {
            leftOffset = existingRootAppend.Extent.Offset;
            rightOffset = incomingShelfAppend.Extent.Offset;
            rightPrefixByte = incomingPrefixByte;
        }

        RawDataReservation routerRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
        RouterWriter writer = new(routerRewrite.Span);
        writer.InitializeExpandedOneByte(
            childRouterKeyDepth,
            target.AllocationClassId,
            CreateSplitScalar8Scalar8RouteTargets(leftOffset, rightOffset, rightPrefixByte));

        terminalIdentityRootReadCache.TryRemove(target.Offset, out _);
        InvalidateRouterReadCacheForRouterRewrite(target.Offset);
        telemetry = CommitAndDeferRouterReadCacheInvalidation();
        return true;
    }

    private static void WriteScalar8Scalar8DuplicateRunShelf(
        Span<byte> target,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        IReadOnlyList<ulong> identities,
        int startIndex,
        int count,
        long nextOffset)
    {
        target.Clear();
        Scalar8Scalar8Layout.WriteMagic(target, Scalar8Scalar8Layout.Magic);
        Scalar8Scalar8Layout.WriteFormatVersion(target, Scalar8Scalar8Layout.FormatVersion);
        Scalar8Scalar8Layout.WriteHeaderSize(target, Scalar8Scalar8Layout.HeaderSize);
        Scalar8Scalar8Layout.WriteFlags(target, Scalar8Scalar8Layout.DuplicateRunFlag);
        Scalar8Scalar8Layout.WriteItemCount(target, checked((ushort)count));
        Scalar8Scalar8Layout.WriteDuplicateRunKey(target, encodedKey);
        Scalar8Scalar8Layout.WriteDuplicateRunNextOffset(target, nextOffset);
        for (int i = 0; i < count; i++)
        {
            Scalar8Scalar8Layout.WriteDuplicateRunIdentity(target, i, identities[startIndex + i]);
        }
    }

    private DataKernelCommitTelemetry RewriteTerminalIdentity8Route(
        long rootOffset,
        byte shape,
        ReadOnlySpan<byte> keyBytes,
        int shelfExtentSize,
        IReadOnlyList<ulong> identities,
        long obsoleteFirstShelfOffset = 0)
    {
        long firstShelfOffset = 0;
        if (identities.Count != 0)
        {
            int capacity = TerminalIdentity8ShelfLayout.GetCapacity(shelfExtentSize);
            if (capacity <= 0)
            {
                throw new InvalidDataException("The terminal identity shelf extent is too small for identity payloads.");
            }

            int remaining = identities.Count;
            int identityIndex = 0;
            long previousShelfOffset = 0;
            RawDataReservation previousReservation = default;
            while (remaining > 0)
            {
                int take = Math.Min(capacity, remaining);
                remaining -= take;
                RawDataReservation shelfReservation = kernel.Reserve(shelfExtentSize);
                if (firstShelfOffset == 0)
                {
                    firstShelfOffset = shelfReservation.Extent.Offset;
                }

                TerminalIdentity8ShelfLayout.Initialize(shelfReservation.Span, identities, identityIndex, take, 0);
                if (previousShelfOffset != 0)
                {
                    RawDataReservation previousRewrite = kernel.ReserveAt(previousShelfOffset, shelfExtentSize);
                    previousReservation.Span.Slice(0, shelfExtentSize).CopyTo(previousRewrite.Span);
                    TerminalIdentity8ShelfLayout.WriteNextShelfOffset(previousRewrite.Span, shelfReservation.Extent.Offset);
                }

                previousShelfOffset = shelfReservation.Extent.Offset;
                previousReservation = shelfReservation;
                identityIndex += take;
            }
        }

        RawDataReservation rootRewrite = kernel.ReserveAt(rootOffset, TerminalIdentityRootLayout.Size);
        TerminalIdentityRootLayout.Initialize(rootRewrite.Span, shape, keyBytes, shelfExtentSize, firstShelfOffset);
        ClearTerminalIdentityReadCaches();
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        ReleaseTerminalIdentity8ShelfChain(obsoleteFirstShelfOffset, shelfExtentSize);
        return telemetry;
    }

    /// <summary>
    /// Rewrites one terminal identity route only when the currently linked identities still match the caller's captured evidence.<br/>
    /// The caller may pass <see langword="null"/> for <paramref name="expectedCurrentIdentities"/> when its replacement list was derived immediately from the current chain and only needs the final publication gate.<br/>
    /// A false return means another writer changed the route before publication, so the caller should re-read and retry the higher-level mutation decision.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root offset to rewrite.<br/></param>
    /// <param name="shape">The terminal root shape byte to preserve.<br/></param>
    /// <param name="keyBytes">The exhausted key bytes stored in the terminal root.<br/></param>
    /// <param name="shelfExtentSize">The terminal identity shelf extent size.<br/></param>
    /// <param name="replacementIdentities">The complete replacement identity list to publish.<br/></param>
    /// <param name="expectedCurrentIdentities">Optional captured identity evidence that must still match current storage.<br/></param>
    /// <param name="obsoleteFirstShelfOffset">The first old shelf offset to release after successful publication.<br/></param>
    /// <param name="telemetry">Receives commit telemetry when publication succeeds.<br/></param>
    /// <returns><see langword="true"/> when the replacement chain was published; otherwise <see langword="false"/>.</returns>
    private bool TryRewriteTerminalIdentity8RouteIfCurrent(
        long rootOffset,
        byte shape,
        ReadOnlySpan<byte> keyBytes,
        int shelfExtentSize,
        IReadOnlyList<ulong> replacementIdentities,
        IReadOnlyList<ulong>? expectedCurrentIdentities,
        long obsoleteFirstShelfOffset,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        lock (writePublicationSync)
        {
            kernel.EnterExclusiveStoragePublication();
            try
            {
                if (expectedCurrentIdentities is not null)
                {
                    List<ulong> currentIdentities = ReadTerminalIdentity8RouteIdentities(rootOffset, keyBytes, shelfExtentSize);
                    if (!AreSameOrderedIdentities(currentIdentities, expectedCurrentIdentities))
                    {
                        return false;
                    }
                }

                telemetry = RewriteTerminalIdentity8Route(rootOffset, shape, keyBytes, shelfExtentSize, replacementIdentities, obsoleteFirstShelfOffset);
                return true;
            }
            finally
            {
                kernel.ExitExclusiveStoragePublication();
            }
        }
    }

    private bool TryAppendTerminalIdentity8Tail(
        long rootOffset,
        ReadOnlySpan<byte> expectedKeyBytes,
        int shelfExtentSize,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out long firstShelfOffset))
        {
            throw new InvalidDataException("The terminal identity root does not match the routed key.");
        }

        if (firstShelfOffset == 0)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
                    if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out firstShelfOffset))
                    {
                        throw new InvalidDataException("The terminal identity root does not match the routed key.");
                    }

                    if (firstShelfOffset != 0)
                    {
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(shelfExtentSize);
                    InitializeTerminalIdentity8SingleIdentityShelf(shelfReservation.Span, encodedIdentity, nextShelfOffset: 0);
                    RawDataReservation firstOffsetRewrite = kernel.ReserveAt(
                        rootOffset + TerminalIdentityRootLayout.FirstShelfOffsetOffset,
                        sizeof(long));
                    BinaryPrimitives.WriteInt64LittleEndian(firstOffsetRewrite.Span, shelfReservation.Extent.Offset);
                    byte[] updatedRootBytes = new byte[TerminalIdentityRootLayout.Size];
                    rootBytes.AsSpan(0, TerminalIdentityRootLayout.Size).CopyTo(updatedRootBytes);
                    TerminalIdentityRootLayout.WriteFirstShelfOffset(updatedRootBytes, shelfReservation.Extent.Offset);
                    byte[] updatedShelfBytes = new byte[shelfExtentSize];
                    shelfReservation.Span.Slice(0, shelfExtentSize).CopyTo(updatedShelfBytes);
                    telemetry = CommitWithoutInvalidatingRouterReadCache();
                    terminalIdentityRootReadCache[rootOffset] = updatedRootBytes;
                    terminalIdentity8ShelfReadCache[shelfReservation.Extent.Offset] = updatedShelfBytes;
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }

        long currentOffset = firstShelfOffset;
        while (true)
        {
            byte[] currentBytes = ReadTerminalIdentity8ShelfBytesCached(currentOffset, shelfExtentSize);
            ValidateTerminalIdentity8Shelf(currentBytes, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(currentBytes);
            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(currentBytes);
            if (nextOffset != 0)
            {
                currentOffset = nextOffset;
                continue;
            }

            if (!allowDuplicateKeys && count != 0)
            {
                return false;
            }

            if (count != 0 && TerminalIdentity8ShelfLayout.ReadIdentity(currentBytes, count - 1) >= encodedIdentity)
            {
                return false;
            }

            int capacity = TerminalIdentity8ShelfLayout.GetCapacity(shelfExtentSize);
            if (count < capacity)
            {
                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        currentBytes = ReadTerminalIdentity8ShelfBytesCached(currentOffset, shelfExtentSize);
                        ValidateTerminalIdentity8Shelf(currentBytes, shelfExtentSize);
                        count = TerminalIdentity8ShelfLayout.ReadItemCount(currentBytes);
                        nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(currentBytes);
                        if (nextOffset != 0 ||
                            count >= capacity ||
                            (!allowDuplicateKeys && count != 0) ||
                            (count != 0 && TerminalIdentity8ShelfLayout.ReadIdentity(currentBytes, count - 1) >= encodedIdentity))
                        {
                            return false;
                        }

                        RawDataReservation identityRewrite = kernel.ReserveAt(
                            currentOffset + TerminalIdentity8ShelfLayout.IdentityBytesOffset + (count * TerminalIdentity8ShelfLayout.IdentitySize),
                            TerminalIdentity8ShelfLayout.IdentitySize);
                        BinaryPrimitives.WriteUInt64BigEndian(identityRewrite.Span, encodedIdentity);

                        RawDataReservation countRewrite = kernel.ReserveAt(
                            currentOffset + TerminalIdentity8ShelfLayout.ItemCountOffset,
                            sizeof(int));
                        BinaryPrimitives.WriteInt32LittleEndian(countRewrite.Span, count + 1);
                        telemetry = CommitWithoutInvalidatingRouterReadCache();
                        TerminalIdentity8ShelfLayout.WriteIdentity(currentBytes, count, encodedIdentity);
                        TerminalIdentity8ShelfLayout.WriteItemCount(currentBytes, count + 1);
                        terminalIdentity8ShelfReadCache[currentOffset] = currentBytes;
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    currentBytes = ReadTerminalIdentity8ShelfBytesCached(currentOffset, shelfExtentSize);
                    ValidateTerminalIdentity8Shelf(currentBytes, shelfExtentSize);
                    count = TerminalIdentity8ShelfLayout.ReadItemCount(currentBytes);
                    nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(currentBytes);
                    if (nextOffset != 0 ||
                        count < capacity ||
                        (!allowDuplicateKeys && count != 0) ||
                        (count != 0 && TerminalIdentity8ShelfLayout.ReadIdentity(currentBytes, count - 1) >= encodedIdentity))
                    {
                        return false;
                    }

                    RawDataReservation append = kernel.Reserve(shelfExtentSize);
                    InitializeTerminalIdentity8SingleIdentityShelf(append.Span, encodedIdentity, nextShelfOffset: 0);
                    RawDataReservation tailNextRewrite = kernel.ReserveAt(
                        currentOffset + TerminalIdentity8ShelfLayout.NextShelfOffsetOffset,
                        sizeof(long));
                    BinaryPrimitives.WriteInt64LittleEndian(tailNextRewrite.Span, append.Extent.Offset);
                    byte[] appendedShelfBytes = new byte[shelfExtentSize];
                    append.Span.Slice(0, shelfExtentSize).CopyTo(appendedShelfBytes);
                    telemetry = CommitWithoutInvalidatingRouterReadCache();
                    TerminalIdentity8ShelfLayout.WriteNextShelfOffset(currentBytes, append.Extent.Offset);
                    terminalIdentity8ShelfReadCache[currentOffset] = currentBytes;
                    terminalIdentity8ShelfReadCache[append.Extent.Offset] = appendedShelfBytes;
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts a writer-context insert into an existing shelf of an exhausted-key `SS8-8` terminal identity route.<br/>
    /// The supported case is intentionally bounded: the terminal root must already point at a shelf chain, the identity must belong in one existing shelf, and that shelf must have spare capacity for an in-place sorted insert.<br/>
    /// Cases that need root publication, a new linked shelf, or cross-shelf rebalancing return false so the caller can use the serialized route path.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged terminal shelf bytes until publish or abort.<br/></param>
    /// <param name="rootOffset">The terminal identity root offset resolved by the route walker.<br/></param>
    /// <param name="expectedKeyBytes">The exhausted scalar key bytes expected in the terminal root.<br/></param>
    /// <param name="shelfExtentSize">The fixed extent size of every terminal identity shelf in the route.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert into sorted terminal-shelf order.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same encoded key.<br/></param>
    /// <param name="result">The routed insert result when the writer-context insert is supported.<br/></param>
    /// <returns>True when the insert was fully handled by writer-local staging; otherwise false.</returns>
    private bool TryInsertTerminalIdentity8ForWriteContext(
        LibraDexWriteContext writeContext,
        long rootOffset,
        ReadOnlySpan<byte> expectedKeyBytes,
        int shelfExtentSize,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar8Scalar8RoutedInsertResult result)
    {
        result = default;
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out long firstShelfOffset))
        {
            throw new InvalidDataException("The terminal identity root does not match the routed key.");
        }

        if (firstShelfOffset == 0)
        {
            return false;
        }

        long currentOffset = firstShelfOffset;
        while (true)
        {
            byte[] currentBytes = ReadTerminalIdentity8ShelfBytesForWriteContext(writeContext, currentOffset, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(currentBytes);
            if (!allowDuplicateKeys && count != 0)
            {
                result = new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.KeyConflict,
                    Scalar8Scalar8InsertResult.KeyConflict,
                    rootOffset,
                    0,
                    0,
                    default);
                return true;
            }

            int capacity = TerminalIdentity8ShelfLayout.GetCapacity(shelfExtentSize);
            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(currentBytes);
            if (count != 0)
            {
                ulong lastIdentity = TerminalIdentity8ShelfLayout.ReadIdentity(currentBytes, count - 1);
                if (encodedIdentity > lastIdentity && nextOffset != 0)
                {
                    currentOffset = nextOffset;
                    continue;
                }
            }

            if (count >= capacity)
            {
                return false;
            }

            int insertIndex = FindTerminalIdentity8InsertIndex(currentBytes, count, encodedIdentity);
            if (insertIndex < 0)
            {
                result = new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.NoOp,
                    Scalar8Scalar8InsertResult.AlreadyPresent,
                    rootOffset,
                    0,
                    0,
                    default);
                return true;
            }

            for (int i = count; i > insertIndex; i--)
            {
                TerminalIdentity8ShelfLayout.WriteIdentity(currentBytes, i, TerminalIdentity8ShelfLayout.ReadIdentity(currentBytes, i - 1));
            }

            TerminalIdentity8ShelfLayout.WriteIdentity(currentBytes, insertIndex, encodedIdentity);
            TerminalIdentity8ShelfLayout.WriteItemCount(currentBytes, count + 1);
            StageTerminalIdentity8ShelfRewriteForWriteContext(writeContext, currentOffset, shelfExtentSize, currentBytes);
            result = new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                Scalar8Scalar8InsertResult.Inserted,
                rootOffset,
                currentOffset,
                0,
                default);
            return true;
        }
    }

    /// <summary>
    /// Finds the sorted insertion slot for one encoded identity inside a terminal identity shelf.<br/>
    /// A non-negative return value is the slot where the identity should be inserted; a negative return value means the identity is already present and no mutation is needed.<br/>
    /// </summary>
    /// <param name="shelfBytes">The terminal identity shelf bytes to search.<br/></param>
    /// <param name="count">The number of live identities in the shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to locate.<br/></param>
    /// <returns>The insertion slot, or -1 when <paramref name="encodedIdentity"/> already exists.</returns>
    private static int FindTerminalIdentity8InsertIndex(
        ReadOnlySpan<byte> shelfBytes,
        int count,
        ulong encodedIdentity)
    {
        int low = 0;
        int high = count - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) >> 1);
            ulong current = TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, middle);
            if (encodedIdentity < current)
            {
                high = middle - 1;
                continue;
            }

            if (encodedIdentity > current)
            {
                low = middle + 1;
                continue;
            }

            return -1;
        }

        return low;
    }

    /// <summary>
    /// Initializes a terminal identity shelf with one encoded identity and no temporary list allocation.<br/>
    /// Terminal append hot paths use this when a new identity-only shelf is needed for an empty or full chain.<br/>
    /// </summary>
    /// <param name="target">The full terminal identity shelf extent to initialize.<br/></param>
    /// <param name="encodedIdentity">The single encoded identity to store.<br/></param>
    /// <param name="nextShelfOffset">The next shelf offset, or zero when this shelf is the tail.<br/></param>
    private static void InitializeTerminalIdentity8SingleIdentityShelf(
        Span<byte> target,
        ulong encodedIdentity,
        long nextShelfOffset)
    {
        target.Clear();
        TerminalIdentity8ShelfLayout.WriteMagic(target, TerminalIdentity8ShelfLayout.Magic);
        TerminalIdentity8ShelfLayout.WriteFormatVersion(target, TerminalIdentity8ShelfLayout.FormatVersion);
        TerminalIdentity8ShelfLayout.WriteHeaderSize(target, TerminalIdentity8ShelfLayout.HeaderSize);
        TerminalIdentity8ShelfLayout.WriteItemCount(target, 1);
        TerminalIdentity8ShelfLayout.WriteNextShelfOffset(target, nextShelfOffset);
        TerminalIdentity8ShelfLayout.WriteIdentity(target, 0, encodedIdentity);
    }

    private List<ulong> ReadTerminalIdentity8RouteIdentities(long rootOffset, ReadOnlySpan<byte> expectedKeyBytes, int shelfExtentSize)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out long shelfOffset))
        {
            throw new InvalidDataException("The terminal identity root does not match the routed key.");
        }

        List<ulong> identities = new();
        while (shelfOffset != 0)
        {
            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytesCached(shelfOffset, shelfExtentSize);
            ValidateTerminalIdentity8Shelf(shelfBytes, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
            for (int i = 0; i < count; i++)
            {
                identities.Add(TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i));
            }

            shelfOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
        }

        return identities;
    }

    /// <summary>
    /// Copies identities from one routed `SS8-8` terminal identity root when the root key lies inside the requested encoded-key range.<br/>
    /// Terminal roots represent an exhausted scalar key, so range readers must treat the root as a point leaf rather than as a shelf extent.<br/>
    /// The helper validates scalar shape and key length before reading the linked identity-only shelves, then copies at most the caller's remaining output capacity.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root file offset selected by a router route entry.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that determines terminal identity shelf extent size.<br/></param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.<br/></param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.<br/></param>
    /// <param name="encodedIdentities">The remaining caller-owned output span that receives matching identities.<br/></param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the routed terminal root is not a scalar-eight identity root.</exception>
    private int CopyScalar8Scalar8TerminalRootIdentitiesInRange(
        long rootOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Span<ulong> encodedIdentities)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeScalar8)
        {
            throw new InvalidDataException("The routed terminal identity root is not an SS8-8 terminal identity root.");
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        if (keyLength != Scalar8Scalar8Layout.KeySize)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity root key length is invalid.");
        }

        ulong rootKey = BinaryPrimitives.ReadUInt64BigEndian(rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, Scalar8Scalar8Layout.KeySize));
        if (rootKey < lowerEncodedKey || rootKey > upperEncodedKey)
        {
            return 0;
        }

        Span<byte> expectedKey = stackalloc byte[Scalar8Scalar8Layout.KeySize];
        BinaryPrimitives.WriteUInt64BigEndian(expectedKey, rootKey);
        List<ulong> identities = ReadTerminalIdentity8RouteIdentities(rootOffset, expectedKey, profile.ShelfExtentSize);
        int copyCount = Math.Min(identities.Count, encodedIdentities.Length);
        for (int i = 0; i < copyCount; i++)
        {
            encodedIdentities[i] = identities[i];
        }

        return copyCount;
    }

    /// <summary>
    /// Reads one terminal identity root into an owned byte array for routed readers.<br/>
    /// The root carries the exhausted key once and points at an identity-only shelf chain.<br/>
    /// </summary>
    /// <param name="rootOffset">The file offset of the terminal identity root.</param>
    /// <returns>An owned terminal root byte image.</returns>
    internal byte[] ReadTerminalIdentityRootBytes(long rootOffset)
    {
        if (terminalIdentityRootReadCache.TryGetValue(rootOffset, out byte[]? cachedRootBytes))
        {
            return cachedRootBytes;
        }

        byte[] rootBytes = new byte[TerminalIdentityRootLayout.Size];
        kernel.Read(rootOffset, rootBytes);
        if (TerminalIdentityRootLayout.ReadMagic(rootBytes) != TerminalIdentityRootLayout.Magic ||
            TerminalIdentityRootLayout.ReadFormatVersion(rootBytes) != TerminalIdentityRootLayout.FormatVersion ||
            TerminalIdentityRootLayout.ReadHeaderSize(rootBytes) != TerminalIdentityRootLayout.HeaderSize)
        {
            throw new InvalidDataException("The routed terminal identity root bytes are invalid.");
        }

        terminalIdentityRootReadCache[rootOffset] = rootBytes;
        return rootBytes;
    }

    /// <summary>
    /// Reads one terminal identity shelf into a pooled byte array for routed range readers.<br/>
    /// The caller owns the returned buffer and must return it to <see cref="ArrayPool{T}.Shared"/> when the cursor is disposed.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset of the terminal identity shelf.</param>
    /// <param name="shelfExtentSize">The extent size recorded by the terminal root.</param>
    /// <returns>A pooled byte array containing a valid terminal identity shelf image.</returns>
    internal byte[] ReadTerminalIdentity8ShelfBytes(long shelfOffset, int shelfExtentSize)
    {
        byte[] shelfBytes = ArrayPool<byte>.Shared.Rent(shelfExtentSize);
        try
        {
            ReadTerminalIdentity8ShelfBytesCached(shelfOffset, shelfExtentSize).AsSpan(0, shelfExtentSize).CopyTo(shelfBytes);
            ValidateTerminalIdentity8Shelf(shelfBytes, shelfExtentSize);
            return shelfBytes;
        }
        catch
        {
            ArrayPool<byte>.Shared.Return(shelfBytes, clearArray: false);
            throw;
        }
    }

    private byte[] ReadTerminalIdentity8ShelfBytesCached(long shelfOffset, int shelfExtentSize)
    {
        if (terminalIdentity8ShelfReadCache.TryGetValue(shelfOffset, out byte[]? cachedShelfBytes))
        {
            if (cachedShelfBytes.Length < shelfExtentSize)
            {
                throw new InvalidDataException("The cached terminal identity shelf extent is smaller than the requested extent.");
            }

            return cachedShelfBytes;
        }

        byte[] shelfBytes = new byte[shelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        ValidateTerminalIdentity8Shelf(shelfBytes, shelfExtentSize);
        terminalIdentity8ShelfReadCache[shelfOffset] = shelfBytes;
        return shelfBytes;
    }

    /// <summary>
    /// Reads the first terminal-identity shelf offset for an existing root that is known to represent the supplied key.<br/>
    /// This is used by memory-backed rewrite paths so the superseded linked shelf chain can be released after the replacement chain is published.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root offset.</param>
    /// <param name="expectedKeyBytes">The exhausted key bytes expected in the root.</param>
    /// <returns>The first linked identity shelf offset, or zero when the root has no identity shelves.</returns>
    private long ReadTerminalIdentityFirstShelfOffset(long rootOffset, ReadOnlySpan<byte> expectedKeyBytes)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out long firstShelfOffset))
        {
            throw new InvalidDataException("The terminal identity root does not match the routed key.");
        }

        return firstShelfOffset;
    }

    /// <summary>
    /// Releases a superseded terminal identity shelf chain from a memory-backed DataKernel arena.<br/>
    /// File-backed kernels ignore each release call, preserving append-only durable-file behavior until a separate compaction pass exists.<br/>
    /// </summary>
    /// <param name="firstShelfOffset">The first shelf in the old linked identity chain, or zero when there is no old chain.</param>
    /// <param name="shelfExtentSize">The fixed extent size of every shelf in the chain.</param>
    private void ReleaseTerminalIdentity8ShelfChain(long firstShelfOffset, int shelfExtentSize)
    {
        long currentOffset = firstShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytesCached(currentOffset, shelfExtentSize);
            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
            terminalIdentity8ShelfReadCache.TryRemove(currentOffset, out _);
            kernel.ReleaseMemoryExtent(currentOffset, shelfExtentSize);
            currentOffset = nextOffset;
        }
    }

    /// <summary>
    /// Reads the next linked shelf offset from an existing `SS8-8` duplicate-run head shelf.<br/>
    /// The value is captured before rewrite so memory-backed catalogs can release superseded tail shelves after publication.<br/>
    /// </summary>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <returns>The old next-shelf offset, or zero when the duplicate run had no tail.</returns>
    private long ReadScalar8Scalar8DuplicateRunNextOffset(long headShelfOffset, Scalar8Scalar8Profile profile)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(headShelfOffset, shelfBytes);
        Scalar8Scalar8ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid || !shelf.IsDuplicateRun)
        {
            return 0;
        }

        return shelf.DuplicateRunNextOffset;
    }

    /// <summary>
    /// Releases a superseded `SS8-8` duplicate-run tail chain from a memory-backed DataKernel arena.<br/>
    /// The head shelf is intentionally not released because the rewrite keeps using that offset as the new duplicate-run head.<br/>
    /// </summary>
    /// <param name="firstTailOffset">The first old tail shelf offset, or zero when the old run had no tail.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    private void ReleaseScalar8Scalar8DuplicateRunChain(long firstTailOffset, Scalar8Scalar8Profile profile)
    {
        long currentOffset = firstTailOffset;
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        while (currentOffset != 0)
        {
            kernel.Read(currentOffset, shelfBytes);
            Scalar8Scalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                return;
            }

            long nextOffset = shelf.DuplicateRunNextOffset;
            kernel.ReleaseMemoryExtent(currentOffset, profile.ShelfExtentSize);
            currentOffset = nextOffset;
        }
    }

    private void ClearTerminalIdentityReadCaches()
    {
        terminalIdentityRootReadCache.Clear();
        terminalIdentity8ShelfReadCache.Clear();
        terminalVarIdentityShelfReadCache.Clear();
    }

    /// <summary>
    /// Deletes one or all identities from an exhausted-key `SS8-8` terminal identity route.<br/>
    /// The route root carries the key bytes, so mutation is a list-filter plus terminal route rewrite rather than a normal shelf slot delete.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines terminal identity shelf extent size.</param>
    /// <param name="encodedKey">The encoded key expected on the terminal root.</param>
    /// <param name="encodedIdentity">The exact identity to delete, or null to delete all identities for the key.</param>
    /// <returns>The number of identities deleted.</returns>
    internal int DeleteScalar8Scalar8TerminalIdentities(
        long rootOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong? encodedIdentity)
    {
        Span<byte> expectedKey = stackalloc byte[Scalar8Scalar8Layout.KeySize];
        BinaryPrimitives.WriteUInt64BigEndian(expectedKey, encodedKey);
        List<ulong> identities = ReadTerminalIdentity8RouteIdentities(rootOffset, expectedKey, profile.ShelfExtentSize);
        int deleted = 0;
        if (encodedIdentity.HasValue)
        {
            int index = identities.BinarySearch(encodedIdentity.Value);
            if (index < 0)
            {
                return 0;
            }

            identities.RemoveAt(index);
            deleted = 1;
        }
        else
        {
            deleted = identities.Count;
            identities.Clear();
        }

        if (deleted != 0)
        {
            long obsoleteFirstShelfOffset = ReadTerminalIdentityFirstShelfOffset(rootOffset, expectedKey);
            _ = RewriteTerminalIdentity8Route(rootOffset, TerminalIdentityRootLayout.ShapeScalar8, expectedKey, profile.ShelfExtentSize, identities, obsoleteFirstShelfOffset);
        }

        return deleted;
    }

    private static bool IsTerminalIdentityRootForKey(ReadOnlySpan<byte> rootBytes, ReadOnlySpan<byte> expectedKeyBytes, out long firstShelfOffset)
    {
        firstShelfOffset = 0;
        if (TerminalIdentityRootLayout.ReadMagic(rootBytes) != TerminalIdentityRootLayout.Magic ||
            TerminalIdentityRootLayout.ReadFormatVersion(rootBytes) != TerminalIdentityRootLayout.FormatVersion ||
            TerminalIdentityRootLayout.ReadHeaderSize(rootBytes) != TerminalIdentityRootLayout.HeaderSize)
        {
            return false;
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        if (keyLength != expectedKeyBytes.Length)
        {
            return false;
        }

        ReadOnlySpan<byte> keyBytes = rootBytes.Slice(TerminalIdentityRootLayout.KeyBytesOffset, keyLength);
        if (!keyBytes.SequenceEqual(expectedKeyBytes))
        {
            return false;
        }

        firstShelfOffset = TerminalIdentityRootLayout.ReadFirstShelfOffset(rootBytes);
        return true;
    }

    private static void ValidateTerminalIdentity8Shelf(ReadOnlySpan<byte> shelfBytes, int shelfExtentSize)
    {
        if (shelfBytes.Length < shelfExtentSize ||
            TerminalIdentity8ShelfLayout.ReadMagic(shelfBytes) != TerminalIdentity8ShelfLayout.Magic ||
            TerminalIdentity8ShelfLayout.ReadFormatVersion(shelfBytes) != TerminalIdentity8ShelfLayout.FormatVersion ||
            TerminalIdentity8ShelfLayout.ReadHeaderSize(shelfBytes) != TerminalIdentity8ShelfLayout.HeaderSize)
        {
            throw new InvalidDataException("The terminal identity shelf bytes are invalid.");
        }

        int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
        if (count < 0 || count > TerminalIdentity8ShelfLayout.GetCapacity(shelfExtentSize))
        {
            throw new InvalidDataException("The terminal identity shelf count is invalid.");
        }
    }

