    /// <summary>
    /// Reads one `SS8-8` shelf image for a writer-local context.<br/>
    /// If the context already owns a staged image for the shelf, that image is returned; otherwise committed backing bytes are copied into a private mutable buffer.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that will own subsequent mutations.<br/></param>
    /// <param name="shelfOffset">The shelf offset to read.<br/></param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.<br/></param>
    /// <returns>A mutable writer-local shelf image.<br/></returns>
    /// <exception cref="InvalidDataException">Thrown when the shelf bytes are invalid.<br/></exception>
    internal byte[] ReadScalar8Scalar8ShelfBytesForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        Scalar8Scalar8Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.Scalar8Scalar8MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            Scalar8Scalar8 shelf = new(dirtyShelfBytes, profile);
            _ = shelf.NormalizeDeletedSlotsForPublication();
            return dirtyShelfBytes;
        }

        ClaimScalar8Scalar8ShelfForWriteContext(writeContext, shelfOffset);
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        writeContext.Scalar8Scalar8MutableBatchShelfBytes[shelfOffset] = shelfBytes;
        kernel.Read(shelfOffset, shelfBytes);
        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context SS8-8 shelf read invalid shelf bytes.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Records the committed router relationship that selected one `SS8-8` shelf for writer-context mutation.<br/>
    /// The claim is revalidated at publication so removing the old root-level staging gate does not allow stale shelf images to overwrite a shelf after its parent route changed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="pathTarget">The route path evidence captured from committed state.<br/></param>
    private static void RecordScalar8Scalar8RouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        Scalar8Scalar8RoutePathTarget pathTarget)
    {
        if (pathTarget.Target.Kind == Scalar8Scalar8RouteTargetKind.Shelf)
        {
            writeContext.Scalar8Scalar8RouteClaims[pathTarget.Target.Offset] = new Scalar8Scalar8RouteClaim(
                pathTarget.ParentRouterOffset,
                pathTarget.RoutePrefixByte,
                pathTarget.Target.Offset);
        }
    }

    /// <summary>
    /// Validates every committed `SS8-8` route relationship used by a writer-context shelf rewrite.<br/>
    /// This is the publish-time guard that replaces the old root-level staging gate: if another writer transformed or relinked the route before publication, this writer fails instead of publishing stale shelf bytes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose route claims should still match committed state.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when a claimed shelf is no longer selected by the captured parent route.<br/></exception>
    private void ValidateScalar8Scalar8RouteClaimsForWriteContext(LibraDexWriteContext writeContext)
    {
        foreach (Scalar8Scalar8RouteClaim claim in writeContext.Scalar8Scalar8RouteClaims.Values)
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            kernel.Read(claim.ParentRouterOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            long currentTargetOffset = reader.IsValid
                ? reader.FindTarget(claim.RoutePrefixByte)
                : 0;
            if (!reader.IsValid ||
                currentTargetOffset != claim.ExpectedTargetOffset ||
                ClassifyScalar8Scalar8RouteTarget(currentTargetOffset) != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidOperationException("The SS8-8 writer-context route claim no longer matches committed router state.");
            }
        }
    }

    /// <summary>
    /// Stages one full `SS8-8` shelf image into a writer-local context after claiming that shelf for the context.<br/>
    /// A second writer context that attempts to stage the same shelf is rejected deterministically before publication.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="shelfOffset">The shelf offset to stage.<br/></param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.<br/></param>
    /// <param name="shelfBytes">The staged shelf bytes.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when another writer context already owns the same shelf.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when the staged shelf image is invalid.<br/></exception>
    internal void StageScalar8Scalar8ShelfRewriteForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The writer-context SS8-8 shelf rewrite bytes must match the profiled extent size.", nameof(shelfBytes));
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context SS8-8 shelf rewrite attempted to stage invalid shelf bytes.");
        }

        ClaimScalar8Scalar8ShelfForWriteContext(writeContext, shelfOffset);
        writeContext.Scalar8Scalar8MutableBatchShelfBytes[shelfOffset] = shelfBytes.ToArray();
        writeContext.Scalar8Scalar8DirtyShelfOffsets.Add(shelfOffset);
    }

