            0,
            0,
            shelfOffset,
            profile);
    }

    /// <summary>
    /// Records that an `FSN-8` writer context staged a shelf selected by a parent router slot.<br/>
    /// Publication revalidates this claim so route-local writers can overlap without allowing stale shelf images after a parent route changes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="parentRouterOffset">The router offset whose route selected the shelf.<br/></param>
    /// <param name="routePrefixByte">The prefix byte inside the parent router that selected the shelf.<br/></param>
    /// <param name="targetOffset">The selected shelf offset captured from committed state.<br/></param>
    /// <param name="profile">The profile required to validate the target as an `FSN-8` shelf.<br/></param>
    private static void RecordFixedNScalar8RouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        byte routePrefixByte,
        long targetOffset,
        FixedNScalar8Profile profile)
    {
        writeContext.FixedNScalar8RouteClaims[targetOffset] = new FixedNScalar8RouteClaim(
            parentRouterOffset,
            routePrefixByte,
            targetOffset,
            profile);
    }

    /// <summary>
    /// Validates every committed `FSN-8` physical-location claim used by a writer-context shelf rewrite.<br/>
    /// Direct-root claims must still be shelves; routed claims must still be selected by the same parent router prefix and still classify as shelves.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose route claims should still match committed state.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when a claimed shelf is no longer selected by the captured physical relationship.<br/></exception>
    private void ValidateFixedNScalar8RouteClaimsForWriteContext(LibraDexWriteContext writeContext)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        foreach (FixedNScalar8RouteClaim claim in writeContext.FixedNScalar8RouteClaims.Values)
        {
            if (claim.ParentRouterOffset == 0)
            {
                if (!IsFixedNScalar8Shelf(claim.ExpectedTargetOffset, claim.Profile))
                {
                    throw new InvalidOperationException("The FSN-8 writer-context root shelf claim no longer matches committed state.");
                }

                continue;
            }

            kernel.Read(claim.ParentRouterOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            long currentTargetOffset = reader.IsValid
                ? reader.FindTarget(claim.RoutePrefixByte)
                : 0;
            if (!reader.IsValid ||
                currentTargetOffset != claim.ExpectedTargetOffset ||
                !IsFixedNScalar8Shelf(currentTargetOffset, claim.Profile))
            {
                throw new InvalidOperationException("The FSN-8 writer-context route claim no longer matches committed router state.");
            }
        }
    }

    /// <summary>
    /// Tests whether an offset still contains an `FSN-8` shelf for the supplied profile.<br/>
    /// Router offsets are rejected before reading the profiled shelf extent so validation never treats a router page as a large shelf.<br/>
    /// </summary>
    /// <param name="offset">The physical offset to classify.<br/></param>
    /// <param name="profile">The profile required to validate the shelf bytes.<br/></param>
    /// <returns><see langword="true"/> when the offset currently contains a valid `FSN-8` shelf; otherwise <see langword="false"/>.<br/></returns>
    private bool IsFixedNScalar8Shelf(long offset, FixedNScalar8Profile profile)
    {
        if (offset <= 0 || IsFixedNScalar8Router(offset))
        {
            return false;
        }

        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(offset, shelfBytes);
        FixedNScalar8ReadOnly readOnly = new(shelfBytes, profile);
        return readOnly.IsValid;
    }

    /// <summary>
    /// Reads one `FSN-8` shelf image for a writer-local context.<br/>
    /// Existing staged bytes are reused for repeat access; otherwise committed bytes are copied into a private mutable shelf buffer and the shelf offset is claimed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf bytes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The durable shelf offset to read.<br/></param>
    /// <param name="profile">The programmable fixed-key shelf profile that determines the extent size.<br/></param>
    /// <returns>A mutable writer-local shelf image.<br/></returns>
    internal byte[] ReadFixedNScalar8ShelfBytesForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        FixedNScalar8Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.FixedNScalar8MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            return dirtyShelfBytes;
        }

        ClaimFixedNScalar8ShelfForWriteContext(writeContext, shelfOffset);
        byte[] shelfBytes = RentFixedNMutableShelfBytes(profile.ShelfExtentSize);
        writeContext.FixedNScalar8MutableBatchShelfBytes[shelfOffset] = shelfBytes;
        kernel.Read(shelfOffset, shelfBytes);
        FixedNScalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context FSN-8 shelf read invalid shelf bytes.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Stages one full `FSN-8` shelf image into a writer-local context after claiming that shelf for the context.<br/>
    /// Same-shelf overlap is rejected before publication so callers can retry without reading stale shelf bytes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="shelfOffset">The shelf offset to stage.<br/></param>
    /// <param name="profile">The programmable fixed-key shelf profile that determines the extent size.<br/></param>
    /// <param name="shelfBytes">The staged shelf bytes.<br/></param>
    internal void StageFixedNScalar8ShelfRewriteForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        FixedNScalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The writer-context FSN-8 shelf rewrite bytes must match the profiled extent size.", nameof(shelfBytes));
        }

        FixedNScalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context FSN-8 shelf rewrite attempted to stage invalid shelf bytes.");
        }

        ClaimFixedNScalar8ShelfForWriteContext(writeContext, shelfOffset);
        if (writeContext.FixedNScalar8MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? stagedShelfBytes))
        {
            shelfBytes.CopyTo(stagedShelfBytes);
            return;
        }

        writeContext.FixedNScalar8MutableBatchShelfBytes[shelfOffset] = shelfBytes.ToArray();
    }

    /// <summary>
    /// Enters the `FSN-8` writer-context staging scope for one index root.<br/>
    /// Shelf-local writers take the read side so topology fallback cannot rewrite the route graph while the writer is selecting and claiming a physical shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FSN-8` index.<br/></param>
    internal void EnterFixedNScalar8WriterContextStaging(long rootRouterOffset)
    {
        GetFixedNScalar8TopologyMutationSync(rootRouterOffset).EnterReadLock();
    }

    /// <summary>
    /// Leaves the `FSN-8` writer-context staging scope for one index root.<br/>
    /// Callers must pair this with <see cref="EnterFixedNScalar8WriterContextStaging(long)"/> in a finally block.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FSN-8` index.<br/></param>
    internal void ExitFixedNScalar8WriterContextStaging(long rootRouterOffset)
    {
        GetFixedNScalar8TopologyMutationSync(rootRouterOffset).ExitReadLock();
    }

    /// <summary>
    /// Records that an `FSN-16` writer context staged the handle root as a direct physical shelf.<br/>
    /// Publication revalidates this claim so a shelf-local writer cannot overwrite the root after another writer transformed it into a router.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="shelfOffset">The direct root shelf offset captured from committed state.<br/></param>
    /// <param name="profile">The profile required to validate the root as an `FSN-16` shelf.<br/></param>
    internal static void RecordFixedNScalar16RootShelfClaimForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        FixedNScalar16Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        writeContext.FixedNScalar16RouteClaims[shelfOffset] = new FixedNScalar16RouteClaim(
            0,
            0,
            shelfOffset,
            profile);
    }

    /// <summary>
    /// Records that an `FSN-16` writer context staged a shelf selected by a parent router slot.<br/>
    /// Publication revalidates this claim so route-local writers can overlap without allowing stale shelf images after a parent route changes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="parentRouterOffset">The router offset whose route selected the shelf.<br/></param>
    /// <param name="routePrefixByte">The prefix byte inside the parent router that selected the shelf.<br/></param>
    /// <param name="targetOffset">The selected shelf offset captured from committed state.<br/></param>
    /// <param name="profile">The profile required to validate the target as an `FSN-16` shelf.<br/></param>
    private static void RecordFixedNScalar16RouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        byte routePrefixByte,
        long targetOffset,
        FixedNScalar16Profile profile)
    {
        writeContext.FixedNScalar16RouteClaims[targetOffset] = new FixedNScalar16RouteClaim(
            parentRouterOffset,
            routePrefixByte,
            targetOffset,
            profile);
    }

    /// <summary>
    /// Validates every committed `FSN-16` physical-location claim used by a writer-context shelf rewrite.<br/>
    /// Direct-root claims must still be shelves; routed claims must still be selected by the same parent router prefix and still classify as shelves.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose route claims should still match committed state.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when a claimed shelf is no longer selected by the captured physical relationship.<br/></exception>
    private void ValidateFixedNScalar16RouteClaimsForWriteContext(LibraDexWriteContext writeContext)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        foreach (FixedNScalar16RouteClaim claim in writeContext.FixedNScalar16RouteClaims.Values)
        {
            if (claim.ParentRouterOffset == 0)
            {
                if (!IsFixedNScalar16Shelf(claim.ExpectedTargetOffset, claim.Profile))
                {
                    throw new InvalidOperationException("The FSN-16 writer-context root shelf claim no longer matches committed state.");
                }

                continue;
            }

            kernel.Read(claim.ParentRouterOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            long currentTargetOffset = reader.IsValid
                ? reader.FindTarget(claim.RoutePrefixByte)
                : 0;
            if (!reader.IsValid ||
                currentTargetOffset != claim.ExpectedTargetOffset ||
                !IsFixedNScalar16Shelf(currentTargetOffset, claim.Profile))
            {
                throw new InvalidOperationException("The FSN-16 writer-context route claim no longer matches committed router state.");
            }
        }
    }

    /// <summary>
    /// Tests whether an offset still contains an `FSN-16` shelf for the supplied profile.<br/>
    /// Router offsets are rejected before reading the profiled shelf extent so validation never treats a router page as a large shelf.<br/>
    /// </summary>
    /// <param name="offset">The physical offset to classify.<br/></param>
    /// <param name="profile">The profile required to validate the shelf bytes.<br/></param>
    /// <returns><see langword="true"/> when the offset currently contains a valid `FSN-16` shelf; otherwise <see langword="false"/>.<br/></returns>
    private bool IsFixedNScalar16Shelf(long offset, FixedNScalar16Profile profile)
    {
        if (offset <= 0 || IsFixedNScalar16Router(offset))
        {
            return false;
        }

        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(offset, shelfBytes);
        FixedNScalar16ReadOnly readOnly = new(shelfBytes, profile);
        return readOnly.IsValid;
    }

    /// <summary>
    /// Reads one `FSN-16` shelf image for a writer-local context.<br/>
    /// Existing staged bytes are reused for repeat access; otherwise committed bytes are copied into a private mutable shelf buffer and the shelf offset is claimed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf bytes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The durable shelf offset to read.<br/></param>
    /// <param name="profile">The programmable fixed-key shelf profile that determines the extent size.<br/></param>
    /// <returns>A mutable writer-local shelf image.<br/></returns>
    internal byte[] ReadFixedNScalar16ShelfBytesForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        FixedNScalar16Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.FixedNScalar16MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            return dirtyShelfBytes;
        }

        ClaimFixedNScalar16ShelfForWriteContext(writeContext, shelfOffset);
        byte[] shelfBytes = RentFixedNMutableShelfBytes(profile.ShelfExtentSize);
        writeContext.FixedNScalar16MutableBatchShelfBytes[shelfOffset] = shelfBytes;
        kernel.Read(shelfOffset, shelfBytes);
        FixedNScalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context FSN-16 shelf read invalid shelf bytes.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Stages one full `FSN-16` shelf image into a writer-local context after claiming that shelf for the context.<br/>
    /// Same-shelf overlap is rejected before publication so callers can retry without reading stale shelf bytes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf image.<br/></param>
    /// <param name="shelfOffset">The shelf offset to stage.<br/></param>
    /// <param name="profile">The programmable fixed-key shelf profile that determines the extent size.<br/></param>
    /// <param name="shelfBytes">The staged shelf bytes.<br/></param>
    internal void StageFixedNScalar16ShelfRewriteForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        FixedNScalar16Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The writer-context FSN-16 shelf rewrite bytes must match the profiled extent size.", nameof(shelfBytes));
        }

        FixedNScalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The writer-context FSN-16 shelf rewrite attempted to stage invalid shelf bytes.");
        }

        ClaimFixedNScalar16ShelfForWriteContext(writeContext, shelfOffset);
        if (writeContext.FixedNScalar16MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? stagedShelfBytes))
        {
            shelfBytes.CopyTo(stagedShelfBytes);
            return;
        }

        writeContext.FixedNScalar16MutableBatchShelfBytes[shelfOffset] = shelfBytes.ToArray();
    }

    /// <summary>
    /// Enters the `FSN-16` writer-context staging scope for one index root.<br/>
    /// Shelf-local writers take the read side so topology fallback cannot rewrite the route graph while the writer is selecting and claiming a physical shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FSN-16` index.<br/></param>
    internal void EnterFixedNScalar16WriterContextStaging(long rootRouterOffset)
    {
        GetFixedNScalar16TopologyMutationSync(rootRouterOffset).EnterReadLock();
    }

    /// <summary>
    /// Leaves the `FSN-16` writer-context staging scope for one index root.<br/>
    /// Callers must pair this with <see cref="EnterFixedNScalar16WriterContextStaging(long)"/> in a finally block.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FSN-16` index.<br/></param>
    internal void ExitFixedNScalar16WriterContextStaging(long rootRouterOffset)
    {
        GetFixedNScalar16TopologyMutationSync(rootRouterOffset).ExitReadLock();
    }

    /// <summary>
    /// Enters the shared `FS32-16` writer-context staging gate for one index root.<br/>
    /// Shelf-local writer-context inserts use this while they walk routes and stage shelf bytes so unsupported topology fallback for the same index cannot rewrite router state underneath the route walk.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FS32-16` index.<br/></param>
    internal void EnterFixed32Scalar16WriterContextStaging(long rootRouterOffset)
    {
        GetFixed32Scalar16TopologyMutationSync(rootRouterOffset).EnterReadLock();
    }

    /// <summary>
    /// Leaves the shared `FS32-16` writer-context staging gate for one index root.<br/>
    /// Callers must pair this with <see cref="EnterFixed32Scalar16WriterContextStaging(long)"/> in a finally block.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FS32-16` index.<br/></param>
    internal void ExitFixed32Scalar16WriterContextStaging(long rootRouterOffset)
    {
        GetFixed32Scalar16TopologyMutationSync(rootRouterOffset).ExitReadLock();
    }

    /// <summary>
    /// Runs an unsupported `SS8-8` topology fallback under the narrow index topology gate and the serialized publication seam.<br/>
    /// The index-specific topology gate blocks only writer-context staging for the same root router, while <c>writePublicationSync</c> preserves the single `DataKernel` append/commit boundary across the session.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="fallback">The fallback operation that performs route initialization, split, duplicate-run, or other topology-changing work.<br/></param>
    /// <returns>The encoded insert result returned by <paramref name="fallback"/>.</returns>
    internal Scalar8Scalar8EncodedInsertResult RunScalar8Scalar8SerializedTopologyFallback(
        long rootRouterOffset,
        Func<Scalar8Scalar8EncodedInsertResult> fallback)
    {
        ArgumentNullException.ThrowIfNull(fallback);
        ReaderWriterLockSlim topologySync = GetScalar8Scalar8TopologyMutationSync(rootRouterOffset);
        topologySync.EnterWriteLock();
        try
        {
            scalar8Scalar8WriterOperationSync.EnterWriteLock();
            try
            {
                lock (writePublicationSync)
                {
                    return fallback();
                }
            }
            finally
            {
                scalar8Scalar8WriterOperationSync.ExitWriteLock();
            }
        }
        finally
        {
            topologySync.ExitWriteLock();
        }
    }

    /// <summary>
    /// Attempts the narrow queued-writer cold-route path for one unset `SS8-8` root-prefix route.<br/>
    /// This path does not take the broad writer-operation gate because it publishes exactly one new shelf plus one direct root-router prefix update under the per-root topology gate and the storage publication lock.<br/>
    /// A false return means the route was no longer unset, so the caller should retry normal writer-context admission or use the broader topology fallback for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile to use for the new shelf.<br/></param>
    /// <param name="encodedKey">The encoded key to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertScalar8Scalar8QueuedColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 preparedShelf = new(shelfBytes, profile);
        preparedShelf.Initialize();
        Scalar8Scalar8InsertResult preparedInsertResult = preparedShelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);
        if (preparedInsertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected SS8-8 queued cold-route shelf insert, got {preparedInsertResult}.");
        }

        Scalar8Scalar8TopologyOwnerKey topologyOwnerKey = new(1, rootRouterOffset, 0, prefixByte);
        object topologyOwner = GetScalar8Scalar8TopologyOwner(topologyOwnerKey);
        lock (topologyOwner)
        {
            ReportScalar8Scalar8TopologyOwnerEnteredForValidation(topologyOwnerKey);
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                    if (currentTarget != 0)
                    {
                        result = default;
                        return false;
                    }

                    byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                    RouterReader existingReader = new(existingRouter);
                    if (existingReader.FindTarget(prefixByte) != 0)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                    shelfBytes.CopyTo(shelfReservation.Span);

                    byte[] updatedRouter = new byte[RouterLayout.Size];
                    existingRouter.CopyTo(updatedRouter, 0);
                    RouterWriter writer = new(updatedRouter);
                    writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                    kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar8Scalar8EncodedInsertResult(
                        Scalar8Scalar8EncodedInsertOutcome.Inserted,
                        CreatedInitialShelfRoute: true,
                        RouteCreateCommit: telemetry,
                        InsertCommit: default)
                    {
                        StructuralKind = Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                        PrimaryOffset = shelfReservation.Extent.Offset,
                        LeftShelfOffset = shelfReservation.Extent.Offset,
                        RightShelfOffset = 0
                    };
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer cold-route path for one unset `SS16-8` root-prefix route.<br/>
    /// This path publishes exactly one new widened-key shelf plus one direct root-router prefix update under the per-root topology gate and the storage publication lock.<br/>
    /// A false return means the route was no longer unset, so the caller should retry normal writer-context admission or use the broader serialized fallback for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-8` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile to use for the new shelf.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert into the new shelf.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertScalar16Scalar8DirectColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar16Scalar8RoutedInsertResult result)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar8 preparedShelf = new(shelfBytes, profile);
        preparedShelf.Initialize();
        Scalar16Scalar8InsertResult preparedInsertResult = preparedShelf.Insert(
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            allowDuplicateKeys);
        if (preparedInsertResult != Scalar16Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected SS16-8 direct cold-route shelf insert, got {preparedInsertResult}.");
        }

        PrimitiveTopologyOwnerKey topologyOwnerKey = new(1, 1, rootRouterOffset, 0, prefixByte);
        object topologyOwner = GetPrimitiveTopologyOwner(topologyOwnerKey);
        lock (topologyOwner)
        {
            ReportPrimitiveTopologyOwnerEnteredForValidation(topologyOwnerKey);
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                    if (currentTarget != 0)
                    {
                        result = default;
                        return false;
                    }

                    byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                    RouterReader existingReader = new(existingRouter);
                    if (existingReader.FindTarget(prefixByte) != 0)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                    shelfBytes.CopyTo(shelfReservation.Span);

                    byte[] updatedRouter = new byte[RouterLayout.Size];
                    existingRouter.CopyTo(updatedRouter, 0);
                    RouterWriter writer = new(updatedRouter);
                    writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                    kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar16Scalar8RoutedInsertResult(
                        Scalar16Scalar8RoutedInsertKind.WalkedNoSplit,
                        preparedInsertResult,
                        shelfReservation.Extent.Offset,
                        shelfReservation.Extent.Offset,
                        0,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Inserts one `SS16-8` tuple through the existing routed topology path under the per-root topology gate and storage publication lock.<br/>
    /// This is the bounded fallback after writer-context staging rejects a route because it needs split, transform, or other topology publication work.<br/>
    /// The operation remains serialized for topology safety, but it no longer enters session durability-batch state for a one-item direct insert.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-8` index.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <returns>The routed insert result from the serialized topology path.<br/></returns>
    internal Scalar16Scalar8RoutedInsertResult InsertScalar16Scalar8DirectSerializedTopologyFallback(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(1, 2, rootRouterOffset, 0, -1));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    return InsertWalkedRoutedScalar16Scalar8(
                        rootRouterOffset,
                        profile,
                        encodedKeyHigh,
                        encodedKeyLow,
                        encodedIdentity,
                        allowDuplicateKeys,
                        maxRouterHops);
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    private readonly record struct Scalar16Scalar8TransformSplitBuild(
        ushort SplitKeyDepth,
        byte SelectedRightPrefixByte,
        byte[] LeftShelfBytes,
        byte[] RightShelfBytes,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar8InsertResult InsertResult,
        ushort AllocationClassId,
        ushort ChildRouterKeyDepth,
        int RouterArenaLength);

    /// <summary>
    /// Attempts a narrowed direct-writer same-prefix shelf transform for a full walked `SS16-8` shelf.<br/>
    /// The route walk, source shelf read, no-op detection, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only route recheck, shelf/router allocation, shelf/router writes, cache invalidation, arena registration, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow shelf transform and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-8` index.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the shelf transform was published.<br/></param>
    /// <returns>True when the shelf transform was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TryTransformScalar16Scalar8DirectShelf(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        int maxRouterHops,
        out Scalar16Scalar8RoutedInsertResult result)
    {
        Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar8RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(1, 3, rootRouterOffset, target.Offset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryBuildScalar16Scalar8TransformSplit(
                existingShelfBytes,
                GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, childRouterKeyDepth),
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentity,
                target.AllocationClassId,
                childRouterKeyDepth,
                out Scalar16Scalar8TransformSplitBuild build))
            {
                if (build.InsertResult == Scalar16Scalar8InsertResult.AlreadyPresent ||
                    build.InsertResult == Scalar16Scalar8InsertResult.KeyConflict)
                {
                    result = new Scalar16Scalar8RoutedInsertResult(
                        build.InsertResult == Scalar16Scalar8InsertResult.KeyConflict
                            ? Scalar16Scalar8RoutedInsertKind.KeyConflict
                            : Scalar16Scalar8RoutedInsertKind.NoOp,
                        build.InsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    Scalar16Scalar8RoutePathTarget currentPathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
                    if (currentPathTarget.Target.Kind != Scalar16Scalar8RouteTargetKind.Shelf ||
                        currentPathTarget.Target.Offset != target.Offset ||
                        currentPathTarget.Target.RouterDepth != target.RouterDepth)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.LeftShelfBytes.CopyTo(leftAppend.Span);
                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.RightShelfBytes.CopyTo(rightAppend.Span);

                    int appendedRouterCount = build.SplitKeyDepth - build.ChildRouterKeyDepth;
                    long nextRouterOffset = 0;
                    for (int i = appendedRouterCount - 1; i >= 0; i--)
                    {
                        ushort routerDepth = checked((ushort)(build.ChildRouterKeyDepth + i + 1));
                        long[] targets = routerDepth == build.SplitKeyDepth
                            ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                            : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
                        RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                        RouterWriter appendedWriter = new(appendedRouter.Span);
                        appendedWriter.InitializeExpandedOneByte(routerDepth, build.AllocationClassId, targets);
                        nextRouterOffset = appendedRouter.Extent.Offset;
                    }

                    RawDataReservation childRouterRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
                    RouterWriter childWriter = new(childRouterRewrite.Span);
                    childWriter.InitializeExpandedOneByte(
                        build.ChildRouterKeyDepth,
                        build.AllocationClassId,
                        CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte));
                    childWriter.WriteArenaMetadata(
                        arenaBaseDelta: 0,
                        arenaLength: build.RouterArenaLength,
                        routerPageSize: checked((ushort)RouterLayout.Size),
                        routerPageIndex: 0,
                        routerPageCount: checked((ushort)(build.RouterArenaLength / RouterLayout.Size)),
                        arenaFlags: 0);

                    scalar16Scalar8CleanShelfCache.Remove(target.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(target.Offset);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    RouterArenaState arena = RegisterRouterArena(target.Offset, build.RouterArenaLength);
                    arena.MarkUsed(0);
                    result = new Scalar16Scalar8RoutedInsertResult(
                        Scalar16Scalar8RoutedInsertKind.WalkedShelfTransformSplit,
                        build.InsertResult,
                        target.Offset,
                        leftAppend.Extent.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts a narrowed direct-writer parent-route split for a full walked `SS16-8` shelf.<br/>
    /// The route walk, source shelf read, parent-router validation, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only the final parent-route recheck, right-shelf allocation, shelf/router staging, cache invalidation, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow parent-route split and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-8` index.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the parent-route split was published.<br/></param>
    /// <returns>True when the parent-route split was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TrySplitScalar16Scalar8DirectParentRoute(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        int maxRouterHops,
        out Scalar16Scalar8RoutedInsertResult result)
    {
        Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar8RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(1, 4, rootRouterOffset, pathTarget.ParentRouterOffset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryCreateScalar16Scalar8SplitShelves(
                existingShelfBytes,
                target.RouterDepth,
                GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, target.RouterDepth),
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentity,
                out byte selectedRightPrefixByte,
                out byte[] leftShelfBytes,
                out byte[] rightShelfBytes,
                out _,
                out _,
                out Scalar16Scalar8InsertResult splitResult))
            {
                if (splitResult == Scalar16Scalar8InsertResult.AlreadyPresent ||
                    splitResult == Scalar16Scalar8InsertResult.KeyConflict)
                {
                    result = new Scalar16Scalar8RoutedInsertResult(
                        splitResult == Scalar16Scalar8InsertResult.KeyConflict
                            ? Scalar16Scalar8RoutedInsertKind.KeyConflict
                            : Scalar16Scalar8RoutedInsertKind.NoOp,
                        splitResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid || !parentReader.HasDirectIndex)
            {
                result = default;
                return false;
            }

            if (parentReader.FindTarget(pathTarget.RoutePrefixByte) != target.Offset)
            {
                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
                    parentReader = new RouterReader(parentRouterBytes);
                    if (!parentReader.IsValid ||
                        !parentReader.HasDirectIndex ||
                        parentReader.FindTarget(pathTarget.RoutePrefixByte) != target.Offset)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    byte[] updatedRouterBytes = new byte[RouterLayout.Size];
                    parentRouterBytes.CopyTo(updatedRouterBytes, 0);
                    RouterWriter parentWriter = new(updatedRouterBytes);
                    for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
                    {
                        byte prefixByte = (byte)prefix;
                        if (parentReader.GetDirectTarget(prefixByte) == target.Offset)
                        {
                            long targetOffset = prefixByte < selectedRightPrefixByte
                                ? target.Offset
                                : rightAppend.Extent.Offset;
                            parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
                        }
                    }

                    scalar16Scalar8CleanShelfCache.Remove(target.Offset);
                    kernel.StageWriteAt(target.Offset, leftShelfBytes);
                    kernel.StageWriteAt(rightAppend.Extent.Offset, rightShelfBytes);
                    InvalidateRouterReadCacheForRouterRewrite(pathTarget.ParentRouterOffset);
                    kernel.StageWriteAt(pathTarget.ParentRouterOffset, updatedRouterBytes);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar16Scalar8RoutedInsertResult(
                        Scalar16Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                        splitResult,
                        pathTarget.ParentRouterOffset,
                        target.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer cold-route path for one unset `SS8-16` root-prefix route.<br/>
    /// This path publishes exactly one wide-identity shelf plus one direct root-router prefix update under the per-root topology gate and the storage publication lock.<br/>
    /// A false return means the route was no longer unset, so the caller should retry normal writer-context admission or use the broader serialized fallback for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-16` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile to use for the new shelf.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertScalar8Scalar16DirectColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        out Scalar8Scalar16RoutedInsertResult result)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar16 preparedShelf = new(shelfBytes, profile);
        preparedShelf.Initialize();
        Scalar8Scalar16InsertResult preparedInsertResult = preparedShelf.Insert(
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys);
        if (preparedInsertResult != Scalar8Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected SS8-16 direct cold-route shelf insert, got {preparedInsertResult}.");
        }

        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(2, 1, rootRouterOffset, 0, prefixByte));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                    if (currentTarget != 0)
                    {
                        result = default;
                        return false;
                    }

                    byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                    RouterReader existingReader = new(existingRouter);
                    if (existingReader.FindTarget(prefixByte) != 0)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                    shelfBytes.CopyTo(shelfReservation.Span);

                    byte[] updatedRouter = new byte[RouterLayout.Size];
                    existingRouter.CopyTo(updatedRouter, 0);
                    RouterWriter writer = new(updatedRouter);
                    writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                    kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar8Scalar16RoutedInsertResult(
                        Scalar8Scalar16RoutedInsertKind.WalkedNoSplit,
                        preparedInsertResult,
                        shelfReservation.Extent.Offset,
                        shelfReservation.Extent.Offset,
                        0,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Inserts one `SS8-16` tuple through the existing routed topology path under the per-root topology gate and storage publication lock.<br/>
    /// This is the bounded fallback after writer-context staging rejects a route because it needs split, transform, or other topology publication work.<br/>
    /// The operation remains serialized for topology safety, but it no longer enters session durability-batch state for a one-item direct insert.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-16` index.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <returns>The routed insert result from the serialized topology path.<br/></returns>
    internal Scalar8Scalar16RoutedInsertResult InsertScalar8Scalar16DirectSerializedTopologyFallback(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(2, 2, rootRouterOffset, 0, -1));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    return InsertWalkedRoutedScalar8Scalar16(
                        rootRouterOffset,
                        profile,
                        encodedKey,
                        encodedIdentityHigh,
                        encodedIdentityLow,
                        allowDuplicateKeys,
                        maxRouterHops);
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    private readonly record struct Scalar8Scalar16TransformSplitBuild(
        ushort SplitKeyDepth,
        byte SelectedRightPrefixByte,
        byte ChildDepthFirstPrefixByte,
        byte[] LeftShelfBytes,
        byte[] RightShelfBytes,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        ushort AllocationClassId,
        ushort ChildRouterKeyDepth,
        int RouterArenaLength);

    /// <summary>
    /// Attempts a narrowed direct-writer same-prefix shelf transform for a full walked `SS8-16` shelf.<br/>
    /// The route walk, source shelf read, no-op detection, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only route recheck, shelf/router allocation, shelf/router writes, cache invalidation, arena registration, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow shelf transform and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-16` index.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the shelf transform was published.<br/></param>
    /// <returns>True when the shelf transform was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TryTransformScalar8Scalar16DirectShelf(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops,
        out Scalar8Scalar16RoutedInsertResult result)
    {
        Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
        Scalar8Scalar16RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(2, 3, rootRouterOffset, target.Offset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryBuildScalar8Scalar16TransformSplit(
                existingShelfBytes,
                GetScalar8Scalar8Prefix(encodedKey, childRouterKeyDepth),
                profile,
                encodedKey,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                childRouterKeyDepth,
                out Scalar8Scalar16TransformSplitBuild build))
            {
                if (build.InsertResult == Scalar8Scalar16InsertResult.AlreadyPresent ||
                    build.InsertResult == Scalar8Scalar16InsertResult.KeyConflict)
                {
                    result = new Scalar8Scalar16RoutedInsertResult(
                        build.InsertResult == Scalar8Scalar16InsertResult.KeyConflict
                            ? Scalar8Scalar16RoutedInsertKind.KeyConflict
                            : Scalar8Scalar16RoutedInsertKind.NoOp,
                        build.InsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    Scalar8Scalar16RoutePathTarget currentPathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
                    if (currentPathTarget.Target.Kind != Scalar8Scalar16RouteTargetKind.Shelf ||
                        currentPathTarget.Target.Offset != target.Offset ||
                        currentPathTarget.Target.RouterDepth != target.RouterDepth)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.LeftShelfBytes.CopyTo(leftAppend.Span);
                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.RightShelfBytes.CopyTo(rightAppend.Span);

                    int appendedRouterCount = build.SplitKeyDepth - build.ChildRouterKeyDepth;
                    long nextRouterOffset = 0;
                    for (int i = appendedRouterCount - 1; i >= 0; i--)
                    {
                        ushort routerDepth = checked((ushort)(build.ChildRouterKeyDepth + i + 1));
                        long[] targets = routerDepth == build.SplitKeyDepth
                            ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                            : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
                        RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                        RouterWriter appendedWriter = new(appendedRouter.Span);
                        appendedWriter.InitializeExpandedOneByte(routerDepth, build.AllocationClassId, targets);
                        nextRouterOffset = appendedRouter.Extent.Offset;
                    }

                    RawDataReservation childRouterRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
                    RouterWriter childWriter = new(childRouterRewrite.Span);
                    childWriter.InitializeExpandedOneByte(
                        build.ChildRouterKeyDepth,
                        build.AllocationClassId,
                        nextRouterOffset == 0
                            ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                            : CreateScalar8Scalar8IntermediateSplitRouteTargets(
                                nextRouterOffset,
                                leftAppend.Extent.Offset,
                                rightAppend.Extent.Offset,
                                build.ChildDepthFirstPrefixByte));
                    childWriter.WriteArenaMetadata(
                        arenaBaseDelta: 0,
                        arenaLength: build.RouterArenaLength,
                        routerPageSize: checked((ushort)RouterLayout.Size),
                        routerPageIndex: 0,
                        routerPageCount: checked((ushort)(build.RouterArenaLength / RouterLayout.Size)),
                        arenaFlags: 0);

                    scalar8Scalar16CleanShelfCache.Remove(target.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(target.Offset);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    RouterArenaState arena = RegisterRouterArena(target.Offset, build.RouterArenaLength);
                    arena.MarkUsed(0);
                    result = new Scalar8Scalar16RoutedInsertResult(
                        Scalar8Scalar16RoutedInsertKind.WalkedShelfTransformSplit,
                        build.InsertResult,
                        target.Offset,
                        leftAppend.Extent.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts a narrowed direct-writer parent-route split for a full walked `SS8-16` shelf.<br/>
    /// The route walk, source shelf read, parent-router validation, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only the final parent-route recheck, right-shelf allocation, shelf/router staging, cache invalidation, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow parent-route split and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-16` index.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the parent-route split was published.<br/></param>
    /// <returns>True when the parent-route split was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TrySplitScalar8Scalar16DirectParentRoute(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops,
        out Scalar8Scalar16RoutedInsertResult result)
    {
        Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
        Scalar8Scalar16RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(2, 4, rootRouterOffset, pathTarget.ParentRouterOffset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryCreateScalar8Scalar16SplitShelves(
                existingShelfBytes,
                target.RouterDepth,
                GetScalar8Scalar8Prefix(encodedKey, target.RouterDepth),
                profile,
                encodedKey,
                encodedIdentityHigh,
                encodedIdentityLow,
                out byte selectedRightPrefixByte,
                out byte[] leftShelfBytes,
                out byte[] rightShelfBytes,
                out _,
                out _,
                out Scalar8Scalar16InsertResult splitResult))
            {
                if (splitResult == Scalar8Scalar16InsertResult.AlreadyPresent ||
                    splitResult == Scalar8Scalar16InsertResult.KeyConflict)
                {
                    result = new Scalar8Scalar16RoutedInsertResult(
                        splitResult == Scalar8Scalar16InsertResult.KeyConflict
                            ? Scalar8Scalar16RoutedInsertKind.KeyConflict
                            : Scalar8Scalar16RoutedInsertKind.NoOp,
                        splitResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid || !parentReader.HasDirectIndex)
            {
                result = default;
                return false;
            }

            if (parentReader.FindTarget(pathTarget.ParentPrefixByte) != target.Offset)
            {
                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
                    parentReader = new RouterReader(parentRouterBytes);
                    if (!parentReader.IsValid ||
                        !parentReader.HasDirectIndex ||
                        parentReader.FindTarget(pathTarget.ParentPrefixByte) != target.Offset)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    byte[] updatedRouterBytes = new byte[RouterLayout.Size];
                    parentRouterBytes.CopyTo(updatedRouterBytes, 0);
                    RouterWriter parentWriter = new(updatedRouterBytes);
                    for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
                    {
                        byte prefixByte = (byte)prefix;
                        if (parentReader.GetDirectTarget(prefixByte) == target.Offset)
                        {
                            long targetOffset = prefixByte < selectedRightPrefixByte
                                ? target.Offset
                                : rightAppend.Extent.Offset;
                            parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
                        }
                    }

                    scalar8Scalar16CleanShelfCache.Remove(target.Offset);
                    kernel.StageWriteAt(target.Offset, leftShelfBytes);
                    kernel.StageWriteAt(rightAppend.Extent.Offset, rightShelfBytes);
                    InvalidateRouterReadCacheForRouterRewrite(pathTarget.ParentRouterOffset);
                    kernel.StageWriteAt(pathTarget.ParentRouterOffset, updatedRouterBytes);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar8Scalar16RoutedInsertResult(
                        Scalar8Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                        splitResult,
                        pathTarget.ParentRouterOffset,
                        target.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer cold-route path for one unset `SS16-16` root-prefix route.<br/>
    /// This path publishes exactly one wide-key/wide-identity shelf plus one direct root-router prefix update under the per-root topology gate and the storage publication lock.<br/>
    /// A false return means the route was no longer unset, so the caller should retry normal writer-context admission or use the broader serialized fallback for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-16` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile to use for the new shelf.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert into the new shelf.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertScalar16Scalar16DirectColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        out Scalar16Scalar16RoutedInsertResult result)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar16 preparedShelf = new(shelfBytes, profile);
        preparedShelf.Initialize();
        Scalar16Scalar16InsertResult preparedInsertResult = preparedShelf.Insert(
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys);
        if (preparedInsertResult != Scalar16Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected SS16-16 direct cold-route shelf insert, got {preparedInsertResult}.");
        }

        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(3, 1, rootRouterOffset, 0, prefixByte));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                    if (currentTarget != 0)
                    {
                        result = default;
                        return false;
                    }

                    byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                    RouterReader existingReader = new(existingRouter);
                    if (existingReader.FindTarget(prefixByte) != 0)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                    shelfBytes.CopyTo(shelfReservation.Span);

                    byte[] updatedRouter = new byte[RouterLayout.Size];
                    existingRouter.CopyTo(updatedRouter, 0);
                    RouterWriter writer = new(updatedRouter);
                    writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                    kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar16Scalar16RoutedInsertResult(
                        Scalar16Scalar16RoutedInsertKind.WalkedNoSplit,
                        preparedInsertResult,
                        shelfReservation.Extent.Offset,
                        shelfReservation.Extent.Offset,
                        0,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Inserts one `SS16-16` tuple through the existing routed topology path under the per-root topology gate and storage publication lock.<br/>
    /// This is the bounded fallback after writer-context staging rejects a route because it needs split, transform, or other topology publication work.<br/>
    /// The operation remains serialized for topology safety, but it no longer enters session durability-batch state for a one-item direct insert.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-16` index.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <returns>The routed insert result from the serialized topology path.<br/></returns>
    internal Scalar16Scalar16RoutedInsertResult InsertScalar16Scalar16DirectSerializedTopologyFallback(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(3, 2, rootRouterOffset, 0, -1));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    return InsertWalkedRoutedScalar16Scalar16(
                        rootRouterOffset,
                        profile,
                        encodedKeyHigh,
                        encodedKeyLow,
                        encodedIdentityHigh,
                        encodedIdentityLow,
                        allowDuplicateKeys,
                        maxRouterHops);
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    private readonly record struct Scalar16Scalar16TransformSplitBuild(
        ushort SplitKeyDepth,
        byte SelectedRightPrefixByte,
        byte[] LeftShelfBytes,
        byte[] RightShelfBytes,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        ushort AllocationClassId,
        ushort ChildRouterKeyDepth,
        int RouterArenaLength);

    /// <summary>
    /// Attempts a narrowed direct-writer same-prefix shelf transform for a full walked `SS16-16` shelf.<br/>
    /// The route walk, source shelf read, no-op detection, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only route recheck, shelf/router allocation, shelf/router writes, cache invalidation, arena registration, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow shelf transform and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-16` index.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the shelf transform was published.<br/></param>
    /// <returns>True when the shelf transform was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TryTransformScalar16Scalar16DirectShelf(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops,
        out Scalar16Scalar16RoutedInsertResult result)
    {
        Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar16RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(3, 3, rootRouterOffset, target.Offset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar16Scalar16ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryBuildScalar16Scalar16TransformSplit(
                existingShelfBytes,
                GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, childRouterKeyDepth),
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                childRouterKeyDepth,
                out Scalar16Scalar16TransformSplitBuild build))
            {
                if (build.InsertResult == Scalar16Scalar16InsertResult.AlreadyPresent ||
                    build.InsertResult == Scalar16Scalar16InsertResult.KeyConflict)
                {
                    result = new Scalar16Scalar16RoutedInsertResult(
                        build.InsertResult == Scalar16Scalar16InsertResult.KeyConflict
                            ? Scalar16Scalar16RoutedInsertKind.KeyConflict
                            : Scalar16Scalar16RoutedInsertKind.NoOp,
                        build.InsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    Scalar16Scalar16RoutePathTarget currentPathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
                    if (currentPathTarget.Target.Kind != Scalar16Scalar16RouteTargetKind.Shelf ||
                        currentPathTarget.Target.Offset != target.Offset ||
                        currentPathTarget.Target.RouterDepth != target.RouterDepth)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.LeftShelfBytes.CopyTo(leftAppend.Span);
                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.RightShelfBytes.CopyTo(rightAppend.Span);

                    int appendedRouterCount = build.SplitKeyDepth - build.ChildRouterKeyDepth;
                    long nextRouterOffset = 0;
                    for (int i = appendedRouterCount - 1; i >= 0; i--)
                    {
                        ushort routerDepth = checked((ushort)(build.ChildRouterKeyDepth + i + 1));
                        long[] targets = routerDepth == build.SplitKeyDepth
                            ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                            : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
                        RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                        RouterWriter appendedWriter = new(appendedRouter.Span);
                        appendedWriter.InitializeExpandedOneByte(routerDepth, build.AllocationClassId, targets);
                        nextRouterOffset = appendedRouter.Extent.Offset;
                    }

                    RawDataReservation childRouterRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
                    RouterWriter childWriter = new(childRouterRewrite.Span);
                    childWriter.InitializeExpandedOneByte(
                        build.ChildRouterKeyDepth,
                        build.AllocationClassId,
                        CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte));
                    childWriter.WriteArenaMetadata(
                        arenaBaseDelta: 0,
                        arenaLength: build.RouterArenaLength,
                        routerPageSize: checked((ushort)RouterLayout.Size),
                        routerPageIndex: 0,
                        routerPageCount: checked((ushort)(build.RouterArenaLength / RouterLayout.Size)),
                        arenaFlags: 0);

                    scalar16Scalar16CleanShelfCache.Remove(target.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(target.Offset);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    RouterArenaState arena = RegisterRouterArena(target.Offset, build.RouterArenaLength);
                    arena.MarkUsed(0);
                    result = new Scalar16Scalar16RoutedInsertResult(
                        Scalar16Scalar16RoutedInsertKind.WalkedShelfTransformSplit,
                        build.InsertResult,
                        target.Offset,
                        leftAppend.Extent.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts a narrowed direct-writer parent-route split for a full walked `SS16-16` shelf.<br/>
    /// The route walk, source shelf read, parent-router validation, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only the final parent-route recheck, right-shelf allocation, shelf/router staging, cache invalidation, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow parent-route split and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS16-16` index.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the parent-route split was published.<br/></param>
    /// <returns>True when the parent-route split was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TrySplitScalar16Scalar16DirectParentRoute(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops,
        out Scalar16Scalar16RoutedInsertResult result)
    {
        Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar16RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(3, 4, rootRouterOffset, pathTarget.ParentRouterOffset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar16Scalar16ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryCreateScalar16Scalar16SplitShelves(
                existingShelfBytes,
                target.RouterDepth,
                GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, target.RouterDepth),
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentityHigh,
                encodedIdentityLow,
                out byte selectedRightPrefixByte,
                out byte[] leftShelfBytes,
                out byte[] rightShelfBytes,
                out _,
                out _,
                out Scalar16Scalar16InsertResult splitResult))
            {
                if (splitResult == Scalar16Scalar16InsertResult.AlreadyPresent ||
                    splitResult == Scalar16Scalar16InsertResult.KeyConflict)
                {
                    result = new Scalar16Scalar16RoutedInsertResult(
                        splitResult == Scalar16Scalar16InsertResult.KeyConflict
                            ? Scalar16Scalar16RoutedInsertKind.KeyConflict
                            : Scalar16Scalar16RoutedInsertKind.NoOp,
                        splitResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid || !parentReader.HasDirectIndex)
            {
                result = default;
                return false;
            }

            if (parentReader.FindTarget(pathTarget.ParentPrefixByte) != target.Offset)
            {
                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
                    parentReader = new RouterReader(parentRouterBytes);
                    if (!parentReader.IsValid ||
                        !parentReader.HasDirectIndex ||
                        parentReader.FindTarget(pathTarget.ParentPrefixByte) != target.Offset)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    byte[] updatedRouterBytes = new byte[RouterLayout.Size];
                    parentRouterBytes.CopyTo(updatedRouterBytes, 0);
                    RouterWriter parentWriter = new(updatedRouterBytes);
                    for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
                    {
                        byte prefixByte = (byte)prefix;
                        if (parentReader.GetDirectTarget(prefixByte) == target.Offset)
                        {
                            long targetOffset = prefixByte < selectedRightPrefixByte
                                ? target.Offset
                                : rightAppend.Extent.Offset;
                            parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
                        }
                    }

                    scalar16Scalar16CleanShelfCache.Remove(target.Offset);
                    kernel.StageWriteAt(target.Offset, leftShelfBytes);
                    kernel.StageWriteAt(rightAppend.Extent.Offset, rightShelfBytes);
                    InvalidateRouterReadCacheForRouterRewrite(pathTarget.ParentRouterOffset);
                    kernel.StageWriteAt(pathTarget.ParentRouterOffset, updatedRouterBytes);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Scalar16Scalar16RoutedInsertResult(
                        Scalar16Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                        splitResult,
                        pathTarget.ParentRouterOffset,
                        target.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer cold-route path for one unset `FS32-8` root-prefix route.<br/>
    /// This path publishes exactly one fixed-32 key shelf plus one direct root-router prefix update under the per-root topology gate and the storage publication lock.<br/>
    /// A false return means the route was no longer unset, so the caller should retry normal writer-context admission or use the broader serialized fallback for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FS32-8` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile to use for the new shelf.<br/></param>
    /// <param name="key0">The first encoded key lane to insert into the new shelf.<br/></param>
    /// <param name="key1">The second encoded key lane to insert into the new shelf.<br/></param>
    /// <param name="key2">The third encoded key lane to insert into the new shelf.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertFixed32Scalar8DirectColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Fixed32Scalar8RoutedInsertResult result)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar8 preparedShelf = new(shelfBytes, profile);
        preparedShelf.Initialize();
        Fixed32Scalar8InsertResult preparedInsertResult = preparedShelf.Insert(
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            allowDuplicateKeys);
        if (preparedInsertResult != Fixed32Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected FS32-8 direct cold-route shelf insert, got {preparedInsertResult}.");
        }

        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(4, 1, rootRouterOffset, 0, prefixByte));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                    if (currentTarget != 0)
                    {
                        result = default;
                        return false;
                    }

                    byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                    RouterReader existingReader = new(existingRouter);
                    if (existingReader.FindTarget(prefixByte) != 0)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                    shelfBytes.CopyTo(shelfReservation.Span);

                    byte[] updatedRouter = new byte[RouterLayout.Size];
                    existingRouter.CopyTo(updatedRouter, 0);
                    RouterWriter writer = new(updatedRouter);
                    writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                    kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    result = new Fixed32Scalar8RoutedInsertResult(
                        Fixed32Scalar8RoutedInsertKind.WalkedNoSplit,
                        preparedInsertResult,
                        shelfReservation.Extent.Offset,
                        shelfReservation.Extent.Offset,
                        0,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

