    private readonly record struct Fixed32Scalar16TransformSplitBuild(
        ushort SplitKeyDepth,
        byte SelectedRightPrefixByte,
        byte[] LeftShelfBytes,
        byte[] RightShelfBytes,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        ushort AllocationClassId,
        ushort ChildRouterKeyDepth,
        int RouterArenaLength);

    /// <summary>
    /// Attempts a narrowed direct-writer same-prefix shelf transform for a full walked `FS32-16` shelf.<br/>
    /// The route walk, source shelf read, no-op detection, and replacement shelf planning happen under the target root topology gate but outside the global storage publication lock.<br/>
    /// The storage publication lock covers only route recheck, shelf/router allocation, shelf/router writes, cache invalidation, arena registration, and commit.<br/>
    /// Returning false means the route shape could not be handled by this narrow shelf transform and the caller should use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `FS32-16` index.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile used by routed shelves.<br/></param>
    /// <param name="key0">The first encoded key lane to insert.<br/></param>
    /// <param name="key1">The second encoded key lane to insert.<br/></param>
    /// <param name="key2">The third encoded key lane to insert.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The routed insert result when the shelf transform was published.<br/></param>
    /// <returns>True when the shelf transform was published or resolved as a no-op; otherwise false.<br/></returns>
    internal bool TryTransformFixed32Scalar16DirectShelf(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops,
        out Fixed32Scalar16RoutedInsertResult result)
    {
        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(5, 3, rootRouterOffset, target.Offset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
            target = pathTarget.Target;
            if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid || existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                result = default;
                return false;
            }

            if (!TryBuildFixed32Scalar16TransformSplit(
                existingShelfBytes,
                GetFixed32Scalar16Prefix(key0, key1, key2, key3, childRouterKeyDepth),
                profile,
                key0,
                key1,
                key2,
                key3,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                childRouterKeyDepth,
                out Fixed32Scalar16TransformSplitBuild build))
            {
                if (build.InsertResult == Fixed32Scalar16InsertResult.AlreadyPresent ||
                    build.InsertResult == Fixed32Scalar16InsertResult.KeyConflict)
                {
                    result = new Fixed32Scalar16RoutedInsertResult(
                        build.InsertResult == Fixed32Scalar16InsertResult.KeyConflict
                            ? Fixed32Scalar16RoutedInsertKind.KeyConflict
                            : Fixed32Scalar16RoutedInsertKind.NoOp,
                        build.InsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                    return true;
                }

                result = default;
                return false;
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    Fixed32Scalar16RoutePathTarget currentPathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
                    if (currentPathTarget.Target.Kind != Fixed32Scalar16RouteTargetKind.Shelf ||
                        currentPathTarget.Target.Offset != target.Offset ||
                        currentPathTarget.Target.RouterDepth != target.RouterDepth)
                    {
                        result = default;
                        return false;
                    }

                    RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.LeftShelfBytes.CopyTo(leftAppend.Span);
                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    build.RightShelfBytes.CopyTo(rightAppend.Span);

                    int appendedRouterCount = build.SplitKeyDepth - build.ChildRouterKeyDepth;
                    long nextRouterOffset = 0;
                    for (int i = appendedRouterCount - 1; i >= 0; i--)
                    {
                        ushort routerDepth = checked((ushort)(build.ChildRouterKeyDepth + i + 1));
                        long[] targets = routerDepth == build.SplitKeyDepth
                            ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                            : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
                        RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                        RouterWriter appendedWriter = new(appendedRouter.Span);
                        appendedWriter.InitializeExpandedOneByte(routerDepth, build.AllocationClassId, targets);
                        nextRouterOffset = appendedRouter.Extent.Offset;
                    }

                    RawDataReservation childRouterRewrite = kernel.ReserveAt(target.Offset, RouterLayout.Size);
                    RouterWriter childWriter = new(childRouterRewrite.Span);
                    childWriter.InitializeExpandedOneByte(
                        build.ChildRouterKeyDepth,
                        build.AllocationClassId,
                        CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte));
                    childWriter.WriteArenaMetadata(
                        arenaBaseDelta: 0,
                        arenaLength: build.RouterArenaLength,
                        routerPageSize: checked((ushort)RouterLayout.Size),
                        routerPageIndex: 0,
                        routerPageCount: checked((ushort)(build.RouterArenaLength / RouterLayout.Size)),
                        arenaFlags: 0);

                    fixed32Scalar16CleanShelfCache.Remove(target.Offset);
                    InvalidateRouterReadCacheForRouterRewrite(target.Offset);
                    DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    RouterArenaState arena = RegisterRouterArena(target.Offset, build.RouterArenaLength);
                    arena.MarkUsed(0);
                    result = new Fixed32Scalar16RoutedInsertResult(
                        Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit,
                        build.InsertResult,
                        target.Offset,
                        leftAppend.Extent.Offset,
                        rightAppend.Extent.Offset,
                        telemetry);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow queued-writer full-shelf split path for a root-prefix `SS8-8` split.<br/>
    /// This handles only the simple case where the full shelf is still selected by multiple root-router prefixes and the incoming key can be separated by the root prefix byte.<br/>
    /// Deeper same-prefix transforms, parent-route splits, duplicate-run conversion, and changed-route races return false so the caller can use the broader serialized topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="rightPrefixByte">The root-prefix byte of the incoming encoded key.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the routed shelf.<br/></param>
    /// <param name="encodedKey">The encoded key to insert during the split.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert during the split.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the root-prefix split was published.<br/></param>
    /// <returns>True when the root-prefix split was published; false when the current route shape needs another fallback path.<br/></returns>
    internal bool TrySplitScalar8Scalar8QueuedRootPrefix(
        long rootRouterOffset,
        byte rightPrefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(2, rootRouterOffset, 0, rightPrefixByte));
        lock (topologyOwner)
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            kernel.Read(rootRouterOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The queued SS8-8 root-prefix split requires a valid direct-index root router.");
            }

            long fullShelfOffset = routerReader.FindTarget(rightPrefixByte);
            if (fullShelfOffset == 0)
            {
                result = default;
                return false;
            }

            byte leftPrefixByte = FindEarlierRootPrefixForSameTarget(routerReader, rightPrefixByte, fullShelfOffset);
            if (leftPrefixByte == rightPrefixByte)
            {
                result = default;
                return false;
            }

            object shelfOwner = GetScalar8Scalar8ShelfDomainOwner(fullShelfOffset);
            lock (shelfOwner)
            {
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(fullShelfOffset, existingShelfBytes);
            if (!TryBuildScalar8Scalar8RootPrefixSplit(
                fullShelfOffset,
                existingShelfBytes,
                rightPrefixByte,
                profile,
                encodedKey,
                encodedIdentity,
                allowDuplicateKeys,
                out byte[] leftShelfBytes,
                out byte[] rightShelfBytes,
                out int leftItemCount,
                out int rightItemCount,
                out Scalar8Scalar8InsertResult splitResult))
            {
                result = default;
                return false;
            }

            if (splitResult != Scalar8Scalar8InsertResult.Inserted)
            {
                result = new Scalar8Scalar8EncodedInsertResult(
                    MapScalar8Scalar8InsertOutcome(splitResult),
                    CreatedInitialShelfRoute: false,
                    RouteCreateCommit: default,
                    InsertCommit: default)
                {
                    StructuralKind = splitResult == Scalar8Scalar8InsertResult.KeyConflict
                        ? Scalar8Scalar8RoutedInsertKind.KeyConflict
                        : Scalar8Scalar8RoutedInsertKind.NoOp,
                    PrimaryOffset = fullShelfOffset,
                    LeftShelfOffset = 0,
                    RightShelfOffset = 0
                };
                return true;
            }

                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        byte[] currentRouterBytes = new byte[RouterLayout.Size];
                        kernel.Read(rootRouterOffset, currentRouterBytes);
                        RouterReader currentReader = new(currentRouterBytes);
                        if (!currentReader.IsValid ||
                            !currentReader.HasDirectIndex ||
                            currentReader.FindTarget(rightPrefixByte) != fullShelfOffset ||
                            FindEarlierRootPrefixForSameTarget(currentReader, rightPrefixByte, fullShelfOffset) != leftPrefixByte)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                        kernel.StageWriteAt(fullShelfOffset, leftShelfBytes);
                        kernel.StageWriteAt(rightAppend.Extent.Offset, rightShelfBytes);
                        byte[] updatedRouterBytes = new byte[RouterLayout.Size];
                        currentRouterBytes.CopyTo(updatedRouterBytes, 0);
                        RouterWriter writer = new(updatedRouterBytes);
                        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);
                        InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                        kernel.StageWriteAt(rootRouterOffset, updatedRouterBytes);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        result = new Scalar8Scalar8EncodedInsertResult(
                            Scalar8Scalar8EncodedInsertOutcome.Inserted,
                            CreatedInitialShelfRoute: false,
                            RouteCreateCommit: default,
                            InsertCommit: telemetry)
                        {
                            StructuralKind = Scalar8Scalar8RoutedInsertKind.RootPrefixSplit,
                            PrimaryOffset = fullShelfOffset,
                            LeftShelfOffset = fullShelfOffset,
                            RightShelfOffset = rightAppend.Extent.Offset
                        };
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrowed queued-writer shelf-transform split for a root-level same-prefix `SS8-8` full shelf.<br/>
    /// This handles only the case where the root route still points directly at the full shelf that can be transformed into a child router; walked parent-route splits and deeper transforms remain on the broader serialized topology path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="rootPrefixByte">The root-prefix byte of the incoming encoded key.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the routed shelf.<br/></param>
    /// <param name="encodedKey">The encoded key to insert during the transform split.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert during the transform split.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the transform split was published.<br/></param>
    /// <returns>True when the root-level transform split was published or resolved as a no-op; false when another fallback path is required.<br/></returns>
    internal bool TrySplitScalar8Scalar8QueuedRootShelfTransform(
        long rootRouterOffset,
        byte rootPrefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(3, rootRouterOffset, 0, rootPrefixByte));
        lock (topologyOwner)
        {
            byte[] rootRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(rootRouterOffset, rootRouterBytes);
            RouterReader rootReader = new(rootRouterBytes);
            if (!rootReader.IsValid || !rootReader.HasDirectIndex)
            {
                throw new InvalidDataException("The queued SS8-8 shelf-transform split requires a valid direct-index root router.");
            }

            long childRouterOffset = rootReader.FindTarget(rootPrefixByte);
            if (childRouterOffset == 0)
            {
                result = default;
                return false;
            }

            Span<byte> magic = stackalloc byte[sizeof(uint)];
            kernel.Read(childRouterOffset, magic);
            if (BinaryPrimitives.ReadUInt32LittleEndian(magic) != Scalar8Scalar8Layout.Magic)
            {
                result = default;
                return false;
            }

            object shelfOwner = GetScalar8Scalar8ShelfDomainOwner(childRouterOffset);
            lock (shelfOwner)
            {
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(childRouterOffset, existingShelfBytes);
            ushort childRouterKeyDepth = 1;
            byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, childRouterKeyDepth);
            if (!TryBuildScalar8Scalar8ShelfTransformSplit(
                existingShelfBytes,
                rightPrefixByte,
                profile,
                encodedKey,
                encodedIdentity,
                allowDuplicateKeys,
                rootReader.AllocationClassId,
                childRouterKeyDepth,
                out Scalar8Scalar8TransformSplitBuild build))
            {
                result = default;
                return false;
            }

            if (build.InsertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                result = new Scalar8Scalar8EncodedInsertResult(
                    MapScalar8Scalar8InsertOutcome(build.InsertResult),
                    CreatedInitialShelfRoute: false,
                    RouteCreateCommit: default,
                    InsertCommit: default)
                {
                    StructuralKind = build.InsertResult == Scalar8Scalar8InsertResult.KeyConflict
                        ? Scalar8Scalar8RoutedInsertKind.KeyConflict
                        : Scalar8Scalar8RoutedInsertKind.NoOp,
                    PrimaryOffset = childRouterOffset,
                    LeftShelfOffset = 0,
                    RightShelfOffset = 0
                };
                return true;
            }

                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        byte[] currentRootRouterBytes = new byte[RouterLayout.Size];
                        kernel.Read(rootRouterOffset, currentRootRouterBytes);
                        RouterReader currentRootReader = new(currentRootRouterBytes);
                        if (!currentRootReader.IsValid ||
                            !currentRootReader.HasDirectIndex ||
                            currentRootReader.FindTarget(rootPrefixByte) != childRouterOffset)
                        {
                            result = default;
                            return false;
                        }

                        Span<byte> currentMagic = stackalloc byte[sizeof(uint)];
                        kernel.Read(childRouterOffset, currentMagic);
                        if (BinaryPrimitives.ReadUInt32LittleEndian(currentMagic) != Scalar8Scalar8Layout.Magic)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                        long nextRouterOffset = 0;
                        int appendedRouterCount = build.SplitKeyDepth - childRouterKeyDepth;
                        long[] appendedRouterOffsets = appendedRouterCount > 0 ? new long[appendedRouterCount] : [];
                        for (int i = appendedRouterCount - 1; i >= 0; i--)
                        {
                            appendedRouterOffsets[i] = kernel.Reserve(RouterLayout.Size).Extent.Offset;
                            nextRouterOffset = appendedRouterOffsets[i];
                        }

                        nextRouterOffset = 0;
                        for (int i = appendedRouterCount - 1; i >= 0; i--)
                        {
                            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
                            long[] targets = routerDepth == build.SplitKeyDepth
                                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                                : CreateScalar8Scalar8IntermediateSplitRouteTargets(
                                    nextRouterOffset,
                                    leftAppend.Extent.Offset,
                                    rightAppend.Extent.Offset,
                                    GetScalar8Scalar8Prefix(build.FirstKey, routerDepth));
                            byte[] appendedRouterBytes = new byte[RouterLayout.Size];
                            RouterWriter appendedWriter = new(appendedRouterBytes);
                            appendedWriter.InitializeExpandedOneByte(routerDepth, currentRootReader.AllocationClassId, targets);
                            kernel.StageWriteAt(appendedRouterOffsets[i], appendedRouterBytes);
                            nextRouterOffset = appendedRouterOffsets[i];
                        }

                        byte[] childRouterBytes = new byte[RouterLayout.Size];
                        RouterWriter childWriter = new(childRouterBytes);
                        childWriter.InitializeExpandedOneByte(
                            childRouterKeyDepth,
                            currentRootReader.AllocationClassId,
                            nextRouterOffset == 0
                                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, build.SelectedRightPrefixByte)
                                : CreateScalar8Scalar8IntermediateSplitRouteTargets(
                                    nextRouterOffset,
                                    leftAppend.Extent.Offset,
                                    rightAppend.Extent.Offset,
                                    GetScalar8Scalar8Prefix(build.FirstKey, childRouterKeyDepth)));
                        childWriter.WriteArenaMetadata(
                            arenaBaseDelta: 0,
                            arenaLength: profile.ShelfExtentSize,
                            routerPageSize: checked((ushort)RouterLayout.Size),
                            routerPageIndex: 0,
                            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
                            arenaFlags: 0);

                        DiscardScalar8Scalar8MutableBatchShelfBytes(childRouterOffset);
                        kernel.StageWriteAt(leftAppend.Extent.Offset, build.LeftShelfBytes);
                        kernel.StageWriteAt(rightAppend.Extent.Offset, build.RightShelfBytes);
                        kernel.StageWriteAt(childRouterOffset, childRouterBytes);
                        InvalidateRouterReadCacheForRouterRewrite(childRouterOffset);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
                        arena.MarkUsed(0);
                        result = new Scalar8Scalar8EncodedInsertResult(
                            Scalar8Scalar8EncodedInsertOutcome.Inserted,
                            CreatedInitialShelfRoute: false,
                            RouteCreateCommit: default,
                            InsertCommit: telemetry)
                        {
                            StructuralKind = Scalar8Scalar8RoutedInsertKind.ShelfTransformSplit,
                            PrimaryOffset = childRouterOffset,
                            LeftShelfOffset = leftAppend.Extent.Offset,
                            RightShelfOffset = rightAppend.Extent.Offset
                        };
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrowed queued-writer walked parent-route split for a full `SS8-8` shelf.<br/>
    /// The route is rewalked under the target index topology gate, replacement shelves are built from the currently routed full shelf, and publication rewrites only the full shelf, one appended right shelf, and parent-router slots that still point at that shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the routed shelf.<br/></param>
    /// <param name="encodedKey">The encoded key to insert during the parent-route split.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert during the parent-route split.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The insert result when the parent-route split was published.<br/></param>
    /// <returns>True when the parent-route split was published or resolved as a no-op; false when another fallback path is required.<br/></returns>
    internal bool TrySplitScalar8Scalar8QueuedParentRoute(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(
            rootRouterOffset,
            encodedKey,
            maxRouterHops,
            Scalar8Scalar8RouteReadPolicy.Uncached);
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(4, rootRouterOffset, pathTarget.ParentRouterOffset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar8RoutePathTarget(
                rootRouterOffset,
                encodedKey,
                maxRouterHops,
                Scalar8Scalar8RouteReadPolicy.Uncached);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                result = default;
                return false;
            }

            object shelfOwner = GetScalar8Scalar8ShelfDomainOwner(target.Offset);
            lock (shelfOwner)
            {
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid ||
                existingReadOnly.ItemCount != profile.MaxItemCount ||
                existingReadOnly.IsDuplicateRun)
            {
                result = default;
                return false;
            }

            if (!TryCreateScalar8Scalar8SplitShelves(
                existingShelfBytes,
                target.RouterDepth,
                GetScalar8Scalar8Prefix(encodedKey, target.RouterDepth),
                profile,
                encodedKey,
                encodedIdentity,
                out byte selectedRightPrefixByte,
                out byte[] leftShelfBytes,
                out byte[] rightShelfBytes,
                out _,
                out _,
                out Scalar8Scalar8InsertResult splitResult))
            {
                if (splitResult == Scalar8Scalar8InsertResult.AlreadyPresent ||
                    splitResult == Scalar8Scalar8InsertResult.KeyConflict)
                {
                    result = new Scalar8Scalar8EncodedInsertResult(
                        MapScalar8Scalar8InsertOutcome(splitResult),
                        CreatedInitialShelfRoute: false,
                        RouteCreateCommit: default,
                        InsertCommit: default)
                    {
                        StructuralKind = splitResult == Scalar8Scalar8InsertResult.KeyConflict
                            ? Scalar8Scalar8RoutedInsertKind.KeyConflict
                            : Scalar8Scalar8RoutedInsertKind.NoOp,
                        PrimaryOffset = target.Offset,
                        LeftShelfOffset = 0,
                        RightShelfOffset = 0
                    };
                    return true;
                }

                result = default;
                return false;
            }

            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid || !parentReader.HasDirectIndex)
            {
                result = default;
                return false;
            }

            if (parentReader.FindTarget(pathTarget.RoutePrefixByte) != target.Offset)
            {
                result = default;
                return false;
            }

                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        byte[] currentParentRouterBytes = new byte[RouterLayout.Size];
                        kernel.Read(pathTarget.ParentRouterOffset, currentParentRouterBytes);
                        RouterReader currentParentReader = new(currentParentRouterBytes);
                        if (!currentParentReader.IsValid ||
                            !currentParentReader.HasDirectIndex ||
                            currentParentReader.FindTarget(pathTarget.RoutePrefixByte) != target.Offset)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                        byte[] updatedRouterBytes = new byte[RouterLayout.Size];
                        currentParentRouterBytes.CopyTo(updatedRouterBytes, 0);
                        RouterWriter parentWriter = new(updatedRouterBytes);
                        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
                        {
                            byte prefixByte = (byte)prefix;
                            if (currentParentReader.GetDirectTarget(prefixByte) == target.Offset)
                            {
                                long targetOffset = prefixByte < selectedRightPrefixByte
                                    ? target.Offset
                                    : rightAppend.Extent.Offset;
                                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
                            }
                        }

                        DiscardScalar8Scalar8MutableBatchShelfBytes(target.Offset);
                        kernel.StageWriteAt(target.Offset, leftShelfBytes);
                        kernel.StageWriteAt(rightAppend.Extent.Offset, rightShelfBytes);
                        InvalidateRouterReadCacheForRouterRewrite(pathTarget.ParentRouterOffset);
                        kernel.StageWriteAt(pathTarget.ParentRouterOffset, updatedRouterBytes);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        result = new Scalar8Scalar8EncodedInsertResult(
                            Scalar8Scalar8EncodedInsertOutcome.Inserted,
                            CreatedInitialShelfRoute: false,
                            RouteCreateCommit: default,
                            InsertCommit: telemetry)
                        {
                            StructuralKind = Scalar8Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                            PrimaryOffset = pathTarget.ParentRouterOffset,
                            LeftShelfOffset = target.Offset,
                            RightShelfOffset = rightAppend.Extent.Offset
                        };
                        _ = allowDuplicateKeys;
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrowed queued-writer duplicate-key overflow path for a full ordinary `SS8-8` shelf.<br/>
    /// The accepted shape is intentionally narrow: the route must currently resolve to a valid full non-duplicate shelf, every item in that shelf must have <paramref name="encodedKey"/>, and duplicate keys must be allowed.<br/>
    /// When those preconditions hold, the existing duplicate-key route deepening and terminal-root conversion logic runs under the target index topology gate and serialized storage-publication boundary, without entering the session-wide writer-operation fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the routed shelf.<br/></param>
    /// <param name="encodedKey">The encoded duplicate key to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert into the duplicate-key route.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The insert result when the duplicate-key overflow was handled.<br/></param>
    /// <returns>True when the duplicate-key overflow was handled or resolved as a no-op; false when another fallback path is required.<br/></returns>
    internal bool TryInsertScalar8Scalar8QueuedDuplicateKeyOverflow(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        result = default;
        if (!allowDuplicateKeys)
        {
            return false;
        }

        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(
            rootRouterOffset,
            encodedKey,
            maxRouterHops,
            Scalar8Scalar8RouteReadPolicy.Uncached);
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(5, rootRouterOffset, pathTarget.ParentRouterOffset, -1));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar8RoutePathTarget(
                rootRouterOffset,
                encodedKey,
                maxRouterHops,
                Scalar8Scalar8RouteReadPolicy.Uncached);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                return false;
            }

            object shelfOwner = GetScalar8Scalar8ShelfDomainOwner(target.Offset);
            lock (shelfOwner)
            {
            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid ||
                existingReadOnly.IsDuplicateRun ||
                existingReadOnly.ItemCount != profile.MaxItemCount)
            {
                return false;
            }

            for (int i = 0; i < existingReadOnly.ItemCount; i++)
            {
                if (existingReadOnly.ReadKeyAt(i) != encodedKey)
                {
                    return false;
                }

                if (existingReadOnly.ReadIdentityAt(i) == encodedIdentity)
                {
                    result = new Scalar8Scalar8EncodedInsertResult(
                        Scalar8Scalar8EncodedInsertOutcome.AlreadyPresent,
                        CreatedInitialShelfRoute: false,
                        RouteCreateCommit: default,
                        InsertCommit: default)
                    {
                        StructuralKind = Scalar8Scalar8RoutedInsertKind.NoOp,
                        PrimaryOffset = target.Offset,
                        LeftShelfOffset = 0,
                        RightShelfOffset = 0
                    };
                    return true;
                }
            }

                lock (writePublicationSync)
                {
                    Scalar8Scalar8RoutedInsertResult routedResult = InsertWalkedRoutedScalar8Scalar8(
                        rootRouterOffset,
                        profile,
                        encodedKey,
                        encodedIdentity,
                        allowDuplicateKeys,
                        maxRouterHops,
                        Scalar8Scalar8RouteReadPolicy.Uncached,
                        retryUnsetRouteChanges: false);
                    result = new Scalar8Scalar8EncodedInsertResult(
                        MapScalar8Scalar8InsertOutcome(routedResult.InsertResult),
                        CreatedInitialShelfRoute: false,
                        RouteCreateCommit: default,
                        InsertCommit: routedResult.Commit)
                    {
                        StructuralKind = routedResult.Kind,
                        PrimaryOffset = routedResult.PrimaryOffset,
                        LeftShelfOffset = routedResult.LeftShelfOffset,
                        RightShelfOffset = routedResult.RightShelfOffset
                    };
                    return true;
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrowed queued-writer terminal-identity overflow path for an exact-key `SS8-8` terminal root.<br/>
    /// The supported case is a route that already resolves to a terminal identity root whose stored key exactly matches <paramref name="encodedKey"/>; append/rewrite work for the terminal identity shelf chain is then published under the target index topology gate and serialized storage-publication boundary.<br/>
    /// Mismatched terminal roots, non-terminal routes, and broader route repair return false so the caller can use another specialized fallback or the broad topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the terminal identity shelves.<br/></param>
    /// <param name="encodedKey">The encoded key whose terminal root should receive the identity.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert into the terminal identity route.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The insert result when the terminal identity route was handled.<br/></param>
    /// <returns>True when the exact-key terminal identity route was handled or resolved as a no-op; false when another fallback path is required.<br/></returns>
    internal bool TryInsertScalar8Scalar8QueuedTerminalIdentityOverflow(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        result = default;
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(
            rootRouterOffset,
            encodedKey,
            maxRouterHops,
            Scalar8Scalar8RouteReadPolicy.Uncached);
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(6, rootRouterOffset, pathTarget.Target.Offset, 0));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar8RoutePathTarget(
                rootRouterOffset,
                encodedKey,
                maxRouterHops,
                Scalar8Scalar8RouteReadPolicy.Uncached);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                return false;
            }

            Span<byte> expectedKeyBytes = stackalloc byte[Scalar8Scalar8Layout.KeySize];
            BinaryPrimitives.WriteUInt64BigEndian(expectedKeyBytes, encodedKey);
            byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
            if (!IsTerminalIdentityRootForKey(rootBytes, expectedKeyBytes, out _))
            {
                return false;
            }

                lock (writePublicationSync)
                {
                    Scalar8Scalar8RoutedInsertResult routedResult = InsertIntoScalar8Scalar8TerminalIdentityRoute(
                        target.Offset,
                        profile,
                        encodedKey,
                        encodedIdentity,
                        allowDuplicateKeys);
                    result = new Scalar8Scalar8EncodedInsertResult(
                        MapScalar8Scalar8InsertOutcome(routedResult.InsertResult),
                        CreatedInitialShelfRoute: false,
                        RouteCreateCommit: default,
                        InsertCommit: routedResult.Commit)
                    {
                        StructuralKind = routedResult.Kind,
                        PrimaryOffset = routedResult.PrimaryOffset,
                        LeftShelfOffset = routedResult.LeftShelfOffset,
                        RightShelfOffset = routedResult.RightShelfOffset
                    };
                    return true;
                }
        }
    }

    /// <summary>
    /// Attempts the narrowed queued-writer duplicate-run chain path for an existing `SS8-8` duplicate-run shelf.<br/>
    /// The supported case is a route that already resolves to a duplicate-run shelf whose stored key matches <paramref name="encodedKey"/>; linked-shelf append or duplicate-run rewrite work is then published under the target index topology gate and serialized storage-publication boundary.<br/>
    /// Ordinary shelves, nonmatching duplicate-run shelves, and broader route repair return false so the caller can use another specialized fallback or the broad topology fallback.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the duplicate-run shelves.<br/></param>
    /// <param name="encodedKey">The encoded duplicate-run key to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert into the duplicate-run route.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="maxRouterHops">The maximum route depth to walk.<br/></param>
    /// <param name="result">The insert result when the duplicate-run route was handled.<br/></param>
    /// <returns>True when the matching duplicate-run route was handled or resolved as a no-op; false when another fallback path is required.<br/></returns>
    internal bool TryInsertScalar8Scalar8QueuedDuplicateRunChain(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        out Scalar8Scalar8EncodedInsertResult result)
    {
        result = default;
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(
            rootRouterOffset,
            encodedKey,
            maxRouterHops,
            Scalar8Scalar8RouteReadPolicy.Uncached);
        object topologyOwner = GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(7, rootRouterOffset, pathTarget.Target.Offset, 0));
        lock (topologyOwner)
        {
            pathTarget = WalkScalar8Scalar8RoutePathTarget(
                rootRouterOffset,
                encodedKey,
                maxRouterHops,
                Scalar8Scalar8RouteReadPolicy.Uncached);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                return false;
            }

            byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(target.Offset, existingShelfBytes);
            Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelfBytes, profile);
            if (!existingReadOnly.IsValid ||
                !existingReadOnly.IsDuplicateRun ||
                existingReadOnly.ItemCount == 0 ||
                existingReadOnly.ReadKeyAt(0) != encodedKey)
            {
                return false;
            }

                lock (writePublicationSync)
                {
                    Scalar8Scalar8RoutedInsertResult routedResult = InsertIntoScalar8Scalar8DuplicateRun(
                        target.Offset,
                        profile,
                        encodedKey,
                        encodedIdentity,
                        allowDuplicateKeys);
                    result = new Scalar8Scalar8EncodedInsertResult(
                        MapScalar8Scalar8InsertOutcome(routedResult.InsertResult),
                        CreatedInitialShelfRoute: false,
                        RouteCreateCommit: default,
                        InsertCommit: routedResult.Commit)
                    {
                        StructuralKind = routedResult.Kind,
                        PrimaryOffset = routedResult.PrimaryOffset,
                        LeftShelfOffset = routedResult.LeftShelfOffset,
                        RightShelfOffset = routedResult.RightShelfOffset
                    };
                    return true;
                }
        }
    }

    /// <summary>
    /// Gets the topology coordination gate for one routed `SS8-8` index root.<br/>
    /// Gates are created lazily because catalogs can contain many indexes, while only concurrently written roots need coordination objects.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `SS8-8` index.<br/></param>
    /// <returns>The reader/writer gate for the supplied root router offset.</returns>
    private ReaderWriterLockSlim GetScalar8Scalar8TopologyMutationSync(long rootRouterOffset)
    {
        lock (scalar8Scalar8TopologyGateSync)
        {
            if (!scalar8Scalar8TopologyMutationSyncByRoot.TryGetValue(rootRouterOffset, out ReaderWriterLockSlim? topologySync))
            {
                topologySync = new ReaderWriterLockSlim(LockRecursionPolicy.SupportsRecursion);
                scalar8Scalar8TopologyMutationSyncByRoot.Add(rootRouterOffset, topologySync);
            }

            return topologySync;
        }
    }

    /// <summary>
    /// Gets the narrow queued-topology owner for one `SS8-8` mutation domain.<br/>
    /// The owner is intentionally separate from the root topology reader/writer gate: callers use this object to keep same-shelf, same-root-prefix, or same-parent-router publishers from racing while unrelated publishers can still do their expensive preparation work concurrently.<br/>
    /// The existing root topology gate remains the short publication barrier that protects already-staged writer contexts from observing a router rewrite in the middle of their route walk.<br/>
    /// </summary>
    /// <param name="key">The concrete `SS8-8` topology domain that must not overlap with another publisher.<br/></param>
    /// <returns>The lock object for the supplied topology owner key.</returns>
    private object GetScalar8Scalar8TopologyOwner(Scalar8Scalar8TopologyOwnerKey key)
    {
        lock (scalar8Scalar8TopologyOwnerGateSync)
        {
            if (!scalar8Scalar8TopologyOwners.TryGetValue(key, out object? sync))
            {
                sync = new object();
                scalar8Scalar8TopologyOwners.Add(key, sync);
            }

            return sync;
        }
    }

    /// <summary>
    /// Gets the narrow topology owner for a primitive non-`SS8-8` mutation domain.<br/>
    /// The owner key identifies the physical shape, mutation kind, root router, and the smallest known shared topology object such as a cold root prefix, source shelf, or parent router.<br/>
    /// Callers use this monitor to serialize only writers that may observe or mutate the same physical topology while unrelated topology planners can proceed concurrently until the global storage publication boundary.<br/>
    /// </summary>
    /// <param name="key">The primitive topology domain that must not overlap with another publisher.<br/></param>
    /// <returns>The monitor object for the supplied topology owner key.</returns>
    private object GetPrimitiveTopologyOwner(PrimitiveTopologyOwnerKey key)
    {
        lock (primitiveTopologyOwnerGateSync)
        {
            if (!primitiveTopologyOwners.TryGetValue(key, out object? sync))
            {
                sync = new object();
                primitiveTopologyOwners.Add(key, sync);
            }

            return sync;
        }
    }

    /// <summary>
    /// Reports that a primitive topology publisher has entered a narrow owner domain.<br/>
    /// This callback is reserved for deterministic validation probes that need to hold one owner while an unrelated owner admits another writer.<br/>
    /// Production leaves the callback null, so normal execution pays only one delegate read after the owner monitor has been acquired.<br/>
    /// </summary>
    /// <param name="key">The primitive topology owner key that was entered.<br/></param>
    private static void ReportPrimitiveTopologyOwnerEnteredForValidation(PrimitiveTopologyOwnerKey key)
    {
        PrimitiveTopologyOwnerEnteredForValidation?.Invoke(key.Shape, key.Kind, key.RootRouterOffset, key.OwnerOffset, key.PrefixByte);
    }

    /// <summary>
    /// Gets the primitive `SS8-8` shelf-domain owner for one physical shelf offset.<br/>
    /// This owner is shared by shelf-local writer contexts and topology publishers that split or transform the same source shelf, making the physical shelf the synchronization boundary instead of the index root.<br/>
    /// </summary>
    /// <param name="shelfOffset">The physical shelf offset whose bytes or type may be changed.<br/></param>
    /// <returns>The owner object for the shelf domain.</returns>
    private object GetScalar8Scalar8ShelfDomainOwner(long shelfOffset)
    {
        return GetScalar8Scalar8TopologyOwner(new Scalar8Scalar8TopologyOwnerKey(20, 0, shelfOffset, -1));
    }

    /// <summary>
    /// Attempts to claim one primitive `SS8-8` shelf domain for a writer context.<br/>
    /// Same-shelf overlap returns through the existing retryable writer-context exception, while different shelves acquire independent monitor domains.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that will hold the shelf domain until publish or abort.<br/></param>
    /// <param name="shelfOffset">The physical shelf offset to claim.<br/></param>
    private void ClaimScalar8Scalar8ShelfDomainForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        if (writeContext.Scalar8Scalar8ShelfDomainLocks.ContainsKey(shelfOffset))
        {
            return;
        }

        object domain = GetScalar8Scalar8ShelfDomainOwner(shelfOffset);
        if (!Monitor.TryEnter(domain))
        {
            throw new LibraDexWriteContextShelfOwnershipException(shelfOffset);
        }

        writeContext.Scalar8Scalar8ShelfDomainLocks.Add(shelfOffset, domain);
    }

    /// <summary>
    /// Releases every primitive `SS8-8` shelf-domain monitor held by a writer context.<br/>
    /// This is paired with context publish/abort so staged shelf bytes and their physical ownership have the same lifetime.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf-domain monitors should be released.<br/></param>
    private static void ReleaseScalar8Scalar8ShelfDomainsForWriteContext(LibraDexWriteContext writeContext)
    {
        foreach (object domain in writeContext.Scalar8Scalar8ShelfDomainLocks.Values)
        {
            Monitor.Exit(domain);
        }

        writeContext.Scalar8Scalar8ShelfDomainLocks.Clear();
    }

    /// <summary>
    /// Releases the per-root topology read gate held for one `SS8-8` writer context.<br/>
    /// Publication and abort call this only after shelf-domain ownership has been released, allowing a waiting broad topology fallback to observe the fully published or fully abandoned context state.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose topology read gate should be released.<br/></param>
    private static void ReleaseScalar8Scalar8TopologyReadForWriteContext(LibraDexWriteContext writeContext)
    {
        ReaderWriterLockSlim? topologySync = writeContext.Scalar8Scalar8TopologyReadSync;
        if (topologySync is null)
        {
            return;
        }

        writeContext.Scalar8Scalar8TopologyReadSync = null;
        topologySync.ExitReadLock();
    }

    /// <summary>
    /// Releases one primitive `SS8-8` shelf-domain monitor held by a writer context.<br/>
    /// This is used only when secondary bookkeeping fails after the primitive domain was acquired.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that may hold the shelf-domain monitor.<br/></param>
    /// <param name="shelfOffset">The physical shelf offset whose domain should be released.<br/></param>
    private static void ReleaseScalar8Scalar8ShelfDomainForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        if (writeContext.Scalar8Scalar8ShelfDomainLocks.Remove(shelfOffset, out object? domain))
        {
            Monitor.Exit(domain);
        }
    }

    /// <summary>
    /// Reports that a queued `SS8-8` topology publisher has entered a narrow owner domain.<br/>
    /// The callback is only for deterministic harness probes that need to hold one owner while another writer attempts admission through a different owner.<br/>
    /// Normal runtime leaves the callback null, so the production path does not allocate and performs only one delegate read at the validation point.<br/>
    /// </summary>
    /// <param name="key">The topology owner key that was entered.<br/></param>
    private static void ReportScalar8Scalar8TopologyOwnerEnteredForValidation(Scalar8Scalar8TopologyOwnerKey key)
    {
        Scalar8Scalar8TopologyOwnerEnteredForValidation?.Invoke(key.Kind, key.RootRouterOffset, key.OwnerOffset, key.PrefixByte);
    }

