    /// <summary>
    /// Publishes all `SS8-8` shelf changes staged in a writer-local context through the serialized session publication seam.<br/>
    /// This keeps staging independent while preserving one `DataKernel` publication at a time.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context to publish.<br/></param>
    /// <returns>The DataKernel commit telemetry for the publication.<br/></returns>
    internal DataKernelCommitTelemetry PublishScalar8Scalar8WriteContext(LibraDexWriteContext writeContext)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        lock (writePublicationSync)
        {
            DataKernelCommitTelemetry telemetry;
            kernel.EnterExclusiveStoragePublication();
            try
            {
                ValidateScalar8Scalar8RouteClaimsForWriteContext(writeContext);
                foreach (long shelfOffset in writeContext.Scalar8Scalar8DirtyShelfOffsets)
                {
                    byte[] dirtyShelfBytes = writeContext.Scalar8Scalar8MutableBatchShelfBytes[shelfOffset];
                    Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Create(dirtyShelfBytes.Length);
                    Scalar8Scalar8 shelf = new(dirtyShelfBytes, profile);
                    _ = shelf.NormalizeDeletedSlotsForPublication();
                    RewriteBatchShelfBytes(shelfOffset, dirtyShelfBytes.AsSpan(0, profile.ShelfExtentSize));
                    scalar8Scalar8CleanShelfCache.Remove(shelfOffset);
                }

                foreach (KeyValuePair<long, byte[]> dirtyShelf in writeContext.TerminalIdentity8MutableShelfBytes)
                {
                    ValidateTerminalIdentity8Shelf(dirtyShelf.Value, dirtyShelf.Value.Length);
                    RewriteBatchShelfBytes(dirtyShelf.Key, dirtyShelf.Value);
                    terminalIdentity8ShelfReadCache.TryRemove(dirtyShelf.Key, out _);
                }

                telemetry = kernel.Commit();
            }
            finally
            {
                kernel.ExitExclusiveStoragePublication();
            }

            ReleaseScalar8Scalar8ShelfOwnersForWriteContext(writeContext);
            ReleaseTerminalIdentity8ShelfOwnersForWriteContext(writeContext);
            ReleaseScalar8Scalar8TopologyReadForWriteContext(writeContext);
            writeContext.Scalar8Scalar8MutableBatchShelfBytes.Clear();
            writeContext.Scalar8Scalar8DirtyShelfOffsets.Clear();
            writeContext.Scalar8Scalar8RouteClaims.Clear();
            writeContext.TerminalIdentity8MutableShelfBytes.Clear();
            return telemetry;
        }
    }

    /// <summary>
    /// Abandons all `SS8-8` shelf changes staged in a writer-local context and releases its shelf ownership claims.<br/>
    /// The method only clears context-local state because these staged shelves do not enter `DataKernel` until publication.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context to abandon.<br/></param>
    internal void AbortScalar8Scalar8WriteContext(LibraDexWriteContext writeContext)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        ReleaseScalar8Scalar8ShelfOwnersForWriteContext(writeContext);
        ReleaseTerminalIdentity8ShelfOwnersForWriteContext(writeContext);
        ReleaseScalar8Scalar8TopologyReadForWriteContext(writeContext);
        writeContext.Scalar8Scalar8MutableBatchShelfBytes.Clear();
        writeContext.Scalar8Scalar8DirtyShelfOffsets.Clear();
        writeContext.Scalar8Scalar8RouteClaims.Clear();
        writeContext.TerminalIdentity8MutableShelfBytes.Clear();
    }

    /// <summary>
    /// Publishes all `SS16-8` shelf changes staged in a writer-local context through the serialized session publication seam.<br/>
