    /// <summary>
    /// Publishes all `FSN-8` shelf changes staged in a writer-local context through the serialized session publication seam.<br/>
    /// Ordinary shelf-local fixed-N mutations publish only the dirty shelf bytes; public counts read shelf metadata directly, so no index-directory count rewrite is needed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context to publish.<br/></param>
    /// <param name="profile">The fixed-N profile that supplies the staged shelf extent size.<br/></param>
    /// <returns>The DataKernel commit telemetry for the publication.<br/></returns>
    internal DataKernelCommitTelemetry PublishFixedNScalar8WriteContext(
        LibraDexWriteContext writeContext,
        FixedNScalar8Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        lock (writePublicationSync)
        {
            try
            {
                DataKernelCommitTelemetry telemetry;
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    ValidateFixedNScalar8RouteClaimsForWriteContext(writeContext);
                    foreach (KeyValuePair<long, byte[]> dirtyShelf in writeContext.FixedNScalar8MutableBatchShelfBytes)
                    {
                        RewriteBatchShelfBytes(dirtyShelf.Key, dirtyShelf.Value.AsSpan(0, profile.ShelfExtentSize));
                    }

                    telemetry = CommitWithoutInvalidatingRouterReadCache();
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }

                return telemetry;
            }
            finally
            {
                ReleaseFixedNScalar8ShelfOwnersForWriteContext(writeContext);
                ReleaseFixedNScalar8ShelfBytesForWriteContext(writeContext);
                writeContext.FixedNScalar8RouteClaims.Clear();
            }
        }
    }

