    /// <summary>
    /// Enters the raw storage-publication gate for deterministic concurrency validation.<br/>
    /// This intentionally bypasses `SS8-8` topology gates so the harness can prove writer-context staging is no longer blocked by the broader session writer-operation gate during ordinary storage publication.<br/>
    /// </summary>
    internal void EnterStoragePublicationForValidation()
    {
        kernel.EnterExclusiveStoragePublication();
    }

    /// <summary>
    /// Leaves the raw storage-publication gate entered by <see cref="EnterStoragePublicationForValidation"/>.<br/>
    /// Harness callers must pair this in a finally block so blocked raw readers or publishers are released after the validation window.<br/>
    /// </summary>
    internal void ExitStoragePublicationForValidation()
    {
        kernel.ExitExclusiveStoragePublication();
    }

    /// <summary>
    /// Claims one `SS8-8` shelf offset for a writer context.<br/>
    /// The claim is the first conflict boundary for the writer-local staging refactor: different shelves can stage independently, while same-shelf writes fail deterministically.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the shelf.<br/></param>
    /// <param name="shelfOffset">The shelf offset to claim.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when another writer context already owns the shelf.<br/></exception>
    private void ClaimScalar8Scalar8ShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        ClaimScalar8Scalar8ShelfDomainForWriteContext(writeContext, shelfOffset);
        try
        {
            lock (writeContextAdmissionSync)
            {
                if (scalar8Scalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
                {
                    if (ReferenceEquals(owner, writeContext))
                    {
                        return;
                    }

                    throw new LibraDexWriteContextShelfOwnershipException(shelfOffset);
                }

                scalar8Scalar8WriterShelfOwners.Add(shelfOffset, writeContext);
            }
        }
        catch
        {
            ReleaseScalar8Scalar8ShelfDomainForWriteContext(writeContext, shelfOffset);
            throw;
        }
    }

    /// <summary>
    /// Releases all `SS8-8` shelf ownership claims held by a writer context.<br/>
    /// This is called only after context publication or abort has consumed the staged shelf images.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf claims should be released.<br/></param>
    private void ReleaseScalar8Scalar8ShelfOwnersForWriteContext(LibraDexWriteContext writeContext)
    {
        lock (writeContextAdmissionSync)
        {
            foreach (long shelfOffset in writeContext.Scalar8Scalar8MutableBatchShelfBytes.Keys)
            {
                if (scalar8Scalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    scalar8Scalar8WriterShelfOwners.Remove(shelfOffset);
                }
            }

            SignalReleasedWriteContextShelves();
        }

        ReleaseScalar8Scalar8ShelfDomainsForWriteContext(writeContext);
    }

