    /// This is called only after context publication or abort has consumed the staged shelf images.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf claims should be released.<br/></param>
    private void ReleaseFixed32Scalar16ShelfOwnersForWriteContext(LibraDexWriteContext writeContext)
    {
        lock (writeContextAdmissionSync)
        {
            foreach (long shelfOffset in writeContext.Fixed32Scalar16MutableBatchShelfBytes.Keys)
            {
                if (fixed32Scalar16WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    fixed32Scalar16WriterShelfOwners.Remove(shelfOffset);
                }
            }

            SignalReleasedWriteContextShelves();
        }
    }

    /// <summary>
    /// Claims one `FSN-8` shelf offset for a writer context.<br/>
    /// Different shelves can stage independently; same-shelf writers receive a retryable ownership exception.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the shelf.<br/></param>
    /// <param name="shelfOffset">The shelf offset to claim.<br/></param>
    private void ClaimFixedNScalar8ShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        lock (writeContextAdmissionSync)
        {
            if (fixedNScalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
            {
                if (ReferenceEquals(owner, writeContext))
                {
                    return;
                }

                throw new LibraDexWriteContextFixedNScalar8ShelfOwnershipException(shelfOffset);
            }

            fixedNScalar8WriterShelfOwners.Add(shelfOffset, writeContext);
        }
    }

