    /// <summary>
    /// Reads one terminal identity shelf into a writer-local image for an isolated writer context.<br/>
    /// Repeated reads from the same context reuse its staged bytes, allowing multiple appends to the same terminal shelf before publication while still excluding other contexts by ownership.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged terminal shelf bytes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The terminal identity shelf offset to read.<br/></param>
    /// <param name="shelfExtentSize">The fixed extent size of the terminal identity shelf.<br/></param>
    /// <returns>A mutable writer-local terminal identity shelf image.<br/></returns>
    private byte[] ReadTerminalIdentity8ShelfBytesForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int shelfExtentSize)
    {
        if (writeContext.TerminalIdentity8MutableShelfBytes.TryGetValue(shelfOffset, out byte[]? stagedShelfBytes))
        {
            if (stagedShelfBytes.Length != shelfExtentSize)
            {
                throw new InvalidDataException("The staged terminal identity shelf extent does not match the requested extent.");
            }

            return stagedShelfBytes;
        }

        byte[] shelfBytes = new byte[shelfExtentSize];
        ReadTerminalIdentity8ShelfBytesCached(shelfOffset, shelfExtentSize).AsSpan(0, shelfExtentSize).CopyTo(shelfBytes);
        ValidateTerminalIdentity8Shelf(shelfBytes, shelfExtentSize);
        return shelfBytes;
    }

    /// <summary>
    /// Stages one terminal identity shelf rewrite for a writer context and claims exclusive ownership of that shelf offset.<br/>
    /// The staged shelf is still private to the context; readers do not observe it until <see cref="PublishScalar8Scalar8WriteContext"/> flushes the context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context receiving the dirty shelf image.<br/></param>
    /// <param name="shelfOffset">The terminal identity shelf offset to rewrite at publish time.<br/></param>
    /// <param name="shelfExtentSize">The fixed extent size of the terminal identity shelf.<br/></param>
    /// <param name="shelfBytes">The full terminal identity shelf image to publish later.<br/></param>
    private void StageTerminalIdentity8ShelfRewriteForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int shelfExtentSize,
        byte[] shelfBytes)
    {
        if (shelfBytes.Length != shelfExtentSize)
        {
            throw new InvalidDataException("The terminal identity writer-context shelf extent is invalid.");
        }

        ValidateTerminalIdentity8Shelf(shelfBytes, shelfExtentSize);
        ClaimTerminalIdentity8ShelfForWriteContext(writeContext, shelfOffset);
        writeContext.TerminalIdentity8MutableShelfBytes[shelfOffset] = shelfBytes;
    }

    /// <summary>
    /// Claims one terminal identity shelf offset for a writer context.<br/>
    /// Different terminal shelves may stage independently, while same-terminal-shelf writes fail deterministically and can be retried by queued facades.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the terminal identity shelf.<br/></param>
    /// <param name="shelfOffset">The terminal identity shelf offset to claim.<br/></param>
    private void ClaimTerminalIdentity8ShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        lock (writeContextAdmissionSync)
        {
            if (terminalIdentity8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
            {
                if (ReferenceEquals(owner, writeContext))
                {
                    return;
                }

                throw new LibraDexWriteContextTerminalIdentityShelfOwnershipException(shelfOffset);
            }

            terminalIdentity8WriterShelfOwners.Add(shelfOffset, writeContext);
        }
    }

    /// <summary>
    /// Releases all terminal identity shelf ownership claims held by a writer context.<br/>
    /// This is called only after context publication or abort has consumed the staged terminal shelf images.<br/>
    /// </summary>
