    /// <summary>
    /// Reads one ordinary `VS8` shelf into a writer-local mutable view and claims the shelf for that writer context.<br/>
    /// Repeated reads by the same context reuse the already decoded mutable shelf; another context targeting the same shelf receives a retryable ownership exception.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged shelf changes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The ordinary `VS8` shelf offset to read.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <returns>A writer-local mutable shelf view.</returns>
    /// <exception cref="InvalidDataException">Thrown when the loaded shelf bytes fail `VS8` validation.<br/></exception>
    internal VarKeyScalar8MutableShelf ReadVarKeyScalar8MutableShelfForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int maxKeyLength)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.VarKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? existing))
        {
            return existing;
        }

        ClaimVarKeyScalar8ShelfForWriteContext(writeContext, shelfOffset);
        byte[] header = new byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The writer-context routed VS8 shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
        VarKeyScalar8Profile profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        byte[] shelfBytes = new byte[shelfExtentSize];
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes);
        if (!VarKeyScalar8MutableShelf.TryCreate(shelfBytes, profile, ownsBytes: false, rentSidecars: false, out VarKeyScalar8MutableShelf shelf))
        {
            throw new InvalidDataException("The writer-context routed VS8 mutable shelf bytes are invalid.");
        }

        writeContext.VarKeyScalar8MutableBatchShelves.Add(shelfOffset, shelf);
        return shelf;
    }

    /// <summary>
    /// Records the committed router slot that selected one `VS8` shelf or terminal root for writer-context mutation.<br/>
    /// Publication revalidates this claim so a warmed shelf writer cannot overwrite stale bytes after another writer grows, splits, or relinks the route.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged target.<br/></param>
    /// <param name="pathTarget">The route path evidence captured from committed state.<br/></param>
    private static void RecordVarKeyScalar8RouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        VarKeyScalar8RoutePathTarget pathTarget)
    {
        if (pathTarget.Target.Kind is VarKeyScalar8RouteTargetKind.Shelf or VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            RecordVarKeyScalar8RouteClaimForWriteContext(
                writeContext,
                pathTarget.ParentRouterOffset,
                pathTarget.RouteIndex,
                pathTarget.Target.Offset);
        }
    }

    /// <summary>
    /// Records one committed `VS8` parent-router route slot for writer-context mutation.<br/>
    /// Range traversal uses this overload because it discovers child targets while walking router pages rather than through a full path-target wrapper.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged target.<br/></param>
    /// <param name="parentRouterOffset">The parent router that selected the target.<br/></param>
    /// <param name="routeIndex">The route slot inside the parent router.</param>
    /// <param name="targetOffset">The expected routed target offset.</param>
    private static void RecordVarKeyScalar8RouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        int routeIndex,
        long targetOffset)
    {
        writeContext.VarKeyScalar8RouteClaims[targetOffset] = new VarKeyScalar8RouteClaim(
            parentRouterOffset,
            routeIndex,
            targetOffset);
    }

    /// <summary>
    /// Validates every committed `VS8` route slot used by a writer-context shelf or terminal-root rewrite.<br/>
    /// If another writer changed the selecting route before publication, this writer fails before any staged shelf bytes are flushed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose route claims should still match committed state.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when a claimed target is no longer selected by the captured parent route.<br/></exception>
    private void ValidateVarKeyScalar8RouteClaimsForWriteContext(LibraDexWriteContext writeContext)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        foreach (VarKeyScalar8RouteClaim claim in writeContext.VarKeyScalar8RouteClaims.Values)
        {
            kernel.Read(claim.ParentRouterOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid ||
                claim.RouteIndex < 0 ||
                claim.RouteIndex >= reader.RouteCount ||
                reader.GetRouteTargetAt(claim.RouteIndex) != claim.ExpectedTargetOffset ||
                !IsVarKeyScalar8TargetForRouteClaim(claim.ExpectedTargetOffset))
            {
                throw new InvalidOperationException("The VS8 writer-context route claim no longer matches committed router state.");
            }
        }
    }

    /// <summary>
    /// Reads the physical target magic for a `VS8` route claim without consulting route-target caches.<br/>
    /// Ordinary shelves and terminal identity roots are valid writer-context targets; routers or unrecognized shapes mean the stale writer must retry through topology handling.<br/>
    /// </summary>
    /// <param name="targetOffset">The claimed routed `VS8` target offset.<br/></param>
    /// <returns><see langword="true"/> when the offset still contains a `VS8` shelf or terminal identity root; otherwise, <see langword="false"/>.</returns>
    private bool IsVarKeyScalar8TargetForRouteClaim(long targetOffset)
    {
        if (targetOffset <= 0)
        {
            return false;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        return magic == VarKeyScalar8Layout.Magic ||
            magic == TerminalIdentityRootLayout.Magic;
    }

