    /// <summary>
    /// Records one committed `SV16` parent-router route slot for writer-context mutation.<br/>
    /// Range traversal uses this overload because it discovers child targets while walking router pages rather than through a full path-target wrapper.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns the staged shelf.<br/></param>
    /// <param name="parentRouterOffset">The parent router that selected the shelf.<br/></param>
    /// <param name="routeIndex">The route slot inside the parent router.</param>
    /// <param name="targetOffset">The expected routed shelf offset.</param>
    private static void RecordScalar16VarIdentityRouteClaimForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        int routeIndex,
        long targetOffset)
    {
        writeContext.Scalar16VarIdentityRouteClaims[targetOffset] = new Scalar16VarIdentityRouteClaim(
            parentRouterOffset,
            routeIndex,
            targetOffset);
    }

    /// <summary>
    /// Validates every committed `SV16` route slot used by a writer-context shelf rewrite.<br/>
    /// If another writer changed the selecting route before publication, this writer fails before any staged shelf bytes are flushed.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose route claims should still match committed state.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when a claimed shelf is no longer selected by the captured parent route.<br/></exception>
    private void ValidateScalar16VarIdentityRouteClaimsForWriteContext(LibraDexWriteContext writeContext)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        foreach (Scalar16VarIdentityRouteClaim claim in writeContext.Scalar16VarIdentityRouteClaims.Values)
        {
            kernel.Read(claim.ParentRouterOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid ||
                claim.RouteIndex < 0 ||
                claim.RouteIndex >= reader.RouteCount ||
                reader.GetRouteTargetAt(claim.RouteIndex) != claim.ExpectedTargetOffset ||
                !IsScalar16VarIdentityShelfForRouteClaim(claim.ExpectedTargetOffset))
            {
                throw new InvalidOperationException("The SV16 writer-context route claim no longer matches committed router state.");
            }
        }
    }

    /// <summary>
    /// Reads the physical target magic for an `SV16` route claim without consulting route-target caches.<br/>
    /// Publish-time validation uses this narrow probe so a same-offset shelf-to-router transform cannot be hidden by an earlier observation.<br/>
    /// </summary>
    /// <param name="targetOffset">The claimed routed shelf offset.<br/></param>
    /// <returns><see langword="true"/> when the offset still contains an `SV16` shelf header; otherwise, <see langword="false"/>.</returns>
    private bool IsScalar16VarIdentityShelfForRouteClaim(long targetOffset)
    {
        if (targetOffset <= 0)
        {
            return false;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        return BinaryPrimitives.ReadUInt32LittleEndian(magicBytes) == Scalar16VarIdentityLayout.Magic;
    }

    /// <summary>
    /// Reads one ordinary `SV8` shelf into a writer-local mutable view and claims the shelf for that writer context.<br/>
    /// Repeated reads by the same context reuse the already decoded mutable shelf; another context targeting the same shelf receives a retryable ownership exception.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged shelf changes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The ordinary `SV8` shelf offset to read.<br/></param>
    /// <param name="maxIdentityLength">The maximum raw identity length accepted by the index profile.<br/></param>
    /// <returns>A writer-local mutable shelf view.</returns>
    /// <exception cref="InvalidDataException">Thrown when the loaded shelf bytes fail `SV8` validation.<br/></exception>
    internal Scalar8VarIdentityMutableShelfView ReadScalar8VarIdentityMutableShelfForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int maxIdentityLength)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.Scalar8VarIdentityMutableBatchShelves.TryGetValue(shelfOffset, out Scalar8VarIdentityMutableShelfView? existing))
        {
            return existing;
        }

        ClaimScalar8VarIdentityShelfForWriteContext(writeContext, shelfOffset);
        Span<byte> header = stackalloc byte[Scalar8VarIdentityLayout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (Scalar8VarIdentityLayout.ReadMagic(header) != Scalar8VarIdentityLayout.Magic ||
            Scalar8VarIdentityLayout.ReadFormatVersion(header) != Scalar8VarIdentityLayout.FormatVersion ||
            Scalar8VarIdentityLayout.ReadHeaderSize(header) != Scalar8VarIdentityLayout.HeaderSize)
        {
            throw new InvalidDataException("The writer-context routed SV8 shelf header is invalid.");
        }

        int shelfExtentSize = Scalar8VarIdentityLayout.ReadShelfExtentSize(header);
        Scalar8VarIdentityProfile profile = Scalar8VarIdentityProfile.Create(shelfExtentSize, maxIdentityLength);
        byte[] shelfBytes = ArrayPool<byte>.Shared.Rent(shelfExtentSize);
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes.AsSpan(0, shelfExtentSize));
        if (!Scalar8VarIdentityMutableShelfView.TryCreatePooled(shelfBytes, profile, pooledBytes: true, out Scalar8VarIdentityMutableShelfView shelf))
        {
            ArrayPool<byte>.Shared.Return(shelfBytes, clearArray: true);
            throw new InvalidDataException("The writer-context routed SV8 mutable shelf bytes are invalid.");
        }

        writeContext.Scalar8VarIdentityMutableBatchShelves.Add(shelfOffset, shelf);
        return shelf;
    }

    /// <summary>
    /// Reads one ordinary `SV16` shelf into a writer-local mutable view and claims the shelf for that writer context.<br/>
    /// Repeated reads by the same context reuse the already decoded mutable shelf; another context targeting the same shelf receives a retryable ownership exception.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged shelf changes until publish or abort.<br/></param>
    /// <param name="shelfOffset">The ordinary `SV16` shelf offset to read.<br/></param>
    /// <param name="maxIdentityLength">The maximum raw identity length accepted by the index profile.<br/></param>
    /// <returns>A writer-local mutable shelf view.</returns>
    /// <exception cref="InvalidDataException">Thrown when the loaded shelf bytes fail `SV16` validation.<br/></exception>
    internal Scalar16VarIdentityMutableShelfView ReadScalar16VarIdentityMutableShelfForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int maxIdentityLength)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.Scalar16VarIdentityMutableBatchShelves.TryGetValue(shelfOffset, out Scalar16VarIdentityMutableShelfView? existing))
        {
            return existing;
        }

        ClaimScalar16VarIdentityShelfForWriteContext(writeContext, shelfOffset);
        Span<byte> header = stackalloc byte[Scalar16VarIdentityLayout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (Scalar16VarIdentityLayout.ReadMagic(header) != Scalar16VarIdentityLayout.Magic ||
            Scalar16VarIdentityLayout.ReadFormatVersion(header) != Scalar16VarIdentityLayout.FormatVersion ||
            Scalar16VarIdentityLayout.ReadHeaderSize(header) != Scalar16VarIdentityLayout.HeaderSize)
        {
            throw new InvalidDataException("The writer-context routed SV16 shelf header is invalid.");
        }

        int shelfExtentSize = Scalar16VarIdentityLayout.ReadShelfExtentSize(header);
        Scalar16VarIdentityProfile profile = Scalar16VarIdentityProfile.Create(shelfExtentSize, maxIdentityLength);
        byte[] shelfBytes = new byte[shelfExtentSize];
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes);
        if (!Scalar16VarIdentityMutableShelfView.TryCreate(shelfBytes, profile, out Scalar16VarIdentityMutableShelfView shelf))
        {
            throw new InvalidDataException("The writer-context routed SV16 mutable shelf bytes are invalid.");
        }

        writeContext.Scalar16VarIdentityMutableBatchShelves.Add(shelfOffset, shelf);
        return shelf;
    }

    /// <summary>
    /// Reads one raw `VS8` shelf image for writer-context mutation when the ordinary mutable sidecar cannot decode the shelf layout.<br/>
    /// Duplicate-run shelves use this path because their compact identity-list layout has no ordinary key/identity slot sidecar.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that will own the raw shelf image.<br/></param>
    /// <param name="shelfOffset">The shelf offset to read and claim.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="profile">Receives the decoded `VS8` shelf profile.<br/></param>
    /// <returns>A writer-local raw shelf byte image.</returns>
    private byte[] ReadVarKeyScalar8RawShelfBytesForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        int maxKeyLength,
        out VarKeyScalar8Profile profile)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (writeContext.VarKeyScalar8RawMutableShelfBytes.TryGetValue(shelfOffset, out byte[]? existing))
        {
            profile = VarKeyScalar8Profile.Create(VarKeyScalar8Layout.ReadShelfExtentSize(existing), maxKeyLength);
            return existing;
        }

        ClaimVarKeyScalar8ShelfForWriteContext(writeContext, shelfOffset);
        byte[] shelfBytes = ReadVarKeyScalar8ShelfBytes(shelfOffset, maxKeyLength, out profile);
        writeContext.VarKeyScalar8RawMutableShelfBytes.Add(shelfOffset, shelfBytes);
        return shelfBytes;
    }

    /// <summary>
    /// Stages one raw `VS8` shelf image for writer-context publication.<br/>
    /// The caller must already have validated the raw shelf layout and claimed the shelf through <see cref="ReadVarKeyScalar8RawShelfBytesForWriteContext"/>.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context receiving the raw shelf image.<br/></param>
    /// <param name="shelfOffset">The shelf offset to rewrite at publication time.<br/></param>
    /// <param name="shelfBytes">The full raw shelf image to publish later.<br/></param>
    private static void StageVarKeyScalar8RawShelfRewriteForWriteContext(
        LibraDexWriteContext writeContext,
        long shelfOffset,
        byte[] shelfBytes)
    {
        writeContext.VarKeyScalar8RawMutableShelfBytes[shelfOffset] = shelfBytes;
    }

    /// <summary>
    /// Publishes all dirty ordinary and terminal `VS8` shelf changes staged in a writer-local context through the serialized DataKernel publication seam.<br/>
    /// The method normalizes tombstones and repack policy exactly like the durability-batch flusher, then releases shelf ownership claims and mutable sidecars.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context to publish.<br/></param>
    /// <returns>The DataKernel commit telemetry for the publication.<br/></returns>
    internal DataKernelCommitTelemetry PublishVarKeyScalar8WriteContext(LibraDexWriteContext writeContext)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        lock (writePublicationSync)
        {
            DataKernelCommitTelemetry telemetry;
            kernel.EnterExclusiveStoragePublication();
            try
            {
                ValidateVarKeyScalar8RouteClaimsForWriteContext(writeContext);
                foreach (KeyValuePair<long, VarKeyScalar8MutableShelf> mutableShelf in writeContext.VarKeyScalar8MutableBatchShelves)
                {
                    if (!mutableShelf.Value.IsDirty)
                    {
                        continue;
                    }

                    int shelfExtentSize = mutableShelf.Value.Profile.ShelfExtentSize;
                    PrepareVarKeyScalar8ShelfForPublication(mutableShelf.Value);
                    RewriteBatchShelfBytes(mutableShelf.Key, mutableShelf.Value.Bytes.AsSpan(0, shelfExtentSize));
                    varKeyScalar8ReadShelfCache.TryRemove(mutableShelf.Key, out _);
                }

                foreach (KeyValuePair<long, byte[]> rawShelf in writeContext.VarKeyScalar8RawMutableShelfBytes)
                {
                    RewriteBatchShelfBytes(rawShelf.Key, rawShelf.Value);
                    varKeyScalar8ReadShelfCache.TryRemove(rawShelf.Key, out _);
                }

                foreach (KeyValuePair<long, byte[]> dirtyShelf in writeContext.TerminalIdentity8MutableShelfBytes)
                {
                    ValidateTerminalIdentity8Shelf(dirtyShelf.Value, dirtyShelf.Value.Length);
                    RewriteBatchShelfBytes(dirtyShelf.Key, dirtyShelf.Value);
                    terminalIdentity8ShelfReadCache.TryRemove(dirtyShelf.Key, out _);
                }

                telemetry = kernel.Commit();
            }
            finally
            {
                kernel.ExitExclusiveStoragePublication();
            }

            ReleaseVarKeyScalar8ShelfOwnersForWriteContext(writeContext);
            ReleaseTerminalIdentity8ShelfOwnersForWriteContext(writeContext);
            ReleaseVarKeyScalar8MutableShelvesForWriteContext(writeContext, clearShelfBytes: true);
            writeContext.VarKeyScalar8RawMutableShelfBytes.Clear();
            writeContext.VarKeyScalar8RouteClaims.Clear();
            writeContext.TerminalIdentity8MutableShelfBytes.Clear();
            return telemetry;
        }
    }

    /// <summary>
    /// Abandons all ordinary and terminal `VS8` shelf changes staged in a writer-local context and releases its shelf ownership claims.<br/>
    /// No staged bytes enter DataKernel until publication, so abort only releases context-local mutable views.<br/>
