    /// <summary>
    /// Claims one ordinary `VS8` shelf offset for a writer context.<br/>
    /// Different shelves may stage independently, while same-shelf writes fail deterministically and can be retried by the caller.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the shelf.<br/></param>
    /// <param name="shelfOffset">The ordinary `VS8` shelf offset to claim.<br/></param>
    private void ClaimVarKeyScalar8ShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        lock (writeContextAdmissionSync)
        {
            if (varKeyScalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
            {
                if (ReferenceEquals(owner, writeContext))
                {
                    return;
                }

                throw new LibraDexWriteContextVarKeyScalar8ShelfOwnershipException(shelfOffset);
            }

            varKeyScalar8WriterShelfOwners.Add(shelfOffset, writeContext);
        }
    }

    /// <summary>
    /// Releases all ordinary `VS8` shelf ownership claims held by a writer context.<br/>
    /// This is called only after context publication or abort has consumed the staged mutable shelves.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf claims should be released.<br/></param>
    private void ReleaseVarKeyScalar8ShelfOwnersForWriteContext(LibraDexWriteContext writeContext)
    {
        lock (writeContextAdmissionSync)
        {
            foreach (long shelfOffset in writeContext.VarKeyScalar8MutableBatchShelves.Keys)
            {
                if (varKeyScalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    varKeyScalar8WriterShelfOwners.Remove(shelfOffset);
                }
            }

            foreach (long shelfOffset in writeContext.VarKeyScalar8RawMutableShelfBytes.Keys)
            {
                if (varKeyScalar8WriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    varKeyScalar8WriterShelfOwners.Remove(shelfOffset);
                }
            }

            SignalReleasedWriteContextShelves();
        }
    }

    /// <summary>
    /// Releases all mutable ordinary `VS8` shelves owned by one writer context.<br/>
    /// Writer-context shelves use private byte arrays but still use the standard mutable-shelf release path for sidecar cleanup and future pooling symmetry.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose mutable shelves should be released.<br/></param>
    /// <param name="clearShelfBytes">Whether reusable shelf bytes should be cleared before release.<br/></param>
    private void ReleaseVarKeyScalar8MutableShelvesForWriteContext(LibraDexWriteContext writeContext, bool clearShelfBytes)
    {
        foreach (VarKeyScalar8MutableShelf mutableShelf in writeContext.VarKeyScalar8MutableBatchShelves.Values)
        {
            ReleaseVarKeyScalar8MutableShelf(mutableShelf, clearShelfBytes);
        }

        writeContext.VarKeyScalar8MutableBatchShelves.Clear();
    }

