    /// Different shelves may stage independently, while same-shelf writes fail deterministically and can be retried by the caller.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the shelf.<br/></param>
    /// <param name="shelfOffset">The ordinary `SV8` shelf offset to claim.<br/></param>
    private void ClaimScalar8VarIdentityShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        lock (writeContextAdmissionSync)
        {
            if (scalar8VarIdentityWriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
            {
                if (ReferenceEquals(owner, writeContext))
                {
                    return;
                }

                throw new LibraDexWriteContextScalar8VarIdentityShelfOwnershipException(shelfOffset);
            }

            scalar8VarIdentityWriterShelfOwners.Add(shelfOffset, writeContext);
        }
    }

    /// <summary>
    /// Releases all ordinary `SV8` shelf ownership claims held by a writer context.<br/>
    /// This is called only after context publication or abort has consumed the staged mutable shelves.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf claims should be released.<br/></param>
    private void ReleaseScalar8VarIdentityShelfOwnersForWriteContext(LibraDexWriteContext writeContext)
    {
        lock (writeContextAdmissionSync)
        {
            foreach (long shelfOffset in writeContext.Scalar8VarIdentityMutableBatchShelves.Keys)
            {
                if (scalar8VarIdentityWriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    scalar8VarIdentityWriterShelfOwners.Remove(shelfOffset);
                }
            }

            SignalReleasedWriteContextShelves();
        }
    }

    /// <summary>
    /// Releases all mutable ordinary `SV8` shelves owned by one writer context.<br/>
    /// The current mutable view uses ordinary arrays, so release clears the staged byte images when requested and drops references.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose mutable shelves should be released.<br/></param>
    /// <param name="clearShelfBytes">Whether reusable shelf bytes should be cleared before dropping references.</param>
    private static void ReleaseScalar8VarIdentityMutableShelvesForWriteContext(LibraDexWriteContext writeContext, bool clearShelfBytes)
    {
        foreach (Scalar8VarIdentityMutableShelfView mutableShelf in writeContext.Scalar8VarIdentityMutableBatchShelves.Values)
        {
            mutableShelf.Release(clearShelfBytes);
        }

        writeContext.Scalar8VarIdentityMutableBatchShelves.Clear();
    }

    /// <summary>
    /// Claims one ordinary `SV16` shelf offset for a writer context.<br/>
    /// Different shelves may stage independently, while same-shelf writes fail deterministically and can be retried by the caller.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context claiming the shelf.<br/></param>
    /// <param name="shelfOffset">The ordinary `SV16` shelf offset to claim.<br/></param>
    private void ClaimScalar16VarIdentityShelfForWriteContext(LibraDexWriteContext writeContext, long shelfOffset)
    {
        lock (writeContextAdmissionSync)
        {
            if (scalar16VarIdentityWriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner))
            {
                if (ReferenceEquals(owner, writeContext))
                {
                    return;
                }

                throw new LibraDexWriteContextScalar16VarIdentityShelfOwnershipException(shelfOffset);
            }

            scalar16VarIdentityWriterShelfOwners.Add(shelfOffset, writeContext);
        }
    }

    /// <summary>
    /// Releases all ordinary `SV16` shelf ownership claims held by a writer context.<br/>
    /// This is called only after context publication or abort has consumed the staged mutable shelves.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose shelf claims should be released.<br/></param>
    private void ReleaseScalar16VarIdentityShelfOwnersForWriteContext(LibraDexWriteContext writeContext)
    {
        lock (writeContextAdmissionSync)
        {
            foreach (long shelfOffset in writeContext.Scalar16VarIdentityMutableBatchShelves.Keys)
            {
                if (scalar16VarIdentityWriterShelfOwners.TryGetValue(shelfOffset, out LibraDexWriteContext? owner) &&
                    ReferenceEquals(owner, writeContext))
                {
                    scalar16VarIdentityWriterShelfOwners.Remove(shelfOffset);
                }
            }

            SignalReleasedWriteContextShelves();
        }
    }

    /// <summary>
    /// Releases all mutable ordinary `SV16` shelves owned by one writer context.<br/>
    /// The current mutable view uses ordinary arrays, so release clears the staged byte images when requested and drops references.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context whose mutable shelves should be released.<br/></param>
    /// <param name="clearShelfBytes">Whether reusable shelf bytes should be cleared before dropping references.</param>
    private static void ReleaseScalar16VarIdentityMutableShelvesForWriteContext(LibraDexWriteContext writeContext, bool clearShelfBytes)
    {
        if (clearShelfBytes)
        {
            foreach (Scalar16VarIdentityMutableShelfView mutableShelf in writeContext.Scalar16VarIdentityMutableBatchShelves.Values)
            {
                mutableShelf.Bytes.AsSpan(0, mutableShelf.Profile.ShelfExtentSize).Clear();
            }
        }

        writeContext.Scalar16VarIdentityMutableBatchShelves.Clear();
    }

    /// <summary>
    /// Starts a session-scoped durability batch that defers session commit calls until the batch commits or aborts.<br/>
    /// The first batch model controls durability cadence rather than transaction isolation; staged writes remain readable through the DataKernel pending overlay until publication.<br/>
    /// Write intent is stored only for the active batch and gives shape-specific policy code a coarse optimization signal.<br/>
    /// </summary>
    /// <param name="writeIntent">Optional coarse write-pattern hints for the active batch.<br/></param>
    /// <returns>A session durability batch handle.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when another durability batch is already active.<br/></exception>
    internal LibraDexFileSessionDurabilityBatch BeginDurabilityBatch(LibraDexWriteIntent writeIntent = default)
    {
        long operationToken = ClaimDiagnosticWriteWindow();
        if (durabilityBatchActive)
        {
            ReleaseDiagnosticWriteWindow(operationToken);
            throw new InvalidOperationException("A LibraDex session durability batch is already active.");
        }

        durabilityBatchActive = true;
        LibraDexWriteContext writeContext = new(operationToken);
        activeWriteContext = writeContext;
        routerReadCacheInvalidationPending = false;
        deferredDurabilityCommitRequests = 0;
        currentWriteIntent = writeIntent;
        scalar8Scalar8MutableBatchShelfBytes.Clear();
        scalar16Scalar8MutableBatchShelfBytes.Clear();
        scalar8Scalar16MutableBatchShelfBytes.Clear();
        scalar16Scalar16MutableBatchShelfBytes.Clear();
        fixed32Scalar8MutableBatchShelfBytes.Clear();
        fixed32Scalar16MutableBatchShelfBytes.Clear();
        fixed32Scalar8RetainedBatchShelfOffsets.Clear();
        fixed32Scalar16RetainedBatchShelfOffsets.Clear();
        ReleaseVarKeyScalar8MutableBatchShelves(clearShelfBytes: true);
        ReleaseVarKeyScalar16MutableBatchShelves(clearShelfBytes: true);
        ReleaseVarKeyVarIdentityMutableBatchShelves(clearShelfBytes: true);
        scalar8VarIdentityMutableBatchShelves.Clear();
        scalar16VarIdentityMutableBatchShelves.Clear();
        return new LibraDexFileSessionDurabilityBatch(this, writeContext);
    }

    /// <summary>
    /// Claims the diagnostics-only active write window before a durability batch mutates session state.<br/>
    /// The token is carried by the returned durability batch and is used only when detailed diagnostics are enabled.<br/>
    /// </summary>
    /// <returns>The claimed write-window operation token, or zero when detailed ownership diagnostics are disabled.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when another detailed diagnostic write window is already active.<br/></exception>
    private long ClaimDiagnosticWriteWindow()
    {
        if (!detailedWriteWindowOwnershipDiagnostics)
        {
            return 0;
        }

        long operationToken = Interlocked.Increment(ref diagnosticWriteWindowNextOperationToken);
        if (operationToken == 0)
        {
            operationToken = Interlocked.Increment(ref diagnosticWriteWindowNextOperationToken);
        }

        long activeToken = Interlocked.CompareExchange(
            ref diagnosticWriteWindowActiveOperationToken,
            operationToken,
            0);
        if (activeToken != 0)
        {
            throw CreateDiagnosticWriteWindowAlreadyActiveException(activeToken);
        }

        Volatile.Write(ref diagnosticWriteWindowOwnerThreadId, Environment.CurrentManagedThreadId);
        return operationToken;
    }

    /// <summary>
    /// Verifies that a commit or abort request is coming through the durability batch that claimed the active write window.<br/>
    /// This keeps detailed diagnostics from treating a managed thread id as the ownership authority.<br/>
    /// </summary>
    /// <param name="operationToken">The operation token carried by the durability batch handle.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when the supplied token does not own the active write window.<br/></exception>
    private void VerifyDiagnosticWriteWindowOwner(long operationToken)
    {
        if (!detailedWriteWindowOwnershipDiagnostics)
        {
            return;
        }

        long activeToken = Volatile.Read(ref diagnosticWriteWindowActiveOperationToken);
        if (operationToken != 0 && operationToken == activeToken)
        {
            return;
        }

        throw new InvalidOperationException(
            "The LibraDex durability batch token does not own the active session write window. " +
            "Commit or abort must be issued by the batch handle that claimed the write window; " +
            "serialize same-session writes or use isolated catalogs.");
    }

    /// <summary>
    /// Verifies that the supplied writer context is the currently active session publication context.<br/>
    /// This keeps the publication seam context-owned before later work allows more than one context to stage independent changes.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context carried by the durability-batch handle.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when the context does not own the active session write window.<br/></exception>
    private void VerifyActiveWriteContext(LibraDexWriteContext writeContext)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (!ReferenceEquals(activeWriteContext, writeContext))
        {
            throw new InvalidOperationException(
                "The LibraDex writer context does not own the active session publication boundary. " +
                "Commit or abort must be issued by the batch handle that created the writer context.");
        }

        VerifyDiagnosticWriteWindowOwner(writeContext.OperationToken);
    }

    /// <summary>
    /// Verifies that an Abraxas-facing materialized read is not entering while a detailed-diagnostics write window is active.<br/>
    /// This is a boundary diagnostic for integration adapters; it does not create a published-reader mode or add synchronization to ordinary lookup paths.<br/>
    /// </summary>
    /// <param name="surfaceName">The adapter or public surface attempting the materialized read.<br/></param>
    /// <exception cref="InvalidOperationException">Thrown when the session has an active detailed diagnostic write window.<br/></exception>
    internal void VerifyNoActiveDiagnosticWriteWindowForMaterializedRead(string surfaceName)
    {
        if (!detailedWriteWindowOwnershipDiagnostics)
        {
            return;
        }

        long activeToken = Volatile.Read(ref diagnosticWriteWindowActiveOperationToken);
        if (activeToken == 0)
        {
            return;
        }

        int ownerThreadId = Volatile.Read(ref diagnosticWriteWindowOwnerThreadId);
        throw new InvalidOperationException(
            "LibraDex detected a materialized Abraxas read while a same-session write window is active. " +
            $"{surfaceName} must run under the Abraxas/owner serialization boundary, or use a future published-reader mode. " +
            "The read was rejected before condition materialization could observe pending writer state. " +
            $"Active write window: operation {activeToken}, claimed by thread {ownerThreadId}.");
    }

    /// <summary>
    /// Releases the diagnostics-only active write-window claim after the session leaves the active durability-batch lifecycle.<br/>
    /// The release is intentionally tied to normal commit/abort cleanup and does not create a rollback or recovery policy.<br/>
    /// </summary>
    /// <param name="operationToken">The operation token carried by the durability batch handle.<br/></param>
    private void ReleaseDiagnosticWriteWindow(long operationToken)
    {
        if (!detailedWriteWindowOwnershipDiagnostics || operationToken == 0)
        {
            return;
        }

        long previousToken = Interlocked.CompareExchange(
            ref diagnosticWriteWindowActiveOperationToken,
            0,
            operationToken);
        if (previousToken == operationToken)
        {
            Volatile.Write(ref diagnosticWriteWindowOwnerThreadId, 0);
        }
    }

    /// <summary>
    /// Creates the detailed diagnostic exception used when a second writer tries to enter an active session write window.<br/>
    /// The message is deliberately contract-oriented so callers see the supported choices rather than a low-level flag failure.<br/>
    /// </summary>
    /// <param name="activeToken">The active write-window operation token observed by the failed claimant.<br/></param>
    /// <returns>The unsupported-concurrency exception to throw.<br/></returns>
    private InvalidOperationException CreateDiagnosticWriteWindowAlreadyActiveException(long activeToken)
    {
        int ownerThreadId = Volatile.Read(ref diagnosticWriteWindowOwnerThreadId);
        return new InvalidOperationException(
            "LibraDex detected overlapping same-session writes. " +
            "Catalog/session writes are single-owner in the current concurrency contract; " +
            "serialize access, use isolated catalogs, materialize read results, or use a future queued-writer/published-reader mode. " +
            "The competing write was rejected before shared session state was mutated. " +
            $"Active write window: operation {activeToken}, claimed by thread {ownerThreadId}.");
    }

    internal static LibraDexFileSession Initialize(
        string path,
        DataKernelOptions options,
        SuperblockDeveloperMetadata developerMetadata,
        DataKernelTelemetryOptions telemetryOptions)
    {
        if (options.ReservedPrefixBytes != 0)
        {
            throw new ArgumentException("LibraDex file sessions own offset zero and require DataKernelOptions.ReservedPrefixBytes to be 0 during initialization.", nameof(options));
        }

        DataKernel kernel = DataKernel.Open(path, FileMode.Create, options, telemetryOptions);
        try
        {
            RawDataReservation superblock = kernel.Reserve(SuperblockLayout.Size);
            RawDataReservation indexDirectory = kernel.Reserve(IndexDirectoryLayout.Size);

            new SuperblockWriter(superblock.Span).Initialize(
                options.ReservedPrefixBytes,
                indexDirectory.Extent.Offset,
                Guid.NewGuid(),
                DateTimeOffset.UtcNow.UtcDateTime.Ticks,
                developerMetadata);

            new IndexDirectoryWriter(indexDirectory.Span).InitializeEmpty();

            SuperblockSnapshot superblockSnapshot = SuperblockSnapshot.FromReader(new SuperblockReader(superblock.Span));
            IndexDirectorySnapshot indexDirectorySnapshot = IndexDirectorySnapshot.FromBytes(indexDirectory.Span);
            kernel.Commit();

            return new LibraDexFileSession(
                kernel,
                superblockSnapshot,
                indexDirectorySnapshot,
                telemetryOptions.Level);
        }
        catch
        {
            kernel.Dispose();
            throw;
        }
    }

    /// <summary>
    /// Initializes a new memory-backed LibraDex session with a superblock and empty fixed index directory.<br/>
    /// Memory-backed sessions preserve the same offset, metadata, index-directory, router, shelf, and commit semantics as file-backed sessions, but they are not durable and cannot be reopened after disposal.<br/>
    /// This method exists for low-friction temporary indexes and validation flows that should avoid file I/O without changing storage-layer byte formats.<br/>
    /// </summary>
    /// <param name="options">The raw DataKernel policy to use for the memory-backed session.</param>
    /// <param name="developerMetadata">The developer metadata to write into the initialized superblock.</param>
    /// <param name="telemetryOptions">The telemetry collection policy.</param>
    /// <returns>An initialized memory-backed file session.</returns>
    internal static LibraDexFileSession InitializeMemory(
        DataKernelOptions options,
        SuperblockDeveloperMetadata developerMetadata,
        DataKernelTelemetryOptions telemetryOptions)
    {
        DataKernel kernel = DataKernel.OpenMemory(options, telemetryOptions);
        try
        {
            RawDataReservation superblock = kernel.Reserve(SuperblockLayout.Size);
            RawDataReservation indexDirectory = kernel.Reserve(IndexDirectoryLayout.Size);

            new SuperblockWriter(superblock.Span).Initialize(
                options.ReservedPrefixBytes,
                indexDirectory.Extent.Offset,
                Guid.NewGuid(),
                DateTimeOffset.UtcNow.UtcDateTime.Ticks,
                developerMetadata);

            new IndexDirectoryWriter(indexDirectory.Span).InitializeEmpty();

            SuperblockSnapshot superblockSnapshot = SuperblockSnapshot.FromReader(new SuperblockReader(superblock.Span));
            IndexDirectorySnapshot indexDirectorySnapshot = IndexDirectorySnapshot.FromBytes(indexDirectory.Span);
            kernel.Commit();

            return new LibraDexFileSession(
                kernel,
                superblockSnapshot,
                indexDirectorySnapshot,
                telemetryOptions.Level);
        }
        catch
        {
            kernel.Dispose();
            throw;
        }
    }

    internal static LibraDexFileSession Open(
        string path,
        DataKernelOptions options,
        DataKernelTelemetryOptions telemetryOptions)
    {
        DataKernel kernel = DataKernel.Open(path, FileMode.Open, options, telemetryOptions);
        try
        {
            byte[] superblockBytes = new byte[SuperblockLayout.Size];
            kernel.Read(0, superblockBytes);
            SuperblockReader superblockReader = new(superblockBytes);
            if (!superblockReader.IsValid)
            {
                throw new InvalidDataException("The LibraDex superblock is invalid.");
            }

            byte[] indexDirectoryBytes = new byte[superblockReader.IndexDirectoryLength];
            kernel.Read(superblockReader.IndexDirectoryOffset, indexDirectoryBytes);

            return new LibraDexFileSession(
                kernel,
                SuperblockSnapshot.FromReader(superblockReader),
                IndexDirectorySnapshot.FromBytes(indexDirectoryBytes),
                telemetryOptions.Level);
        }
        catch
        {
            kernel.Dispose();
            throw;
        }
    }

    /// <summary>
    /// Updates the optional developer-owned superblock metadata and commits the fixed superblock page.<br/>
    /// The superblock cache is replaced only after the DataKernel commit succeeds.<br/>
    /// This method rewrites the full 4 KiB superblock so metadata updates remain one fixed-offset staged write.<br/>
    /// </summary>
    /// <param name="developerMetadata">The developer-owned metadata values to persist.</param>
    /// <returns>The DataKernel commit telemetry for the superblock rewrite.</returns>
    internal DataKernelCommitTelemetry UpdateDeveloperMetadata(SuperblockDeveloperMetadata developerMetadata)
    {
        RawDataReservation superblock = kernel.ReserveAt(0, SuperblockLayout.Size);
        new SuperblockWriter(superblock.Span).Initialize(
            Superblock.ReservedPrefixBytes,
            Superblock.IndexDirectoryOffset,
            Superblock.FileGuid,
            Superblock.CreatedUtcTicks,
            developerMetadata);

        SuperblockSnapshot updated = SuperblockSnapshot.FromReader(new SuperblockReader(superblock.Span));
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        Superblock = updated;
        return telemetry;
    }

    /// <summary>
    /// Writes or replaces one fixed index-directory slot and commits the full directory region.<br/>
    /// The directory cache is replaced only after the DataKernel commit succeeds.<br/>
    /// This early implementation rewrites the full 8 KiB directory to keep update shape simple and same-offset.<br/>
    /// </summary>
    /// <param name="slot">The slot snapshot to persist.</param>
    /// <returns>The DataKernel commit telemetry for the directory rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slot index is outside the fixed directory.</exception>
    /// <exception cref="ArgumentException">Thrown when an active slot uses offset zero as a root-router target.</exception>
    internal DataKernelCommitTelemetry UpsertIndexDirectorySlot(IndexDirectorySlotSnapshot slot)
    {
        if ((uint)slot.SlotIndex >= IndexDirectoryLayout.SlotCount)
        {
            throw new ArgumentOutOfRangeException(nameof(slot), slot.SlotIndex, "Index directory slot is outside the fixed directory.");
        }

        if (slot.IsActive && slot.RootRouterOffset == 0)
        {
            throw new ArgumentException("Active index-directory slots cannot use file offset zero as a root-router target.", nameof(slot));
        }

        RawDataReservation directory = kernel.ReserveAt(Superblock.IndexDirectoryOffset, Superblock.IndexDirectoryLength);
        IndexDirectoryWriter writer = new(directory.Span);
        writer.InitializeEmpty();

        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            IndexDirectorySlotSnapshot existing = activeSlots[i];
            if (existing.SlotIndex != slot.SlotIndex)
            {
                writer.WriteSlot(existing);
            }
        }

        writer.WriteSlot(slot);
        IndexDirectorySnapshot updated = IndexDirectorySnapshot.FromBytes(directory.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        IndexDirectory = updated;
        return telemetry;
    }

    /// <summary>
    /// Runs one fixed-N mutation under the session publication gate.<br/>
    /// Fixed-N does not yet have per-shelf writer-context staging, so this conservative gate prevents concurrent fixed-N writers from interleaving index-directory rewrites, shelf rewrites, and storage publication while preserving the no-ceremony public API.<br/>
    /// </summary>
    /// <typeparam name="TResult">The mutation result type.<br/></typeparam>
    /// <param name="mutation">The session-backed fixed-N mutation to execute.<br/></param>
    /// <returns>The mutation result.<br/></returns>
    internal TResult RunFixedNMutation<TResult>(Func<TResult> mutation)
    {
        ArgumentNullException.ThrowIfNull(mutation);
        lock (writePublicationSync)
        {
            return mutation();
        }
    }

    /// <summary>
    /// Runs one `FSN-8` topology fallback mutation under the session publication gate.<br/>
    /// Shelf-local writer contexts no longer take a root topology lock; they publish only after route-claim validation, so fallback synchronization is limited to the storage publication boundary.<br/>
    /// </summary>
    /// <typeparam name="TResult">The mutation result type.<br/></typeparam>
    /// <param name="rootRouterOffset">The routed fixed-N root that owns the topology mutation.<br/></param>
    /// <param name="mutation">The fixed-N fallback mutation to execute.<br/></param>
    /// <returns>The mutation result.<br/></returns>
    internal TResult RunFixedNScalar8TopologyMutation<TResult>(long rootRouterOffset, Func<TResult> mutation)
    {
        ArgumentNullException.ThrowIfNull(mutation);
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(7, 1, rootRouterOffset, rootRouterOffset, -1));
        lock (topologyOwner)
        {
            ReaderWriterLockSlim topologySync = GetFixedNScalar8TopologyMutationSync(rootRouterOffset);
            topologySync.EnterWriteLock();
            try
            {
                return RunFixedNMutation(mutation);
            }
            finally
            {
                topologySync.ExitWriteLock();
            }
        }
    }

    /// <summary>
    /// Runs one `FSN-16` topology fallback mutation under the session publication gate.<br/>
    /// Shelf-local writer contexts no longer take a root topology lock; they publish only after route-claim validation, so fallback synchronization is limited to the storage publication boundary.<br/>
    /// </summary>
    /// <typeparam name="TResult">The mutation result type.<br/></typeparam>
    /// <param name="rootRouterOffset">The routed fixed-N root that owns the topology mutation.<br/></param>
    /// <param name="mutation">The fixed-N fallback mutation to execute.<br/></param>
    /// <returns>The mutation result.<br/></returns>
    internal TResult RunFixedNScalar16TopologyMutation<TResult>(long rootRouterOffset, Func<TResult> mutation)
    {
        ArgumentNullException.ThrowIfNull(mutation);
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(8, 1, rootRouterOffset, rootRouterOffset, -1));
        lock (topologyOwner)
        {
            ReaderWriterLockSlim topologySync = GetFixedNScalar16TopologyMutationSync(rootRouterOffset);
            topologySync.EnterWriteLock();
            try
            {
                return RunFixedNMutation(mutation);
            }
            finally
            {
                topologySync.ExitWriteLock();
            }
        }
    }

    /// <summary>
    /// Creates a fully expanded one-byte root router and links it from an index-directory slot in one commit.<br/>
    /// The root router is appended as a new 4 KiB page, while the fixed 8 KiB index directory is rewritten in place.<br/>
    /// The directory cache is replaced only after the DataKernel commit succeeds.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router offset is supplied by this method.</param>
    /// <returns>The created router snapshot and DataKernel commit telemetry.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slot index is outside the fixed directory.</exception>
    internal (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateRootRouterIndex(IndexDirectorySlotSnapshot slot)
    {
        return CreateRootRouterIndexCore(slot);
    }

    /// <summary>
    /// Creates a root router and persists a versioned variable-length catalog metadata blob for the index in the same commit.<br/>
    /// The fixed index-directory slot remains the durable inventory anchor, while `MetadataOffset` points to the richer group/name/type/profile metadata needed by grouped and non-generic public APIs.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router and metadata offsets are supplied by this method.</param>
    /// <param name="metadata">The richer catalog metadata to serialize beside the fixed slot.</param>
    /// <returns>The created router snapshot and DataKernel commit telemetry.</returns>
    internal (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateRootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata)
    {
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(metadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, metadata);
        return CreateRootRouterIndexCore(slot with { MetadataOffset = metadataReservation.Extent.Offset });
    }

    /// <summary>
    /// Attempts to read richer catalog index metadata from an active directory slot.<br/>
    /// Slots without a metadata offset are treated as older scaffold entries and return false so callers can fall back to fixed-slot fields.<br/>
    /// </summary>
    /// <param name="slot">The directory slot whose metadata offset should be read.</param>
    /// <param name="metadata">Receives the decoded metadata when present and valid.</param>
    /// <returns><see langword="true"/> when versioned metadata was decoded; otherwise <see langword="false"/>.</returns>
    internal bool TryReadCatalogIndexMetadata(IndexDirectorySlotSnapshot slot, out CatalogIndexMetadata metadata)
    {
        metadata = default;
        if (slot.MetadataOffset <= 0)
        {
            return false;
        }

        Span<byte> header = stackalloc byte[20];
        kernel.Read(slot.MetadataOffset, header);
        if (!CatalogIndexMetadataCodec.TryReadLength(header, out int length))
        {
            return false;
        }

        byte[] bytes = new byte[length];
        header.CopyTo(bytes);
        if (length > header.Length)
        {
            kernel.Read(slot.MetadataOffset + header.Length, bytes.AsSpan(header.Length));
        }

        return CatalogIndexMetadataCodec.TryRead(bytes, out metadata);
    }

    /// <summary>
    /// Attempts to read the durable root-level null and empty key-state routes for an index slot.<br/>
    /// Older catalog metadata versions decode with both offsets set to zero, which means no special route has been published yet.<br/>
    /// The offsets are intentionally stored in catalog metadata rather than the direct root router, because all 256 root prefix bytes are valid normal routes.<br/>
    /// </summary>
    /// <param name="slot">The active index-directory slot whose route offsets should be read.</param>
    /// <param name="offsets">Receives the decoded key-state route offsets when metadata exists.</param>
    /// <returns><see langword="true"/> when catalog metadata was decoded; otherwise <see langword="false"/>.</returns>
    internal bool TryReadKeyRouteOffsets(IndexDirectorySlotSnapshot slot, out KeyRouteOffsets offsets)
    {
        offsets = default;
        if (!TryReadCatalogIndexMetadata(slot, out CatalogIndexMetadata metadata))
        {
            return false;
        }

        offsets = new KeyRouteOffsets(metadata.NullKeyRouteOffset, metadata.EmptyKeyRouteOffset);
        return true;
    }

    /// <summary>
    /// Appends replacement catalog metadata with updated null and empty key-state routes, then publishes the metadata offset through the fixed directory slot.<br/>
    /// This keeps special root routes durable without stealing slot-array bits or reserving magic root-router prefixes.<br/>
    /// The normal enumeration order remains null route first, empty route second, then ordinary root-router value routes.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed directory slot that owns the index metadata.</param>
    /// <param name="offsets">The root-level key-state route offsets to publish.</param>
    /// <returns>The DataKernel commit telemetry for the metadata append and directory update.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when a route offset is negative.</exception>
    /// <exception cref="InvalidDataException">Thrown when the requested slot is inactive or has no decodable catalog metadata.</exception>
    internal DataKernelCommitTelemetry UpdateKeyRouteOffsets(int slotIndex, KeyRouteOffsets offsets)
    {
        if (offsets.Null < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(offsets), offsets.Null, "The null key route offset cannot be negative.");
        }

        if (offsets.Empty < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(offsets), offsets.Empty, "The empty key route offset cannot be negative.");
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested index slot is not active.");
        }

        if (!TryReadCatalogIndexMetadata(slot, out CatalogIndexMetadata metadata))
        {
            throw new InvalidDataException("The requested index slot does not have decodable catalog metadata for key-state routes.");
        }

        CatalogIndexMetadata updatedMetadata = metadata with
        {
            NullKeyRouteOffset = offsets.Null,
            EmptyKeyRouteOffset = offsets.Empty
        };
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(updatedMetadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, updatedMetadata);
        return UpsertIndexDirectorySlot(slot with
        {
            MetadataOffset = metadataReservation.Extent.Offset,
            Generation = slot.Generation + 1
        });
    }

    /// <summary>
    /// Creates a composite index catalog slot with versioned metadata and an initial persisted composite snapshot.<br/>
    /// The snapshot offset is stored in the slot root offset for this first durable composite-content slice; later mini-router pages can keep the same catalog anchor while changing the pointed-to byte format.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The richer catalog metadata to serialize beside the fixed slot.</param>
    /// <param name="snapshot">The encoded composite snapshot bytes.</param>
    /// <param name="itemCount">The logical composite tuple count represented by the snapshot.</param>
    /// <returns>The DataKernel commit telemetry for the metadata, snapshot, and directory update.</returns>
    internal DataKernelCommitTelemetry CreateCompositeSnapshotIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        ReadOnlySpan<byte> snapshot,
        long itemCount)
    {
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(metadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, metadata);
        RawDataReservation snapshotReservation = kernel.Reserve(snapshot.Length);
        snapshot.CopyTo(snapshotReservation.Span);
        return UpsertIndexDirectorySlot(slot with
        {
            MetadataOffset = metadataReservation.Extent.Offset,
            RootRouterOffset = snapshotReservation.Extent.Offset,
            ItemCount = itemCount
        });
    }

    /// <summary>
    /// Creates a composite index catalog slot with versioned metadata and an initial durable root node page.<br/>
    /// The root node offset is stored in the fixed slot root offset so later inserts can update only the copied path back to the root.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The richer catalog metadata to serialize beside the fixed slot.</param>
    /// <param name="rootNode">The encoded root node page bytes.</param>
    /// <returns>The root node offset and DataKernel commit telemetry.</returns>
    internal (long RootOffset, DataKernelCommitTelemetry Commit) CreateCompositeNodePageIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        ReadOnlySpan<byte> rootNode)
    {
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(metadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, metadata);
        RawDataReservation rootReservation = kernel.Reserve(rootNode.Length);
        rootNode.CopyTo(rootReservation.Span);
        DataKernelCommitTelemetry commit = UpsertIndexDirectorySlot(slot with
        {
            MetadataOffset = metadataReservation.Extent.Offset,
            RootRouterOffset = rootReservation.Extent.Offset,
            ItemCount = 0
        });
        return (rootReservation.Extent.Offset, commit);
    }

    /// <summary>
    /// Persists a replacement composite snapshot and updates the fixed directory slot to point at it.<br/>
    /// This whole-snapshot rewrite is intentionally a correctness bridge before durable per-tier mini-router pages are introduced.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to update.</param>
    /// <param name="snapshot">The encoded composite snapshot bytes.</param>
    /// <param name="itemCount">The logical composite tuple count represented by the snapshot.</param>
    /// <returns>The DataKernel commit telemetry for the snapshot and directory update.</returns>
    internal DataKernelCommitTelemetry UpdateCompositeSnapshotIndex(
        int slotIndex,
        ReadOnlySpan<byte> snapshot,
        long itemCount)
    {
        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested composite index slot is not active.");
        }

        RawDataReservation snapshotReservation = kernel.Reserve(snapshot.Length);
        snapshot.CopyTo(snapshotReservation.Span);
        return UpsertIndexDirectorySlot(slot with
        {
            RootRouterOffset = snapshotReservation.Extent.Offset,
            ItemCount = itemCount,
            Generation = slot.Generation + 1
        });
    }

    /// <summary>
    /// Appends one immutable composite node page.<br/>
    /// The caller decides whether this page is a terminal path copy, a copied parent, or a new child route; publication occurs through the normal DataKernel commit path.<br/>
    /// </summary>
    /// <param name="nodePage">The encoded node page bytes.</param>
    /// <returns>The durable offset of the appended node page.</returns>
    internal long AppendCompositeNodePage(ReadOnlySpan<byte> nodePage)
    {
        RawDataReservation reservation = kernel.Reserve(nodePage.Length);
        nodePage.CopyTo(reservation.Span);
        return reservation.Extent.Offset;
    }

    /// <summary>
    /// Updates the fixed directory slot to point at a replacement composite root node page.<br/>
    /// Immutable path-copy inserts append changed nodes first, then publish the new root offset through this directory update.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to update.</param>
    /// <param name="rootOffset">The durable offset of the replacement root node page.</param>
    /// <param name="itemCount">The logical composite tuple count represented by the root.</param>
    /// <returns>The DataKernel commit telemetry for the directory update.</returns>
    internal DataKernelCommitTelemetry UpdateCompositeNodeRoot(
        int slotIndex,
        long rootOffset,
        long itemCount)
    {
        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested composite index slot is not active.");
        }

        return UpsertIndexDirectorySlot(slot with
        {
            RootRouterOffset = rootOffset,
            ItemCount = itemCount,
            Generation = slot.Generation + 1
        });
    }

    /// <summary>
    /// Records payload cell offsets made unreachable by slot-table deletion in one shelf.<br/>
    /// Slot removal is the visibility delete; this session-local queue preserves the orphaned payload locations so future reuse or compaction can avoid rediscovering them by scanning every shelf.<br/>
    /// The record is intentionally not a transaction log and is not yet persisted across sessions.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable shelf offset whose payload cells became unreachable.</param>
    /// <param name="payloadOffsets">The shelf-relative payload cell offsets removed from the active slot table.</param>
    internal void RecordDeletedShelfPayloadOffsets(long shelfOffset, ReadOnlySpan<ushort> payloadOffsets)
    {
        if (shelfOffset <= 0 || payloadOffsets.Length == 0)
        {
            return;
        }

        if (!deletedShelfPayloadOffsets.TryGetValue(shelfOffset, out List<ushort>? offsets))
        {
            offsets = new List<ushort>(payloadOffsets.Length);
            deletedShelfPayloadOffsets.Add(shelfOffset, offsets);
        }

        for (int i = 0; i < payloadOffsets.Length; i++)
        {
            offsets.Add(payloadOffsets[i]);
        }

        deletedShelfPayloadCellsRecorded += payloadOffsets.Length;
    }

    /// <summary>
    /// Removes one reclaimed payload cell from the session-local delete queue after a later insert writes into that exact cell.<br/>
    /// Fixed scalar deletes compact survivors so ordinary no-split inserts naturally reuse the tail cell at the old active count; this method keeps the maintenance-facing ledger from advertising a live payload cell as free.<br/>
    /// The queue is intentionally best-effort and session-local, so a missing offset is not an error.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable shelf offset that received the insert.</param>
    /// <param name="payloadOffset">The shelf-relative payload cell offset written by the insert.</param>
    /// <returns><see langword="true"/> when a queued reclaimed cell was consumed.</returns>
    internal bool TryConsumeDeletedShelfPayloadOffset(long shelfOffset, ushort payloadOffset)
    {
        if (shelfOffset <= 0 ||
            !deletedShelfPayloadOffsets.TryGetValue(shelfOffset, out List<ushort>? offsets))
        {
            return false;
        }

        int index = offsets.LastIndexOf(payloadOffset);
        if (index < 0)
        {
            return false;
        }

        offsets.RemoveAt(index);
        deletedShelfPayloadCellsConsumed++;
        if (offsets.Count == 0)
        {
            deletedShelfPayloadOffsets.Remove(shelfOffset);
        }

        return true;
    }

    /// <summary>
    /// Gets the current session-local reclaimed fixed-shelf payload-cell counters.<br/>
    /// The queued values are point-in-time observations from the open-session ledger, while recorded and consumed values are cumulative for this session instance only.<br/>
    /// </summary>
    /// <returns>A reclaimed-payload stats snapshot for this session.</returns>
    internal LibraDexReclaimedPayloadStats GetReclaimedPayloadStats()
    {
        long queuedCellCount = 0;
        foreach (KeyValuePair<long, List<ushort>> pair in deletedShelfPayloadOffsets)
        {
            queuedCellCount += pair.Value.Count;
        }

        return new LibraDexReclaimedPayloadStats(
            deletedShelfPayloadOffsets.Count,
            queuedCellCount,
            deletedShelfPayloadCellsRecorded,
            deletedShelfPayloadCellsConsumed);
    }

    /// <summary>
    /// Creates a defensive copy of the session-local deleted payload cell queue.<br/>
    /// This is the first maintenance-facing observation point for delete bookkeeping; later slices can persist or drain these records into shelf reuse and compaction flows.<br/>
    /// </summary>
    /// <returns>A snapshot keyed by durable shelf offset.</returns>
    internal IReadOnlyDictionary<long, IReadOnlyList<ushort>> SnapshotDeletedShelfPayloadOffsets()
    {
        Dictionary<long, IReadOnlyList<ushort>> snapshot = new(deletedShelfPayloadOffsets.Count);
        foreach (KeyValuePair<long, List<ushort>> pair in deletedShelfPayloadOffsets)
        {
            snapshot.Add(pair.Key, pair.Value.ToArray());
        }

        return snapshot;
    }

    /// <summary>
    /// Attempts to read the composite snapshot pointed to by a fixed directory slot.<br/>
    /// Slots whose root offset does not point at a composite snapshot return <see langword="false"/> so older metadata-only composite slots fail closed instead of being misread as tuple data.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot whose root offset should point at a composite snapshot.</param>
    /// <param name="snapshot">Receives the encoded snapshot bytes when present.</param>
    /// <returns><see langword="true"/> when a composite snapshot was decoded from the slot root offset; otherwise <see langword="false"/>.</returns>
    internal bool TryReadCompositeSnapshot(IndexDirectorySlotSnapshot slot, out byte[] snapshot)
    {
        snapshot = [];
        if (slot.RootRouterOffset <= 0)
        {
            return false;
        }

        Span<byte> header = stackalloc byte[16];
        kernel.Read(slot.RootRouterOffset, header);
        if (!LibraDexCompositeSnapshotCodec.TryReadLength(header, out int length))
        {
            return false;
        }

        snapshot = new byte[length];
        header.CopyTo(snapshot);
        if (length > header.Length)
        {
            kernel.Read(slot.RootRouterOffset + header.Length, snapshot.AsSpan(header.Length));
        }

        return true;
    }

    /// <summary>
    /// Attempts to read a composite node page from a direct DataKernel offset.<br/>
    /// </summary>
    /// <param name="offset">The direct node page offset.</param>
    /// <param name="page">Receives the encoded node page bytes when present.</param>
    /// <returns><see langword="true"/> when a composite node page was decoded; otherwise <see langword="false"/>.</returns>
    internal bool TryReadCompositeNodePage(long offset, out byte[] page)
    {
        page = [];
        if (offset <= 0)
        {
            return false;
        }

        Span<byte> header = stackalloc byte[22];
        kernel.Read(offset, header);
        if (!LibraDexCompositeNodePageCodec.TryReadLength(header, out int length))
        {
            return false;
        }

        page = new byte[length];
        header.CopyTo(page);
        if (length > header.Length)
        {
            kernel.Read(offset + header.Length, page.AsSpan(header.Length));
        }

        return true;
    }

    /// <summary>
    /// Finds an active fixed index-directory slot in the cached session directory snapshot.<br/>
    /// This helper keeps session-owned metadata updates local to the session instead of requiring callers to duplicate directory scanning logic.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed slot index to locate.</param>
    /// <param name="slot">Receives the active slot snapshot when found.</param>
    /// <returns><see langword="true"/> when the active slot exists; otherwise <see langword="false"/>.</returns>
    private bool TryFindIndexDirectorySlot(int slotIndex, out IndexDirectorySlotSnapshot slot)
    {
        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            if (activeSlots[i].SlotIndex == slotIndex)
            {
                slot = activeSlots[i];
                return true;
            }
        }

        slot = default;
        return false;
    }

    private (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateRootRouterIndexCore(IndexDirectorySlotSnapshot slot)
    {
        if ((uint)slot.SlotIndex >= IndexDirectoryLayout.SlotCount)
        {
            throw new ArgumentOutOfRangeException(nameof(slot), slot.SlotIndex, "Index directory slot is outside the fixed directory.");
        }

        RawDataReservation router = kernel.Reserve(RouterLayout.Size);
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeRoot(slot.AllocationClassId);
        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("Created root router did not validate.");
        }

        IndexDirectorySlotSnapshot updatedSlot = slot with
        {
            State = IndexDirectoryLayout.ActiveState,
            RootRouterOffset = router.Extent.Offset
        };

        RawDataReservation directory = kernel.ReserveAt(Superblock.IndexDirectoryOffset, Superblock.IndexDirectoryLength);
        IndexDirectoryWriter directoryWriter = new(directory.Span);
        directoryWriter.InitializeEmpty();

        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            IndexDirectorySlotSnapshot existing = activeSlots[i];
            if (existing.SlotIndex != updatedSlot.SlotIndex)
            {
                directoryWriter.WriteSlot(existing);
            }
        }

        directoryWriter.WriteSlot(updatedSlot);
        RouterSnapshot routerSnapshot = RouterSnapshot.FromReader(router.Extent.Offset, routerReader);
        IndexDirectorySnapshot updatedDirectory = IndexDirectorySnapshot.FromBytes(directory.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        IndexDirectory = updatedDirectory;
        return (routerSnapshot, telemetry);
    }

    /// <summary>
    /// Rewrites a known physical offset as a root router for internal concurrency proof fixtures.<br/>
    /// This method exists to force a stale physical-shape observation after a writer context has staged private shelf bytes; production topology mutation paths should use the shape-specific split/transform methods instead.<br/>
    /// </summary>
    /// <param name="offset">The physical offset to overwrite with root-router bytes.<br/></param>
    /// <param name="allocationClassId">The allocation class id to persist in the proof router header.<br/></param>
    /// <returns>The DataKernel commit telemetry for the proof rewrite.<br/></returns>
    internal DataKernelCommitTelemetry RewriteOffsetAsRootRouterForConcurrencyProof(long offset, ushort allocationClassId)
    {
        if (offset <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(offset), offset, "The proof router offset must be a positive DataKernel offset.");
        }

        RawDataReservation router = kernel.ReserveAt(offset, RouterLayout.Size);
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeRoot(allocationClassId);
        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The concurrency proof router rewrite did not produce a valid direct-index router.");
        }

        return kernel.Commit();
    }

    /// <summary>
    /// Creates a fully expanded one-byte root router for the current `SS8-8` profile and returns a runtime index handle with the commit result.<br/>
    /// This is the first handle-acquisition path for new indexes: the index-directory slot remains the durable metadata source, while the returned handle is runtime-only and avoids passing root offset plus profile separately.<br/>
    /// Supported directory profile tuples map to named `Scalar8Scalar8Profile` shelf extents; unsupported profile IDs fail fast so reopen never guesses a shelf size.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router offset is supplied by this method.</param>
    /// <returns>The runtime `SS8-8` handle, created router snapshot, and DataKernel commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the slot profile identifiers do not describe the current `SS8-8` index profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slot index is outside the fixed directory.</exception>
    internal (Scalar8Scalar8IndexHandle Index, RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8RootRouterIndex(IndexDirectorySlotSnapshot slot)
    {
        Scalar8Scalar8Profile profile = GetScalar8Scalar8ProfileForSlot(slot);
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot);
        return (new Scalar8Scalar8IndexHandle(router.Offset, profile), router, commit);
    }

    /// <summary>
    /// Creates a fully expanded one-byte root router for an internal `VS8` varlen index and returns a runtime handle with the commit result.<br/>
    /// The handle carries only runtime policy values in this slice; persisted profile metadata for public varlen indexes remains a later API decision.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router offset is supplied by this method.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the runtime index.</param>
    /// <param name="optimizerRouteFanout">The compressed-route fanout requested by optimizer maintenance.</param>
    /// <param name="optimizerPolicy">The internal optimizer observation and maintenance scheduling policy.</param>
    /// <returns>The runtime `VS8` handle, created router snapshot, and DataKernel commit telemetry.</returns>
    internal (VarKeyScalar8IndexHandle Index, RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateVarKeyScalar8RootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        int maxKeyLength,
        int optimizerRouteFanout,
        VarLenOptimizerMaintenancePolicy optimizerPolicy)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot);
        VarKeyScalar8IndexHandle handle = new(router.Offset, maxKeyLength, optimizerRouteFanout, optimizerPolicy);
        handle.Validate();
        return (handle, router, commit);
    }

    /// <summary>
    /// Creates a fully expanded one-byte root router for a metadata-backed public `VS8` varlen index and returns a runtime handle with the commit result.<br/>
    /// The metadata is persisted beside the fixed index-directory slot in the same commit so reopen can reconstruct logical string projection ownership without parsing slot names.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router and metadata offsets are supplied by this method.</param>
    /// <param name="metadata">The catalog metadata to persist for this variable-key index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the runtime index.</param>
    /// <param name="optimizerRouteFanout">The compressed-route fanout requested by optimizer maintenance.</param>
    /// <param name="optimizerPolicy">The internal optimizer observation and maintenance scheduling policy.</param>
    /// <returns>The runtime `VS8` handle, created router snapshot, and DataKernel commit telemetry.</returns>
    internal (VarKeyScalar8IndexHandle Index, RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateVarKeyScalar8RootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        int maxKeyLength,
        int optimizerRouteFanout,
        VarLenOptimizerMaintenancePolicy optimizerPolicy)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot, metadata);
        VarKeyScalar8IndexHandle handle = new(router.Offset, maxKeyLength, optimizerRouteFanout, optimizerPolicy);
        handle.Validate();
        return (handle, router, commit);
    }

    /// <summary>
    /// Creates a metadata-backed single-shelf `FixedNScalar8` index and returns its runtime handle.<br/>
    /// This is the first programmable fixed-key durable bridge; later routed FSN storage can replace the shelf root with a router while preserving the public BigInt shape metadata.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The catalog metadata to persist for this fixed-key index.</param>
    /// <param name="profile">The programmable fixed-key shelf profile.</param>
    /// <returns>The runtime `FSN-8` handle and commit telemetry.</returns>
    internal (FixedNScalar8IndexHandle Index, DataKernelCommitTelemetry Commit) CreateFixedNScalar8ShelfIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        FixedNScalar8Profile profile)
    {
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(metadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, metadata);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        FixedNScalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();

        DataKernelCommitTelemetry commit = UpsertIndexDirectorySlot(slot with
        {
            MetadataOffset = metadataReservation.Extent.Offset,
            RootRouterOffset = shelfReservation.Extent.Offset,
            ItemCount = 0
        });
        FixedNScalar8IndexHandle handle = new(shelfReservation.Extent.Offset, profile, IsRouted: false);
        handle.Validate();
        return (handle, commit);
    }

    /// <summary>
    /// Creates a metadata-backed root-router `FixedNScalar8` index and returns its runtime handle.<br/>
    /// Root-prefix routing keeps the public fixed BigInt facade from depending on a single shelf while deeper same-prefix splits are developed.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The catalog metadata to persist for this fixed-key index.</param>
    /// <param name="profile">The programmable fixed-key shelf profile.</param>
    /// <returns>The runtime routed `FSN-8` handle and commit telemetry.</returns>
    internal (FixedNScalar8IndexHandle Index, DataKernelCommitTelemetry Commit) CreateFixedNScalar8RootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        FixedNScalar8Profile profile)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot, metadata);
        FixedNScalar8IndexHandle handle = new(router.Offset, profile, IsRouted: true);
        handle.Validate();
        return (handle, commit);
    }

    /// <summary>
    /// Creates a metadata-backed root-router `FV` index and returns its runtime handle.<br/>
    /// This keeps fixed-width key routing durable while variable-length identities remain stored inside shelf-local record arenas.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The catalog metadata to persist for this fixed-key index.</param>
    /// <param name="profile">The programmable fixed-key / variable-identity shelf profile.</param>
    /// <returns>The runtime routed `FV` handle and commit telemetry.</returns>
    internal (FixedNVarIdentityIndexHandle Index, DataKernelCommitTelemetry Commit) CreateFixedNVarIdentityRootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        FixedNVarIdentityProfile profile)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot, metadata);
        FixedNVarIdentityIndexHandle handle = new(router.Offset, profile, IsRouted: true);
        handle.Validate();
        return (handle, commit);
    }

    /// <summary>
    /// Opens a single-shelf `FixedNScalar8` index from an active directory slot.<br/>
    /// The pointed shelf is validated against the supplied programmable fixed-key profile before a handle is returned.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to open.</param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.</param>
    /// <returns>The runtime `FSN-8` handle.</returns>
    internal FixedNScalar8IndexHandle OpenFixedNScalar8ShelfIndex(int slotIndex, FixedNScalar8Profile profile)
    {
        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-8 index slot is not active.");
        }

        byte[] rootBytes = new byte[Math.Max(RouterLayout.Size, profile.ShelfExtentSize)];
        kernel.Read(slot.RootRouterOffset, rootBytes.AsSpan(0, RouterLayout.Size));
        RouterReader router = new(rootBytes.AsSpan(0, RouterLayout.Size));
        if (router.IsValid)
        {
            FixedNScalar8IndexHandle routedHandle = new(slot.RootRouterOffset, profile, IsRouted: true);
            routedHandle.Validate();
            return routedHandle;
        }

        kernel.Read(slot.RootRouterOffset, rootBytes.AsSpan(0, profile.ShelfExtentSize));
        FixedNScalar8ReadOnly shelf = new(rootBytes.AsSpan(0, profile.ShelfExtentSize), profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The persisted FSN-8 root is neither a valid router nor a valid single shelf.");
        }

        FixedNScalar8IndexHandle shelfHandle = new(slot.RootRouterOffset, profile, IsRouted: false);
        shelfHandle.Validate();
        return shelfHandle;
    }

    /// <summary>
    /// Reads the current bytes for a single-shelf `FixedNScalar8` index handle.<br/>
    /// The returned array is disconnected so callers can mutate it before explicitly publishing a rewrite.<br/>
    /// </summary>
    /// <param name="handle">The `FSN-8` index handle.</param>
    /// <returns>A disconnected copy of the shelf bytes.</returns>
    internal byte[] ReadFixedNScalar8ShelfBytes(FixedNScalar8IndexHandle handle)
    {
        handle.Validate();
        if (handle.IsRouted)
        {
            throw new ArgumentException("A routed FSN-8 handle does not point directly at a shelf.", nameof(handle));
        }

        return ReadFixedNScalar8ShelfBytes(handle.RootOffset, handle.Profile);
    }

    /// <summary>
    /// Reads a single `FixedNScalar8` shelf from a direct shelf offset.<br/>
    /// The returned array is disconnected so callers can mutate it before explicitly publishing a rewrite.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the shelf to read.</param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.</param>
    /// <returns>A disconnected copy of the shelf bytes.</returns>
    internal byte[] ReadFixedNScalar8ShelfBytes(long shelfOffset, FixedNScalar8Profile profile)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        FixedNScalar8ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The persisted FSN-8 shelf bytes are invalid.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Reads only the `FSN-8` shelf header and returns the persisted live item count.<br/>
    /// Count-all uses this path so it does not pull the fixed-key item arena into memory when the header already carries the needed count.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the `FSN-8` shelf.<br/></param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.<br/></param>
    /// <returns>The validated shelf-local item count.<br/></returns>
    internal long ReadFixedNScalar8ShelfItemCountNarrow(long shelfOffset, FixedNScalar8Profile profile)
    {
        Span<byte> header = stackalloc byte[FixedNScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (FixedNScalar8Layout.ReadMagic(header) != FixedNScalar8Layout.Magic ||
            FixedNScalar8Layout.ReadFormatVersion(header) != FixedNScalar8Layout.FormatVersion ||
            FixedNScalar8Layout.ReadHeaderSize(header) != FixedNScalar8Layout.HeaderSize ||
            FixedNScalar8Layout.ReadKeySize(header) != profile.KeySize)
        {
            throw new InvalidDataException("The persisted FSN-8 shelf header is invalid.");
        }

        ushort count = FixedNScalar8Layout.ReadItemCount(header);
        if (count > profile.MaxItemCount)
        {
            throw new InvalidDataException("The persisted FSN-8 shelf item count exceeds the profile capacity.");
        }

        return count;
    }

    /// <summary>
    /// Reads a single `FV` shelf from a direct shelf offset.<br/>
    /// The returned array is disconnected so callers can mutate it before explicitly publishing a rewrite.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the shelf to read.</param>
    /// <param name="profile">The expected programmable fixed-key / variable-identity shelf profile.</param>
    /// <returns>A disconnected copy of the shelf bytes.</returns>
    internal byte[] ReadFixedNVarIdentityShelfBytes(long shelfOffset, FixedNVarIdentityProfile profile)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        LibraDex.Views.FixedNVarIdentityReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The persisted FV shelf bytes are invalid.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Reads only the `FV` shelf header and returns the persisted live item count.<br/>
    /// Count-all uses this path so variable identity payloads stay untouched when shelf metadata already carries the count.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the `FV` shelf.<br/></param>
    /// <param name="profile">The expected programmable fixed-key / variable-identity shelf profile.<br/></param>
    /// <returns>The validated shelf-local item count.<br/></returns>
    internal long ReadFixedNVarIdentityShelfItemCountNarrow(long shelfOffset, FixedNVarIdentityProfile profile)
    {
        FixedNVarIdentityShelfCountCacheKey cacheKey = new(shelfOffset, profile.ShelfExtentSize, profile.KeySize, profile.MaxIdentityLength);
        if (TryGetFixedNVarIdentityShelfCountCache(cacheKey, out long cachedCount))
        {
            return cachedCount;
        }

        Span<byte> header = stackalloc byte[FixedNVarIdentityLayout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (FixedNVarIdentityLayout.ReadMagic(header) != FixedNVarIdentityLayout.Magic ||
            FixedNVarIdentityLayout.ReadFormatVersion(header) != FixedNVarIdentityLayout.FormatVersion ||
            FixedNVarIdentityLayout.ReadHeaderSize(header) != FixedNVarIdentityLayout.HeaderSize ||
            FixedNVarIdentityLayout.ReadShelfExtentSize(header) != profile.ShelfExtentSize)
        {
            throw new InvalidDataException("The persisted FV shelf header is invalid.");
        }

        int count = FixedNVarIdentityLayout.ReadItemCount(header);
        int slotStreamLength = FixedNVarIdentityLayout.ReadSlotStreamLength(header);
        int slotCapacityBytes = FixedNVarIdentityLayout.ReadSlotCapacityBytes(header);
        int recordArenaEnd = FixedNVarIdentityLayout.ReadRecordArenaEnd(header);
        int expectedSlotCapacityBytes = FixedNVarIdentityLayout.CalculateSlotCapacityBytes(profile.ShelfExtentSize, profile.KeySize);
        if (count < 0 ||
            count > profile.MaxItemCount ||
            slotStreamLength != checked(count * FixedNVarIdentityLayout.SlotSize) ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            recordArenaEnd < FixedNVarIdentityLayout.HeaderSize + slotCapacityBytes ||
            recordArenaEnd > profile.ShelfExtentSize)
        {
            throw new InvalidDataException("The persisted FV shelf count metadata is invalid.");
        }

        StoreFixedNVarIdentityShelfCountCache(cacheKey, count);
        return count;
    }

    /// <summary>
    /// Tries to read a session-local narrow count projection for one `FV` shelf.<br/>
    /// The key includes the physical profile dimensions so programmable fixed-key widths and variable identity limits do not share cached projections.<br/>
    /// Entries are invalidated by the shared raw-storage mutation version, keeping the cache free and in-memory only.<br/>
    /// </summary>
    /// <param name="key">The physical `FV` shelf count cache key.<br/></param>
    /// <param name="count">Receives the cached item count when a current entry is available.<br/></param>
    /// <returns><see langword="true"/> when a current count projection was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetFixedNVarIdentityShelfCountCache(FixedNVarIdentityShelfCountCacheKey key, out long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (fixedNVarIdentityShelfCountCache.TryGetValue(key, out count) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        count = 0;
        return false;
    }


    /// <summary>
    /// Stores one validated `FV` shelf count projection at the current raw-storage mutation version.<br/>
    /// The count is copied from a shelf header the current count operation already validated, so repeated count-all calls avoid rereads without adding any persisted metadata write.<br/>
    /// </summary>
    /// <param name="key">The physical `FV` shelf count cache key.<br/></param>
    /// <param name="count">The validated live item count read from the shelf header.<br/></param>
    private void StoreFixedNVarIdentityShelfCountCache(FixedNVarIdentityShelfCountCacheKey key, long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            fixedNVarIdentityShelfCountCache[key] = count;
        }
    }

    /// <summary>
    /// Rewrites a direct `FV` shelf in place.<br/>
    /// The shelf header carries the physical count, so ordinary same-shelf mutations do not rewrite the fixed index directory.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed directory slot that owns the shelf.</param>
    /// <param name="handle">The direct `FV` handle.</param>
    /// <param name="shelfBytes">The validated shelf bytes to publish.</param>
    /// <returns>The commit telemetry for the rewrite.</returns>
    internal DataKernelCommitTelemetry RewriteFixedNVarIdentityShelf(
        int slotIndex,
        FixedNVarIdentityIndexHandle handle,
        ReadOnlySpan<byte> shelfBytes)
    {
        handle.Validate();
        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FV index slot is not active.");
        }

        if (handle.IsRouted)
        {
            throw new ArgumentException("A routed FV handle does not point directly at a shelf.", nameof(handle));
        }

        RawDataReservation shelfReservation = kernel.ReserveAt(handle.RootOffset, handle.Profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Creates a metadata-backed single-shelf `FixedNScalar16` index and returns its runtime handle.<br/>
    /// This is the first fixed BigInt bridge for 16-byte scalar identities; routed `FSN-16` split behavior remains a later slice.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The catalog metadata to persist for this fixed-key index.</param>
    /// <param name="profile">The programmable fixed-key shelf profile.</param>
    /// <returns>The runtime `FSN-16` handle and commit telemetry.</returns>
    internal (FixedNScalar16IndexHandle Index, DataKernelCommitTelemetry Commit) CreateFixedNScalar16ShelfIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        FixedNScalar16Profile profile)
    {
        int metadataLength = CatalogIndexMetadataCodec.GetEncodedSize(metadata);
        RawDataReservation metadataReservation = kernel.Reserve(metadataLength);
        CatalogIndexMetadataCodec.Write(metadataReservation.Span, metadata);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        FixedNScalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();

        DataKernelCommitTelemetry commit = UpsertIndexDirectorySlot(slot with
        {
            MetadataOffset = metadataReservation.Extent.Offset,
            RootRouterOffset = shelfReservation.Extent.Offset,
            ItemCount = 0
        });
        FixedNScalar16IndexHandle handle = new(shelfReservation.Extent.Offset, profile, IsRouted: false);
        handle.Validate();
        return (handle, commit);
    }

    /// <summary>
    /// Creates a metadata-backed root-router `FixedNScalar16` index and returns its runtime handle.<br/>
    /// Root-prefix routing gives fixed BigInt indexes with 16-byte identities the same growth path as `FSN-8`.<br/>
    /// </summary>
    /// <param name="slot">The fixed index-directory slot values to persist.</param>
    /// <param name="metadata">The catalog metadata to persist for this fixed-key index.</param>
    /// <param name="profile">The programmable fixed-key shelf profile.</param>
    /// <returns>The runtime routed `FSN-16` handle and commit telemetry.</returns>
    internal (FixedNScalar16IndexHandle Index, DataKernelCommitTelemetry Commit) CreateFixedNScalar16RootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        CatalogIndexMetadata metadata,
        FixedNScalar16Profile profile)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot, metadata);
        FixedNScalar16IndexHandle handle = new(router.Offset, profile, IsRouted: true);
        handle.Validate();
        return (handle, commit);
    }

    /// <summary>
    /// Opens a single-shelf `FixedNScalar16` index from an active directory slot.<br/>
    /// The pointed shelf is validated against the supplied programmable fixed-key profile before a handle is returned.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to open.</param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.</param>
    /// <returns>The runtime `FSN-16` handle.</returns>
    internal FixedNScalar16IndexHandle OpenFixedNScalar16ShelfIndex(int slotIndex, FixedNScalar16Profile profile)
    {
        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-16 index slot is not active.");
        }

        byte[] rootBytes = new byte[Math.Max(RouterLayout.Size, profile.ShelfExtentSize)];
        kernel.Read(slot.RootRouterOffset, rootBytes.AsSpan(0, RouterLayout.Size));
        RouterReader router = new(rootBytes.AsSpan(0, RouterLayout.Size));
        if (router.IsValid)
        {
            FixedNScalar16IndexHandle routedHandle = new(slot.RootRouterOffset, profile, IsRouted: true);
            routedHandle.Validate();
            return routedHandle;
        }

        kernel.Read(slot.RootRouterOffset, rootBytes.AsSpan(0, profile.ShelfExtentSize));
        FixedNScalar16ReadOnly shelf = new(rootBytes.AsSpan(0, profile.ShelfExtentSize), profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The persisted FSN-16 root is neither a valid router nor a valid single shelf.");
        }

        FixedNScalar16IndexHandle shelfHandle = new(slot.RootRouterOffset, profile, IsRouted: false);
        shelfHandle.Validate();
        return shelfHandle;
    }

    /// <summary>
    /// Reads the current bytes for a single-shelf `FixedNScalar16` index handle.<br/>
    /// The returned array is disconnected so callers can mutate it before explicitly publishing a rewrite.<br/>
    /// </summary>
    /// <param name="handle">The `FSN-16` index handle.</param>
    /// <returns>A disconnected copy of the shelf bytes.</returns>
    internal byte[] ReadFixedNScalar16ShelfBytes(FixedNScalar16IndexHandle handle)
    {
        handle.Validate();
        if (handle.IsRouted)
        {
            throw new ArgumentException("A routed FSN-16 handle does not point directly at a shelf.", nameof(handle));
        }

        return ReadFixedNScalar16ShelfBytes(handle.RootOffset, handle.Profile);
    }

    /// <summary>
    /// Reads a single `FixedNScalar16` shelf from a direct shelf offset.<br/>
    /// The returned array is disconnected so callers can mutate it before explicitly publishing a rewrite.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the shelf to read.</param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.</param>
    /// <returns>A disconnected copy of the shelf bytes.</returns>
    internal byte[] ReadFixedNScalar16ShelfBytes(long shelfOffset, FixedNScalar16Profile profile)
    {
        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        FixedNScalar16ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The persisted FSN-16 shelf bytes are invalid.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Reads only the `FSN-16` shelf header and returns the persisted live item count.<br/>
    /// Count-all uses this path so it avoids reading fixed-key payload and sixteen-byte identity lanes when the header count is sufficient.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the `FSN-16` shelf.<br/></param>
    /// <param name="profile">The expected programmable fixed-key shelf profile.<br/></param>
    /// <returns>The validated shelf-local item count.<br/></returns>
    internal long ReadFixedNScalar16ShelfItemCountNarrow(long shelfOffset, FixedNScalar16Profile profile)
    {
        Span<byte> header = stackalloc byte[FixedNScalar16Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (FixedNScalar16Layout.ReadMagic(header) != FixedNScalar16Layout.Magic ||
            FixedNScalar16Layout.ReadFormatVersion(header) != FixedNScalar16Layout.FormatVersion ||
            FixedNScalar16Layout.ReadHeaderSize(header) != FixedNScalar16Layout.HeaderSize ||
            FixedNScalar16Layout.ReadKeySize(header) != profile.KeySize)
        {
            throw new InvalidDataException("The persisted FSN-16 shelf header is invalid.");
        }

        ushort count = FixedNScalar16Layout.ReadItemCount(header);
        if (count > profile.MaxItemCount)
        {
            throw new InvalidDataException("The persisted FSN-16 shelf item count exceeds the profile capacity.");
        }

        return count;
    }

    /// <summary>
    /// Rewrites a single-shelf `FixedNScalar16` index in place.<br/>
    /// The shelf header carries the physical count, so ordinary same-shelf mutations do not rewrite the fixed index directory.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to update.</param>
    /// <param name="handle">The `FSN-16` index handle.</param>
    /// <param name="shelfBytes">The complete replacement shelf bytes.</param>
    /// <returns>The commit telemetry for the shelf rewrite.</returns>
    internal DataKernelCommitTelemetry RewriteFixedNScalar16Shelf(
        int slotIndex,
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> shelfBytes)
    {
        handle.Validate();
        if (shelfBytes.Length != handle.Profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FSN-16 shelf rewrite bytes must match the handle profile extent size.", nameof(shelfBytes));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-16 index slot is not active.");
        }

        if (handle.IsRouted)
        {
            throw new ArgumentException("A routed FSN-16 handle does not point directly at a shelf.", nameof(handle));
        }

        RawDataReservation shelfReservation = kernel.ReserveAt(handle.RootOffset, handle.Profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Inserts one tuple into a routed `FixedNScalar16` index and transforms full shelves into child routers when needed.<br/>
    /// The split behavior mirrors `FSN-8` while preserving the 16-byte identity tie-breaker bytes.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot that owns the routed index.</param>
    /// <param name="handle">The routed `FSN-16` handle.</param>
    /// <param name="key">The encoded fixed-width key bytes.</param>
    /// <param name="encodedIdentity">The encoded sortable scalar-16 identity bytes.</param>
    /// <param name="allowDuplicateKeys">True for non-unique index behavior; false for unique key behavior.</param>
    /// <returns>The insert result and commit telemetry.</returns>
    internal (FixedNScalarInsertResult Result, DataKernelCommitTelemetry Commit) InsertRoutedFixedNScalar16RootNoSplit(
        int slotIndex,
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> encodedIdentity,
        bool allowDuplicateKeys)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 root-prefix insertion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (encodedIdentity.Length != FixedNScalar16Layout.IdentitySize)
        {
            throw new ArgumentException("FSN-16 encoded identity length must be sixteen bytes.", nameof(encodedIdentity));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-16 index slot is not active.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        long routerOffset = handle.RootOffset;
        for (int hop = 0; hop < handle.Profile.KeySize; hop++)
        {
            kernel.Read(routerOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The routed FSN-16 router is invalid.");
            }

            byte prefix = key[routerReader.KeyDepth];
            long targetOffset = routerReader.FindTarget(prefix);
            if (targetOffset == 0)
            {
                RawDataReservation shelfReservation = kernel.Reserve(handle.Profile.ShelfExtentSize);
                FixedNScalar16 shelf = new(shelfReservation.Span, handle.Profile);
                shelf.Initialize();
                FixedNScalarInsertResult result = shelf.Insert(key, encodedIdentity, allowDuplicateKeys);
                if (result != FixedNScalarInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected first FSN-16 routed shelf insert to succeed, got {result}.");
                }

                RawDataReservation routerReservation = kernel.ReserveAt(routerOffset, RouterLayout.Size);
                routerBytes.CopyTo(routerReservation.Span);
                RouterWriter routerWriter = new(routerReservation.Span);
                routerWriter.WriteRoute(prefix, prefix, prefix, shelfReservation.Extent.Offset);
                InvalidateRouterReadCacheForRouterRewrite(routerOffset);
                DataKernelCommitTelemetry createCommit = CommitAndDeferRouterReadCacheInvalidation();
                return (result, createCommit);
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                routerOffset = targetOffset;
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar16ShelfBytes(targetOffset, handle.Profile);
            FixedNScalar16 existingShelf = new(shelfBytes, handle.Profile);
            FixedNScalarInsertResult insertResult = existingShelf.Insert(key, encodedIdentity, allowDuplicateKeys);
            if (insertResult != FixedNScalarInsertResult.Inserted)
            {
                if (insertResult == FixedNScalarInsertResult.Full)
                {
                    return SplitRoutedFixedNScalar16ByShelfTransform(
                        slotIndex,
                        slot,
                        handle,
                        targetOffset,
                        shelfBytes,
                        checked((ushort)(routerReader.KeyDepth + 1)),
                        key,
                        encodedIdentity,
                        allowDuplicateKeys);
                }

                return (insertResult, default);
            }

            RawDataReservation shelfRewrite = kernel.ReserveAt(targetOffset, handle.Profile.ShelfExtentSize);
            shelfBytes.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry rewriteCommit = CommitWithoutInvalidatingRouterReadCache();
            return (insertResult, rewriteCommit);
        }

        throw new InvalidDataException("The routed FSN-16 insert exceeded the fixed key depth.");
    }

    /// <summary>
    /// Deletes one exact tuple from a routed `FixedNScalar16` index without attempting route merge or empty-route cleanup.<br/>
    /// The operation follows the encoded key through child routers, compacts the selected leaf shelf, rewrites that shelf, and decrements the owning index-directory item count.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot that owns the routed index.<br/></param>
    /// <param name="handle">The routed `FSN-16` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-16 identity bytes.<br/></param>
    /// <returns>The delete result and commit telemetry.<br/></returns>
    internal (bool Deleted, DataKernelCommitTelemetry Commit) DeleteRoutedFixedNScalar16RootNoMerge(
        int slotIndex,
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> encodedIdentity)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 root-prefix deletion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (encodedIdentity.Length != FixedNScalar16Layout.IdentitySize)
        {
            throw new ArgumentException("FSN-16 encoded identity length must be sixteen bytes.", nameof(encodedIdentity));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-16 index slot is not active.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        long routerOffset = handle.RootOffset;
        for (int hop = 0; hop < handle.Profile.KeySize; hop++)
        {
            kernel.Read(routerOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The routed FSN-16 router is invalid.");
            }

            long targetOffset = routerReader.FindTarget(key[routerReader.KeyDepth]);
            if (targetOffset == 0)
            {
                return (false, default);
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                routerOffset = targetOffset;
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar16ShelfBytes(targetOffset, handle.Profile);
            FixedNScalar16 shelf = new(shelfBytes, handle.Profile);
            if (!shelf.Delete(key, encodedIdentity))
            {
                return (false, default);
            }

            RawDataReservation shelfRewrite = kernel.ReserveAt(targetOffset, handle.Profile.ShelfExtentSize);
            shelfBytes.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry commit = CommitWithoutInvalidatingRouterReadCache();
            return (true, commit);
        }

        throw new InvalidDataException("The routed FSN-16 delete exceeded the fixed key depth.");
    }

    /// <summary>
    /// Inserts one tuple into an already-routed `FSN-16` leaf shelf using a writer-local context.<br/>
    /// The route must resolve to an existing shelf with available capacity; route creation and full-shelf transforms stay on the serialized topology path.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="handle">The routed `FSN-16` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-16 identity bytes.<br/></param>
    /// <param name="allowDuplicateKeys">True for non-unique index behavior; false for unique key behavior.<br/></param>
    /// <returns>The insert result; commit telemetry is deferred to writer-context publication.<br/></returns>
    internal (bool Handled, FixedNScalarInsertResult Result) InsertRoutedFixedNScalar16NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> encodedIdentity,
        bool allowDuplicateKeys)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 writer-context insertion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (encodedIdentity.Length != FixedNScalar16Layout.IdentitySize)
        {
            throw new ArgumentException("FSN-16 encoded identity length must be sixteen bytes.", nameof(encodedIdentity));
        }

        EnterFixedNScalar16WriterContextStaging(handle.RootOffset);
        try
        {
            Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
            long routerOffset = handle.RootOffset;
            for (int hop = 0; hop < handle.Profile.KeySize; hop++)
            {
                kernel.Read(routerOffset, routerBytes);
                RouterReader routerReader = new(routerBytes);
                if (!routerReader.IsValid || !routerReader.HasDirectIndex)
                {
                    throw new InvalidDataException("The routed FSN-16 router is invalid.");
                }

                byte routePrefixByte = key[routerReader.KeyDepth];
                long targetOffset = routerReader.FindTarget(routePrefixByte);
                if (targetOffset == 0)
                {
                    return (false, default);
                }

                if (IsFixedNScalar16Router(targetOffset))
                {
                    routerOffset = targetOffset;
                    continue;
                }

                RecordFixedNScalar16RouteClaimForWriteContext(
                    writeContext,
                    routerOffset,
                    routePrefixByte,
                    targetOffset,
                    handle.Profile);
                byte[] shelfBytes = ReadFixedNScalar16ShelfBytesForWriteContext(writeContext, targetOffset, handle.Profile);
                FixedNScalar16 shelf = new(shelfBytes, handle.Profile);
                FixedNScalarInsertResult result = shelf.Insert(key, encodedIdentity, allowDuplicateKeys);
                if (result == FixedNScalarInsertResult.Full)
                {
                    return (false, default);
                }

                if (result == FixedNScalarInsertResult.Inserted)
                {
                    StageFixedNScalar16ShelfRewriteForWriteContext(writeContext, targetOffset, handle.Profile, shelfBytes);
                }

                return (true, result);
            }

            throw new InvalidDataException("The routed FSN-16 writer-context insert exceeded the fixed key depth.");
        }
        finally
        {
            ExitFixedNScalar16WriterContextStaging(handle.RootOffset);
        }
    }

    /// <summary>
    /// Deletes one exact tuple from an already-routed `FSN-16` leaf shelf using a writer-local context.<br/>
    /// The operation stages only the selected leaf shelf; empty-route cleanup and merge work stay out of this hot concurrent path.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="handle">The routed `FSN-16` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-16 identity bytes.<br/></param>
    /// <returns><see langword="true"/> when one tuple was staged for deletion; otherwise <see langword="false"/>.<br/></returns>
    internal bool DeleteRoutedFixedNScalar16ExactForWriteContext(
        LibraDexWriteContext writeContext,
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> encodedIdentity)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 writer-context deletion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (encodedIdentity.Length != FixedNScalar16Layout.IdentitySize)
        {
            throw new ArgumentException("FSN-16 encoded identity length must be sixteen bytes.", nameof(encodedIdentity));
        }

        EnterFixedNScalar16WriterContextStaging(handle.RootOffset);
        try
        {
            Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
            long routerOffset = handle.RootOffset;
            for (int hop = 0; hop < handle.Profile.KeySize; hop++)
            {
                kernel.Read(routerOffset, routerBytes);
                RouterReader routerReader = new(routerBytes);
                if (!routerReader.IsValid || !routerReader.HasDirectIndex)
                {
                    throw new InvalidDataException("The routed FSN-16 router is invalid.");
                }

                byte routePrefixByte = key[routerReader.KeyDepth];
                long targetOffset = routerReader.FindTarget(routePrefixByte);
                if (targetOffset == 0)
                {
                    return false;
                }

                if (IsFixedNScalar16Router(targetOffset))
                {
                    routerOffset = targetOffset;
                    continue;
                }

                RecordFixedNScalar16RouteClaimForWriteContext(
                    writeContext,
                    routerOffset,
                    routePrefixByte,
                    targetOffset,
                    handle.Profile);
                byte[] shelfBytes = ReadFixedNScalar16ShelfBytesForWriteContext(writeContext, targetOffset, handle.Profile);
                FixedNScalar16 shelf = new(shelfBytes, handle.Profile);
                if (!shelf.Delete(key, encodedIdentity))
                {
                    return false;
                }

                StageFixedNScalar16ShelfRewriteForWriteContext(writeContext, targetOffset, handle.Profile, shelfBytes);
                return true;
            }

            throw new InvalidDataException("The routed FSN-16 writer-context delete exceeded the fixed key depth.");
        }
        finally
        {
            ExitFixedNScalar16WriterContextStaging(handle.RootOffset);
        }
    }

    private bool IsFixedNScalar16Router(long offset)
    {
        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        kernel.Read(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        return reader.IsValid;
    }

    private (FixedNScalarInsertResult Result, DataKernelCommitTelemetry Commit) SplitRoutedFixedNScalar16ByShelfTransform(
        int slotIndex,
        IndexDirectorySlotSnapshot slot,
        FixedNScalar16IndexHandle handle,
        long fullShelfOffset,
        byte[] existingShelfBytes,
        ushort firstKeyDepth,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> encodedIdentity,
        bool allowDuplicateKeys)
    {
        _ = slotIndex;
        FixedNScalar16ReadOnly existingShelf = new(existingShelfBytes, handle.Profile);
        if (!existingShelf.IsValid)
        {
            throw new InvalidDataException("The routed FSN-16 shelf selected for transform split is invalid.");
        }

        int existingCount = existingShelf.ItemCount;
        byte[][] keys = new byte[existingCount + 1][];
        byte[][] identities = new byte[existingCount + 1][];
        bool inserted = false;
        int writeIndex = 0;
        for (int slotOrdinal = 0; slotOrdinal < existingCount; slotOrdinal++)
        {
            byte[] currentKey = new byte[handle.Profile.KeySize];
            byte[] currentIdentity = new byte[FixedNScalar16Layout.IdentitySize];
            existingShelf.CopyKeyAt(slotOrdinal, currentKey);
            existingShelf.CopyIdentityAt(slotOrdinal, currentIdentity);
            if (!inserted && CompareFixedNScalar16Tuple(currentKey, currentIdentity, key, encodedIdentity) > 0)
            {
                keys[writeIndex] = key.ToArray();
                identities[writeIndex] = encodedIdentity.ToArray();
                writeIndex++;
                inserted = true;
            }

            if (currentKey.AsSpan().SequenceEqual(key) && currentIdentity.AsSpan().SequenceEqual(encodedIdentity))
            {
                return (FixedNScalarInsertResult.AlreadyPresent, default);
            }

            if (!allowDuplicateKeys && currentKey.AsSpan().SequenceEqual(key))
            {
                return (FixedNScalarInsertResult.KeyConflict, default);
            }

            keys[writeIndex] = currentKey;
            identities[writeIndex] = currentIdentity;
            writeIndex++;
        }

        if (!inserted)
        {
            keys[writeIndex] = key.ToArray();
            identities[writeIndex] = encodedIdentity.ToArray();
        }

        if (!TryChooseFixedNScalar16Split(keys, firstKeyDepth, out ushort splitKeyDepth, out byte rightPrefixByte))
        {
            throw new InvalidDataException("The full FSN-16 shelf could not be split because all keys share every fixed-key byte.");
        }

        byte[] leftShelfBytes = new byte[handle.Profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[handle.Profile.ShelfExtentSize];
        FixedNScalar16 leftShelf = new(leftShelfBytes, handle.Profile);
        FixedNScalar16 rightShelf = new(rightShelfBytes, handle.Profile);
        leftShelf.Initialize();
        rightShelf.Initialize();
        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = keys[i][splitKeyDepth] >= rightPrefixByte;
            FixedNScalarInsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true);
            if (result != FixedNScalarInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FSN-16 split shelf insert to succeed, got {result}.");
            }
        }

        RawDataReservation leftAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - firstKeyDepth;
        long nextRouterOffset = 0;
        long[] appendedRouterOffsets = appendedRouterCount > 0 ? new long[appendedRouterCount] : [];
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            appendedRouterOffsets[i] = kernel.Reserve(RouterLayout.Size).Extent.Offset;
        }

        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(firstKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateFixedNScalar16SplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
                : CreateFixedNScalar16SingleTarget(keys[0][routerDepth], nextRouterOffset);
            RawDataReservation routerReservation = kernel.ReserveAt(appendedRouterOffsets[i], RouterLayout.Size);
            RouterWriter writer = new(routerReservation.Span);
            writer.InitializeExpandedOneByte(routerDepth, slot.AllocationClassId, targets);
            nextRouterOffset = appendedRouterOffsets[i];
        }

        long rootChildTarget = appendedRouterCount == 0 ? 0 : nextRouterOffset;
        long[] firstTargets = appendedRouterCount == 0
            ? CreateFixedNScalar16SplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
            : CreateFixedNScalar16SingleTarget(keys[0][firstKeyDepth], rootChildTarget);
        RawDataReservation transformedRouter = kernel.ReserveAt(fullShelfOffset, RouterLayout.Size);
        RouterWriter transformedWriter = new(transformedRouter.Span);
        transformedWriter.InitializeExpandedOneByte(firstKeyDepth, slot.AllocationClassId, firstTargets);

        InvalidateRouterReadCacheForRouterRewrite(fullShelfOffset);
        DataKernelCommitTelemetry commit = CommitAndDeferRouterReadCacheInvalidation();
        return (FixedNScalarInsertResult.Inserted, commit);
    }

    private static long[] CreateFixedNScalar16SplitTerminalTargets(
        IReadOnlyList<byte[]> keys,
        ushort splitKeyDepth,
        byte rightPrefixByte,
        long leftShelfOffset,
        long rightShelfOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < keys.Count; i++)
        {
            byte prefix = keys[i][splitKeyDepth];
            targets[prefix] = prefix >= rightPrefixByte ? rightShelfOffset : leftShelfOffset;
        }

        return targets;
    }

    private static long[] CreateFixedNScalar16SingleTarget(byte prefix, long targetOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        targets[prefix] = targetOffset;
        return targets;
    }

    private static bool TryChooseFixedNScalar16Split(
        IReadOnlyList<byte[]> sortedKeys,
        ushort firstKeyDepth,
        out ushort splitKeyDepth,
        out byte rightPrefixByte)
    {
        return TryChooseFixedNScalar8Split(sortedKeys, firstKeyDepth, out splitKeyDepth, out rightPrefixByte);
    }

    private static int CompareFixedNScalar16Tuple(ReadOnlySpan<byte> leftKey, ReadOnlySpan<byte> leftIdentity, ReadOnlySpan<byte> rightKey, ReadOnlySpan<byte> rightIdentity)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        return keyComparison != 0 ? keyComparison : leftIdentity.SequenceCompareTo(rightIdentity);
    }

    /// <summary>
    /// Reads encoded identities from a routed `FixedNScalar16` index over an inclusive fixed-key range.<br/>
    /// Traversal follows child routers and tracks visited shelves because multiple route prefixes can intentionally point to the same split shelf.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-16` handle.</param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.</param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.</param>
    /// <returns>Concatenated encoded scalar-16 identities matching the requested key range.</returns>
    internal byte[] ReadRoutedFixedNScalar16IdentityRange(
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 routed range reads require a routed handle.", nameof(handle));
        }

        if (lowerKey.Length != handle.Profile.KeySize || upperKey.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded range keys must match the handle profile key size.");
        }

        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The FSN-16 upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperKey));
        }

        List<byte[]> identities = new();
        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        ReadRoutedFixedNScalar16IdentityRangeFromRouter(handle.RootOffset, handle.Profile, lowerKey, upperKey, identities, visitedShelves, visitedRouters);
        byte[] result = new byte[identities.Count * FixedNScalar16Layout.IdentitySize];
        for (int i = 0; i < identities.Count; i++)
        {
            identities[i].CopyTo(result.AsSpan(i * FixedNScalar16Layout.IdentitySize, FixedNScalar16Layout.IdentitySize));
        }

        return result;
    }

    /// <summary>
    /// Counts all ordinary tuples reachable from a routed `FSN-16` index.<br/>
    /// Each leaf shelf is counted once from its header item count; the index-directory item count is intentionally not used as the public count source.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-16` handle.<br/></param>
    /// <returns>The summed ordinary tuple count across reachable routed shelves.<br/></returns>
    internal long CountRoutedFixedNScalar16Identities(FixedNScalar16IndexHandle handle)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 routed counts require a routed handle.", nameof(handle));
        }

        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        return CountRoutedFixedNScalar16IdentitiesFromRouter(handle.RootOffset, handle.Profile, visitedShelves, visitedRouters);
    }

    /// <summary>
    /// Counts routed `FSN-16` tuples whose keys are inside an inclusive encoded key range.<br/>
    /// Traversal follows the same router range pruning as identity reads, but leaf handling counts matching slots without copying identity bytes.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-16` handle.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <returns>The count of routed ordinary tuples in the requested range.<br/></returns>
    internal long CountRoutedFixedNScalar16IdentityRange(
        FixedNScalar16IndexHandle handle,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-16 routed range counts require a routed handle.", nameof(handle));
        }

        if (lowerKey.Length != handle.Profile.KeySize || upperKey.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-16 encoded range keys must match the handle profile key size.");
        }

        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The FSN-16 upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperKey));
        }

        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        return CountRoutedFixedNScalar16IdentityRangeFromRouter(
            handle.RootOffset,
            handle.Profile,
            lowerKey,
            upperKey,
            lowerEdge: true,
            upperEdge: true,
            visitedShelves,
            visitedRouters);
    }

    private long CountRoutedFixedNScalar16IdentitiesFromRouter(
        long routerOffset,
        FixedNScalar16Profile profile,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-16 router is invalid.");
        }

        long count = 0;
        for (int prefix = 0; prefix <= byte.MaxValue; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                count += CountRoutedFixedNScalar16IdentitiesFromRouter(targetOffset, profile, visitedShelves, visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            count += ReadFixedNScalar16ShelfItemCountNarrow(targetOffset, profile);
        }

        return count;
    }

    private long CountRoutedFixedNScalar16IdentityRangeFromRouter(
        long routerOffset,
        FixedNScalar16Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-16 router is invalid.");
        }

        long count = 0;
        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerEdge ? lowerKey[keyDepth] : byte.MinValue;
        byte endPrefix = upperEdge ? upperKey[keyDepth] : byte.MaxValue;
        long lowerTarget = lowerEdge ? routerReader.FindTarget(startPrefix) : 0;
        long upperTarget = upperEdge ? routerReader.FindTarget(endPrefix) : 0;
        if (lowerEdge && upperEdge && startPrefix != endPrefix && lowerTarget != 0 && lowerTarget == upperTarget)
        {
            return CountRoutedFixedNScalar16IdentityRangeByReaderLikeTraversal(routerReader, profile, lowerKey, upperKey, visitedShelves, visitedRouters);
        }

        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            bool childLowerEdge = lowerEdge && prefix == startPrefix;
            bool childUpperEdge = upperEdge && prefix == endPrefix;
            if (!childLowerEdge && !childUpperEdge && (targetOffset == lowerTarget || targetOffset == upperTarget))
            {
                return CountRoutedFixedNScalar16IdentityRangeByReaderLikeTraversal(routerReader, profile, lowerKey, upperKey, visitedShelves, visitedRouters);
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                count += childLowerEdge || childUpperEdge
                    ? CountRoutedFixedNScalar16IdentityRangeFromRouter(targetOffset, profile, lowerKey, upperKey, childLowerEdge, childUpperEdge, visitedShelves, visitedRouters)
                    : CountRoutedFixedNScalar16IdentitiesFromRouter(targetOffset, profile, visitedShelves, visitedRouters);
                continue;
            }

            count += childLowerEdge || childUpperEdge
                ? CountFixedNScalar16ShelfKeyRangeNarrow(targetOffset, profile, lowerKey, upperKey, visitedShelves)
                : CountFixedNScalar16ShelfCountNarrow(targetOffset, profile, visitedShelves);
        }

        return count;
    }

    /// <summary>
    /// Counts a routed `FSN-16` range with the pre-optimization traversal shape for ambiguous aliased route targets.<br/>
    /// The fallback preserves correctness when a direct router maps an interior prefix to the same physical target as a boundary prefix, because that target cannot be treated as fully contained.<br/>
    /// </summary>
    /// <param name="routerReader">The decoded router whose children should be counted.<br/></param>
    /// <param name="profile">The `FSN-16` shelf profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <param name="visitedRouters">The visited router offsets for cycle protection.<br/></param>
    /// <returns>The number of routed `FSN-16` tuples in the requested range.<br/></returns>
    private long CountRoutedFixedNScalar16IdentityRangeByReaderLikeTraversal(
        RouterReader routerReader,
        FixedNScalar16Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        long count = 0;
        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerKey[keyDepth];
        byte endPrefix = upperKey[keyDepth];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                count += CountRoutedFixedNScalar16IdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lowerKey,
                    upperKey,
                    lowerEdge: true,
                    upperEdge: true,
                    visitedShelves,
                    visitedRouters);
                continue;
            }

            count += CountFixedNScalar16ShelfKeyRangeNarrow(targetOffset, profile, lowerKey, upperKey, visitedShelves);
        }

        return count;
    }

    /// <summary>
    /// Counts every item in one `FSN-16` shelf target from its header metadata after visited-set filtering.<br/>
    /// This is used only for range targets whose route path proves the whole shelf is contained by the requested key range.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset to count.<br/></param>
    /// <param name="profile">The `FSN-16` shelf profile.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <returns>The shelf item count, or zero when the shelf was already counted.<br/></returns>
    private long CountFixedNScalar16ShelfCountNarrow(long shelfOffset, FixedNScalar16Profile profile, HashSet<long> visitedShelves)
    {
        return visitedShelves.Add(shelfOffset)
            ? ReadFixedNScalar16ShelfItemCountNarrow(shelfOffset, profile)
            : 0;
    }

    /// <summary>
    /// Counts only matching keys in one `FSN-16` shelf after visited-set filtering.<br/>
    /// Boundary range targets use this narrow slot scan because the route path does not prove every key in the shelf is contained.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset to inspect.<br/></param>
    /// <param name="profile">The `FSN-16` shelf profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <returns>The number of matching items in the shelf, or zero when the shelf was already counted.<br/></returns>
    private long CountFixedNScalar16ShelfKeyRangeNarrow(
        long shelfOffset,
        FixedNScalar16Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        HashSet<long> visitedShelves)
    {
        if (!visitedShelves.Add(shelfOffset))
        {
            return 0;
        }

        byte[] shelfBytes = ReadFixedNScalar16ShelfBytes(shelfOffset, profile);
        FixedNScalar16ReadOnly shelf = new(shelfBytes, profile);
        return shelf.CountItemsInKeyRange(lowerKey, upperKey);
    }

    private void ReadRoutedFixedNScalar16IdentityRangeFromRouter(
        long routerOffset,
        FixedNScalar16Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        List<byte[]> identities,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-16 router is invalid.");
        }

        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerKey[keyDepth];
        byte endPrefix = upperKey[keyDepth];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar16Router(targetOffset))
            {
                ReadRoutedFixedNScalar16IdentityRangeFromRouter(targetOffset, profile, lowerKey, upperKey, identities, visitedShelves, visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar16ShelfBytes(targetOffset, profile);
            FixedNScalar16ReadOnly shelf = new(shelfBytes, profile);
            byte[] shelfIdentities = new byte[shelf.ItemCount * FixedNScalar16Layout.IdentitySize];
            int copied = shelf.CopyIdentitiesInKeyRange(lowerKey, upperKey, shelfIdentities);
            for (int i = 0; i < copied; i++)
            {
                identities.Add(shelfIdentities.AsSpan(i * FixedNScalar16Layout.IdentitySize, FixedNScalar16Layout.IdentitySize).ToArray());
            }
        }
    }

    /// <summary>
    /// Rewrites a single-shelf `FixedNScalar8` index in place.<br/>
    /// The shelf header carries the physical count, so ordinary same-shelf mutations do not rewrite the fixed index directory.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot to update.</param>
    /// <param name="handle">The `FSN-8` index handle.</param>
    /// <param name="shelfBytes">The complete replacement shelf bytes.</param>
    /// <returns>The commit telemetry for the shelf rewrite.</returns>
    internal DataKernelCommitTelemetry RewriteFixedNScalar8Shelf(
        int slotIndex,
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> shelfBytes)
    {
        handle.Validate();
        if (shelfBytes.Length != handle.Profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FSN-8 shelf rewrite bytes must match the handle profile extent size.", nameof(shelfBytes));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-8 index slot is not active.");
        }

        if (handle.IsRouted)
        {
            throw new ArgumentException("A routed FSN-8 handle does not point directly at a shelf.", nameof(handle));
        }

        RawDataReservation shelfReservation = kernel.ReserveAt(handle.RootOffset, handle.Profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Inserts one tuple into a root-prefix routed `FixedNScalar8` index without deeper split handling.<br/>
    /// Missing root-prefix routes allocate and link a new shelf; existing root-prefix shelves are rewritten in place when they have capacity.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot that owns the routed index.</param>
    /// <param name="handle">The routed `FSN-8` handle.</param>
    /// <param name="key">The encoded fixed-width key bytes.</param>
    /// <param name="encodedIdentity">The encoded sortable scalar-8 identity.</param>
    /// <param name="allowDuplicateKeys">True for non-unique index behavior; false for unique key behavior.</param>
    /// <returns>The insert result and commit telemetry.</returns>
    internal (FixedNScalarInsertResult Result, DataKernelCommitTelemetry Commit) InsertRoutedFixedNScalar8RootNoSplit(
        int slotIndex,
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 root-prefix insertion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-8 index slot is not active.");
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        long routerOffset = handle.RootOffset;
        long targetOffset;
        byte prefix;
        for (int hop = 0; hop < handle.Profile.KeySize; hop++)
        {
            kernel.Read(routerOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The routed FSN-8 router is invalid.");
            }

            prefix = key[routerReader.KeyDepth];
            targetOffset = routerReader.FindTarget(prefix);
            if (targetOffset == 0)
            {
                RawDataReservation shelfReservation = kernel.Reserve(handle.Profile.ShelfExtentSize);
                FixedNScalar8 shelf = new(shelfReservation.Span, handle.Profile);
                shelf.Initialize();
                FixedNScalarInsertResult result = shelf.Insert(key, encodedIdentity, allowDuplicateKeys);
                if (result != FixedNScalarInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected first FSN-8 routed shelf insert to succeed, got {result}.");
                }

                RawDataReservation routerReservation = kernel.ReserveAt(routerOffset, RouterLayout.Size);
                routerBytes.CopyTo(routerReservation.Span);
                RouterWriter routerWriter = new(routerReservation.Span);
                routerWriter.WriteRoute(prefix, prefix, prefix, shelfReservation.Extent.Offset);
                InvalidateRouterReadCacheForRouterRewrite(routerOffset);
                DataKernelCommitTelemetry createCommit = CommitAndDeferRouterReadCacheInvalidation();
                return (result, createCommit);
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                routerOffset = targetOffset;
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar8ShelfBytes(targetOffset, handle.Profile);
            FixedNScalar8 existingShelf = new(shelfBytes, handle.Profile);
            FixedNScalarInsertResult insertResult = existingShelf.Insert(key, encodedIdentity, allowDuplicateKeys);
            if (insertResult != FixedNScalarInsertResult.Inserted)
            {
                if (insertResult == FixedNScalarInsertResult.Full)
                {
                    return SplitRoutedFixedNScalar8ByShelfTransform(
                        slotIndex,
                        slot,
                        handle,
                        targetOffset,
                        shelfBytes,
                        checked((ushort)(routerReader.KeyDepth + 1)),
                        key,
                        encodedIdentity,
                        allowDuplicateKeys);
                }

                return (insertResult, default);
            }

            RawDataReservation shelfRewrite = kernel.ReserveAt(targetOffset, handle.Profile.ShelfExtentSize);
            shelfBytes.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry rewriteCommit = CommitWithoutInvalidatingRouterReadCache();
            return (insertResult, rewriteCommit);
        }

        throw new InvalidDataException("The routed FSN-8 insert exceeded the fixed key depth.");
    }

    /// <summary>
    /// Deletes one exact tuple from a routed `FixedNScalar8` index without attempting route merge or empty-route cleanup.<br/>
    /// The operation follows the encoded key through child routers, compacts the selected leaf shelf, rewrites that shelf, and decrements the owning index-directory item count.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot that owns the routed index.<br/></param>
    /// <param name="handle">The routed `FSN-8` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-8 identity.<br/></param>
    /// <returns>The delete result and commit telemetry.<br/></returns>
    internal (bool Deleted, DataKernelCommitTelemetry Commit) DeleteRoutedFixedNScalar8RootNoMerge(
        int slotIndex,
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 root-prefix deletion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded key length must match the handle profile key size.", nameof(key));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FSN-8 index slot is not active.");
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        long routerOffset = handle.RootOffset;
        for (int hop = 0; hop < handle.Profile.KeySize; hop++)
        {
            kernel.Read(routerOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The routed FSN-8 router is invalid.");
            }

            long targetOffset = routerReader.FindTarget(key[routerReader.KeyDepth]);
            if (targetOffset == 0)
            {
                return (false, default);
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                routerOffset = targetOffset;
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar8ShelfBytes(targetOffset, handle.Profile);
            FixedNScalar8 shelf = new(shelfBytes, handle.Profile);
            if (!shelf.Delete(key, encodedIdentity))
            {
                return (false, default);
            }

            RawDataReservation shelfRewrite = kernel.ReserveAt(targetOffset, handle.Profile.ShelfExtentSize);
            shelfBytes.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry commit = CommitWithoutInvalidatingRouterReadCache();
            return (true, commit);
        }

        throw new InvalidDataException("The routed FSN-8 delete exceeded the fixed key depth.");
    }

    /// <summary>
    /// Inserts one tuple into an already-routed `FSN-8` leaf shelf using a writer-local context.<br/>
    /// The route must resolve to an existing shelf with available capacity; route creation and full-shelf transforms stay on the serialized topology path.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="handle">The routed `FSN-8` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-8 identity.<br/></param>
    /// <param name="allowDuplicateKeys">True for non-unique index behavior; false for unique key behavior.<br/></param>
    /// <returns>The insert result; commit telemetry is deferred to writer-context publication.<br/></returns>
    internal (bool Handled, FixedNScalarInsertResult Result) InsertRoutedFixedNScalar8NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 writer-context insertion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded key length must match the handle profile key size.", nameof(key));
        }

        EnterFixedNScalar8WriterContextStaging(handle.RootOffset);
        try
        {
            Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
            long routerOffset = handle.RootOffset;
            for (int hop = 0; hop < handle.Profile.KeySize; hop++)
            {
                kernel.Read(routerOffset, routerBytes);
                RouterReader routerReader = new(routerBytes);
                if (!routerReader.IsValid || !routerReader.HasDirectIndex)
                {
                    throw new InvalidDataException("The routed FSN-8 router is invalid.");
                }

                byte routePrefixByte = key[routerReader.KeyDepth];
                long targetOffset = routerReader.FindTarget(routePrefixByte);
                if (targetOffset == 0)
                {
                    return (false, default);
                }

                if (IsFixedNScalar8Router(targetOffset))
                {
                    routerOffset = targetOffset;
                    continue;
                }

                RecordFixedNScalar8RouteClaimForWriteContext(
                    writeContext,
                    routerOffset,
                    routePrefixByte,
                    targetOffset,
                    handle.Profile);
                byte[] shelfBytes = ReadFixedNScalar8ShelfBytesForWriteContext(writeContext, targetOffset, handle.Profile);
                FixedNScalar8 shelf = new(shelfBytes, handle.Profile);
                FixedNScalarInsertResult result = shelf.Insert(key, encodedIdentity, allowDuplicateKeys);
                if (result == FixedNScalarInsertResult.Full)
                {
                    return (false, default);
                }

                if (result == FixedNScalarInsertResult.Inserted)
                {
                    StageFixedNScalar8ShelfRewriteForWriteContext(writeContext, targetOffset, handle.Profile, shelfBytes);
                }

                return (true, result);
            }

            throw new InvalidDataException("The routed FSN-8 writer-context insert exceeded the fixed key depth.");
        }
        finally
        {
            ExitFixedNScalar8WriterContextStaging(handle.RootOffset);
        }
    }

    /// <summary>
    /// Deletes one exact tuple from an already-routed `FSN-8` leaf shelf using a writer-local context.<br/>
    /// The operation stages only the selected leaf shelf; empty-route cleanup and merge work stay out of this hot concurrent path.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="handle">The routed `FSN-8` handle.<br/></param>
    /// <param name="key">The encoded fixed-width key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded sortable scalar-8 identity.<br/></param>
    /// <returns><see langword="true"/> when one tuple was staged for deletion; otherwise <see langword="false"/>.<br/></returns>
    internal bool DeleteRoutedFixedNScalar8ExactForWriteContext(
        LibraDexWriteContext writeContext,
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 writer-context deletion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded key length must match the handle profile key size.", nameof(key));
        }

        EnterFixedNScalar8WriterContextStaging(handle.RootOffset);
        try
        {
            Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
            long routerOffset = handle.RootOffset;
            for (int hop = 0; hop < handle.Profile.KeySize; hop++)
            {
                kernel.Read(routerOffset, routerBytes);
                RouterReader routerReader = new(routerBytes);
                if (!routerReader.IsValid || !routerReader.HasDirectIndex)
                {
                    throw new InvalidDataException("The routed FSN-8 router is invalid.");
                }

                byte routePrefixByte = key[routerReader.KeyDepth];
                long targetOffset = routerReader.FindTarget(routePrefixByte);
                if (targetOffset == 0)
                {
                    return false;
                }

                if (IsFixedNScalar8Router(targetOffset))
                {
                    routerOffset = targetOffset;
                    continue;
                }

                RecordFixedNScalar8RouteClaimForWriteContext(
                    writeContext,
                    routerOffset,
                    routePrefixByte,
                    targetOffset,
                    handle.Profile);
                byte[] shelfBytes = ReadFixedNScalar8ShelfBytesForWriteContext(writeContext, targetOffset, handle.Profile);
                FixedNScalar8 shelf = new(shelfBytes, handle.Profile);
                if (!shelf.Delete(key, encodedIdentity))
                {
                    return false;
                }

                StageFixedNScalar8ShelfRewriteForWriteContext(writeContext, targetOffset, handle.Profile, shelfBytes);
                return true;
            }

            throw new InvalidDataException("The routed FSN-8 writer-context delete exceeded the fixed key depth.");
        }
        finally
        {
            ExitFixedNScalar8WriterContextStaging(handle.RootOffset);
        }
    }

    /// <summary>
    /// Inserts one tuple into a routed `FV` index.<br/>
    /// Missing routes allocate and link a new `FV` shelf; full shelves transform into child routers at the next separating key byte.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot that owns the routed index.</param>
    /// <param name="handle">The routed `FV` handle.</param>
    /// <param name="key">The encoded fixed-width key bytes.</param>
    /// <param name="identity">The raw variable-length identity bytes.</param>
    /// <param name="allowDuplicateKeys">True for non-unique key behavior; false for unique key behavior.</param>
    /// <returns>The insert result and commit telemetry.</returns>
    internal (FixedNVarIdentityInsertResult Result, DataKernelCommitTelemetry Commit) InsertRoutedFixedNVarIdentityRootNoSplit(
        int slotIndex,
        FixedNVarIdentityIndexHandle handle,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> identity,
        bool allowDuplicateKeys)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FV root-prefix insertion requires a routed handle.", nameof(handle));
        }

        if (key.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FV encoded key length must match the handle profile key size.", nameof(key));
        }

        if (!TryFindIndexDirectorySlot(slotIndex, out IndexDirectorySlotSnapshot slot))
        {
            throw new InvalidDataException("The requested FV index slot is not active.");
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        long routerOffset = handle.RootOffset;
        for (int hop = 0; hop < handle.Profile.KeySize; hop++)
        {
            kernel.Read(routerOffset, routerBytes);
            RouterReader routerReader = new(routerBytes);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("The routed FV router is invalid.");
            }

            byte prefix = key[routerReader.KeyDepth];
            long targetOffset = routerReader.FindTarget(prefix);
            if (targetOffset == 0)
            {
                byte[] shelfBytes = LibraDex.Views.FixedNVarIdentity.CreateEmpty(handle.Profile);
                FixedNVarIdentityInsertResult result = LibraDex.Views.FixedNVarIdentity.InsertInPlace(shelfBytes, handle.Profile, key, identity, allowDuplicateKeys, out shelfBytes);
                if (result != FixedNVarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected first FV routed shelf insert to succeed, got {result}.");
                }

                RawDataReservation shelfReservation = kernel.Reserve(handle.Profile.ShelfExtentSize);
                shelfBytes.CopyTo(shelfReservation.Span);
                RawDataReservation routerReservation = kernel.ReserveAt(routerOffset, RouterLayout.Size);
                routerBytes.CopyTo(routerReservation.Span);
                RouterWriter routerWriter = new(routerReservation.Span);
                routerWriter.WriteRoute(prefix, prefix, prefix, shelfReservation.Extent.Offset);
                InvalidateRouterReadCacheForRouterRewrite(routerOffset);
                DataKernelCommitTelemetry createCommit = CommitAndDeferRouterReadCacheInvalidation();
                return (result, createCommit);
            }

            if (IsFixedNVarIdentityRouter(targetOffset))
            {
                routerOffset = targetOffset;
                continue;
            }

            byte[] existingShelfBytes = ReadFixedNVarIdentityShelfBytes(targetOffset, handle.Profile);
            FixedNVarIdentityInsertResult insertResult = LibraDex.Views.FixedNVarIdentity.InsertInPlace(existingShelfBytes, handle.Profile, key, identity, allowDuplicateKeys, out existingShelfBytes);
            if (insertResult != FixedNVarIdentityInsertResult.Inserted)
            {
                if (insertResult == FixedNVarIdentityInsertResult.Full)
                {
                    return SplitRoutedFixedNVarIdentityByShelfTransform(
                        slot,
                        handle,
                        targetOffset,
                        existingShelfBytes,
                        checked((ushort)(routerReader.KeyDepth + 1)),
                        key,
                        identity,
                        allowDuplicateKeys);
                }

                return (insertResult, default);
            }

            RawDataReservation shelfRewrite = kernel.ReserveAt(targetOffset, handle.Profile.ShelfExtentSize);
            existingShelfBytes.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry rewriteCommit = CommitWithoutInvalidatingRouterReadCache();
            return (insertResult, rewriteCommit);
        }

        throw new InvalidDataException("The routed FV insert exceeded the fixed key depth.");
    }

    private (FixedNVarIdentityInsertResult Result, DataKernelCommitTelemetry Commit) SplitRoutedFixedNVarIdentityByShelfTransform(
        IndexDirectorySlotSnapshot slot,
        FixedNVarIdentityIndexHandle handle,
        long fullShelfOffset,
        byte[] existingShelfBytes,
        ushort firstKeyDepth,
        ReadOnlySpan<byte> key,
        ReadOnlySpan<byte> identity,
        bool allowDuplicateKeys)
    {
        LibraDex.Views.FixedNVarIdentityReadOnly existingShelf = new(existingShelfBytes, handle.Profile);
        if (!existingShelf.IsValid)
        {
            throw new InvalidDataException("The routed FV shelf selected for transform split is invalid.");
        }

        int existingCount = existingShelf.ItemCount;
        byte[][] keys = new byte[existingCount + 1][];
        byte[][] identities = new byte[existingCount + 1][];
        bool inserted = false;
        int writeIndex = 0;
        for (int slotOrdinal = 0; slotOrdinal < existingCount; slotOrdinal++)
        {
            byte[] currentKey = existingShelf.ReadKeyAt(slotOrdinal).ToArray();
            byte[] currentIdentity = existingShelf.ReadIdentityAt(slotOrdinal).ToArray();
            if (!inserted && CompareFixedNVarIdentityTuple(currentKey, currentIdentity, key, identity) > 0)
            {
                keys[writeIndex] = key.ToArray();
                identities[writeIndex] = identity.ToArray();
                writeIndex++;
                inserted = true;
            }

            if (currentKey.AsSpan().SequenceEqual(key) && currentIdentity.AsSpan().SequenceEqual(identity))
            {
                return (FixedNVarIdentityInsertResult.AlreadyPresent, default);
            }

            if (!allowDuplicateKeys && currentKey.AsSpan().SequenceEqual(key))
            {
                return (FixedNVarIdentityInsertResult.KeyConflict, default);
            }

            keys[writeIndex] = currentKey;
            identities[writeIndex] = currentIdentity;
            writeIndex++;
        }

        if (!inserted)
        {
            keys[writeIndex] = key.ToArray();
            identities[writeIndex] = identity.ToArray();
        }

        if (!TryChooseFixedNVarIdentitySplit(keys, firstKeyDepth, out ushort splitKeyDepth, out byte rightPrefixByte))
        {
            throw new InvalidDataException("The full FV shelf could not be split because all keys share every fixed-key byte.");
        }

        byte[] leftShelfBytes = LibraDex.Views.FixedNVarIdentity.CreateEmpty(handle.Profile);
        byte[] rightShelfBytes = LibraDex.Views.FixedNVarIdentity.CreateEmpty(handle.Profile);
        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = keys[i][splitKeyDepth] >= rightPrefixByte;
            FixedNVarIdentityInsertResult result = goesRight
                ? LibraDex.Views.FixedNVarIdentity.InsertInPlace(rightShelfBytes, handle.Profile, keys[i], identities[i], allowDuplicateKeys: true, out rightShelfBytes)
                : LibraDex.Views.FixedNVarIdentity.InsertInPlace(leftShelfBytes, handle.Profile, keys[i], identities[i], allowDuplicateKeys: true, out leftShelfBytes);
            if (result != FixedNVarIdentityInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FV split shelf insert to succeed, got {result}.");
            }
        }

        RawDataReservation leftAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - firstKeyDepth;
        long nextRouterOffset = 0;
        long[] appendedRouterOffsets = appendedRouterCount > 0 ? new long[appendedRouterCount] : [];
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            appendedRouterOffsets[i] = kernel.Reserve(RouterLayout.Size).Extent.Offset;
        }

        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(firstKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateFixedNVarIdentitySplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
                : CreateFixedNVarIdentitySingleTarget(keys[0][routerDepth], nextRouterOffset);
            RawDataReservation routerReservation = kernel.ReserveAt(appendedRouterOffsets[i], RouterLayout.Size);
            RouterWriter writer = new(routerReservation.Span);
            writer.InitializeExpandedOneByte(routerDepth, slot.AllocationClassId, targets);
            nextRouterOffset = appendedRouterOffsets[i];
        }

        long rootChildTarget = appendedRouterCount == 0 ? 0 : nextRouterOffset;
        long[] firstTargets = appendedRouterCount == 0
            ? CreateFixedNVarIdentitySplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
            : CreateFixedNVarIdentitySingleTarget(keys[0][firstKeyDepth], rootChildTarget);
        RawDataReservation transformedRouter = kernel.ReserveAt(fullShelfOffset, RouterLayout.Size);
        RouterWriter transformedWriter = new(transformedRouter.Span);
        transformedWriter.InitializeExpandedOneByte(firstKeyDepth, slot.AllocationClassId, firstTargets);

        InvalidateRouterReadCacheForRouterRewrite(fullShelfOffset);
        DataKernelCommitTelemetry commit = CommitAndDeferRouterReadCacheInvalidation();
        return (FixedNVarIdentityInsertResult.Inserted, commit);
    }

    private static long[] CreateFixedNVarIdentitySplitTerminalTargets(
        IReadOnlyList<byte[]> keys,
        ushort splitKeyDepth,
        byte rightPrefixByte,
        long leftShelfOffset,
        long rightShelfOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < keys.Count; i++)
        {
            byte prefix = keys[i][splitKeyDepth];
            targets[prefix] = prefix >= rightPrefixByte ? rightShelfOffset : leftShelfOffset;
        }

        return targets;
    }

    private static long[] CreateFixedNVarIdentitySingleTarget(byte prefix, long targetOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        targets[prefix] = targetOffset;
        return targets;
    }

    private static bool TryChooseFixedNVarIdentitySplit(
        IReadOnlyList<byte[]> sortedKeys,
        ushort firstKeyDepth,
        out ushort splitKeyDepth,
        out byte rightPrefixByte)
    {
        return TryChooseFixedNScalar8Split(sortedKeys, firstKeyDepth, out splitKeyDepth, out rightPrefixByte);
    }

    private static int CompareFixedNVarIdentityTuple(ReadOnlySpan<byte> leftKey, ReadOnlySpan<byte> leftIdentity, ReadOnlySpan<byte> rightKey, ReadOnlySpan<byte> rightIdentity)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        return keyComparison != 0 ? keyComparison : leftIdentity.SequenceCompareTo(rightIdentity);
    }

    private bool IsFixedNVarIdentityRouter(long offset)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        return reader.IsValid;
    }

    private bool IsFixedNScalar8Router(long offset)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        return reader.IsValid;
    }

    private (FixedNScalarInsertResult Result, DataKernelCommitTelemetry Commit) SplitRoutedFixedNScalar8ByShelfTransform(
        int slotIndex,
        IndexDirectorySlotSnapshot slot,
        FixedNScalar8IndexHandle handle,
        long fullShelfOffset,
        byte[] existingShelfBytes,
        ushort firstKeyDepth,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        _ = slotIndex;
        FixedNScalar8ReadOnly existingShelf = new(existingShelfBytes, handle.Profile);
        if (!existingShelf.IsValid)
        {
            throw new InvalidDataException("The routed FSN-8 shelf selected for transform split is invalid.");
        }

        int existingCount = existingShelf.ItemCount;
        byte[][] keys = new byte[existingCount + 1][];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int writeIndex = 0;
        for (int slotOrdinal = 0; slotOrdinal < existingCount; slotOrdinal++)
        {
            byte[] currentKey = new byte[handle.Profile.KeySize];
            existingShelf.CopyKeyAt(slotOrdinal, currentKey);
            ulong currentIdentity = existingShelf.ReadIdentityAt(slotOrdinal);
            if (!inserted && CompareFixedNScalar8Tuple(currentKey, currentIdentity, key, encodedIdentity) > 0)
            {
                keys[writeIndex] = key.ToArray();
                identities[writeIndex] = encodedIdentity;
                writeIndex++;
                inserted = true;
            }

            if (currentKey.AsSpan().SequenceEqual(key) && currentIdentity == encodedIdentity)
            {
                return (FixedNScalarInsertResult.AlreadyPresent, default);
            }

            if (!allowDuplicateKeys && currentKey.AsSpan().SequenceEqual(key))
            {
                return (FixedNScalarInsertResult.KeyConflict, default);
            }

            keys[writeIndex] = currentKey;
            identities[writeIndex] = currentIdentity;
            writeIndex++;
        }

        if (!inserted)
        {
            keys[writeIndex] = key.ToArray();
            identities[writeIndex] = encodedIdentity;
        }

        if (!TryChooseFixedNScalar8Split(keys, firstKeyDepth, out ushort splitKeyDepth, out byte rightPrefixByte))
        {
            throw new InvalidDataException("The full FSN-8 shelf could not be split because all keys share every fixed-key byte.");
        }

        byte[] leftShelfBytes = new byte[handle.Profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[handle.Profile.ShelfExtentSize];
        FixedNScalar8 leftShelf = new(leftShelfBytes, handle.Profile);
        FixedNScalar8 rightShelf = new(rightShelfBytes, handle.Profile);
        leftShelf.Initialize();
        rightShelf.Initialize();
        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = keys[i][splitKeyDepth] >= rightPrefixByte;
            FixedNScalarInsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true);
            if (result != FixedNScalarInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FSN-8 split shelf insert to succeed, got {result}.");
            }
        }

        RawDataReservation leftAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(handle.Profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - firstKeyDepth;
        long nextRouterOffset = 0;
        long[] appendedRouterOffsets = appendedRouterCount > 0 ? new long[appendedRouterCount] : [];
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            appendedRouterOffsets[i] = kernel.Reserve(RouterLayout.Size).Extent.Offset;
        }

        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(firstKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateFixedNScalar8SplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
                : CreateFixedNScalar8SingleTarget(keys[0][routerDepth], nextRouterOffset);
            RawDataReservation routerReservation = kernel.ReserveAt(appendedRouterOffsets[i], RouterLayout.Size);
            RouterWriter writer = new(routerReservation.Span);
            writer.InitializeExpandedOneByte(routerDepth, slot.AllocationClassId, targets);
            nextRouterOffset = appendedRouterOffsets[i];
        }

        long rootChildTarget = appendedRouterCount == 0 ? 0 : nextRouterOffset;
        long[] firstTargets = appendedRouterCount == 0
            ? CreateFixedNScalar8SplitTerminalTargets(keys, splitKeyDepth, rightPrefixByte, leftAppend.Extent.Offset, rightAppend.Extent.Offset)
            : CreateFixedNScalar8SingleTarget(keys[0][firstKeyDepth], rootChildTarget);
        RawDataReservation transformedRouter = kernel.ReserveAt(fullShelfOffset, RouterLayout.Size);
        RouterWriter transformedWriter = new(transformedRouter.Span);
        transformedWriter.InitializeExpandedOneByte(firstKeyDepth, slot.AllocationClassId, firstTargets);

        InvalidateRouterReadCacheForRouterRewrite(fullShelfOffset);
        DataKernelCommitTelemetry commit = CommitAndDeferRouterReadCacheInvalidation();
        return (FixedNScalarInsertResult.Inserted, commit);
    }

    private static long[] CreateFixedNScalar8SplitTerminalTargets(
        IReadOnlyList<byte[]> keys,
        ushort splitKeyDepth,
        byte rightPrefixByte,
        long leftShelfOffset,
        long rightShelfOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < keys.Count; i++)
        {
            byte prefix = keys[i][splitKeyDepth];
            targets[prefix] = prefix >= rightPrefixByte ? rightShelfOffset : leftShelfOffset;
        }

        return targets;
    }

    private static long[] CreateFixedNScalar8SingleTarget(byte prefix, long targetOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        targets[prefix] = targetOffset;
        return targets;
    }

    private static bool TryChooseFixedNScalar8Split(
        IReadOnlyList<byte[]> sortedKeys,
        ushort firstKeyDepth,
        out ushort splitKeyDepth,
        out byte rightPrefixByte)
    {
        splitKeyDepth = 0;
        rightPrefixByte = 0;
        if (sortedKeys.Count < 2)
        {
            return false;
        }

        int midpoint = sortedKeys.Count / 2;
        for (ushort keyDepth = firstKeyDepth; keyDepth < sortedKeys[0].Length; keyDepth++)
        {
            for (int delta = 0; delta < sortedKeys.Count; delta++)
            {
                int left = midpoint - 1 - delta;
                if (left >= 0 && sortedKeys[left][keyDepth] != sortedKeys[left + 1][keyDepth])
                {
                    splitKeyDepth = keyDepth;
                    rightPrefixByte = sortedKeys[left + 1][keyDepth];
                    return true;
                }

                int right = midpoint + delta;
                if (right > 0 && right < sortedKeys.Count && sortedKeys[right - 1][keyDepth] != sortedKeys[right][keyDepth])
                {
                    splitKeyDepth = keyDepth;
                    rightPrefixByte = sortedKeys[right][keyDepth];
                    return true;
                }
            }
        }

        return false;
    }

    private static int CompareFixedNScalar8Tuple(ReadOnlySpan<byte> leftKey, ulong leftIdentity, ReadOnlySpan<byte> rightKey, ulong rightIdentity)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        return leftIdentity > rightIdentity ? 1 : 0;
    }

    /// <summary>
    /// Reads encoded identities from a root-prefix routed `FixedNScalar8` index over an inclusive fixed-key range.<br/>
    /// The first routed slice scans only root-prefix shelves touched by the range; deeper child-router traversal is reserved for the next FSN split slice.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-8` handle.</param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.</param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.</param>
    /// <returns>Encoded scalar-8 identities matching the requested key range.</returns>
    internal ulong[] ReadRoutedFixedNScalar8IdentityRange(
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 routed range reads require a routed handle.", nameof(handle));
        }

        if (lowerKey.Length != handle.Profile.KeySize || upperKey.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded range keys must match the handle profile key size.");
        }

        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The FSN-8 upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperKey));
        }

        List<ulong> identities = new();
        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        ReadRoutedFixedNScalar8IdentityRangeFromRouter(handle.RootOffset, handle.Profile, lowerKey, upperKey, identities, visitedShelves, visitedRouters);
        return identities.ToArray();
    }

    /// <summary>
    /// Counts all ordinary tuples reachable from a routed `FSN-8` index.<br/>
    /// Each leaf shelf is counted once from its header item count; the index-directory item count is intentionally not used as the public count source.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-8` handle.<br/></param>
    /// <returns>The summed ordinary tuple count across reachable routed shelves.<br/></returns>
    internal long CountRoutedFixedNScalar8Identities(FixedNScalar8IndexHandle handle)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 routed counts require a routed handle.", nameof(handle));
        }

        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        return CountRoutedFixedNScalar8IdentitiesFromRouter(handle.RootOffset, handle.Profile, visitedShelves, visitedRouters);
    }

    /// <summary>
    /// Counts routed `FSN-8` tuples whose keys are inside an inclusive encoded key range.<br/>
    /// Traversal follows the same router range pruning as identity reads, but leaf handling counts matching slots without copying identity values.<br/>
    /// </summary>
    /// <param name="handle">The routed `FSN-8` handle.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <returns>The count of routed ordinary tuples in the requested range.<br/></returns>
    internal long CountRoutedFixedNScalar8IdentityRange(
        FixedNScalar8IndexHandle handle,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        handle.Validate();
        if (!handle.IsRouted)
        {
            throw new ArgumentException("FSN-8 routed range counts require a routed handle.", nameof(handle));
        }

        if (lowerKey.Length != handle.Profile.KeySize || upperKey.Length != handle.Profile.KeySize)
        {
            throw new ArgumentException("FSN-8 encoded range keys must match the handle profile key size.");
        }

        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The FSN-8 upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperKey));
        }

        HashSet<long> visitedShelves = new();
        HashSet<long> visitedRouters = new();
        return CountRoutedFixedNScalar8IdentityRangeFromRouter(
            handle.RootOffset,
            handle.Profile,
            lowerKey,
            upperKey,
            lowerEdge: true,
            upperEdge: true,
            visitedShelves,
            visitedRouters);
    }

    private long CountRoutedFixedNScalar8IdentitiesFromRouter(
        long routerOffset,
        FixedNScalar8Profile profile,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-8 router is invalid.");
        }

        long count = 0;
        for (int prefix = 0; prefix <= byte.MaxValue; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                count += CountRoutedFixedNScalar8IdentitiesFromRouter(targetOffset, profile, visitedShelves, visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            count += ReadFixedNScalar8ShelfItemCountNarrow(targetOffset, profile);
        }

        return count;
    }

    private long CountRoutedFixedNScalar8IdentityRangeFromRouter(
        long routerOffset,
        FixedNScalar8Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-8 router is invalid.");
        }

        long count = 0;
        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerEdge ? lowerKey[keyDepth] : byte.MinValue;
        byte endPrefix = upperEdge ? upperKey[keyDepth] : byte.MaxValue;
        long lowerTarget = lowerEdge ? routerReader.FindTarget(startPrefix) : 0;
        long upperTarget = upperEdge ? routerReader.FindTarget(endPrefix) : 0;
        if (lowerEdge && upperEdge && startPrefix != endPrefix && lowerTarget != 0 && lowerTarget == upperTarget)
        {
            return CountRoutedFixedNScalar8IdentityRangeByReaderLikeTraversal(routerReader, profile, lowerKey, upperKey, visitedShelves, visitedRouters);
        }

        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            bool childLowerEdge = lowerEdge && prefix == startPrefix;
            bool childUpperEdge = upperEdge && prefix == endPrefix;
            if (!childLowerEdge && !childUpperEdge && (targetOffset == lowerTarget || targetOffset == upperTarget))
            {
                return CountRoutedFixedNScalar8IdentityRangeByReaderLikeTraversal(routerReader, profile, lowerKey, upperKey, visitedShelves, visitedRouters);
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                count += childLowerEdge || childUpperEdge
                    ? CountRoutedFixedNScalar8IdentityRangeFromRouter(targetOffset, profile, lowerKey, upperKey, childLowerEdge, childUpperEdge, visitedShelves, visitedRouters)
                    : CountRoutedFixedNScalar8IdentitiesFromRouter(targetOffset, profile, visitedShelves, visitedRouters);
                continue;
            }

            count += childLowerEdge || childUpperEdge
                ? CountFixedNScalar8ShelfKeyRangeNarrow(targetOffset, profile, lowerKey, upperKey, visitedShelves)
                : CountFixedNScalar8ShelfCountNarrow(targetOffset, profile, visitedShelves);
        }

        return count;
    }

    /// <summary>
    /// Counts a routed `FSN-8` range with the pre-optimization traversal shape for ambiguous aliased route targets.<br/>
    /// The fallback preserves correctness when a direct router maps an interior prefix to the same physical target as a boundary prefix, because that target cannot be treated as fully contained.<br/>
    /// </summary>
    /// <param name="routerReader">The decoded router whose children should be counted.<br/></param>
    /// <param name="profile">The `FSN-8` shelf profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <param name="visitedRouters">The visited router offsets for cycle protection.<br/></param>
    /// <returns>The number of routed `FSN-8` tuples in the requested range.<br/></returns>
    private long CountRoutedFixedNScalar8IdentityRangeByReaderLikeTraversal(
        RouterReader routerReader,
        FixedNScalar8Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        long count = 0;
        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerKey[keyDepth];
        byte endPrefix = upperKey[keyDepth];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                count += CountRoutedFixedNScalar8IdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lowerKey,
                    upperKey,
                    lowerEdge: true,
                    upperEdge: true,
                    visitedShelves,
                    visitedRouters);
                continue;
            }

            count += CountFixedNScalar8ShelfKeyRangeNarrow(targetOffset, profile, lowerKey, upperKey, visitedShelves);
        }

        return count;
    }

    /// <summary>
    /// Counts every item in one `FSN-8` shelf target from its header metadata after visited-set filtering.<br/>
    /// This is used only for range targets whose route path proves the whole shelf is contained by the requested key range.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset to count.<br/></param>
    /// <param name="profile">The `FSN-8` shelf profile.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <returns>The shelf item count, or zero when the shelf was already counted.<br/></returns>
    private long CountFixedNScalar8ShelfCountNarrow(long shelfOffset, FixedNScalar8Profile profile, HashSet<long> visitedShelves)
    {
        return visitedShelves.Add(shelfOffset)
            ? ReadFixedNScalar8ShelfItemCountNarrow(shelfOffset, profile)
            : 0;
    }

    /// <summary>
    /// Counts only matching keys in one `FSN-8` shelf after visited-set filtering.<br/>
    /// Boundary range targets use this narrow slot scan because the route path does not prove every key in the shelf is contained.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset to inspect.<br/></param>
    /// <param name="profile">The `FSN-8` shelf profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <param name="visitedShelves">The visited shelf offsets for cycle and alias protection.<br/></param>
    /// <returns>The number of matching items in the shelf, or zero when the shelf was already counted.<br/></returns>
    private long CountFixedNScalar8ShelfKeyRangeNarrow(
        long shelfOffset,
        FixedNScalar8Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        HashSet<long> visitedShelves)
    {
        if (!visitedShelves.Add(shelfOffset))
        {
            return 0;
        }

        byte[] shelfBytes = ReadFixedNScalar8ShelfBytes(shelfOffset, profile);
        FixedNScalar8ReadOnly shelf = new(shelfBytes, profile);
        return shelf.CountItemsInKeyRange(lowerKey, upperKey);
    }

    /// <summary>
    /// Reads raw identities from a root-prefix routed `FV` index over an inclusive fixed-key range.<br/>
    /// This first durable FV route reads root-prefix shelves and preserves raw identity bytes without decoding or comparer callbacks.<br/>
    /// </summary>
    /// <param name="handle">The routed `FV` handle.</param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.</param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.</param>
    /// <returns>Raw variable-length identities matching the requested key range.</returns>
    internal IReadOnlyList<byte[]> ReadRoutedFixedNVarIdentityRange(
        FixedNVarIdentityIndexHandle handle,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        handle.Validate();
        if (!handle.IsRouted)
