            {
                count += CountRoutedFixedNVarIdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lowerKey,
                    upperKey,
                    lowerEdge: true,
                    upperEdge: true,
                    visitedShelves,
                    visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            count += CountFixedNVarIdentityShelfKeyRangeNarrow(targetOffset, profile, lowerKey, upperKey);
        }

        return count;
    }

    /// <summary>
    /// Counts matching rows inside one `FV` shelf when the shelf overlaps a routed range boundary.<br/>
    /// Boundary shelves still need slot/key inspection, but identity payloads are not copied and contained shelves use the cached count-header path instead.<br/>
    /// </summary>
    /// <param name="shelfOffset">The durable offset of the boundary shelf.<br/></param>
    /// <param name="profile">The expected fixed-key / variable-identity shelf profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower encoded fixed-width key.<br/></param>
    /// <param name="upperKey">The inclusive upper encoded fixed-width key.<br/></param>
    /// <returns>The number of rows inside the encoded key range.<br/></returns>
    private long CountFixedNVarIdentityShelfKeyRangeNarrow(
        long shelfOffset,
        FixedNVarIdentityProfile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        byte[] shelfBytes = ReadFixedNVarIdentityShelfBytes(shelfOffset, profile);
        LibraDex.Views.FixedNVarIdentityReadOnly shelf = new(shelfBytes, profile);
        return shelf.CountItemsInKeyRange(lowerKey, upperKey);
    }

    private void ReadRoutedFixedNVarIdentityRangeFromRouter(
        long routerOffset,
        FixedNVarIdentityProfile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        List<byte[]> identities,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FV router is invalid.");
        }

        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerKey[keyDepth];
        byte endPrefix = upperKey[keyDepth];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNVarIdentityRouter(targetOffset))
            {
                ReadRoutedFixedNVarIdentityRangeFromRouter(targetOffset, profile, lowerKey, upperKey, identities, visitedShelves, visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            byte[] shelfBytes = ReadFixedNVarIdentityShelfBytes(targetOffset, profile);
            LibraDex.Views.FixedNVarIdentityReadOnly shelf = new(shelfBytes, profile);
            shelf.CopyIdentitiesInKeyRange(lowerKey, upperKey, identities);
        }
    }

    private void ReadRoutedFixedNScalar8IdentityRangeFromRouter(
        long routerOffset,
        FixedNScalar8Profile profile,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        List<ulong> identities,
        HashSet<long> visitedShelves,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, routerBytes);
        RouterReader routerReader = new(routerBytes);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("The routed FSN-8 router is invalid.");
        }

        int keyDepth = routerReader.KeyDepth;
        byte startPrefix = lowerKey[keyDepth];
        byte endPrefix = upperKey[keyDepth];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            long targetOffset = routerReader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            if (IsFixedNScalar8Router(targetOffset))
            {
                ReadRoutedFixedNScalar8IdentityRangeFromRouter(targetOffset, profile, lowerKey, upperKey, identities, visitedShelves, visitedRouters);
                continue;
            }

            if (!visitedShelves.Add(targetOffset))
            {
                continue;
            }

            byte[] shelfBytes = ReadFixedNScalar8ShelfBytes(targetOffset, profile);
            FixedNScalar8ReadOnly shelf = new(shelfBytes, profile);
            ulong[] shelfIdentities = new ulong[shelf.ItemCount];
            int copied = shelf.CopyIdentitiesInKeyRange(lowerKey, upperKey, shelfIdentities);
            for (int i = 0; i < copied; i++)
            {
                identities.Add(shelfIdentities[i]);
            }
        }
    }

    /// <summary>
    /// Creates a fully expanded one-byte root router for an internal `VS16` varlen index and returns a runtime handle with the commit result.<br/>
    /// This mirrors the `VS8` lifecycle handle while preserving the shape-specific identity width at operation call sites.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router offset is supplied by this method.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the runtime index.</param>
    /// <param name="optimizerRouteFanout">The compressed-route fanout requested by optimizer maintenance.</param>
    /// <param name="optimizerPolicy">The internal optimizer observation and maintenance scheduling policy.</param>
    /// <returns>The runtime `VS16` handle, created router snapshot, and DataKernel commit telemetry.</returns>
    internal (VarKeyScalar16IndexHandle Index, RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateVarKeyScalar16RootRouterIndex(
        IndexDirectorySlotSnapshot slot,
        int maxKeyLength,
        int optimizerRouteFanout,
        VarLenOptimizerMaintenancePolicy optimizerPolicy)
    {
        (RouterSnapshot router, DataKernelCommitTelemetry commit) = CreateRootRouterIndex(slot);
        VarKeyScalar16IndexHandle handle = new(router.Offset, maxKeyLength, optimizerRouteFanout, optimizerPolicy);
        handle.Validate();
        return (handle, router, commit);
    }

    /// <summary>
    /// Resolves a runtime `SS8-8` index handle from the cached index directory by slot index.<br/>
    /// This is the first reopen/resume handle-acquisition path: it trusts the session's cached directory snapshot and validates the active slot plus supported `SS8-8` profile identifiers.<br/>
    /// The returned handle is runtime-only and does not add new persisted state.<br/>
    /// </summary>
    /// <param name="slotIndex">The fixed index-directory slot index to resolve.</param>
    /// <returns>The runtime `SS8-8` index handle for the active slot.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slot index is outside the fixed directory.</exception>
    /// <exception cref="InvalidDataException">Thrown when the slot is inactive, missing, or uses unsupported profile identifiers.</exception>
    internal Scalar8Scalar8IndexHandle GetScalar8Scalar8IndexHandle(int slotIndex)
    {
        if ((uint)slotIndex >= IndexDirectoryLayout.SlotCount)
        {
            throw new ArgumentOutOfRangeException(nameof(slotIndex), slotIndex, "Index directory slot is outside the fixed directory.");
        }

        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            IndexDirectorySlotSnapshot slot = activeSlots[i];
            if (slot.SlotIndex == slotIndex)
            {
                return GetScalar8Scalar8IndexHandle(slot);
            }
        }

        throw new InvalidDataException("The requested index-directory slot is not active.");
    }

    /// <summary>
    /// Resolves a runtime `SS8-8` index handle from an active index-directory slot snapshot.<br/>
    /// The method keeps profile decoding explicit so future shelf sizes or shape IDs do not accidentally reuse the current default `SS8-8` physical profile.<br/>
    /// </summary>
    /// <param name="slot">The active index-directory slot snapshot.</param>
    /// <returns>The runtime `SS8-8` index handle for the slot.</returns>
    /// <exception cref="InvalidDataException">Thrown when the slot is inactive, has no root router offset, or uses unsupported profile identifiers.</exception>
    internal Scalar8Scalar8IndexHandle GetScalar8Scalar8IndexHandle(IndexDirectorySlotSnapshot slot)
    {
        if (!slot.IsActive)
        {
            throw new InvalidDataException("The index-directory slot is not active.");
        }

        if (slot.RootRouterOffset <= 0)
        {
            throw new InvalidDataException("The active index-directory slot does not reference a valid root router offset.");
        }

        Scalar8Scalar8Profile profile = GetScalar8Scalar8ProfileForSlot(slot);
        return new Scalar8Scalar8IndexHandle(slot.RootRouterOffset, profile);
    }

    /// <summary>
    /// Resolves a runtime `SS8-8` index handle from the cached index directory by root-router offset.<br/>
    /// This helper is useful while outer code is still carrying router offsets from earlier primitives; it still derives the handle from directory metadata rather than manually pairing an offset with a profile.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root-router offset to find in the active index-directory slots.</param>
    /// <returns>The runtime `SS8-8` index handle for the matching active slot.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="rootRouterOffset"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when no active slot references the root-router offset or the slot uses unsupported profile identifiers.</exception>
    internal Scalar8Scalar8IndexHandle GetScalar8Scalar8IndexHandleByRootRouterOffset(long rootRouterOffset)
    {
        if (rootRouterOffset <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(rootRouterOffset), rootRouterOffset, "Root router offset must be positive.");
        }

        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            IndexDirectorySlotSnapshot slot = activeSlots[i];
            if (slot.RootRouterOffset == rootRouterOffset)
            {
                return GetScalar8Scalar8IndexHandle(slot);
            }
        }

        throw new InvalidDataException("No active index-directory slot references the requested root-router offset.");
    }

    /// <summary>
    /// Maps the current fixed index-directory profile identifiers to a runtime `SS8-8` shelf profile.<br/>
    /// Profile identifiers are deliberately checked together because `SS8-8` is a shape tuple, not independent key, identity, router, and allocation choices.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot snapshot whose profile identifiers should be decoded.</param>
    /// <returns>The supported runtime `SS8-8` shelf profile.</returns>
    /// <exception cref="ArgumentException">Thrown when the slot profile identifiers do not describe the current `SS8-8` profile.</exception>
    private static Scalar8Scalar8Profile GetScalar8Scalar8ProfileForSlot(IndexDirectorySlotSnapshot slot)
    {
        if (slot.KeyProfileId == 1 &&
            slot.IdentityProfileId == 1 &&
            slot.RouterProfileId == 1 &&
            slot.AllocationClassId == 1)
        {
            return Scalar8Scalar8Profile.Default32KiB;
        }

        if (slot.KeyProfileId == 1 &&
            slot.IdentityProfileId == 1 &&
            slot.RouterProfileId == 1 &&
            slot.AllocationClassId == 2)
        {
            return Scalar8Scalar8Profile.Default24KiB;
        }

        if (slot.KeyProfileId == 1 &&
            slot.IdentityProfileId == 1 &&
            slot.RouterProfileId == 1 &&
            slot.AllocationClassId == 3)
        {
            return Scalar8Scalar8Profile.Default16KiB;
        }

        if (slot.KeyProfileId == 1 &&
            slot.IdentityProfileId == 1 &&
            slot.RouterProfileId == 1 &&
            slot.AllocationClassId == 4)
        {
            return Scalar8Scalar8Profile.Default48KiB;
        }

        if (slot.KeyProfileId == 1 &&
            slot.IdentityProfileId == 1 &&
            slot.RouterProfileId == 1 &&
            slot.AllocationClassId == 5)
        {
            return Scalar8Scalar8Profile.Default64KiB;
        }

        throw new ArgumentException("The index-directory slot does not describe a supported SS8-8 profile.", nameof(slot));
    }

    /// <summary>
    /// Creates a compressed router page with caller-supplied route ranges.<br/>
    /// This appends one 4 KiB router page and commits it without changing the index directory.<br/>
    /// </summary>
    /// <param name="prefixByteCount">The number of key bytes consumed by this router.</param>
    /// <param name="keyDepth">The key byte depth where this router begins.</param>
    /// <param name="maxRouteCount">The configured maximum route count for this router.</param>
    /// <param name="allocationClassId">The router allocation class identifier.</param>
    /// <param name="routes">The compressed route ranges to persist.</param>
    /// <returns>The created router snapshot and DataKernel commit telemetry.</returns>
    internal (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateCompressedRouter(
        byte prefixByteCount,
        ushort keyDepth,
        ushort maxRouteCount,
        ushort allocationClassId,
        ReadOnlySpan<RouterRouteSnapshot> routes)
    {
        RawDataReservation router = kernel.Reserve(RouterLayout.Size);
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeCompressed(prefixByteCount, keyDepth, maxRouteCount, allocationClassId, routes);

        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("Created compressed router did not validate.");
        }

        RouterSnapshot routerSnapshot = RouterSnapshot.FromReader(router.Extent.Offset, routerReader);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (routerSnapshot, telemetry);
    }

    /// <summary>
    /// Creates a compressed multi-byte router page with caller-supplied exact-stem route ranges.<br/>
    /// This is a cold construction primitive for bulk/build paths that already know the useful fanout byte and want to avoid writing a one-byte router chain.<br/>
    /// The persisted router still uses the shared route-slot contract; only the compact stem table after the configured route slots is multi-byte specific.<br/>
    /// </summary>
    /// <param name="prefixByteCount">The number of consecutive key bytes consumed by this router.</param>
    /// <param name="keyDepth">The first key byte depth consumed by the router.</param>
    /// <param name="maxRouteCount">The configured maximum route count for the router.</param>
    /// <param name="allocationClassId">The router allocation class identifier.</param>
    /// <param name="routes">The compressed multi-byte routes to persist.</param>
    /// <returns>The created router snapshot and commit telemetry.</returns>
    internal (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateCompressedMultiByteRouter(
        byte prefixByteCount,
        ushort keyDepth,
        ushort maxRouteCount,
        ushort allocationClassId,
        ReadOnlySpan<RouterMultiByteRouteSnapshot> routes)
    {
        RawDataReservation router = kernel.Reserve(RouterLayout.Size);
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeCompressedMultiByte(prefixByteCount, keyDepth, maxRouteCount, allocationClassId, routes);

        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || routerReader.HasDirectIndex || routerReader.PrefixByteCount <= 1)
        {
            throw new InvalidDataException("Created compressed multi-byte router did not validate.");
        }

        RouterSnapshot routerSnapshot = RouterSnapshot.FromReader(router.Extent.Offset, routerReader);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (routerSnapshot, telemetry);
    }

    /// <summary>
    /// Creates one fully expanded one-byte router by appending a new 4 KiB router page.<br/>
    /// This is a validation primitive for comparing normal appended router allocation against router placement inside transformed shelf slack.<br/>
    /// The router starts with all direct-index route targets unset.<br/>
    /// </summary>
    /// <param name="keyDepth">The key byte depth where the router begins.</param>
    /// <param name="allocationClassId">The allocation class identifier persisted in the router header.</param>
    /// <returns>The created router snapshot and DataKernel commit telemetry.</returns>
    internal (RouterSnapshot Router, DataKernelCommitTelemetry Commit) CreateExpandedOneByteRouter(
        ushort keyDepth,
        ushort allocationClassId)
    {
        RawDataReservation router = kernel.Reserve(RouterLayout.Size);
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeExpandedOneByte(keyDepth, allocationClassId, targets);

        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("Created expanded router did not validate.");
        }

        RouterSnapshot routerSnapshot = RouterSnapshot.FromReader(router.Extent.Offset, routerReader);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (routerSnapshot, telemetry);
    }

    /// <summary>
    /// Creates one fully expanded one-byte router using the current router micro-arena policy.<br/>
    /// The policy prefers the supplied local arena, then any eligible same-session arena, then normal append when no arena has free router pages.<br/>
    /// Arena allocations write relative arena metadata into the router header so future block relocation can preserve internal arena relationships.<br/>
    /// </summary>
    /// <param name="keyDepth">The key byte depth where the router begins.</param>
    /// <param name="allocationClassId">The allocation class identifier persisted in the router header.</param>
    /// <param name="preferredArenaBaseOffset">The preferred local arena base offset, or zero when no local preference exists.</param>
    /// <returns>The router allocation result and commit telemetry.</returns>
    internal RouterArenaAllocationResult CreateExpandedOneByteRouterUsingArena(
        ushort keyDepth,
        ushort allocationClassId,
        long preferredArenaBaseOffset)
    {
        RouterArenaState? arena = null;
        RouterArenaAllocationKind kind = RouterArenaAllocationKind.Append;
        if (preferredArenaBaseOffset != 0)
        {
            arena = FindRouterArena(preferredArenaBaseOffset);
            if (arena is not null && arena.TryFindFreePage(out _))
            {
                kind = RouterArenaAllocationKind.LocalArena;
            }
            else
            {
                arena = null;
            }
        }

        if (arena is null)
        {
            arena = FindAnyRouterArenaWithFreePage();
            if (arena is not null)
            {
                kind = RouterArenaAllocationKind.IndexArena;
            }
        }

        if (arena is null)
        {
            (RouterSnapshot appendedRouter, DataKernelCommitTelemetry appendCommit) = CreateExpandedOneByteRouter(keyDepth, allocationClassId);
            return new RouterArenaAllocationResult(appendedRouter, RouterArenaAllocationKind.Append, 0, 0, appendCommit);
        }

        if (!arena.TryFindFreePage(out int pageIndex))
        {
            throw new InvalidDataException("Selected router arena did not contain a free page.");
        }

        long routerOffset = arena.BaseOffset + ((long)pageIndex * arena.PageSize);
        RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        RouterWriter routerWriter = new(router.Span);
        routerWriter.InitializeExpandedOneByte(keyDepth, allocationClassId, targets);
        routerWriter.WriteArenaMetadata(
            checked((int)(arena.BaseOffset - routerOffset)),
            arena.Length,
            checked((ushort)arena.PageSize),
            checked((ushort)pageIndex),
            checked((ushort)arena.PageCount),
            arenaFlags: arena.Length > ushort.MaxValue + 1 ? RouterLayout.ArenaLengthFromPageCountFlag : 0);

        RouterReader routerReader = new(router.Span);
        if (!routerReader.IsValid || !routerReader.HasDirectIndex)
        {
            throw new InvalidDataException("Created arena-allocated router did not validate.");
        }

        RouterSnapshot snapshot = RouterSnapshot.FromReader(routerOffset, routerReader);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        arena.MarkUsed(pageIndex);
        return new RouterArenaAllocationResult(snapshot, kind, arena.BaseOffset, checked((ushort)pageIndex), telemetry);
    }

    /// <summary>
    /// Creates fully expanded one-byte routers at caller-supplied contiguous offsets inside an already-owned extent.<br/>
    /// This is a validation primitive for transformed shelf micro-arenas: it writes router pages into the former shelf extent without appending file data.<br/>
    /// The routers start with all direct-index route targets unset and are committed as one staged write batch.<br/>
    /// </summary>
    /// <param name="firstRouterOffset">The file offset where the first router page should be written.</param>
    /// <param name="routerCount">The number of contiguous 4 KiB router pages to write.</param>
    /// <param name="keyDepth">The key byte depth where the routers begin.</param>
    /// <param name="allocationClassId">The allocation class identifier persisted in each router header.</param>
    /// <returns>The created router snapshots and DataKernel commit telemetry.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when router count is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when any created router does not validate.</exception>
    internal (RouterSnapshot[] Routers, DataKernelCommitTelemetry Commit) CreateExpandedOneByteRoutersAt(
        long firstRouterOffset,
        int routerCount,
        ushort keyDepth,
        ushort allocationClassId,
        long arenaBaseOffset,
        int arenaLength)
    {
        if (routerCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(routerCount), routerCount, "Router count must be positive.");
        }

        RouterSnapshot[] snapshots = new RouterSnapshot[routerCount];
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < routerCount; i++)
        {
            long routerOffset = firstRouterOffset + ((long)i * RouterLayout.Size);
            RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
            RouterWriter routerWriter = new(router.Span);
            routerWriter.InitializeExpandedOneByte(keyDepth, allocationClassId, targets);
            int arenaBaseDelta = checked((int)(arenaBaseOffset - routerOffset));
            routerWriter.WriteArenaMetadata(
                arenaBaseDelta,
                arenaLength,
                checked((ushort)RouterLayout.Size),
                checked((ushort)((routerOffset - arenaBaseOffset) / RouterLayout.Size)),
                checked((ushort)(arenaLength / RouterLayout.Size)),
                arenaFlags: arenaLength > ushort.MaxValue + 1 ? RouterLayout.ArenaLengthFromPageCountFlag : 0);

            RouterReader routerReader = new(router.Span);
            if (!routerReader.IsValid || !routerReader.HasDirectIndex)
            {
                throw new InvalidDataException("Created arena router did not validate.");
            }

            snapshots[i] = RouterSnapshot.FromReader(routerOffset, routerReader);
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(arenaBaseOffset, arenaLength);
        for (int i = 0; i < routerCount; i++)
        {
            long routerOffset = firstRouterOffset + ((long)i * RouterLayout.Size);
            arena.MarkUsed(checked((int)((routerOffset - arenaBaseOffset) / RouterLayout.Size)));
        }

        return (snapshots, telemetry);
    }

    /// <summary>
    /// Creates a synthetic one-byte router chain and links it from an index-directory slot in one commit.<br/>
    /// This is a stress/validation helper for comparing write-combined router construction against separated mutations.<br/>
    /// Each router routes byte `0x41` to the next router, and the final router routes byte `0x41` to a placeholder target.<br/>
    /// </summary>
    /// <param name="slot">The index-directory slot values to persist; the root-router offset is supplied by this method.</param>
    /// <param name="routerCount">The number of routers to create, including the root router.</param>
    /// <param name="finalTargetOffset">The placeholder final target offset.</param>
    /// <returns>The chain creation result and DataKernel commit telemetry.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when router count or slot index is invalid.</exception>
    internal (RouteChainCreationResult Chain, DataKernelCommitTelemetry Commit) CreateRouteChainIndexCombined(
        IndexDirectorySlotSnapshot slot,
        int routerCount,
        long finalTargetOffset)
    {
        if ((uint)slot.SlotIndex >= IndexDirectoryLayout.SlotCount)
        {
            throw new ArgumentOutOfRangeException(nameof(slot), slot.SlotIndex, "Index directory slot is outside the fixed directory.");
        }

        if (routerCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(routerCount), routerCount, "Router count must be greater than zero.");
        }

        RawDataReservation rootRouter = kernel.Reserve(RouterLayout.Size);
        long rootOffset = rootRouter.Extent.Offset;
        RouterWriter rootWriter = new(rootRouter.Span);
        rootWriter.InitializeRoot(slot.AllocationClassId);
        long firstTarget = routerCount == 1 ? finalTargetOffset : rootOffset + RouterLayout.Size;
        rootWriter.WriteRoute(0x41, 0x41, 0x41, firstTarget);

        for (int i = 1; i < routerCount; i++)
        {
            RawDataReservation router = kernel.Reserve(RouterLayout.Size);
            long expectedOffset = rootOffset + ((long)i * RouterLayout.Size);
            if (router.Extent.Offset != expectedOffset)
            {
                throw new InvalidDataException("Combined router chain reservations were not contiguous.");
            }

            long target = i == routerCount - 1 ? finalTargetOffset : expectedOffset + RouterLayout.Size;
            RouterRouteSnapshot[] routes = [new RouterRouteSnapshot(0x41, 0x41, target)];
            RouterWriter writer = new(router.Span);
            writer.InitializeCompressed(1, checked((ushort)i), 16, slot.AllocationClassId, routes);
        }

        IndexDirectorySlotSnapshot updatedSlot = slot with
        {
            State = IndexDirectoryLayout.ActiveState,
            RootRouterOffset = rootOffset
        };

        RawDataReservation directory = kernel.ReserveAt(Superblock.IndexDirectoryOffset, Superblock.IndexDirectoryLength);
        IndexDirectoryWriter directoryWriter = new(directory.Span);
        directoryWriter.InitializeEmpty();

        ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = IndexDirectory.ActiveSlots;
        for (int i = 0; i < activeSlots.Length; i++)
        {
            IndexDirectorySlotSnapshot existing = activeSlots[i];
            if (existing.SlotIndex != updatedSlot.SlotIndex)
            {
                directoryWriter.WriteSlot(existing);
            }
        }

        directoryWriter.WriteSlot(updatedSlot);
        IndexDirectorySnapshot updatedDirectory = IndexDirectorySnapshot.FromBytes(directory.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        IndexDirectory = updatedDirectory;

        RouteChainCreationResult result = new(rootOffset, finalTargetOffset, routerCount);
        return (result, telemetry);
    }

    /// <summary>
    /// Updates one route target in an existing router page and commits the full 4 KiB router page in place.<br/>
    /// This keeps the route slot shape intact and makes the route mutation structurally dirty through the write operation.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset where the router page starts.</param>
    /// <param name="routeIndex">The zero-based route slot index to update.</param>
    /// <param name="prefixStart">The inclusive route prefix start byte to persist.</param>
    /// <param name="prefixEnd">The inclusive route prefix end byte to persist.</param>
    /// <param name="targetOffset">The route target offset to persist.</param>
    /// <returns>The DataKernel commit telemetry for the router rewrite.</returns>
    internal DataKernelCommitTelemetry UpdateRouterRoute(
        long routerOffset,
        int routeIndex,
        byte prefixStart,
        byte prefixEnd,
        long targetOffset)
    {
        byte[] existing = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, existing);
        RouterReader existingReader = new(existing);
        if (!existingReader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        if ((uint)routeIndex >= existingReader.RouteCount)
        {
            throw new ArgumentOutOfRangeException(nameof(routeIndex), routeIndex, "Route index is outside the persisted route count.");
        }

        RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
        existing.CopyTo(router.Span);
        RouterWriter writer = new(router.Span);
        writer.WriteRoute(routeIndex, prefixStart, prefixEnd, targetOffset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return telemetry;
    }

    /// <summary>
    /// Attempts to publish one route target only when the selected route still points at the expected source target.<br/>
    /// This supports cold copy/build/publish maintenance: the optimizer can build replacement route state outside the hot path, then use this method as a short version-checked publish step.<br/>
    /// A false return means another writer or structural change already changed the selected route; the caller should discard or requeue the replacement subtree rather than overwrite the newer route.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset where the router page starts.</param>
    /// <param name="prefixByte">The one-byte prefix used to select the route slot.</param>
    /// <param name="expectedTargetOffset">The route target offset observed before the cold replacement was built.</param>
    /// <param name="replacementTargetOffset">The replacement route target offset to publish when the expected target still matches.</param>
    /// <param name="telemetry">The DataKernel commit telemetry for the router rewrite, or default when the expected target no longer matches.</param>
    /// <returns>True when the replacement target was published; false when the selected route no longer matched <paramref name="expectedTargetOffset"/>.</returns>
    internal bool TryUpdateRouterRouteTargetIfCurrent(
        long routerOffset,
        byte prefixByte,
        long expectedTargetOffset,
        long replacementTargetOffset,
        out DataKernelCommitTelemetry telemetry)
    {
        byte[] existing = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, existing);
        RouterReader existingReader = new(existing);
        if (!existingReader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        long currentTargetOffset = existingReader.FindTarget(prefixByte, out int routeIndex);
        if (routeIndex < 0 || currentTargetOffset != expectedTargetOffset)
        {
            telemetry = default;
            return false;
        }

        ReadOnlySpan<byte> route = RouterLayout.GetRoute(existing, routeIndex);
        byte prefixStart = RouterLayout.ReadRoutePrefixStart(route);
        byte prefixEnd = RouterLayout.ReadRoutePrefixEnd(route);
        RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
        existing.CopyTo(router.Span);
        RouterWriter writer = new(router.Span);
        writer.WriteRoute(routeIndex, prefixStart, prefixEnd, replacementTargetOffset);

        telemetry = CommitAndInvalidateRouterReadCache();
        return true;
    }

    /// <summary>
    /// Repoints one selected prefix in a one-byte router while preserving every sibling prefix target.<br/>
    /// This is used when a shared shelf is converted to a terminal identity route for one exact key and the rest of the parent route fanout must continue to see the old shelf.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset where the parent router page starts.</param>
    /// <param name="prefixByte">The selected one-byte route prefix to repoint.</param>
    /// <param name="expectedTargetOffset">The target offset that must still be selected by <paramref name="prefixByte"/>.</param>
    /// <param name="replacementTargetOffset">The replacement target for only <paramref name="prefixByte"/>.</param>
    /// <param name="obsoleteTargetLength">The byte length of the old target extent when the caller can release it after the selected prefix no longer has sibling references, or zero when no release should occur.</param>
    /// <param name="telemetry">The DataKernel commit telemetry for the router rewrite, or default when the expected target no longer matches.</param>
    /// <returns>True when the selected prefix was repointed; false when the parent route no longer matched the expected target.</returns>
    private bool TryUpdateSingleByteRouterPrefixTargetIfCurrent(
        long routerOffset,
        byte prefixByte,
        long expectedTargetOffset,
        long replacementTargetOffset,
        int obsoleteTargetLength,
        out DataKernelCommitTelemetry telemetry)
    {
        byte[] existing = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, existing);
        RouterReader reader = new(existing);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        long currentTargetOffset = reader.FindTarget(prefixByte);
        if (currentTargetOffset != expectedTargetOffset)
        {
            telemetry = default;
            return false;
        }

        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < targets.Length; i++)
        {
            targets[i] = reader.FindTarget((byte)i);
        }

        bool oldTargetStillReferenced = false;
        targets[prefixByte] = replacementTargetOffset;
        if (expectedTargetOffset != 0 && obsoleteTargetLength > 0)
        {
            for (int i = 0; i < targets.Length; i++)
            {
                if (targets[i] == expectedTargetOffset)
                {
                    oldTargetStillReferenced = true;
                    break;
                }
            }
        }

        long[] publishedTargets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < publishedTargets.Length; i++)
        {
            long requestedTarget = targets[i];
            if (requestedTarget != 0)
            {
                publishedTargets[i] = requestedTarget;
                continue;
            }

            long existingTarget = reader.FindTarget((byte)i);
            publishedTargets[i] = existingTarget == expectedTargetOffset ? 0 : existingTarget;
        }

        RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
        RouterWriter writer = new(router.Span);
        writer.InitializeExpandedOneByte(
            reader.KeyDepth,
            reader.AllocationClassId,
            publishedTargets);

        InvalidateRouterReadCacheForRouterRewrite(routerOffset);
        telemetry = CommitAndDeferRouterReadCacheInvalidation();
        if (!oldTargetStillReferenced)
        {
            kernel.ReleaseMemoryExtent(expectedTargetOffset, obsoleteTargetLength);
        }

        return true;
    }

    /// <summary>
    /// Replaces one one-byte router prefix and clears all sibling prefix targets in the same router page.<br/>
    /// This is used only after a full `SS8-8` shelf has been proven to contain one duplicate key, so the old shelf is not a valid sibling fallback for nearby keys.<br/>
    /// Clearing siblings keeps range traversal from reaching the obsolete same-key shelf through nonmatching prefixes while future inserts can still create new shelves through the unset-route path.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset where the parent router page starts.<br/></param>
    /// <param name="prefixByte">The exact one-byte prefix that should route to <paramref name="replacementTargetOffset"/>.<br/></param>
    /// <param name="expectedTargetOffset">The current target offset that must still be selected by <paramref name="prefixByte"/>.<br/></param>
    /// <param name="replacementTargetOffset">The replacement target offset for the exact duplicate-key prefix.<br/></param>
    /// <param name="obsoleteTargetLength">The byte length of the obsolete target extent, or zero when no release should be attempted.<br/></param>
    /// <param name="telemetry">The DataKernel commit telemetry for the router rewrite, or default when the expected target no longer matches.<br/></param>
    /// <returns>True when the exact prefix was replaced and siblings were cleared; false when the route no longer matched the expected target.<br/></returns>
    private bool TryReplaceSingleByteRouterPrefixOnlyIfCurrent(
        long routerOffset,
        byte prefixByte,
        long expectedTargetOffset,
        long replacementTargetOffset,
        int obsoleteTargetLength,
        out DataKernelCommitTelemetry telemetry)
    {
        byte[] existing = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, existing);
        RouterReader reader = new(existing);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        long currentTargetOffset = reader.FindTarget(prefixByte);
        if (currentTargetOffset != expectedTargetOffset)
        {
            telemetry = default;
            return false;
        }

        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        targets[prefixByte] = replacementTargetOffset;
        return TryReplaceSingleByteRouterTargetsIfCurrent(
            routerOffset,
            prefixByte,
            expectedTargetOffset,
            targets,
            obsoleteTargetLength,
            out telemetry);
    }

    /// <summary>
    /// Replaces a mixed exhausted-depth `SS8-8` shelf with an exact-key terminal route plus one remainder shelf.<br/>
    /// The source shelf is known to contain the incoming duplicate key and at least one other key that shares the parent route, so preserving the old shelf would duplicate the exact-key rows during range traversal.<br/>
    /// Nonmatching rows are copied into one ordinary shelf and routed only from the prefix bytes present in those rows; unrelated sibling prefixes are left unset for future insert allocation.<br/>
    /// </summary>
    /// <param name="pathTarget">The routed path target that reached the full mixed shelf.<br/></param>
    /// <param name="existingShelf">The read-only source shelf image.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by the source and remainder shelves.<br/></param>
    /// <param name="encodedKey">The exact key that has been promoted to <paramref name="terminalRootOffset"/>.<br/></param>
    /// <param name="terminalRootOffset">The terminal identity root offset for <paramref name="encodedKey"/>.<br/></param>
    /// <param name="expectedTargetOffset">The source shelf offset that must still be selected by the exact-key prefix.<br/></param>
    /// <param name="telemetry">The DataKernel commit telemetry for the parent router rewrite, or default when the expected target no longer matches.<br/></param>
    /// <returns>True when the mixed shelf route was replaced; false when the parent route no longer matched the expected target.<br/></returns>
    private bool TryReplaceScalar8Scalar8MixedDuplicateShelfRoute(
        Scalar8Scalar8RoutePathTarget pathTarget,
        Scalar8Scalar8ReadOnly existingShelf,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        long terminalRootOffset,
        long expectedTargetOffset,
        out DataKernelCommitTelemetry telemetry)
    {
        byte[] remainderShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 remainderShelf = new(remainderShelfBytes, profile);
        remainderShelf.Initialize();
        Span<byte> remainderPrefixes = stackalloc byte[RouterLayout.MaxOneByteRouteCount];
        int remainderCount = 0;
        for (int i = 0; i < existingShelf.ItemCount; i++)
        {
            ulong key = existingShelf.ReadKeyAt(i);
            if (key == encodedKey)
            {
                continue;
            }

            Scalar8Scalar8InsertResult result = remainderShelf.Insert(key, existingShelf.ReadIdentityAt(i), allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected mixed SS8-8 remainder insert at {i}, got {result}.");
            }

            remainderPrefixes[GetScalar8Scalar8Prefix(key, pathTarget.Target.RouterDepth)] = 1;
            remainderCount++;
        }

        if (remainderCount == 0)
        {
            throw new InvalidDataException("The mixed SS8-8 duplicate shelf replacement did not produce a remainder shelf.");
        }

        RawDataReservation remainderAppend = kernel.Reserve(profile.ShelfExtentSize);
        remainderShelfBytes.CopyTo(remainderAppend.Span);

        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < targets.Length; i++)
        {
            if (remainderPrefixes[i] != 0)
            {
                targets[i] = remainderAppend.Extent.Offset;
            }
        }

        targets[pathTarget.RoutePrefixByte] = terminalRootOffset;
        return TryReplaceSingleByteRouterTargetsIfCurrent(
            pathTarget.ParentRouterOffset,
            pathTarget.RoutePrefixByte,
            expectedTargetOffset,
            targets,
            profile.ShelfExtentSize,
            out telemetry);
    }

    /// <summary>
    /// Rewrites a one-byte parent router with caller-provided exact target offsets after verifying the selected prefix still points at the expected source target.<br/>
    /// The method intentionally publishes a complete 256-entry direct router so stale broad routes cannot keep obsolete shelves reachable after structural duplicate-key promotion.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset where the parent router page starts.<br/></param>
    /// <param name="prefixByte">The prefix used for the compare-and-publish guard.<br/></param>
    /// <param name="expectedTargetOffset">The target offset that must still be selected by <paramref name="prefixByte"/>.<br/></param>
    /// <param name="targets">The complete 256-entry replacement target table.<br/></param>
    /// <param name="obsoleteTargetLength">The byte length of the obsolete source target, or zero when no release should be attempted.<br/></param>
    /// <param name="telemetry">The DataKernel commit telemetry for the router rewrite, or default when the expected target no longer matches.<br/></param>
    /// <returns>True when the router targets were published; false when the selected route no longer matched the expected source target.<br/></returns>
    private bool TryReplaceSingleByteRouterTargetsIfCurrent(
        long routerOffset,
        byte prefixByte,
        long expectedTargetOffset,
        ReadOnlySpan<long> targets,
        int obsoleteTargetLength,
        out DataKernelCommitTelemetry telemetry)
    {
        if (targets.Length != RouterLayout.MaxOneByteRouteCount)
        {
            throw new ArgumentException("Replacement SS8-8 router targets must contain exactly 256 offsets.", nameof(targets));
        }

        byte[] existing = new byte[RouterLayout.Size];
        kernel.Read(routerOffset, existing);
        RouterReader reader = new(existing);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        long currentTargetOffset = reader.FindTarget(prefixByte);
        if (currentTargetOffset != expectedTargetOffset)
        {
            telemetry = default;
            return false;
        }

        long[] publishedTargets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < publishedTargets.Length; i++)
        {
            long requestedTarget = targets[i];
            if (requestedTarget != 0)
            {
                publishedTargets[i] = requestedTarget;
                continue;
            }

            long existingTarget = reader.FindTarget((byte)i);
            publishedTargets[i] = existingTarget == expectedTargetOffset ? 0 : existingTarget;
        }

        RawDataReservation router = kernel.ReserveAt(routerOffset, RouterLayout.Size);
        RouterWriter writer = new(router.Span);
        writer.InitializeExpandedOneByte(
            reader.KeyDepth,
            reader.AllocationClassId,
            publishedTargets);

        InvalidateRouterReadCacheForRouterRewrite(routerOffset);
        telemetry = CommitAndDeferRouterReadCacheInvalidation();
        if (expectedTargetOffset != 0 && obsoleteTargetLength > 0)
        {
            kernel.ReleaseMemoryExtent(expectedTargetOffset, obsoleteTargetLength);
        }

        return true;
    }

    /// <summary>
    /// Gets or creates internal optimizer state for one variable-length index root.<br/>
    /// This is the first session-owned lifecycle hook for varlen optimization: callers no longer need to own raw queue objects, but public API exposure remains deferred.<br/>
    /// Repeated calls for the same root return the existing state, so threshold policy should be selected before observations begin.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset whose route pressure should be observed.</param>
    /// <param name="depthThreshold">The minimum routed depth required before an observation can count toward a candidate.</param>
    /// <param name="shelfItemThreshold">The minimum landing shelf item count required before an observation can count toward a candidate.</param>
    /// <param name="hitThreshold">The number of qualifying observations needed before the prefix is enqueued.</param>
    /// <returns>The session-owned optimizer state for the supplied root router offset.</returns>
    internal VarLenRouteOptimizerState GetOrCreateVarLenRouteOptimizerState(
        long rootRouterOffset,
        int depthThreshold,
        int shelfItemThreshold,
        int hitThreshold)
    {
        if (!varLenRouteOptimizerStates.TryGetValue(rootRouterOffset, out VarLenRouteOptimizerState? state))
        {
            state = new VarLenRouteOptimizerState(rootRouterOffset, depthThreshold, shelfItemThreshold, hitThreshold);
            varLenRouteOptimizerStates.Add(rootRouterOffset, state);
        }

        return state;
    }

    /// <summary>
    /// Gets or creates internal optimizer state for one variable-length index root using a policy object.<br/>
    /// This overload is the preferred internal hook for production-style scheduling because threshold policy and maintenance mode remain a single value at the call site.<br/>
    /// Repeated calls for the same root return the existing state, so callers should select the policy before observations begin.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset whose route pressure should be observed.</param>
    /// <param name="policy">The optimizer maintenance policy supplying observation thresholds.</param>
    /// <returns>The session-owned optimizer state for the supplied root router offset.</returns>
    internal VarLenRouteOptimizerState GetOrCreateVarLenRouteOptimizerState(
        long rootRouterOffset,
        VarLenOptimizerMaintenancePolicy policy)
    {
        return GetOrCreateVarLenRouteOptimizerState(
            rootRouterOffset,
            policy.DepthThreshold,
            policy.ShelfItemThreshold,
            policy.HitThreshold);
    }

    /// <summary>
    /// Gets or creates internal optimizer state for a runtime `VS8` varlen index handle.<br/>
    /// This is the lifecycle-oriented overload that lets varlen write code use the handle rather than repeating root and threshold policy values at each call site.<br/>
    /// </summary>
    /// <param name="handle">The runtime `VS8` index handle that owns the optimizer state.</param>
    /// <returns>The session-owned optimizer state for the handle's root router offset.</returns>
    internal VarLenRouteOptimizerState GetOrCreateVarLenRouteOptimizerState(VarKeyScalar8IndexHandle handle)
    {
        handle.Validate();
        return GetOrCreateVarLenRouteOptimizerState(handle.RootRouterOffset, handle.OptimizerPolicy);
    }

    /// <summary>
    /// Gets or creates internal optimizer state for a runtime `VS16` varlen index handle.<br/>
    /// This mirrors the `VS8` lifecycle overload so both identity widths carry optimizer state through the same internal handle contract.<br/>
    /// </summary>
    /// <param name="handle">The runtime `VS16` index handle that owns the optimizer state.</param>
    /// <returns>The session-owned optimizer state for the handle's root router offset.</returns>
    internal VarLenRouteOptimizerState GetOrCreateVarLenRouteOptimizerState(VarKeyScalar16IndexHandle handle)
    {
        handle.Validate();
        return GetOrCreateVarLenRouteOptimizerState(handle.RootRouterOffset, handle.OptimizerPolicy);
    }

    /// <summary>
    /// Records one `VS8` walked-write optimizer observation through a runtime varlen index handle.<br/>
    /// The caller supplies the insert ordinal, key bytes, and routed insert result already produced by the hot write path; this method resolves the session-owned optimizer state and records only those existing route facts.<br/>
    /// A <see langword="true"/> return means the observation queued a new optimizer candidate that a between-action or on-demand maintenance boundary may later drain.<br/>
    /// </summary>
    /// <param name="handle">The runtime `VS8` handle that owns the optimizer state and root router offset.</param>
    /// <param name="insertOrdinal">The 1-based write ordinal used for optimizer evidence and later build-slice selection.</param>
    /// <param name="key">The variable-length key bytes that were inserted.</param>
    /// <param name="result">The routed insert result containing target depth, shelf item count, and current target offset.</param>
    /// <returns><see langword="true"/> when this observation queued a new optimizer candidate.</returns>
    internal bool ObserveVarKeyScalar8OptimizerWrite(
        VarKeyScalar8IndexHandle handle,
        int insertOrdinal,
        ReadOnlySpan<byte> key,
        VarKeyScalar8RoutedInsertResult result)
    {
        handle.Validate();
        VarLenRouteOptimizerState state = GetOrCreateVarLenRouteOptimizerState(handle);
        return state.Observe(
            insertOrdinal,
            key,
            result.TargetRouterDepth,
            result.TargetShelfItemCount,
            handle.RootRouterOffset,
            result.PrimaryOffset);
    }

    /// <summary>
    /// Records one `VS16` walked-write optimizer observation through a runtime varlen index handle.<br/>
    /// This mirrors the `VS8` observation bridge while preserving the shape-specific routed insert result type used by the 16-byte identity write path.<br/>
    /// The method keeps root ownership and policy lookup behind the handle so callers do not manually repeat root offsets when collecting optimizer telemetry.<br/>
    /// </summary>
    /// <param name="handle">The runtime `VS16` handle that owns the optimizer state and root router offset.</param>
    /// <param name="insertOrdinal">The 1-based write ordinal used for optimizer evidence and later build-slice selection.</param>
    /// <param name="key">The variable-length key bytes that were inserted.</param>
    /// <param name="result">The routed insert result containing target depth, shelf item count, and current target offset.</param>
    /// <returns><see langword="true"/> when this observation queued a new optimizer candidate.</returns>
    internal bool ObserveVarKeyScalar16OptimizerWrite(
        VarKeyScalar16IndexHandle handle,
        int insertOrdinal,
        ReadOnlySpan<byte> key,
        VarKeyScalar16RoutedInsertResult result)
    {
        handle.Validate();
        VarLenRouteOptimizerState state = GetOrCreateVarLenRouteOptimizerState(handle);
        return state.Observe(
            insertOrdinal,
            key,
            result.TargetRouterDepth,
            result.TargetShelfItemCount,
            handle.RootRouterOffset,
            result.PrimaryOffset);
    }

    /// <summary>
    /// Returns whether optimizer maintenance may run at the supplied scheduler boundary for a session-owned varlen optimizer state.<br/>
    /// This keeps hot-write loops limited to fact collection while giving automatic and on-demand callers a common policy check before draining a bounded candidate.<br/>
    /// </summary>
    /// <param name="policy">The optimizer maintenance policy to evaluate.</param>
    /// <param name="boundary">The scheduler boundary where maintenance is being considered.</param>
    /// <param name="candidateQueued">Whether the latest observation queued a candidate.</param>
    /// <param name="state">The optimizer state that owns the queued candidate.</param>
    /// <param name="alreadyPublishedAtBoundary">The number of candidates already published at this boundary.</param>
    /// <returns><see langword="true"/> when one optimizer candidate may be drained.</returns>
    internal static bool ShouldRunVarLenOptimizerMaintenance(
        VarLenOptimizerMaintenancePolicy policy,
        VarLenOptimizerMaintenanceBoundary boundary,
        bool candidateQueued,
        VarLenRouteOptimizerState state,
        int alreadyPublishedAtBoundary)
    {
        if (!state.TryGetCandidate(alreadyPublishedAtBoundary, out VarLenRouteOptimizerCandidate candidate) ||
            candidate.LastObservedAt == 0)
        {
            return false;
        }

        return policy.ShouldDrain(boundary, candidateQueued, alreadyPublishedAtBoundary);
    }

    /// <summary>
    /// Attempts to publish a variable-length route optimizer replacement using a queued candidate as evidence.<br/>
    /// The candidate's captured target is not trusted as the publication token; the method re-reads the current route target immediately before attempting the version-checked update.<br/>
    /// Callers should stage the replacement target in the active durability batch before calling this method, then commit that batch only when the returned result reports a publication.<br/>
    /// </summary>
    /// <param name="candidate">The queued optimizer candidate that identified the route pressure.</param>
    /// <param name="rootRouterOffset">The root router offset that owns the route being optimized.</param>
    /// <param name="rootPrefix">The root prefix byte whose target should be replaced.</param>
    /// <param name="replacementTargetOffset">The staged replacement router or shelf target offset.</param>
    /// <param name="builtKeyCount">The number of keys the caller used to build the replacement target.</param>
    /// <returns>A maintenance result describing stale-candidate status, refreshed route state, and publish success.</returns>
    internal VarLenOptimizerMaintenanceResult TryPublishVarLenOptimizerReplacement(
        VarLenRouteOptimizerCandidate candidate,
        long rootRouterOffset,
        byte rootPrefix,
        long replacementTargetOffset,
        int builtKeyCount)
    {
        if (candidate.LastObservedAt == 0)
        {
            throw new InvalidDataException("The varlen route optimizer publish requires an enqueued candidate.");
        }

        if (candidate.RootRouterOffset != 0 &&
            candidate.RootRouterOffset != rootRouterOffset)
        {
            throw new InvalidDataException("The varlen route optimizer candidate belongs to a different root router.");
        }

        Stopwatch watch = Stopwatch.StartNew();
        long refreshedTarget = FindRouterTarget(rootRouterOffset, rootPrefix);
        bool published = TryUpdateRouterRouteTargetIfCurrent(rootRouterOffset, rootPrefix, refreshedTarget, replacementTargetOffset, out _);
        watch.Stop();
        return new VarLenOptimizerMaintenanceResult(
            ConsideredCount: 1,
            AttemptedCount: 1,
            PublishedCount: published ? 1 : 0,
            CoveredCandidateCount: 0,
            StaleCandidateTargetCount: refreshedTarget == candidate.CurrentTargetOffset ? 0 : 1,
            RejectedCount: published ? 0 : 1,
            BuiltKeyCount: builtKeyCount,
            CandidateTargetOffset: candidate.CurrentTargetOffset,
            RefreshedTargetOffset: refreshedTarget,
            ReplacementTargetOffset: replacementTargetOffset,
            Elapsed: watch.Elapsed);
    }

    /// <summary>
    /// Reads a router page and materializes its header into a cacheable snapshot.<br/>
    /// This is a validation and reopen helper; hot routing will use cached/page-resident router views later.<br/>
    /// </summary>
    /// <param name="offset">The file offset where the router page starts.</param>
    /// <returns>A snapshot of the router header fields.</returns>
    /// <exception cref="InvalidDataException">Thrown when the router bytes do not match the router layout.</exception>
    internal RouterSnapshot ReadRouterSnapshot(long offset)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        return RouterSnapshot.FromReader(offset, reader);
    }

    /// <summary>
    /// Reads a direct-index router target from a persisted router page.<br/>
    /// Offset zero means the route is present but does not yet point to a child page.<br/>
    /// </summary>
    /// <param name="offset">The file offset where the router page starts.</param>
    /// <param name="prefixByte">The prefix byte used as direct route index.</param>
    /// <returns>The persisted target offset for the prefix byte, or zero when unset.</returns>
    /// <exception cref="InvalidDataException">Thrown when the router is invalid or is not direct-index capable.</exception>
    internal long ReadDirectRouterTarget(long offset, byte prefixByte)
    {
        byte[] routerBytes = new byte[RouterLayout.Size];
        kernel.Read(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid || !reader.HasDirectIndex)
        {
            throw new InvalidDataException("The router page is invalid or not direct-index capable.");
        }

        return reader.GetDirectTarget(prefixByte);
    }

    /// <summary>
    /// Reads a router page and finds the target for one prefix byte using that router's persisted lookup mode.<br/>
    /// Direct-index routers use array indexing; compressed routers use route range search.<br/>
    /// </summary>
    /// <param name="offset">The file offset where the router page starts.</param>
    /// <param name="prefixByte">The prefix byte to route.</param>
    /// <returns>The matched target offset, or zero when no target is set.</returns>
    /// <exception cref="InvalidDataException">Thrown when the router is invalid.</exception>
    internal long FindRouterTarget(long offset, byte prefixByte)
    {
        if (TryGetDirectRouterView(offset, out DirectRouterView? directView))
        {
            return directView!.GetTarget(prefixByte);
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingPageCache(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        return reader.FindTarget(prefixByte);
    }

    /// <summary>
    /// Resolves the contiguous direct-router prefix range that maps one selected prefix to the expected target offset.<br/>
    /// Fixed-scalar monotonic batch cursors use the retained range to validate adjacent keys without re-entering session router lookup on every insert.<br/>
    /// </summary>
    /// <param name="routerOffset">The direct parent router offset.<br/></param>
    /// <param name="prefixByte">The selected prefix byte.<br/></param>
    /// <param name="expectedTargetOffset">The shelf offset expected at the selected prefix.<br/></param>
    /// <param name="prefixStart">Receives the first contiguous prefix mapped to the expected target.<br/></param>
    /// <param name="prefixEnd">Receives the last contiguous prefix mapped to the expected target.<br/></param>
    /// <returns><see langword="true"/> when the router is direct and the selected prefix still maps to the expected target; otherwise <see langword="false"/>.<br/></returns>
    internal bool TryGetDirectRouterTargetPrefixRange(
        long routerOffset,
        byte prefixByte,
        long expectedTargetOffset,
        out byte prefixStart,
        out byte prefixEnd)
    {
        if (TryGetDirectRouterView(routerOffset, out DirectRouterView? view))
        {
            return view!.TryGetTargetPrefixRange(prefixByte, expectedTargetOffset, out prefixStart, out prefixEnd);
        }

        prefixStart = prefixByte;
        prefixEnd = prefixByte;
        return false;
    }

    /// <summary>
    /// Tries to expose the persisted key depth of an existing session-promoted direct router.<br/>
    /// Range readers use this narrow projection to expand the same authoritative route table without copying and reparsing its 4 KiB persisted page on every cursor.<br/>
    /// Compressed routers return <see langword="false"/> and continue through the normal persisted-router reader path.<br/>
    /// </summary>
    /// <param name="routerOffset">The durable file offset of the router to inspect.<br/></param>
    /// <param name="keyDepth">Receives the router key depth when the target is direct-index capable.<br/></param>
    /// <returns><see langword="true"/> when a promoted direct-router projection is available; otherwise <see langword="false"/>.<br/></returns>
    internal bool TryGetDirectRouterKeyDepth(long routerOffset, out ushort keyDepth)
    {
        if (TryGetDirectRouterView(routerOffset, out DirectRouterView? view))
        {
            keyDepth = view!.KeyDepth;
            return true;
        }

        keyDepth = 0;
        return false;
    }

    /// <summary>
    /// Tries to expose the key depth of a direct router only when that router already has a session-promoted projection.<br/>
    /// Unlike <see cref="TryGetDirectRouterKeyDepth"/>, this probe never reads or classifies the supplied file offset, so callers can safely test an offset whose shelf-or-router kind is not yet known.<br/>
    /// </summary>
    /// <param name="routerOffset">The possible durable router file offset.<br/></param>
    /// <param name="keyDepth">Receives the promoted router key depth when present.<br/></param>
    /// <returns><see langword="true"/> when the offset is already known as a promoted direct router; otherwise <see langword="false"/>.<br/></returns>
    internal bool TryGetPromotedDirectRouterKeyDepth(long routerOffset, out ushort keyDepth)
    {
        if (directRouterViewCache.TryGetValue(routerOffset, out DirectRouterView? view))
        {
            keyDepth = view.KeyDepth;
            return true;
        }

        keyDepth = 0;
        return false;
    }

    /// <summary>
    /// Gets or creates a decoded direct-index router view for a router page.<br/>
    /// Direct router views promote the persisted 10-byte route slots into a RAM target-offset array while preserving compact router bytes on disk.<br/>
    /// </summary>
    /// <param name="offset">The file offset where the router page starts.</param>
    /// <param name="view">The decoded direct router view when the router is direct-index capable.</param>
    /// <returns>True when a direct-index view is available; false when the router is valid but compressed.</returns>
    /// <exception cref="InvalidDataException">Thrown when the router page is invalid.</exception>
    private bool TryGetDirectRouterView(long offset, out DirectRouterView? view)
    {
        if (directRouterViewCache.TryGetValue(offset, out view))
        {
            RecordVarKeyScalar8PhaseAllocation("route/direct-view-hit", 0, 0);
            return true;
        }

        long createStart = 0;
        long createAllocatedStart = 0;
        lock (routerReadCacheSync)
        {
            if (directRouterViewCache.TryGetValue(offset, out view))
            {
                RecordVarKeyScalar8PhaseAllocation("route/direct-view-hit", 0, 0);
                return true;
            }

            if (nonDirectRouterViewOffsets.Contains(offset))
            {
                RecordVarKeyScalar8PhaseAllocation("route/direct-view-nondirect-hit", 0, 0);
                view = null;
                return false;
            }

            createStart = StartVarKeyScalar8PhaseTicks();
            createAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingPageCache(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        lock (routerReadCacheSync)
        {
            if (directRouterViewCache.TryGetValue(offset, out view))
            {
                RecordVarKeyScalar8PhaseAllocation("route/direct-view-hit", 0, 0);
                return true;
            }

            if (nonDirectRouterViewOffsets.Contains(offset))
            {
                RecordVarKeyScalar8PhaseAllocation("route/direct-view-nondirect-hit", 0, 0);
                view = null;
                return false;
            }

            if (!reader.HasDirectIndex)
            {
                nonDirectRouterViewOffsets.Add(offset);
                view = null;
                RecordVarKeyScalar8RouteAllocation("route/direct-view-nondirect-create", createStart, createAllocatedStart);
                return false;
            }

            long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
            Scalar8Scalar8RouteTargetKind[] targetKinds = new Scalar8Scalar8RouteTargetKind[RouterLayout.MaxOneByteRouteCount];
            uint[] targetRouterRamOffsets = new uint[RouterLayout.MaxOneByteRouteCount];
            for (int i = 0; i < RouterLayout.MaxOneByteRouteCount; i++)
            {
                targets[i] = reader.GetDirectTarget((byte)i);
            }

            view = new DirectRouterView(offset, reader.KeyDepth, reader.AllocationClassId, targets, targetKinds, targetRouterRamOffsets);
            view.RamOffset = promotedRouterArena.Add(view);
            directRouterViewCache.TryAdd(offset, view);
            RecordVarKeyScalar8RouteAllocation("route/direct-view-create", createStart, createAllocatedStart);
            return true;
        }
    }

    /// <summary>
    /// Gets or creates a decoded compressed multi-byte router view for a router page.<br/>
    /// This promotes route stems, final-byte ranges, and target offsets into session-local arrays so repeated `VS8` walked writes do not reread and reinterpret the same compressed router bytes.<br/>
    /// The view is invalidated with the normal router read caches whenever structural writes are committed.<br/>
    /// </summary>
    /// <param name="offset">The file offset where the router page starts.</param>
    /// <param name="view">The decoded multi-byte router view when the router is compressed multi-byte.</param>
    /// <returns>True when a multi-byte router view is available; false when the router is valid but not compressed multi-byte.</returns>
    /// <exception cref="InvalidDataException">Thrown when the router page is invalid.</exception>
    private bool TryGetMultiByteRouterView(long offset, out MultiByteRouterView? view)
    {
        long createStart = 0;
        long createAllocatedStart = 0;
        lock (routerReadCacheSync)
        {
            if (multiByteRouterViewCache.TryGetValue(offset, out view))
            {
                RecordVarKeyScalar8PhaseAllocation("route/multibyte-view-hit", 0, 0);
                return true;
            }

            createStart = StartVarKeyScalar8PhaseTicks();
            createAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(offset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The router page is invalid.");
        }

        lock (routerReadCacheSync)
        {
            if (multiByteRouterViewCache.TryGetValue(offset, out view))
            {
                RecordVarKeyScalar8PhaseAllocation("route/multibyte-view-hit", 0, 0);
                return true;
            }

            if (reader.PrefixByteCount <= 1 || reader.HasDirectIndex)
            {
                view = null;
                RecordVarKeyScalar8RouteAllocation("route/multibyte-view-not-create", createStart, createAllocatedStart);
                return false;
            }

            int routeCount = reader.RouteCount;
            int prefixByteCount = reader.PrefixByteCount;
            int stemLength = prefixByteCount - 1;
            byte[] stems = new byte[checked(routeCount * stemLength)];
            byte[] prefixStarts = new byte[routeCount];
            byte[] prefixEnds = new byte[routeCount];
            long[] targetOffsets = new long[routeCount];
            PromotedRouteTargetKind[] targetKinds = new PromotedRouteTargetKind[routeCount];
            for (int i = 0; i < routeCount; i++)
            {
                routerBytes.Slice(RouterLayout.GetMultiByteRouteStemOffset(reader.MaxRouteCount, reader.PrefixByteCount, i), stemLength).CopyTo(stems.AsSpan(i * stemLength, stemLength));
                ReadOnlySpan<byte> route = RouterLayout.GetRoute(routerBytes, i);
                prefixStarts[i] = RouterLayout.ReadRoutePrefixStart(route);
                prefixEnds[i] = RouterLayout.ReadRoutePrefixEnd(route);
                targetOffsets[i] = RouterLayout.ReadRouteTargetOffset(route);
            }

            view = new MultiByteRouterView(offset, reader.KeyDepth, reader.AllocationClassId, prefixByteCount, stems, prefixStarts, prefixEnds, targetOffsets, targetKinds);
            multiByteRouterViewCache.Add(offset, view);
            RecordVarKeyScalar8RouteAllocation("route/multibyte-view-create", createStart, createAllocatedStart);
            return true;
        }
    }

    /// <summary>
    /// Tries to read a cached `SS8-8` route-target kind for count and extent planning paths.<br/>
    /// The cache stores only the magic-derived structure kind and is invalidated by the DataKernel mutation version, so it avoids repeated four-byte reads without adding persisted route metadata.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset to classify.<br/></param>
    /// <param name="kind">Receives the cached route target kind.<br/></param>
    /// <returns><see langword="true"/> when a current-version cache entry was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetScalar8Scalar8RouteTargetKindCountCache(long targetOffset, out Scalar8Scalar8RouteTargetKind kind)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (scalar8Scalar8RouteTargetKindCountCache.TryGetValue(targetOffset, out kind) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        kind = Scalar8Scalar8RouteTargetKind.None;
        return false;
    }

    /// <summary>
    /// Stores a magic-derived `SS8-8` route-target kind at the current raw-storage mutation version.<br/>
    /// This is a read-side projection only; route topology and target pages remain the sole persisted source of truth.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset that was classified.<br/></param>
    /// <param name="kind">The magic-derived target kind.<br/></param>
    private void StoreScalar8Scalar8RouteTargetKindCountCache(long targetOffset, Scalar8Scalar8RouteTargetKind kind)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            scalar8Scalar8RouteTargetKindCountCache[targetOffset] = kind;
        }
    }

    /// <summary>
    /// Classifies the structure stored at a direct route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while the one-level fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS8-8` shelf magic value.</exception>
    internal Scalar8Scalar8RouteTargetKind ClassifyScalar8Scalar8RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Scalar8Scalar8RouteTargetKind.None;
        }

        if (TryGetScalar8Scalar8RouteTargetKindCountCache(targetOffset, out Scalar8Scalar8RouteTargetKind cachedKind))
        {
            return cachedKind;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            StoreScalar8Scalar8RouteTargetKindCountCache(targetOffset, Scalar8Scalar8RouteTargetKind.Router);
            return Scalar8Scalar8RouteTargetKind.Router;
        }

        if (magic == Scalar8Scalar8Layout.Magic)
        {
            StoreScalar8Scalar8RouteTargetKindCountCache(targetOffset, Scalar8Scalar8RouteTargetKind.Shelf);
            return Scalar8Scalar8RouteTargetKind.Shelf;
        }

        if (magic == TerminalIdentityRootLayout.Magic)
        {
            StoreScalar8Scalar8RouteTargetKindCountCache(targetOffset, Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot);
            return Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot;
        }

        throw new InvalidDataException($"Route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Counts ordinary `SS8-8` identities by walking routed targets and summing shelf-local live counts.<br/>
    /// Unlike the range reader, this count path does not retain shelf images or allocate cursor extent arrays because no caller can subsequently read rows from the result.<br/>
    /// Terminal identity roots are counted by walking their identity shelf chains and summing terminal shelf item counts.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by leaf shelves.</param>
    /// <returns>The number of ordinary identities reachable from the routed `SS8-8` root.</returns>
    internal long CountScalar8Scalar8Identities(long rootRouterOffset, Scalar8Scalar8Profile profile)
    {
        if (rootRouterOffset <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(rootRouterOffset), rootRouterOffset, "Root router offset must be positive.");
        }

        HashSet<long> visitedTargets = [];
        HashSet<long> visitedRouters = [];
        return CountScalar8Scalar8IdentitiesFromRouter(rootRouterOffset, profile, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts identities under one `SS8-8` router, visiting each reachable shelf or child router at most once.<br/>
    /// Router slots can share targets across prefix ranges, so visited sets are part of correctness rather than just cycle protection.<br/>
    /// </summary>
    /// <param name="routerOffset">The router page to count below.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by leaf shelves.</param>
    /// <param name="visitedTargets">The set of already-counted shelf and terminal-root offsets.</param>
    /// <param name="visitedRouters">The set of already-walked router offsets.</param>
    /// <returns>The number of identities reachable below <paramref name="routerOffset"/>.</returns>
    private long CountScalar8Scalar8IdentitiesFromRouter(
        long routerOffset,
        Scalar8Scalar8Profile profile,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 count router is invalid.");
        }

        long count = 0;
        if (router.HasDirectIndex)
        {
            for (int routeIndex = 0; routeIndex < RouterLayout.MaxOneByteRouteCount; routeIndex++)
            {
                count += CountScalar8Scalar8RouteTarget(
                    router.GetRouteTargetAt(routeIndex),
                    profile,
                    visitedTargets,
                    visitedRouters);
            }

            return count;
        }

        for (int routeIndex = 0; routeIndex < router.RouteCount; routeIndex++)
        {
            count += CountScalar8Scalar8RouteTarget(
                router.GetRouteTargetAt(routeIndex),
                profile,
                visitedTargets,
                visitedRouters);
        }

        return count;
    }

    /// <summary>
    /// Counts one physical `SS8-8` route target without requiring ordered prefix traversal.<br/>
    /// Router targets recurse, shelf targets use narrow shelf metadata reads, and terminal identity roots use narrow root/shelf header reads.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset, or zero for an empty route.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by ordinary shelves.<br/></param>
    /// <param name="visitedTargets">The set of already-counted shelf and terminal-root offsets.<br/></param>
    /// <param name="visitedRouters">The set of already-walked router offsets.<br/></param>
    /// <returns>The number of identities reachable from the target.<br/></returns>
    private long CountScalar8Scalar8RouteTarget(
        long targetOffset,
        Scalar8Scalar8Profile profile,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (targetOffset == 0)
        {
            return 0;
        }

        Scalar8Scalar8RouteTargetCountCacheKey cacheKey = new(
            targetOffset,
            profile.MaxItemCount,
            Scalar8Scalar8Layout.GetDuplicateRunCapacity(profile));
        if (TryApplyScalar8Scalar8RouteTargetCountCache(cacheKey, visitedTargets, visitedRouters, out long cachedCount))
        {
            return cachedCount;
        }

        if (visitedTargets.Contains(targetOffset) ||
            visitedRouters.Contains(targetOffset))
        {
            return 0;
        }

        HashSet<long> targetVisitedTargets = [];
        HashSet<long> targetVisitedRouters = [];
        long targetCount = CountScalar8Scalar8RouteTargetUncached(
            targetOffset,
            profile,
            targetVisitedTargets,
            targetVisitedRouters);
        StoreScalar8Scalar8RouteTargetCountCache(cacheKey, targetCount, targetVisitedTargets, targetVisitedRouters);
        if (TryApplyScalar8Scalar8RouteTargetVisitedOffsets(targetVisitedTargets, targetVisitedRouters, visitedTargets, visitedRouters))
        {
            return targetCount;
        }

        return CountScalar8Scalar8RouteTargetUncached(targetOffset, profile, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts one physical `SS8-8` route target using the supplied visited sets directly.<br/>
    /// This helper preserves the original shared-target semantics and is used both to build independent route-target count cache entries and to fall back when a cached subtree overlaps already-counted offsets.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used by ordinary shelves.<br/></param>
    /// <param name="visitedTargets">The target offsets already counted in the current traversal.<br/></param>
    /// <param name="visitedRouters">The router offsets already walked in the current traversal.<br/></param>
    /// <returns>The number of identities reachable from the target after honoring the supplied visited sets.<br/></returns>
    private long CountScalar8Scalar8RouteTargetUncached(
        long targetOffset,
        Scalar8Scalar8Profile profile,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTarget(targetOffset);
        return kind switch
        {
            Scalar8Scalar8RouteTargetKind.Router => CountScalar8Scalar8IdentitiesFromRouter(targetOffset, profile, visitedTargets, visitedRouters),
            Scalar8Scalar8RouteTargetKind.Shelf => CountScalar8Scalar8ShelfChain(targetOffset, profile, visitedTargets),
            Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot => CountScalar8Scalar8TerminalIdentityRoot(targetOffset, visitedTargets),
            _ => throw new InvalidDataException("The routed SS8-8 count target is not a shelf, terminal identity root, or router.")
        };
    }

    /// <summary>
    /// Tries to apply a cached `SS8-8` route-target aggregate to the current traversal visited sets.<br/>
    /// Cached aggregates carry their counted target/router offsets, so shared route structures are still counted at most once even when the count itself is reused.<br/>
    /// </summary>
    /// <param name="key">The physical route-target/profile cache key.<br/></param>
    /// <param name="visitedTargets">The current traversal's counted target offsets.<br/></param>
    /// <param name="visitedRouters">The current traversal's walked router offsets.<br/></param>
    /// <param name="count">Receives the cached aggregate count when it can be applied without overlap.<br/></param>
    /// <returns><see langword="true"/> when the cached aggregate was current and non-overlapping; otherwise <see langword="false"/>.<br/></returns>
    private bool TryApplyScalar8Scalar8RouteTargetCountCache(
        Scalar8Scalar8RouteTargetCountCacheKey key,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        out long count)
    {
        long mutationVersion = kernel.MutationVersion;
        Scalar8Scalar8RouteTargetCountCacheValue value;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (!scalar8Scalar8RouteTargetCountCache.TryGetValue(key, out value) ||
                kernel.MutationVersion != mutationVersion)
            {
                count = 0;
                return false;
            }
        }

        if (!TryApplyScalar8Scalar8RouteTargetVisitedOffsets(
            value.TargetOffsets,
            value.RouterOffsets,
            visitedTargets,
            visitedRouters))
        {
            count = 0;
            return false;
        }

        count = value.Count;
        return true;
    }

    /// <summary>
    /// Stores one independent `SS8-8` route-target aggregate at the current raw-storage mutation version.<br/>
    /// The aggregate is derived from existing shelf/router metadata and stores the visited offsets needed to replay it safely; no persisted counter or router write is introduced.<br/>
    /// </summary>
    /// <param name="key">The physical route-target/profile cache key.<br/></param>
    /// <param name="count">The independent aggregate count for the route target.<br/></param>
    /// <param name="visitedTargets">The target offsets counted while deriving the aggregate.<br/></param>
    /// <param name="visitedRouters">The router offsets walked while deriving the aggregate.<br/></param>
    private void StoreScalar8Scalar8RouteTargetCountCache(
        Scalar8Scalar8RouteTargetCountCacheKey key,
        long count,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        long mutationVersion = kernel.MutationVersion;
        Scalar8Scalar8RouteTargetCountCacheValue value = new(count, [.. visitedTargets], [.. visitedRouters]);
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            scalar8Scalar8RouteTargetCountCache[key] = value;
        }
    }

    /// <summary>
    /// Applies visited offsets from a freshly-derived `SS8-8` route-target aggregate to an outer traversal.<br/>
    /// The method checks for overlap before mutating the outer sets, preserving the same shared-target behavior as the uncached walker.<br/>
    /// </summary>
    /// <param name="targetVisitedTargets">The target offsets counted by the independent aggregate.<br/></param>
    /// <param name="targetVisitedRouters">The router offsets walked by the independent aggregate.<br/></param>
    /// <param name="visitedTargets">The outer traversal's target offsets.<br/></param>
    /// <param name="visitedRouters">The outer traversal's router offsets.<br/></param>
    /// <returns><see langword="true"/> when the offsets were non-overlapping and applied; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryApplyScalar8Scalar8RouteTargetVisitedOffsets(
        HashSet<long> targetVisitedTargets,
        HashSet<long> targetVisitedRouters,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        foreach (long targetOffset in targetVisitedTargets)
        {
            if (visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
            {
                return false;
            }
        }

        foreach (long routerOffset in targetVisitedRouters)
        {
            if (visitedTargets.Contains(routerOffset) || visitedRouters.Contains(routerOffset))
            {
                return false;
            }
        }

        foreach (long targetOffset in targetVisitedTargets)
        {
            visitedTargets.Add(targetOffset);
        }

        foreach (long routerOffset in targetVisitedRouters)
        {
            visitedRouters.Add(routerOffset);
        }

        return true;
    }

    /// <summary>
    /// Applies visited offsets from a cached `SS8-8` route-target aggregate to an outer traversal.<br/>
    /// Cached offsets are replayed only when none were already visited, which keeps route sharing and duplicate route entries from double-counting cached subtrees.<br/>
    /// </summary>
    /// <param name="targetVisitedTargets">The target offsets counted by the cached aggregate.<br/></param>
    /// <param name="targetVisitedRouters">The router offsets walked by the cached aggregate.<br/></param>
    /// <param name="visitedTargets">The outer traversal's target offsets.<br/></param>
    /// <param name="visitedRouters">The outer traversal's router offsets.<br/></param>
    /// <returns><see langword="true"/> when the offsets were non-overlapping and applied; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryApplyScalar8Scalar8RouteTargetVisitedOffsets(
        long[] targetVisitedTargets,
        long[] targetVisitedRouters,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        for (int i = 0; i < targetVisitedTargets.Length; i++)
        {
            long targetOffset = targetVisitedTargets[i];
            if (visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
            {
                return false;
            }
        }

        for (int i = 0; i < targetVisitedRouters.Length; i++)
        {
            long routerOffset = targetVisitedRouters[i];
            if (visitedTargets.Contains(routerOffset) || visitedRouters.Contains(routerOffset))
            {
                return false;
            }
        }

        for (int i = 0; i < targetVisitedTargets.Length; i++)
        {
            visitedTargets.Add(targetVisitedTargets[i]);
        }

        for (int i = 0; i < targetVisitedRouters.Length; i++)
        {
            visitedRouters.Add(targetVisitedRouters[i]);
        }

        return true;
    }

    /// <summary>
    /// Counts one `SS8-8` shelf or duplicate-run shelf chain by summing live item counts.<br/>
    /// Duplicate-run shelves are linked outside the router table, so a count-all route walk must follow their next-shelf offsets explicitly.<br/>
    /// </summary>
    /// <param name="shelfOffset">The first shelf offset to count.</param>
    /// <param name="profile">The `SS8-8` shelf profile used to validate and project the shelf.</param>
    /// <param name="visitedTargets">The set of already-counted shelf and terminal-root offsets.</param>
    /// <returns>The number of live identities in the shelf chain.</returns>
    private long CountScalar8Scalar8ShelfChain(long shelfOffset, Scalar8Scalar8Profile profile, HashSet<long> visitedTargets)
    {
        long count = 0;
        long currentOffset = shelfOffset;
        while (currentOffset != 0)
        {
            if (!visitedTargets.Add(currentOffset))
            {
                break;
            }

            count += ReadScalar8Scalar8ShelfLiveCountNarrow(currentOffset, profile, out currentOffset);
        }

        return count;
    }

    /// <summary>
    /// Tries to read a cached narrow count projection for one ordinary or duplicate-run `SS8-8` shelf.<br/>
    /// The cache is keyed by the DataKernel mutation version, so any staged or directly-published raw byte change makes older count metadata unreachable without a persisted invalidation write.<br/>
    /// </summary>
    /// <param name="key">The physical shelf/profile cache key.<br/></param>
    /// <param name="value">Receives the cached count and duplicate-run next-shelf offset.<br/></param>
    /// <returns><see langword="true"/> when a current-version cache entry was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetScalar8Scalar8ShelfCountCache(Scalar8Scalar8ShelfCountCacheKey key, out Scalar8Scalar8ShelfCountCacheValue value)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (scalar8Scalar8ShelfCountCache.TryGetValue(key, out value) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        value = default;
        return false;
    }

    /// <summary>
    /// Stores the narrow count projection for one ordinary or duplicate-run `SS8-8` shelf at the current raw-storage mutation version.<br/>
    /// This is a session-local derived cache only; it does not update shelf, router, or file metadata and therefore stays inside the free-count rule.<br/>
    /// </summary>
    /// <param name="key">The physical shelf/profile cache key.<br/></param>
    /// <param name="count">The live item count read from the normalized shelf header.<br/></param>
    /// <param name="nextShelfOffset">The duplicate-run next-shelf offset, or zero for ordinary shelves.<br/></param>
    private void StoreScalar8Scalar8ShelfCountCache(Scalar8Scalar8ShelfCountCacheKey key, long count, long nextShelfOffset)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            scalar8Scalar8ShelfCountCache[key] = new Scalar8Scalar8ShelfCountCacheValue(count, nextShelfOffset);
        }
    }

    /// <summary>
    /// Reads only the count-bearing bytes from one published `SS8-8` shelf.<br/>
    /// Published ordinary shelves are normalized before rewrite, so the header item count is the live count and no slot-table scan is needed for count-only traversal.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf file offset.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile used to bound item counts.<br/></param>
    /// <param name="nextShelfOffset">Receives the next duplicate-run shelf offset, or zero for ordinary shelves.<br/></param>
    /// <returns>The live identity count represented by the shelf.<br/></returns>
    private long ReadScalar8Scalar8ShelfLiveCountNarrow(
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        out long nextShelfOffset)
    {
        Scalar8Scalar8ShelfCountCacheKey cacheKey = new(
            shelfOffset,
            profile.MaxItemCount,
            Scalar8Scalar8Layout.GetDuplicateRunCapacity(profile));
        if (TryGetScalar8Scalar8ShelfCountCache(cacheKey, out Scalar8Scalar8ShelfCountCacheValue cachedValue))
        {
            nextShelfOffset = cachedValue.NextShelfOffset;
            return cachedValue.Count;
        }

        Span<byte> header = stackalloc byte[Scalar8Scalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (Scalar8Scalar8Layout.ReadMagic(header) != Scalar8Scalar8Layout.Magic ||
            Scalar8Scalar8Layout.ReadFormatVersion(header) != Scalar8Scalar8Layout.FormatVersion ||
            Scalar8Scalar8Layout.ReadHeaderSize(header) != Scalar8Scalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed SS8-8 count shelf header is invalid.");
        }

        ushort itemCount = Scalar8Scalar8Layout.ReadItemCount(header);
        if (Scalar8Scalar8Layout.HasDuplicateRunFlag(header))
        {
            if (itemCount > Scalar8Scalar8Layout.GetDuplicateRunCapacity(profile))
            {
                throw new InvalidDataException("The routed SS8-8 duplicate-run count exceeds the profiled shelf capacity.");
            }

            nextShelfOffset = Scalar8Scalar8Layout.ReadDuplicateRunNextOffset(header);
            StoreScalar8Scalar8ShelfCountCache(cacheKey, itemCount, nextShelfOffset);
            return itemCount;
        }

        if (itemCount > profile.MaxItemCount)
        {
            throw new InvalidDataException("The routed SS8-8 count exceeds the profiled shelf capacity.");
        }

        nextShelfOffset = 0;
        StoreScalar8Scalar8ShelfCountCache(cacheKey, itemCount, nextShelfOffset);
        return itemCount;
    }

    /// <summary>
    /// Counts one `SS8-8` terminal identity root by summing the item counts of its terminal identity shelves.<br/>
    /// Terminal roots store the key once and keep identities in linked shelves, so no key or identity projection is needed for count-all.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root offset.</param>
    /// <param name="visitedTargets">The set of already-counted shelf and terminal-root offsets.</param>
    /// <returns>The number of identities stored under the terminal identity root.</returns>
    private long CountScalar8Scalar8TerminalIdentityRoot(long rootOffset, HashSet<long> visitedTargets)
    {
        if (!visitedTargets.Add(rootOffset))
        {
            return 0;
        }

        Span<byte> rootHeader = stackalloc byte[TerminalIdentityRootLayout.HeaderSize];
        kernel.Read(rootOffset, rootHeader);
        if (TerminalIdentityRootLayout.ReadMagic(rootHeader) != TerminalIdentityRootLayout.Magic ||
            TerminalIdentityRootLayout.ReadFormatVersion(rootHeader) != TerminalIdentityRootLayout.FormatVersion ||
            TerminalIdentityRootLayout.ReadHeaderSize(rootHeader) != TerminalIdentityRootLayout.HeaderSize ||
            TerminalIdentityRootLayout.ReadShape(rootHeader) != TerminalIdentityRootLayout.ShapeScalar8 ||
            TerminalIdentityRootLayout.ReadKeyLength(rootHeader) != Scalar8Scalar8Layout.KeySize)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity root shape is invalid.");
        }

        long count = 0;
        int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootHeader);
        long shelfOffset = TerminalIdentityRootLayout.ReadFirstShelfOffset(rootHeader);
        while (shelfOffset != 0)
        {
            if (!visitedTargets.Add(shelfOffset))
            {
                break;
            }

            count += ReadTerminalIdentity8ShelfCountNarrow(shelfOffset, shelfExtentSize, out shelfOffset);
        }

        return count;
    }

    /// <summary>
    /// Reads only the header bytes needed to count one terminal scalar-8 identity shelf.<br/>
    /// Terminal identity shelves are identity-only append shelves, so count-all does not need to inspect or copy identity payload bytes.<br/>
    /// </summary>
    /// <param name="shelfOffset">The terminal identity shelf offset.<br/></param>
    /// <param name="shelfExtentSize">The terminal shelf extent size recorded by the root.<br/></param>
    /// <param name="nextShelfOffset">Receives the next terminal shelf offset, or zero at the end of the chain.<br/></param>
    /// <returns>The number of identities stored in the terminal shelf.<br/></returns>
    private long ReadTerminalIdentity8ShelfCountNarrow(
        long shelfOffset,
        int shelfExtentSize,
        out long nextShelfOffset)
    {
        TerminalIdentity8ShelfCountCacheKey cacheKey = new(shelfOffset, shelfExtentSize);
        if (TryGetTerminalIdentity8ShelfCountCache(cacheKey, out TerminalIdentity8ShelfCountCacheValue cachedValue))
        {
            nextShelfOffset = cachedValue.NextShelfOffset;
            return cachedValue.Count;
        }

        if (shelfExtentSize < TerminalIdentity8ShelfLayout.HeaderSize)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity shelf extent is smaller than its header.");
        }

        Span<byte> header = stackalloc byte[TerminalIdentity8ShelfLayout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (TerminalIdentity8ShelfLayout.ReadMagic(header) != TerminalIdentity8ShelfLayout.Magic ||
            TerminalIdentity8ShelfLayout.ReadFormatVersion(header) != TerminalIdentity8ShelfLayout.FormatVersion ||
            TerminalIdentity8ShelfLayout.ReadHeaderSize(header) != TerminalIdentity8ShelfLayout.HeaderSize)
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity shelf header is invalid.");
        }

        int itemCount = TerminalIdentity8ShelfLayout.ReadItemCount(header);
        if ((uint)itemCount > (uint)TerminalIdentity8ShelfLayout.GetCapacity(shelfExtentSize))
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity shelf count exceeds capacity.");
        }

        nextShelfOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(header);
        StoreTerminalIdentity8ShelfCountCache(cacheKey, itemCount, nextShelfOffset);
        return itemCount;
    }

    /// <summary>
    /// Tries to read a cached narrow count projection for one scalar-8 terminal identity shelf.<br/>
    /// Terminal identity roots can be revisited by repeated criteria counts, so caching the count-bearing shelf header avoids repeated raw reads while preserving the existing linked-shelf traversal.<br/>
    /// </summary>
    /// <param name="key">The physical terminal shelf/extent cache key.<br/></param>
    /// <param name="value">Receives the cached count and next-shelf offset.<br/></param>
    /// <returns><see langword="true"/> when a current-version cache entry was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetTerminalIdentity8ShelfCountCache(TerminalIdentity8ShelfCountCacheKey key, out TerminalIdentity8ShelfCountCacheValue value)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (terminalIdentity8ShelfCountCache.TryGetValue(key, out value) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        value = default;
        return false;
    }

    /// <summary>
    /// Stores the narrow count projection for one scalar-8 terminal identity shelf at the current raw-storage mutation version.<br/>
    /// The projection contains only metadata already present in the shelf header, so it adds no durability work and no new count maintenance path.<br/>
    /// </summary>
    /// <param name="key">The physical terminal shelf/extent cache key.<br/></param>
    /// <param name="count">The identity count read from the terminal shelf header.<br/></param>
    /// <param name="nextShelfOffset">The next terminal shelf offset, or zero at the end of the chain.<br/></param>
    private void StoreTerminalIdentity8ShelfCountCache(TerminalIdentity8ShelfCountCacheKey key, long count, long nextShelfOffset)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            terminalIdentity8ShelfCountCache[key] = new TerminalIdentity8ShelfCountCacheValue(count, nextShelfOffset);
        }
    }

    /// <summary>
    /// Counts all ordinary `SS16-8` identities by walking physical route entries and reading only shelf count metadata.<br/>
    /// The traversal is count-shaped rather than ordered-reader-shaped: each unique target is classified once, routers recurse immediately, and shelves read only the header plus slot table needed to subtract deleted sentinels.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile used by leaf shelves.<br/></param>
    /// <returns>The number of ordinary identities reachable from the routed `SS16-8` root.<br/></returns>
    internal long CountScalar16Scalar8Identities(long rootRouterOffset, Scalar16Scalar8Profile profile)
    {
        return CountOrdinaryFixedScalarIdentities(rootRouterOffset, profile.MaxItemCount, profile.SlotRegionOffset, Scalar16Scalar8Layout.Magic, "SS16-8");
    }

    /// <summary>
    /// Counts all ordinary `SS8-16` identities by walking physical route entries and reading only shelf count metadata.<br/>
    /// This avoids range-reader allocation, ordered prefix progression, identity copying, and full shelf reads for count-all.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile used by leaf shelves.<br/></param>
    /// <returns>The number of ordinary identities reachable from the routed `SS8-16` root.<br/></returns>
    internal long CountScalar8Scalar16Identities(long rootRouterOffset, Scalar8Scalar16Profile profile)
    {
        return CountOrdinaryFixedScalarIdentities(rootRouterOffset, profile.MaxItemCount, profile.SlotRegionOffset, Scalar8Scalar16Layout.Magic, "SS8-16");
    }

    /// <summary>
    /// Counts all ordinary `SS16-16` identities by walking physical route entries and reading only shelf count metadata.<br/>
    /// The helper intentionally shares the fixed-scalar count walker because the routed topology and count-bearing shelf header are identical in kind to the narrower scalar shapes.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile used by leaf shelves.<br/></param>
    /// <returns>The number of ordinary identities reachable from the routed `SS16-16` root.<br/></returns>
    internal long CountScalar16Scalar16Identities(long rootRouterOffset, Scalar16Scalar16Profile profile)
    {
        return CountOrdinaryFixedScalarIdentities(rootRouterOffset, profile.MaxItemCount, profile.SlotRegionOffset, Scalar16Scalar16Layout.Magic, "SS16-16");
    }

    /// <summary>
    /// Counts all ordinary `FS32-8` identities by walking physical route entries and reading only shelf count metadata.<br/>
    /// This is the fixed-32-key counterpart to the scalar route-entry count path and keeps count-all independent from ordered range-reader traversal.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile used by leaf shelves.<br/></param>
    /// <returns>The number of ordinary identities reachable from the routed `FS32-8` root.<br/></returns>
    internal long CountFixed32Scalar8Identities(long rootRouterOffset, Fixed32Scalar8Profile profile)
    {
        return CountOrdinaryFixedScalarIdentities(rootRouterOffset, profile.MaxItemCount, profile.SlotRegionOffset, Fixed32Scalar8Layout.Magic, "FS32-8");
    }

    /// <summary>
    /// Counts all ordinary `FS32-16` identities by walking physical route entries and reading only shelf count metadata.<br/>
    /// The count path visits each physical shelf once and does not decode keys, inspect identity payloads, or materialize reader ranges.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile used by leaf shelves.<br/></param>
    /// <returns>The number of ordinary identities reachable from the routed `FS32-16` root.<br/></returns>
    internal long CountFixed32Scalar16Identities(long rootRouterOffset, Fixed32Scalar16Profile profile)
    {
        return CountOrdinaryFixedScalarIdentities(rootRouterOffset, profile.MaxItemCount, profile.SlotRegionOffset, Fixed32Scalar16Layout.Magic, "FS32-16");
    }

    /// <summary>
    /// Counts ordinary fixed-scalar route targets for shapes whose route graph contains only routers and ordinary shelves.<br/>
    /// The fixed-scalar shelf family shares the same count-bearing header offsets and 16-bit slot table, so count-all can use one physical route-entry walker without paying ordered-reader costs.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="maxItemCount">The maximum ordinary shelf item count for the selected shape profile.<br/></param>
    /// <param name="slotRegionOffset">The byte offset of the shelf slot table for the selected shape profile.<br/></param>
    /// <param name="shelfMagic">The expected shelf magic value for the selected fixed-scalar shape.<br/></param>
    /// <param name="shapeName">The short shape name used in validation errors.<br/></param>
    /// <returns>The number of live ordinary identities reachable from the root router.<br/></returns>
    private long CountOrdinaryFixedScalarIdentities(long rootRouterOffset, ushort maxItemCount, int slotRegionOffset, uint shelfMagic, string shapeName)
    {
        if (rootRouterOffset <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(rootRouterOffset), rootRouterOffset, "Root router offset must be positive.");
        }

        HashSet<long> visitedTargets = [];
        HashSet<long> visitedRouters = [];
        return CountOrdinaryFixedScalarIdentitiesFromRouter(rootRouterOffset, maxItemCount, slotRegionOffset, shelfMagic, shapeName, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts ordinary fixed-scalar identities below one router by iterating physical route entries rather than ordered logical prefixes.<br/>
    /// Direct-index routers visit each physical route slot, while compressed routers visit only persisted route entries.<br/>
    /// </summary>
    /// <param name="routerOffset">The router page offset to count below.<br/></param>
    /// <param name="maxItemCount">The maximum ordinary shelf item count for the selected shape profile.<br/></param>
    /// <param name="slotRegionOffset">The byte offset of the shelf slot table for the selected shape profile.<br/></param>
    /// <param name="shelfMagic">The expected shelf magic value for the selected fixed-scalar shape.<br/></param>
    /// <param name="shapeName">The short shape name used in validation errors.<br/></param>
    /// <param name="visitedTargets">The set of already-counted shelf offsets.<br/></param>
    /// <param name="visitedRouters">The set of already-walked router offsets.<br/></param>
    /// <returns>The number of live identities below the router.<br/></returns>
    private long CountOrdinaryFixedScalarIdentitiesFromRouter(
        long routerOffset,
        ushort maxItemCount,
        int slotRegionOffset,
        uint shelfMagic,
        string shapeName,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException($"The routed {shapeName} count router is invalid.");
        }

        long count = 0;
        if (router.HasDirectIndex)
        {
            for (int routeIndex = 0; routeIndex < RouterLayout.MaxOneByteRouteCount; routeIndex++)
            {
                count += CountOrdinaryFixedScalarRouteTarget(router.GetRouteTargetAt(routeIndex), maxItemCount, slotRegionOffset, shelfMagic, shapeName, visitedTargets, visitedRouters);
            }

            return count;
        }

        for (int routeIndex = 0; routeIndex < router.RouteCount; routeIndex++)
        {
            count += CountOrdinaryFixedScalarRouteTarget(router.GetRouteTargetAt(routeIndex), maxItemCount, slotRegionOffset, shelfMagic, shapeName, visitedTargets, visitedRouters);
        }

        return count;
    }

    /// <summary>
    /// Counts one ordinary fixed-scalar route target, skipping already-seen physical offsets before any target classification read.<br/>
    /// This keeps compressed or shared route spans from turning one physical shelf into many magic reads during count-all.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset, or zero for an empty route.<br/></param>
    /// <param name="maxItemCount">The maximum ordinary shelf item count for the selected shape profile.<br/></param>
    /// <param name="slotRegionOffset">The byte offset of the shelf slot table for the selected shape profile.<br/></param>
    /// <param name="shelfMagic">The expected shelf magic value for the selected fixed-scalar shape.<br/></param>
    /// <param name="shapeName">The short shape name used in validation errors.<br/></param>
    /// <param name="visitedTargets">The set of already-counted shelf offsets.<br/></param>
    /// <param name="visitedRouters">The set of already-walked router offsets.<br/></param>
    /// <returns>The number of live identities reachable from the target.<br/></returns>
    private long CountOrdinaryFixedScalarRouteTarget(
        long targetOffset,
        ushort maxItemCount,
        int slotRegionOffset,
        uint shelfMagic,
        string shapeName,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (targetOffset == 0 || visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
        {
            return 0;
        }

        OrdinaryFixedScalarRouteTargetCountCacheKey cacheKey = new(targetOffset, maxItemCount, shelfMagic);
        if (TryApplyOrdinaryFixedScalarRouteTargetCountCache(cacheKey, visitedTargets, visitedRouters, out long cachedCount))
        {
            return cachedCount;
        }

        HashSet<long> targetVisitedTargets = [];
        HashSet<long> targetVisitedRouters = [];
        long targetCount = CountOrdinaryFixedScalarRouteTargetUncached(
            targetOffset,
            maxItemCount,
            slotRegionOffset,
            shelfMagic,
            shapeName,
            targetVisitedTargets,
            targetVisitedRouters);
        StoreOrdinaryFixedScalarRouteTargetCountCache(cacheKey, targetCount, targetVisitedTargets, targetVisitedRouters);
        if (TryApplyOrdinaryFixedScalarRouteTargetVisitedOffsets(targetVisitedTargets, targetVisitedRouters, visitedTargets, visitedRouters))
        {
            return targetCount;
        }

        return CountOrdinaryFixedScalarRouteTargetUncached(targetOffset, maxItemCount, slotRegionOffset, shelfMagic, shapeName, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts one ordinary fixed-scalar route target using the supplied visited sets directly.<br/>
    /// The helper is the uncached source of truth for both count-all and range-count aggregate cache derivation, preserving shared-route and router-cycle semantics in one path.<br/>
    /// </summary>
    /// <param name="targetOffset">The physical route target offset.<br/></param>
    /// <param name="maxItemCount">The maximum ordinary shelf item count for the selected shape profile.<br/></param>
    /// <param name="slotRegionOffset">The byte offset of the shelf slot table for the selected shape profile.<br/></param>
    /// <param name="shelfMagic">The expected shelf magic value for the selected fixed-scalar shape.<br/></param>
    /// <param name="shapeName">The short shape name used in validation errors.<br/></param>
    /// <param name="visitedTargets">The target offsets already counted in the current traversal.<br/></param>
    /// <param name="visitedRouters">The router offsets already walked in the current traversal.<br/></param>
    /// <returns>The number of identities reachable from the target after honoring the supplied visited sets.<br/></returns>
    private long CountOrdinaryFixedScalarRouteTargetUncached(
        long targetOffset,
        ushort maxItemCount,
        int slotRegionOffset,
        uint shelfMagic,
        string shapeName,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return CountOrdinaryFixedScalarIdentitiesFromRouter(targetOffset, maxItemCount, slotRegionOffset, shelfMagic, shapeName, visitedTargets, visitedRouters);
        }

        if (magic != shelfMagic)
        {
            throw new InvalidDataException($"{shapeName} count target at offset {targetOffset} does not contain a recognized LibraDex structure.");
        }

        if (!visitedTargets.Add(targetOffset))
        {
            return 0;
        }

        return ReadOrdinaryFixedScalarShelfLiveCountNarrow(targetOffset, maxItemCount, slotRegionOffset, shelfMagic, shapeName);
    }

    /// <summary>
    /// Tries to apply a cached ordinary fixed-scalar route-target aggregate to the current traversal visited sets.<br/>
    /// Cached aggregates include every target/router offset counted while deriving the value, so replay remains safe when compressed route entries share physical targets.<br/>
    /// </summary>
    /// <param name="key">The physical route-target/profile cache key.<br/></param>
    /// <param name="visitedTargets">The current traversal's counted target offsets.<br/></param>
    /// <param name="visitedRouters">The current traversal's walked router offsets.<br/></param>
    /// <param name="count">Receives the cached aggregate count when it can be applied without overlap.<br/></param>
    /// <returns><see langword="true"/> when the cached aggregate was current and non-overlapping; otherwise <see langword="false"/>.<br/></returns>
    private bool TryApplyOrdinaryFixedScalarRouteTargetCountCache(
        OrdinaryFixedScalarRouteTargetCountCacheKey key,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        out long count)
    {
        long mutationVersion = kernel.MutationVersion;
        OrdinaryFixedScalarRouteTargetCountCacheValue value;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (!ordinaryFixedScalarRouteTargetCountCache.TryGetValue(key, out value) ||
                kernel.MutationVersion != mutationVersion)
            {
                count = 0;
                return false;
            }
        }

        if (!TryApplyOrdinaryFixedScalarRouteTargetVisitedOffsets(
            value.TargetOffsets,
            value.RouterOffsets,
            visitedTargets,
            visitedRouters))
        {
            count = 0;
            return false;
        }

        count = value.Count;
        return true;
    }

    /// <summary>
    /// Stores one ordinary fixed-scalar route-target aggregate at the current raw-storage mutation version.<br/>
    /// The value is derived from existing router topology and shelf count headers, making it a free session-local projection rather than persisted count maintenance.<br/>
    /// </summary>
    /// <param name="key">The physical route-target/profile cache key.<br/></param>
    /// <param name="count">The independent aggregate count for the route target.<br/></param>
    /// <param name="visitedTargets">The target offsets counted while deriving the aggregate.<br/></param>
    /// <param name="visitedRouters">The router offsets walked while deriving the aggregate.<br/></param>
    private void StoreOrdinaryFixedScalarRouteTargetCountCache(
        OrdinaryFixedScalarRouteTargetCountCacheKey key,
        long count,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        long mutationVersion = kernel.MutationVersion;
        OrdinaryFixedScalarRouteTargetCountCacheValue value = new(count, [.. visitedTargets], [.. visitedRouters]);
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            ordinaryFixedScalarRouteTargetCountCache[key] = value;
        }
    }

    /// <summary>
    /// Applies visited offsets from a freshly-derived ordinary fixed-scalar route-target aggregate to an outer traversal.<br/>
    /// The method checks all offsets before mutating the outer visited sets so overlapping shared routes fall back to the uncached walker.<br/>
    /// </summary>
    /// <param name="targetVisitedTargets">The target offsets counted by the independent aggregate.<br/></param>
    /// <param name="targetVisitedRouters">The router offsets walked by the independent aggregate.<br/></param>
    /// <param name="visitedTargets">The outer traversal's target offsets.<br/></param>
    /// <param name="visitedRouters">The outer traversal's router offsets.<br/></param>
    /// <returns><see langword="true"/> when the offsets were non-overlapping and applied; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryApplyOrdinaryFixedScalarRouteTargetVisitedOffsets(
        HashSet<long> targetVisitedTargets,
        HashSet<long> targetVisitedRouters,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        foreach (long targetOffset in targetVisitedTargets)
        {
            if (visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
            {
                return false;
            }
        }

        foreach (long routerOffset in targetVisitedRouters)
        {
            if (visitedTargets.Contains(routerOffset) || visitedRouters.Contains(routerOffset))
            {
                return false;
            }
        }

        foreach (long targetOffset in targetVisitedTargets)
        {
            visitedTargets.Add(targetOffset);
        }

        foreach (long routerOffset in targetVisitedRouters)
        {
            visitedRouters.Add(routerOffset);
        }

        return true;
    }

    /// <summary>
    /// Applies visited offsets from a cached ordinary fixed-scalar route-target aggregate to an outer traversal.<br/>
    /// Cached offsets are replayed only when none were already visited, which keeps compressed/shared route topology from double-counting cached subtrees.<br/>
    /// </summary>
    /// <param name="targetVisitedTargets">The target offsets counted by the cached aggregate.<br/></param>
    /// <param name="targetVisitedRouters">The router offsets walked by the cached aggregate.<br/></param>
    /// <param name="visitedTargets">The outer traversal's target offsets.<br/></param>
    /// <param name="visitedRouters">The outer traversal's router offsets.<br/></param>
    /// <returns><see langword="true"/> when the offsets were non-overlapping and applied; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryApplyOrdinaryFixedScalarRouteTargetVisitedOffsets(
        long[] targetVisitedTargets,
        long[] targetVisitedRouters,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        for (int i = 0; i < targetVisitedTargets.Length; i++)
        {
            long targetOffset = targetVisitedTargets[i];
            if (visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
            {
                return false;
            }
        }

        for (int i = 0; i < targetVisitedRouters.Length; i++)
        {
            long routerOffset = targetVisitedRouters[i];
            if (visitedTargets.Contains(routerOffset) || visitedRouters.Contains(routerOffset))
            {
                return false;
            }
        }

        for (int i = 0; i < targetVisitedTargets.Length; i++)
        {
            visitedTargets.Add(targetVisitedTargets[i]);
        }

        for (int i = 0; i < targetVisitedRouters.Length; i++)
        {
            visitedRouters.Add(targetVisitedRouters[i]);
        }

        return true;
    }

    /// <summary>
    /// Tries to read a cached narrow count projection for one ordinary fixed-scalar shelf.<br/>
    /// The projection is scoped by shelf offset, expected magic, maximum count, and DataKernel mutation version so shape-specific count paths do not share stale or mismatched metadata.<br/>
    /// </summary>
    /// <param name="key">The physical fixed-scalar shelf cache key.<br/></param>
    /// <param name="count">Receives the cached live item count.<br/></param>
    /// <returns><see langword="true"/> when a current-version cache entry was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetOrdinaryFixedScalarShelfCountCache(OrdinaryFixedScalarShelfCountCacheKey key, out long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (ordinaryFixedScalarShelfCountCache.TryGetValue(key, out count) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        count = 0;
        return false;
    }

    /// <summary>
    /// Stores the narrow count projection for one ordinary fixed-scalar shelf at the current raw-storage mutation version.<br/>
    /// This cache records a value that was already present in the shelf header and is invalidated by volatile storage versioning rather than by any extra page write.<br/>
    /// </summary>
    /// <param name="key">The physical fixed-scalar shelf cache key.<br/></param>
    /// <param name="count">The live item count read from the normalized shelf header.<br/></param>
    private void StoreOrdinaryFixedScalarShelfCountCache(OrdinaryFixedScalarShelfCountCacheKey key, long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            ordinaryFixedScalarShelfCountCache[key] = count;
        }
    }

    /// <summary>
    /// Clears all narrow count-header caches when the DataKernel mutation version changes.<br/>
    /// Callers already hold <see cref="countHeaderCacheSync"/>; centralizing the reset keeps all shape-specific count projections on the same raw-storage visibility boundary.<br/>
    /// </summary>
    /// <param name="mutationVersion">The raw-storage mutation version observed by the caller.<br/></param>
    private void EnsureCountHeaderCacheVersionUnderLock(long mutationVersion)
    {
        if (countHeaderCacheMutationVersion == mutationVersion)
        {
            return;
        }

        scalar8Scalar8ShelfCountCache.Clear();
        terminalIdentity8ShelfCountCache.Clear();
        ordinaryFixedScalarShelfCountCache.Clear();
        scalar8VarIdentityShelfCountCache.Clear();
        scalar16VarIdentityShelfCountCache.Clear();
        fixedNVarIdentityShelfCountCache.Clear();
        varKeyScalar8ShelfCountCache.Clear();
        varKeyScalar16ShelfCountCache.Clear();
        varKeyVarIdentityShelfCountCache.Clear();
        scalar8Scalar8RouteTargetKindCountCache.Clear();
        scalar8Scalar8RouteTargetCountCache.Clear();
        ordinaryFixedScalarRouteTargetCountCache.Clear();
        countHeaderCacheMutationVersion = mutationVersion;
    }

    /// <summary>
    /// Reads only the fixed-scalar shelf header bytes needed to derive a live count.<br/>
    /// Published fixed-scalar shelves are normalized before rewrite, so the shared item-count header is already the live count for count-only traversal.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf file offset.<br/></param>
    /// <param name="maxItemCount">The maximum ordinary shelf item count for the selected shape profile.<br/></param>
    /// <param name="slotRegionOffset">The byte offset of the shelf slot table for the selected shape profile.<br/></param>
    /// <param name="shelfMagic">The expected shelf magic value for the selected fixed-scalar shape.<br/></param>
    /// <param name="shapeName">The short shape name used in validation errors.<br/></param>
    /// <returns>The live identity count represented by the shelf.<br/></returns>
    private long ReadOrdinaryFixedScalarShelfLiveCountNarrow(long shelfOffset, ushort maxItemCount, int slotRegionOffset, uint shelfMagic, string shapeName)
    {
        OrdinaryFixedScalarShelfCountCacheKey cacheKey = new(shelfOffset, maxItemCount, shelfMagic);
        if (TryGetOrdinaryFixedScalarShelfCountCache(cacheKey, out long cachedCount))
        {
            return cachedCount;
        }

        Span<byte> header = stackalloc byte[Scalar8Scalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (BinaryPrimitives.ReadUInt32LittleEndian(header.Slice(Scalar8Scalar8Layout.MagicOffset, sizeof(uint))) != shelfMagic ||
            BinaryPrimitives.ReadUInt16LittleEndian(header.Slice(Scalar8Scalar8Layout.FormatVersionOffset, sizeof(ushort))) != Scalar8Scalar8Layout.FormatVersion ||
            BinaryPrimitives.ReadUInt16LittleEndian(header.Slice(Scalar8Scalar8Layout.HeaderSizeOffset, sizeof(ushort))) != Scalar8Scalar8Layout.HeaderSize)
        {
            throw new InvalidDataException($"The routed {shapeName} count shelf header is invalid.");
        }

        ushort itemCount = BinaryPrimitives.ReadUInt16LittleEndian(header.Slice(Scalar8Scalar8Layout.ItemCountOffset, sizeof(ushort)));
        if (itemCount > maxItemCount)
        {
            throw new InvalidDataException($"The routed {shapeName} count exceeds the profiled shelf capacity.");
        }

        StoreOrdinaryFixedScalarShelfCountCache(cacheKey, itemCount);
        return itemCount;
    }

    /// <summary>
    /// Counts every ordinary `VS8` identity reachable from the routed root by summing shelf-local count metadata.<br/>
    /// The traversal intentionally ignores ordered range-reader progression because count-all only needs to reach each physical leaf once.<br/>
    /// Terminal duplicate-key identity roots are counted from their identity shelf headers without reading identity payloads.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS8` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <returns>The summed ordinary routed identity count.<br/></returns>
    internal long CountVarKeyScalar8Identities(long rootRouterOffset, int maxKeyLength)
    {
        HashSet<long> visitedTargets = new();
        HashSet<long> visitedRouters = new();
        return CountVarKeyScalar8IdentitiesFromRouter(rootRouterOffset, maxKeyLength, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts `VS8` identities in an inclusive encoded-key range without forcing a full ordered reader pass when root-prefix targets are wholly covered.<br/>
    /// Boundary prefixes keep the existing range-reader count path for exact slot-bound correctness; fully covered direct root prefixes use the count-all target walker so broad range counts avoid loading every shelf payload.<br/>
    /// Compressed or shared root targets fall back to the reader count rather than risking over-counting keys outside the requested range.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS8` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower key.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper key.<br/></param>
    /// <returns>The number of matching identities.<br/></returns>
    internal long CountVarKeyScalar8IdentityRange(long rootRouterOffset, int maxKeyLength, ReadOnlySpan<byte> lowerKey, ReadOnlySpan<byte> upperKey)
    {
        return CountVarKeyScalar8IdentityRangeByShelfScoop(rootRouterOffset, maxKeyLength, lowerKey, upperKey);
    }

    /// <summary>
    /// Counts `VS8` identities whose encoded key starts with <paramref name="encodedPrefix"/> using a shape-specific prefix extent walk.<br/>
    /// Contained router targets are counted from existing shelf and terminal-root metadata; partial or ambiguous targets are counted through the established encoded range counter.<br/>
    /// The method carries prefix semantics explicitly so prefix criteria do not have to be inferred back from generic lower/upper bounds.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS8` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="encodedPrefix">The encoded key prefix to match.<br/></param>
    /// <returns>The number of matching identities.<br/></returns>
    internal long CountVarKeyScalar8IdentityPrefix(long rootRouterOffset, int maxKeyLength, ReadOnlySpan<byte> encodedPrefix)
    {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        return CountVarKeyScalar8IdentityPrefix(rootRouterOffset, maxKeyLength, encodedPrefix, out _);
#else
        if (encodedPrefix.Length == 0)
        {
            return CountVarKeyScalar8Identities(rootRouterOffset, maxKeyLength);
        }

        byte[] lowerKey = encodedPrefix.ToArray();
        byte[] upperKey = CreateVarKeyPrefixUpperBound(encodedPrefix, maxKeyLength);
        HashSet<long> visitedTargets = new();
        HashSet<long> visitedRouters = new();
        if (TryCountVarKeyScalar8IdentityPrefixFromRouter(
            rootRouterOffset,
            maxKeyLength,
            lowerKey,
            upperKey,
            encodedPrefix,
            visitedTargets,
            visitedRouters,
            DefaultVarKeyScalar8MaxRouterHops,
            out long count))
        {
            return count;
        }

        return CountVarKeyScalar8IdentityRange(rootRouterOffset, maxKeyLength, lowerKey, upperKey);
#endif
    }

#if LIBRADEX_PREFIX_COUNT_TELEMETRY
    /// <summary>
    /// Counts `VS8` identities whose encoded key starts with <paramref name="encodedPrefix"/> using a shape-specific prefix extent walk.<br/>
    /// The returned diagnostics describe whether the count stayed on the prefix planner or failed closed to the exact encoded range counter.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS8` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="encodedPrefix">The encoded key prefix to match.<br/></param>
    /// <param name="telemetry">Receives prefix-count planner diagnostics for the completed count.<br/></param>
    /// <returns>The number of matching identities.<br/></returns>
    internal long CountVarKeyScalar8IdentityPrefix(long rootRouterOffset, int maxKeyLength, ReadOnlySpan<byte> encodedPrefix, out VarKeyScalar8PrefixCountTelemetry telemetry)
    {
        VarKeyScalar8PrefixCountTelemetryBuilder telemetryBuilder = default;
        if (encodedPrefix.Length == 0)
        {
            telemetry = telemetryBuilder.ToTelemetry();
            return CountVarKeyScalar8Identities(rootRouterOffset, maxKeyLength);
        }

        byte[] lowerKey = encodedPrefix.ToArray();
        byte[] upperKey = CreateVarKeyPrefixUpperBound(encodedPrefix, maxKeyLength);
        HashSet<long> visitedTargets = new();
        HashSet<long> visitedRouters = new();
        if (TryCountVarKeyScalar8IdentityPrefixFromRouter(
            rootRouterOffset,
            maxKeyLength,
            lowerKey,
            upperKey,
            encodedPrefix,
            visitedTargets,
            visitedRouters,
            ref telemetryBuilder,
            DefaultVarKeyScalar8MaxRouterHops,
            out long count))
        {
            telemetry = telemetryBuilder.ToTelemetry();
            return count;
        }

        telemetryBuilder.FallbackToRangeCount++;
        long fallbackCount = CountVarKeyScalar8IdentityRange(rootRouterOffset, maxKeyLength, lowerKey, upperKey);
        telemetry = telemetryBuilder.ToTelemetry();
        return fallbackCount;
    }
#endif

    /// <summary>
    /// Counts a routed `VS8` router subtree for one encoded prefix criterion.<br/>
    /// The walker only descends through routes that can contain the prefix and switches to count-all once the route path proves the prefix is fully contained.<br/>
    /// Ambiguous compressed routes return <see langword="false"/> so the public count can fall back to exact range counting instead of over-counting.<br/>
    /// </summary>
    /// <param name="routerOffset">The router offset to evaluate.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the prefix walk succeeds.<br/></param>
    /// <returns><see langword="true"/> when the prefix extent was counted without needing the generic range reader; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar8IdentityPrefixFromRouter(
        long routerOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        ref VarKeyScalar8PrefixCountTelemetryBuilder telemetry,
#endif
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (routerOffset == 0)
        {
            return true;
        }

        if (!visitedRouters.Add(routerOffset))
        {
            return true;
        }

        if (remainingRouterHops <= 0)
        {
            return false;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS8 prefix-count router is invalid.");
        }

#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        telemetry.RoutersVisited++;
#endif
        if (router.KeyDepth >= encodedPrefix.Length)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            count = CountContainedVarKeyScalar8RouterTargets(router, maxKeyLength, visitedTargets, visitedRouters, ref telemetry);
#else
            count = CountContainedVarKeyScalar8RouterTargets(router, maxKeyLength, visitedTargets, visitedRouters);
#endif
            return true;
        }

        if (router.PrefixByteCount == 1)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.OneByteRoutersVisited++;
#endif
            byte prefixByte = GetVarKeyScalar8Prefix(encodedPrefix, router.KeyDepth);
            long targetOffset = router.FindTarget(prefixByte);
            return TryCountVarKeyScalar8IdentityPrefixFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                routeProvesContainment: router.KeyDepth + 1 >= encodedPrefix.Length,
                visitedTargets,
                visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
                ref telemetry,
#endif
                remainingRouterHops - 1,
                out count);
        }

#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        telemetry.MultiByteRoutersVisited++;
#endif
        return TryCountVarKeyScalar8IdentityPrefixFromMultiByteRouter(
            router,
            routerBytes,
            maxKeyLength,
            lowerKey,
            upperKey,
            encodedPrefix,
            visitedTargets,
            visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            ref telemetry,
#endif
            remainingRouterHops,
            out count);
    }

    /// <summary>
    /// Counts matching targets under one compressed multi-byte `VS8` router for an encoded prefix criterion.<br/>
    /// Routes whose stored stem proves the requested prefix are counted wholesale; routes with a widened final-byte range continue as partial targets when the requested byte is inside that range.<br/>
    /// This keeps compressed-router prefix counting correct while still allowing deeper routers to prove containment and boundary shelves to use exact narrow counting.<br/>
    /// </summary>
    /// <param name="router">The decoded router view.<br/></param>
    /// <param name="routerBytes">The router page bytes that own compressed route stems.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the compressed-router walk succeeds.<br/></param>
    /// <returns><see langword="true"/> when the compressed router was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar8IdentityPrefixFromMultiByteRouter(
        RouterReader router,
        ReadOnlySpan<byte> routerBytes,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        ref VarKeyScalar8PrefixCountTelemetryBuilder telemetry,
#endif
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        int keyDepth = router.KeyDepth;
        int prefixByteCount = router.PrefixByteCount;
        int stemLength = prefixByteCount - 1;
        int finalDepth = keyDepth + stemLength;
        int routeEndDepth = keyDepth + prefixByteCount;
        int routeCount = router.RouteCount;
        int maxRouteCount = router.MaxRouteCount;

        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.MultiByteRoutesVisited++;
#endif
            ReadOnlySpan<byte> stem = routerBytes.Slice(RouterLayout.GetMultiByteRouteStemOffset(maxRouteCount, prefixByteCount, routeIndex), stemLength);
            if (!VarKeyPrefixMatchesRouteStem(encodedPrefix, keyDepth, stem))
            {
                continue;
            }

#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.MultiByteRoutesStemMatched++;
#endif
            long targetOffset = router.GetRouteTargetAt(routeIndex);
            if (targetOffset == 0)
            {
                continue;
            }

            bool contained;
            if (encodedPrefix.Length <= finalDepth)
            {
                contained = true;
            }
            else
            {
                byte finalPrefixByte = GetVarKeyScalar8Prefix(encodedPrefix, finalDepth);
                byte routeStart = router.GetRoutePrefixStartAt(routeIndex);
                byte routeEnd = router.GetRoutePrefixEndAt(routeIndex);
                if (finalPrefixByte < routeStart || finalPrefixByte > routeEnd)
                {
                    continue;
                }

                if (routeStart != routeEnd)
                {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
                    telemetry.MultiByteRoutesAmbiguous++;
#endif
                    contained = false;
                }
                else
                {
                    contained = encodedPrefix.Length <= routeEndDepth;
                }
            }

            if (contained)
            {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
                telemetry.MultiByteRoutesContained++;
#endif
            }

            if (!TryCountVarKeyScalar8IdentityPrefixFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                contained,
                visitedTargets,
                visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
                ref telemetry,
#endif
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    /// <summary>
    /// Counts one routed `VS8` target for an encoded prefix criterion.<br/>
    /// Proven-contained targets use ordinary count-all metadata traversal; partial shelf and terminal targets use exact encoded range checks.<br/>
    /// Router targets continue the shape-specific prefix walk so deeper routes can become contained without materializing tuples.<br/>
    /// </summary>
    /// <param name="targetOffset">The target offset to count.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="routeProvesContainment">True when the route path already proves every key below this target starts with <paramref name="encodedPrefix"/>.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the target was counted safely.<br/></param>
    /// <returns><see langword="true"/> when the target was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar8IdentityPrefixFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        bool routeProvesContainment,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        ref VarKeyScalar8PrefixCountTelemetryBuilder telemetry,
#endif
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (targetOffset == 0)
        {
            return true;
        }

#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        telemetry.TargetsVisited++;
#endif
        if (routeProvesContainment)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.TargetsCountedByMetadata++;
#endif
            count = CountVarKeyScalar8RouteTarget(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
            return true;
        }

        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Router)
        {
            return TryCountVarKeyScalar8IdentityPrefixFromRouter(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                visitedTargets,
                visitedRouters,
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
                ref telemetry,
#endif
                remainingRouterHops,
                out count);
        }

        if (kind == VarKeyScalar8RouteTargetKind.Shelf)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.ShelfTargetsCountedNarrow++;
#endif
            count = CountVarKeyScalar8ShelfChainKeyRangeNarrow(targetOffset, maxKeyLength, lowerKey, upperKey, visitedTargets);
            return true;
        }

        if (kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
            telemetry.TerminalRootsCountedNarrow++;
#endif
            count = CountVarKeyScalar8TerminalIdentityRootKeyRangeNarrow(targetOffset, lowerKey, upperKey);
            return true;
        }

        throw new InvalidDataException("The routed VS8 prefix-count target is not a shelf, terminal root, or router.");
    }

    /// <summary>
    /// Counts every target directly referenced by an already visited contained `VS8` router.<br/>
    /// This avoids re-entering the router's own visited check while preserving count-all metadata traversal for each child target.<br/>
    /// The helper is used only after the prefix planner has proven the current router's whole subtree is inside the requested prefix.<br/>
    /// </summary>
    /// <param name="router">The contained router view whose route targets should be counted.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <returns>The number of identities in the router's child targets.<br/></returns>
    private long CountContainedVarKeyScalar8RouterTargets(
        RouterReader router,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        ,
        ref VarKeyScalar8PrefixCountTelemetryBuilder telemetry)
#else
        )
#endif
    {
#if LIBRADEX_PREFIX_COUNT_TELEMETRY
        telemetry.ContainedRouterTargetScans++;
#endif
        long count = 0;
        int routeCount = router.HasDirectIndex ? RouterLayout.MaxOneByteRouteCount : router.RouteCount;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            count += CountVarKeyScalar8RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
        }

        return count;
    }

    /// <summary>
    /// Creates the inclusive high encoded-key bound for a prefix criterion by padding the remaining key space with `0xFF` bytes.<br/>
    /// The lower bound is the prefix itself; the padded high bound preserves exact-prefix keys and all longer keys sharing that prefix under LibraDex's byte ordering.<br/>
    /// </summary>
    /// <param name="encodedPrefix">The encoded key prefix being matched.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <returns>The inclusive high key bound for the prefix.<br/></returns>
    private static byte[] CreateVarKeyPrefixUpperBound(ReadOnlySpan<byte> encodedPrefix, int maxKeyLength)
    {
        int length = Math.Max(encodedPrefix.Length, maxKeyLength);
        byte[] upper = new byte[length];
        encodedPrefix.CopyTo(upper);
        upper.AsSpan(encodedPrefix.Length).Fill(0xFF);
        return upper;
    }

    /// <summary>
    /// Tests whether a compressed route stem is compatible with an encoded prefix at the router's key depth.<br/>
    /// If the prefix ends inside the stem, the route is contained only when the stem starts with the remaining prefix bytes.<br/>
    /// If the prefix extends past the stem, every stem byte must match before the caller evaluates the final route byte.<br/>
    /// </summary>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="keyDepth">The router key depth where the stem begins.<br/></param>
    /// <param name="stem">The persisted compressed route stem bytes.<br/></param>
    /// <returns><see langword="true"/> when the stem can contain keys matching the prefix; otherwise <see langword="false"/>.<br/></returns>
    private static bool VarKeyPrefixMatchesRouteStem(ReadOnlySpan<byte> encodedPrefix, int keyDepth, ReadOnlySpan<byte> stem)
    {
        int remaining = encodedPrefix.Length - keyDepth;
        int bytesToCompare = Math.Min(stem.Length, Math.Max(0, remaining));
        for (int i = 0; i < bytesToCompare; i++)
        {
            if (stem[i] != GetVarKeyScalar8Prefix(encodedPrefix, keyDepth + i))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryCountVarKeyScalar8IdentityRangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        byte[] pathPrefix,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (targetOffset == 0)
        {
            return true;
        }

        if (!lowerEdge && !upperEdge)
        {
            count = CountVarKeyScalar8RouteTarget(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
            return true;
        }

        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Shelf)
        {
            count = CountVarKeyScalar8ShelfChainKeyRangeNarrow(targetOffset, maxKeyLength, lowerKey, upperKey, visitedTargets);
            return true;
        }

        if (kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            count = CountVarKeyScalar8TerminalIdentityRootKeyRangeNarrow(targetOffset, lowerKey, upperKey);
            return true;
        }

        if (kind != VarKeyScalar8RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS8 range-count target is not a shelf, terminal identity root, or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return true;
        }

        if (remainingRouterHops <= 0)
        {
            return false;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS8 range-count router is invalid.");
        }

        if (router.PrefixByteCount > 1)
        {
            return TryCountVarKeyScalar8IdentityRangeFromMultiByteRouter(
                router,
                routerBytes,
                maxKeyLength,
                lowerKey,
                upperKey,
                pathPrefix,
                lowerEdge,
                upperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops,
                out count);
        }

        byte lowerPrefix = lowerEdge ? GetVarKeyScalar8Prefix(lowerKey, router.KeyDepth) : byte.MinValue;
        byte upperPrefix = upperEdge ? GetVarKeyScalar8Prefix(upperKey, router.KeyDepth) : byte.MaxValue;
        long lowerTarget = lowerEdge ? router.FindTarget(lowerPrefix) : 0;
        long upperTarget = upperEdge ? router.FindTarget(upperPrefix) : 0;
        if (lowerEdge && upperEdge && lowerPrefix != upperPrefix && lowerTarget != 0 && lowerTarget == upperTarget)
        {
            return false;
        }

        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTarget = router.FindTarget((byte)prefix);
            if (childTarget == 0)
            {
                continue;
            }

            bool childLowerEdge = lowerEdge && prefix == lowerPrefix;
            bool childUpperEdge = upperEdge && prefix == upperPrefix;
            if (!childLowerEdge && !childUpperEdge && (childTarget == lowerTarget || childTarget == upperTarget))
            {
                return false;
            }

            if (!TryCountVarKeyScalar8IdentityRangeFromTarget(
                childTarget,
                maxKeyLength,
                lowerKey,
                upperKey,
                CreateVarKeyRoutePathPrefix(pathPrefix, router.KeyDepth, (byte)prefix),
                childLowerEdge,
                childUpperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    /// <summary>
    /// Counts a compressed multi-byte `VS8` router for an inclusive encoded-key range.<br/>
    /// Each compressed route is classified as disjoint, fully contained, or boundary-overlapping using the route stem and final-byte interval; contained routes use metadata counts while boundary routes continue the exact range walk.<br/>
    /// </summary>
    /// <param name="router">The decoded compressed router.<br/></param>
    /// <param name="routerBytes">The router page bytes that own the route stems.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower key.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper key.<br/></param>
    /// <param name="pathPrefix">The key bytes proven by parent route traversal.<br/></param>
    /// <param name="lowerEdge">True when this router may contain the lower range boundary.<br/></param>
    /// <param name="upperEdge">True when this router may contain the upper range boundary.<br/></param>
    /// <param name="visitedTargets">Route targets already counted by this range walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted by this range walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the router was counted safely.<br/></param>
    /// <returns><see langword="true"/> when the compressed router was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar8IdentityRangeFromMultiByteRouter(
        RouterReader router,
        ReadOnlySpan<byte> routerBytes,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> pathPrefix,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        int keyDepth = router.KeyDepth;
        int prefixByteCount = router.PrefixByteCount;
        int stemLength = prefixByteCount - 1;
        int routeCount = router.RouteCount;
        int maxRouteCount = router.MaxRouteCount;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            ReadOnlySpan<byte> stem = routerBytes.Slice(RouterLayout.GetMultiByteRouteStemOffset(maxRouteCount, prefixByteCount, routeIndex), stemLength);
            byte routeStart = router.GetRoutePrefixStartAt(routeIndex);
            byte routeEnd = router.GetRoutePrefixEndAt(routeIndex);
            if (!TryClassifyVarKeyMultiByteRangeRoute(pathPrefix, keyDepth, stem, routeStart, routeEnd, lowerKey, upperKey, maxKeyLength, lowerEdge, upperEdge, out bool childLowerEdge, out bool childUpperEdge))
            {
                continue;
            }

            long childTarget = router.GetRouteTargetAt(routeIndex);
            if (childTarget == 0)
            {
                continue;
            }

            if (!TryCountVarKeyScalar8IdentityRangeFromTarget(
                childTarget,
                maxKeyLength,
                lowerKey,
                upperKey,
                CreateVarKeyMultiByteRoutePathPrefix(pathPrefix, keyDepth, stem, routeStart),
                childLowerEdge,
                childUpperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    private long CountVarKeyScalar8ShelfChainKeyRangeNarrow(
        long shelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        HashSet<long> visitedTargets)
    {
        long count = 0;
        long currentOffset = shelfOffset;
        while (currentOffset != 0)
        {
            if (!visitedTargets.Add(currentOffset))
            {
                break;
            }

            count += CountVarKeyScalar8ShelfKeyRangeNarrow(currentOffset, maxKeyLength, lowerKey, upperKey, out long nextOffset);
            currentOffset = nextOffset;
        }

        return count;
    }

    private long CountVarKeyScalar8ShelfKeyRangeNarrow(long shelfOffset, int maxKeyLength, ReadOnlySpan<byte> lowerKey, ReadOnlySpan<byte> upperKey, out long nextOffset)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            nextOffset = VarKeyScalar8Layout.HasDuplicateRunFlag(mutableShelf.Bytes)
                ? VarKeyScalar8Layout.ReadDuplicateRunNextOffset(mutableShelf.Bytes)
                : 0;
            return mutableShelf.CountLiveItemsInKeyRange(lowerKey, upperKey);
        }

        byte[] shelfBytes = ReadVarKeyScalar8ShelfBytes(shelfOffset, maxKeyLength, out VarKeyScalar8Profile profile);
        VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed VS8 range-count shelf is invalid.");
        }

        nextOffset = shelf.IsDuplicateRun ? shelf.DuplicateRunNextOffset : 0;
        return shelf.CountItemsInKeyRange(lowerKey, upperKey);
    }

    private long CountVarKeyScalar8TerminalIdentityRootKeyRangeNarrow(long rootOffset, ReadOnlySpan<byte> lowerKey, ReadOnlySpan<byte> upperKey)
    {
        Span<byte> rootHeader = stackalloc byte[TerminalIdentityRootLayout.HeaderSize];
        kernel.Read(rootOffset, rootHeader);
        if (TerminalIdentityRootLayout.ReadMagic(rootHeader) != TerminalIdentityRootLayout.Magic ||
            TerminalIdentityRootLayout.ReadFormatVersion(rootHeader) != TerminalIdentityRootLayout.FormatVersion ||
            TerminalIdentityRootLayout.ReadHeaderSize(rootHeader) != TerminalIdentityRootLayout.HeaderSize ||
            TerminalIdentityRootLayout.ReadShape(rootHeader) != TerminalIdentityRootLayout.ShapeVarKey)
        {
            throw new InvalidDataException("The routed VS8 range-count terminal root header is invalid.");
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootHeader);
        byte[] rootBytes = new byte[TerminalIdentityRootLayout.Size];
        kernel.Read(rootOffset, rootBytes);
        ReadOnlySpan<byte> key = rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, keyLength);
        return key.SequenceCompareTo(lowerKey) >= 0 && key.SequenceCompareTo(upperKey) <= 0
            ? CountTerminalIdentity8RootNarrow(rootOffset)
            : 0;
    }

    private long CountVarKeyScalar8IdentitiesFromRouter(
        long routerOffset,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS8 count router is invalid.");
        }

        long count = 0;
        if (router.HasDirectIndex)
        {
            for (int routeIndex = 0; routeIndex <= byte.MaxValue; routeIndex++)
            {
                count += CountVarKeyScalar8RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
            }

            return count;
        }

        for (int routeIndex = 0; routeIndex < router.RouteCount; routeIndex++)
        {
            count += CountVarKeyScalar8RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
        }

        return count;
    }

    private long CountVarKeyScalar8RouteTarget(
        long targetOffset,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (targetOffset == 0 || visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
        {
            return 0;
        }

        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Router)
        {
            return CountVarKeyScalar8IdentitiesFromRouter(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
        }

        if (!visitedTargets.Add(targetOffset))
        {
            return 0;
        }

        return kind switch
        {
            VarKeyScalar8RouteTargetKind.Shelf => CountVarKeyScalar8ShelfChainNarrow(targetOffset, maxKeyLength, visitedTargets),
            VarKeyScalar8RouteTargetKind.TerminalIdentityRoot => CountTerminalIdentity8RootNarrow(targetOffset),
            _ => throw new InvalidDataException("The routed VS8 count target is not a shelf, terminal root, or router.")
        };
    }

    private long CountVarKeyScalar8ShelfChainNarrow(long shelfOffset, int maxKeyLength, HashSet<long> visitedTargets)
    {
        long count = 0;
        long currentOffset = shelfOffset;
        while (currentOffset != 0)
        {
            count += ReadVarKeyScalar8ShelfItemCountNarrow(currentOffset, maxKeyLength, out long nextOffset);
            currentOffset = nextOffset;
            if (currentOffset != 0 && !visitedTargets.Add(currentOffset))
            {
                break;
            }
        }

        return count;
    }

    private long ReadVarKeyScalar8ShelfItemCountNarrow(long shelfOffset, int maxKeyLength, out long nextOffset)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            nextOffset = VarKeyScalar8Layout.HasDuplicateRunFlag(mutableShelf.Bytes)
                ? VarKeyScalar8Layout.ReadDuplicateRunNextOffset(mutableShelf.Bytes)
                : 0;
            return mutableShelf.LiveItemCount;
        }

        VarKeyScalar8ShelfCountCacheKey cacheKey = new(shelfOffset, maxKeyLength);
        if (TryGetVarKeyScalar8ShelfCountCache(cacheKey, out VarKeyScalar8ShelfCountCacheValue cachedValue))
        {
            nextOffset = cachedValue.NextShelfOffset;
            return cachedValue.Count;
        }

        Span<byte> header = stackalloc byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS8 count shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
        VarKeyScalar8Profile profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        int count = VarKeyScalar8Layout.ReadItemCount(header);
        if (count < 0)
        {
            throw new InvalidDataException("The routed VS8 count exceeds the profiled shelf capacity.");
        }

        if (VarKeyScalar8Layout.HasDuplicateRunFlag(header))
        {
            int keyLength = VarKeyScalar8Layout.ReadDuplicateRunKeyLength(header);
            if (keyLength <= 0 ||
                keyLength > profile.MaxKeyLength ||
                count > VarKeyScalar8Layout.GetDuplicateRunCapacity(profile, keyLength))
            {
                throw new InvalidDataException("The routed VS8 duplicate-run count metadata is invalid.");
            }

            nextOffset = VarKeyScalar8Layout.ReadDuplicateRunNextOffset(header);
            StoreVarKeyScalar8ShelfCountCache(cacheKey, count, nextOffset);
            return count;
        }

        int slotStreamLength = VarKeyScalar8Layout.ReadSlotStreamLength(header);
        int slotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(header);
        int recordArenaEnd = VarKeyScalar8Layout.ReadRecordArenaEnd(header);
        int expectedSlotCapacityBytes = VarKeyScalar8Layout.CalculateSlotCapacityBytes(shelfExtentSize);
        if (count > expectedSlotCapacityBytes / VarKeyScalar8Layout.SlotSize ||
            slotStreamLength != checked(count * VarKeyScalar8Layout.SlotSize) ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            recordArenaEnd < VarKeyScalar8Layout.HeaderSize + slotCapacityBytes ||
            recordArenaEnd > shelfExtentSize)
        {
            throw new InvalidDataException("The routed VS8 count shelf metadata is invalid.");
        }

        nextOffset = 0;
        StoreVarKeyScalar8ShelfCountCache(cacheKey, count, nextOffset);
        return count;
    }

    /// <summary>
    /// Tries to read a session-local narrow count projection for one `VS8` shelf.<br/>
    /// The cached value includes the duplicate-run next-shelf offset because count-all traversal needs both fields after the first validated header read.<br/>
    /// Entries are invalidated by the shared DataKernel mutation-version boundary, so this remains a free in-memory reuse path and never maintains persisted metadata.<br/>
    /// </summary>
    /// <param name="key">The physical `VS8` shelf count cache key.<br/></param>
    /// <param name="value">Receives the cached count and next offset when a current entry is available.<br/></param>
    /// <returns><see langword="true"/> when a current count projection was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetVarKeyScalar8ShelfCountCache(VarKeyScalar8ShelfCountCacheKey key, out VarKeyScalar8ShelfCountCacheValue value)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (varKeyScalar8ShelfCountCache.TryGetValue(key, out value) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        value = default;
        return false;
    }


    /// <summary>
    /// Stores one validated `VS8` shelf count projection at the current raw-storage mutation version.<br/>
    /// The value is copied from an existing shelf header that the count operation already read, making repeated counts cheaper without adding a page write or flush.<br/>
    /// </summary>
    /// <param name="key">The physical `VS8` shelf count cache key.<br/></param>
    /// <param name="count">The validated live item count read from the shelf header.<br/></param>
    /// <param name="nextOffset">The duplicate-run next-shelf offset, or zero for ordinary shelves.<br/></param>
    private void StoreVarKeyScalar8ShelfCountCache(VarKeyScalar8ShelfCountCacheKey key, long count, long nextOffset)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            varKeyScalar8ShelfCountCache[key] = new VarKeyScalar8ShelfCountCacheValue(count, nextOffset);
        }
    }

    /// <summary>
    /// Counts every ordinary `VS16` identity reachable from the routed root by summing shelf-local count metadata.<br/>
    /// This is the count-all companion to the `VS16` range reader and avoids ordered key-bound traversal when the whole index is requested.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS16` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <returns>The summed ordinary routed identity count.<br/></returns>
    internal long CountVarKeyScalar16Identities(long rootRouterOffset, int maxKeyLength)
    {
        HashSet<long> visitedTargets = new();
        HashSet<long> visitedRouters = new();
        return CountVarKeyScalar16IdentitiesFromRouter(rootRouterOffset, maxKeyLength, visitedTargets, visitedRouters);
    }

    /// <summary>
    /// Counts `VS16` identities in an inclusive encoded-key range using the same hybrid root-prefix strategy as `VS8`.<br/>
    /// Fully covered direct root-prefix targets use narrow metadata traversal, while boundary prefixes and compressed/shared root targets keep the established reader count for correctness.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS16` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower key.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper key.<br/></param>
    /// <returns>The number of matching identities.<br/></returns>
    internal long CountVarKeyScalar16IdentityRange(long rootRouterOffset, int maxKeyLength, ReadOnlySpan<byte> lowerKey, ReadOnlySpan<byte> upperKey)
    {
        return CountVarKeyScalar16IdentityRangeByShelfScoop(rootRouterOffset, maxKeyLength, lowerKey, upperKey);
    }

    /// <summary>
    /// Counts `VS16` identities whose encoded key starts with <paramref name="encodedPrefix"/> using a shape-specific prefix extent walk.<br/>
    /// Contained router targets are counted from existing shelf metadata; partial or ambiguous targets are counted through the established encoded range counter.<br/>
    /// The method mirrors the `VS8` prefix planner so scalar-16 identity projections keep prefix criteria on route-contained metadata whenever possible.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The routed `VS16` root router offset.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="encodedPrefix">The encoded key prefix to match.<br/></param>
    /// <returns>The number of matching identities.<br/></returns>
    internal long CountVarKeyScalar16IdentityPrefix(long rootRouterOffset, int maxKeyLength, ReadOnlySpan<byte> encodedPrefix)
    {
        if (encodedPrefix.Length == 0)
        {
            return CountVarKeyScalar16Identities(rootRouterOffset, maxKeyLength);
        }

        byte[] lowerKey = encodedPrefix.ToArray();
        byte[] upperKey = CreateVarKeyPrefixUpperBound(encodedPrefix, maxKeyLength);
        HashSet<long> visitedTargets = new();
        HashSet<long> visitedRouters = new();
        return TryCountVarKeyScalar16IdentityPrefixFromRouter(
            rootRouterOffset,
            maxKeyLength,
            lowerKey,
            upperKey,
            encodedPrefix,
            visitedTargets,
            visitedRouters,
            DefaultVarKeyScalar16MaxRouterHops,
            out long count)
            ? count
            : CountVarKeyScalar16IdentityRange(rootRouterOffset, maxKeyLength, lowerKey, upperKey);
    }

    /// <summary>
    /// Counts a routed `VS16` router subtree for one encoded prefix criterion.<br/>
    /// The walker follows only routes that can contain the requested prefix and switches to count-all when the route path proves full containment.<br/>
    /// </summary>
    /// <param name="routerOffset">The router offset to evaluate.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the prefix walk succeeds.<br/></param>
    /// <returns><see langword="true"/> when the prefix extent was counted without falling back to the generic range count; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar16IdentityPrefixFromRouter(
        long routerOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (routerOffset == 0)
        {
            return true;
        }

        if (!visitedRouters.Add(routerOffset))
        {
            return true;
        }

        if (remainingRouterHops <= 0)
        {
            return false;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS16 prefix-count router is invalid.");
        }

        if (router.KeyDepth >= encodedPrefix.Length)
        {
            count = CountContainedVarKeyScalar16RouterTargets(router, maxKeyLength, visitedTargets, visitedRouters);
            return true;
        }

        if (router.PrefixByteCount == 1)
        {
            byte prefixByte = GetVarKeyScalar8Prefix(encodedPrefix, router.KeyDepth);
            long targetOffset = router.FindTarget(prefixByte);
            return TryCountVarKeyScalar16IdentityPrefixFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                routeProvesContainment: router.KeyDepth + 1 >= encodedPrefix.Length,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out count);
        }

        return TryCountVarKeyScalar16IdentityPrefixFromMultiByteRouter(
            router,
            routerBytes,
            maxKeyLength,
            lowerKey,
            upperKey,
            encodedPrefix,
            visitedTargets,
            visitedRouters,
            remainingRouterHops,
            out count);
    }

    /// <summary>
    /// Counts matching targets under one compressed multi-byte `VS16` router for an encoded prefix criterion.<br/>
    /// Routes whose stored stem proves the requested prefix are counted wholesale; routes with a widened final-byte range continue as partial targets when the requested byte is inside that range.<br/>
    /// </summary>
    /// <param name="router">The decoded router view.<br/></param>
    /// <param name="routerBytes">The router page bytes that own compressed route stems.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the compressed-router walk succeeds.<br/></param>
    /// <returns><see langword="true"/> when the compressed router was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar16IdentityPrefixFromMultiByteRouter(
        RouterReader router,
        ReadOnlySpan<byte> routerBytes,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        int keyDepth = router.KeyDepth;
        int prefixByteCount = router.PrefixByteCount;
        int stemLength = prefixByteCount - 1;
        int finalDepth = keyDepth + stemLength;
        int routeEndDepth = keyDepth + prefixByteCount;
        int routeCount = router.RouteCount;
        int maxRouteCount = router.MaxRouteCount;

        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            ReadOnlySpan<byte> stem = routerBytes.Slice(RouterLayout.GetMultiByteRouteStemOffset(maxRouteCount, prefixByteCount, routeIndex), stemLength);
            if (!VarKeyPrefixMatchesRouteStem(encodedPrefix, keyDepth, stem))
            {
                continue;
            }

            long targetOffset = router.GetRouteTargetAt(routeIndex);
            if (targetOffset == 0)
            {
                continue;
            }

            bool contained;
            if (encodedPrefix.Length <= finalDepth)
            {
                contained = true;
            }
            else
            {
                byte finalPrefixByte = GetVarKeyScalar8Prefix(encodedPrefix, finalDepth);
                byte routeStart = router.GetRoutePrefixStartAt(routeIndex);
                byte routeEnd = router.GetRoutePrefixEndAt(routeIndex);
                if (finalPrefixByte < routeStart || finalPrefixByte > routeEnd)
                {
                    continue;
                }

                contained = routeStart == routeEnd && encodedPrefix.Length <= routeEndDepth;
            }

            if (!TryCountVarKeyScalar16IdentityPrefixFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                contained,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    /// <summary>
    /// Counts one routed `VS16` target for an encoded prefix criterion.<br/>
    /// Proven-contained targets use ordinary count-all metadata traversal; partial shelves use exact encoded range checks; routers continue the prefix walk.<br/>
    /// </summary>
    /// <param name="targetOffset">The target offset to count.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower bound for narrow fallback counting.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper bound for narrow fallback counting.<br/></param>
    /// <param name="encodedPrefix">The encoded prefix being matched.<br/></param>
    /// <param name="routeProvesContainment">True when the route path already proves every key below this target starts with <paramref name="encodedPrefix"/>.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the target was counted safely.<br/></param>
    /// <returns><see langword="true"/> when the target was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar16IdentityPrefixFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> encodedPrefix,
        bool routeProvesContainment,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (targetOffset == 0)
        {
            return true;
        }

        if (routeProvesContainment)
        {
            count = CountVarKeyScalar16RouteTarget(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
            return true;
        }

        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Router)
        {
            return TryCountVarKeyScalar16IdentityPrefixFromRouter(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedPrefix,
                visitedTargets,
                visitedRouters,
                remainingRouterHops,
                out count);
        }

        if (kind == VarKeyScalar16RouteTargetKind.Shelf)
        {
            if (!visitedTargets.Add(targetOffset))
            {
                return true;
            }

            count = CountVarKeyScalar16ShelfKeyRangeNarrow(targetOffset, maxKeyLength, lowerKey, upperKey);
            return true;
        }

        throw new InvalidDataException("The routed VS16 prefix-count target is not a shelf or router.");
    }

    /// <summary>
    /// Counts every target directly referenced by an already visited contained `VS16` router.<br/>
    /// This avoids re-entering the router's own visited check while preserving count-all metadata traversal for each child target.<br/>
    /// </summary>
    /// <param name="router">The contained router view whose route targets should be counted.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="visitedTargets">Route targets already counted during this prefix walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted during this prefix walk.<br/></param>
    /// <returns>The number of identities in the router's child targets.<br/></returns>
    private long CountContainedVarKeyScalar16RouterTargets(
        RouterReader router,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        long count = 0;
        int routeCount = router.HasDirectIndex ? RouterLayout.MaxOneByteRouteCount : router.RouteCount;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            count += CountVarKeyScalar16RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
        }

        return count;
    }

    private bool TryCountVarKeyScalar16IdentityRangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        byte[] pathPrefix,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        if (targetOffset == 0)
        {
            return true;
        }

        if (!lowerEdge && !upperEdge)
        {
            count = CountVarKeyScalar16RouteTarget(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
            return true;
        }

        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Shelf)
        {
            if (!visitedTargets.Add(targetOffset))
            {
                return true;
            }

            count = CountVarKeyScalar16ShelfKeyRangeNarrow(targetOffset, maxKeyLength, lowerKey, upperKey);
            return true;
        }

        if (kind != VarKeyScalar16RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS16 range-count target is not a shelf or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return true;
        }

        if (remainingRouterHops <= 0)
        {
            return false;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS16 range-count router is invalid.");
        }

        if (router.PrefixByteCount > 1)
        {
            return TryCountVarKeyScalar16IdentityRangeFromMultiByteRouter(
                router,
                routerBytes,
                maxKeyLength,
                lowerKey,
                upperKey,
                pathPrefix,
                lowerEdge,
                upperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops,
                out count);
        }

        byte lowerPrefix = lowerEdge ? GetVarKeyScalar8Prefix(lowerKey, router.KeyDepth) : byte.MinValue;
        byte upperPrefix = upperEdge ? GetVarKeyScalar8Prefix(upperKey, router.KeyDepth) : byte.MaxValue;
        long lowerTarget = lowerEdge ? router.FindTarget(lowerPrefix) : 0;
        long upperTarget = upperEdge ? router.FindTarget(upperPrefix) : 0;
        if (lowerEdge && upperEdge && lowerPrefix != upperPrefix && lowerTarget != 0 && lowerTarget == upperTarget)
        {
            return false;
        }

        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTarget = router.FindTarget((byte)prefix);
            if (childTarget == 0)
            {
                continue;
            }

            bool childLowerEdge = lowerEdge && prefix == lowerPrefix;
            bool childUpperEdge = upperEdge && prefix == upperPrefix;
            if (!childLowerEdge && !childUpperEdge && (childTarget == lowerTarget || childTarget == upperTarget))
            {
                return false;
            }

            if (!TryCountVarKeyScalar16IdentityRangeFromTarget(
                childTarget,
                maxKeyLength,
                lowerKey,
                upperKey,
                CreateVarKeyRoutePathPrefix(pathPrefix, router.KeyDepth, (byte)prefix),
                childLowerEdge,
                childUpperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    /// <summary>
    /// Counts a compressed multi-byte `VS16` router for an inclusive encoded-key range.<br/>
    /// The classifier keeps fully contained compressed routes on the narrow metadata count path and sends only boundary-overlapping routes through exact shelf range counts.<br/>
    /// </summary>
    /// <param name="router">The decoded compressed router.<br/></param>
    /// <param name="routerBytes">The router page bytes that own the route stems.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower key.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper key.<br/></param>
    /// <param name="pathPrefix">The key bytes proven by parent route traversal.<br/></param>
    /// <param name="lowerEdge">True when this router may contain the lower range boundary.<br/></param>
    /// <param name="upperEdge">True when this router may contain the upper range boundary.<br/></param>
    /// <param name="visitedTargets">Route targets already counted by this range walk.<br/></param>
    /// <param name="visitedRouters">Routers already counted by this range walk.<br/></param>
    /// <param name="remainingRouterHops">The remaining router-hop safety budget.<br/></param>
    /// <param name="count">Receives the matching count when the router was counted safely.<br/></param>
    /// <returns><see langword="true"/> when the compressed router was counted safely; otherwise <see langword="false"/>.<br/></returns>
    private bool TryCountVarKeyScalar16IdentityRangeFromMultiByteRouter(
        RouterReader router,
        ReadOnlySpan<byte> routerBytes,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        ReadOnlySpan<byte> pathPrefix,
        bool lowerEdge,
        bool upperEdge,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters,
        int remainingRouterHops,
        out long count)
    {
        count = 0;
        int keyDepth = router.KeyDepth;
        int prefixByteCount = router.PrefixByteCount;
        int stemLength = prefixByteCount - 1;
        int routeCount = router.RouteCount;
        int maxRouteCount = router.MaxRouteCount;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            ReadOnlySpan<byte> stem = routerBytes.Slice(RouterLayout.GetMultiByteRouteStemOffset(maxRouteCount, prefixByteCount, routeIndex), stemLength);
            byte routeStart = router.GetRoutePrefixStartAt(routeIndex);
            byte routeEnd = router.GetRoutePrefixEndAt(routeIndex);
            if (!TryClassifyVarKeyMultiByteRangeRoute(pathPrefix, keyDepth, stem, routeStart, routeEnd, lowerKey, upperKey, maxKeyLength, lowerEdge, upperEdge, out bool childLowerEdge, out bool childUpperEdge))
            {
                continue;
            }

            long childTarget = router.GetRouteTargetAt(routeIndex);
            if (childTarget == 0)
            {
                continue;
            }

            if (!TryCountVarKeyScalar16IdentityRangeFromTarget(
                childTarget,
                maxKeyLength,
                lowerKey,
                upperKey,
                CreateVarKeyMultiByteRoutePathPrefix(pathPrefix, keyDepth, stem, routeStart),
                childLowerEdge,
                childUpperEdge,
                visitedTargets,
                visitedRouters,
                remainingRouterHops - 1,
                out long childCount))
            {
                return false;
            }

            count += childCount;
        }

        return true;
    }

    private long CountVarKeyScalar16ShelfKeyRangeNarrow(long shelfOffset, int maxKeyLength, ReadOnlySpan<byte> lowerKey, ReadOnlySpan<byte> upperKey)
    {
        if (durabilityBatchActive &&
            varKeyScalar16MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar16MutableShelf? mutableShelf))
        {
            return mutableShelf.CountLiveItemsInKeyRange(lowerKey, upperKey);
        }

        byte[] shelfBytes = ReadVarKeyScalar16ShelfBytes(shelfOffset, maxKeyLength, out VarKeyScalar16Profile profile);
        VarKeyScalar16ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed VS16 range-count shelf is invalid.");
        }

        return shelf.CountItemsInKeyRange(lowerKey, upperKey);
    }

    private long CountVarKeyScalar16IdentitiesFromRouter(
        long routerOffset,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
        RouterReader router = new(routerBytes);
        if (!router.IsValid)
        {
            throw new InvalidDataException("The routed VS16 count router is invalid.");
        }

        long count = 0;
        if (router.HasDirectIndex)
        {
            for (int routeIndex = 0; routeIndex <= byte.MaxValue; routeIndex++)
            {
                count += CountVarKeyScalar16RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
            }

            return count;
        }

        for (int routeIndex = 0; routeIndex < router.RouteCount; routeIndex++)
        {
            count += CountVarKeyScalar16RouteTarget(router.GetRouteTargetAt(routeIndex), maxKeyLength, visitedTargets, visitedRouters);
        }

        return count;
    }

    private long CountVarKeyScalar16RouteTarget(
        long targetOffset,
        int maxKeyLength,
        HashSet<long> visitedTargets,
        HashSet<long> visitedRouters)
    {
        if (targetOffset == 0 || visitedTargets.Contains(targetOffset) || visitedRouters.Contains(targetOffset))
        {
            return 0;
        }

        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Router)
        {
            return CountVarKeyScalar16IdentitiesFromRouter(targetOffset, maxKeyLength, visitedTargets, visitedRouters);
        }

        if (kind != VarKeyScalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The routed VS16 count target is not a shelf or router.");
        }

        if (!visitedTargets.Add(targetOffset))
        {
            return 0;
        }

        return ReadVarKeyScalar16ShelfItemCountNarrow(targetOffset, maxKeyLength);
    }

    private long ReadVarKeyScalar16ShelfItemCountNarrow(long shelfOffset, int maxKeyLength)
    {
        if (durabilityBatchActive &&
            varKeyScalar16MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar16MutableShelf? mutableShelf))
        {
            return mutableShelf.LiveItemCount;
        }

        VarKeyScalar16ShelfCountCacheKey cacheKey = new(shelfOffset, maxKeyLength);
        if (TryGetVarKeyScalar16ShelfCountCache(cacheKey, out long cachedCount))
        {
            return cachedCount;
        }

        Span<byte> header = stackalloc byte[VarKeyScalar16Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar16Layout.ReadMagic(header) != VarKeyScalar16Layout.Magic ||
            VarKeyScalar16Layout.ReadFormatVersion(header) != VarKeyScalar16Layout.FormatVersion ||
            VarKeyScalar16Layout.ReadHeaderSize(header) != VarKeyScalar16Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS16 count shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar16Layout.ReadShelfExtentSize(header);
        _ = VarKeyScalar16Profile.Create(shelfExtentSize, maxKeyLength);
        int count = VarKeyScalar16Layout.ReadItemCount(header);
        int slotStreamLength = VarKeyScalar16Layout.ReadSlotStreamLength(header);
        int slotCapacityBytes = VarKeyScalar16Layout.ReadSlotCapacityBytes(header);
        int recordArenaEnd = VarKeyScalar16Layout.ReadRecordArenaEnd(header);
        int expectedSlotCapacityBytes = VarKeyScalar16Layout.CalculateSlotCapacityBytes(shelfExtentSize);
        if (count < 0 ||
            count > expectedSlotCapacityBytes / VarKeyScalar16Layout.SlotSize ||
            slotStreamLength != checked(count * VarKeyScalar16Layout.SlotSize) ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            recordArenaEnd < VarKeyScalar16Layout.HeaderSize + slotCapacityBytes ||
            recordArenaEnd > shelfExtentSize)
        {
            throw new InvalidDataException("The routed VS16 count shelf metadata is invalid.");
        }

        StoreVarKeyScalar16ShelfCountCache(cacheKey, count);
        return count;
    }

    /// <summary>
    /// Tries to read a session-local narrow count projection for one `VS16` shelf.<br/>
    /// The cache is keyed by physical shelf offset and max key length, and is invalidated by the shared DataKernel mutation-version boundary.<br/>
    /// This mirrors the `VV` count-header cache and avoids repeated shelf-header reads without maintaining persisted count metadata.<br/>
    /// </summary>
    /// <param name="key">The physical `VS16` shelf count cache key.<br/></param>
    /// <param name="count">Receives the cached item count when a current entry is available.<br/></param>
    /// <returns><see langword="true"/> when a current count projection was found; otherwise <see langword="false"/>.<br/></returns>
    private bool TryGetVarKeyScalar16ShelfCountCache(VarKeyScalar16ShelfCountCacheKey key, out long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            if (varKeyScalar16ShelfCountCache.TryGetValue(key, out count) &&
                kernel.MutationVersion == mutationVersion)
            {
                return true;
            }
        }

        count = 0;
        return false;
    }


    /// <summary>
    /// Stores one validated `VS16` shelf item-count projection at the current raw-storage mutation version.<br/>
    /// The stored value comes from an existing shelf header read by the count operation, preserving the rule that cached count metadata is only kept when it is free.<br/>
    /// </summary>
    /// <param name="key">The physical `VS16` shelf count cache key.<br/></param>
    /// <param name="count">The validated live item count read from the shelf header.<br/></param>
    private void StoreVarKeyScalar16ShelfCountCache(VarKeyScalar16ShelfCountCacheKey key, long count)
    {
        long mutationVersion = kernel.MutationVersion;
        lock (countHeaderCacheSync)
        {
            EnsureCountHeaderCacheVersionUnderLock(mutationVersion);
            varKeyScalar16ShelfCountCache[key] = count;
        }
    }

    /// <summary>
    /// Creates the inclusive lower encoded-key bound for a one-byte `VS` root prefix.<br/>
    /// The shortest byte sequence for the prefix sorts before longer keys that share the same prefix, which is the desired edge lower bound for physical var-key traversal.<br/>
    /// </summary>
    /// <param name="prefix">The root prefix byte to bound.<br/></param>
    /// <returns>A lower-bound key for the prefix.<br/></returns>
    private static byte[] CreateVarKeyPrefixLowerBound(byte prefix)
    {
        return [prefix];
    }

    /// <summary>
    /// Creates the inclusive upper encoded-key bound for a one-byte `VS` root prefix.<br/>
    /// Filling the remaining physical key length with `0xFF` keeps the boundary above every persisted key beginning with the prefix without inspecting shelf tuples.<br/>
    /// </summary>
    /// <param name="prefix">The root prefix byte to bound.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length for the index.<br/></param>
    /// <returns>An upper-bound key for the prefix.<br/></returns>
    private static byte[] CreateVarKeyPrefixUpperBound(byte prefix, int maxKeyLength)
    {
        if (maxKeyLength <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxKeyLength), maxKeyLength, "Maximum key length must be positive.");
        }

        byte[] key = new byte[maxKeyLength];
        key[0] = prefix;
        key.AsSpan(1).Fill(0xFF);
        return key;
    }

    /// <summary>
    /// Creates the exact path prefix for a child route selected by a one-byte var-key router.<br/>
    /// The caller supplies the bytes proven by parent traversal; missing bytes up to the router depth are zero-filled to match the existing short-key routing rule.<br/>
    /// </summary>
    /// <param name="parentPrefix">The exact prefix bytes known before the current router.<br/></param>
    /// <param name="keyDepth">The byte depth consumed by the current router.<br/></param>
    /// <param name="routePrefix">The child route prefix byte selected at <paramref name="keyDepth"/>.<br/></param>
    /// <returns>The exact prefix bytes known for the child route.<br/></returns>
    private static byte[] CreateVarKeyRoutePathPrefix(ReadOnlySpan<byte> parentPrefix, int keyDepth, byte routePrefix)
    {
        byte[] prefix = new byte[keyDepth + 1];
        parentPrefix.Slice(0, Math.Min(parentPrefix.Length, keyDepth)).CopyTo(prefix);
        prefix[keyDepth] = routePrefix;
        return prefix;
    }

    /// <summary>
    /// Creates the exact path prefix for a child route selected by a compressed multi-byte var-key router.<br/>
    /// The returned prefix includes the parent-proven bytes, the compressed stem bytes, and the selected route start byte; callers use it to preserve boundary context for deeper routers.<br/>
    /// </summary>
    /// <param name="parentPrefix">The exact prefix bytes known before the current router.<br/></param>
    /// <param name="keyDepth">The byte depth consumed by the current router.<br/></param>
    /// <param name="stem">The compressed route stem bytes stored before the final route byte interval.<br/></param>
    /// <param name="routePrefix">The selected route prefix byte at the final compressed depth.<br/></param>
    /// <returns>The exact prefix bytes known for the child route.<br/></returns>
    private static byte[] CreateVarKeyMultiByteRoutePathPrefix(ReadOnlySpan<byte> parentPrefix, int keyDepth, ReadOnlySpan<byte> stem, byte routePrefix)
    {
        byte[] prefix = new byte[keyDepth + stem.Length + 1];
        parentPrefix.Slice(0, Math.Min(parentPrefix.Length, keyDepth)).CopyTo(prefix);
        stem.CopyTo(prefix.AsSpan(keyDepth));
        prefix[^1] = routePrefix;
        return prefix;
    }

    /// <summary>
    /// Classifies one compressed var-key route interval against an inclusive encoded-key range.<br/>
    /// The comparison uses zero/0xFF extension as a conservative routing bound: uncertain edges remain boundary work, while only provably contained intervals are allowed to use metadata counts.<br/>
    /// </summary>
    /// <param name="pathPrefix">The key bytes proven by parent route traversal.<br/></param>
    /// <param name="keyDepth">The byte depth consumed by the current router.<br/></param>
    /// <param name="stem">The compressed route stem bytes stored before the final route byte interval.<br/></param>
    /// <param name="routeStart">The inclusive first final-byte value for the route interval.<br/></param>
    /// <param name="routeEnd">The inclusive last final-byte value for the route interval.<br/></param>
    /// <param name="lowerKey">The inclusive encoded lower key.<br/></param>
    /// <param name="upperKey">The inclusive encoded upper key.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <param name="lowerEdge">True when this router may contain the lower range boundary.<br/></param>
    /// <param name="upperEdge">True when this router may contain the upper range boundary.<br/></param>
    /// <param name="childLowerEdge">Receives whether the child target still overlaps the lower boundary.<br/></param>
    /// <param name="childUpperEdge">Receives whether the child target still overlaps the upper boundary.<br/></param>
    /// <returns><see langword="true"/> when the route can intersect the requested range; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryClassifyVarKeyMultiByteRangeRoute(
        ReadOnlySpan<byte> pathPrefix,
        int keyDepth,
        ReadOnlySpan<byte> stem,
        byte routeStart,
        byte routeEnd,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxKeyLength,
        bool lowerEdge,
        bool upperEdge,
        out bool childLowerEdge,
        out bool childUpperEdge)
    {
        childLowerEdge = false;
        childUpperEdge = false;
        if (lowerEdge &&
            CompareVarKeyMultiByteRouteBoundToKey(pathPrefix, keyDepth, stem, routeEnd, true, lowerKey, maxKeyLength) < 0)
        {
            return false;
        }

        if (upperEdge &&
            CompareVarKeyMultiByteRouteBoundToKey(pathPrefix, keyDepth, stem, routeStart, false, upperKey, maxKeyLength) > 0)
        {
            return false;
        }

        childLowerEdge = lowerEdge &&
            CompareVarKeyMultiByteRouteBoundToKey(pathPrefix, keyDepth, stem, routeStart, false, lowerKey, maxKeyLength) < 0;
        childUpperEdge = upperEdge &&
            CompareVarKeyMultiByteRouteBoundToKey(pathPrefix, keyDepth, stem, routeEnd, true, upperKey, maxKeyLength) > 0;
        return true;
    }

    /// <summary>
    /// Compares a compressed route's low or high synthetic bound against an encoded key without allocating a full bound key.<br/>
    /// Bytes after the route prefix are treated as zero for the low bound and 0xFF for the high bound, matching the conservative containment model used by range-count routing.<br/>
    /// </summary>
    /// <param name="pathPrefix">The key bytes proven by parent route traversal.<br/></param>
    /// <param name="keyDepth">The byte depth consumed by the current router.<br/></param>
    /// <param name="stem">The compressed route stem bytes stored before the final route byte interval.<br/></param>
    /// <param name="routePrefix">The route prefix byte at the final compressed depth.<br/></param>
    /// <param name="highBound">True to compare the route's high synthetic bound; false for the low synthetic bound.<br/></param>
    /// <param name="key">The encoded key to compare against.<br/></param>
    /// <param name="maxKeyLength">The maximum encoded key length accepted by the index.<br/></param>
    /// <returns>A negative value when the route bound is less than the key, zero when equivalent under padded comparison, or a positive value when greater.<br/></returns>
    private static int CompareVarKeyMultiByteRouteBoundToKey(
        ReadOnlySpan<byte> pathPrefix,
        int keyDepth,
        ReadOnlySpan<byte> stem,
        byte routePrefix,
        bool highBound,
        ReadOnlySpan<byte> key,
        int maxKeyLength)
    {
        int routeDepth = keyDepth + stem.Length;
        int routeLength = routeDepth + 1;
        int compareLength = Math.Max(Math.Max(routeLength, key.Length), maxKeyLength);
        byte fill = highBound ? byte.MaxValue : byte.MinValue;
        for (int depth = 0; depth < compareLength; depth++)
        {
            byte routeByte;
            if (depth < keyDepth)
            {
                routeByte = depth < pathPrefix.Length ? pathPrefix[depth] : byte.MinValue;
            }
            else if (depth < routeDepth)
            {
                routeByte = stem[depth - keyDepth];
            }
            else if (depth == routeDepth)
            {
                routeByte = routePrefix;
            }
            else
            {
                routeByte = fill;
            }

            byte keyByte = depth < key.Length ? key[depth] : byte.MinValue;
            if (routeByte != keyByte)
            {
                return routeByte < keyByte ? -1 : 1;
            }
        }

        return 0;
    }

    private long CountTerminalIdentity8RootNarrow(long rootOffset)
    {
        Span<byte> rootHeader = stackalloc byte[TerminalIdentityRootLayout.HeaderSize];
        kernel.Read(rootOffset, rootHeader);
        if (TerminalIdentityRootLayout.ReadMagic(rootHeader) != TerminalIdentityRootLayout.Magic ||
            TerminalIdentityRootLayout.ReadFormatVersion(rootHeader) != TerminalIdentityRootLayout.FormatVersion ||
            TerminalIdentityRootLayout.ReadHeaderSize(rootHeader) != TerminalIdentityRootLayout.HeaderSize)
        {
            throw new InvalidDataException("The terminal identity count root header is invalid.");
        }

        int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootHeader);
        long shelfOffset = TerminalIdentityRootLayout.ReadFirstShelfOffset(rootHeader);
        long count = 0;
        HashSet<long> visitedShelves = new();
        while (shelfOffset != 0)
        {
            if (!visitedShelves.Add(shelfOffset))
            {
                break;
            }

            count += ReadTerminalIdentity8ShelfCountNarrow(shelfOffset, shelfExtentSize, out shelfOffset);
        }

        return count;
    }

    /// <summary>
    /// Classifies the structure stored at a route target offset for the first `VS8` varlen-key shape.<br/>
    /// Only the magic value is read, keeping target classification independent from the concrete grown shelf extent size.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified `VS8` route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `VS8` shelf magic value.</exception>
    internal VarKeyScalar8RouteTargetKind ClassifyVarKeyScalar8RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return VarKeyScalar8RouteTargetKind.None;
        }

        RouteTargetKindCache targetKindCache = varKeyScalar8RouteTargetKindCache.Value!;
        if (targetKindCache.TryGet(targetOffset, out int cachedKind))
        {
            return (VarKeyScalar8RouteTargetKind)cachedKind;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            targetKindCache.Set(targetOffset, (int)VarKeyScalar8RouteTargetKind.Router);
            return VarKeyScalar8RouteTargetKind.Router;
        }

        if (magic == VarKeyScalar8Layout.Magic)
        {
            targetKindCache.Set(targetOffset, (int)VarKeyScalar8RouteTargetKind.Shelf);
            return VarKeyScalar8RouteTargetKind.Shelf;
        }

        if (magic == TerminalIdentityRootLayout.Magic)
        {
            targetKindCache.Set(targetOffset, (int)VarKeyScalar8RouteTargetKind.TerminalIdentityRoot);
            return VarKeyScalar8RouteTargetKind.TerminalIdentityRoot;
        }

        throw new InvalidDataException($"VS8 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    internal VarKeyScalar16RouteTargetKind ClassifyVarKeyScalar16RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
