        }

        throw new InvalidDataException($"VS16 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-8` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, making classification overhead visible for benchmarking.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior are still being designed.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded scalar key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar8Scalar8RouteTarget WalkScalar8Scalar8RouteTarget(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            if (TryGetDirectRouterView(routerOffset, out DirectRouterView? directView))
            {
                byte directPrefixByte = GetScalar8Scalar8Prefix(encodedKey, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed target is unset.");
                }

                Scalar8Scalar8RouteTargetKind directKind = ClassifyScalar8Scalar8RouteTarget(directTargetOffset);
                if (directKind == Scalar8Scalar8RouteTargetKind.Shelf ||
                    directKind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
                {
                    return new Scalar8Scalar8RouteTarget(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId);
                }

                if (directKind == Scalar8Scalar8RouteTargetKind.Router)
                {
                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed target is not a shelf or router.");
            }

            byte[] routerBytes = new byte[RouterLayout.Size];
            kernel.Read(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar8Scalar8Prefix(encodedKey, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed target is unset.");
            }

            Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTarget(targetOffset);
            if (kind == Scalar8Scalar8RouteTargetKind.Shelf ||
                kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                return new Scalar8Scalar8RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId);
            }

            if (kind == Scalar8Scalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-8` key using the requested route-read policy.<br/>
    /// This overload is the first explicit policy gate for arena-aware route reads; the default uncached policy preserves the established classified walker behavior.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded scalar key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply for router page and target classifier reads.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, routing does not terminate at a shelf, or the policy is unsupported.</exception>
    internal Scalar8Scalar8RouteTarget WalkScalar8Scalar8RouteTarget(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy)
    {
        return readPolicy switch
        {
            Scalar8Scalar8RouteReadPolicy.Uncached => WalkScalar8Scalar8RouteTarget(rootRouterOffset, encodedKey, maxRouterHops),
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache => WalkScalar8Scalar8RouteTargetUsingArenaCache(rootRouterOffset, encodedKey, maxRouterHops),
            _ => throw new InvalidDataException($"Unsupported SS8-8 route read policy {readPolicy}.")
        };
    }

    /// <summary>
    /// Classifies the structure stored at a direct `SS16-8` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS16-8` shelf magic value.</exception>
    internal Scalar16Scalar8RouteTargetKind ClassifyScalar16Scalar8RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Scalar16Scalar8RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Scalar16Scalar8RouteTargetKind.Router;
        }

        if (magic == Scalar16Scalar8Layout.Magic)
        {
            return Scalar16Scalar8RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"SS16-8 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS16-8` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, matching the first `SS8-8` route walker shape.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior remain shape-local.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKeyHigh">The encoded high key half whose prefix bytes drive routing.</param>
    /// <param name="encodedKeyLow">The encoded low key half whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar16Scalar8RouteTarget WalkScalar16Scalar8RouteTarget(
        long rootRouterOffset,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        int maxRouterHops)
    {
        return WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops).Target;
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS16-8` key and returns both the classified target and the parent router route that selected it.<br/>
    /// Parent-route split logic uses this to refine the exact router page that currently fans several prefixes into the same full shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKeyHigh">The encoded high key half whose prefix bytes drive routing.</param>
    /// <param name="encodedKeyLow">The encoded low key half whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified route target and parent router route metadata.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar16Scalar8RoutePathTarget WalkScalar16Scalar8RoutePathTarget(
        long rootRouterOffset,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed SS16-8 target is unset.");
            }

            Scalar16Scalar8RouteTargetKind kind = ClassifyScalar16Scalar8RouteTarget(targetOffset);
            if (kind == Scalar16Scalar8RouteTargetKind.Shelf)
            {
                return new Scalar16Scalar8RoutePathTarget(
                    new Scalar16Scalar8RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte);
            }

            if (kind == Scalar16Scalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed SS16-8 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed SS16-8 target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Classifies the structure stored at a direct `FS32-8` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `FS32-8` shelf magic value.</exception>
    internal Fixed32Scalar8RouteTargetKind ClassifyFixed32Scalar8RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Fixed32Scalar8RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        if (!TryReadFromRouterArenaCache(targetOffset, magicBytes))
        {
            kernel.Read(targetOffset, magicBytes);
        }
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Fixed32Scalar8RouteTargetKind.Router;
        }

        if (magic == Fixed32Scalar8Layout.Magic)
        {
            return Fixed32Scalar8RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"FS32-8 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `FS32-8` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, matching the first fixed scalar route walker shape.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior remain shape-local.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="key0">The encoded fixed key part 0 whose prefix bytes drive routing.</param>
    /// <param name="key1">The encoded fixed key part 1 whose prefix bytes drive routing.</param>
    /// <param name="key2">The encoded fixed key part 2 whose prefix bytes drive routing.</param>
    /// <param name="key3">The encoded fixed key part 3 whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Fixed32Scalar8RouteTarget WalkFixed32Scalar8RouteTarget(
        long rootRouterOffset,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        int maxRouterHops)
    {
        return WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops).Target;
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `FS32-8` key and returns both the classified target and the parent router route that selected it.<br/>
    /// Parent-route split logic uses this to refine the exact router page that currently fans several prefixes into the same full shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="key0">The encoded fixed key part 0 whose prefix bytes drive routing.</param>
    /// <param name="key1">The encoded fixed key part 1 whose prefix bytes drive routing.</param>
    /// <param name="key2">The encoded fixed key part 2 whose prefix bytes drive routing.</param>
    /// <param name="key3">The encoded fixed key part 3 whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="routerOffsetsByDepth">Optional caller-owned frontier storage populated with each visited router offset at its encoded key depth.<br/></param>
    /// <returns>The classified route target and parent router route metadata.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Fixed32Scalar8RoutePathTarget WalkFixed32Scalar8RoutePathTarget(
        long rootRouterOffset,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        int maxRouterHops,
        Span<long> routerOffsetsByDepth = default)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        if (!routerOffsetsByDepth.IsEmpty && routerOffsetsByDepth.Length < Fixed32Scalar8Layout.KeySize)
        {
            throw new ArgumentException("The FS32-8 route frontier must have room for every fixed-key byte depth.", nameof(routerOffsetsByDepth));
        }

        long routerOffset = rootRouterOffset;
        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            if (TryGetDirectRouterView(routerOffset, out DirectRouterView? directView))
            {
                if (!routerOffsetsByDepth.IsEmpty)
                    routerOffsetsByDepth[directView!.KeyDepth] = routerOffset;

                byte directPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed FS32-8 target is unset.");
                }

                Fixed32Scalar8RouteTargetKind directKind = (Fixed32Scalar8RouteTargetKind)directView.GetTargetKind(directPrefixByte);
                if (directKind == Fixed32Scalar8RouteTargetKind.None)
                {
                    directKind = ClassifyFixed32Scalar8RouteTarget(directTargetOffset);
                    directView.SetTargetKind(directPrefixByte, (Scalar8Scalar8RouteTargetKind)directKind);
                }

                if (directKind == Fixed32Scalar8RouteTargetKind.Shelf)
                {
                    return new Fixed32Scalar8RoutePathTarget(
                        new Fixed32Scalar8RouteTarget(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte);
                }

                if (directKind == Fixed32Scalar8RouteTargetKind.Router)
                {
                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed FS32-8 target is not a shelf or router.");
            }

            ReadRouterPageUsingPageCache(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            if (!routerOffsetsByDepth.IsEmpty)
                routerOffsetsByDepth[reader.KeyDepth] = routerOffset;

            byte prefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed FS32-8 target is unset.");
            }

            Fixed32Scalar8RouteTargetKind kind = ClassifyFixed32Scalar8RouteTarget(targetOffset);
            if (kind == Fixed32Scalar8RouteTargetKind.Shelf)
            {
                return new Fixed32Scalar8RoutePathTarget(
                    new Fixed32Scalar8RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte);
            }

            if (kind == Fixed32Scalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed FS32-8 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed FS32-8 target walk exceeded the configured maximum router hop count.");
    }

