    /// Classifies the structure stored at a direct `SS16-16` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS16-16` shelf magic value.</exception>
    internal Scalar16Scalar16RouteTargetKind ClassifyScalar16Scalar16RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Scalar16Scalar16RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Scalar16Scalar16RouteTargetKind.Router;
        }

        if (magic == Scalar16Scalar16Layout.Magic)
        {
            return Scalar16Scalar16RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"SS16-16 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS16-16` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, matching the first widened-shape route walker shape.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior remain shape-local.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKeyHigh">The encoded high key half whose prefix bytes drive routing.</param>
    /// <param name="encodedKeyLow">The encoded low key half whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar16Scalar16RouteTarget WalkScalar16Scalar16RouteTarget(
        long rootRouterOffset,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        int maxRouterHops)
    {
        return WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops).Target;
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS16-16` key and returns both the classified target and the parent router route that selected it.<br/>
    /// Parent-route split logic uses this to refine the exact router page that currently fans several prefixes into the same full shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKeyHigh">The encoded high key half whose prefix bytes drive routing.</param>
    /// <param name="encodedKeyLow">The encoded low key half whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified route target and parent router route metadata.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar16Scalar16RoutePathTarget WalkScalar16Scalar16RoutePathTarget(
        long rootRouterOffset,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            if (TryGetDirectRouterView(routerOffset, out DirectRouterView? directView))
            {
                byte directPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed SS16-16 target is unset.");
                }

                Scalar16Scalar16RouteTargetKind directKind = (Scalar16Scalar16RouteTargetKind)directView.GetTargetKind(directPrefixByte);
                if (directKind == Scalar16Scalar16RouteTargetKind.None)
                {
                    directKind = ClassifyScalar16Scalar16RouteTarget(directTargetOffset);
                    directView.SetTargetKind(directPrefixByte, (Scalar8Scalar8RouteTargetKind)directKind);
                }

                if (directKind == Scalar16Scalar16RouteTargetKind.Shelf)
                {
                    return new Scalar16Scalar16RoutePathTarget(
                        new Scalar16Scalar16RouteTarget(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte);
                }

                if (directKind == Scalar16Scalar16RouteTargetKind.Router)
                {
                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed SS16-16 target is not a shelf or router.");
            }

            ReadRouterPageUsingPageCache(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed SS16-16 target is unset.");
            }

            Scalar16Scalar16RouteTargetKind kind = ClassifyScalar16Scalar16RouteTarget(targetOffset);
            if (kind == Scalar16Scalar16RouteTargetKind.Shelf)
            {
                return new Scalar16Scalar16RoutePathTarget(
                    new Scalar16Scalar16RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte);
            }

            if (kind == Scalar16Scalar16RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed SS16-16 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed SS16-16 target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Walks routers for a raw `VS8` key until the route target is classified as a shelf.<br/>
    /// The key bytes themselves drive routing; missing deeper key bytes route as zero so short keys remain deterministic.<br/>
    /// One-byte routers use the existing route-slot lookup path; multi-byte routers compare their exact stem bytes and final-byte route range.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="key">The raw byte key whose bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target plus the parent route that selected it.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, invalid, or does not terminate at a shelf.</exception>
    internal VarKeyScalar8RoutePathTarget WalkVarKeyScalar8RoutePathTarget(
        long rootRouterOffset,
        ReadOnlySpan<byte> key,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The VS8 maximum router hop count must be positive.");
        }

        Span<byte> routerSpan = varKeyScalar8RouteWalkRouterScratch.Value!.AsSpan(0, RouterLayout.Size);
        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            long routeSliceStart = StartVarKeyScalar8PhaseTicks();
            long routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            bool hasDirectView = TryGetDirectRouterView(routerOffset, out DirectRouterView? directView);
            RecordVarKeyScalar8RouteAllocation("route/direct-view", routeSliceStart, routeSliceAllocatedStart);
            if (hasDirectView)
            {
                byte directPrefixByte = GetVarKeyScalar8Prefix(key, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    return new VarKeyScalar8RoutePathTarget(
                        new VarKeyScalar8RouteTarget(VarKeyScalar8RouteTargetKind.None, 0, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte,
                        directPrefixByte);
                }

                VarKeyScalar8RouteTargetKind directKind = ToVarKeyScalar8RouteTargetKind(directView.GetTargetKind(directPrefixByte));
                if (directKind == VarKeyScalar8RouteTargetKind.None)
                {
                    routeSliceStart = StartVarKeyScalar8PhaseTicks();
                    routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
                    directKind = ClassifyVarKeyScalar8RouteTarget(directTargetOffset);
                    RecordVarKeyScalar8RouteAllocation("route/direct-classify", routeSliceStart, routeSliceAllocatedStart);
                    directView.SetTargetKind(directPrefixByte, ToDirectRouterTargetKind(directKind));
                }

                if (directKind == VarKeyScalar8RouteTargetKind.Shelf ||
                    directKind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
                {
                    return new VarKeyScalar8RoutePathTarget(
                        new VarKeyScalar8RouteTarget(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte,
                        directPrefixByte);
                }

                if (directKind == VarKeyScalar8RouteTargetKind.Router)
                {
                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed VS8 target is not a shelf or router.");
            }

            routeSliceStart = StartVarKeyScalar8PhaseTicks();
            routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            ReadRouterPageUsingPageCache(routerOffset, routerSpan);
            RouterReader multiByteReader = new(routerSpan);
            if (!multiByteReader.IsValid)
            {
                throw new InvalidDataException("The routed VS8 router is invalid.");
            }

            RecordVarKeyScalar8RouteAllocation("route/multibyte-page-read", routeSliceStart, routeSliceAllocatedStart);
            if (multiByteReader.PrefixByteCount > 1 && !multiByteReader.HasDirectIndex)
            {
                long multiByteTargetOffset = multiByteReader.FindTarget(key, multiByteReader.KeyDepth, out int multiByteRouteIndex);
                if (multiByteTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed VS8 target is unset.");
                }

                routeSliceStart = StartVarKeyScalar8PhaseTicks();
                routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
                VarKeyScalar8RouteTargetKind multiByteKind = ClassifyVarKeyScalar8RouteTarget(multiByteTargetOffset);
                RecordVarKeyScalar8RouteAllocation("route/multibyte-classify", routeSliceStart, routeSliceAllocatedStart);

                byte multiBytePrefixByte = GetVarKeyScalar8Prefix(key, multiByteReader.KeyDepth);
                if (multiByteKind == VarKeyScalar8RouteTargetKind.Shelf ||
                    multiByteKind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
                {
                    return new VarKeyScalar8RoutePathTarget(
                        new VarKeyScalar8RouteTarget(multiByteKind, multiByteTargetOffset, multiByteReader.KeyDepth, multiByteReader.AllocationClassId),
                        routerOffset,
                        multiBytePrefixByte,
                        multiByteRouteIndex);
                }

                if (multiByteKind == VarKeyScalar8RouteTargetKind.Router)
                {
                    routerOffset = multiByteTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed VS8 target is not a shelf or router.");
            }

            routeSliceStart = StartVarKeyScalar8PhaseTicks();
            routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            kernel.Read(routerOffset, routerSpan);
            RouterReader reader = new(routerSpan);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed VS8 router is invalid.");
            }
            RecordVarKeyScalar8RouteAllocation("route/raw-router-read", routeSliceStart, routeSliceAllocatedStart);

            byte prefixByte = GetVarKeyScalar8Prefix(key, reader.KeyDepth);
            long targetOffset = reader.PrefixByteCount == 1
                ? reader.FindTarget(prefixByte, out int routeIndex)
                : reader.FindTarget(key, reader.KeyDepth, out routeIndex);
            if (targetOffset == 0)
            {
                return new VarKeyScalar8RoutePathTarget(
                    new VarKeyScalar8RouteTarget(VarKeyScalar8RouteTargetKind.None, 0, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte,
                    routeIndex);
            }

            routeSliceStart = StartVarKeyScalar8PhaseTicks();
            routeSliceAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
            RecordVarKeyScalar8RouteAllocation("route/raw-classify", routeSliceStart, routeSliceAllocatedStart);
            if (kind == VarKeyScalar8RouteTargetKind.Shelf ||
                kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
            {
                return new VarKeyScalar8RoutePathTarget(
                    new VarKeyScalar8RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte,
                    routeIndex);
            }

            if (kind == VarKeyScalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed VS8 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed VS8 target walk exceeded the configured maximum router hop count.");
    }

    internal static byte GetVarKeyScalar8Prefix(ReadOnlySpan<byte> key, int keyDepth)
    {
        return keyDepth >= 0 && keyDepth < key.Length
            ? key[keyDepth]
            : (byte)0;
    }

    internal VarKeyScalar16RoutePathTarget WalkVarKeyScalar16RoutePathTarget(
        long rootRouterOffset,
        ReadOnlySpan<byte> key,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The VS16 maximum router hop count must be positive.");
        }

        Span<byte> routerSpan = varKeyScalar16RouteWalkRouterScratch.Value!.AsSpan(0, RouterLayout.Size);
        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            if (TryGetDirectRouterView(routerOffset, out DirectRouterView? directView))
            {
                byte directPrefixByte = GetVarKeyScalar16Prefix(key, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    return new VarKeyScalar16RoutePathTarget(
                        new VarKeyScalar16RouteTarget(VarKeyScalar16RouteTargetKind.None, 0, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte,
                        directPrefixByte);
                }

                VarKeyScalar16RouteTargetKind directKind = ToVarKeyScalar16RouteTargetKind(directView.GetTargetKind(directPrefixByte));
                if (directKind == VarKeyScalar16RouteTargetKind.None)
                {
                    directKind = ClassifyVarKeyScalar16RouteTarget(directTargetOffset);
                    directView.SetTargetKind(directPrefixByte, ToDirectRouterTargetKind(directKind));
                }

                if (directKind == VarKeyScalar16RouteTargetKind.Shelf)
                {
                    return new VarKeyScalar16RoutePathTarget(
                        new VarKeyScalar16RouteTarget(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId),
                        routerOffset,
                        directPrefixByte,
                        directPrefixByte);
                }

                if (directKind == VarKeyScalar16RouteTargetKind.Router)
                {
                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed VS16 target is not a shelf or router.");
            }

            if (TryGetMultiByteRouterView(routerOffset, out MultiByteRouterView? multiByteView))
            {
                long multiByteTargetOffset = multiByteView!.FindTarget(key, out int multiByteRouteIndex);
                if (multiByteTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed VS16 target is unset.");
                }

                PromotedRouteTargetKind cachedKind = multiByteView.GetTargetKind(multiByteRouteIndex);
                VarKeyScalar16RouteTargetKind multiByteKind;
                if (cachedKind == PromotedRouteTargetKind.None)
                {
                    multiByteKind = ClassifyVarKeyScalar16RouteTarget(multiByteTargetOffset);
                    multiByteView.SetTargetKind(multiByteRouteIndex, ToPromotedRouteTargetKind(multiByteKind));
                }
                else
                {
                    multiByteKind = ToVarKeyScalar16RouteTargetKind(cachedKind);
                }

                byte multiBytePrefixByte = GetVarKeyScalar16Prefix(key, multiByteView.KeyDepth);
                if (multiByteKind == VarKeyScalar16RouteTargetKind.Shelf)
                {
                    return new VarKeyScalar16RoutePathTarget(
                        new VarKeyScalar16RouteTarget(multiByteKind, multiByteTargetOffset, multiByteView.KeyDepth, multiByteView.AllocationClassId),
                        routerOffset,
                        multiBytePrefixByte,
                        multiByteRouteIndex);
                }

                if (multiByteKind == VarKeyScalar16RouteTargetKind.Router)
                {
                    routerOffset = multiByteTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed VS16 target is not a shelf or router.");
            }

            kernel.Read(routerOffset, routerSpan);
            RouterReader reader = new(routerSpan);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed VS16 router is invalid.");
            }

            byte prefixByte = GetVarKeyScalar16Prefix(key, reader.KeyDepth);
            long targetOffset = reader.PrefixByteCount == 1
                ? reader.FindTarget(prefixByte, out int routeIndex)
                : reader.FindTarget(key, reader.KeyDepth, out routeIndex);
            if (targetOffset == 0)
            {
                return new VarKeyScalar16RoutePathTarget(
                    new VarKeyScalar16RouteTarget(VarKeyScalar16RouteTargetKind.None, 0, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte,
                    routeIndex);
            }

            VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
            if (kind == VarKeyScalar16RouteTargetKind.Shelf)
            {
                return new VarKeyScalar16RoutePathTarget(
                    new VarKeyScalar16RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte,
                    routeIndex);
            }

            if (kind == VarKeyScalar16RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed VS16 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed VS16 target walk exceeded the configured maximum router hop count.");
    }

    private static byte GetVarKeyScalar16Prefix(ReadOnlySpan<byte> key, int keyDepth)
    {
        return keyDepth >= 0 && keyDepth < key.Length
            ? key[keyDepth]
            : (byte)0;
    }

    private static PromotedRouteTargetKind ToPromotedRouteTargetKind(VarKeyScalar8RouteTargetKind kind)
    {
        return kind switch
        {
            VarKeyScalar8RouteTargetKind.Shelf => PromotedRouteTargetKind.Shelf,
            VarKeyScalar8RouteTargetKind.Router => PromotedRouteTargetKind.Router,
            VarKeyScalar8RouteTargetKind.TerminalIdentityRoot => PromotedRouteTargetKind.TerminalIdentityRoot,
            _ => PromotedRouteTargetKind.None
        };
    }

    private static PromotedRouteTargetKind ToPromotedRouteTargetKind(VarKeyScalar16RouteTargetKind kind)
    {
        return kind switch
        {
            VarKeyScalar16RouteTargetKind.Shelf => PromotedRouteTargetKind.Shelf,
            VarKeyScalar16RouteTargetKind.Router => PromotedRouteTargetKind.Router,
            _ => PromotedRouteTargetKind.None
        };
    }

    /// <summary>
    /// Converts a `VS8` route target kind into the shared direct-router cached target-kind enum.<br/>
    /// The direct-router view is shape-agnostic, so the walker stores only the common structural shape classification there.<br/>
    /// </summary>
    /// <param name="kind">The `VS8` target kind to cache.</param>
    /// <returns>The shared direct-router target kind.</returns>
    private static Scalar8Scalar8RouteTargetKind ToDirectRouterTargetKind(VarKeyScalar8RouteTargetKind kind)
    {
        return kind switch
        {
            VarKeyScalar8RouteTargetKind.Shelf => Scalar8Scalar8RouteTargetKind.Shelf,
            VarKeyScalar8RouteTargetKind.Router => Scalar8Scalar8RouteTargetKind.Router,
            VarKeyScalar8RouteTargetKind.TerminalIdentityRoot => Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot,
            _ => Scalar8Scalar8RouteTargetKind.None
        };
    }

    /// <summary>
    /// Converts a `VS16` route target kind into the shared direct-router cached target-kind enum.<br/>
    /// The direct-router view is shape-agnostic, so the walker stores only the common structural shape classification there.<br/>
    /// </summary>
    /// <param name="kind">The `VS16` target kind to cache.</param>
    /// <returns>The shared direct-router target kind.</returns>
    private static Scalar8Scalar8RouteTargetKind ToDirectRouterTargetKind(VarKeyScalar16RouteTargetKind kind)
    {
        return kind switch
        {
            VarKeyScalar16RouteTargetKind.Shelf => Scalar8Scalar8RouteTargetKind.Shelf,
            VarKeyScalar16RouteTargetKind.Router => Scalar8Scalar8RouteTargetKind.Router,
            _ => Scalar8Scalar8RouteTargetKind.None
        };
    }

    /// <summary>
    /// Converts a direct-router cached target kind into the `VS8` route target enum.<br/>
    /// Direct router views are shared across route shapes, so the cached storage enum is mapped explicitly at the route-walker edge.<br/>
    /// </summary>
    /// <param name="kind">The cached shared direct-router target kind.</param>
    /// <returns>The equivalent `VS8` target kind, or `None` when no cached classification exists.</returns>
    private static VarKeyScalar8RouteTargetKind ToVarKeyScalar8RouteTargetKind(Scalar8Scalar8RouteTargetKind kind)
    {
        return kind switch
        {
            Scalar8Scalar8RouteTargetKind.Shelf => VarKeyScalar8RouteTargetKind.Shelf,
            Scalar8Scalar8RouteTargetKind.Router => VarKeyScalar8RouteTargetKind.Router,
            Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot => VarKeyScalar8RouteTargetKind.TerminalIdentityRoot,
            _ => VarKeyScalar8RouteTargetKind.None
        };
    }

    private static VarKeyScalar8RouteTargetKind ToVarKeyScalar8RouteTargetKind(PromotedRouteTargetKind kind)
    {
        return kind switch
        {
            PromotedRouteTargetKind.Shelf => VarKeyScalar8RouteTargetKind.Shelf,
            PromotedRouteTargetKind.Router => VarKeyScalar8RouteTargetKind.Router,
            PromotedRouteTargetKind.TerminalIdentityRoot => VarKeyScalar8RouteTargetKind.TerminalIdentityRoot,
            _ => VarKeyScalar8RouteTargetKind.None
        };
    }

    /// <summary>
    /// Converts a direct-router cached target kind into the `VS16` route target enum.<br/>
    /// Direct router views use a shared fixed-shape enum for cached target classification, while `VS16` keeps its own storage-facing target enum.<br/>
    /// </summary>
    /// <param name="kind">The cached shared direct-router target kind.</param>
    /// <returns>The equivalent `VS16` target kind, or `None` when no cached classification exists.</returns>
    private static VarKeyScalar16RouteTargetKind ToVarKeyScalar16RouteTargetKind(Scalar8Scalar8RouteTargetKind kind)
    {
        return kind switch
        {
            Scalar8Scalar8RouteTargetKind.Shelf => VarKeyScalar16RouteTargetKind.Shelf,
            Scalar8Scalar8RouteTargetKind.Router => VarKeyScalar16RouteTargetKind.Router,
            _ => VarKeyScalar16RouteTargetKind.None
        };
    }

    private static VarKeyScalar16RouteTargetKind ToVarKeyScalar16RouteTargetKind(PromotedRouteTargetKind kind)
    {
        return kind switch
        {
            PromotedRouteTargetKind.Shelf => VarKeyScalar16RouteTargetKind.Shelf,
            PromotedRouteTargetKind.Router => VarKeyScalar16RouteTargetKind.Router,
            _ => VarKeyScalar16RouteTargetKind.None
        };
    }

    /// <summary>
    /// Walks a batch of encoded `SS8-8` keys to classified route targets using one explicit route-read policy.<br/>
    /// This is the first locality-heavy operation that can opt into arena-aware reads while point lookups keep the conservative uncached default.<br/>
    /// Results are written into a caller-owned span so the operation does not allocate per routed key.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKeys">The encoded scalar keys whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow for each key before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply for router page and target classifier reads.</param>
    /// <param name="targets">The caller-owned span that receives one route target per encoded key.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="targets"/> is shorter than <paramref name="encodedKeys"/>.</exception>
    /// <exception cref="InvalidDataException">Thrown when any route is unset, invalid, or does not terminate at a known target.</exception>
    internal void WalkScalar8Scalar8RouteTargets(
        long rootRouterOffset,
        ReadOnlySpan<ulong> encodedKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<Scalar8Scalar8RouteTarget> targets)
    {
        if (targets.Length < encodedKeys.Length)
        {
            throw new ArgumentException("The target span must be at least as long as the encoded key span.", nameof(targets));
        }

        for (int i = 0; i < encodedKeys.Length; i++)
        {
            targets[i] = WalkScalar8Scalar8RouteTarget(rootRouterOffset, encodedKeys[i], maxRouterHops, readPolicy);
        }
    }

    /// <summary>
    /// Looks up the first encoded identity for each encoded `SS8-8` key through the routed shelf graph.<br/>
    /// Routing uses the supplied route-read policy, so locality-heavy callers can request arena-aware router reads while point lookup paths can keep the uncached default.<br/>
    /// The method uses caller-owned spans for targets, result identities, result flags, and the shelf read buffer; the library path does not allocate per key.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="encodedKeys">The encoded sortable keys to look up.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow for each key before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while walking routers and classifying targets.</param>
    /// <param name="encodedIdentities">The caller-owned span that receives the first encoded identity for each found key.</param>
    /// <param name="foundFlags">The caller-owned span that receives `1` for found keys and `0` for misses.</param>
    /// <param name="routeTargets">The caller-owned scratch span that receives route targets from the batched walker.</param>
    /// <param name="shelfBuffer">The caller-owned scratch buffer used for one shelf extent read at a time.</param>
    /// <exception cref="ArgumentException">Thrown when any caller-owned result or scratch span is too short, or when <paramref name="shelfBuffer"/> does not match the profile extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf.</exception>
    internal void LookupScalar8Scalar8Identities(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> foundFlags,
        Span<Scalar8Scalar8RouteTarget> routeTargets,
        Span<byte> shelfBuffer)
    {
        if (encodedIdentities.Length < encodedKeys.Length)
        {
            throw new ArgumentException("The identity result span must be at least as long as the encoded key span.", nameof(encodedIdentities));
        }

        if (foundFlags.Length < encodedKeys.Length)
        {
            throw new ArgumentException("The found-flag span must be at least as long as the encoded key span.", nameof(foundFlags));
        }

        if (routeTargets.Length < encodedKeys.Length)
        {
            throw new ArgumentException("The route-target scratch span must be at least as long as the encoded key span.", nameof(routeTargets));
        }

        if (shelfBuffer.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The shelf buffer length must match the profiled SS8-8 shelf extent size.", nameof(shelfBuffer));
        }

        WalkScalar8Scalar8RouteTargets(rootRouterOffset, encodedKeys, maxRouterHops, readPolicy, routeTargets);

        long loadedShelfOffset = 0;
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8RouteTarget target = routeTargets[i];
            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The batched lookup route walker did not terminate at an SS8-8 shelf.");
            }

            if (target.Offset != loadedShelfOffset)
            {
                kernel.Read(target.Offset, shelfBuffer);
                Scalar8Scalar8ReadOnly loadedShelf = new(shelfBuffer, profile);
                if (!loadedShelf.IsValid)
                {
                    throw new InvalidDataException("The batched lookup SS8-8 shelf bytes are invalid.");
                }

                loadedShelfOffset = target.Offset;
            }

            Scalar8Scalar8ReadOnly shelf = new(shelfBuffer, profile);
            if (shelf.TryFindFirstIdentity(encodedKeys[i], out ulong encodedIdentity))
            {
                encodedIdentities[i] = encodedIdentity;
                foundFlags[i] = 1;
            }
            else
            {
                encodedIdentities[i] = 0;
                foundFlags[i] = 0;
            }
        }
    }

    /// <summary>
    /// Scoops encoded identities for an inclusive `SS8-8` encoded key range that resolves to one routed shelf.<br/>
    /// The method routes both range boundaries with the supplied route-read policy, reads the reached shelf once, and copies matching identities into caller-owned output.<br/>
    /// This first range primitive intentionally rejects cross-shelf ranges until shelf continuation and multi-shelf scan semantics are defined.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow for each boundary before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while walking routers and classifying targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfBuffer">The caller-owned scratch buffer used for the single shelf extent read.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the range is invalid or <paramref name="shelfBuffer"/> does not match the profile extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf, or when the boundaries route to different shelves.</exception>
    internal int ScoopScalar8Scalar8IdentityRange(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> shelfBuffer)
    {
        if (upperEncodedKey < lowerEncodedKey)
        {
            throw new ArgumentException("The upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperEncodedKey));
        }

        if (shelfBuffer.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The shelf buffer length must match the profiled SS8-8 shelf extent size.", nameof(shelfBuffer));
        }

        if (GetScalar8Scalar8RootPrefix(lowerEncodedKey) != GetScalar8Scalar8RootPrefix(upperEncodedKey))
        {
            return ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversal(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                readPolicy,
                encodedIdentities,
                shelfBuffer);
        }

        Scalar8Scalar8RoutePathTarget lowerPath = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, lowerEncodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RoutePathTarget upperPath = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, upperEncodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget lowerTarget = lowerPath.Target;
        Scalar8Scalar8RouteTarget upperTarget = upperPath.Target;
        if (lowerEncodedKey == upperEncodedKey &&
            lowerTarget.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot &&
            upperTarget.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot &&
            lowerTarget.Offset == upperTarget.Offset)
        {
            return CopyScalar8Scalar8TerminalRootIdentitiesInRange(lowerTarget.Offset, profile, lowerEncodedKey, upperEncodedKey, encodedIdentities);
        }

        if (lowerTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || upperTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The routed SS8-8 range boundaries did not terminate at shelves.");
        }

        if (lowerTarget.Offset != upperTarget.Offset)
        {
            if (lowerPath.ParentRouterOffset == upperPath.ParentRouterOffset)
            {
                return ScoopScalar8Scalar8IdentityRangeAcrossParentRouter(
                    profile,
                    lowerEncodedKey,
                    upperEncodedKey,
                    lowerPath,
                    upperPath,
                    readPolicy,
                    encodedIdentities,
                    shelfBuffer);
            }

            return ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversal(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                readPolicy,
                encodedIdentities,
                shelfBuffer);
        }

        kernel.Read(lowerTarget.Offset, shelfBuffer);
        Scalar8Scalar8ReadOnly shelf = new(shelfBuffer, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 range shelf bytes are invalid.");
        }

        if (shelf.IsDuplicateRun)
        {
            return CopyScalar8Scalar8DuplicateRunChainIdentitiesInRange(
                lowerTarget.Offset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                encodedIdentities,
                shelfBuffer);
        }

        return shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities);
    }

    /// <summary>
    /// Copies identities from one routed `SS8-8` duplicate-run shelf chain when the duplicate key lies inside the requested encoded-key range.<br/>
    /// This keeps the optimized same-shelf range path consistent with router traversal, which already follows duplicate-run next-shelf links.<br/>
    /// The caller supplies the reusable shelf buffer so linked-chain reads do not allocate per shelf.<br/>
    /// </summary>
    /// <param name="headShelfOffset">The first duplicate-run shelf offset selected by routing.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length.<br/></param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.<br/></param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.<br/></param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching identities.<br/></param>
    /// <param name="shelfBuffer">The reusable caller-owned shelf buffer.<br/></param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the duplicate-run chain contains invalid or non-duplicate shelf bytes.<br/></exception>
    private int CopyScalar8Scalar8DuplicateRunChainIdentitiesInRange(
        long headShelfOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Span<ulong> encodedIdentities,
        Span<byte> shelfBuffer)
    {
        int copied = 0;
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            kernel.Read(currentOffset, shelfBuffer);
            Scalar8Scalar8ReadOnly shelf = new(shelfBuffer, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                throw new InvalidDataException("The routed SS8-8 duplicate-run chain contains invalid shelf bytes.");
            }

            copied += shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
            currentOffset = shelf.DuplicateRunNextOffset;
        }

        return copied;
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range using an explicit scratch and policy contract.<br/>
    /// The method is the first storage-facing range API shape: conservative reads require only one shelf buffer, while coalesced reads use a separate caller-owned range buffer when supplied and enabled.<br/>
    /// No heap allocation or pooled fallback is hidden in this method; callers must make scratch capacity an explicit part of the operation shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="options">The range-read policy knobs for routing and coalescing.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="scratch">The caller-owned scratch buffers used by the selected range-read path.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the range is invalid or the required shelf scratch length does not match the profile.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-8` shelves.</exception>
    internal int ReadScalar8Scalar8IdentityRange(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities,
        Scalar8Scalar8RangeReadScratch scratch)
    {
        options.Validate();
        if (scratch.Shelf.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The shelf scratch length must match the profiled SS8-8 shelf extent size.", nameof(scratch));
        }

        if (!options.EnableCoalescing || scratch.Range.Length < profile.ShelfExtentSize)
        {
            return ScoopScalar8Scalar8IdentityRange(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                options.RouteReadPolicy,
                encodedIdentities,
                scratch.Shelf);
        }

        return ScoopScalar8Scalar8IdentityRangeCoalesced(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            maxRouterHops,
            options.RouteReadPolicy,
            encodedIdentities,
            scratch.Range,
            options.MinimumRootPrefixSpanForTraversalCoalescing);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range using caller-owned scratch and the session default route-hop guard.<br/>
    /// This is the first outer encoded range method shape: callers still provide root/profile/index context and scratch, but they receive a named result contract instead of a bare count and do not manage low-level route-hop plumbing.<br/>
    /// The method intentionally remains encoded-only; developer-facing codecs and catalog handles belong in a later layer.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="options">The range-read policy knobs for routing and coalescing.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="scratch">The caller-owned scratch buffers used by the selected range-read path.</param>
    /// <returns>A result describing the copied identity count and scratch/coalescing shape.</returns>
    /// <exception cref="ArgumentException">Thrown when the range is invalid or the required shelf scratch length does not match the profile.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-8` shelves.</exception>
    internal Scalar8Scalar8RangeReadResult ReadEncodedScalar8Scalar8IdentityRange(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities,
        Scalar8Scalar8RangeReadScratch scratch)
    {
        int identityCount = ReadScalar8Scalar8IdentityRange(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            DefaultScalar8Scalar8MaxRouterHops,
            options,
            encodedIdentities,
            scratch);
        int rangeScratchShelfCapacity = scratch.Range.Length / profile.ShelfExtentSize;
        return new Scalar8Scalar8RangeReadResult(
            identityCount,
            UsedPooledScratch: false,
            options.EnableCoalescing,
            rangeScratchShelfCapacity);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range through a runtime index handle and caller-owned scratch.<br/>
    /// This overload is the first step from storage primitives toward index/session APIs: callers pass one handle instead of separately carrying the root router offset and shelf profile.<br/>
    /// The method still remains encoded-only and allocation-free when the supplied scratch is reused by the caller.<br/>
    /// </summary>
    /// <param name="index">The runtime `SS8-8` index handle containing root-router offset and shelf profile.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="options">The range-read policy knobs for routing and coalescing.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="scratch">The caller-owned scratch buffers used by the selected range-read path.</param>
    /// <returns>A result describing the copied identity count and scratch/coalescing shape.</returns>
    /// <exception cref="InvalidDataException">Thrown when the handle or routed target data is invalid.</exception>
    internal Scalar8Scalar8RangeReadResult ReadEncodedScalar8Scalar8IdentityRange(
        Scalar8Scalar8IndexHandle index,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities,
        Scalar8Scalar8RangeReadScratch scratch)
    {
        index.Validate();
        return ReadEncodedScalar8Scalar8IdentityRange(
            index.RootRouterOffset,
            index.Profile,
            lowerEncodedKey,
            upperEncodedKey,
            options,
            encodedIdentities,
            scratch);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range using pooled scratch owned by the call.<br/>
    /// This is the low-friction wrapper over the explicit scratch API: it rents temporary byte buffers from `ArrayPool&lt;byte&gt;.Shared`, performs the same range read, and returns the buffers before exiting.<br/>
    /// Hot callers should prefer <see cref="ReadScalar8Scalar8IdentityRange(long, Scalar8Scalar8Profile, ulong, ulong, int, Scalar8Scalar8RangeReadOptions, Span{ulong}, Scalar8Scalar8RangeReadScratch)"/> so scratch lifetime and capacity remain under caller control.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="options">The range-read policy knobs for routing, coalescing, and pooled scratch capacity.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when a policy value is outside the supported range.</exception>
    /// <exception cref="ArgumentException">Thrown when the encoded key range is invalid.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-8` shelves.</exception>
    internal int ReadScalar8Scalar8IdentityRangePooled(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities)
    {
        options.Validate();
        int shelfExtentSize = profile.ShelfExtentSize;
        int rangeScratchLength = options.EnableCoalescing
            ? checked(shelfExtentSize * options.CoalescedShelfScratchCount)
            : 0;

        byte[] shelfBuffer = ArrayPool<byte>.Shared.Rent(shelfExtentSize);
        byte[]? rangeBuffer = rangeScratchLength == 0
            ? null
            : ArrayPool<byte>.Shared.Rent(rangeScratchLength);
        try
        {
            Span<byte> shelfScratch = shelfBuffer.AsSpan(0, shelfExtentSize);
            Span<byte> rangeScratch = rangeBuffer is null
                ? Span<byte>.Empty
                : rangeBuffer.AsSpan(0, rangeScratchLength);
            Scalar8Scalar8RangeReadScratch scratch = new(shelfScratch, rangeScratch);
            return ReadScalar8Scalar8IdentityRange(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                options,
                encodedIdentities,
                scratch);
        }
        finally
        {
            if (rangeBuffer is not null)
            {
                ArrayPool<byte>.Shared.Return(rangeBuffer);
            }

            ArrayPool<byte>.Shared.Return(shelfBuffer);
        }
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range using pooled scratch and the session default route-hop guard.<br/>
    /// This is the low-friction counterpart to <see cref="ReadEncodedScalar8Scalar8IdentityRange(long, Scalar8Scalar8Profile, ulong, ulong, Scalar8Scalar8RangeReadOptions, Span{ulong}, Scalar8Scalar8RangeReadScratch)"/> and should be treated as a convenience path in perf analysis.<br/>
    /// The method remains encoded-only so the first outer API does not mix codec design into the storage/range-read layer.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="options">The range-read policy knobs for routing, coalescing, and pooled scratch capacity.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <returns>A result describing the copied identity count and scratch/coalescing shape.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when a policy value is outside the supported range.</exception>
    /// <exception cref="ArgumentException">Thrown when the encoded key range is invalid.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-8` shelves.</exception>
    internal Scalar8Scalar8RangeReadResult ReadEncodedScalar8Scalar8IdentityRangePooled(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities)
    {
        int identityCount = ReadScalar8Scalar8IdentityRangePooled(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            DefaultScalar8Scalar8MaxRouterHops,
            options,
            encodedIdentities);
        int rangeScratchShelfCapacity = options.EnableCoalescing
            ? options.CoalescedShelfScratchCount
            : 0;
        return new Scalar8Scalar8RangeReadResult(
            identityCount,
            UsedPooledScratch: true,
            options.EnableCoalescing,
            rangeScratchShelfCapacity);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS8-8` encoded key range through a runtime index handle using pooled scratch.<br/>
    /// This is the low-friction counterpart to the handle-based explicit scratch overload and should be treated as a convenience path in perf analysis.<br/>
    /// The handle avoids repeated root/profile parameter plumbing while keeping encoded-key and identity spans explicit.<br/>
    /// </summary>
    /// <param name="index">The runtime `SS8-8` index handle containing root-router offset and shelf profile.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="options">The range-read policy knobs for routing, coalescing, and pooled scratch capacity.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <returns>A result describing the copied identity count and scratch/coalescing shape.</returns>
    /// <exception cref="InvalidDataException">Thrown when the handle or routed target data is invalid.</exception>
    internal Scalar8Scalar8RangeReadResult ReadEncodedScalar8Scalar8IdentityRangePooled(
        Scalar8Scalar8IndexHandle index,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RangeReadOptions options,
        Span<ulong> encodedIdentities)
    {
        index.Validate();
        return ReadEncodedScalar8Scalar8IdentityRangePooled(
            index.RootRouterOffset,
            index.Profile,
            lowerEncodedKey,
            upperEncodedKey,
            options,
            encodedIdentities);
    }

    /// <summary>
    /// Scoops an inclusive encoded key range using a caller-owned multi-shelf scratch buffer for contiguous shelf coalescing when the route shape justifies it.<br/>
    /// The method keeps the normal range-scoop contract but can collapse adjacent shelf extent reads into one larger sequential read when the route interval targets shelves stored back-to-back.<br/>
    /// Same-parent shelf spans are coalesced directly; small mixed-router traversal falls back to the normal one-shelf path because current evidence shows the extra classifier/routing work can outweigh the coalesced read win.<br/>
    /// If the supplied scratch buffer cannot hold at least one profiled shelf extent, the method fails fast because hidden allocation would violate the hot-path ownership contract.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while walking routers and classifying targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the range is invalid or <paramref name="rangeScratch"/> cannot hold one shelf extent.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-8` shelves.</exception>
    internal int ScoopScalar8Scalar8IdentityRangeCoalesced(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch)
    {
        return ScoopScalar8Scalar8IdentityRangeCoalesced(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            maxRouterHops,
            readPolicy,
            encodedIdentities,
            rangeScratch,
            Scalar8Scalar8RangeReadOptions.CoalescingCached.MinimumRootPrefixSpanForTraversalCoalescing);
    }

    /// <summary>
    /// Scoops an inclusive encoded key range using caller-owned range scratch and an explicit generalized traversal coalescing gate.<br/>
    /// This overload exists so the first range API shape can keep coalescing thresholds as policy values instead of private hot-path constants.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while walking routers and classifying targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <param name="minimumRootPrefixSpanForTraversalCoalescing">The minimum inclusive root-prefix width before generalized traversal coalescing is considered.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    private int ScoopScalar8Scalar8IdentityRangeCoalesced(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch,
        int minimumRootPrefixSpanForTraversalCoalescing)
    {
        if (upperEncodedKey < lowerEncodedKey)
        {
            throw new ArgumentException("The upper encoded key must be greater than or equal to the lower encoded key.", nameof(upperEncodedKey));
        }

        if (rangeScratch.Length < profile.ShelfExtentSize)
        {
            throw new ArgumentException("The range scratch buffer must hold at least one profiled SS8-8 shelf extent.", nameof(rangeScratch));
        }

        byte lowerRootPrefix = GetScalar8Scalar8RootPrefix(lowerEncodedKey);
        byte upperRootPrefix = GetScalar8Scalar8RootPrefix(upperEncodedKey);
        if (lowerRootPrefix != upperRootPrefix)
        {
            int rootPrefixSpan = upperRootPrefix - lowerRootPrefix + 1;
            if (rootPrefixSpan < minimumRootPrefixSpanForTraversalCoalescing)
            {
                return ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversal(
                    rootRouterOffset,
                    profile,
                    lowerEncodedKey,
                    upperEncodedKey,
                    maxRouterHops,
                    readPolicy,
                    encodedIdentities,
                    rangeScratch[..profile.ShelfExtentSize]);
            }

            return ScoopScalar8Scalar8IdentityRangeFromRootPrefixSpanCoalesced(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                lowerRootPrefix,
                upperRootPrefix,
                maxRouterHops,
                readPolicy,
                encodedIdentities,
                rangeScratch);
        }

        Scalar8Scalar8RoutePathTarget lowerPath = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, lowerEncodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RoutePathTarget upperPath = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, upperEncodedKey, maxRouterHops, readPolicy);
        if (lowerPath.Target.Kind != Scalar8Scalar8RouteTargetKind.Shelf || upperPath.Target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The coalesced SS8-8 range boundaries did not terminate at shelves.");
        }

        if (lowerPath.Target.Offset == upperPath.Target.Offset)
        {
            kernel.Read(lowerPath.Target.Offset, rangeScratch[..profile.ShelfExtentSize]);
            Scalar8Scalar8ReadOnly shelf = new(rangeScratch[..profile.ShelfExtentSize], profile);
            if (!shelf.IsValid)
            {
                throw new InvalidDataException("The coalesced single-shelf SS8-8 range bytes are invalid.");
            }

            return shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities);
        }

        if (lowerPath.ParentRouterOffset != upperPath.ParentRouterOffset)
        {
            return ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversal(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                readPolicy,
                encodedIdentities,
                rangeScratch[..profile.ShelfExtentSize]);
        }

        return ScoopScalar8Scalar8IdentityRangeAcrossParentRouterCoalesced(
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            lowerPath,
            upperPath,
            readPolicy,
            encodedIdentities,
            rangeScratch);
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-8` key and records the parent router route that produced the final shelf target.<br/>
    /// The extra parent-route information lets range scoop enumerate adjacent route targets from the same parent router without requiring a shelf sibling pointer.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded scalar key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply for router page and target classifier reads.</param>
    /// <returns>The classified shelf target plus its parent router offset and selected route prefix.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, invalid, does not terminate at a shelf, or the policy is unsupported.</exception>
    internal Scalar8Scalar8RoutePathTarget WalkScalar8Scalar8RoutePathTarget(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        DirectRouterView? currentDirectView = null;
        byte[]? routerBytes = null;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            DirectRouterView? directView = currentDirectView;
            currentDirectView = null;
            if (directView is not null || TryGetDirectRouterView(routerOffset, out directView))
            {
                byte directPrefixByte = GetScalar8Scalar8Prefix(encodedKey, directView!.KeyDepth);
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                if (directTargetOffset == 0)
                {
                    Scalar8Scalar8RouteTarget target = new(Scalar8Scalar8RouteTargetKind.None, 0, directView.KeyDepth, directView.AllocationClassId);
                    return new Scalar8Scalar8RoutePathTarget(target, routerOffset, directPrefixByte);
                }

                Scalar8Scalar8RouteTargetKind directKind = ResolveDirectRouteTargetKind(directView, directPrefixByte, directTargetOffset, readPolicy);
                if (directKind == Scalar8Scalar8RouteTargetKind.Shelf ||
                    directKind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
                {
                    Scalar8Scalar8RouteTarget target = new(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId);
                    return new Scalar8Scalar8RoutePathTarget(target, routerOffset, directPrefixByte);
                }

                if (directKind == Scalar8Scalar8RouteTargetKind.Router)
                {
                    uint childRamOffset = directView.GetTargetRouterRamOffset(directPrefixByte);
                    if (childRamOffset != 0 && TryGetPromotedRouterView(childRamOffset, out DirectRouterView? childView))
                    {
                        currentDirectView = childView;
                    }

                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed target is not a shelf, terminal identity root, or router.");
            }

            ReadScalar8Scalar8RouterForPolicy(routerOffset, readPolicy, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar8Scalar8Prefix(encodedKey, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                Scalar8Scalar8RouteTarget target = new(Scalar8Scalar8RouteTargetKind.None, 0, reader.KeyDepth, reader.AllocationClassId);
                return new Scalar8Scalar8RoutePathTarget(target, routerOffset, prefixByte);
            }

            Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
            if (kind == Scalar8Scalar8RouteTargetKind.Shelf ||
                kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                Scalar8Scalar8RouteTarget target = new(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId);
                return new Scalar8Scalar8RoutePathTarget(target, routerOffset, prefixByte);
            }

            if (kind == Scalar8Scalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed target is not a shelf, terminal identity root, or router.");
        }

        throw new InvalidDataException("The routed target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-8` key while attributing the internal route-walk operations.<br/>
    /// This diagnostic path mirrors <see cref="WalkScalar8Scalar8RoutePathTarget(long, ulong, int, Scalar8Scalar8RouteReadPolicy)"/> but separates direct-view lookup, prefix extraction, slot load, router reads, and target classification costs.<br/>
    /// Normal insert paths should use the non-attributed walker so Stopwatch probes do not affect production routing.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded scalar key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply for router page and target classifier reads.</param>
    /// <param name="telemetry">The route-walk attribution counters to update.</param>
    /// <returns>The classified shelf target plus its parent router offset and selected route prefix.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, invalid, does not terminate at a shelf, or the policy is unsupported.</exception>
    internal Scalar8Scalar8RoutePathTarget WalkScalar8Scalar8RoutePathTargetWithAttribution(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        ref Scalar8Scalar8RouteWalkAttributionTelemetry telemetry)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        DirectRouterView? currentDirectView = null;
        byte[]? routerBytes = null;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            DirectRouterView? directView = currentDirectView;
            currentDirectView = null;
            if (directView is null)
            {
                long directViewLookupStart = System.Diagnostics.Stopwatch.GetTimestamp();
                bool hasDirectView = TryGetDirectRouterView(routerOffset, out directView);
                telemetry.DirectViewLookupTicks += System.Diagnostics.Stopwatch.GetTimestamp() - directViewLookupStart;
                if (!hasDirectView)
                {
                    routerBytes ??= new byte[RouterLayout.Size];
                    long routerReadStart = System.Diagnostics.Stopwatch.GetTimestamp();
                    ReadScalar8Scalar8RouterForPolicy(routerOffset, readPolicy, routerBytes);
                    RouterReader reader = new(routerBytes);
                    if (!reader.IsValid)
                    {
                        throw new InvalidDataException("The routed page is not a valid router.");
                    }

                    telemetry.NonDirectRouterReadTicks += System.Diagnostics.Stopwatch.GetTimestamp() - routerReadStart;

                    long prefixByteStart = System.Diagnostics.Stopwatch.GetTimestamp();
                    byte prefixByte = GetScalar8Scalar8Prefix(encodedKey, reader.KeyDepth);
                    telemetry.NonDirectPrefixTicks += System.Diagnostics.Stopwatch.GetTimestamp() - prefixByteStart;

                    long routeLookupStart = System.Diagnostics.Stopwatch.GetTimestamp();
                    long targetOffset = reader.FindTarget(prefixByte);
                    telemetry.NonDirectRouteLookupTicks += System.Diagnostics.Stopwatch.GetTimestamp() - routeLookupStart;
                    if (targetOffset == 0)
                    {
                        throw new InvalidDataException("The routed target is unset.");
                    }

                    long targetClassificationStart = System.Diagnostics.Stopwatch.GetTimestamp();
                    Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
                    telemetry.NonDirectTargetClassificationTicks += System.Diagnostics.Stopwatch.GetTimestamp() - targetClassificationStart;
                    if (kind == Scalar8Scalar8RouteTargetKind.Shelf ||
                        kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
                    {
                        telemetry.NonDirectShelfTargetCount++;
                        Scalar8Scalar8RouteTarget target = new(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId);
                        return new Scalar8Scalar8RoutePathTarget(target, routerOffset, prefixByte);
                    }

                    if (kind == Scalar8Scalar8RouteTargetKind.Router)
                    {
                        telemetry.NonDirectRouterTargetCount++;
                        routerOffset = targetOffset;
                        continue;
                    }

                    throw new InvalidDataException("The routed target is not a shelf, terminal identity root, or router.");
                }
            }

            if (directView is not null)
            {
                long prefixStart = System.Diagnostics.Stopwatch.GetTimestamp();
                byte directPrefixByte = GetScalar8Scalar8Prefix(encodedKey, directView!.KeyDepth);
                telemetry.DirectPrefixTicks += System.Diagnostics.Stopwatch.GetTimestamp() - prefixStart;

                long slotLoadStart = System.Diagnostics.Stopwatch.GetTimestamp();
                long directTargetOffset = directView.GetTarget(directPrefixByte);
                telemetry.DirectSlotLoadTicks += System.Diagnostics.Stopwatch.GetTimestamp() - slotLoadStart;
                if (directTargetOffset == 0)
                {
                    throw new InvalidDataException("The routed target is unset.");
                }

                long classificationStart = System.Diagnostics.Stopwatch.GetTimestamp();
                Scalar8Scalar8RouteTargetKind directKind = ResolveDirectRouteTargetKind(directView, directPrefixByte, directTargetOffset, readPolicy);
                telemetry.DirectTargetClassificationTicks += System.Diagnostics.Stopwatch.GetTimestamp() - classificationStart;
                if (directKind == Scalar8Scalar8RouteTargetKind.Shelf ||
                    directKind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
                {
                    telemetry.DirectShelfTargetCount++;
                    Scalar8Scalar8RouteTarget target = new(directKind, directTargetOffset, directView.KeyDepth, directView.AllocationClassId);
                    return new Scalar8Scalar8RoutePathTarget(target, routerOffset, directPrefixByte);
                }

                if (directKind == Scalar8Scalar8RouteTargetKind.Router)
                {
                    telemetry.DirectRouterTargetCount++;
                    uint childRamOffset = directView.GetTargetRouterRamOffset(directPrefixByte);
                    if (childRamOffset != 0 && TryGetPromotedRouterView(childRamOffset, out DirectRouterView? childView))
                    {
                        currentDirectView = childView;
                    }

                    routerOffset = directTargetOffset;
                    continue;
                }

                throw new InvalidDataException("The routed target is not a shelf, terminal identity root, or router.");
            }
        }

        throw new InvalidDataException("The routed target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Reads and validates one full `SS8-8` shelf extent for a batch-local mutation cache.<br/>
    /// During an active durability batch this is the pending writer view: an existing dirty shelf image is returned before committed backing bytes.<br/>
    /// Dirty images are normalized before reuse by default so writer-side search/insert code can keep using ordinary compact shelf algorithms.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to read.</param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.</param>
    /// <param name="normalizePendingBeforeReturn">Whether an existing dirty image should be normalized before it is returned for writer-side search or insertion.</param>
    /// <returns>A mutable byte array containing the current shelf image.</returns>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="shelfOffset"/> are not a valid `SS8-8` shelf.</exception>
    internal byte[] ReadScalar8Scalar8ShelfBytesForBatch(long shelfOffset, Scalar8Scalar8Profile profile, bool normalizePendingBeforeReturn = true)
    {
        Dictionary<long, byte[]> mutableShelfBytes = GetScalar8Scalar8MutableBatchShelfBytes();
        if (durabilityBatchActive &&
            mutableShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            if (normalizePendingBeforeReturn)
            {
                Scalar8Scalar8 shelf = new(dirtyShelfBytes, profile);
                _ = shelf.NormalizeDeletedSlotsForPublication();
            }

            return dirtyShelfBytes;
        }

        if (scalar8Scalar8CleanShelfCache.Remove(shelfOffset, out byte[]? cachedShelfBytes))
        {
            Scalar8Scalar8ReadOnly cachedReadOnly = new(cachedShelfBytes, profile);
            if (!cachedReadOnly.IsValid)
            {
                throw new InvalidDataException("The session-local SS8-8 clean shelf cache contained invalid shelf bytes.");
            }

            return cachedShelfBytes;
        }

        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local SS8-8 shelf cache read invalid shelf bytes.");
        }

        return shelfBytes;
    }

    /// <summary>
    /// Gets a batch-owned mutable `SS8-8` shelf image and registers it as dirty for the active durability batch.<br/>
    /// Normal shared-batch scalar inserts use this to mutate one shelf buffer in place instead of allocating an existing image, a rewritten image, and a staged rewrite image for every inserted tuple.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to read or reuse.</param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.</param>
    /// <returns>A mutable shelf byte array owned by the active batch when batching is enabled; otherwise a standalone shelf read buffer.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target shelf bytes are invalid.</exception>
    internal byte[] GetOrCreateScalar8Scalar8MutableShelfBytesForBatch(long shelfOffset, Scalar8Scalar8Profile profile)
    {
        if (!durabilityBatchActive)
        {
            return ReadScalar8Scalar8ShelfBytesForBatch(shelfOffset, profile);
        }

        Dictionary<long, byte[]> mutableShelfBytes = GetScalar8Scalar8MutableBatchShelfBytes();
        if (mutableShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            Scalar8Scalar8 shelf = new(dirtyShelfBytes, profile);
            _ = shelf.NormalizeDeletedSlotsForPublication();
            return dirtyShelfBytes;
        }

        byte[] shelfBytes;
        if (scalar8Scalar8CleanShelfCache.Remove(shelfOffset, out byte[]? cachedShelfBytes))
        {
            shelfBytes = cachedShelfBytes;
        }
        else
        {
            shelfBytes = new byte[profile.ShelfExtentSize];
            kernel.Read(shelfOffset, shelfBytes);
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local SS8-8 mutable shelf cache read invalid shelf bytes.");
        }

        mutableShelfBytes[shelfOffset] = shelfBytes;
        return shelfBytes;
    }

    /// <summary>
    /// Records that an already registered batch-owned `SS8-8` shelf image was changed in place.<br/>
    /// The dirty shelf bytes are published by the active durability batch commit, so this method only folds the logical commit request into the batch boundary.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset registered in the active mutable shelf map.</param>
    /// <param name="profile">The `SS8-8` profile used to validate the changed shelf image.</param>
    /// <param name="shelfBytes">The changed batch-owned shelf bytes.</param>
    /// <returns>Default telemetry while the durability request is deferred into the active batch.</returns>
    /// <exception cref="InvalidOperationException">Thrown when no durability batch is active or the shelf is not registered.</exception>
    /// <exception cref="InvalidDataException">Thrown when the changed shelf image is invalid.</exception>
    internal DataKernelCommitTelemetry MarkScalar8Scalar8MutableShelfChangedForBatch(long shelfOffset, Scalar8Scalar8Profile profile, byte[] shelfBytes)
    {
        if (!durabilityBatchActive)
        {
            throw new InvalidOperationException("SS8-8 mutable shelf change marking requires an active durability batch.");
        }

        Dictionary<long, byte[]> mutableShelfBytes = GetScalar8Scalar8MutableBatchShelfBytes();
        if (!mutableShelfBytes.TryGetValue(shelfOffset, out byte[]? registeredShelfBytes) ||
            !ReferenceEquals(registeredShelfBytes, shelfBytes))
        {
            throw new InvalidOperationException("The changed SS8-8 shelf bytes are not registered with the active durability batch.");
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local SS8-8 shelf cache attempted to mark invalid shelf bytes as dirty.");
        }

        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Removes a batch-local dirty `SS8-8` shelf image when that offset is structurally rewritten outside the dirty-shelf flush path.<br/>
    /// A routed split can reuse a former shelf offset as a router or can stage replacement shelf bytes directly; keeping the old dirty image would let the batch publisher overwrite the newer structure with stale shelf bytes.<br/>
    /// This method is intentionally a no-op outside durability batching so non-batched writes keep their direct commit behavior unchanged.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset whose dirty batch image must no longer be published.</param>
    private void DiscardScalar8Scalar8MutableBatchShelfBytes(long shelfOffset)
    {
        if (durabilityBatchActive)
        {
            GetScalar8Scalar8MutableBatchShelfBytes().Remove(shelfOffset);
        }
    }

    /// <summary>
    /// Reads the persisted extent size from a `VS8` shelf header for validation and cold-optimizer accounting.<br/>
    /// The method validates only the fixed header identity because callers use the value to account for reachable storage, not to expose shelf contents.<br/>
    /// This is deliberately outside the hot insert/read paths and should remain a diagnostic/cold-planning primitive.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset where the `VS8` shelf starts.</param>
    /// <returns>The persisted shelf extent size in bytes.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a valid `VS8` shelf header.</exception>
    internal int ReadVarKeyScalar8ShelfExtentSizeForValidation(long shelfOffset)
    {
        byte[] header = new byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The VS8 shelf header is invalid.");
        }

        return VarKeyScalar8Layout.ReadShelfExtentSize(header);
    }

    /// <summary>
    /// Reads the persisted extent size from a `VS16` shelf header for validation and cold-optimizer accounting.<br/>
    /// The method validates only the fixed header identity because callers use the value to account for reachable storage, not to expose shelf contents.<br/>
    /// This is deliberately outside the hot insert/read paths and should remain a diagnostic/cold-planning primitive.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset where the `VS16` shelf starts.</param>
    /// <returns>The persisted shelf extent size in bytes.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a valid `VS16` shelf header.</exception>
    internal int ReadVarKeyScalar16ShelfExtentSizeForValidation(long shelfOffset)
    {
        byte[] header = new byte[VarKeyScalar16Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar16Layout.ReadMagic(header) != VarKeyScalar16Layout.Magic ||
            VarKeyScalar16Layout.ReadFormatVersion(header) != VarKeyScalar16Layout.FormatVersion ||
            VarKeyScalar16Layout.ReadHeaderSize(header) != VarKeyScalar16Layout.HeaderSize)
        {
            throw new InvalidDataException("The VS16 shelf header is invalid.");
        }

        return VarKeyScalar16Layout.ReadShelfExtentSize(header);
    }

    /// <summary>
    /// Stores one clean `SS8-8` shelf image for reuse by a later batch in the same session.<br/>
    /// The image must represent bytes already published through a successful commit; the cache is a performance hint and never the durable source of truth.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset used as the cache key.</param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.</param>
    /// <param name="shelfBytes">The clean shelf image to keep for a later batch.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="shelfBytes"/> does not match the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> is not a valid `SS8-8` shelf image.</exception>
    internal void StoreScalar8Scalar8CleanShelfBytesForBatch(long shelfOffset, Scalar8Scalar8Profile profile, byte[] shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The session-local SS8-8 clean shelf cache image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The session-local SS8-8 clean shelf cache attempted to store invalid shelf bytes.");
        }

        scalar8Scalar8CleanShelfCache[shelfOffset] = shelfBytes;
    }

    /// <summary>
    /// Stages one full `SS8-8` shelf rewrite for a batch-local mutation cache.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to rewrite.</param>
    /// <param name="profile">The `SS8-8` profile that determines the expected shelf extent size.</param>
    /// <param name="shelfBytes">The final shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentException">Thrown when the shelf byte span does not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> does not contain a valid `SS8-8` shelf.</exception>
    internal DataKernelCommitTelemetry StageScalar8Scalar8ShelfRewriteForBatch(
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The batch-local SS8-8 shelf rewrite bytes must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local SS8-8 shelf cache attempted to stage invalid shelf bytes.");
        }

        if (durabilityBatchActive)
        {
            GetScalar8Scalar8MutableBatchShelfBytes()[shelfOffset] = shelfBytes.ToArray();
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        shelfBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Stages one partial `SS8-8` shelf rewrite for a batch-local mutation cache.<br/>
    /// The caller owns full-shelf validation and only passes byte ranges whose contents were changed by cached shelf mutation.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent that owns the slice.</param>
    /// <param name="profile">The `SS8-8` profile that determines valid shelf bounds.</param>
    /// <param name="sliceOffset">The byte offset inside the shelf extent where the slice begins.</param>
    /// <param name="sliceBytes">The changed shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slice is outside the profiled shelf extent.</exception>
    internal DataKernelCommitTelemetry StageScalar8Scalar8ShelfSliceRewriteForBatch(
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        int sliceOffset,
        ReadOnlySpan<byte> sliceBytes)
    {
        if (sliceOffset < 0 || sliceOffset > profile.ShelfExtentSize || sliceBytes.Length > profile.ShelfExtentSize - sliceOffset)
        {
            throw new ArgumentOutOfRangeException(nameof(sliceOffset), sliceOffset, "The batch-local SS8-8 shelf slice must fit inside the profiled shelf extent.");
        }

        if (sliceBytes.Length == 0)
        {
            return default;
        }

        if (durabilityBatchActive)
        {
            Dictionary<long, byte[]> mutableShelfBytes = GetScalar8Scalar8MutableBatchShelfBytes();
            if (!mutableShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
            {
                dirtyShelfBytes = new byte[profile.ShelfExtentSize];
                kernel.Read(shelfOffset, dirtyShelfBytes);
                mutableShelfBytes[shelfOffset] = dirtyShelfBytes;
            }

            sliceBytes.CopyTo(dirtyShelfBytes.AsSpan(sliceOffset, sliceBytes.Length));
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset + sliceOffset, sliceBytes.Length);
        sliceBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Reads and validates one full `SS16-8` shelf extent for a batch-local mutation cache.<br/>
    /// During an active durability batch this is the pending writer view: an existing dirty shelf image is returned before committed backing bytes.<br/>
    /// Dirty images are normalized before reuse by default so writer-side search/insert code can keep using ordinary compact shelf algorithms.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to read.</param>
    /// <param name="profile">The `SS16-8` profile that determines the shelf extent size.</param>
    /// <param name="normalizePendingBeforeReturn">Whether an existing dirty image should be normalized before it is returned for writer-side search or insertion.</param>
    /// <returns>A mutable byte array containing the current shelf image.</returns>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="shelfOffset"/> are not a valid `SS16-8` shelf.</exception>
