    /// <param name="shelfOffset">The offset of the shelf extent that owns the slice.</param>
    /// <param name="profile">The `FS32-8` profile that determines valid shelf bounds.</param>
    /// <param name="sliceOffset">The byte offset inside the shelf extent where the slice begins.</param>
    /// <param name="sliceBytes">The changed shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slice is outside the profiled shelf extent.</exception>
    internal DataKernelCommitTelemetry StageFixed32Scalar8ShelfSliceRewriteForBatch(
        long shelfOffset,
        Fixed32Scalar8Profile profile,
        int sliceOffset,
        ReadOnlySpan<byte> sliceBytes)
    {
        if (sliceOffset < 0 || sliceOffset > profile.ShelfExtentSize || sliceBytes.Length > profile.ShelfExtentSize - sliceOffset)
        {
            throw new ArgumentOutOfRangeException(nameof(sliceOffset), sliceOffset, "The batch-local FS32-8 shelf slice must fit inside the profiled shelf extent.");
        }

        if (sliceBytes.Length == 0)
        {
            return default;
        }

        if (durabilityBatchActive)
        {
            if (!fixed32Scalar8MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
            {
                dirtyShelfBytes = new byte[profile.ShelfExtentSize];
                kernel.Read(shelfOffset, dirtyShelfBytes);
                fixed32Scalar8MutableBatchShelfBytes[shelfOffset] = dirtyShelfBytes;
            }

            sliceBytes.CopyTo(dirtyShelfBytes.AsSpan(sliceOffset, sliceBytes.Length));
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset + sliceOffset, sliceBytes.Length);
        sliceBytes.CopyTo(rewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitWithoutInvalidatingRouterReadCache();
        fixed32Scalar8ReadCache.Remove(shelfOffset);
        return telemetry;
    }

    /// <summary>
    /// Stages one `FS32-8` slice directly from a batch-retained final shelf image.<br/>
    /// Unlike the general slice API, this path does not rehydrate a second mutable 40 KiB shelf because the owning public batch guarantees no further access after prepare begins.<br/>
    /// </summary>
    /// <param name="shelfOffset">The physical shelf extent offset.<br/></param>
    /// <param name="profile">The active `FS32-8` shelf profile.<br/></param>
    /// <param name="sliceOffset">The changed byte offset inside the shelf extent.<br/></param>
    /// <param name="shelfBytes">The batch-owned final shelf image borrowed through publication.<br/></param>
    /// <param name="sliceLength">The number of final shelf bytes to publish from <paramref name="sliceOffset"/>.<br/></param>
    /// <returns>Default telemetry while the active durability batch defers publication.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when no durability batch owns the retained image.<br/></exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slice lies outside the shelf extent.<br/></exception>
    internal DataKernelCommitTelemetry StageFixed32Scalar8RetainedShelfSliceRewriteForBatch(
        long shelfOffset,
        Fixed32Scalar8Profile profile,
        int sliceOffset,
        byte[] shelfBytes,
        int sliceLength)
    {
        if (!durabilityBatchActive)
        {
            throw new InvalidOperationException("An FS32-8 retained shelf slice requires an active durability batch.");
        }

        if (sliceOffset < 0 || sliceLength < 0 || sliceOffset > profile.ShelfExtentSize || sliceLength > profile.ShelfExtentSize - sliceOffset || shelfBytes.Length < profile.ShelfExtentSize)
        {
            throw new ArgumentOutOfRangeException(nameof(sliceOffset), sliceOffset, "The retained FS32-8 shelf slice must fit inside the profiled shelf extent.");
        }

        if (sliceLength == 0)
        {
            return default;
        }

        fixed32Scalar8RetainedBatchShelfOffsets.Add(shelfOffset);
        kernel.StageBorrowedAt(shelfOffset + sliceOffset, shelfBytes, sliceOffset, sliceLength);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Resolves a publication-safe `FS32-8` route hint retained for one root router.<br/>
    /// Structural cache invalidation clears these hints, while successful public batch completion stores the final path after publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The fixed index root router offset.<br/></param>
    /// <param name="key0">The first encoded fixed-key lane.<br/></param>
    /// <param name="key1">The second encoded fixed-key lane.<br/></param>
    /// <param name="key2">The third encoded fixed-key lane.<br/></param>
    /// <param name="key3">The fourth encoded fixed-key lane.<br/></param>
    /// <param name="pathTarget">The retained current path when its routed prefix matches.<br/></param>
    /// <returns><see langword="true"/> when a current matching route hint exists.<br/></returns>
    internal bool TryGetFixed32Scalar8BatchRouteHint(long rootRouterOffset, ulong key0, ulong key1, ulong key2, ulong key3, out Fixed32Scalar8RoutePathTarget pathTarget)
    {
        lock (routerReadCacheSync)
        {
            if (fixed32Scalar8BatchRouteHints.TryGetValue(rootRouterOffset, out Fixed32Scalar8BatchRouteHint hint))
            {
                Fixed32Scalar8RouteTarget target = hint.PathTarget.Target;
                if (hint.Prefix.Matches(key0, key1, key2, key3) ||
                    GetFixed32BatchRouteHintCommonPrefixByteCount(hint.Key0, hint.Key1, hint.Key2, hint.Key3, key0, key1, key2, key3) >= target.RouterDepth)
                {
                    byte prefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, target.RouterDepth);
                    if ((prefixByte >= hint.PrefixRangeStart && prefixByte <= hint.PrefixRangeEnd) ||
                        TryGetDirectRouterTargetPrefixRange(hint.PathTarget.ParentRouterOffset, prefixByte, target.Offset, out _, out _))
                    {
                        pathTarget = new Fixed32Scalar8RoutePathTarget(target, hint.PathTarget.ParentRouterOffset, prefixByte);
                        return true;
                    }
                }
            }
        }

        pathTarget = default;
        return false;
    }

    /// <summary>
    /// Retains the final published `FS32-8` route path for the next public batch on the same root.<br/>
    /// The hint is an accelerator only and is cleared by every structural router-cache invalidation.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The fixed index root router offset.<br/></param>
    /// <param name="key0">The first encoded fixed-key lane used to classify the path.<br/></param>
    /// <param name="key1">The second encoded fixed-key lane used to classify the path.<br/></param>
    /// <param name="key2">The third encoded fixed-key lane used to classify the path.<br/></param>
    /// <param name="key3">The fourth encoded fixed-key lane used to classify the path.<br/></param>
    /// <param name="pathTarget">The final path known to be valid after publication.<br/></param>
    internal void StoreFixed32Scalar8BatchRouteHint(long rootRouterOffset, ulong key0, ulong key1, ulong key2, ulong key3, Fixed32Scalar8RoutePathTarget pathTarget)
    {
        Fixed32BatchRouteHintPrefix prefix = Fixed32BatchRouteHintPrefix.Create(key0, key1, key2, key3, pathTarget.Target.RouterDepth);
        byte prefixRangeStart = pathTarget.RoutePrefixByte;
        byte prefixRangeEnd = pathTarget.RoutePrefixByte;
        _ = TryGetDirectRouterTargetPrefixRange(pathTarget.ParentRouterOffset, pathTarget.RoutePrefixByte, pathTarget.Target.Offset, out prefixRangeStart, out prefixRangeEnd);
        lock (routerReadCacheSync)
        {
            fixed32Scalar8BatchRouteHints[rootRouterOffset] = new Fixed32Scalar8BatchRouteHint(prefix, pathTarget, key0, key1, key2, key3, prefixRangeStart, prefixRangeEnd);
        }
    }

    /// <summary>
    /// Reads one router page into caller-owned scratch for harness-level routed range scans.<br/>
    /// This keeps the benchmark path allocation-free per router while avoiding repeated one-prefix router reads during broad prefix traversal.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset of the router page to read.</param>
    /// <param name="destination">The caller-owned router scratch buffer.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly one router page.</exception>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="routerOffset"/> are not a valid router.</exception>
    internal void ReadRouterPageForRangeScan(long routerOffset, Span<byte> destination)
    {
        if (destination.Length != RouterLayout.Size)
        {
            throw new ArgumentException("The router range-scan scratch buffer must be exactly one router page.", nameof(destination));
        }

        kernel.Read(routerOffset, destination);
        RouterReader reader = new(destination);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed range-scan page is not a valid router.");
        }
    }

    /// <summary>
    /// Reads one `FS32-8` shelf into caller-owned scratch for harness-level routed range scans.<br/>
    /// The method validates the shelf image but does not interact with the batch-local clean-shelf cache used by write benchmarks.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset of the shelf extent to read.</param>
    /// <param name="profile">The `FS32-8` profile that determines the shelf extent size.</param>
    /// <param name="destination">The caller-owned shelf scratch buffer.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly one profiled shelf extent.</exception>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="shelfOffset"/> are not a valid `FS32-8` shelf.</exception>
    internal void ReadFixed32Scalar8ShelfForRangeScan(long shelfOffset, Fixed32Scalar8Profile profile, Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FS32-8 range-scan shelf scratch buffer must match the profiled shelf extent size.", nameof(destination));
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar8ReadOnly readOnly = new(destination, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The routed range-scan FS32-8 shelf is invalid.");
        }
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `FS32-8` encoded key range using caller-owned scratch and route-kind cache state.<br/>
    /// The method keeps storage semantics byte-first: keys are already encoded fixed-key lanes, and identities are returned in persisted encoded scalar form.<br/>
    /// Reusing <paramref name="targetKindCache"/> across repeated reads over the same session avoids repeated 4-byte target-classifier reads without introducing global mutable state.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-8` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the key range is invalid or shelf scratch does not match the profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `FS32-8` shelves.</exception>
    internal int ReadFixed32Scalar8IdentityRange(
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int maxRouterHops,
        Span<ulong> encodedIdentities,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        if (CompareFixed32Scalar8Key(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3) > 0)
        {
            throw new ArgumentException("The upper FS32-8 encoded key must be greater than or equal to the lower encoded key.", nameof(upper0));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The FS32-8 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FS32-8 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

        Span<byte> routerScratch = stackalloc byte[RouterLayout.Size];
        return ReadFixed32Scalar8IdentityRangeFromRouter(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            remainingRouterHops: maxRouterHops,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentities,
            routerScratch,
            shelfScratch,
            previousShelfOffset: 0,
            targetKindCache);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `FS32-8` encoded key range using the session default route-hop guard.<br/>
    /// This wrapper returns a result contract while preserving explicit caller-owned scratch and cache lifetimes for hot paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-8` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>A result describing the copied identity count and cache shape.</returns>
    internal Fixed32Scalar8RangeReadResult ReadEncodedFixed32Scalar8IdentityRange(
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        Span<ulong> encodedIdentities,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        int identityCount = ReadFixed32Scalar8IdentityRange(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            DefaultFixed32Scalar8MaxRouterHops,
            encodedIdentities,
            shelfScratch,
            targetKindCache);
        return new Fixed32Scalar8RangeReadResult(
            identityCount,
            UsedRouteKindCache: true,
            targetKindCache.Count);
    }

    private int ReadFixed32Scalar8IdentityRangeFromRouter(
        long routerOffset,
        Fixed32Scalar8Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int remainingRouterHops,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentities,
        Span<byte> routerScratch,
        Span<byte> shelfScratch,
        long previousShelfOffset,
        RouteTargetKindCache targetKindCache)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The FS32-8 routed range traversal exceeded the configured maximum router hop count.");
        }

        ReadRouterPageForRangeScan(routerOffset, routerScratch);
        RouterReader reader = new(routerScratch);
        byte startPrefix = lowerEdge ? GetFixed32Scalar8Prefix(lower0, lower1, lower2, lower3, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetFixed32Scalar8Prefix(upper0, upper1, upper2, upper3, reader.KeyDepth) : byte.MaxValue;
        int routeCount = endPrefix - startPrefix + 1;
        Span<long> targetOffsets = routeCount <= 256
            ? stackalloc long[routeCount]
            : new long[routeCount];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            targetOffsets[prefix - startPrefix] = reader.FindTarget((byte)prefix);
        }

        int copied = 0;
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            byte prefixByte = (byte)prefix;
            long targetOffset = targetOffsets[prefix - startPrefix];
            if (targetOffset == 0)
            {
                continue;
            }

            Fixed32Scalar8RouteTargetKind kind = GetFixed32Scalar8RouteTargetKind(targetOffset, targetKindCache);
            if (kind == Fixed32Scalar8RouteTargetKind.Router)
            {
                copied += ReadFixed32Scalar8IdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lower0,
                    lower1,
                    lower2,
                    lower3,
                    upper0,
                    upper1,
                    upper2,
                    upper3,
                    remainingRouterHops - 1,
                    lowerEdge && prefixByte == startPrefix,
                    upperEdge && prefixByte == endPrefix,
                    encodedIdentities[copied..],
                    routerScratch,
                    shelfScratch,
                    previousShelfOffset,
                    targetKindCache);
                continue;
            }

            if (kind != Fixed32Scalar8RouteTargetKind.Shelf || targetOffset == previousShelfOffset)
            {
                continue;
            }

            ReadFixed32Scalar8ShelfForRangeScan(targetOffset, profile, shelfScratch);
            Fixed32Scalar8ReadOnly shelf = new(shelfScratch, profile);
            copied += shelf.CopyIdentitiesInKeyRange(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3, encodedIdentities[copied..]);
            previousShelfOffset = targetOffset;
        }

        return copied;
    }

    private Fixed32Scalar8RouteTargetKind GetFixed32Scalar8RouteTargetKind(long targetOffset, RouteTargetKindCache targetKindCache)
    {
        if (targetKindCache.TryGet(targetOffset, out int cachedKind))
        {
            return (Fixed32Scalar8RouteTargetKind)cachedKind;
        }

        Fixed32Scalar8RouteTargetKind kind = ClassifyFixed32Scalar8RouteTarget(targetOffset);
        targetKindCache.Set(targetOffset, (int)kind);
        return kind;
    }

