    /// <summary>
    /// Reads encoded identities for an inclusive `SS16-8` encoded key range using caller-owned scratch and route-kind cache state.<br/>
    /// The traversal follows the persisted router topology and copies identities directly from validated shelf bytes without constructing typed key objects.<br/>
    /// Reusing <paramref name="targetKindCache"/> across repeated reads over the same session avoids repeated target-classifier reads while keeping cache lifetime explicit.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerHigh">The inclusive lower encoded high key half.</param>
    /// <param name="lowerLow">The inclusive lower encoded low key half.</param>
    /// <param name="upperHigh">The inclusive upper encoded high key half.</param>
    /// <param name="upperLow">The inclusive upper encoded low key half.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `SS16-8` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the key range is invalid or shelf scratch does not match the profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS16-8` shelves.</exception>
    internal int ReadScalar16Scalar8IdentityRange(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong lowerHigh,
        ulong lowerLow,
        ulong upperHigh,
        ulong upperLow,
        int maxRouterHops,
        Span<ulong> encodedIdentities,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        if (CompareScalar16Key(lowerHigh, lowerLow, upperHigh, upperLow) > 0)
        {
            throw new ArgumentException("The upper SS16-8 encoded key must be greater than or equal to the lower encoded key.", nameof(upperHigh));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The SS16-8 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The SS16-8 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

        Span<byte> routerScratch = stackalloc byte[RouterLayout.Size];
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        return ReadScalar16Scalar8IdentityRangeFromRouter(
            rootRouterOffset,
            profile,
            lowerHigh,
            lowerLow,
            upperHigh,
            upperLow,
            remainingRouterHops: maxRouterHops,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentities,
            routerScratch,
            shelfScratch,
            visitedShelves,
            targetKindCache);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive `SS16-8` encoded key range using the session default route-hop guard.<br/>
    /// This wrapper returns a result contract while preserving explicit caller-owned scratch and cache lifetimes for hot paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerHigh">The inclusive lower encoded high key half.</param>
    /// <param name="lowerLow">The inclusive lower encoded low key half.</param>
    /// <param name="upperHigh">The inclusive upper encoded high key half.</param>
    /// <param name="upperLow">The inclusive upper encoded low key half.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `SS16-8` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>A result describing the copied identity count and cache shape.</returns>
    internal Scalar16Scalar8RangeReadResult ReadEncodedScalar16Scalar8IdentityRange(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong lowerHigh,
        ulong lowerLow,
        ulong upperHigh,
        ulong upperLow,
        Span<ulong> encodedIdentities,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        int identityCount = ReadScalar16Scalar8IdentityRange(
            rootRouterOffset,
            profile,
            lowerHigh,
            lowerLow,
            upperHigh,
            upperLow,
            DefaultScalar16Scalar8MaxRouterHops,
            encodedIdentities,
            shelfScratch,
            targetKindCache);
        return new Scalar16Scalar8RangeReadResult(
            identityCount,
            UsedRouteKindCache: true,
            targetKindCache.Count);
    }

    private int ReadScalar16Scalar8IdentityRangeFromRouter(
        long routerOffset,
        Scalar16Scalar8Profile profile,
        ulong lowerHigh,
        ulong lowerLow,
        ulong upperHigh,
        ulong upperLow,
        int remainingRouterHops,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentities,
        Span<byte> routerScratch,
        Span<byte> shelfScratch,
        RouteVisitedOffsetSet visitedShelves,
        RouteTargetKindCache targetKindCache)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The SS16-8 routed range traversal exceeded the configured maximum router hop count.");
        }

        ReadRouterPageForRangeScan(routerOffset, routerScratch);
        RouterReader reader = new(routerScratch);
        int keyDepth = reader.KeyDepth;
        byte startPrefix = lowerEdge ? GetScalar16Scalar8Prefix(lowerHigh, lowerLow, keyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetScalar16Scalar8Prefix(upperHigh, upperLow, keyDepth) : byte.MaxValue;
        int routeCount = endPrefix - startPrefix + 1;
        Span<long> targetOffsets = stackalloc long[routeCount];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            targetOffsets[prefix - startPrefix] = reader.FindTarget((byte)prefix);
        }

        int copied = 0;
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            byte prefixByte = (byte)prefix;
            long targetOffset = targetOffsets[prefix - startPrefix];
            if (targetOffset == 0)
            {
                continue;
            }

            Scalar16Scalar8RouteTargetKind kind = GetScalar16Scalar8RouteTargetKind(targetOffset, targetKindCache);
            if (kind == Scalar16Scalar8RouteTargetKind.Router)
            {
                if (keyDepth == 0)
                {
                    visitedShelves.Clear();
                }

                copied += ReadScalar16Scalar8IdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lowerHigh,
                    lowerLow,
                    upperHigh,
                    upperLow,
                    remainingRouterHops - 1,
                    lowerEdge && prefixByte == startPrefix,
                    upperEdge && prefixByte == endPrefix,
                    encodedIdentities[copied..],
                    routerScratch,
                    shelfScratch,
                    visitedShelves,
                    targetKindCache);
                continue;
            }

            if (kind != Scalar16Scalar8RouteTargetKind.Shelf || !visitedShelves.Add(targetOffset))
            {
                continue;
            }

            ReadScalar16Scalar8ShelfForRangeScan(targetOffset, profile, shelfScratch);
            Scalar16Scalar8ReadOnly shelf = new(shelfScratch, profile);
            copied += shelf.CopyIdentitiesInKeyRange(lowerHigh, lowerLow, upperHigh, upperLow, encodedIdentities[copied..]);
        }

        return copied;
    }

    private Scalar16Scalar8RouteTargetKind GetScalar16Scalar8RouteTargetKind(long targetOffset, RouteTargetKindCache targetKindCache)
    {
        if (targetKindCache.TryGet(targetOffset, out int cachedKind))
        {
            return (Scalar16Scalar8RouteTargetKind)cachedKind;
        }

        Scalar16Scalar8RouteTargetKind kind = ClassifyScalar16Scalar8RouteTarget(targetOffset);
        targetKindCache.Set(targetOffset, (int)kind);
        return kind;
    }

    /// <summary>
    /// Reads encoded identity pairs for an inclusive `SS8-16` encoded key range using caller-owned scratch and route-kind cache state.<br/>
    /// The traversal follows the persisted router topology and copies identity halves directly from validated shelf bytes without constructing typed identity objects.<br/>
    /// Reusing <paramref name="targetKindCache"/> across repeated reads over the same session avoids repeated target-classifier reads while keeping cache lifetime explicit.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-16` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower">The inclusive lower encoded key.</param>
    /// <param name="upper">The inclusive upper encoded key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="identityHighs">The caller-owned output span that receives matching encoded identity high halves.</param>
    /// <param name="identityLows">The caller-owned output span that receives matching encoded identity low halves.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `SS8-16` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>The number of encoded identity pairs copied into <paramref name="identityHighs"/> and <paramref name="identityLows"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the key range is invalid or shelf scratch does not match the profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `SS8-16` shelves.</exception>
    internal int ReadScalar8Scalar16IdentityRange(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong lower,
        ulong upper,
        int maxRouterHops,
        Span<ulong> identityHighs,
        Span<ulong> identityLows,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        if (upper < lower)
        {
            throw new ArgumentException("The upper SS8-16 encoded key must be greater than or equal to the lower encoded key.", nameof(upper));
        }

        if (identityLows.Length < identityHighs.Length)
        {
            throw new ArgumentException("The SS8-16 identity-low output span must be at least as long as the identity-high output span.", nameof(identityLows));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The SS8-16 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The SS8-16 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

        Span<byte> routerScratch = stackalloc byte[RouterLayout.Size];
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        return ReadScalar8Scalar16IdentityRangeFromRouter(
            rootRouterOffset,
            profile,
            lower,
            upper,
            remainingRouterHops: maxRouterHops,
            lowerEdge: true,
            upperEdge: true,
            identityHighs,
            identityLows,
            routerScratch,
            shelfScratch,
            visitedShelves,
            targetKindCache);
    }

