        {
            throw new ArgumentException("The SS16-16 identity-low output span must be at least as long as the identity-high output span.", nameof(identityLows));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The SS16-16 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The SS16-16 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

