    /// <summary>
    /// Dispatches a coalesced range whose lower and upper keys select different root-router prefix bytes.<br/>
    /// If both root routes already target shelves, the method can coalesce directly across the root router without separate boundary walks.<br/>
    /// If either boundary points to another router, the method enters generalized coalesced traversal directly and avoids duplicate boundary work.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="lowerRootPrefix">The lower key's root-prefix byte.</param>
    /// <param name="upperRootPrefix">The upper key's root-prefix byte.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading routers and classifying targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or a boundary route target is unset.</exception>
    private int ScoopScalar8Scalar8IdentityRangeFromRootPrefixSpanCoalesced(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        byte lowerRootPrefix,
        byte upperRootPrefix,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch)
    {
        Span<byte> rootBytes = stackalloc byte[RouterLayout.Size];
        ReadScalar8Scalar8RouterForPolicy(rootRouterOffset, readPolicy, rootBytes);
        RouterReader rootReader = new(rootBytes);
        if (!rootReader.IsValid)
        {
            throw new InvalidDataException("The coalesced range root router is invalid.");
        }

        long lowerTargetOffset = rootReader.FindTarget(lowerRootPrefix);
        long upperTargetOffset = rootReader.FindTarget(upperRootPrefix);
        if (lowerTargetOffset == 0 || upperTargetOffset == 0)
        {
            throw new InvalidDataException("The coalesced range root boundary route is unset.");
        }

        Scalar8Scalar8RouteTargetKind lowerKind = ClassifyScalar8Scalar8RouteTargetForPolicy(lowerTargetOffset, readPolicy);
        Scalar8Scalar8RouteTargetKind upperKind = ClassifyScalar8Scalar8RouteTargetForPolicy(upperTargetOffset, readPolicy);
        if (lowerKind == Scalar8Scalar8RouteTargetKind.Shelf && upperKind == Scalar8Scalar8RouteTargetKind.Shelf)
        {
            Scalar8Scalar8RouteTarget lowerTarget = new(lowerKind, lowerTargetOffset, rootReader.KeyDepth, rootReader.AllocationClassId);
            Scalar8Scalar8RouteTarget upperTarget = new(upperKind, upperTargetOffset, rootReader.KeyDepth, rootReader.AllocationClassId);
            return ScoopScalar8Scalar8IdentityRangeAcrossParentRouterCoalesced(
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                new Scalar8Scalar8RoutePathTarget(lowerTarget, rootRouterOffset, lowerRootPrefix),
                new Scalar8Scalar8RoutePathTarget(upperTarget, rootRouterOffset, upperRootPrefix),
                readPolicy,
                encodedIdentities,
                rangeScratch);
        }

        if (lowerKind == Scalar8Scalar8RouteTargetKind.Router || upperKind == Scalar8Scalar8RouteTargetKind.Router)
        {
            return ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversalCoalesced(
                rootRouterOffset,
                profile,
                lowerEncodedKey,
                upperEncodedKey,
                maxRouterHops,
                readPolicy,
                encodedIdentities,
                rangeScratch);
        }

        throw new InvalidDataException("The coalesced range root boundary route did not target a shelf or router.");
    }

    /// <summary>
    /// Scoops an inclusive encoded key range across distinct shelf targets selected by one parent router.<br/>
    /// The method enumerates the parent router prefix interval, reads each distinct shelf target once, and reuses the fixed-shelf range scoop primitive for identity copying.<br/>
    /// </summary>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="lowerPath">The routed lower-bound target and parent route.</param>
    /// <param name="upperPath">The routed upper-bound target and parent route.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading the parent router and classifying shelf targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfBuffer">The caller-owned scratch buffer used for one shelf extent read at a time.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the range cannot be represented by one parent router or when an enumerated route target is invalid.</exception>
    private int ScoopScalar8Scalar8IdentityRangeAcrossParentRouter(
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RoutePathTarget lowerPath,
        Scalar8Scalar8RoutePathTarget upperPath,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> shelfBuffer)
    {
        if (lowerPath.ParentRouterOffset != upperPath.ParentRouterOffset ||
            lowerPath.Target.RouterDepth != upperPath.Target.RouterDepth ||
            lowerPath.RoutePrefixByte > upperPath.RoutePrefixByte)
        {
            throw new InvalidDataException("The first cross-shelf SS8-8 range scoop requires both boundaries to share one parent router and increasing route prefix interval.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadScalar8Scalar8RouterForPolicy(lowerPath.ParentRouterOffset, readPolicy, routerBytes);
        RouterReader parentReader = new(routerBytes);
        if (!parentReader.IsValid)
        {
            throw new InvalidDataException("The range parent router is invalid.");
        }

        int copied = 0;
        long previousShelfOffset = 0;
        for (int prefix = lowerPath.RoutePrefixByte; prefix <= upperPath.RoutePrefixByte; prefix++)
        {
            long targetOffset = parentReader.FindTarget((byte)prefix);
            if (targetOffset == 0 || targetOffset == previousShelfOffset)
            {
                continue;
            }

            bool knownBoundaryTarget =
                targetOffset == lowerPath.Target.Offset ||
                targetOffset == upperPath.Target.Offset;
            Scalar8Scalar8RouteTargetKind kind = knownBoundaryTarget && targetOffset == lowerPath.Target.Offset
                ? lowerPath.Target.Kind
                : knownBoundaryTarget && targetOffset == upperPath.Target.Offset
                    ? upperPath.Target.Kind
                    : ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
            if (kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                copied += CopyScalar8Scalar8TerminalRootIdentitiesInRange(targetOffset, profile, lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                previousShelfOffset = targetOffset;
                continue;
            }

            if (kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The range parent router enumerated a non-shelf target.");
            }

            kernel.Read(targetOffset, shelfBuffer);
            Scalar8Scalar8ReadOnly shelf = new(shelfBuffer, profile);
            if (!shelf.IsValid)
            {
                throw new InvalidDataException("The cross-shelf range SS8-8 shelf bytes are invalid.");
            }

            copied += shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
            previousShelfOffset = targetOffset;
        }

        return copied;
    }

    /// <summary>
    /// Scoops an inclusive encoded key range across one parent router while coalescing contiguous shelf extent reads into a caller-owned scratch buffer.<br/>
    /// The method still validates each shelf view after the coalesced read, so target corruption is caught by the existing shelf magic/header checks without an extra classifier read for known boundary shelves.<br/>
    /// Coalescing is bounded by <paramref name="rangeScratch"/>; when a contiguous run would exceed that buffer, the current run is flushed and a new run starts.<br/>
    /// </summary>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="lowerPath">The routed lower-bound target and parent route.</param>
    /// <param name="upperPath">The routed upper-bound target and parent route.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading the parent router and classifying unknown targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the range cannot be represented by one parent router or when an enumerated route target is invalid.</exception>
    private int ScoopScalar8Scalar8IdentityRangeAcrossParentRouterCoalesced(
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        Scalar8Scalar8RoutePathTarget lowerPath,
        Scalar8Scalar8RoutePathTarget upperPath,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch)
    {
        if (lowerPath.ParentRouterOffset != upperPath.ParentRouterOffset ||
            lowerPath.Target.RouterDepth != upperPath.Target.RouterDepth ||
            lowerPath.RoutePrefixByte > upperPath.RoutePrefixByte)
        {
            throw new InvalidDataException("The coalesced cross-shelf SS8-8 range scoop requires both boundaries to share one parent router and increasing route prefix interval.");
        }

        int shelfExtentSize = profile.ShelfExtentSize;
        int maxRunShelves = rangeScratch.Length / shelfExtentSize;
        if (maxRunShelves <= 0)
        {
            throw new InvalidDataException("The coalesced range scratch buffer cannot hold one SS8-8 shelf extent.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadScalar8Scalar8RouterForPolicy(lowerPath.ParentRouterOffset, readPolicy, routerBytes);
        RouterReader parentReader = new(routerBytes);
        if (!parentReader.IsValid)
        {
            throw new InvalidDataException("The coalesced range parent router is invalid.");
        }

        int copied = 0;
        long previousShelfOffset = 0;
        long runStartOffset = 0;
        int runShelfCount = 0;
        for (int prefix = lowerPath.RoutePrefixByte; prefix <= upperPath.RoutePrefixByte; prefix++)
        {
            long targetOffset = parentReader.FindTarget((byte)prefix);
            if (targetOffset == 0 || targetOffset == previousShelfOffset)
            {
                continue;
            }

            bool knownBoundaryTarget =
                targetOffset == lowerPath.Target.Offset ||
                targetOffset == upperPath.Target.Offset;
            Scalar8Scalar8RouteTargetKind kind = knownBoundaryTarget && targetOffset == lowerPath.Target.Offset
                ? lowerPath.Target.Kind
                : knownBoundaryTarget && targetOffset == upperPath.Target.Offset
                    ? upperPath.Target.Kind
                    : ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
            if (kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                if (runShelfCount > 0)
                {
                    copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
                    runStartOffset = 0;
                    runShelfCount = 0;
                }

                copied += CopyScalar8Scalar8TerminalRootIdentitiesInRange(targetOffset, profile, lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                previousShelfOffset = targetOffset;
                continue;
            }

            if (kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The coalesced range parent router enumerated a non-shelf target.");
            }

            bool extendsRun = runShelfCount > 0 && targetOffset == runStartOffset + ((long)runShelfCount * shelfExtentSize);
            if (runShelfCount == 0)
            {
                runStartOffset = targetOffset;
                runShelfCount = 1;
            }
            else if (extendsRun && runShelfCount < maxRunShelves)
            {
                runShelfCount++;
            }
            else
            {
                copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
                runStartOffset = targetOffset;
                runShelfCount = 1;
            }

            previousShelfOffset = targetOffset;
        }

        if (runShelfCount > 0)
        {
            copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
        }

        return copied;
    }

    /// <summary>
    /// Reads and processes one contiguous run of `SS8-8` shelf extents from a caller-owned coalescing scratch buffer.<br/>
    /// One `DataKernel` positional read fills the contiguous byte span, then each shelf view is projected from that span and copied through the existing fixed-shelf range primitive.<br/>
    /// The helper is intentionally small and hot-path local so range coalescing avoids callback/delegate overhead while preserving per-shelf validation.<br/>
    /// </summary>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="runStartOffset">The file offset of the first shelf extent in the contiguous run.</param>
    /// <param name="runShelfCount">The number of contiguous shelf extents in the run.</param>
    /// <param name="encodedIdentities">The remaining caller-owned output span.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for the coalesced read.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when a shelf in the coalesced run is invalid.</exception>
    private int FlushScalar8Scalar8CoalescedShelfRun(
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        long runStartOffset,
        int runShelfCount,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch)
    {
        int shelfExtentSize = profile.ShelfExtentSize;
        int runLength = checked(runShelfCount * shelfExtentSize);
        Span<byte> runBytes = rangeScratch[..runLength];
        kernel.Read(runStartOffset, runBytes);

        int copied = 0;
        for (int i = 0; i < runShelfCount; i++)
        {
            Span<byte> shelfBytes = runBytes.Slice(i * shelfExtentSize, shelfExtentSize);
            Scalar8Scalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid)
            {
                throw new InvalidDataException("The coalesced range read invalid SS8-8 shelf bytes.");
            }

            copied += shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
        }

        return copied;
    }

    /// <summary>
    /// Scoops an inclusive encoded key range by traversing the router graph from the root over only the relevant prefix intervals.<br/>
    /// The traversal carries lower-edge and upper-edge state so child routers below the lower boundary scan from the lower key byte, child routers below the upper boundary scan to the upper key byte, and middle branches scan their full local prefix space.<br/>
    /// This is the first generalized range cursor shape and intentionally keeps the same fixed-shelf scoop primitive as the leaf operation.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading routers and classifying route targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfBuffer">The caller-owned scratch buffer used for one shelf extent read at a time.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    private int ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversal(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> shelfBuffer)
    {
        long previousShelfOffset = 0;
        int copied = 0;
        TraverseScalar8Scalar8RangeRouter(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            maxRouterHops,
            readPolicy,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentities,
            shelfBuffer,
            ref copied,
            ref previousShelfOffset);
        return copied;
    }

    /// <summary>
    /// Scoops an inclusive encoded key range by traversing the router graph and coalescing contiguous shelf runs through caller-owned scratch.<br/>
    /// This is the generalized counterpart to same-parent coalescing: recursion still determines route order, while a small run accumulator collapses adjacent shelf extents before reading them.<br/>
    /// The caller controls the maximum coalesced run size by choosing <paramref name="rangeScratch"/> length, so the hot path does not allocate or hide memory growth.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading routers and classifying route targets.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <returns>The number of encoded identities copied into <paramref name="encodedIdentities"/>.</returns>
    private int ScoopScalar8Scalar8IdentityRangeAcrossRouterTraversalCoalesced(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch)
    {
        int copied = 0;
        long previousShelfOffset = 0;
        long runStartOffset = 0;
        int runShelfCount = 0;
        TraverseScalar8Scalar8RangeRouterCoalesced(
            rootRouterOffset,
            profile,
            lowerEncodedKey,
            upperEncodedKey,
            maxRouterHops,
            readPolicy,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentities,
            rangeScratch,
            ref copied,
            ref previousShelfOffset,
            ref runStartOffset,
            ref runShelfCount);

        if (runShelfCount > 0)
        {
            copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
        }

        return copied;
    }

    /// <summary>
    /// Traverses one router for an inclusive encoded key range while accumulating contiguous shelf targets for coalesced reads.<br/>
    /// Pending shelf runs are flushed before descending into child routers so output order remains route-order stable across mixed shelf/router branches.<br/>
    /// </summary>
    /// <param name="routerOffset">The current router page file offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="remainingRouterHops">The remaining router hop budget.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading routers and classifying route targets.</param>
    /// <param name="lowerEdge">Whether this router branch still lies on the lower-bound edge.</param>
    /// <param name="upperEdge">Whether this router branch still lies on the upper-bound edge.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="rangeScratch">The caller-owned scratch span used for one or more contiguous shelf extents.</param>
    /// <param name="copied">The running count of copied identities.</param>
    /// <param name="previousShelfOffset">The last shelf offset visited, used to avoid duplicate adjacent route targets.</param>
    /// <param name="runStartOffset">The file offset of the first shelf in the pending contiguous run.</param>
    /// <param name="runShelfCount">The number of shelves in the pending contiguous run.</param>
    /// <exception cref="InvalidDataException">Thrown when traversal reaches invalid router bytes or a non-shelf/non-router target.</exception>
    private void TraverseScalar8Scalar8RangeRouterCoalesced(
        long routerOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int remainingRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentities,
        Span<byte> rangeScratch,
        ref int copied,
        ref long previousShelfOffset,
        ref long runStartOffset,
        ref int runShelfCount)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The coalesced routed range traversal exceeded the configured maximum router hop count.");
        }

        int shelfExtentSize = profile.ShelfExtentSize;
        int maxRunShelves = rangeScratch.Length / shelfExtentSize;
        if (maxRunShelves <= 0)
        {
            throw new InvalidDataException("The coalesced range scratch buffer cannot hold one SS8-8 shelf extent.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadScalar8Scalar8RouterForPolicy(routerOffset, readPolicy, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The coalesced routed range traversal read an invalid router.");
        }

        byte startPrefix = lowerEdge ? GetScalar8Scalar8Prefix(lowerEncodedKey, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetScalar8Scalar8Prefix(upperEncodedKey, reader.KeyDepth) : byte.MaxValue;
        int prefix = startPrefix;
        while (prefix <= endPrefix)
        {
            long targetOffset = reader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                prefix++;
                continue;
            }

            int runStart = prefix;
            int runEnd = prefix;
            while (runEnd < endPrefix && reader.FindTarget((byte)(runEnd + 1)) == targetOffset)
            {
                runEnd++;
            }

            bool singlePrefixRun = runStart == runEnd;
            Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
            if (kind == Scalar8Scalar8RouteTargetKind.Shelf)
            {
                if (targetOffset == previousShelfOffset)
                {
                    prefix = runEnd + 1;
                    continue;
                }

                bool extendsRun = runShelfCount > 0 && targetOffset == runStartOffset + ((long)runShelfCount * shelfExtentSize);
                if (runShelfCount == 0)
                {
                    runStartOffset = targetOffset;
                    runShelfCount = 1;
                }
                else if (extendsRun && runShelfCount < maxRunShelves)
                {
                    runShelfCount++;
                }
                else
                {
                    copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
                    runStartOffset = targetOffset;
                    runShelfCount = 1;
                }

                previousShelfOffset = targetOffset;
                prefix = runEnd + 1;
                continue;
            }

            if (kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                if (targetOffset == previousShelfOffset)
                {
                    prefix = runEnd + 1;
                    continue;
                }

                if (runShelfCount > 0)
                {
                    copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
                    runStartOffset = 0;
                    runShelfCount = 0;
                }

                copied += CopyScalar8Scalar8TerminalRootIdentitiesInRange(targetOffset, profile, lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                previousShelfOffset = targetOffset;
                prefix = runEnd + 1;
                continue;
            }

            if (kind == Scalar8Scalar8RouteTargetKind.Router)
            {
                if (runShelfCount > 0)
                {
                    copied += FlushScalar8Scalar8CoalescedShelfRun(profile, lowerEncodedKey, upperEncodedKey, runStartOffset, runShelfCount, encodedIdentities.Slice(copied), rangeScratch);
                    runStartOffset = 0;
                    runShelfCount = 0;
                }

                TraverseScalar8Scalar8RangeRouterCoalesced(
                    targetOffset,
                    profile,
                    lowerEncodedKey,
                    upperEncodedKey,
                    remainingRouterHops - 1,
                    readPolicy,
                    singlePrefixRun && lowerEdge && runStart == startPrefix,
                    singlePrefixRun && upperEdge && runEnd == endPrefix,
                    encodedIdentities,
                    rangeScratch,
                    ref copied,
                    ref previousShelfOffset,
                    ref runStartOffset,
                    ref runShelfCount);
                prefix = runEnd + 1;
                continue;
            }

            throw new InvalidDataException("The coalesced routed range traversal found an unsupported route target.");
        }
    }

    /// <summary>
    /// Traverses one router for an inclusive encoded key range and recursively visits only relevant child routes.<br/>
    /// The method scans at most the prefix interval required at this router depth and reads each distinct shelf target once in traversal order.<br/>
    /// </summary>
    /// <param name="routerOffset">The current router page file offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lowerEncodedKey">The inclusive lower encoded sortable key.</param>
    /// <param name="upperEncodedKey">The inclusive upper encoded sortable key.</param>
    /// <param name="remainingRouterHops">The remaining router hop budget.</param>
    /// <param name="readPolicy">The route-read policy to apply while reading routers and classifying route targets.</param>
    /// <param name="lowerEdge">Whether this router branch still lies on the lower-bound edge.</param>
    /// <param name="upperEdge">Whether this router branch still lies on the upper-bound edge.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching encoded identities.</param>
    /// <param name="shelfBuffer">The caller-owned scratch buffer used for one shelf extent read at a time.</param>
    /// <param name="copied">The running count of copied identities.</param>
    /// <param name="previousShelfOffset">The last shelf offset visited, used to avoid duplicate adjacent route targets.</param>
    /// <exception cref="InvalidDataException">Thrown when traversal reaches invalid router bytes or a non-shelf/non-router target.</exception>
    private void TraverseScalar8Scalar8RangeRouter(
        long routerOffset,
        Scalar8Scalar8Profile profile,
        ulong lowerEncodedKey,
        ulong upperEncodedKey,
        int remainingRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentities,
        Span<byte> shelfBuffer,
        ref int copied,
        ref long previousShelfOffset)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed range traversal exceeded the configured maximum router hop count.");
        }

        Span<byte> routerBytes = stackalloc byte[RouterLayout.Size];
        ReadScalar8Scalar8RouterForPolicy(routerOffset, readPolicy, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed range traversal read an invalid router.");
        }

        byte startPrefix = lowerEdge ? GetScalar8Scalar8Prefix(lowerEncodedKey, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetScalar8Scalar8Prefix(upperEncodedKey, reader.KeyDepth) : byte.MaxValue;
        int prefix = startPrefix;
        while (prefix <= endPrefix)
        {
            long targetOffset = reader.FindTarget((byte)prefix);
            if (targetOffset == 0)
            {
                prefix++;
                continue;
            }

            int runStart = prefix;
            int runEnd = prefix;
            while (runEnd < endPrefix && reader.FindTarget((byte)(runEnd + 1)) == targetOffset)
            {
                runEnd++;
            }

            bool singlePrefixRun = runStart == runEnd;
            Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
            if (kind == Scalar8Scalar8RouteTargetKind.Shelf)
            {
                if (targetOffset == previousShelfOffset)
                {
                    prefix = runEnd + 1;
                    continue;
                }

                kernel.Read(targetOffset, shelfBuffer);
                Scalar8Scalar8ReadOnly shelf = new(shelfBuffer, profile);
                if (!shelf.IsValid)
                {
                    throw new InvalidDataException("The routed range traversal read invalid SS8-8 shelf bytes.");
                }

                copied += shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                long nextDuplicateRunOffset = shelf.IsDuplicateRun ? shelf.DuplicateRunNextOffset : 0;
                while (nextDuplicateRunOffset != 0)
                {
                    kernel.Read(nextDuplicateRunOffset, shelfBuffer);
                    shelf = new Scalar8Scalar8ReadOnly(shelfBuffer, profile);
                    if (!shelf.IsValid || !shelf.IsDuplicateRun)
                    {
                        throw new InvalidDataException("The routed range traversal read invalid SS8-8 duplicate-run chain bytes.");
                    }

                    copied += shelf.CopyIdentitiesInKeyRange(lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                    nextDuplicateRunOffset = shelf.DuplicateRunNextOffset;
                }

                previousShelfOffset = targetOffset;
                prefix = runEnd + 1;
                continue;
            }

            if (kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                if (targetOffset == previousShelfOffset)
                {
                    prefix = runEnd + 1;
                    continue;
                }

                copied += CopyScalar8Scalar8TerminalRootIdentitiesInRange(targetOffset, profile, lowerEncodedKey, upperEncodedKey, encodedIdentities.Slice(copied));
                previousShelfOffset = targetOffset;
                prefix = runEnd + 1;
                continue;
            }

            if (kind == Scalar8Scalar8RouteTargetKind.Router)
            {
                TraverseScalar8Scalar8RangeRouter(
                    targetOffset,
                    profile,
                    lowerEncodedKey,
                    upperEncodedKey,
                    remainingRouterHops - 1,
                    readPolicy,
                    singlePrefixRun && lowerEdge && runStart == startPrefix,
                    singlePrefixRun && upperEdge && runEnd == endPrefix,
                    encodedIdentities,
                    shelfBuffer,
                    ref copied,
                    ref previousShelfOffset);
                prefix = runEnd + 1;
                continue;
            }

            throw new InvalidDataException("The routed range traversal found an unsupported route target.");
        }
    }

    /// <summary>
    /// Reads one router page according to the supplied `SS8-8` route-read policy.<br/>
    /// The helper centralizes policy dispatch for route walkers that need richer path metadata than the basic target-only walker returns.<br/>
    /// </summary>
    /// <param name="routerOffset">The router page file offset.</param>
    /// <param name="readPolicy">The route-read policy to apply.</param>
    /// <param name="destination">The destination buffer that receives the router page.</param>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="readPolicy"/> is unsupported.</exception>
    private void ReadScalar8Scalar8RouterForPolicy(
        long routerOffset,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<byte> destination)
    {
        switch (readPolicy)
        {
            case Scalar8Scalar8RouteReadPolicy.Uncached:
                kernel.Read(routerOffset, destination);
                break;
            case Scalar8Scalar8RouteReadPolicy.PreferArenaCache:
                ReadRouterPageUsingArenaCache(routerOffset, destination);
                break;
            default:
                throw new InvalidDataException($"Unsupported SS8-8 route read policy {readPolicy}.");
        }
    }

    /// <summary>
    /// Classifies one route target according to the supplied `SS8-8` route-read policy.<br/>
    /// Arena-aware policy can satisfy router magic reads from an already-loaded arena cache while uncached policy reads the target magic directly.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <param name="readPolicy">The route-read policy to apply.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="readPolicy"/> is unsupported or the target magic is unknown.</exception>
    private Scalar8Scalar8RouteTargetKind ClassifyScalar8Scalar8RouteTargetForPolicy(
        long targetOffset,
        Scalar8Scalar8RouteReadPolicy readPolicy)
    {
        return readPolicy switch
        {
            Scalar8Scalar8RouteReadPolicy.Uncached => ClassifyScalar8Scalar8RouteTarget(targetOffset),
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache => ClassifyScalar8Scalar8RouteTargetUsingArenaCache(targetOffset),
            _ => throw new InvalidDataException($"Unsupported SS8-8 route read policy {readPolicy}.")
        };
    }

    /// <summary>
    /// Resolves and caches the classified target kind for one promoted direct-router route entry.<br/>
    /// File offset remains the durable route identity; target kind and child-router RAM offset are session-local accelerators over that durable target.<br/>
    /// </summary>
    /// <param name="view">The promoted direct-router view that owns the route entry.</param>
    /// <param name="prefixByte">The prefix byte selecting the route entry.</param>
    /// <param name="targetOffset">The durable file offset stored in the route entry.</param>
    /// <param name="readPolicy">The route-read policy to apply when classification is not cached.</param>
    /// <returns>The cached or newly classified target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target magic is unknown or the target router is invalid.</exception>
    private Scalar8Scalar8RouteTargetKind ResolveDirectRouteTargetKind(
        DirectRouterView view,
        byte prefixByte,
        long targetOffset,
        Scalar8Scalar8RouteReadPolicy readPolicy)
    {
        Scalar8Scalar8RouteTargetKind kind = view.GetTargetKind(prefixByte);
        if (kind != Scalar8Scalar8RouteTargetKind.None)
        {
            return kind;
        }

        kind = ClassifyScalar8Scalar8RouteTargetForPolicy(targetOffset, readPolicy);
        view.SetTargetKind(prefixByte, kind);
        if (kind == Scalar8Scalar8RouteTargetKind.Router && TryGetDirectRouterView(targetOffset, out DirectRouterView? childView))
        {
            view.SetTargetRouterRamOffset(prefixByte, childView!.RamOffset);
        }

        return kind;
    }

    /// <summary>
    /// Attempts to resolve a promoted child router from the session-local RAM offset cached in a direct route entry.<br/>
    /// Offset zero is reserved as "no promoted router" so default route-entry memory cannot accidentally reference a router.<br/>
    /// </summary>
    /// <param name="ramOffset">The session-local promoted-router arena offset.</param>
    /// <param name="view">The promoted direct-router view when the offset is valid.</param>
    /// <returns>True when <paramref name="ramOffset"/> identifies a promoted router; otherwise false.</returns>
    private bool TryGetPromotedRouterView(uint ramOffset, out DirectRouterView? view)
    {
        return promotedRouterArena.TryGetRouterView(ramOffset, out view);
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-8` key while using router micro-arena metadata as a read-cache hint.<br/>
    /// When a target router is known to live inside a registered or persisted arena, the session loads the whole arena once and serves later router-page or router-magic reads from that cached 32 KiB block.<br/>
    /// The cache is session-scoped and invalidated by every session commit so structural rewrites cannot leave stale router bytes behind.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded scalar key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar8Scalar8RouteTarget WalkScalar8Scalar8RouteTargetUsingArenaCache(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        byte[] routerBytes = new byte[RouterLayout.Size];
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            ReadRouterPageUsingArenaCache(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar8Scalar8Prefix(encodedKey, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed target is unset.");
            }

            Scalar8Scalar8RouteTargetKind kind = ClassifyScalar8Scalar8RouteTargetUsingArenaCache(targetOffset);
            if (kind == Scalar8Scalar8RouteTargetKind.Shelf ||
                kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                return new Scalar8Scalar8RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId);
            }

            if (kind == Scalar8Scalar8RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed target walk exceeded the configured maximum router hop count.");
    }

    private byte[] ReadDirectRootRouterBytesForLink(long rootRouterOffset)
    {
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingReader = new(existingRouter);
        if (!existingReader.IsValid || !existingReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        return existingRouter;
    }

    private DataKernelCommitTelemetry LinkDirectRootRouterRouteToShelf(
        long rootRouterOffset,
        byte[] existingRouter,
        byte prefixByte,
        long shelfOffset)
    {
        RawDataReservation routerReservation = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerReservation.Span);
        RouterWriter writer = new(routerReservation.Span);
        writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfOffset);
        InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
        return CommitAndDeferRouterReadCacheInvalidation();
    }

    private DataKernelCommitTelemetry LinkDirectRootRouterRoutesToShelf(
        long rootRouterOffset,
        byte[] existingRouter,
        ReadOnlySpan<byte> prefixBytes,
        long shelfOffset)
    {
        RawDataReservation routerReservation = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerReservation.Span);
        RouterWriter writer = new(routerReservation.Span);
        for (int i = 0; i < prefixBytes.Length; i++)
        {
            byte prefix = prefixBytes[i];
            writer.WriteRoute(prefix, prefix, prefix, shelfOffset);
        }

        InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
        return CommitAndDeferRouterReadCacheInvalidation();
    }

    /// <summary>
    /// Appends a sorted `Scalar8Scalar8` shelf and links one root-router prefix byte to the new shelf in the same commit.<br/>
    /// The shelf is initialized with deterministic `(key, identity)` tuples where both encoded scalar values equal the insert index.<br/>
    /// The root router is read once, then rewritten in place with the route target while the new shelf is appended.<br/>
    /// This is the first router-to-shelf integration primitive and intentionally keeps generation logic simple for validation.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte route to link to the new shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile used to size and populate the shelf extent.</param>
    /// <param name="itemCount">The number of deterministic sorted tuples to insert into the shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="itemCount"/> is outside the profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or not direct-index capable.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar8Profile profile,
        int itemCount)
    {
        if (itemCount < 0 || itemCount > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(itemCount), itemCount, "SS8-8 shelf item count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < itemCount; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i),
                allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 routed shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Creates an empty `VS8` shelf and links one root-router prefix to it.<br/>
    /// The first routed varlen slice starts with one shelf per root prefix and lets later inserts grow that shelf by appending a larger extent and repointing the route.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset to update.</param>
    /// <param name="prefixByte">The root prefix byte that should point at the new shelf.</param>
    /// <param name="profile">The starting `VS8` shelf profile.</param>
    /// <returns>The created shelf offset and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or not direct-index capable.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateVarKeyScalar8ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        VarKeyScalar8Profile profile)
    {
        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        byte[] shelfBytes = VarKeyScalar8.CreateEmpty(profile);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Attempts the narrow direct-writer cold-route path for one unset `VS8` root-prefix route.<br/>
    /// This path publishes exactly one prebuilt `VS8` shelf plus one direct root-router prefix update under the root-prefix topology owner and the storage publication lock.<br/>
    /// A false return means the route is no longer unset, so the caller should retry normal writer-context admission or use the broader topology path for the current route shape.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `VS8` index.<br/></param>
    /// <param name="prefixByte">The root-prefix byte expected to be unset.<br/></param>
    /// <param name="profile">The `VS8` shelf profile to use for the new shelf.<br/></param>
    /// <param name="key">The raw encoded key to insert into the new shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert into the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys are accepted by the index.<br/></param>
    /// <param name="result">The insert result when the cold route was initialized.<br/></param>
    /// <returns>True when the cold route was initialized and the tuple inserted; false when the route is no longer unset.<br/></returns>
    internal bool TryInsertVarKeyScalar8DirectColdRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out VarKeyScalar8RoutedInsertResult result)
    {
        byte[] shelfBytes = VarKeyScalar8.CreateEmpty(profile);
        if (!VarKeyScalar8MutableShelf.TryCreate(shelfBytes, profile, ownsBytes: false, rentSidecars: false, out VarKeyScalar8MutableShelf preparedShelf))
        {
            throw new InvalidDataException("The prepared VS8 cold-route shelf is invalid.");
        }

        VarKeyScalar8InsertResult preparedInsertResult = preparedShelf.InsertWithMutationHint(
            key,
            encodedIdentity,
            allowDuplicateKeys,
            hintStartDepth: 0,
            maxHintBytes: 0,
            out _);
        if (preparedInsertResult != VarKeyScalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected VS8 direct cold-route shelf insert, got {preparedInsertResult}.");
        }

        PrimitiveTopologyOwnerKey topologyOwnerKey = new(6, 1, rootRouterOffset, 0, prefixByte);
        object topologyOwner = GetPrimitiveTopologyOwner(topologyOwnerKey);
        try
        {
            lock (topologyOwner)
            {
                ReportPrimitiveTopologyOwnerEnteredForValidation(topologyOwnerKey);
                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        long currentTarget = FindRouterTarget(rootRouterOffset, prefixByte);
                        if (currentTarget != 0)
                        {
                            result = default;
                            return false;
                        }

                        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);
                        RouterReader existingReader = new(existingRouter);
                        if (existingReader.FindTarget(prefixByte) != 0)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                        preparedShelf.Bytes.AsSpan(0, profile.ShelfExtentSize).CopyTo(shelfReservation.Span);

                        byte[] updatedRouter = new byte[RouterLayout.Size];
                        existingRouter.CopyTo(updatedRouter, 0);
                        RouterWriter writer = new(updatedRouter);
                        writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                        InvalidateRouterReadCacheForRouterRewrite(rootRouterOffset);
                        kernel.StageWriteAt(rootRouterOffset, updatedRouter);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        result = new VarKeyScalar8RoutedInsertResult(
                            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                            VarKeyScalar8InsertResult.Inserted,
                            shelfReservation.Extent.Offset,
                            shelfReservation.Extent.Offset,
                            telemetry,
                            TargetShelfItemCount: 1,
                            TargetShelfExtentSize: profile.ShelfExtentSize);
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
        finally
        {
            preparedShelf.Release(clearShelfBytes: true);
        }
    }

    /// <summary>
    /// Publishes the first tuple for an unset route in any expanded direct `VS8` router.<br/>
    /// Same-depth replacement routers deliberately leave prefixes outside their parent-owned interval unset; this method lets the first future key for one of those sibling prefixes create an independent shelf instead of aliasing an existing ordered extent.<br/>
    /// Shelf construction occurs before the guarded publication section, which revalidates that the exact direct route is still unset before appending the shelf and rewriting the router page in one commit boundary.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset identifying the owning `VS8` index.<br/></param>
    /// <param name="routerOffset">The expanded direct router containing the unset route.<br/></param>
    /// <param name="prefixByte">The exact direct prefix route expected to be unset.<br/></param>
    /// <param name="profile">The initial shelf profile for the new sibling extent.<br/></param>
    /// <param name="key">The encoded key to place in the new shelf.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to place in the new shelf.<br/></param>
    /// <param name="allowDuplicateKeys">Whether different identities may share the encoded key.<br/></param>
    /// <param name="result">Receives the inserted routed outcome when publication succeeds.<br/></param>
    /// <returns><see langword="true"/> when this call initialized the route; false when another writer published it first.<br/></returns>
    private bool TryInsertVarKeyScalar8DirectColdRoute(
        long rootRouterOffset,
        long routerOffset,
        byte prefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        out VarKeyScalar8RoutedInsertResult result)
    {
        byte[] shelfBytes = VarKeyScalar8.CreateEmpty(profile);
        if (!VarKeyScalar8MutableShelf.TryCreate(shelfBytes, profile, ownsBytes: false, rentSidecars: false, out VarKeyScalar8MutableShelf preparedShelf))
            throw new InvalidDataException("The prepared VS8 child cold-route shelf is invalid.");

        VarKeyScalar8InsertResult insertResult = preparedShelf.InsertWithMutationHint(
            key,
            encodedIdentity,
            allowDuplicateKeys,
            hintStartDepth: 0,
            maxHintBytes: 0,
            out _);
        if (insertResult != VarKeyScalar8InsertResult.Inserted)
            throw new InvalidDataException($"Expected VS8 child cold-route shelf insert, got {insertResult}.");

        PrimitiveTopologyOwnerKey topologyOwnerKey = new(6, 7, rootRouterOffset, routerOffset, prefixByte);
        object topologyOwner = GetPrimitiveTopologyOwner(topologyOwnerKey);
        try
        {
            lock (topologyOwner)
            {
                ReportPrimitiveTopologyOwnerEnteredForValidation(topologyOwnerKey);
                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        byte[] routerBytes = new byte[RouterLayout.Size];
                        kernel.Read(routerOffset, routerBytes);
                        RouterReader reader = new(routerBytes);
                        if (!reader.IsValid || !reader.HasDirectIndex)
                            throw new InvalidDataException("The VS8 child cold-route parent is not a valid expanded direct router.");

                        if (reader.GetDirectTarget(prefixByte) != 0)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                        preparedShelf.Bytes.AsSpan(0, profile.ShelfExtentSize).CopyTo(shelfReservation.Span);
                        RawDataReservation routerRewrite = kernel.ReserveAt(routerOffset, RouterLayout.Size);
                        routerBytes.CopyTo(routerRewrite.Span);
                        RouterWriter writer = new(routerRewrite.Span);
                        writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                        InvalidateRouterReadCacheForRouterRewrite(routerOffset);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        result = new VarKeyScalar8RoutedInsertResult(
                            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                            VarKeyScalar8InsertResult.Inserted,
                            shelfReservation.Extent.Offset,
                            shelfReservation.Extent.Offset,
                            telemetry,
                            TargetShelfItemCount: 1,
                            TargetShelfExtentSize: profile.ShelfExtentSize,
                            TargetRouterDepth: reader.KeyDepth);
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
        finally
        {
            preparedShelf.Release(clearShelfBytes: true);
        }
    }

    /// <summary>
    /// Publishes the first tuple for an unset route in an expanded direct `VS16` exact-stem chain.<br/>
    /// Exact-stem transforms leave unrelated sibling prefixes unset so those prefixes can acquire independent ordered shelves instead of aliasing an existing extent.<br/>
    /// The prepared shelf is built before the guarded publication section; publication revalidates the exact route and commits the new shelf plus router rewrite atomically.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset identifying the owning `VS16` index.<br/></param>
    /// <param name="routerOffset">The expanded direct router containing the unset route.<br/></param>
    /// <param name="prefixByte">The exact direct prefix route expected to remain unset.<br/></param>
    /// <param name="profile">The initial shelf profile for the independent sibling extent.<br/></param>
    /// <param name="key">The encoded key to place in the new shelf.<br/></param>
    /// <param name="encodedIdentityHigh">The high 8 bytes of the encoded identity.<br/></param>
    /// <param name="encodedIdentityLow">The low 8 bytes of the encoded identity.<br/></param>
    /// <param name="allowDuplicateKeys">Whether different identities may share the encoded key.<br/></param>
    /// <param name="result">Receives the routed insert result when this call publishes the route.<br/></param>
    /// <returns><see langword="true"/> when this call initialized the route; otherwise false when another publisher won the race.<br/></returns>
    private bool TryInsertVarKeyScalar16DirectColdRoute(
        long rootRouterOffset,
        long routerOffset,
        byte prefixByte,
        VarKeyScalar16Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        out VarKeyScalar16RoutedInsertResult result)
    {
        byte[] shelfBytes = VarKeyScalar16.CreateEmpty(profile);
        if (!VarKeyScalar16MutableShelf.TryCreate(shelfBytes, profile, ownsBytes: false, rentSidecars: false, out VarKeyScalar16MutableShelf preparedShelf))
            throw new InvalidDataException("The prepared VS16 child cold-route shelf is invalid.");

        VarKeyScalar16InsertResult insertResult = preparedShelf.InsertWithMutationHint(
            key,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys,
            hintStartDepth: 0,
            maxHintBytes: 0,
            out _);
        if (insertResult != VarKeyScalar16InsertResult.Inserted)
            throw new InvalidDataException($"Expected VS16 child cold-route shelf insert, got {insertResult}.");

        PrimitiveTopologyOwnerKey topologyOwnerKey = new(6, 8, rootRouterOffset, routerOffset, prefixByte);
        object topologyOwner = GetPrimitiveTopologyOwner(topologyOwnerKey);
        try
        {
            lock (topologyOwner)
            {
                ReportPrimitiveTopologyOwnerEnteredForValidation(topologyOwnerKey);
                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        byte[] routerBytes = new byte[RouterLayout.Size];
                        kernel.Read(routerOffset, routerBytes);
                        RouterReader reader = new(routerBytes);
                        if (!reader.IsValid || !reader.HasDirectIndex)
                            throw new InvalidDataException("The VS16 child cold-route parent is not a valid expanded direct router.");

                        if (reader.GetDirectTarget(prefixByte) != 0)
                        {
                            result = default;
                            return false;
                        }

                        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
                        preparedShelf.Bytes.AsSpan(0, profile.ShelfExtentSize).CopyTo(shelfReservation.Span);
                        RawDataReservation routerRewrite = kernel.ReserveAt(routerOffset, RouterLayout.Size);
                        routerBytes.CopyTo(routerRewrite.Span);
                        RouterWriter writer = new(routerRewrite.Span);
                        writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);
                        InvalidateRouterReadCacheForRouterRewrite(routerOffset);
                        DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        result = new VarKeyScalar16RoutedInsertResult(
                            VarKeyScalar16RoutedInsertKind.WalkedNoSplit,
                            VarKeyScalar16InsertResult.Inserted,
                            shelfReservation.Extent.Offset,
                            shelfReservation.Extent.Offset,
                            telemetry,
                            TargetShelfItemCount: 1,
                            TargetShelfExtentSize: profile.ShelfExtentSize,
                            TargetRouterDepth: reader.KeyDepth);
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }
        }
        finally
        {
            preparedShelf.Release(clearShelfBytes: true);
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer `VS8` shelf-growth publisher for one full routed shelf.<br/>
    /// Growth planning and shelf construction happen before this helper; the guarded section only rechecks the parent route, reserves the grown shelf, rewrites the route target, and commits the publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `VS8` index.<br/></param>
    /// <param name="parentRouterOffset">The parent router that currently points at the old shelf.<br/></param>
    /// <param name="routeIndex">The parent-router route index to recheck and rewrite.<br/></param>
    /// <param name="oldShelfOffset">The full shelf currently reached by the route walker.<br/></param>
    /// <param name="oldProfile">The old shelf profile used to release memory-backed extents after publication.<br/></param>
    /// <param name="grownProfile">The grown shelf profile.<br/></param>
    /// <param name="grownShelf">The full grown shelf image to publish.<br/></param>
    /// <param name="telemetry">Receives commit telemetry when the grown shelf is published.<br/></param>
    /// <param name="newShelfOffset">Receives the new grown shelf offset when publication succeeds.<br/></param>
    /// <returns><see langword="true"/> when the parent route still pointed at <paramref name="oldShelfOffset"/> and the grown shelf was published.</returns>
    private bool TryPublishVarKeyScalar8DirectShelfGrowth(
        long rootRouterOffset,
        long parentRouterOffset,
        int routeIndex,
        long oldShelfOffset,
        VarKeyScalar8Profile oldProfile,
        VarKeyScalar8Profile grownProfile,
        ReadOnlySpan<byte> grownShelf,
        out DataKernelCommitTelemetry telemetry,
        out long newShelfOffset)
    {
        telemetry = default;
        newShelfOffset = 0;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(6, 2, rootRouterOffset, oldShelfOffset, routeIndex));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    byte[] parentRouterBytes = new byte[RouterLayout.Size];
                    kernel.Read(parentRouterOffset, parentRouterBytes);
                    RouterReader parentReader = new(parentRouterBytes);
                    if (!parentReader.IsValid)
                    {
                        throw new InvalidDataException("The VS8 growth parent router is invalid.");
                    }

                    if (parentReader.GetRouteTargetAt(routeIndex) != oldShelfOffset)
                    {
                        return false;
                    }

                    RawDataReservation grownReservation = kernel.Reserve(grownProfile.ShelfExtentSize);
                    grownShelf.CopyTo(grownReservation.Span);
                    RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
                    parentRouterBytes.CopyTo(parentRouterRewrite.Span);
                    RouterWriter parentWriter = new(parentRouterRewrite.Span);
                    parentWriter.WriteRouteTarget(routeIndex, grownReservation.Extent.Offset);

                    InvalidateRouterReadCacheForRouterRewrite(parentRouterOffset);
                    telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    kernel.ReleaseMemoryExtent(oldShelfOffset, oldProfile.ShelfExtentSize);
                    newShelfOffset = grownReservation.Extent.Offset;
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Attempts the narrow direct-writer `VS8` shelf-transform publisher for one full routed shelf.<br/>
    /// Split shelf planning happens before this helper; the guarded section rechecks the parent route, appends the replacement shelves, rewrites the old shelf offset as a child router, and commits the publication.<br/>
    /// A false return means another writer changed the parent route before publication, so the caller should retry against the current route topology.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset that identifies the routed `VS8` index.<br/></param>
    /// <param name="parentRouterOffset">The parent router that currently points at the full shelf.<br/></param>
    /// <param name="routeIndex">The parent-router route index to recheck before publication.<br/></param>
    /// <param name="childRouterOffset">The full shelf offset that will be rewritten as the replacement child router.<br/></param>
    /// <param name="parentHasDirectIndex">Whether the planned parent route uses the expanded direct-index representation.<br/></param>
    /// <param name="parentRangeStart">The planned inclusive prefix start of the parent target's logical route range.<br/></param>
    /// <param name="parentRangeEnd">The planned inclusive prefix end of the parent target's logical route range.<br/></param>
    /// <param name="parentFinalKeyDepth">The final raw-key byte depth consumed by the planned parent route.<br/></param>
    /// <param name="allocationClassId">The allocation class identifier to preserve in replacement routers.<br/></param>
    /// <param name="childRouterKeyDepth">The raw-key byte depth owned by the replacement child router.<br/></param>
    /// <param name="splitKeyDepth">The raw-key byte depth selected for the split boundary.<br/></param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.<br/></param>
    /// <param name="selectedPrefixStem">The common prefix stem between the child-router depth and selected split depth.<br/></param>
    /// <param name="routeMutationHint">The recent route mutation hint used to choose the child-router encoding shape.<br/></param>
    /// <param name="profile">The `VS8` shelf profile used by the replacement shelves.<br/></param>
    /// <param name="leftShelfBytes">The populated left replacement shelf image.<br/></param>
    /// <param name="rightShelfBytes">The populated right replacement shelf image.<br/></param>
    /// <param name="telemetry">Receives commit telemetry when the transform is published.<br/></param>
    /// <param name="leftShelfOffset">Receives the appended left replacement shelf offset.<br/></param>
    /// <param name="rightShelfOffset">Receives the appended right replacement shelf offset.<br/></param>
    /// <returns><see langword="true"/> when the parent route still pointed at <paramref name="childRouterOffset"/> and the transform was published.</returns>
    private bool TryPublishVarKeyScalar8DirectShelfTransform(
        long rootRouterOffset,
        long parentRouterOffset,
        int routeIndex,
        long childRouterOffset,
        bool parentHasDirectIndex,
        int parentRangeStart,
        int parentRangeEnd,
        ushort parentFinalKeyDepth,
        ushort allocationClassId,
        ushort childRouterKeyDepth,
        ushort splitKeyDepth,
        byte selectedRightPrefixByte,
        ReadOnlySpan<byte> selectedPrefixStem,
        VarKeyScalar8RouteMutationHint routeMutationHint,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> leftShelfBytes,
        ReadOnlySpan<byte> rightShelfBytes,
        out DataKernelCommitTelemetry telemetry,
        out long leftShelfOffset,
        out long rightShelfOffset)
    {
        telemetry = default;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        object topologyOwner = GetPrimitiveTopologyOwner(new PrimitiveTopologyOwnerKey(6, 3, rootRouterOffset, childRouterOffset, parentRangeStart));
        lock (topologyOwner)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    byte[] parentRouterBytes = new byte[RouterLayout.Size];
                    kernel.Read(parentRouterOffset, parentRouterBytes);
                    RouterReader parentReader = new(parentRouterBytes);
                    if (!parentReader.IsValid)
                    {
                        throw new InvalidDataException("The VS8 transform parent router is invalid.");
                    }

                    if (!TryGetVarKeyParentTargetRange(
                        parentReader,
                        routeIndex,
                        childRouterOffset,
                        out bool currentParentHasDirectIndex,
                        out int currentParentRangeStart,
                        out int currentParentRangeEnd,
                        out ushort currentParentFinalKeyDepth) ||
                        currentParentHasDirectIndex != parentHasDirectIndex ||
                        currentParentRangeStart != parentRangeStart ||
                        currentParentRangeEnd != parentRangeEnd ||
                        currentParentFinalKeyDepth != parentFinalKeyDepth)
                    {
                        return false;
                    }

                    if (parentHasDirectIndex &&
                        parentRangeStart < parentRangeEnd &&
                        splitKeyDepth == parentFinalKeyDepth)
                    {
                        if (selectedRightPrefixByte <= parentRangeStart || selectedRightPrefixByte > parentRangeEnd)
                        {
                            throw new InvalidDataException($"The VS8 parent-range split boundary {selectedRightPrefixByte} is outside owning direct route run {parentRangeStart}-{parentRangeEnd} at depth {parentFinalKeyDepth}; childDepth={childRouterKeyDepth}, splitDepth={splitKeyDepth}.");
                        }

                        RawDataReservation leftRewrite = kernel.ReserveAt(childRouterOffset, profile.ShelfExtentSize);
                        leftShelfBytes.CopyTo(leftRewrite.Span);
                        RawDataReservation parentRightAppend = kernel.Reserve(profile.ShelfExtentSize);
                        rightShelfBytes.CopyTo(parentRightAppend.Span);
                        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
                        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
                        RouterWriter parentWriter = new(parentRouterRewrite.Span);
                        for (int prefix = parentRangeStart; prefix <= parentRangeEnd; prefix++)
                        {
                            byte prefixByte = (byte)prefix;
                            parentWriter.WriteRouteTarget(
                                prefix,
                                prefixByte < selectedRightPrefixByte ? childRouterOffset : parentRightAppend.Extent.Offset);
                        }

                        varKeyScalar8ReadShelfCache.TryRemove(childRouterOffset, out _);
                        InvalidateRouterReadCacheForRouterRewrite(parentRouterOffset);
                        telemetry = CommitAndDeferRouterReadCacheInvalidation();
                        leftShelfOffset = childRouterOffset;
                        rightShelfOffset = parentRightAppend.Extent.Offset;
                        return true;
                    }

                    RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
                    leftShelfBytes.CopyTo(leftAppend.Span);
                    RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    rightShelfBytes.CopyTo(rightAppend.Span);

                    RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
                    RouterWriter childWriter = new(childRouterRewrite.Span);
                    VarKeyScalar8TransformRouterPlan routerPlan = parentRangeStart < parentRangeEnd && splitKeyDepth > childRouterKeyDepth
                        ? VarKeyScalar8TransformRouterPlan.ExpandedOneByteChain
                        : ChooseVarKeyScalar8TransformRouterPlan(childRouterKeyDepth, splitKeyDepth, selectedPrefixStem, routeMutationHint);
                    if (routerPlan.Kind == VarKeyScalar8TransformRouterKind.ExpandedOneByte)
                    {
                        long[] directTargets = CreateUniformScalar8Scalar8RouteTargets(0, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte);
                        if (childRouterKeyDepth == parentFinalKeyDepth && parentRangeStart < parentRangeEnd)
                        {
                            directTargets.AsSpan(0, parentRangeStart).Clear();
                            directTargets.AsSpan(parentRangeEnd + 1).Clear();
                        }

                        childWriter.InitializeExpandedOneByte(
                            childRouterKeyDepth,
                            allocationClassId,
                            directTargets);
                    }
                    else if (routerPlan.Kind == VarKeyScalar8TransformRouterKind.CompressedMultiByte)
                    {
                        RouterMultiByteRouteSnapshot[] routes =
                        [
                            new(routerPlan.PrefixStem, 0, checked((byte)(selectedRightPrefixByte - 1)), leftAppend.Extent.Offset),
                            new(routerPlan.PrefixStem, selectedRightPrefixByte, byte.MaxValue, rightAppend.Extent.Offset)
                        ];
                        childWriter.InitializeCompressedMultiByte(
                            routerPlan.PrefixByteCount,
                            childRouterKeyDepth,
                            maxRouteCount: 2,
                            allocationClassId,
                            routes);
                    }
                    else
                    {
                        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
                        long nextRouterOffset = 0;
                        for (int i = appendedRouterCount - 1; i >= 0; i--)
                        {
                            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
                            long[] targets = routerDepth == splitKeyDepth
                                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                                : CreateVarKeyScalar8IntermediateSplitRouteTargets(
                                    nextRouterOffset,
                                    leftAppend.Extent.Offset,
                                    rightAppend.Extent.Offset,
                                    selectedPrefixStem[routerDepth - childRouterKeyDepth]);
                            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                            RouterWriter appendedWriter = new(appendedRouter.Span);
                            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
                            nextRouterOffset = appendedRouter.Extent.Offset;
                        }

                        long[] childTargets = CreateVarKeyScalar8IntermediateSplitRouteTargets(
                            nextRouterOffset,
                            leftAppend.Extent.Offset,
                            rightAppend.Extent.Offset,
                            selectedPrefixStem[0]);
                        if (childRouterKeyDepth == parentFinalKeyDepth && parentRangeStart < parentRangeEnd)
                        {
                            childTargets.AsSpan(0, parentRangeStart).Clear();
                            childTargets.AsSpan(parentRangeEnd + 1).Clear();
                        }

                        childWriter.InitializeExpandedOneByte(childRouterKeyDepth, allocationClassId, childTargets);
                    }

                    int varKeyScalar8RouterArenaLength = profile.ShelfExtentSize;
                    childWriter.WriteArenaMetadata(
                        arenaBaseDelta: 0,
                        arenaLength: varKeyScalar8RouterArenaLength,
                        routerPageSize: checked((ushort)RouterLayout.Size),
                        routerPageIndex: 0,
                        routerPageCount: checked((ushort)(varKeyScalar8RouterArenaLength / RouterLayout.Size)),
                        arenaFlags: varKeyScalar8RouterArenaLength > ushort.MaxValue + 1 ? RouterLayout.ArenaLengthFromPageCountFlag : 0);

                    InvalidateRouterReadCacheForRouterRewrite(childRouterOffset);
                    telemetry = CommitAndDeferRouterReadCacheInvalidation();
                    RouterArenaState arena = RegisterRouterArena(childRouterOffset, varKeyScalar8RouterArenaLength);
                    arena.MarkUsed(0);
                    leftShelfOffset = leftAppend.Extent.Offset;
                    rightShelfOffset = rightAppend.Extent.Offset;
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    /// <summary>
    /// Resolves the logical prefix range owned by one variable-key parent route target without allocating or materializing route records.<br/>
    /// Expanded direct routers collapse the contiguous same-target slot run around <paramref name="routeIndex"/>; compressed routers use the selected route's persisted inclusive prefix range.<br/>
    /// The method also returns the final key-byte depth consumed by the parent route so a shared range can be split at that byte instead of incorrectly advancing past it.<br/>
    /// </summary>
    /// <param name="parentReader">The validated parent router view.<br/></param>
    /// <param name="routeIndex">The physical route slot selected by the walked key.<br/></param>
    /// <param name="targetOffset">The shelf target expected at the selected route.<br/></param>
    /// <param name="hasDirectIndex">Receives whether the parent uses the expanded direct-index representation.<br/></param>
    /// <param name="rangeStart">Receives the inclusive final-byte prefix start owned by the target.<br/></param>
    /// <param name="rangeEnd">Receives the inclusive final-byte prefix end owned by the target.<br/></param>
    /// <param name="finalKeyDepth">Receives the raw-key byte depth represented by <paramref name="rangeStart"/> and <paramref name="rangeEnd"/>.<br/></param>
    /// <returns><see langword="true"/> when the selected route still points at <paramref name="targetOffset"/> and its logical range is valid; otherwise <see langword="false"/>.<br/></returns>
    private static bool TryGetVarKeyParentTargetRange(
        RouterReader parentReader,
        int routeIndex,
        long targetOffset,
        out bool hasDirectIndex,
        out int rangeStart,
        out int rangeEnd,
        out ushort finalKeyDepth)
    {
        hasDirectIndex = parentReader.HasDirectIndex;
        rangeStart = 0;
        rangeEnd = 0;
        finalKeyDepth = checked((ushort)(parentReader.KeyDepth + parentReader.PrefixByteCount - 1));
        int routeCount = hasDirectIndex ? RouterLayout.MaxOneByteRouteCount : parentReader.RouteCount;
        if ((uint)routeIndex >= (uint)routeCount || parentReader.GetRouteTargetAt(routeIndex) != targetOffset)
            return false;

        if (!hasDirectIndex)
        {
            rangeStart = parentReader.GetRoutePrefixStartAt(routeIndex);
            rangeEnd = parentReader.GetRoutePrefixEndAt(routeIndex);
            return rangeStart <= rangeEnd;
        }

        rangeStart = routeIndex;
        while (rangeStart > 0 && parentReader.GetRouteTargetAt(rangeStart - 1) == targetOffset)
            rangeStart--;

        rangeEnd = routeIndex;
        while (rangeEnd + 1 < RouterLayout.MaxOneByteRouteCount && parentReader.GetRouteTargetAt(rangeEnd + 1) == targetOffset)
            rangeEnd++;

        for (int prefix = 0; prefix < rangeStart; prefix++)
        {
            if (parentReader.GetRouteTargetAt(prefix) == targetOffset)
                throw new InvalidDataException("The variable-key parent router contains a noncontiguous target alias before the selected route run.");
        }

        for (int prefix = rangeEnd + 1; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            if (parentReader.GetRouteTargetAt(prefix) == targetOffset)
                throw new InvalidDataException("The variable-key parent router contains a noncontiguous target alias after the selected route run.");
        }

        return true;
    }

    /// <summary>
    /// Creates a prebuilt `VS8` shelf and links one root-router prefix to it.<br/>
    /// This supports bulk construction where sorted varlen-key rows are compacted into their final shelf image before touching the DataKernel.<br/>
    /// The supplied bytes are validated before publication so callers cannot link arbitrary payloads into a routed varlen-key index.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset to update.</param>
    /// <param name="prefixByte">The root prefix byte that should point at the new shelf.</param>
    /// <param name="profile">The `VS8` shelf profile used to validate and reserve the shelf extent.</param>
    /// <param name="shelfBytes">The complete prebuilt shelf image.</param>
    /// <returns>The created shelf offset and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied shelf image length does not match the profile.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid, not direct-index capable, or the shelf bytes are invalid.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateVarKeyScalar8ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The prebuilt VS8 shelf image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        VarKeyScalar8ReadOnly readOnly = new(shelfBytes.ToArray(), profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The prebuilt VS8 shelf image is invalid.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Creates a prebuilt `VS8` shelf without linking it to any router route.<br/>
    /// Bulk construction uses this to append final shelf images first, then wire those shelves through the chosen router shape in a separate cold step.<br/>
    /// The supplied bytes are validated against the profile before reservation so malformed payloads cannot enter the routed varlen-key graph.<br/>
    /// </summary>
    /// <param name="profile">The `VS8` shelf profile used to validate and reserve the shelf extent.</param>
    /// <param name="shelfBytes">The complete prebuilt shelf image.</param>
    /// <returns>The created shelf offset and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied shelf image length does not match the profile.</exception>
    /// <exception cref="InvalidDataException">Thrown when the shelf bytes are invalid.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateVarKeyScalar8Shelf(
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The prebuilt VS8 shelf image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        VarKeyScalar8ReadOnly readOnly = new(shelfBytes.ToArray(), profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The prebuilt VS8 shelf image is invalid.");
        }

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfReservation.Extent.Offset, telemetry);
    }

    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateVarKeyScalar16ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        VarKeyScalar16Profile profile)
    {
        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        byte[] shelfBytes = VarKeyScalar16.CreateEmpty(profile);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        shelfBytes.CopyTo(shelfReservation.Span);

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

