    /// <summary>
    /// Routes one prefix byte through a persisted root router and reads the targeted `SS8-8` shelf bytes into a caller buffer.<br/>
    /// This validation helper deliberately performs the two physical reads separately: root router first, then shelf extent.<br/>
    /// Later cache-aware paths can replace this shape, but this method exposes the current routed read syscall pattern clearly.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte to route.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The routed shelf offset that was read into <paramref name="destination"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `SS8-8` shelf.</exception>
    internal long ReadRoutedScalar8Scalar8Shelf(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar8Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled SS8-8 shelf extent size.", nameof(destination));
        }

        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 shelf route is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Scalar8Scalar8ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 shelf bytes are invalid.");
        }

        return shelfOffset;
    }

    /// <summary>
    /// Appends a sorted `Scalar16Scalar8` shelf and links one root-router prefix byte to the new shelf in the same commit.<br/>
    /// The shelf is initialized with deterministic `(keyHigh, keyLow, identity)` tuples where the high key half is zero and the low key half plus identity equal the insert index.<br/>
    /// This mirrors the first `SS8-8` router-to-shelf primitive while keeping the widened-key shelf isolated from routed mutation and split code.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte route to link to the new shelf.</param>
    /// <param name="profile">The `SS16-8` shelf profile used to size and populate the shelf extent.</param>
    /// <param name="itemCount">The number of deterministic sorted tuples to insert into the shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="itemCount"/> is outside the profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid, not direct-index capable, or shelf population fails.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar16Scalar8ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Scalar16Scalar8Profile profile,
        int itemCount)
    {
        if (itemCount < 0 || itemCount > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(itemCount), itemCount, "SS16-8 shelf item count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar16Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < itemCount; i++)
        {
            Scalar16Scalar8Layout.EncodeUnsignedScalar16FromUInt64((ulong)i, out ulong keyHigh, out ulong keyLow);
            Scalar16Scalar8InsertResult result = shelf.Insert(
                keyHigh,
                keyLow,
                Scalar16Scalar8Layout.EncodeUnsignedScalar8((ulong)i),
                allowDuplicateKeys: true);
            if (result != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-8 routed shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Routes one prefix byte through a persisted root router and reads the targeted `SS16-8` shelf bytes into a caller buffer.<br/>
    /// This validation helper deliberately performs the two physical reads separately: root router first, then shelf extent.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte to route.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The routed shelf offset that was read into <paramref name="destination"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `SS16-8` shelf.</exception>
    internal long ReadRoutedScalar16Scalar8Shelf(
        long rootRouterOffset,
        byte prefixByte,
        Scalar16Scalar8Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled SS16-8 shelf extent size.", nameof(destination));
        }

        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS16-8 shelf route is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Scalar16Scalar8ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed SS16-8 shelf bytes are invalid.");
        }

        return shelfOffset;
    }

    /// <summary>
    /// Appends a sorted `Fixed32Scalar8` shelf and links one root-router prefix byte to the new shelf in the same commit.<br/>
    /// The shelf is initialized with deterministic `(key0, key1, key2, key3, identity)` tuples where the key suffix plus identity equal the insert index.<br/>
    /// This mirrors the first `SS16-8` router-to-shelf primitive while keeping the fixed 32-byte key shelf isolated from split code.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte route to link to the new shelf.</param>
    /// <param name="profile">The `FS32-8` shelf profile used to size and populate the shelf extent.</param>
    /// <param name="itemCount">The number of deterministic sorted tuples to insert into the shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="itemCount"/> is outside the profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid, not direct-index capable, or shelf population fails.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar8ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar8Profile profile,
        int itemCount)
    {
        if (itemCount < 0 || itemCount > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(itemCount), itemCount, "FS32-8 shelf item count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < itemCount; i++)
        {
            Fixed32Scalar8Layout.EncodeFixed32FromUInt64((ulong)i, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
            Fixed32Scalar8InsertResult result = shelf.Insert(
                key0,
                key1,
                key2,
                key3,
                Fixed32Scalar8Layout.EncodeUnsignedScalar8((ulong)i),
                allowDuplicateKeys: true);
            if (result != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-8 routed shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

