        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar16Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeyHighs.Length; i++)
        {
            Scalar16Scalar8InsertResult result = shelf.Insert(encodedKeyHighs[i], encodedKeyLows[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-8 setup shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRoutesToShelf(rootRouterOffset, existingRouter, prefixBytes, shelfReservation.Extent.Offset);
