        Fixed32Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar8InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
