        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar8 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = (byte)(key0s[i] >> 56) >= rightPrefixByte;
            Fixed32Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
