    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar8ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Fixed32Scalar8Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled FS32-8 shelf extent size.", nameof(existingShelfBytes));
        }

        Fixed32Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full FS32-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        Fixed32BatchAttributionDiagnostics? transformAttribution = Fixed32BatchAttributionDiagnostics.Current;
        long transformPhaseStart = transformAttribution is null ? 0 : Stopwatch.GetTimestamp();
        int mergedCount = existingCount + 1;
        ulong[] key0Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key1Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key2Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key3Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] identityBuffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        byte[] leftShelfBuffer = ArrayPool<byte>.Shared.Rent(profile.ShelfExtentSize);
        byte[] rightShelfBuffer = ArrayPool<byte>.Shared.Rent(profile.ShelfExtentSize);
        Span<ulong> key0s = key0Buffer.AsSpan(0, mergedCount);
        Span<ulong> key1s = key1Buffer.AsSpan(0, mergedCount);
        Span<ulong> key2s = key2Buffer.AsSpan(0, mergedCount);
        Span<ulong> key3s = key3Buffer.AsSpan(0, mergedCount);
        Span<ulong> identities = identityBuffer.AsSpan(0, mergedCount);
        Span<byte> leftShelfBytes = leftShelfBuffer.AsSpan(0, profile.ShelfExtentSize);
        Span<byte> rightShelfBytes = rightShelfBuffer.AsSpan(0, profile.ShelfExtentSize);
        try
        {
            bool inserted = false;
            int targetIndex = 0;
            for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
            {
                ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
                ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
                ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
                ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
                ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
                if (!inserted && CompareFixed32Scalar8Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentity, key0, key1, key2, key3, encodedIdentity) > 0)
                {
                    key0s[targetIndex] = key0;
                    key1s[targetIndex] = key1;
                    key2s[targetIndex] = key2;
                    key3s[targetIndex] = key3;
                    identities[targetIndex] = encodedIdentity;
                    targetIndex++;
                    inserted = true;
                }

                if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentity == encodedIdentity)
                {
                    return (childRouterOffset, 0, 0, existingCount, 0, Fixed32Scalar8InsertResult.AlreadyPresent, default);
                }

                key0s[targetIndex] = currentKey0;
                key1s[targetIndex] = currentKey1;
                key2s[targetIndex] = currentKey2;
                key3s[targetIndex] = currentKey3;
                identities[targetIndex] = currentIdentity;
                targetIndex++;
            }

            if (!inserted)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identities[targetIndex] = encodedIdentity;
            }

            if (transformAttribution is not null)
            {
                long phaseEnd = Stopwatch.GetTimestamp();
                transformAttribution.TransformMergeTicks += phaseEnd - transformPhaseStart;
                transformPhaseStart = phaseEnd;
            }

            (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseFixed32Scalar8TransformSplitPlan(key0s, key1s, key2s, key3s, childRouterKeyDepth, rightPrefixByte);
            if (transformAttribution is not null)
            {
                long phaseEnd = Stopwatch.GetTimestamp();
                transformAttribution.TransformPlanTicks += phaseEnd - transformPhaseStart;
                transformPhaseStart = phaseEnd;
            }

            Fixed32Scalar8 leftShelf = new(leftShelfBytes, profile);
            Fixed32Scalar8 rightShelf = new(rightShelfBytes, profile);
            leftShelf.Initialize();
            rightShelf.Initialize();

            for (int i = 0; i < mergedCount; i++)
            {
            bool goesRight = GetFixed32Scalar8Prefix(key0s[i], key1s[i], key2s[i], key3s[i], splitKeyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar8InsertResult result = goesRight
                ? rightShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identities[i])
                : leftShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identities[i]);
                if (result != Fixed32Scalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected transform split FS32-8 insert at {i}, got {result}.");
                }
            }

            if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
            {
                throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
            }

            if (transformAttribution is not null)
            {
                long phaseEnd = Stopwatch.GetTimestamp();
                transformAttribution.TransformShelfBuildTicks += phaseEnd - transformPhaseStart;
                transformPhaseStart = phaseEnd;
            }

            RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
            leftShelfBytes.CopyTo(leftAppend.Span);
            RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
            rightShelfBytes.CopyTo(rightAppend.Span);

            if (transformAttribution is not null)
            {
                long phaseEnd = Stopwatch.GetTimestamp();
                transformAttribution.TransformShelfCopyTicks += phaseEnd - transformPhaseStart;
                transformPhaseStart = phaseEnd;
            }

            int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
            long nextRouterOffset = 0;
            for (int i = appendedRouterCount - 1; i >= 0; i--)
            {
                ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
                RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                RouterWriter appendedWriter = new(appendedRouter.Span);
                if (routerDepth == splitKeyDepth)
                    appendedWriter.InitializeExpandedOneByteSplit(routerDepth, allocationClassId, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte);
                else
                    appendedWriter.InitializeExpandedOneByteUniform(routerDepth, allocationClassId, nextRouterOffset);
                nextRouterOffset = appendedRouter.Extent.Offset;
            }

            RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
            RouterWriter childWriter = new(childRouterRewrite.Span);
            if (nextRouterOffset != 0)
                childWriter.InitializeExpandedOneByteUniform(childRouterKeyDepth, allocationClassId, nextRouterOffset);
            else
                childWriter.InitializeExpandedOneByteSplit(childRouterKeyDepth, allocationClassId, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte);
            int routerArenaLength = Math.Min(profile.ShelfExtentSize, 64 * 1024);
            childWriter.WriteArenaMetadata(
                arenaBaseDelta: 0,
                arenaLength: routerArenaLength,
                routerPageSize: checked((ushort)RouterLayout.Size),
                routerPageIndex: 0,
                routerPageCount: checked((ushort)(routerArenaLength / RouterLayout.Size)),
                arenaFlags: 0);

            if (transformAttribution is not null)
            {
                long phaseEnd = Stopwatch.GetTimestamp();
                transformAttribution.TransformRouterBuildTicks += phaseEnd - transformPhaseStart;
                transformPhaseStart = phaseEnd;
            }

            int leftItemCount = leftShelf.ItemCount;
            int rightItemCount = rightShelf.ItemCount;
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            if (transformAttribution is not null)
            {
                transformAttribution.TransformCommitTicks += Stopwatch.GetTimestamp() - transformPhaseStart;
            }
            RouterArenaState arena = RegisterRouterArena(childRouterOffset, routerArenaLength);
            arena.MarkUsed(0);
            return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftItemCount, rightItemCount, Fixed32Scalar8InsertResult.Inserted, telemetry);
        }
        finally
        {
            ArrayPool<ulong>.Shared.Return(key0Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key1Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key2Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key3Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(identityBuffer, clearArray: false);
            ArrayPool<byte>.Shared.Return(leftShelfBuffer, clearArray: false);
            ArrayPool<byte>.Shared.Return(rightShelfBuffer, clearArray: false);
        }
    }

    /// <summary>
    /// Splits a full routed `SS16-16` shelf by transforming the shelf's existing offset into a child router and appending two replacement shelves.<br/>
    /// This path covers same-root-prefix widened-key and widened-identity splits where the root route must stay stable and the next key byte decides left/right ownership.<br/>
    /// The parent root router is not dirtied; the former shelf location is structurally reused as a direct-index one-byte child router at key depth `1`.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root prefix byte that currently routes to the full shelf and will continue routing to the transformed child router.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar16Scalar16ByShelfTransform(
            long rootRouterOffset,
            byte rootPrefixByte,
            byte rightPrefixByte,
            Scalar16Scalar16Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow)
    {
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootRouterReader = new(rootRouterBytes);
        if (!rootRouterReader.IsValid || !rootRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        ushort allocationClassId = rootRouterReader.AllocationClassId;
        long childRouterOffset = rootRouterReader.FindTarget(rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The routed SS16-16 transform source route is unset.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(childRouterOffset, existingShelfBytes);
        return SplitRoutedScalar16Scalar16ByShelfTransform(
            childRouterOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            allocationClassId,
            childRouterKeyDepth: 1);
    }

    /// <summary>
    /// Builds the replacement shelf images and route split plan for an `SS16-16` same-prefix transform without touching storage publication state.<br/>
    /// The caller can run this under a root topology gate, then publish the returned bytes in a short storage-publication section.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full existing shelf bytes.<br/></param>
    /// <param name="rightPrefixByte">The incoming tuple prefix byte at <paramref name="childRouterKeyDepth"/>.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.<br/></param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.<br/></param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.<br/></param>
    /// <param name="build">The prepared split image and router plan when the method succeeds.<br/></param>
    /// <returns>True when a transform split plan was built; false for no-op/conflict results.<br/></returns>
    private static bool TryBuildScalar16Scalar16TransformSplit(
        ReadOnlySpan<byte> existingShelfBytes,
        byte rightPrefixByte,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        ushort allocationClassId,
        ushort childRouterKeyDepth,
        out Scalar16Scalar16TransformSplitBuild build)
    {
        build = default;
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS16-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar16Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS16-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar16Tuple(currentKeyHigh, currentKeyLow, currentIdentityHigh, currentIdentityLow, encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                build = new Scalar16Scalar16TransformSplitBuild(
                    0,
                    0,
                    [],
                    [],
                    existingCount,
                    0,
                    Scalar16Scalar16InsertResult.AlreadyPresent,
                    allocationClassId,
                    childRouterKeyDepth,
                    0);
                return false;
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar16Scalar8TransformSplitPlan(keyHighs, keyLows, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS16-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        build = new Scalar16Scalar16TransformSplitBuild(
            splitKeyDepth,
            selectedRightPrefixByte,
            leftShelfBytes,
            rightShelfBytes,
            leftShelf.ItemCount,
            rightShelf.ItemCount,
            Scalar16Scalar16InsertResult.Inserted,
            allocationClassId,
            childRouterKeyDepth,
            profile.ShelfExtentSize);
        return true;
    }

    /// <summary>
    /// Splits an already-routed full `SS16-16` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar16Scalar16ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Scalar16Scalar16Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS16-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar16Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS16-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar16Tuple(currentKeyHigh, currentKeyLow, currentIdentityHigh, currentIdentityLow, encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Scalar16Scalar16InsertResult.AlreadyPresent, default);
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar16Scalar8TransformSplitPlan(keyHighs, keyLows, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS16-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar16Scalar16InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Inserts one encoded tuple through the current rooted `SS8-8` routing graph and selects the first supported structural mutation path.<br/>
    /// The decision order is no-split shelf rewrite, root-prefix-visible split when an earlier root prefix still targets the same full shelf, then same-prefix shelf-to-router transform.<br/>
    /// This first orchestrator intentionally handles only the currently validated split shapes and does not claim general route-range refinement yet.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route graph is invalid or the full-shelf split path cannot be selected safely.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertRoutedScalar8Scalar8(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        byte rootPrefixByte = GetScalar8Scalar8RootPrefix(encodedKey);
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootReader = new(rootRouterBytes);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        long shelfOffset = rootReader.FindTarget(rootPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult noSplitResult = shelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);

        if (noSplitResult == Scalar8Scalar8InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry noSplitCommit = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoSplit,
                noSplitResult,
                shelfOffset,
                shelfOffset,
                0,
                noSplitCommit);
        }

        if (noSplitResult == Scalar8Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                noSplitResult,
                shelfOffset,
                0,
                0,
                default);
        }

        if (noSplitResult == Scalar8Scalar8InsertResult.KeyConflict)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.KeyConflict,
                noSplitResult,
                shelfOffset,
                0,
                0,
                default);
        }

        if (noSplitResult != Scalar8Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS8-8 routed insert result {noSplitResult}.");
        }

        byte leftRootPrefix = FindEarlierRootPrefixForSameTarget(rootReader, rootPrefixByte, shelfOffset);
        if (leftRootPrefix != rootPrefixByte)
        {
            (
                long leftShelfOffset,
                long rightShelfOffset,
                _,
                _,
                Scalar8Scalar8InsertResult splitResult,
                DataKernelCommitTelemetry splitCommit) = SplitRoutedScalar8Scalar8ByRootPrefix(
                    rootRouterOffset,
                    rootRouterBytes,
                    shelfOffset,
                    existingShelf,
                    rootPrefixByte,
                    profile,
                    encodedKey,
                    encodedIdentity);

            Scalar8Scalar8RoutedInsertKind kind = splitResult == Scalar8Scalar8InsertResult.Inserted
                ? Scalar8Scalar8RoutedInsertKind.RootPrefixSplit
                : Scalar8Scalar8RoutedInsertKind.NoOp;
            return new Scalar8Scalar8RoutedInsertResult(
                kind,
                splitResult,
                leftShelfOffset,
                leftShelfOffset,
                rightShelfOffset,
                splitCommit);
        }

        byte childRightPrefix = GetScalar8Scalar8Prefix(encodedKey, keyDepth: 1);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar8ByShelfTransform(
                shelfOffset,
                existingShelf,
                childRightPrefix,
                profile,
                encodedKey,
                encodedIdentity,
                rootReader.AllocationClassId,
                childRouterKeyDepth: 1);

        Scalar8Scalar8RoutedInsertKind transformKind = transformResult == Scalar8Scalar8InsertResult.Inserted
            ? Scalar8Scalar8RoutedInsertKind.ShelfTransformSplit
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            transformKind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-8` shelf and links multiple root-router prefix bytes to that same shelf in one commit.<br/>
    /// This helper exists for split-path validation where a single full shelf initially owns more than one root prefix byte.<br/>
    /// The supplied key and identity vectors are inserted through the shelf view, so persisted ordering and duplicate rules match normal shelf behavior.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <param name="prefixBytes">The root-router prefix bytes to point at the new shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfAndLinkRootRoutes(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentities,
        ReadOnlySpan<byte> prefixBytes)
    {
        if (encodedKeys.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS8-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 setup shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRoutesToShelf(rootRouterOffset, existingRouter, prefixBytes, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-8` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive creates a controlled deeper route graph where one child-router prefix owns a full shelf, allowing walked split behavior to be measured directly.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (encodedKeys.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS8-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-8` shelf behind a new direct-index child router and links multiple child prefixes to that same shelf.<br/>
    /// This validation primitive creates the parent-route split shape directly: a parent router has more than one prefix slot pointing at one full shelf, so a split can rewrite those parent slots without transforming the shelf offset into another router.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.<br/></param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.<br/></param>
    /// <param name="childPrefixBytes">The child-router prefix bytes that will point to the created shelf.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that sizes the new shelf extent.<br/></param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.<br/></param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.<br/></param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ, or no child prefix is supplied.<br/></exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.<br/></exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfBehindChildRouterRoutes(
        long rootRouterOffset,
        byte rootPrefixByte,
        ReadOnlySpan<byte> childPrefixBytes,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (encodedKeys.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS8-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (childPrefixBytes.Length <= 0)
        {
            throw new ArgumentException("At least one child-router prefix must be supplied.", nameof(childPrefixBytes));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < childPrefixBytes.Length; i++)
        {
            childTargets[childPrefixBytes[i]] = shelfReservation.Extent.Offset;
        }

        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

