    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateScalar16Scalar8SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar16Scalar8InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Scalar16Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full SS16-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar8Tuple(currentKeyHigh, currentKeyLow, currentIdentity, encodedKeyHigh, encodedKeyLow, encodedIdentity) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentity == encodedIdentity)
            {
                insertResult = Scalar16Scalar8InsertResult.AlreadyPresent;
                return false;
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identities[targetIndex] = encodedIdentity;
        }

        if (!TryChooseScalar16Scalar8TransformSplitRightPrefix(keyHighs, keyLows, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], keyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar8InsertResult itemResult = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true);
            if (itemResult != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS16-8 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Scalar16Scalar8InsertResult.Inserted;
        return true;
    }

    /// <summary>
    /// Tries to build replacement `FS32-8` shelves for a parent-route refinement split at one encoded key byte depth.<br/>
    /// The incoming tuple is merged into sorted order first, then the selected route prefix boundary is used to populate left and right replacement shelves.<br/>
    /// Returning false means the parent route cannot distinguish the tuples at this depth or the incoming tuple was already present.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full source shelf bytes.</param>
    /// <param name="keyDepth">The parent router key byte depth used for partitioning.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix used as the initial boundary hint.</param>
    /// <param name="profile">The `FS32-8` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateFixed32Scalar8SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar8InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Fixed32Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full FS32-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar8Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentity, key0, key1, key2, key3, encodedIdentity) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentity == encodedIdentity)
            {
                insertResult = Fixed32Scalar8InsertResult.AlreadyPresent;
                return false;
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identities[targetIndex] = encodedIdentity;
        }

        if (!TryChooseFixed32Scalar8TransformSplitRightPrefix(key0s, key1s, key2s, key3s, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar8 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar8Prefix(key0s[i], key1s[i], key2s[i], key3s[i], keyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar8InsertResult itemResult = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
            if (itemResult != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-8 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Fixed32Scalar8InsertResult.Inserted;
        return true;
    }

    /// <summary>
    /// Tries to build replacement `SS8-16` shelves for a parent-route refinement split at one encoded key byte depth.<br/>
    /// The incoming tuple is merged into sorted order first, then the selected route prefix boundary is used to populate left and right replacement shelves.<br/>
    /// Returning false means the parent route cannot distinguish the tuples at this depth or the incoming tuple was already present.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full source shelf bytes.</param>
    /// <param name="keyDepth">The parent router key byte depth used for partitioning.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix used as the initial boundary hint.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateScalar8Scalar16SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar8Scalar16InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Scalar8Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full SS8-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar16Tuple(currentKey, currentIdentityHigh, currentIdentityLow, encodedKey, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keys[targetIndex] = encodedKey;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                insertResult = Scalar8Scalar16InsertResult.AlreadyPresent;
                return false;
            }

            keys[targetIndex] = currentKey;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        if (!TryChooseScalar8Scalar8TransformSplitRightPrefix(keys, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8Prefix(keys[i], keyDepth) >= selectedRightPrefixByte;
            Scalar8Scalar16InsertResult itemResult = goesRight
                ? rightShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (itemResult != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS8-16 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Scalar8Scalar16InsertResult.Inserted;
        return true;
    }

    /// <summary>
    /// Tries to create two replacement shelves for a full `SS16-16` shelf at one specific router byte depth.<br/>
    /// The method merges the incoming tuple with the existing sorted shelf, chooses a median-near prefix boundary, and populates left/right shelf byte arrays.<br/>
    /// Returning false means that byte depth cannot distinguish the tuple set and the caller should try another structural split strategy.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full existing shelf bytes.</param>
    /// <param name="keyDepth">The encoded key byte depth used to divide the replacement shelves.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix at <paramref name="keyDepth"/>.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateScalar16Scalar16SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar16Scalar16InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Scalar16Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full SS16-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar16Tuple(currentKeyHigh, currentKeyLow, currentIdentityHigh, currentIdentityLow, encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                insertResult = Scalar16Scalar16InsertResult.AlreadyPresent;
                return false;
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        if (!TryChooseScalar16Scalar8TransformSplitRightPrefix(keyHighs, keyLows, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], keyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar16InsertResult itemResult = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (itemResult != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS16-16 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Scalar16Scalar16InsertResult.Inserted;
        return true;
    }

    /// <summary>
    /// Tries to choose the right-side prefix boundary for an `SS8-8` transform split at one encoded key depth.<br/>
    /// The chosen boundary is the nearest usable prefix transition around the median of the full shelf plus incoming tuple set.<br/>
    /// Returning false means all tuples share the same prefix at this byte depth and the caller must try a deeper router byte.<br/>
    /// </summary>
    /// <param name="sortedKeys">The complete sorted key set for the full shelf plus the incoming tuple.</param>
    /// <param name="keyDepth">The encoded key byte depth being evaluated.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte when a usable boundary exists.</param>
    /// <returns>True when a usable boundary exists at <paramref name="keyDepth"/>; otherwise false.</returns>
    private static bool TryChooseScalar8Scalar8TransformSplitRightPrefix(
        ReadOnlySpan<ulong> sortedKeys,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeys.Length / 2;
        for (int i = desiredRightStart; i < sortedKeys.Length; i++)
        {
            byte leftPrefix = GetScalar8Scalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetScalar8Scalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetScalar8Scalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetScalar8Scalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetScalar8Scalar8Prefix(sortedKeys[0], keyDepth);
        byte lastPrefix = GetScalar8Scalar8Prefix(sortedKeys[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the byte depth and right-side prefix boundary for an `SS16-8` transform split from the sorted tuple set being repartitioned.<br/>
    /// The search starts at the immediate child-router depth and advances until it finds a prefix byte that can divide the full shelf plus incoming tuple into two replacement shelves.<br/>
    /// This mirrors the `SS8-8` transform planner while reading from the widened key's high and low halves.<br/>
    /// </summary>
    /// <param name="sortedKeyHighs">The complete sorted high key halves for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKeyLows">The complete sorted low key halves for the full shelf plus the incoming tuple.</param>
    /// <param name="firstKeyDepth">The first encoded key byte depth that can be owned by the router being created at the transformed shelf offset.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <returns>The byte depth and first prefix byte that should route to the right replacement shelf.</returns>
    /// <exception cref="InvalidDataException">Thrown when the key set has no usable prefix boundary in the encoded key.</exception>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseScalar16Scalar8TransformSplitPlan(
        ReadOnlySpan<ulong> sortedKeyHighs,
        ReadOnlySpan<ulong> sortedKeyLows,
        ushort firstKeyDepth,
        byte hintRightPrefixByte)
    {
        if (sortedKeyHighs.Length != sortedKeyLows.Length)
        {
            throw new ArgumentException("SS16-8 key half vectors must have the same length.", nameof(sortedKeyLows));
        }

        if (sortedKeyHighs.Length < 2)
        {
            throw new InvalidDataException("The SS16-8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < Scalar16Scalar8Layout.KeySize; keyDepth++)
        {
            if (TryChooseScalar16Scalar8TransformSplitRightPrefix(sortedKeyHighs, sortedKeyLows, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The SS16-8 transform split path requires at least two distinct prefixes in the remaining encoded key bytes.");
    }

    /// <summary>
    /// Tries to choose the right-side prefix boundary for an `SS16-8` transform split at one encoded key depth.<br/>
    /// The chosen boundary is the nearest usable prefix transition around the median of the full shelf plus incoming tuple set.<br/>
    /// Returning false means all tuples share the same prefix at this byte depth and the caller must try a deeper router byte.<br/>
    /// </summary>
    /// <param name="sortedKeyHighs">The complete sorted high key halves for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKeyLows">The complete sorted low key halves for the full shelf plus the incoming tuple.</param>
    /// <param name="keyDepth">The encoded key byte depth being evaluated.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte when a usable boundary exists.</param>
    /// <returns>True when a usable boundary exists at <paramref name="keyDepth"/>; otherwise false.</returns>
    private static bool TryChooseScalar16Scalar8TransformSplitRightPrefix(
        ReadOnlySpan<ulong> sortedKeyHighs,
        ReadOnlySpan<ulong> sortedKeyLows,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeyHighs.Length / 2;
        for (int i = desiredRightStart; i < sortedKeyHighs.Length; i++)
        {
            byte leftPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[i - 1], sortedKeyLows[i - 1], keyDepth);
            byte rightPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[i], sortedKeyLows[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[i - 1], sortedKeyLows[i - 1], keyDepth);
            byte rightPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[i], sortedKeyLows[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[0], sortedKeyLows[0], keyDepth);
        byte lastPrefix = GetScalar16Scalar8Prefix(sortedKeyHighs[^1], sortedKeyLows[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the key byte depth and right-side prefix boundary for an `FS32-8` transform split.<br/>
    /// The search starts at the immediate child-router depth and advances until it finds a prefix byte that can divide the full shelf plus incoming tuple into two replacement shelves.<br/>
    /// This mirrors the `SS16-8` transform planner while reading from all four fixed-key lanes.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="firstKeyDepth">The first encoded key byte depth that can be owned by the router being created at the transformed shelf offset.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <returns>The byte depth and first prefix byte that should route to the right replacement shelf.</returns>
    /// <exception cref="ArgumentException">Thrown when key lane vectors do not have the same length.</exception>
    /// <exception cref="InvalidDataException">Thrown when the key set has no usable prefix boundary in the encoded key.</exception>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseFixed32Scalar8TransformSplitPlan(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort firstKeyDepth,
        byte hintRightPrefixByte)
    {
        if (sortedKey0s.Length != sortedKey1s.Length || sortedKey0s.Length != sortedKey2s.Length || sortedKey0s.Length != sortedKey3s.Length)
        {
            throw new ArgumentException("FS32-8 key lane vectors must have the same length.", nameof(sortedKey1s));
        }

        if (sortedKey0s.Length < 2)
        {
            throw new InvalidDataException("The FS32-8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < Fixed32Scalar8Layout.KeySize; keyDepth++)
        {
            if (TryChooseFixed32Scalar8TransformSplitRightPrefix(sortedKey0s, sortedKey1s, sortedKey2s, sortedKey3s, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The FS32-8 transform split path requires at least two distinct prefixes in the remaining encoded key bytes.");
    }

    /// <summary>
    /// Tries to choose the right-side prefix boundary for an `FS32-8` transform split at one encoded key depth.<br/>
    /// The chosen boundary is the nearest usable prefix transition around the median of the full shelf plus incoming tuple set.<br/>
    /// Returning false means all tuples share the same prefix at this byte depth and the caller must try a deeper router byte.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="keyDepth">The encoded key byte depth being evaluated.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte when a usable boundary exists.</param>
    /// <returns>True when a usable boundary exists at <paramref name="keyDepth"/>; otherwise false.</returns>
    private static bool TryChooseFixed32Scalar8TransformSplitRightPrefix(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKey0s.Length / 2;
        for (int i = desiredRightStart; i < sortedKey0s.Length; i++)
        {
            byte leftPrefix = GetFixed32Scalar8Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar8Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetFixed32Scalar8Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar8Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetFixed32Scalar8Prefix(sortedKey0s[0], sortedKey1s[0], sortedKey2s[0], sortedKey3s[0], keyDepth);
        byte lastPrefix = GetFixed32Scalar8Prefix(sortedKey0s[^1], sortedKey1s[^1], sortedKey2s[^1], sortedKey3s[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Creates expanded one-byte router targets where every route points at the same next router or, when no next router is needed, the final split shelves.<br/>
    /// The fallback split-shelf form is used when the transform can split at the first router depth and no appended router chain exists.<br/>
    /// </summary>
    /// <param name="nextRouterOffset">The appended router offset that should receive every route, or zero when the current router is the split router.</param>
    /// <param name="leftShelfOffset">The left replacement shelf offset.</param>
    /// <param name="rightShelfOffset">The right replacement shelf offset.</param>
    /// <param name="rightPrefixByte">The first prefix byte that routes to the right replacement shelf when no next router exists.</param>
    /// <returns>A 256-entry route target array.</returns>
    private static long[] CreateUniformScalar8Scalar8RouteTargets(
        long nextRouterOffset,
        long leftShelfOffset,
        long rightShelfOffset,
        byte rightPrefixByte)
    {
        return nextRouterOffset == 0
            ? CreateSplitScalar8Scalar8RouteTargets(leftShelfOffset, rightShelfOffset, rightPrefixByte)
            : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
    }

    /// <summary>
    /// Creates expanded one-byte router targets for a binary shelf split boundary.<br/>
    /// Prefix bytes below the boundary route to the left shelf, while the boundary and higher prefixes route to the right shelf.<br/>
    /// </summary>
    /// <param name="leftShelfOffset">The left replacement shelf offset.</param>
    /// <param name="rightShelfOffset">The right replacement shelf offset.</param>
    /// <param name="rightPrefixByte">The first prefix byte that routes to the right replacement shelf.</param>
    /// <returns>A 256-entry route target array.</returns>
    private static long[] CreateSplitScalar8Scalar8RouteTargets(
        long leftShelfOffset,
        long rightShelfOffset,
        byte rightPrefixByte)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < rightPrefixByte; i++)
        {
            targets[i] = leftShelfOffset;
        }

        for (int i = rightPrefixByte; i < targets.Length; i++)
        {
            targets[i] = rightShelfOffset;
        }

        return targets;
    }

    /// <summary>
    /// Creates expanded one-byte `VS8` intermediate-router targets for a deeper shelf transform split.<br/>
    /// Only the exact observed stem byte continues deeper because both replacement shelves contain that stem byte; sibling prefixes remain unset and receive independent shelves on their first insertion.<br/>
    /// This preserves one disjoint key interval per physical shelf instead of aliasing the boundary shelves across an earlier byte that they do not contain.<br/>
    /// </summary>
    /// <param name="nextRouterOffset">The next router in the exact shared-stem chain.</param>
    /// <param name="leftShelfOffset">Unused legacy argument retained while transform call sites share the existing compact signature.</param>
    /// <param name="rightShelfOffset">Unused legacy argument retained while transform call sites share the existing compact signature.</param>
    /// <param name="stemPrefixByte">The shared prefix byte that should continue to <paramref name="nextRouterOffset"/>.</param>
    /// <returns>A 256-entry route target array.</returns>
    private static long[] CreateVarKeyScalar8IntermediateSplitRouteTargets(
        long nextRouterOffset,
        long leftShelfOffset,
        long rightShelfOffset,
        byte stemPrefixByte)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        targets[stemPrefixByte] = nextRouterOffset;
        return targets;
    }

    /// <summary>
    /// Creates expanded one-byte `SS8-8` intermediate-router targets for a deeper transform split.<br/>
    /// Prefixes below the shared scalar-key stem route left, the exact stem byte continues deeper, and prefixes above the stem route right.<br/>
    /// This keeps long shared-prefix scalar clusters from routing unrelated sibling prefixes into the exact-stem subtree.<br/>
    /// </summary>
    /// <param name="nextRouterOffset">The next router in the exact shared-stem chain.</param>
    /// <param name="leftShelfOffset">The left replacement shelf offset for future keys below the shared stem.</param>
    /// <param name="rightShelfOffset">The right replacement shelf offset for future keys above the shared stem.</param>
    /// <param name="stemPrefixByte">The shared prefix byte that should continue to <paramref name="nextRouterOffset"/>.</param>
    /// <returns>A 256-entry route target array.</returns>
    private static long[] CreateScalar8Scalar8IntermediateSplitRouteTargets(
        long nextRouterOffset,
        long leftShelfOffset,
        long rightShelfOffset,
        byte stemPrefixByte)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        for (int i = 0; i < stemPrefixByte; i++)
        {
            targets[i] = leftShelfOffset;
        }

        targets[stemPrefixByte] = nextRouterOffset;
        for (int i = stemPrefixByte + 1; i < targets.Length; i++)
        {
            targets[i] = rightShelfOffset;
        }

        return targets;
    }

    /// <summary>
    /// Creates expanded one-byte router targets where every prefix routes to the same target offset.<br/>
    /// Chained transform splits use this for intermediate routers that only consume another common prefix byte before the actual shelf split router.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target offset assigned to every prefix.</param>
    /// <returns>A 256-entry route target array.</returns>
    private static long[] CreateFilledScalar8Scalar8RouteTargets(long targetOffset)
    {
        long[] targets = new long[RouterLayout.MaxOneByteRouteCount];
        Array.Fill(targets, targetOffset);
        return targets;
    }

    /// <summary>
    /// Routes through a direct-index root router and one direct-index child router, then reads the targeted `SS8-8` shelf bytes into a caller buffer.<br/>
    /// This validation helper supports same-root-prefix split testing before a general multi-depth routing walker exists.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
