    /// <summary>
    /// Inserts one encoded tuple into an `SS16-16` shelf reached by the classified route walker without performing split handling.<br/>
    /// This path supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// The classifier reads make this path more general but not cheaper than direct fast paths where the route target shape is already known.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The walked shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-16` shelf.</exception>
    internal (long ShelfOffset, Scalar16Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertWalkedRoutedScalar16Scalar16NoSplit(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar16Scalar16RouteTarget target = WalkScalar16Scalar16RouteTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar16Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS16-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar16Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar16InsertResult insertResult = shelf.Insert(encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys);
        if (insertResult != Scalar16Scalar16InsertResult.Inserted)
        {
            return (target.Offset, insertResult, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (target.Offset, insertResult, telemetry);
    }

    /// <summary>
    /// Splits a full `SS16-16` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the widened-key and widened-identity counterpart to the validated walked shelf-transform paths and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `SS16-16` shelf or the transform cannot partition safely.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedScalar16Scalar16ByShelfTransform(
            long rootRouterOffset,
            Scalar16Scalar16Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            int maxRouterHops)
    {
        Scalar16Scalar16RouteTarget target = WalkScalar16Scalar16RouteTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        return SplitRoutedScalar16Scalar16ByShelfTransform(
            target.Offset,
            existingShelf,
            rightPrefixByte,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);
    }

    /// <summary>
    /// Splits a full `SS16-16` shelf reached by the classified route walker by refining the parent router routes that already point at that shelf.<br/>
    /// This is the normal split counterpart to the transform path: the full shelf offset is rewritten for the left side, one right shelf is appended, and the parent router is rewritten.<br/>
    /// The method returns false when the parent router byte cannot distinguish the full shelf plus incoming tuple, allowing callers to choose a deeper transform instead.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>Whether the parent split occurred, the parent router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `SS16-16` shelf or the parent router is invalid.</exception>
    internal (
        bool DidSplit,
        long ParentRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedScalar16Scalar16ByParentRoute(
            long rootRouterOffset,
            Scalar16Scalar16Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            int maxRouterHops)
    {
        Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        if (!TrySplitRoutedScalar16Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out int leftItemCount,
            out int rightItemCount,
            out Scalar16Scalar16InsertResult insertResult,
            out DataKernelCommitTelemetry telemetry))
        {
            return (false, pathTarget.ParentRouterOffset, target.Offset, 0, 0, 0, insertResult, default);
        }

        return (true, parentRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, telemetry);
    }

    /// <summary>
    /// Tries to split a full walked `SS16-16` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local widened-key and widened-identity counterpart to the other parent-route split helpers.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedScalar16Scalar16ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar16Scalar16InsertResult insertResult,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        telemetry = default;
        if (!TryCreateScalar16Scalar16SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, parentRouterKeyDepth),
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked SS16-16 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        InvalidateRouterReadCacheForRouterRewrite(parentRouterOffset);
        telemetry = CommitAndDeferRouterReadCacheInvalidation();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }


    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-16` route walker and selects the first supported structural mutation path.<br/>
    /// The decision order matches the other walked shapes: no-split shelf rewrite, duplicate/no-op or key conflict, parent-route split, then shelf-to-router transform.<br/>
    /// This keeps widened-key and widened-identity orchestration shape-local while preserving the same low-friction caller contract for upcoming physical shapes.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-16` shelf profile that determines extent sizing.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-16` shelf or the split cannot be selected safely.</exception>
    internal Scalar16Scalar16RoutedInsertResult InsertWalkedRoutedScalar16Scalar16(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar16Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS16-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar16Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out Scalar16Scalar16MutationBounds mutationBounds);
        if (insertResult == Scalar16Scalar16InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar16Scalar16RoutedInsertResult(
                Scalar16Scalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar16Scalar16InsertResult.AlreadyPresent)
        {
            return new Scalar16Scalar16RoutedInsertResult(
                Scalar16Scalar16RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar16Scalar16InsertResult.KeyConflict)
        {
            return new Scalar16Scalar16RoutedInsertResult(
                Scalar16Scalar16RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar16Scalar16InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS16-16 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar16Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar16Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar16Scalar16RoutedInsertResult(
                Scalar16Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar16Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar16Scalar16ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar16Scalar16RoutedInsertKind kind = transformResult == Scalar16Scalar16InsertResult.Inserted
            ? Scalar16Scalar16RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar16Scalar16RoutedInsertKind.NoOp;
        return new Scalar16Scalar16RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-16` route walker using a caller-owned full shelf image as the split source.<br/>
    /// Batch-local write paths use this when a cached shelf reaches capacity before the active durability batch has published its pending shelf bytes.<br/>
    /// The method keeps those pending bytes in the structural split input and avoids staging the full shelf image over the router or replacement shelf written by the split.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile that determines extent sizing.<br/></param>
    /// <param name="fullShelfOffset">The routed shelf offset represented by <paramref name="fullShelfBytes"/>.<br/></param>
    /// <param name="fullShelfBytes">The full batch-local shelf image to split or rewrite.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation was staged.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing no longer resolves to <paramref name="fullShelfOffset"/>, the shelf image is invalid, or the split cannot be selected safely.<br/></exception>
    internal Scalar16Scalar16RoutedInsertResult InsertWalkedRoutedScalar16Scalar16FromShelfImage(
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        long fullShelfOffset,
        ReadOnlySpan<byte> fullShelfBytes,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The SS16-16 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf || target.Offset != fullShelfOffset)
            throw new InvalidDataException("The classified SS16-16 route no longer resolves to the supplied full shelf image.");

        Scalar16Scalar16ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied SS16-16 split source shelf image is invalid.");

        byte[] rewrittenShelf = fullShelfBytes.ToArray();
        Scalar16Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
        if (insertResult == Scalar16Scalar16InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar16Scalar16RoutedInsertResult(Scalar16Scalar16RoutedInsertKind.WalkedNoSplit, insertResult, target.Offset, target.Offset, 0, telemetry);
        }

        if (insertResult == Scalar16Scalar16InsertResult.AlreadyPresent)
            return new Scalar16Scalar16RoutedInsertResult(Scalar16Scalar16RoutedInsertKind.NoOp, insertResult, target.Offset, 0, 0, default);

        if (insertResult == Scalar16Scalar16InsertResult.KeyConflict)
            return new Scalar16Scalar16RoutedInsertResult(Scalar16Scalar16RoutedInsertKind.KeyConflict, insertResult, target.Offset, 0, 0, default);

        if (insertResult != Scalar16Scalar16InsertResult.Full)
            throw new InvalidDataException($"Unsupported SS16-16 shelf-image insert result {insertResult}.");

        if (TrySplitRoutedScalar16Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar16Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar16Scalar16RoutedInsertResult(Scalar16Scalar16RoutedInsertKind.WalkedParentRouteSplit, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Scalar16Scalar16InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar16Scalar16ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Scalar16Scalar16RoutedInsertKind kind = transformResult == Scalar16Scalar16InsertResult.Inserted ? Scalar16Scalar16RoutedInsertKind.WalkedShelfTransformSplit : Scalar16Scalar16RoutedInsertKind.NoOp;
        return new Scalar16Scalar16RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-16` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple without split or route publication work.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishScalar16Scalar16WriteContext"/> publishes that context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is populated only after context publication.<br/></returns>
    internal Scalar16Scalar16RoutedInsertResult InsertWalkedRoutedScalar16Scalar16NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar16Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            Scalar16Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
            }

            byte[] existingShelf = ReadScalar16Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar16Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar16Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The writer-context walked routed SS16-16 shelf bytes are invalid.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The SS16-16 writer-context insert cannot mutate an empty routed shelf because the current serialized path owns route initialization.");
            }

            Scalar16Scalar16 shelf = new(existingShelf, profile);
            Scalar16Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
            if (insertResult == Scalar16Scalar16InsertResult.Inserted)
            {
                StageScalar16Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Scalar16Scalar16RoutedInsertResult(
                    Scalar16Scalar16RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar16InsertResult.AlreadyPresent)
            {
                return new Scalar16Scalar16RoutedInsertResult(
                    Scalar16Scalar16RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar16InsertResult.KeyConflict)
            {
                return new Scalar16Scalar16RoutedInsertResult(
                    Scalar16Scalar16RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar16InsertResult.Full)
            {
                throw new InvalidOperationException("The SS16-16 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported SS16-16 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitScalar16Scalar16WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `SS16-16` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is bounded to a route that resolves to a non-empty shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to delete.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to delete.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to delete.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    internal bool DeleteWalkedRoutedScalar16Scalar16ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar16Scalar16Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar16Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar16Scalar16RoutePathTarget pathTarget = WalkScalar16Scalar16RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            Scalar16Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS16-16 shelf.");
            }

            byte[] existingShelf = ReadScalar16Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar16Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar16Scalar16ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS16-16 delete shelf bytes are invalid.");
            }

            int startSlot = readOnly.LowerBoundKey(encodedKeyHigh, encodedKeyLow);
            int deleteSlot = -1;
            for (int slot = startSlot; slot < readOnly.ItemCount; slot++)
            {
                int compare = CompareScalar16Key(
                    readOnly.ReadKeyHighAt(slot),
                    readOnly.ReadKeyLowAt(slot),
                    encodedKeyHigh,
                    encodedKeyLow);
                if (compare != 0)
                {
                    break;
                }

                if (readOnly.ReadIdentityHighAt(slot) == encodedIdentityHigh &&
                    readOnly.ReadIdentityLowAt(slot) == encodedIdentityLow)
                {
                    deleteSlot = slot;
                    break;
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Scalar16Scalar16 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageScalar16Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitScalar16Scalar16WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Inserts one encoded tuple into an `SS8-16` shelf reached by the classified route walker without performing split handling.<br/>
    /// This path supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// The classifier reads make this path more general but not cheaper than direct fast paths where the route target shape is already known.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The walked shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-16` shelf.</exception>
    internal (long ShelfOffset, Scalar8Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertWalkedRoutedScalar8Scalar16NoSplit(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar8Scalar16RouteTarget target = WalkScalar8Scalar16RouteTarget(rootRouterOffset, encodedKey, maxRouterHops);
        if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar16InsertResult insertResult = shelf.Insert(encodedKey, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys);
        if (insertResult != Scalar8Scalar16InsertResult.Inserted)
        {
            return (target.Offset, insertResult, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (target.Offset, insertResult, telemetry);
    }

    /// <summary>
    /// Splits a full `SS8-16` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the widened-identity counterpart to the validated `SS8-8` walked shelf-transform path and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `SS8-16` shelf or the transform cannot partition safely.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedScalar8Scalar16ByShelfTransform(
            long rootRouterOffset,
            Scalar8Scalar16Profile profile,
            ulong encodedKey,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            int maxRouterHops)
    {
        Scalar8Scalar16RouteTarget target = WalkScalar8Scalar16RouteTarget(rootRouterOffset, encodedKey, maxRouterHops);
        if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, nextRouterKeyDepth);
        return SplitRoutedScalar8Scalar16ByShelfTransform(
            target.Offset,
            existingShelf,
            rightPrefixByte,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);
    }

    /// <summary>
    /// Splits a full `SS8-16` shelf reached by the classified route walker by refining the parent router routes that already point at that shelf.<br/>
    /// This is the normal split counterpart to the transform path: the full shelf offset is rewritten for the left side, one right shelf is appended, and the parent router is rewritten.<br/>
    /// The method returns false when the parent router byte cannot distinguish the full shelf plus incoming tuple, allowing callers to choose a deeper transform instead.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>Whether the parent split occurred, the parent router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `SS8-16` shelf or the parent router is invalid.</exception>
    internal (
        bool DidSplit,
        long ParentRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedScalar8Scalar16ByParentRoute(
            long rootRouterOffset,
            Scalar8Scalar16Profile profile,
            ulong encodedKey,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            int maxRouterHops)
    {
        Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
        Scalar8Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        if (!TrySplitRoutedScalar8Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out int leftItemCount,
            out int rightItemCount,
            out Scalar8Scalar16InsertResult insertResult,
            out DataKernelCommitTelemetry telemetry))
        {
            return (false, pathTarget.ParentRouterOffset, target.Offset, 0, 0, 0, insertResult, default);
        }

        return (true, parentRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, telemetry);
    }

    /// <summary>
    /// Tries to split a full walked `SS8-16` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local widened-identity counterpart to the `SS16-8` parent-route split helper.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedScalar8Scalar16ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar8Scalar16InsertResult insertResult,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        telemetry = default;
        if (!TryCreateScalar8Scalar16SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetScalar8Scalar8Prefix(encodedKey, parentRouterKeyDepth),
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked SS8-16 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-16` route walker and selects the first supported structural mutation path.<br/>
    /// The decision order matches the current `SS16-8` behavior envelope: no-split shelf rewrite, duplicate/no-op or key conflict, parent-route split, then shelf-to-router transform.<br/>
    /// This keeps widened-identity orchestration shape-local while preserving the same low-friction caller contract for upcoming physical shapes.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-16` shelf profile that determines shelf extent sizing.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-16` shelf or the split cannot be selected safely.</exception>
    internal Scalar8Scalar16RoutedInsertResult InsertWalkedRoutedScalar8Scalar16(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
        Scalar8Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out Scalar8Scalar16MutationBounds mutationBounds);
        if (insertResult == Scalar8Scalar16InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar16RoutedInsertResult(
                Scalar8Scalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar8Scalar16InsertResult.AlreadyPresent)
        {
            return new Scalar8Scalar16RoutedInsertResult(
                Scalar8Scalar16RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar8Scalar16InsertResult.KeyConflict)
        {
            return new Scalar8Scalar16RoutedInsertResult(
                Scalar8Scalar16RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar8Scalar16InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS8-16 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar8Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar8Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar8Scalar16RoutedInsertResult(
                Scalar8Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar8Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar16ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKey,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar8Scalar16RoutedInsertKind kind = transformResult == Scalar8Scalar16InsertResult.Inserted
            ? Scalar8Scalar16RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar8Scalar16RoutedInsertKind.NoOp;
        return new Scalar8Scalar16RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-16` route walker using a caller-owned full shelf image as the split source.<br/>
    /// Batch-local write paths use this when a cached shelf reaches capacity before the active durability batch has published its pending shelf bytes.<br/>
    /// The method keeps those pending bytes in the structural split input and avoids staging the full shelf image over the router or replacement shelf written by the split.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile that determines shelf extent sizing.<br/></param>
    /// <param name="fullShelfOffset">The routed shelf offset represented by <paramref name="fullShelfBytes"/>.<br/></param>
    /// <param name="fullShelfBytes">The full batch-local shelf image to split or rewrite.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation was staged.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing no longer resolves to <paramref name="fullShelfOffset"/>, the shelf image is invalid, or the split cannot be selected safely.<br/></exception>
    internal Scalar8Scalar16RoutedInsertResult InsertWalkedRoutedScalar8Scalar16FromShelfImage(
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        long fullShelfOffset,
        ReadOnlySpan<byte> fullShelfBytes,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The SS8-16 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
        Scalar8Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf || target.Offset != fullShelfOffset)
            throw new InvalidDataException("The classified SS8-16 route no longer resolves to the supplied full shelf image.");

        Scalar8Scalar16ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied SS8-16 split source shelf image is invalid.");

        byte[] rewrittenShelf = fullShelfBytes.ToArray();
        Scalar8Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
        if (insertResult == Scalar8Scalar16InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar16RoutedInsertResult(Scalar8Scalar16RoutedInsertKind.WalkedNoSplit, insertResult, target.Offset, target.Offset, 0, telemetry);
        }

        if (insertResult == Scalar8Scalar16InsertResult.AlreadyPresent)
            return new Scalar8Scalar16RoutedInsertResult(Scalar8Scalar16RoutedInsertKind.NoOp, insertResult, target.Offset, 0, 0, default);

        if (insertResult == Scalar8Scalar16InsertResult.KeyConflict)
            return new Scalar8Scalar16RoutedInsertResult(Scalar8Scalar16RoutedInsertKind.KeyConflict, insertResult, target.Offset, 0, 0, default);

        if (insertResult != Scalar8Scalar16InsertResult.Full)
            throw new InvalidDataException($"Unsupported SS8-16 shelf-image insert result {insertResult}.");

        if (TrySplitRoutedScalar8Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar8Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar8Scalar16RoutedInsertResult(Scalar8Scalar16RoutedInsertKind.WalkedParentRouteSplit, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Scalar8Scalar16InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar16ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Scalar8Scalar16RoutedInsertKind kind = transformResult == Scalar8Scalar16InsertResult.Inserted ? Scalar8Scalar16RoutedInsertKind.WalkedShelfTransformSplit : Scalar8Scalar16RoutedInsertKind.NoOp;
        return new Scalar8Scalar16RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-16` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple without split or route publication work.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishScalar8Scalar16WriteContext"/> publishes that context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is populated only after context publication.<br/></returns>
    internal Scalar8Scalar16RoutedInsertResult InsertWalkedRoutedScalar8Scalar16NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar8Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
            Scalar8Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
            }

            byte[] existingShelf = ReadScalar8Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar8Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The writer-context walked routed SS8-16 shelf bytes are invalid.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The SS8-16 writer-context insert cannot mutate an empty routed shelf because the current serialized path owns route initialization.");
            }

            Scalar8Scalar16 shelf = new(existingShelf, profile);
            Scalar8Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
            if (insertResult == Scalar8Scalar16InsertResult.Inserted)
            {
                StageScalar8Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Scalar8Scalar16RoutedInsertResult(
                    Scalar8Scalar16RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar16InsertResult.AlreadyPresent)
            {
                return new Scalar8Scalar16RoutedInsertResult(
                    Scalar8Scalar16RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar16InsertResult.KeyConflict)
            {
                return new Scalar8Scalar16RoutedInsertResult(
                    Scalar8Scalar16RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar16InsertResult.Full)
            {
                throw new InvalidOperationException("The SS8-16 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported SS8-16 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitScalar8Scalar16WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `SS8-16` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is bounded to a route that resolves to a non-empty shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to delete.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to delete.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    internal bool DeleteWalkedRoutedScalar8Scalar16ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar8Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar8Scalar16RoutePathTarget pathTarget = WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops);
            Scalar8Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS8-16 shelf.");
            }

            byte[] existingShelf = ReadScalar8Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar8Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar8Scalar16ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS8-16 delete shelf bytes are invalid.");
            }

            int startSlot = readOnly.LowerBoundKey(encodedKey);
            int deleteSlot = -1;
            for (int slot = startSlot; slot < readOnly.ItemCount; slot++)
            {
                ulong currentKey = readOnly.ReadKeyAt(slot);
                if (currentKey != encodedKey)
                {
                    break;
                }

                if (readOnly.ReadIdentityHighAt(slot) == encodedIdentityHigh &&
                    readOnly.ReadIdentityLowAt(slot) == encodedIdentityLow)
                {
                    deleteSlot = slot;
                    break;
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Scalar8Scalar16 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageScalar8Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitScalar8Scalar16WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Inserts one encoded tuple into an `SS16-8` shelf reached by the classified route walker without performing split handling.<br/>
    /// This path supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// The classifier reads make this path more general but not cheaper than direct fast paths where the route target shape is already known.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The walked shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-8` shelf.</exception>
    internal (long ShelfOffset, Scalar16Scalar8InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertWalkedRoutedScalar16Scalar8NoSplit(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar16Scalar8RouteTarget target = WalkScalar16Scalar8RouteTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS16-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar16Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar8InsertResult insertResult = shelf.Insert(encodedKeyHigh, encodedKeyLow, encodedIdentity, allowDuplicateKeys);
        if (insertResult != Scalar16Scalar8InsertResult.Inserted)
        {
            return (target.Offset, insertResult, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (target.Offset, insertResult, telemetry);
    }

    /// <summary>
    /// Splits a full `SS16-8` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the widened-key counterpart to the validated `SS8-8` walked shelf-transform path and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `SS16-8` shelf or the transform cannot partition safely.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedScalar16Scalar8ByShelfTransform(
            long rootRouterOffset,
            Scalar16Scalar8Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Scalar16Scalar8RouteTarget target = WalkScalar16Scalar8RouteTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        return SplitRoutedScalar16Scalar8ByShelfTransform(
            target.Offset,
            existingShelf,
            rightPrefixByte,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            target.AllocationClassId,
            nextRouterKeyDepth);
    }

    /// <summary>
    /// Splits a full `FS32-8` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the fixed-32-byte-key counterpart to the validated `SS16-8` walked shelf-transform path and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-8` shelf or the transform cannot partition safely.</exception>
    internal (
