    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-8` shelf or the parent router is invalid.</exception>
    internal (
        bool DidSplit,
        long ParentRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedFixed32Scalar8ByParentRoute(
            long rootRouterOffset,
            Fixed32Scalar8Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        if (!TrySplitRoutedFixed32Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            allowDuplicateKeys: true,
            allowRetainedSortedLeftImage: false,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out int leftItemCount,
            out int rightItemCount,
            out Fixed32Scalar8InsertResult insertResult,
            out _,
            out DataKernelCommitTelemetry telemetry))
        {
            return (false, pathTarget.ParentRouterOffset, target.Offset, 0, 0, 0, insertResult, default);
        }

        return (true, parentRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, telemetry);
    }

    /// <summary>
    /// Tries to split a full walked `SS16-8` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local widened-key counterpart to the `SS8-8` parent-route split helper.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `SS16-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedScalar16Scalar8ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar16Scalar8InsertResult insertResult,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        telemetry = default;
        if (!TryCreateScalar16Scalar8SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, parentRouterKeyDepth),
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked SS16-8 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }

    /// <summary>
    /// Tries to split a full walked `FS32-8` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local fixed-32-byte-key counterpart to the `SS16-8` parent-route split helper.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `FS32-8` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allowDuplicateKeys">Whether equal keys with different identities may remain in the split shelves.<br/></param>
    /// <param name="allowRetainedSortedLeftImage">Whether the caller can retain and publish the source image after an in-place sorted-tail split.<br/></param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="retainedSortedLeftImage">True when the caller's source image was truncated in place and must remain batch-owned through publication.<br/></param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedFixed32Scalar8ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        Span<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        bool allowRetainedSortedLeftImage,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar8InsertResult insertResult,
        out bool retainedSortedLeftImage,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        retainedSortedLeftImage = false;
        telemetry = default;
        Fixed32BatchAttributionDiagnostics? attribution = Fixed32BatchAttributionDiagnostics.Current;

        Fixed32Scalar8ReadOnly sortedShelf = new(existingShelfBytes, profile);
        if (allowRetainedSortedLeftImage &&
            sortedShelf.IsValid &&
            sortedShelf.ItemCount == profile.MaxItemCount &&
            sortedShelf.DeletedItemCount == 0)
        {
            int lastSlotIndex = sortedShelf.ItemCount - 1;
            int incomingKeyComparison = CompareFixed32Scalar8Key(
                sortedShelf.ReadKeyPart0At(lastSlotIndex),
                sortedShelf.ReadKeyPart1At(lastSlotIndex),
                sortedShelf.ReadKeyPart2At(lastSlotIndex),
                sortedShelf.ReadKeyPart3At(lastSlotIndex),
                key0,
                key1,
                key2,
                key3);
            bool incomingIsSortedAppend = incomingKeyComparison < 0 ||
                (allowDuplicateKeys && incomingKeyComparison == 0 && sortedShelf.ReadIdentityAt(lastSlotIndex) < encodedIdentity);
            if (incomingIsSortedAppend)
            {
                int desiredRightStart = sortedShelf.ItemCount / 2;
                int rightStartSlot = 0;
                int lastTransitionBeforeMedian = 0;
                byte selectedSortedRightPrefixByte = 0;
                byte transitionBeforeMedianPrefixByte = 0;
                byte previousPrefixByte = GetFixed32Scalar8Prefix(
                    sortedShelf.ReadKeyPart0At(0),
                    sortedShelf.ReadKeyPart1At(0),
                    sortedShelf.ReadKeyPart2At(0),
                    sortedShelf.ReadKeyPart3At(0),
                    parentRouterKeyDepth);
                bool canTruncateDenseSortedPrefix = Fixed32Scalar8Layout.ReadSlot(existingShelfBytes, profile, 0) == Fixed32Scalar8Layout.GetItemOffset(profile, 0);
                for (int slotIndex = 1; canTruncateDenseSortedPrefix && slotIndex < sortedShelf.ItemCount; slotIndex++)
                {
                    if (attribution is not null)
                        attribution.SortedScannedSlots++;
                    canTruncateDenseSortedPrefix = Fixed32Scalar8Layout.ReadSlot(existingShelfBytes, profile, slotIndex) == Fixed32Scalar8Layout.GetItemOffset(profile, slotIndex);
                    byte prefixByte = GetFixed32Scalar8Prefix(
                        sortedShelf.ReadKeyPart0At(slotIndex),
                        sortedShelf.ReadKeyPart1At(slotIndex),
                        sortedShelf.ReadKeyPart2At(slotIndex),
                        sortedShelf.ReadKeyPart3At(slotIndex),
                        parentRouterKeyDepth);
                    if (prefixByte < previousPrefixByte)
                    {
                        canTruncateDenseSortedPrefix = false;
                        break;
                    }

                    if (prefixByte > previousPrefixByte)
                    {
                        if (slotIndex >= desiredRightStart && rightStartSlot == 0)
                        {
                            rightStartSlot = slotIndex;
                            selectedSortedRightPrefixByte = prefixByte;
                        }
                        else if (slotIndex < desiredRightStart)
                        {
                            lastTransitionBeforeMedian = slotIndex;
                            transitionBeforeMedianPrefixByte = prefixByte;
                        }
                    }

                    previousPrefixByte = prefixByte;
                }

                if (rightStartSlot == 0 && lastTransitionBeforeMedian != 0)
                {
                    rightStartSlot = lastTransitionBeforeMedian;
                    selectedSortedRightPrefixByte = transitionBeforeMedianPrefixByte;
                }

                byte incomingPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, parentRouterKeyDepth);
                if (canTruncateDenseSortedPrefix &&
                    rightStartSlot == 0 &&
                    lastTransitionBeforeMedian == 0 &&
                    incomingPrefixByte == previousPrefixByte)
                {
                    if (attribution is not null)
                    {
                        attribution.SortedRejectedNoPrefixBoundary++;
                        attribution.SortedParentDepthImpossibleFastRejects++;
                    }

                    return false;
                }

                if (canTruncateDenseSortedPrefix &&
                    rightStartSlot > 0 &&
                    incomingPrefixByte >= selectedSortedRightPrefixByte)
                {
                    byte[] sortedParentRouterBytes = new byte[RouterLayout.Size];
                    kernel.Read(parentRouterOffset, sortedParentRouterBytes);
                    RouterReader sortedParentReader = new(sortedParentRouterBytes);
                    if (!sortedParentReader.IsValid ||
                        !sortedParentReader.HasDirectIndex ||
                        sortedParentReader.GetDirectTarget(incomingPrefixByte) != fullShelfOffset)
                    {
                        throw new InvalidDataException("The walked sorted FS32-8 parent route no longer points to the classified full shelf.");
                    }

                    RawDataReservation sortedRightAppend = kernel.Reserve(profile.ShelfExtentSize);
                    Fixed32Scalar8 sortedRightShelf = new(sortedRightAppend.Span, profile);
                    sortedRightShelf.Initialize();
                    for (int slotIndex = rightStartSlot; slotIndex < sortedShelf.ItemCount; slotIndex++)
                    {
                        if (attribution is not null)
                            attribution.SortedCopiedItems++;
                        Fixed32Scalar8InsertResult movedResult = sortedRightShelf.Insert(
                            sortedShelf.ReadKeyPart0At(slotIndex),
                            sortedShelf.ReadKeyPart1At(slotIndex),
                            sortedShelf.ReadKeyPart2At(slotIndex),
                            sortedShelf.ReadKeyPart3At(slotIndex),
                            sortedShelf.ReadIdentityAt(slotIndex),
                            allowDuplicateKeys);
                        if (movedResult != Fixed32Scalar8InsertResult.Inserted)
                        {
                            throw new InvalidDataException($"Expected sorted-tail FS32-8 move at slot {slotIndex}, got {movedResult}.");
                        }
                    }

                    insertResult = sortedRightShelf.Insert(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys);
                    if (insertResult != Fixed32Scalar8InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected sorted-tail FS32-8 incoming insert, got {insertResult}.");
                    }

                    Fixed32Scalar8Layout.WriteItemCount(existingShelfBytes, checked((ushort)rightStartSlot));
                    fixed32Scalar8CleanShelfCache.Remove(fullShelfOffset);
                    RawDataReservation leftCountRewrite = kernel.ReserveAt(
                        fullShelfOffset + Fixed32Scalar8Layout.ItemCountOffset,
                        sizeof(ushort));
                    existingShelfBytes.Slice(Fixed32Scalar8Layout.ItemCountOffset, sizeof(ushort)).CopyTo(leftCountRewrite.Span);

                    RawDataReservation sortedParentRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
                    sortedParentRouterBytes.CopyTo(sortedParentRewrite.Span);
                    RouterWriter sortedParentWriter = new(sortedParentRewrite.Span);
                    for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
                    {
                        byte prefixByte = (byte)prefix;
                        if (sortedParentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
                        {
                            long targetOffset = prefixByte < selectedSortedRightPrefixByte
                                ? fullShelfOffset
                                : sortedRightAppend.Extent.Offset;
                            sortedParentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
                        }
                    }

                    telemetry = CommitAndInvalidateRouterReadCache();
                    leftShelfOffset = fullShelfOffset;
                    rightShelfOffset = sortedRightAppend.Extent.Offset;
                    leftItemCount = rightStartSlot;
                    rightItemCount = sortedRightShelf.ItemCount;
                    retainedSortedLeftImage = true;
                    return true;
                }

                if (attribution is not null)
                    attribution.SortedRejectedNoPrefixBoundary++;
            }
            else if (attribution is not null)
                attribution.SortedRejectedNotAppend++;
        }
        else if (attribution is not null)
            attribution.SortedRejectedInvalidOrNotFull++;

        if (!TryCreateFixed32Scalar8SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetFixed32Scalar8Prefix(key0, key1, key2, key3, parentRouterKeyDepth),
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked FS32-8 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-8` route walker and selects the first supported structural mutation path.<br/>
    /// The decision order matches the current `SS8-8` behavior envelope: no-split shelf rewrite, duplicate/no-op or key conflict, parent-route split, then shelf-to-router transform.<br/>
    /// This keeps widened-key orchestration shape-local while preserving the same low-friction caller contract for upcoming physical shapes.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-8` shelf or the split cannot be selected safely.</exception>
    internal Scalar16Scalar8RoutedInsertResult InsertWalkedRoutedScalar16Scalar8(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS16-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar16Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentity, allowDuplicateKeys, out Scalar16Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar16Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar16Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar16Scalar8InsertResult.KeyConflict)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar16Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS16-8 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar16Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar16Scalar8InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar16Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar16Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar16Scalar8RoutedInsertKind kind = transformResult == Scalar16Scalar8InsertResult.Inserted
            ? Scalar16Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar16Scalar8RoutedInsertKind.NoOp;
        return new Scalar16Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-8` route walker using a caller-owned full shelf image as the split source.<br/>
    /// Batch-local write paths use this when a cached shelf reaches capacity before the active durability batch has published its pending shelf bytes.<br/>
    /// The method keeps those pending bytes in the structural split input and avoids staging the full shelf image over the router or replacement shelf written by the split.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent sizing.<br/></param>
    /// <param name="fullShelfOffset">The routed shelf offset represented by <paramref name="fullShelfBytes"/>.<br/></param>
    /// <param name="fullShelfBytes">The full batch-local shelf image to split or rewrite.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation was staged.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing no longer resolves to <paramref name="fullShelfOffset"/>, the shelf image is invalid, or the split cannot be selected safely.<br/></exception>
    internal Scalar16Scalar8RoutedInsertResult InsertWalkedRoutedScalar16Scalar8FromShelfImage(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        long fullShelfOffset,
        ReadOnlySpan<byte> fullShelfBytes,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The SS16-8 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));
        }

        Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf || target.Offset != fullShelfOffset)
        {
            throw new InvalidDataException("The classified SS16-8 route no longer resolves to the supplied full shelf image.");
        }

        Scalar16Scalar8ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The supplied SS16-8 split source shelf image is invalid.");
        }

        byte[] rewrittenShelf = fullShelfBytes.ToArray();
        Scalar16Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentity, allowDuplicateKeys, out _);
        if (insertResult == Scalar16Scalar8InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar16Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar16Scalar8InsertResult.KeyConflict)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar16Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS16-8 shelf-image insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar16Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar16Scalar8InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar16Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar16Scalar8ByShelfTransform(
                target.Offset,
                fullShelfBytes,
                rightPrefixByte,
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar16Scalar8RoutedInsertKind kind = transformResult == Scalar16Scalar8InsertResult.Inserted
            ? Scalar16Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar16Scalar8RoutedInsertKind.NoOp;
        return new Scalar16Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-8` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple without split or route publication work.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishScalar16Scalar8WriteContext"/> publishes that context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key lane to insert.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key lane to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same encoded key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is default because publication is deferred to the writer context.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-8` shelf.<br/></exception>
    /// <exception cref="InvalidOperationException">Thrown when the insert requires route topology changes, full-shelf split handling, or a shelf already owned by another writer context.<br/></exception>
    internal Scalar16Scalar8RoutedInsertResult InsertWalkedRoutedScalar16Scalar8NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar16Scalar8WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            Scalar16Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
            }

            byte[] existingShelf = ReadScalar16Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar16Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS16-8 shelf bytes are invalid.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The SS16-8 writer-context insert cannot mutate an empty routed shelf because the current serialized path owns route initialization.");
            }

            Scalar16Scalar8 shelf = new(existingShelf, profile);
            Scalar16Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentity, allowDuplicateKeys, out _);
            if (insertResult == Scalar16Scalar8InsertResult.Inserted)
            {
                StageScalar16Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Scalar16Scalar8RoutedInsertResult(
                    Scalar16Scalar8RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar8InsertResult.AlreadyPresent)
            {
                return new Scalar16Scalar8RoutedInsertResult(
                    Scalar16Scalar8RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar8InsertResult.KeyConflict)
            {
                return new Scalar16Scalar8RoutedInsertResult(
                    Scalar16Scalar8RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar16Scalar8InsertResult.Full)
            {
                throw new InvalidOperationException("The SS16-8 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported SS16-8 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitScalar16Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `SS16-8` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is bounded to a route that resolves to a non-empty shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS16-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKeyHigh">The encoded high key lane to delete.<br/></param>
    /// <param name="encodedKeyLow">The encoded low key lane to delete.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity value to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing or shelf bytes are invalid.<br/></exception>
    internal bool DeleteWalkedRoutedScalar16Scalar8ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar16Scalar8WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
            Scalar16Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
            }

            byte[] existingShelf = ReadScalar16Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar16Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar16Scalar8ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS16-8 delete shelf bytes are invalid.");
            }

            int startSlot = readOnly.LowerBoundKey(encodedKeyHigh, encodedKeyLow);
            int deleteSlot = -1;
            for (int slot = startSlot; slot < readOnly.ItemCount; slot++)
            {
                int compare = CompareScalar16Key(
                    readOnly.ReadKeyHighAt(slot),
                    readOnly.ReadKeyLowAt(slot),
                    encodedKeyHigh,
                    encodedKeyLow);
                if (compare != 0)
                {
                    break;
                }

                if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
                {
                    deleteSlot = slot;
                    break;
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Scalar16Scalar8 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageScalar16Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitScalar16Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-8` route walker when the routed shelf has room for a no-split rewrite.<br/>
    /// The method supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// Full-shelf split selection remains deliberately outside this slice; walked transform and parent-route refinement are added as separate validated steps.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-8` shelf or when a full shelf requires a not-yet-selected walked split path.</exception>
    internal Fixed32Scalar8RoutedInsertResult InsertWalkedRoutedFixed32Scalar8(
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Fixed32Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed FS32-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar8 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys, out Fixed32Scalar8MutationBounds mutationBounds);
        if (insertResult == Fixed32Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Fixed32Scalar8InsertResult.AlreadyPresent)
        {
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Fixed32Scalar8InsertResult.KeyConflict)
        {
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Fixed32Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported FS32-8 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedFixed32Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            allowDuplicateKeys,
            allowRetainedSortedLeftImage: false,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar8InsertResult parentSplitResult,
            out bool retainedSortedLeftImage,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar8RoutedInsertResult(
                retainedSortedLeftImage ? Fixed32Scalar8RoutedInsertKind.WalkedSortedTailSplit : Fixed32Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Fixed32Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                key0,
                key1,
                key2,
                key3,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Fixed32Scalar8RoutedInsertKind kind = transformResult == Fixed32Scalar8InsertResult.Inserted
            ? Fixed32Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Fixed32Scalar8RoutedInsertKind.NoOp;
        return new Fixed32Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-8` route walker using a caller-owned full shelf image as the split source.<br/>
    /// Batch-local write paths use this when a cached shelf reaches capacity before the active durability batch has published its pending shelf bytes.<br/>
    /// The method keeps those pending bytes in the structural split input and avoids staging the full shelf image over the router or replacement shelf written by the split.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile that determines shelf extent sizing.<br/></param>
    /// <param name="fullShelfOffset">The routed shelf offset represented by <paramref name="fullShelfBytes"/>.<br/></param>
    /// <param name="fullShelfBytes">The full batch-local shelf image to split or rewrite.<br/></param>
    /// <param name="key0">The first encoded key lane to insert.<br/></param>
    /// <param name="key1">The second encoded key lane to insert.<br/></param>
    /// <param name="key2">The third encoded key lane to insert.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation was staged.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing no longer resolves to <paramref name="fullShelfOffset"/>, the shelf image is invalid, or the split cannot be selected safely.<br/></exception>
    internal Fixed32Scalar8RoutedInsertResult InsertWalkedRoutedFixed32Scalar8FromShelfImage(
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        long fullShelfOffset,
        Span<byte> fullShelfBytes,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The FS32-8 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf || target.Offset != fullShelfOffset)
            throw new InvalidDataException("The classified FS32-8 route no longer resolves to the supplied full shelf image.");

        Fixed32Scalar8ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied FS32-8 split source shelf image is invalid.");

        byte[] rewrittenShelf = fullShelfBytes.ToArray();
        Fixed32Scalar8 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys, out _);
        if (insertResult == Fixed32Scalar8InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar8RoutedInsertResult(Fixed32Scalar8RoutedInsertKind.WalkedNoSplit, insertResult, target.Offset, target.Offset, 0, telemetry);
        }

        if (insertResult == Fixed32Scalar8InsertResult.AlreadyPresent)
            return new Fixed32Scalar8RoutedInsertResult(Fixed32Scalar8RoutedInsertKind.NoOp, insertResult, target.Offset, 0, 0, default);

        if (insertResult == Fixed32Scalar8InsertResult.KeyConflict)
            return new Fixed32Scalar8RoutedInsertResult(Fixed32Scalar8RoutedInsertKind.KeyConflict, insertResult, target.Offset, 0, 0, default);

        if (insertResult != Fixed32Scalar8InsertResult.Full)
            throw new InvalidDataException($"Unsupported FS32-8 shelf-image insert result {insertResult}.");

        if (TrySplitRoutedFixed32Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            allowDuplicateKeys,
            allowRetainedSortedLeftImage: false,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar8InsertResult parentSplitResult,
            out bool retainedSortedLeftImage,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            Fixed32Scalar8RoutedInsertKind parentKind = retainedSortedLeftImage ? Fixed32Scalar8RoutedInsertKind.WalkedSortedTailSplit : Fixed32Scalar8RoutedInsertKind.WalkedParentRouteSplit;
            return new Fixed32Scalar8RoutedInsertResult(parentKind, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Fixed32Scalar8InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar8ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Fixed32Scalar8RoutedInsertKind kind = transformResult == Fixed32Scalar8InsertResult.Inserted ? Fixed32Scalar8RoutedInsertKind.WalkedShelfTransformSplit : Fixed32Scalar8RoutedInsertKind.NoOp;
        return new Fixed32Scalar8RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Splits one full `FS32-8` shelf image through its already classified direct parent route.<br/>
    /// The caller must retain the path from the current single-writer topology and clear it after any structural mutation; this avoids a redundant root walk and a redundant full-shelf insertion retry.<br/>
    /// </summary>
    /// <param name="pathTarget">The current terminal shelf target and direct parent route that selected it.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile that owns the supplied image.<br/></param>
    /// <param name="fullShelfBytes">The validated full shelf image already tested by the caller's in-place insert.<br/></param>
    /// <param name="key0">The first encoded key lane to insert during the split.<br/></param>
    /// <param name="key1">The second encoded key lane to insert during the split.<br/></param>
    /// <param name="key2">The third encoded key lane to insert during the split.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.<br/></param>
    /// <param name="allowDuplicateKeys">Whether equal keys with different identities are allowed.<br/></param>
    /// <returns>The storage-facing routed split result and deferred or immediate commit telemetry.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when the retained target, route prefix, or shelf image is invalid.<br/></exception>
    internal Fixed32Scalar8RoutedInsertResult SplitRoutedFixed32Scalar8FromShelfImage(
        Fixed32Scalar8RoutePathTarget pathTarget,
        Fixed32Scalar8Profile profile,
        Span<byte> fullShelfBytes,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The FS32-8 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Fixed32Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf ||
            GetFixed32Scalar8Prefix(key0, key1, key2, key3, target.RouterDepth) != pathTarget.RoutePrefixByte)
        {
            throw new InvalidDataException("The retained FS32-8 path does not classify the supplied split key to a shelf.");
        }

        Fixed32Scalar8ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied FS32-8 split source shelf image is invalid.");

        if (TrySplitRoutedFixed32Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            allowDuplicateKeys,
            allowRetainedSortedLeftImage: true,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar8InsertResult parentSplitResult,
            out bool retainedSortedLeftImage,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            Fixed32Scalar8RoutedInsertKind parentKind = retainedSortedLeftImage ? Fixed32Scalar8RoutedInsertKind.WalkedSortedTailSplit : Fixed32Scalar8RoutedInsertKind.WalkedParentRouteSplit;
            return new Fixed32Scalar8RoutedInsertResult(parentKind, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Fixed32Scalar8InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar8ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Fixed32Scalar8RoutedInsertKind kind = transformResult == Fixed32Scalar8InsertResult.Inserted ? Fixed32Scalar8RoutedInsertKind.WalkedShelfTransformSplit : Fixed32Scalar8RoutedInsertKind.NoOp;
        return new Fixed32Scalar8RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-8` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple without split or route publication work.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishFixed32Scalar8WriteContext"/> publishes that context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="key0">The first encoded key lane to insert.<br/></param>
    /// <param name="key1">The second encoded key lane to insert.<br/></param>
    /// <param name="key2">The third encoded key lane to insert.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same encoded key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is default because publication is deferred to the writer context.<br/></returns>
    internal Fixed32Scalar8RoutedInsertResult InsertWalkedRoutedFixed32Scalar8NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterFixed32Scalar8WriterContextStaging(rootRouterOffset);
        try
        {
            Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
            Fixed32Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an FS32-8 shelf.");
            }

            byte[] existingShelf = ReadFixed32Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordFixed32Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Fixed32Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed FS32-8 shelf bytes are invalid.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The FS32-8 writer-context insert cannot mutate an empty routed shelf because the current serialized path owns route initialization.");
            }

            Fixed32Scalar8 shelf = new(existingShelf, profile);
            Fixed32Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys, out _);
            if (insertResult == Fixed32Scalar8InsertResult.Inserted)
            {
                StageFixed32Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Fixed32Scalar8RoutedInsertResult(
                    Fixed32Scalar8RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar8InsertResult.AlreadyPresent)
            {
                return new Fixed32Scalar8RoutedInsertResult(
                    Fixed32Scalar8RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar8InsertResult.KeyConflict)
            {
                return new Fixed32Scalar8RoutedInsertResult(
                    Fixed32Scalar8RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar8InsertResult.Full)
            {
                throw new InvalidOperationException("The FS32-8 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported FS32-8 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitFixed32Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `FS32-8` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is bounded to a route that resolves to a non-empty shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="key0">The first encoded key lane to delete.<br/></param>
    /// <param name="key1">The second encoded key lane to delete.<br/></param>
    /// <param name="key2">The third encoded key lane to delete.<br/></param>
    /// <param name="key3">The fourth encoded key lane to delete.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity value to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing or shelf bytes are invalid.<br/></exception>
    internal bool DeleteWalkedRoutedFixed32Scalar8ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterFixed32Scalar8WriterContextStaging(rootRouterOffset);
        try
        {
            Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
            Fixed32Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an FS32-8 shelf.");
            }

            byte[] existingShelf = ReadFixed32Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordFixed32Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Fixed32Scalar8ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed FS32-8 delete shelf bytes are invalid.");
            }

            int startSlot = readOnly.LowerBoundKey(key0, key1, key2, key3);
            int deleteSlot = -1;
            for (int slot = startSlot; slot < readOnly.ItemCount; slot++)
            {
                int compare = CompareFixed32Scalar8Key(
                    readOnly.ReadKeyPart0At(slot),
                    readOnly.ReadKeyPart1At(slot),
                    readOnly.ReadKeyPart2At(slot),
                    readOnly.ReadKeyPart3At(slot),
                    key0,
                    key1,
                    key2,
                    key3);
                if (compare != 0)
                {
                    break;
                }

                if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
                {
                    deleteSlot = slot;
                    break;
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Fixed32Scalar8 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageFixed32Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitFixed32Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Inserts one encoded tuple into a shelf reached by the classified `SS8-8` route walker without performing split handling.<br/>
    /// This path supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// The classifier reads make this path more general but not cheaper than direct fast paths where the route target shape is already known.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertWalkedRoutedScalar8Scalar8NoSplit(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
        {
            if (TryDeepenMismatchedScalar8Scalar8TerminalIdentityRoute(pathTarget, profile, encodedKey, out _))
            {
                return InsertWalkedRoutedScalar8Scalar8NoSplit(rootRouterOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy);
            }

            return InsertIntoScalar8Scalar8TerminalIdentityRoute(target.Offset, profile, encodedKey, encodedIdentity, allowDuplicateKeys);
        }

        if (target.Kind == Scalar8Scalar8RouteTargetKind.None)
        {
            return InsertIntoUnsetScalar8Scalar8Route(rootRouterOffset, pathTarget, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy, retryOnChangedRoute: false);
        }

        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
        }

        byte[] existingShelf = durabilityBatchActive
            ? GetOrCreateScalar8Scalar8MutableShelfBytesForBatch(target.Offset, profile)
            : new byte[profile.ShelfExtentSize];
        if (!durabilityBatchActive)
        {
            kernel.Read(target.Offset, existingShelf);
        }

        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-8 shelf bytes are invalid.");
        }

        if (existingReadOnly.IsDuplicateRun)
        {
            return InsertIntoScalar8Scalar8DuplicateRun(target.Offset, profile, encodedKey, encodedIdentity, allowDuplicateKeys);
        }

        int existingItemCount = existingReadOnly.ItemCount;
        if (existingItemCount == 0)
        {
            if (durabilityBatchActive)
            {
                GetScalar8Scalar8MutableBatchShelfBytes().Remove(target.Offset);
            }

            RawDataReservation privateShelf = kernel.Reserve(profile.ShelfExtentSize);
            existingShelf.CopyTo(privateShelf.Span);
            Scalar8Scalar8 privateShelfView = new(privateShelf.Span, profile);
            Scalar8Scalar8InsertResult privateInsertResult = privateShelfView.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds privateMutationBounds);
            if (privateInsertResult == Scalar8Scalar8InsertResult.Inserted)
            {
                _ = TryConsumeDeletedShelfPayloadOffset(privateShelf.Extent.Offset, checked((ushort)privateMutationBounds.ItemOffset));
                if (!TryUpdateSingleByteRouterPrefixTargetIfCurrent(pathTarget.ParentRouterOffset, pathTarget.RoutePrefixByte, target.Offset, privateShelf.Extent.Offset, profile.ShelfExtentSize, out DataKernelCommitTelemetry privateLinkTelemetry))
                {
                    throw new InvalidDataException("The SS8-8 empty-shelf private route parent changed before the shelf could be linked.");
                }

                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                    privateInsertResult,
                    privateShelf.Extent.Offset,
                    privateShelf.Extent.Offset,
                    0,
                    privateLinkTelemetry);
            }

            Scalar8Scalar8RoutedInsertKind privateKind = privateInsertResult == Scalar8Scalar8InsertResult.KeyConflict
                ? Scalar8Scalar8RoutedInsertKind.KeyConflict
                : Scalar8Scalar8RoutedInsertKind.NoOp;
            return new Scalar8Scalar8RoutedInsertResult(
                privateKind,
                privateInsertResult,
                target.Offset,
                0,
                0,
                default);
        }

        Scalar8Scalar8 shelf = new(existingShelf, profile);
        Scalar8Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar8Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            DataKernelCommitTelemetry telemetry;
            if (durabilityBatchActive)
            {
                telemetry = MarkScalar8Scalar8MutableShelfChangedForBatch(target.Offset, profile, existingShelf);
            }
            else
            {
                RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
                existingShelf.CopyTo(shelfRewrite.Span);
                telemetry = CommitAndInvalidateRouterReadCache();
            }

            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        Scalar8Scalar8RoutedInsertKind kind = insertResult == Scalar8Scalar8InsertResult.KeyConflict
            ? Scalar8Scalar8RoutedInsertKind.KeyConflict
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            kind,
            insertResult,
            target.Offset,
            0,
            0,
            default);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-8` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple, to a single-shelf duplicate run that has remaining identity capacity, or to an existing terminal identity shelf that can accept a sorted insert without allocating a new shelf.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishScalar8Scalar8WriteContext"/> publishes that context.<br/>
    /// Same-shelf writer conflicts are detected when the staged shelf rewrite is claimed for the context, allowing different shelves to stage concurrently while preserving deterministic ownership for one shelf.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same encoded key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is default because publication is deferred to the writer context.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf.<br/></exception>
    /// <exception cref="InvalidOperationException">Thrown when the insert requires route topology changes, linked duplicate-run mutation, full-shelf split handling, or a shelf already owned by another writer context.<br/></exception>
    internal Scalar8Scalar8RoutedInsertResult InsertWalkedRoutedScalar8Scalar8NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar8Scalar8WriterContextStaging(rootRouterOffset);
        try
        {

            Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                Span<byte> expectedKey = stackalloc byte[Scalar8Scalar8Layout.KeySize];
                BinaryPrimitives.WriteUInt64BigEndian(expectedKey, encodedKey);
                if (TryInsertTerminalIdentity8ForWriteContext(
                    writeContext,
                    target.Offset,
                    expectedKey,
                    profile.ShelfExtentSize,
                    encodedIdentity,
                    allowDuplicateKeys,
                    out Scalar8Scalar8RoutedInsertResult terminalIdentityAppend))
                {
                    return terminalIdentityAppend;
                }

                throw new InvalidOperationException("The SS8-8 writer-context insert cannot mutate this terminal-identity route because it requires root publication, a new linked shelf, or cross-shelf rebalancing.");
            }

            if (target.Kind == Scalar8Scalar8RouteTargetKind.None)
            {
                throw new InvalidOperationException("The SS8-8 writer-context insert cannot initialize an unset route because route publication is still serialized outside writer contexts.");
            }

            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
            }

            byte[] existingShelf = ReadScalar8Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar8Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS8-8 shelf bytes are invalid.");
            }

            if (existingReadOnly.IsDuplicateRun)
            {
                Scalar8Scalar8 duplicateRunShelf = new(existingShelf, profile);
                Scalar8Scalar8InsertResult duplicateRunInsertResult = duplicateRunShelf.InsertIntoSingleShelfDuplicateRun(encodedKey, encodedIdentity, allowDuplicateKeys);
                if (duplicateRunInsertResult == Scalar8Scalar8InsertResult.Inserted)
                {
                    StageScalar8Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                    return new Scalar8Scalar8RoutedInsertResult(
                        Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                        duplicateRunInsertResult,
                        target.Offset,
                        target.Offset,
                        0,
                        default);
                }

                if (duplicateRunInsertResult == Scalar8Scalar8InsertResult.AlreadyPresent)
                {
                    return new Scalar8Scalar8RoutedInsertResult(
                        Scalar8Scalar8RoutedInsertKind.NoOp,
                        duplicateRunInsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                }

                if (duplicateRunInsertResult == Scalar8Scalar8InsertResult.KeyConflict)
                {
                    return new Scalar8Scalar8RoutedInsertResult(
                        Scalar8Scalar8RoutedInsertKind.KeyConflict,
                        duplicateRunInsertResult,
                        target.Offset,
                        0,
                        0,
                        default);
                }

                throw new InvalidOperationException("The SS8-8 writer-context insert cannot mutate a linked or full duplicate-run shelf because that path may require append or chain publication.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The SS8-8 writer-context insert cannot mutate an empty routed shelf because the current serialized path relinks empty shelves before publication.");
            }

            Scalar8Scalar8 shelf = new(existingShelf, profile);
            Scalar8Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out _);
            if (insertResult == Scalar8Scalar8InsertResult.Inserted)
            {
                StageScalar8Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar8InsertResult.AlreadyPresent)
            {
                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar8InsertResult.KeyConflict)
            {
                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Scalar8Scalar8InsertResult.Full)
            {
                throw new InvalidOperationException("The SS8-8 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported SS8-8 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitScalar8Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `SS8-8` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is intentionally bounded to a route that resolves to a non-empty ordinary shelf, a single-shelf duplicate run, or one terminal identity shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// Linked duplicate-run chain work and route cleanup return to serialized mutation paths because they may allocate, relink, or rewrite topology outside one owned shelf.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to delete.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity value to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing or shelf bytes are invalid.<br/></exception>
    /// <exception cref="InvalidOperationException">Thrown when the delete requires topology mutation outside a single owned shelf.<br/></exception>
    internal bool DeleteWalkedRoutedScalar8Scalar8ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterScalar8Scalar8WriterContextStaging(rootRouterOffset);
        try
        {
            Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
            Scalar8Scalar8RouteTarget target = pathTarget.Target;
            if (target.Kind == Scalar8Scalar8RouteTargetKind.None)
            {
                return false;
            }

            if (target.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
            {
                return TryDeleteTerminalIdentity8ForWriteContext(
                    writeContext,
                    target.Offset,
                    profile.ShelfExtentSize,
                    encodedKey,
                    encodedIdentity);
            }

            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
            }

            byte[] existingShelf = ReadScalar8Scalar8ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordScalar8Scalar8RouteClaimForWriteContext(writeContext, pathTarget);
            Scalar8Scalar8ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed SS8-8 delete shelf bytes are invalid.");
            }

            int deleteSlot = -1;
            if (readOnly.IsDuplicateRun)
            {
                if (Scalar8Scalar8Layout.ReadDuplicateRunKey(existingShelf) != encodedKey)
                {
                    throw new InvalidOperationException("The SS8-8 writer-context delete cannot mutate this duplicate-run route because the routed shelf is not a matching duplicate run.");
                }

                long currentOffset = target.Offset;
                while (currentOffset != 0)
                {
                    if (currentOffset != target.Offset)
                    {
                        existingShelf = ReadScalar8Scalar8ShelfBytesForWriteContext(writeContext, currentOffset, profile);
                        readOnly = new Scalar8Scalar8ReadOnly(existingShelf, profile);
                        if (!readOnly.IsValid ||
                            !readOnly.IsDuplicateRun ||
                            Scalar8Scalar8Layout.ReadDuplicateRunKey(existingShelf) != encodedKey)
                        {
                            throw new InvalidDataException("The routed SS8-8 duplicate-run writer-context delete chain contains invalid shelf bytes.");
                        }
                    }

                    for (int slot = 0; slot < readOnly.ItemCount; slot++)
                    {
                        if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
                        {
                            Scalar8Scalar8 duplicateRunShelf = new(existingShelf, profile);
                            int duplicateRunRemoved = duplicateRunShelf.RemoveSlotRange(slot, 1);
                            if (duplicateRunRemoved != 1)
                            {
                                return false;
                            }

                            StageScalar8Scalar8ShelfRewriteForWriteContext(writeContext, currentOffset, profile, existingShelf);
                            return true;
                        }
                    }

                    currentOffset = readOnly.DuplicateRunNextOffset;
                }

                return false;
            }
            else
            {
                int startSlot = readOnly.LowerBoundKey(encodedKey);
                for (int slot = startSlot; slot < readOnly.ItemCount && readOnly.ReadKeyAt(slot) == encodedKey; slot++)
                {
                    if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
                    {
                        deleteSlot = slot;
                        break;
                    }
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Scalar8Scalar8 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageScalar8Scalar8ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitScalar8Scalar8WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one identity from an existing scalar terminal identity route through an isolated writer context.<br/>
    /// This helper is intentionally shelf-local: it may rewrite the one terminal identity shelf that contains the target identity, but it does not relink shelves, remove an empty root, or compact the terminal chain.<br/>
    /// Leaving an empty terminal shelf/root is valid published index state and keeps the common exact-delete path independent from route-topology publication.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged terminal shelf bytes until publish or abort.<br/></param>
    /// <param name="rootOffset">The terminal identity root offset reached by the route walker.<br/></param>
    /// <param name="shelfExtentSize">The fixed extent size for every terminal identity shelf under this root.<br/></param>
    /// <param name="encodedKey">The encoded scalar key expected on the terminal identity root.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to remove.<br/></param>
    /// <returns><see langword="true"/> when the identity was found and staged for deletion; otherwise <see langword="false"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the terminal root or shelf chain is structurally invalid.<br/></exception>
    /// <exception cref="LibraDexWriteContextTerminalIdentityShelfOwnershipException">Thrown when another writer context already owns the target terminal identity shelf.<br/></exception>
    private bool TryDeleteTerminalIdentity8ForWriteContext(
        LibraDexWriteContext writeContext,
        long rootOffset,
        int shelfExtentSize,
        ulong encodedKey,
        ulong encodedIdentity)
    {
        Span<byte> expectedKey = stackalloc byte[Scalar8Scalar8Layout.KeySize];
        BinaryPrimitives.WriteUInt64BigEndian(expectedKey, encodedKey);
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeScalar8 ||
            !IsTerminalIdentityRootForKey(rootBytes, expectedKey, out long shelfOffset))
        {
            throw new InvalidDataException("The routed SS8-8 terminal identity delete root does not match the encoded key.");
        }

        while (shelfOffset != 0)
        {
            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytesForWriteContext(writeContext, shelfOffset, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
            int deleteIndex = -1;
            for (int i = 0; i < count; i++)
            {
                ulong current = TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i);
                if (current == encodedIdentity)
                {
                    deleteIndex = i;
                    break;
                }

                if (current > encodedIdentity)
                {
                    return false;
                }
            }

            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
            if (deleteIndex >= 0)
            {
                for (int i = deleteIndex + 1; i < count; i++)
                {
                    TerminalIdentity8ShelfLayout.WriteIdentity(shelfBytes, i - 1, TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i));
                }

                TerminalIdentity8ShelfLayout.WriteItemCount(shelfBytes, count - 1);
                StageTerminalIdentity8ShelfRewriteForWriteContext(writeContext, shelfOffset, shelfExtentSize, shelfBytes);
                return true;
            }

            shelfOffset = nextOffset;
        }

        return false;
    }

    /// <summary>
    /// Deletes one exact encoded `SS8-8` tuple through the classified route walker and publishes the mutation immediately.<br/>
    /// This serialized path is used by queued delete fallback for terminal identity roots and other cases that are not writer-context isolated yet.<br/>
    /// The method intentionally avoids route cleanup; empty shelves or roots remain valid published index state and can be reused or compacted by future maintenance.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="encodedKey">The encoded scalar key to delete.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity value to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.<br/></param>
    /// <param name="telemetry">Receives commit telemetry when the tuple was deleted.<br/></param>
    /// <returns>True when one tuple was deleted; false when the exact tuple was not present.<br/></returns>
    /// <exception cref="InvalidDataException">Thrown when routing or shelf bytes are invalid.<br/></exception>
    internal bool DeleteWalkedRoutedScalar8Scalar8Exact(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == Scalar8Scalar8RouteTargetKind.None)
        {
            return false;
        }

        if (target.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
        {
            int deleted = DeleteScalar8Scalar8TerminalIdentities(target.Offset, profile, encodedKey, encodedIdentity);
            return deleted == 1;
        }

        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
        }

        byte[] shelfBytes = durabilityBatchActive
            ? ReadScalar8Scalar8ShelfBytesForBatch(target.Offset, profile)
            : new byte[profile.ShelfExtentSize];
        if (!durabilityBatchActive)
        {
            kernel.Read(target.Offset, shelfBytes);
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-8 delete shelf bytes are invalid.");
        }

        int deleteSlot = -1;
        if (readOnly.IsDuplicateRun)
        {
            if (readOnly.ItemCount == 0 || readOnly.ReadKeyAt(0) != encodedKey)
            {
                return false;
            }

            long currentOffset = target.Offset;
            while (currentOffset != 0)
            {
                if (currentOffset != target.Offset)
                {
                    kernel.Read(currentOffset, shelfBytes);
                    readOnly = new Scalar8Scalar8ReadOnly(shelfBytes, profile);
                    if (!readOnly.IsValid || !readOnly.IsDuplicateRun || readOnly.ReadKeyAt(0) != encodedKey)
                    {
                        throw new InvalidDataException("The routed SS8-8 duplicate-run delete chain contains invalid shelf bytes.");
                    }
                }

                for (int slot = 0; slot < readOnly.ItemCount; slot++)
                {
                    if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
                    {
                        Scalar8Scalar8 duplicateRunShelf = new(shelfBytes, profile);
                        int removed = duplicateRunShelf.RemoveSlotRange(slot, 1);
                        if (removed != 1)
                        {
                            return false;
                        }

                        telemetry = StageScalar8Scalar8ShelfRewriteForBatch(currentOffset, profile, shelfBytes);
                        return true;
                    }
                }

                currentOffset = readOnly.DuplicateRunNextOffset;
            }

            return false;
        }

        int startSlot = readOnly.LowerBoundKey(encodedKey);
        for (int slot = startSlot; slot < readOnly.ItemCount && readOnly.ReadKeyAt(slot) == encodedKey; slot++)
        {
            if (readOnly.ReadIdentityAt(slot) == encodedIdentity)
            {
                deleteSlot = slot;
                break;
            }
        }

        if (deleteSlot < 0)
        {
            return false;
        }

        Scalar8Scalar8 shelf = new(shelfBytes, profile);
        int removedFromShelf = shelf.RemoveSlotRange(deleteSlot, 1);
        if (removedFromShelf != 1)
        {
            return false;
        }

        telemetry = StageScalar8Scalar8ShelfRewriteForBatch(target.Offset, profile, shelfBytes);
        return true;
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-8` route walker and handles the first deeper split case.<br/>
    /// The current deeper split case is same-prefix transmorphic growth: when the walked target shelf is full, that shelf offset is rewritten as the next-depth router and two replacement shelves are appended.<br/>
    /// This keeps the parent router stable and makes file growth/slack behavior measurable before adding parent-router route refinement below the root.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.</param>
    /// <param name="retryUnsetRouteChanges">Whether an unset-route publish mismatch should clear router caches and retry the insert once.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf or the split cannot be selected safely.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertWalkedRoutedScalar8Scalar8(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached,
        bool retryUnsetRouteChanges = true)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == Scalar8Scalar8RouteTargetKind.TerminalIdentityRoot)
        {
            if (TryDeepenMismatchedScalar8Scalar8TerminalIdentityRoute(pathTarget, profile, encodedKey, out _))
            {
                return InsertWalkedRoutedScalar8Scalar8(rootRouterOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy);
            }

            return InsertIntoScalar8Scalar8TerminalIdentityRoute(target.Offset, profile, encodedKey, encodedIdentity, allowDuplicateKeys);
        }

        if (target.Kind == Scalar8Scalar8RouteTargetKind.None)
        {
            return InsertIntoUnsetScalar8Scalar8Route(rootRouterOffset, pathTarget, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy, retryOnChangedRoute: retryUnsetRouteChanges);
        }

        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
        }

        byte[] existingShelf = durabilityBatchActive
            ? GetOrCreateScalar8Scalar8MutableShelfBytesForBatch(target.Offset, profile)
            : new byte[profile.ShelfExtentSize];
        if (!durabilityBatchActive)
        {
            kernel.Read(target.Offset, existingShelf);
        }

        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-8 shelf bytes are invalid.");
        }

        if (existingReadOnly.IsDuplicateRun)
        {
            return InsertIntoScalar8Scalar8DuplicateRun(target.Offset, profile, encodedKey, encodedIdentity, allowDuplicateKeys);
        }

        int existingItemCount = existingReadOnly.ItemCount;
        if (existingItemCount == 0)
        {
            if (durabilityBatchActive)
            {
                GetScalar8Scalar8MutableBatchShelfBytes().Remove(target.Offset);
            }

            RawDataReservation privateShelf = kernel.Reserve(profile.ShelfExtentSize);
            existingShelf.CopyTo(privateShelf.Span);
            Scalar8Scalar8 privateShelfView = new(privateShelf.Span, profile);
            Scalar8Scalar8InsertResult privateInsertResult = privateShelfView.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds privateMutationBounds);
            if (privateInsertResult == Scalar8Scalar8InsertResult.Inserted)
            {
                _ = TryConsumeDeletedShelfPayloadOffset(privateShelf.Extent.Offset, checked((ushort)privateMutationBounds.ItemOffset));
                if (!TryUpdateSingleByteRouterPrefixTargetIfCurrent(pathTarget.ParentRouterOffset, pathTarget.RoutePrefixByte, target.Offset, privateShelf.Extent.Offset, profile.ShelfExtentSize, out DataKernelCommitTelemetry privateLinkTelemetry))
                {
                    throw new InvalidDataException("The SS8-8 empty-shelf private route parent changed before the shelf could be linked.");
                }

                return new Scalar8Scalar8RoutedInsertResult(
                    Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                    privateInsertResult,
                    privateShelf.Extent.Offset,
                    privateShelf.Extent.Offset,
                    0,
                    privateLinkTelemetry);
            }

            Scalar8Scalar8RoutedInsertKind privateKind = privateInsertResult == Scalar8Scalar8InsertResult.KeyConflict
                ? Scalar8Scalar8RoutedInsertKind.KeyConflict
                : Scalar8Scalar8RoutedInsertKind.NoOp;
            return new Scalar8Scalar8RoutedInsertResult(
                privateKind,
                privateInsertResult,
                target.Offset,
                0,
                0,
                default);
        }

        Scalar8Scalar8 shelf = new(existingShelf, profile);
        Scalar8Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar8Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            DataKernelCommitTelemetry telemetry;
            if (durabilityBatchActive)
            {
                telemetry = MarkScalar8Scalar8MutableShelfChangedForBatch(target.Offset, profile, existingShelf);
            }
            else
            {
                RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
                existingShelf.CopyTo(shelfRewrite.Span);
                telemetry = CommitAndInvalidateRouterReadCache();
            }

            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar8Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar8Scalar8InsertResult.KeyConflict)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar8Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS8-8 walked insert result {insertResult}.");
        }

        if (existingReadOnly.ItemCount != 0 &&
            existingReadOnly.ReadKeyAt(0) == encodedKey &&
            existingReadOnly.ReadKeyAt(existingReadOnly.ItemCount - 1) == encodedKey)
        {
            if (target.RouterDepth + 1 < Scalar8Scalar8Layout.KeySize)
            {
                ushort duplicateRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
                _ = DeepenScalar8Scalar8DuplicateKeyRoute(
                    target.Offset,
                    existingShelf,
                    profile,
                    encodedKey,
                    duplicateRouterKeyDepth,
                    target.AllocationClassId);
                return InsertWalkedRoutedScalar8Scalar8(rootRouterOffset, profile, encodedKey, encodedIdentity, allowDuplicateKeys, maxRouterHops, readPolicy);
            }

            return InsertOrConvertScalar8Scalar8DuplicateRun(
                pathTarget,
                existingShelf,
                profile,
                encodedKey,
                encodedIdentity,
                allowDuplicateKeys);
        }

        if (TrySplitRoutedScalar8Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKey,
            encodedIdentity,
            target.AllocationClassId,
            out Scalar8Scalar8RoutedInsertResult parentRouteSplit))
        {
            return parentRouteSplit;
        }

        if (target.RouterDepth + 1 >= Scalar8Scalar8Layout.KeySize)
        {
            throw new InvalidDataException("The SS8-8 split path exhausted key routing bytes without a duplicate-run candidate.");
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long leftShelfOffset,
            long rightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKey,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar8Scalar8RoutedInsertKind kind = transformResult == Scalar8Scalar8InsertResult.Inserted
            ? Scalar8Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            leftShelfOffset,
            rightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Splits a full max-growth `VS8` shelf by transforming that shelf offset into a direct child router.<br/>
    /// The full shelf plus incoming tuple are merged in persisted key/identity order, a median-near raw-key byte boundary is selected, and two replacement shelves are appended.<br/>
    /// If all rows share the immediate child byte, the method appends a short router chain until a later raw-key byte can divide the replacement shelves.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset identifying the `VS8` index.</param>
    /// <param name="parentRouterOffset">The parent router currently owning the full shelf target.</param>
    /// <param name="routeIndex">The selected physical route index in the parent router.</param>
    /// <param name="childRouterOffset">The existing shelf offset that will be rewritten as a child router or retained as the left shelf by a parent-range split.</param>
    /// <param name="parentHasDirectIndex">Whether the parent uses the expanded direct-index representation.</param>
    /// <param name="parentRangeStart">The inclusive prefix start of the logical parent target range.</param>
    /// <param name="parentRangeEnd">The inclusive prefix end of the logical parent target range.</param>
    /// <param name="parentFinalKeyDepth">The final raw-key byte depth consumed by the parent route.</param>
    /// <param name="existingShelf">The full existing shelf as a mutable decoded sidecar.</param>
    /// <param name="rightPrefixByte">The incoming key prefix byte at <paramref name="childRouterKeyDepth"/>.</param>
    /// <param name="profile">The current max-growth `VS8` shelf profile.</param>
    /// <param name="key">The incoming raw byte key.</param>
    /// <param name="encodedIdentity">The incoming encoded identity.</param>
    /// <param name="allocationClassId">The router allocation class identifier to preserve.</param>
    /// <param name="childRouterKeyDepth">The key byte depth owned by the router replacing the shelf.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        VarKeyScalar8InsertResult InsertResult,
        bool Published,
        DataKernelCommitTelemetry Commit) SplitRoutedVarKeyScalar8ByShelfTransform(
        long rootRouterOffset,
        long parentRouterOffset,
        int routeIndex,
        long childRouterOffset,
        bool parentHasDirectIndex,
        int parentRangeStart,
        int parentRangeEnd,
        ushort parentFinalKeyDepth,
        VarKeyScalar8MutableShelf existingShelf,
        byte rightPrefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        ushort allocationClassId,
        ushort childRouterKeyDepth,
        VarKeyScalar8RouteMutationHint routeMutationHint)
    {
        if (existingShelf.Bytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled VS8 shelf extent size.", nameof(existingShelf));
        }

        if (!TryCreateVarKeyScalar8SplitShelves(
            existingShelf,
            childRouterKeyDepth,
            rightPrefixByte,
            profile,
            key,
            encodedIdentity,
            out ushort splitKeyDepth,
            out byte selectedRightPrefixByte,
            out byte[] selectedPrefixStem,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out int leftItemCount,
            out int rightItemCount,
            out VarKeyScalar8InsertResult insertResult))
        {
            return (childRouterOffset, 0, 0, 0, 0, insertResult, true, default);
        }

        try
        {
            if (!TryPublishVarKeyScalar8DirectShelfTransform(
                rootRouterOffset,
                parentRouterOffset,
                routeIndex,
                childRouterOffset,
                parentHasDirectIndex,
                parentRangeStart,
                parentRangeEnd,
                parentFinalKeyDepth,
                allocationClassId,
                childRouterKeyDepth,
                splitKeyDepth,
                selectedRightPrefixByte,
                selectedPrefixStem,
                routeMutationHint,
                profile,
                leftShelfBytes,
                rightShelfBytes,
                out DataKernelCommitTelemetry telemetry,
                out long leftShelfOffset,
                out long rightShelfOffset))
            {
                return (childRouterOffset, 0, 0, leftItemCount, rightItemCount, insertResult, false, default);
            }

            return (childRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, true, telemetry);
        }
        finally
        {
            ReturnTemporaryVarKeyScalar8SplitShelfBytes(leftShelfBytes);
            ReturnTemporaryVarKeyScalar8SplitShelfBytes(rightShelfBytes);
        }
    }

    /// <summary>
    /// Creates two replacement shelves for a full `VS8` shelf at a selected raw-key byte boundary.<br/>
    /// The method keeps raw bytes as the comparison source, preserving the current storage model and avoiding text or typed projection in the shelf layer.<br/>
    /// Returning false means the key set cannot be separated by any available raw-key byte and therefore needs a later overflow/duplicate strategy.<br/>
    /// </summary>
    /// <param name="existingShelf">The full existing shelf as a decoded mutable sidecar.</param>
    /// <param name="firstKeyDepth">The first raw key byte depth to consider for the replacement router.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="profile">The `VS8` shelf profile used for both replacement shelves.</param>
    /// <param name="key">The incoming raw byte key.</param>
    /// <param name="encodedIdentity">The incoming encoded identity.</param>
    /// <param name="splitKeyDepth">The raw key byte depth selected for the split boundary.</param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private bool TryCreateVarKeyScalar8SplitShelves(
        VarKeyScalar8MutableShelf existingShelf,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        out ushort splitKeyDepth,
        out byte selectedRightPrefixByte,
        out byte[] selectedPrefixStem,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out VarKeyScalar8InsertResult insertResult)
    {
        splitKeyDepth = 0;
        selectedRightPrefixByte = 0;
        selectedPrefixStem = [];
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        int existingCount = existingShelf.ItemCount;
        int totalCount = checked(existingCount + 1);
        int[] rentedKeyOffsets = ArrayPool<int>.Shared.Rent(totalCount);
        int[] rentedKeyLengths = ArrayPool<int>.Shared.Rent(totalCount);
        ulong[] rentedIdentities = ArrayPool<ulong>.Shared.Rent(totalCount);
        try
        {
            Span<int> keyOffsets = rentedKeyOffsets.AsSpan(0, totalCount);
            Span<int> keyLengths = rentedKeyLengths.AsSpan(0, totalCount);
            Span<ulong> identities = rentedIdentities.AsSpan(0, totalCount);
            bool inserted = false;
            int targetIndex = 0;
            for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
            {
                ReadOnlySpan<byte> currentKey = existingShelf.ReadKeyAt(sourceIndex);
                ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
                if (!inserted && CompareVarKeyScalar8Tuple(currentKey, currentIdentity, key, encodedIdentity) > 0)
                {
                    keyOffsets[targetIndex] = -1;
                    keyLengths[targetIndex] = key.Length;
                    identities[targetIndex] = encodedIdentity;
                    targetIndex++;
                    inserted = true;
                }

                if (currentKey.SequenceEqual(key) && currentIdentity == encodedIdentity)
                {
                    insertResult = VarKeyScalar8InsertResult.AlreadyPresent;
                    return false;
                }

                existingShelf.ReadKeyLocationAt(sourceIndex, out int currentKeyOffset, out int currentKeyLength);
                keyOffsets[targetIndex] = currentKeyOffset;
                keyLengths[targetIndex] = currentKeyLength;
                identities[targetIndex] = currentIdentity;
                targetIndex++;
            }

            if (!inserted)
            {
                keyOffsets[targetIndex] = -1;
                keyLengths[targetIndex] = key.Length;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
            }

            if (targetIndex != totalCount)
            {
                throw new InvalidDataException("The VS8 transform split source map did not cover the complete tuple set.");
            }

            (splitKeyDepth, selectedRightPrefixByte) = ChooseVarKeyScalar8TransformSplitPlan(
                existingShelf,
                keyOffsets,
                keyLengths,
                key,
                firstKeyDepth,
                hintRightPrefixByte,
                profile.MaxKeyLength);
            selectedPrefixStem = CreateVarKeyScalar8SplitPrefixStem(
                ReadVarKeyScalar8SplitSourceKey(existingShelf.Bytes, keyOffsets[0], keyLengths[0], key),
                firstKeyDepth,
                splitKeyDepth);
            if (!TryBuildVarKeyScalar8SplitShelvesFromSources(
                existingShelf,
                keyOffsets,
                keyLengths,
                identities,
                key,
                splitKeyDepth,
                selectedRightPrefixByte,
                profile,
                out leftShelfBytes,
                out rightShelfBytes,
                out leftItemCount,
                out rightItemCount))
            {
                return false;
            }

            insertResult = VarKeyScalar8InsertResult.Inserted;
            return true;
        }
        finally
        {
            ArrayPool<int>.Shared.Return(rentedKeyOffsets, clearArray: false);
            ArrayPool<int>.Shared.Return(rentedKeyLengths, clearArray: false);
            ArrayPool<ulong>.Shared.Return(rentedIdentities, clearArray: false);
        }
    }

    /// <summary>
    /// Builds the two replacement `VS8` shelves directly from the sorted split source map.<br/>
    /// The method writes disk-shaped shelf images in one pass and avoids cloned key arrays, tuple lists, and a second read-only shelf decode.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="identities">The sorted encoded identities matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="splitKeyDepth">The raw-key byte depth selected for the split boundary.</param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.</param>
    /// <param name="profile">The `VS8` shelf profile used by both replacement shelves.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples written to the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples written to the right replacement shelf.</param>
    /// <returns>`true` when both replacement shelves were non-empty and fit the current profile.</returns>
    private bool TryBuildVarKeyScalar8SplitShelvesFromSources(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<ulong> identities,
        ReadOnlySpan<byte> incomingKey,
        ushort splitKeyDepth,
        byte selectedRightPrefixByte,
        VarKeyScalar8Profile profile,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount)
    {
        leftShelfBytes = RentTemporaryVarKeyScalar8SplitShelfBytes(profile.ShelfExtentSize);
        rightShelfBytes = RentTemporaryVarKeyScalar8SplitShelfBytes(profile.ShelfExtentSize);
        VarKeyScalar8Layout.Initialize(leftShelfBytes, profile);
        VarKeyScalar8Layout.Initialize(rightShelfBytes, profile);

        int leftSlotCursor = VarKeyScalar8Layout.HeaderSize;
        int rightSlotCursor = VarKeyScalar8Layout.HeaderSize;
        int leftRecordCursor = VarKeyScalar8Layout.HeaderSize + VarKeyScalar8Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightRecordCursor = VarKeyScalar8Layout.HeaderSize + VarKeyScalar8Layout.ReadSlotCapacityBytes(rightShelfBytes);
        int leftSlotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightSlotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(rightShelfBytes);
        leftItemCount = 0;
        rightItemCount = 0;

        for (int i = 0; i < keyOffsets.Length; i++)
        {
            ReadOnlySpan<byte> currentKey = ReadVarKeyScalar8SplitSourceKey(existingShelf.Bytes, keyOffsets[i], keyLengths[i], incomingKey);
            ulong currentIdentity = identities[i];
            bool goesRight = GetVarKeyScalar8SplitSourcePrefix(existingShelf.Bytes, keyOffsets[i], keyLengths[i], incomingKey, splitKeyDepth) >= selectedRightPrefixByte;
            byte[] targetBytes = goesRight ? rightShelfBytes : leftShelfBytes;
            int slotCursor = goesRight ? rightSlotCursor : leftSlotCursor;
            int recordCursor = goesRight ? rightRecordCursor : leftRecordCursor;
            int slotCapacityBytes = goesRight ? rightSlotCapacityBytes : leftSlotCapacityBytes;
            if (slotCursor + VarKeyScalar8Layout.SlotSize > VarKeyScalar8Layout.HeaderSize + slotCapacityBytes)
            {
                ReturnFailedTemporaryVarKeyScalar8SplitShelfBytes(ref leftShelfBytes, ref rightShelfBytes);
                return false;
            }

            int recordLength = VarKeyScalar8Layout.GetNewRecordLength(currentKey.Length);
            if (recordCursor + recordLength > profile.ShelfExtentSize)
            {
                ReturnFailedTemporaryVarKeyScalar8SplitShelfBytes(ref leftShelfBytes, ref rightShelfBytes);
                return false;
            }

            VarKeyScalar8Layout.WriteRecord(targetBytes, recordCursor, currentKey, currentIdentity);
            VarKeyScalar8Layout.WriteSlotRecordOffset(targetBytes, slotCursor, recordCursor);
            VarKeyScalar8Layout.WriteSlotKeyPrefix(targetBytes, slotCursor, VarKeyScalar8Layout.CreateKeyPrefix(currentKey));
            slotCursor += VarKeyScalar8Layout.SlotSize;
            recordCursor += recordLength;
            if (goesRight)
            {
                rightSlotCursor = slotCursor;
                rightRecordCursor = recordCursor;
                rightItemCount++;
            }
            else
            {
                leftSlotCursor = slotCursor;
                leftRecordCursor = recordCursor;
                leftItemCount++;
            }
        }

        if (leftItemCount == 0 || rightItemCount == 0)
        {
            ReturnFailedTemporaryVarKeyScalar8SplitShelfBytes(ref leftShelfBytes, ref rightShelfBytes);
            return false;
        }

        VarKeyScalar8Layout.WriteItemCount(leftShelfBytes, leftItemCount);
        VarKeyScalar8Layout.WriteSlotStreamLength(leftShelfBytes, leftSlotCursor - VarKeyScalar8Layout.HeaderSize);
        VarKeyScalar8Layout.WriteRecordArenaEnd(leftShelfBytes, leftRecordCursor);
        VarKeyScalar8Layout.WriteItemCount(rightShelfBytes, rightItemCount);
        VarKeyScalar8Layout.WriteSlotStreamLength(rightShelfBytes, rightSlotCursor - VarKeyScalar8Layout.HeaderSize);
        VarKeyScalar8Layout.WriteRecordArenaEnd(rightShelfBytes, rightRecordCursor);
        return true;
    }

    /// <summary>
    /// Rents a temporary `VS8` split shelf image using the same bounded byte reuse path as mutable shelf reads.<br/>
    /// Split builders are hot for clustered variable-length keys such as file paths, and reusing these images avoids repeated large-array allocation during router transforms.<br/>
    /// </summary>
    /// <param name="shelfExtentSize">The exact shelf extent size needed for the split output image.</param>
    /// <returns>A byte image large enough for one `VS8` split output shelf.</returns>
    private byte[] RentTemporaryVarKeyScalar8SplitShelfBytes(int shelfExtentSize)
    {
        return RentMutableShelfBytes(shelfExtentSize, out _);
    }

    /// <summary>
    /// Returns one successful temporary `VS8` split shelf image after its bytes have been copied to the target DataKernel reservation.<br/>
    /// The returned image is intentionally not cleared; the next split initialization overwrites the header and the written record/slot region, avoiding a large memory clear on the write path.<br/>
    /// </summary>
    /// <param name="bytes">The temporary split shelf image to return.</param>
    private void ReturnTemporaryVarKeyScalar8SplitShelfBytes(byte[] bytes)
    {
        if (bytes.Length <= PooledMutableShelfMaxBytes)
        {
            ArrayPool<byte>.Shared.Return(bytes, clearArray: false);
            return;
        }

        ReturnLargeMutableShelfBytes(bytes);
    }

    /// <summary>
    /// Returns both temporary `VS8` split shelf images when split construction cannot produce a valid left/right pair.<br/>
    /// The out references are reset to empty arrays so failure callers cannot accidentally copy a returned buffer.<br/>
    /// </summary>
    /// <param name="leftShelfBytes">The left temporary shelf image reference to return and clear.</param>
    /// <param name="rightShelfBytes">The right temporary shelf image reference to return and clear.</param>
    private void ReturnFailedTemporaryVarKeyScalar8SplitShelfBytes(ref byte[] leftShelfBytes, ref byte[] rightShelfBytes)
    {
        ReturnTemporaryVarKeyScalar8SplitShelfBytes(leftShelfBytes);
        ReturnTemporaryVarKeyScalar8SplitShelfBytes(rightShelfBytes);
        leftShelfBytes = [];
        rightShelfBytes = [];
    }

    /// <summary>
    /// Reads a key from the split source map without cloning it into an intermediate array.<br/>
    /// A negative source slot represents the incoming tuple; non-negative slots point at the existing mutable shelf sidecar.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlot">The source slot index, or a negative value for the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <returns>The key bytes for the mapped source tuple.</returns>
    private static ReadOnlySpan<byte> ReadVarKeyScalar8SplitSourceKey(
        VarKeyScalar8MutableShelf existingShelf,
        int sourceSlot,
        ReadOnlySpan<byte> incomingKey)
    {
        return sourceSlot < 0 ? incomingKey : existingShelf.ReadKeyAt(sourceSlot);
    }

    /// <summary>
    /// Reads a key from predecoded split key-location arrays without decoding the shelf record header again.<br/>
    /// A negative key offset represents the incoming tuple; non-negative offsets point at raw key payload bytes in the existing shelf image.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <returns>The key bytes for the mapped source tuple.</returns>
    private static ReadOnlySpan<byte> ReadVarKeyScalar8SplitSourceKey(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey)
    {
        return keyOffset < 0 ? incomingKey : existingShelfBytes.AsSpan(keyOffset, keyLength);
    }

    /// <summary>
    /// Reads one split-boundary prefix byte from predecoded key-location arrays without constructing a span.<br/>
    /// This is used by deep shared-prefix scans where the same source descriptors are probed at many raw-key depths.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to read.</param>
    /// <returns>The prefix byte at <paramref name="keyDepth"/>, or zero when the depth is beyond the key length.</returns>
    private static byte GetVarKeyScalar8SplitSourcePrefix(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey,
        int keyDepth)
    {
        if (keyDepth < 0)
        {
            return 0;
        }

        if (keyOffset < 0)
        {
            return keyDepth < incomingKey.Length ? incomingKey[keyDepth] : (byte)0;
        }

        return keyDepth < keyLength ? existingShelfBytes[keyOffset + keyDepth] : (byte)0;
    }

    /// <summary>
    /// Reads an encoded identity from the split source map without creating an intermediate tuple object.<br/>
    /// A negative source slot represents the incoming tuple; non-negative slots point at the existing mutable shelf sidecar.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlot">The source slot index, or a negative value for the incoming tuple.</param>
    /// <param name="incomingIdentity">The incoming encoded 8-byte identity.</param>
    /// <returns>The encoded identity for the mapped source tuple.</returns>
    private static ulong ReadVarKeyScalar8SplitSourceIdentity(
        VarKeyScalar8MutableShelf existingShelf,
        int sourceSlot,
        ulong incomingIdentity)
    {
        return sourceSlot < 0 ? incomingIdentity : existingShelf.ReadIdentityAt(sourceSlot);
    }

    private static byte[] CreateVarKeyScalar8SplitPrefixStem(ReadOnlySpan<byte> representativeKey, ushort firstKeyDepth, ushort splitKeyDepth)
    {
        int stemLength = splitKeyDepth - firstKeyDepth;
        byte[] stem = new byte[stemLength];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar8Prefix(representativeKey, firstKeyDepth + i);
        }

        return stem;
    }

    private static VarKeyScalar8TransformRouterPlan ChooseVarKeyScalar8TransformRouterPlan(
        ushort childRouterKeyDepth,
        ushort splitKeyDepth,
        ReadOnlySpan<byte> selectedPrefixStem,
        VarKeyScalar8RouteMutationHint routeMutationHint)
    {
        if (splitKeyDepth == childRouterKeyDepth)
        {
            return VarKeyScalar8TransformRouterPlan.ExpandedOneByte;
        }

        return VarKeyScalar8TransformRouterPlan.ExpandedOneByteChain;
    }

    private void RecordVarKeyScalar8RouteMutationHint(
        long parentRouterOffset,
        int routeIndex,
        VarKeyScalar8MutationHint mutationHint)
    {
        if (!mutationHint.Sampled || routeIndex < 0)
        {
            return;
        }

        VarKeyScalar8RouteHintKey key = new(parentRouterOffset, routeIndex);
        if (varKeyScalar8RouteMutationHints.TryGetValue(key, out VarKeyScalar8RouteMutationHint current))
        {
            varKeyScalar8RouteMutationHints[key] = new VarKeyScalar8RouteMutationHint(
                SampleCount: checked(current.SampleCount + 1),
                MaxCommonPrefixBytes: Math.Max(current.MaxCommonPrefixBytes, mutationHint.MaxCommonPrefixBytes),
                MaxCommonPrefixDepth: Math.Max(current.MaxCommonPrefixDepth, mutationHint.MaxCommonPrefixDepth));
            return;
        }

        varKeyScalar8RouteMutationHints[key] = new VarKeyScalar8RouteMutationHint(
            SampleCount: 1,
            MaxCommonPrefixBytes: mutationHint.MaxCommonPrefixBytes,
            MaxCommonPrefixDepth: mutationHint.MaxCommonPrefixDepth);
    }

    private VarKeyScalar8RouteMutationHint GetVarKeyScalar8RouteMutationHint(long parentRouterOffset, int routeIndex)
    {
        return routeIndex >= 0 &&
            varKeyScalar8RouteMutationHints.TryGetValue(new VarKeyScalar8RouteHintKey(parentRouterOffset, routeIndex), out VarKeyScalar8RouteMutationHint hint)
            ? hint
            : default;
    }

    /// <summary>
    /// Decides whether a `VS8` insert should collect common-prefix mutation evidence while rewriting a reached shelf.<br/>
    /// Default intent keeps the existing sparse sampling cadence; clustered intent samples every warmed shelf mutation so multi-byte router opportunities emerge quickly for hierarchical or repeated-token keys.<br/>
    /// </summary>
    /// <param name="shelfBytes">The reached shelf bytes before the incoming tuple is applied.</param>
    /// <returns>`true` when the insert path should collect mutation-hint evidence for this shelf rewrite.</returns>
    private bool ShouldSampleVarKeyScalar8MutationHint(ReadOnlySpan<byte> shelfBytes)
    {
        int itemCount = VarKeyScalar8Layout.ReadItemCount(shelfBytes);
        if (itemCount < VarKeyScalar8MutationHintWarmupItemCount)
        {
            return false;
        }

        if (currentWriteIntent.Locality == LibraDexWriteLocality.Clustered)
        {
            return true;
        }

        if (currentWriteIntent.Locality == LibraDexWriteLocality.Broad)
        {
            return (itemCount & VarKeyScalar8MutationHintSparseSampleMask) == 0;
        }

        if (currentWriteIntent.Order == LibraDexWriteOrder.Sorted &&
            currentWriteIntent.Priority != LibraDexWritePriority.Compactness)
        {
            return false;
        }

        if (currentWriteIntent.Priority == LibraDexWritePriority.WriteSpeed)
        {
            return (itemCount & VarKeyScalar8MutationHintSparseSampleMask) == 0;
        }

        return (itemCount & VarKeyScalar8MutationHintSampleMask) == 0;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split.<br/>
    /// The search starts at the router depth replacing the full shelf and advances until it finds a prefix transition near the median.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (keyOffsets.Length < 2 || keyOffsets.Length != keyLengths.Length)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two complete key descriptors.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(existingShelf.Bytes, keyOffsets, keyLengths, incomingKey, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    /// <summary>
    /// Chooses the right-side prefix byte for a `VS8` transform split from predecoded key-location arrays.<br/>
    /// This avoids repeated varint length decoding while preserving raw byte comparison semantics over the existing shelf image.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to evaluate.</param>
    /// <param name="hintRightPrefixByte">The incoming prefix byte at the initial child-router depth.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte.</param>
    /// <returns>`true` when the source range can be divided at <paramref name="keyDepth"/>.</returns>
    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = keyOffsets.Length / 2;
        for (int i = desiredRightStart; i < keyOffsets.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[0], keyLengths[0], incomingKey, keyDepth);
        byte lastPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[^1], keyLengths[^1], incomingKey, keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split from source slots.<br/>
    /// This overload is retained for experiments that have a source-slot map but have not predecoded key payload locations.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> sourceSlots,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sourceSlots.Length < 2)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(existingShelf, sourceSlots, incomingKey, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    /// <summary>
    /// Chooses the right-side prefix byte for a `VS8` transform split from source slots instead of cloned key arrays.<br/>
    /// The search prefers a transition near the median and falls back to the incoming-prefix hint when it still divides the observed source range.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to evaluate.</param>
    /// <param name="hintRightPrefixByte">The incoming prefix byte at the initial child-router depth.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte.</param>
    /// <returns>`true` when the source range can be divided at <paramref name="keyDepth"/>.</returns>
    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> sourceSlots,
        ReadOnlySpan<byte> incomingKey,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sourceSlots.Length / 2;
        for (int i = desiredRightStart; i < sourceSlots.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i - 1], incomingKey), keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i], incomingKey), keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i - 1], incomingKey), keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i], incomingKey), keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[0], incomingKey), keyDepth);
        byte lastPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[^1], incomingKey), keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split from cloned key arrays.<br/>
    /// This overload is retained for older callers and shape bring-up tests that still construct a sorted raw-key array before splitting.<br/>
    /// </summary>
    /// <param name="sortedKeys">The complete sorted raw-key set for the full shelf plus incoming tuple.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sortedKeys.Length < 2)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(sortedKeys, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeys.Length / 2;
        for (int i = desiredRightStart; i < sortedKeys.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8Prefix(sortedKeys[0], keyDepth);
        byte lastPrefix = GetVarKeyScalar8Prefix(sortedKeys[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    private static int CompareVarKeyScalar8Tuple(ReadOnlySpan<byte> leftKey, ulong leftIdentity, ReadOnlySpan<byte> rightKey, ulong rightIdentity)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        return leftIdentity > rightIdentity ? 1 : 0;
    }

    private VarKeyScalar8RoutedInsertResult InsertOrConvertVarKeyScalar8DuplicateRun(
        long headShelfOffset,
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        long routeWalkTicks,
        long shelfReadTicks,
        long mutationTicks,
        long structuralStart,
        ushort routerDepth)
    {
        if (!allowDuplicateKeys || existingShelf.ItemCount == 0)
        {
            long elapsed = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar8RoutedInsertResult(
                allowDuplicateKeys ? VarKeyScalar8RoutedInsertKind.Full : VarKeyScalar8RoutedInsertKind.KeyConflict,
                allowDuplicateKeys ? VarKeyScalar8InsertResult.Full : VarKeyScalar8InsertResult.KeyConflict,
                headShelfOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, elapsed),
                existingShelf.ItemCount,
                existingShelf.Profile.ShelfExtentSize,
                routerDepth);
        }

        ReadOnlySpan<byte> runKey = existingShelf.ReadKeyAt(0);
        if (!runKey.SequenceEqual(key) || !existingShelf.ReadKeyAt(existingShelf.ItemCount - 1).SequenceEqual(key))
        {
            throw new InvalidDataException("The VS8 duplicate-run conversion requires one exhausted raw key.");
        }

        List<ulong> identities = new(existingShelf.ItemCount + 1);
        for (int i = 0; i < existingShelf.ItemCount; i++)
        {
            identities.Add(existingShelf.ReadIdentityAt(i));
        }

        int insertIndex = identities.BinarySearch(encodedIdentity);
        if (insertIndex >= 0)
        {
            long elapsed = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                VarKeyScalar8InsertResult.AlreadyPresent,
                headShelfOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, elapsed),
                existingShelf.ItemCount,
                existingShelf.Profile.ShelfExtentSize,
                routerDepth);
        }

        identities.Insert(~insertIndex, encodedIdentity);
        DataKernelCommitTelemetry telemetry = RewriteTerminalIdentity8Route(
            headShelfOffset,
            TerminalIdentityRootLayout.ShapeVarKey,
            key,
            existingShelf.Profile.ShelfExtentSize,
            identities,
            obsoleteFirstShelfOffset: 0);
        long structuralTicks = Stopwatch.GetTimestamp() - structuralStart;
        return new VarKeyScalar8RoutedInsertResult(
            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
            VarKeyScalar8InsertResult.Inserted,
            headShelfOffset,
            headShelfOffset,
            telemetry,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, structuralTicks),
            identities.Count,
            existingShelf.Profile.ShelfExtentSize,
            routerDepth);
    }

    private VarKeyScalar8RoutedInsertResult InsertIntoVarKeyScalar8TerminalIdentityRoute(
        long rootOffset,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        long routeWalkTicks,
        long shelfReadTicks,
        ushort routerDepth)
    {
        if (TryAppendTerminalIdentity8Tail(rootOffset, key, profile.ShelfExtentSize, encodedIdentity, allowDuplicateKeys, out DataKernelCommitTelemetry appendTelemetry))
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                VarKeyScalar8InsertResult.Inserted,
                rootOffset,
                rootOffset,
                appendTelemetry,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                0,
                profile.ShelfExtentSize,
                routerDepth);
        }

        List<ulong> identities = ReadTerminalIdentity8RouteIdentities(rootOffset, key, profile.ShelfExtentSize);
        if (!allowDuplicateKeys && identities.Count != 0)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                VarKeyScalar8InsertResult.KeyConflict,
                rootOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                identities.Count,
                profile.ShelfExtentSize,
                routerDepth);
        }

        int insertIndex = identities.BinarySearch(encodedIdentity);
        if (insertIndex >= 0)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                VarKeyScalar8InsertResult.AlreadyPresent,
                rootOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                identities.Count,
                profile.ShelfExtentSize,
                routerDepth);
        }

        List<ulong> expectedIdentities = new(identities);
        identities.Insert(~insertIndex, encodedIdentity);
        if (!TryRewriteTerminalIdentity8RouteIfCurrent(
            rootOffset,
            TerminalIdentityRootLayout.ShapeVarKey,
            key,
            profile.ShelfExtentSize,
            identities,
            expectedCurrentIdentities: expectedIdentities,
            obsoleteFirstShelfOffset: ReadTerminalIdentityFirstShelfOffset(rootOffset, key),
            out DataKernelCommitTelemetry telemetry))
        {
            return InsertIntoVarKeyScalar8TerminalIdentityRoute(
                rootOffset,
                profile,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                routeWalkTicks,
                shelfReadTicks,
                routerDepth);
        }

        return new VarKeyScalar8RoutedInsertResult(
            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
            VarKeyScalar8InsertResult.Inserted,
            rootOffset,
            rootOffset,
            telemetry,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
            identities.Count,
            profile.ShelfExtentSize,
            routerDepth);
    }

    private VarKeyScalar8RoutedInsertResult InsertIntoVarKeyScalar8DuplicateRun(
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        long routeWalkTicks,
        long shelfReadTicks,
        ushort routerDepth)
    {
        if (TryAppendVarKeyScalar8DuplicateRunTail(
            headShelfOffset,
            maxKeyLength,
            key,
            encodedIdentity,
            allowDuplicateKeys,
            routeWalkTicks,
            shelfReadTicks,
            routerDepth,
            out VarKeyScalar8RoutedInsertResult appendResult))
        {
            return appendResult;
        }

        byte[] headBytes = ReadVarKeyScalar8ShelfBytes(headShelfOffset, maxKeyLength, out VarKeyScalar8Profile profile);
        VarKeyScalar8ReadOnly head = new(headBytes, profile);
        if (!head.IsValid || !head.IsDuplicateRun)
        {
            throw new InvalidDataException("The routed VS8 duplicate-run head shelf is invalid.");
        }

        List<ulong> identities = new();
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = currentOffset == headShelfOffset ? headBytes : ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                throw new InvalidDataException("The VS8 duplicate-run chain contains an invalid shelf.");
            }

            if (!shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The routed VS8 duplicate-run key does not match the incoming key.");
            }

            for (int i = 0; i < shelf.ItemCount; i++)
            {
                identities.Add(shelf.ReadIdentityAt(i));
            }

            currentOffset = shelf.DuplicateRunNextOffset;
        }

        if (!allowDuplicateKeys && identities.Count != 0)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.KeyConflict,
                VarKeyScalar8InsertResult.KeyConflict,
                headShelfOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                identities.Count,
                profile.ShelfExtentSize,
                routerDepth);
        }

        int insertIndex = identities.BinarySearch(encodedIdentity);
        if (insertIndex >= 0)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                VarKeyScalar8InsertResult.AlreadyPresent,
                headShelfOffset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                identities.Count,
                profile.ShelfExtentSize,
                routerDepth);
        }

        long structuralStart = Stopwatch.GetTimestamp();
        List<ulong> expectedIdentities = new(identities);
        identities.Insert(~insertIndex, encodedIdentity);
        if (!TryRewriteVarKeyScalar8DuplicateRunIfCurrent(
            headShelfOffset,
            maxKeyLength,
            profile,
            key,
            expectedIdentities,
            identities,
            out DataKernelCommitTelemetry telemetry))
        {
            return InsertIntoVarKeyScalar8DuplicateRun(
                headShelfOffset,
                maxKeyLength,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                routeWalkTicks,
                shelfReadTicks,
                routerDepth);
        }

        long structuralTicks = Stopwatch.GetTimestamp() - structuralStart;
        return new VarKeyScalar8RoutedInsertResult(
            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
            VarKeyScalar8InsertResult.Inserted,
            headShelfOffset,
            headShelfOffset,
            telemetry,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, structuralTicks),
            identities.Count,
            profile.ShelfExtentSize,
            routerDepth);
    }

    private bool TryAppendVarKeyScalar8DuplicateRunTail(
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        long routeWalkTicks,
        long shelfReadTicks,
        ushort routerDepth,
        out VarKeyScalar8RoutedInsertResult result)
    {
        result = default;
        long currentOffset = headShelfOffset;
        VarKeyScalar8Profile profile = default;
        while (true)
        {
            byte[] shelfBytes = ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun)
            {
                throw new InvalidDataException("The VS8 duplicate-run append path found an invalid shelf.");
            }

            if (!shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The routed VS8 duplicate-run key does not match the incoming key.");
            }

            if (shelf.DuplicateRunNextOffset != 0)
            {
                currentOffset = shelf.DuplicateRunNextOffset;
                continue;
            }

            if (!allowDuplicateKeys && shelf.ItemCount != 0)
            {
                result = new VarKeyScalar8RoutedInsertResult(
                    VarKeyScalar8RoutedInsertKind.KeyConflict,
                    VarKeyScalar8InsertResult.KeyConflict,
                    headShelfOffset,
                    0,
                    default,
                    new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                    shelf.ItemCount,
                    profile.ShelfExtentSize,
                    routerDepth);
                return true;
            }

            if (shelf.ItemCount != 0 && shelf.ReadIdentityAt(shelf.ItemCount - 1) >= encodedIdentity)
            {
                return false;
            }

            int capacity = VarKeyScalar8Layout.GetDuplicateRunCapacity(profile, key.Length);
            long structuralStart = Stopwatch.GetTimestamp();
            if (shelf.ItemCount < capacity)
            {
                lock (writePublicationSync)
                {
                    kernel.EnterExclusiveStoragePublication();
                    try
                    {
                        shelfBytes = ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
                        shelf = new VarKeyScalar8ReadOnly(shelfBytes, profile);
                        if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
                        {
                            throw new InvalidDataException("The VS8 duplicate-run append path found an invalid shelf.");
                        }

                        if (shelf.DuplicateRunNextOffset != 0 ||
                            shelf.ItemCount >= capacity ||
                            (!allowDuplicateKeys && shelf.ItemCount != 0) ||
                            (shelf.ItemCount != 0 && shelf.ReadIdentityAt(shelf.ItemCount - 1) >= encodedIdentity))
                        {
                            return false;
                        }

                        RawDataReservation rewrite = kernel.ReserveAt(currentOffset, profile.ShelfExtentSize);
                        shelfBytes.CopyTo(rewrite.Span);
                        VarKeyScalar8Layout.WriteDuplicateRunIdentity(rewrite.Span, key.Length, shelf.ItemCount, encodedIdentity);
                        VarKeyScalar8Layout.WriteItemCount(rewrite.Span, shelf.ItemCount + 1);
                        varKeyScalar8ReadShelfCache.TryRemove(currentOffset, out _);
                        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
                        long structuralTicks = Stopwatch.GetTimestamp() - structuralStart;
                        result = new VarKeyScalar8RoutedInsertResult(
                            VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                            VarKeyScalar8InsertResult.Inserted,
                            headShelfOffset,
                            currentOffset,
                            telemetry,
                            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, structuralTicks),
                            shelf.ItemCount + 1,
                            profile.ShelfExtentSize,
                            routerDepth);
                        return true;
                    }
                    finally
                    {
                        kernel.ExitExclusiveStoragePublication();
                    }
                }
            }

            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
                    shelfBytes = ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
                    shelf = new VarKeyScalar8ReadOnly(shelfBytes, profile);
                    if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
                    {
                        throw new InvalidDataException("The VS8 duplicate-run append path found an invalid shelf.");
                    }

                    capacity = VarKeyScalar8Layout.GetDuplicateRunCapacity(profile, key.Length);
                    if (shelf.DuplicateRunNextOffset != 0 ||
                        shelf.ItemCount < capacity ||
                        (!allowDuplicateKeys && shelf.ItemCount != 0) ||
                        (shelf.ItemCount != 0 && shelf.ReadIdentityAt(shelf.ItemCount - 1) >= encodedIdentity))
                    {
                        return false;
                    }

                    RawDataReservation append = kernel.Reserve(profile.ShelfExtentSize);
                    ulong[] singleIdentity = [encodedIdentity];
                    WriteVarKeyScalar8DuplicateRunShelf(append.Span, profile, key, singleIdentity, 0, 1, 0);
                    RawDataReservation tailRewrite = kernel.ReserveAt(currentOffset, profile.ShelfExtentSize);
                    shelfBytes.CopyTo(tailRewrite.Span);
                    VarKeyScalar8Layout.WriteDuplicateRunNextOffset(tailRewrite.Span, append.Extent.Offset);
                    varKeyScalar8ReadShelfCache.TryRemove(currentOffset, out _);
                    DataKernelCommitTelemetry appendTelemetry = CommitAndInvalidateRouterReadCache();
                    long appendStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
                    result = new VarKeyScalar8RoutedInsertResult(
                        VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                        VarKeyScalar8InsertResult.Inserted,
                        headShelfOffset,
                        append.Extent.Offset,
                        appendTelemetry,
                        new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, appendStructuralTicks),
                        shelf.ItemCount + 1,
                        profile.ShelfExtentSize,
                        routerDepth);
                    return true;
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }
    }

    private DataKernelCommitTelemetry RewriteVarKeyScalar8DuplicateRun(
        long headShelfOffset,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        IReadOnlyList<ulong> identities)
    {
        int capacity = VarKeyScalar8Layout.GetDuplicateRunCapacity(profile, key.Length);
        if (capacity <= 0)
        {
            throw new InvalidDataException("The VS8 duplicate-run key is too large for the selected shelf profile.");
        }

        if (identities.Count == 0)
        {
            RawDataReservation emptyRewrite = kernel.ReserveAt(headShelfOffset, profile.ShelfExtentSize);
            WriteVarKeyScalar8DuplicateRunShelf(emptyRewrite.Span, profile, key, identities, 0, 0, 0);
            varKeyScalar8ReadShelfCache.TryRemove(headShelfOffset, out _);
            return CommitAndInvalidateRouterReadCache();
        }

        int remaining = identities.Count;
        int identityIndex = 0;
        long currentOffset = headShelfOffset;
        while (remaining > 0)
        {
            int take = Math.Min(capacity, remaining);
            remaining -= take;
            long nextOffset = remaining > 0 ? kernel.Reserve(profile.ShelfExtentSize).Extent.Offset : 0;
            RawDataReservation rewrite = kernel.ReserveAt(currentOffset, profile.ShelfExtentSize);
            WriteVarKeyScalar8DuplicateRunShelf(rewrite.Span, profile, key, identities, identityIndex, take, nextOffset);
            currentOffset = nextOffset;
            identityIndex += take;
        }

        varKeyScalar8ReadShelfCache.TryRemove(headShelfOffset, out _);
        return CommitAndInvalidateRouterReadCache();
    }

    /// <summary>
    /// Rewrites one `VS8` duplicate-run chain only when the currently linked identities still match the caller's captured evidence.<br/>
    /// The caller may pass <see langword="null"/> for <paramref name="expectedIdentities"/> when its replacement list was derived immediately from the current chain and only needs the final publication gate.<br/>
    /// A false return means another writer changed the duplicate-run chain before publication, so the caller should re-read and retry the higher-level mutation decision.<br/>
    /// </summary>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset to rewrite.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="profile">The current duplicate-run shelf profile.<br/></param>
    /// <param name="key">The duplicate-run key bytes.<br/></param>
    /// <param name="expectedIdentities">Optional captured identity evidence that must still match current storage.<br/></param>
    /// <param name="replacementIdentities">The complete replacement identity list to publish.<br/></param>
    /// <param name="telemetry">Receives commit telemetry when publication succeeds.<br/></param>
    /// <returns><see langword="true"/> when the replacement chain was published; otherwise <see langword="false"/>.</returns>
    private bool TryRewriteVarKeyScalar8DuplicateRunIfCurrent(
        long headShelfOffset,
        int maxKeyLength,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        IReadOnlyList<ulong>? expectedIdentities,
        IReadOnlyList<ulong> replacementIdentities,
        out DataKernelCommitTelemetry telemetry)
    {
        telemetry = default;
        lock (writePublicationSync)
        {
            kernel.EnterExclusiveStoragePublication();
            try
            {
                if (expectedIdentities is not null)
                {
                    List<ulong> currentIdentities = ReadVarKeyScalar8DuplicateRunIdentities(headShelfOffset, maxKeyLength, key, out profile);
                    if (!AreSameOrderedIdentities(currentIdentities, expectedIdentities))
                    {
                        return false;
                    }
                }

                telemetry = RewriteVarKeyScalar8DuplicateRun(headShelfOffset, profile, key, replacementIdentities);
                return true;
            }
            finally
            {
                kernel.ExitExclusiveStoragePublication();
            }
        }
    }

    private int DeleteFromVarKeyScalar8DuplicateRun(
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong? encodedIdentity)
    {
        byte[] headBytes = ReadVarKeyScalar8ShelfBytes(headShelfOffset, maxKeyLength, out VarKeyScalar8Profile profile);
        VarKeyScalar8ReadOnly head = new(headBytes, profile);
        if (!head.IsValid || !head.IsDuplicateRun)
        {
            throw new InvalidDataException("The routed VS8 duplicate-run delete target is invalid.");
        }

        if (!head.ReadKeyAt(0).SequenceEqual(key))
        {
            return 0;
        }

        List<ulong> surviving = new();
        int deleted = 0;
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = currentOffset == headShelfOffset ? headBytes : ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The VS8 duplicate-run delete chain contains an invalid shelf.");
            }

            for (int i = 0; i < shelf.ItemCount; i++)
            {
                ulong identity = shelf.ReadIdentityAt(i);
                if (!encodedIdentity.HasValue || identity == encodedIdentity.Value)
                {
                    deleted++;
                    continue;
                }

                surviving.Add(identity);
            }

            currentOffset = shelf.DuplicateRunNextOffset;
        }

        if (deleted != 0)
        {
            if (!TryRewriteVarKeyScalar8DuplicateRunIfCurrent(
                headShelfOffset,
                maxKeyLength,
                profile,
                key,
                expectedIdentities: null,
                replacementIdentities: surviving,
                out _))
            {
                return DeleteFromVarKeyScalar8DuplicateRun(headShelfOffset, maxKeyLength, key, encodedIdentity);
            }
        }

        return deleted;
    }

    /// <summary>
    /// Reads the ordered identity list from one `VS8` duplicate-run chain and validates that every linked shelf belongs to the expected run key.<br/>
    /// This is used as publication evidence for guarded full-chain rewrites; it intentionally performs no mutation and allocates only the identity list being compared.<br/>
    /// </summary>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="key">The expected duplicate-run key bytes.<br/></param>
    /// <param name="profile">Receives the shelf profile decoded from the chain.<br/></param>
    /// <returns>The ordered identity list currently stored in the duplicate-run chain.</returns>
    private List<ulong> ReadVarKeyScalar8DuplicateRunIdentities(
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        out VarKeyScalar8Profile profile)
    {
        List<ulong> identities = new();
        long currentOffset = headShelfOffset;
        profile = default;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = ReadVarKeyScalar8ShelfBytes(currentOffset, maxKeyLength, out profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The VS8 duplicate-run chain contains an invalid shelf.");
            }

            for (int i = 0; i < shelf.ItemCount; i++)
            {
                identities.Add(shelf.ReadIdentityAt(i));
            }

            currentOffset = shelf.DuplicateRunNextOffset;
        }

        return identities;
    }

    /// <summary>
    /// Compares two ordered identity lists without allocating enumerators or intermediate spans.<br/>
    /// The rebuild publication guards use exact ordered equality because terminal and duplicate-run shelves store identities sorted in ascending encoded order.<br/>
    /// </summary>
    /// <param name="left">The first ordered identity list.<br/></param>
    /// <param name="right">The second ordered identity list.<br/></param>
    /// <returns><see langword="true"/> when both lists contain the same identities in the same order.</returns>
    private static bool AreSameOrderedIdentities(IReadOnlyList<ulong> left, IReadOnlyList<ulong> right)
    {
        if (left.Count != right.Count)
        {
            return false;
        }

        for (int i = 0; i < left.Count; i++)
        {
            if (left[i] != right[i])
            {
                return false;
            }
        }

        return true;
    }

    private int DeleteFromVarKeyScalar8TerminalIdentityRoute(
        long rootOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong? encodedIdentity)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
        {
            throw new InvalidDataException("The routed VS8 terminal identity delete target has the wrong shape.");
        }

        int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes);
        _ = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        List<ulong> identities = ReadTerminalIdentity8RouteIdentities(rootOffset, key, shelfExtentSize);
        int deleted = 0;
        if (encodedIdentity.HasValue)
        {
            int index = identities.BinarySearch(encodedIdentity.Value);
            if (index < 0)
            {
                return 0;
            }

            identities.RemoveAt(index);
            deleted = 1;
        }
        else
        {
            deleted = identities.Count;
            identities.Clear();
        }

        if (deleted != 0)
        {
            long obsoleteFirstShelfOffset = ReadTerminalIdentityFirstShelfOffset(rootOffset, key);
            if (!TryRewriteTerminalIdentity8RouteIfCurrent(
                rootOffset,
                TerminalIdentityRootLayout.ShapeVarKey,
                key,
                shelfExtentSize,
                identities,
                expectedCurrentIdentities: null,
                obsoleteFirstShelfOffset,
                out _))
            {
                return DeleteFromVarKeyScalar8TerminalIdentityRoute(rootOffset, maxKeyLength, key, encodedIdentity);
            }
        }

        return deleted;
    }

    private static void WriteVarKeyScalar8DuplicateRunShelf(
        Span<byte> target,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        IReadOnlyList<ulong> identities,
        int startIndex,
        int count,
        long nextOffset)
    {
        target.Clear();
        VarKeyScalar8Layout.WriteMagic(target, VarKeyScalar8Layout.Magic);
        VarKeyScalar8Layout.WriteFormatVersion(target, VarKeyScalar8Layout.FormatVersion);
        VarKeyScalar8Layout.WriteHeaderSize(target, VarKeyScalar8Layout.HeaderSize);
        VarKeyScalar8Layout.WriteFlags(target, VarKeyScalar8Layout.DuplicateRunFlag);
        VarKeyScalar8Layout.WriteItemCount(target, count);
        VarKeyScalar8Layout.WriteShelfExtentSize(target, profile.ShelfExtentSize);
        VarKeyScalar8Layout.WriteDuplicateRunKeyLength(target, key.Length);
        VarKeyScalar8Layout.WriteDuplicateRunNextOffset(target, nextOffset);
        key.CopyTo(target.Slice(VarKeyScalar8Layout.DuplicateRunKeyOffset, key.Length));
        for (int i = 0; i < count; i++)
        {
            VarKeyScalar8Layout.WriteDuplicateRunIdentity(target, key.Length, i, identities[startIndex + i]);
        }
    }

    private static byte[] CreateVarKeyScalar16SplitPrefixStem(ReadOnlySpan<byte> representativeKey, ushort firstKeyDepth, ushort splitKeyDepth)
    {
        int stemLength = splitKeyDepth - firstKeyDepth;
        byte[] stem = new byte[stemLength];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar16Prefix(representativeKey, firstKeyDepth + i);
        }

        return stem;
    }

    private static VarKeyScalar16TransformRouterPlan ChooseVarKeyScalar16TransformRouterPlan(
        ushort childRouterKeyDepth,
        ushort splitKeyDepth,
        ReadOnlySpan<byte> selectedPrefixStem)
    {
        if (splitKeyDepth == childRouterKeyDepth)
        {
            return VarKeyScalar16TransformRouterPlan.ExpandedOneByte;
        }

        return VarKeyScalar16TransformRouterPlan.ExpandedOneByteChain;
    }

    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar16TransformSplitPlan(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sortedKeys.Length < 2)
        {
            throw new InvalidDataException("The VS16 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar16TransformSplitRightPrefix(sortedKeys, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS16 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    private static bool TryChooseVarKeyScalar16TransformSplitRightPrefix(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeys.Length / 2;
        for (int i = desiredRightStart; i < sortedKeys.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar16Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar16Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar16Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar16Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar16Prefix(sortedKeys[0], keyDepth);
        byte lastPrefix = GetVarKeyScalar16Prefix(sortedKeys[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    private static int CompareVarKeyScalar16Tuple(
        ReadOnlySpan<byte> leftKey,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ReadOnlySpan<byte> rightKey,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        return leftIdentityLow > rightIdentityLow ? 1 : 0;
    }

    /// <summary>
    /// Inserts one raw varlen key and encoded 8-byte identity through the routed `VS8` shelf path.<br/>
    /// No-split inserts rewrite the reached shelf extent; when the shelf is full but has a larger growth class, a larger shelf is appended and the parent route is repointed.<br/>
    /// This first routed slice deliberately stops at growth-before-split so varlen persistence, route repointing, and range reads can be measured before deeper split policy is added.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="key">The raw byte key to insert.</param>
    /// <param name="encodedIdentity">The encoded 8-byte identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns>The storage-facing routed insert result.</returns>
    internal VarKeyScalar8RoutedInsertResult InsertWalkedRoutedVarKeyScalar8(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        long phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        long routeWalkStart = Stopwatch.GetTimestamp();
        VarKeyScalar8RoutePathTarget pathTarget;
        lock (routerReadCacheSync)
        {
            pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        }
        long routeWalkTicks = Stopwatch.GetTimestamp() - routeWalkStart;
        RecordVarKeyScalar8PhaseAllocation("route", routeWalkTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == VarKeyScalar8RouteTargetKind.None)
        {
            if (TryInsertVarKeyScalar8DirectColdRoute(
                rootRouterOffset,
                pathTarget.ParentRouterOffset,
                pathTarget.RoutePrefixByte,
                VarKeyScalar8Profile.DefaultInitial,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                out VarKeyScalar8RoutedInsertResult coldRouteResult))
            {
                return coldRouteResult;
            }

            return InsertWalkedRoutedVarKeyScalar8(rootRouterOffset, maxKeyLength, key, encodedIdentity, allowDuplicateKeys, maxRouterHops);
        }

        if (target.Kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            long terminalReadStart = Stopwatch.GetTimestamp();
            byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
            int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes);
            VarKeyScalar8Profile terminalProfile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
            long terminalReadTicks = Stopwatch.GetTimestamp() - terminalReadStart;
            RecordVarKeyScalar8PhaseAllocation("terminal-read", terminalReadTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
            if (TryDeepenMismatchedVarKeyScalar8TerminalIdentityRoute(pathTarget, terminalProfile, key, out _))
            {
                return InsertWalkedRoutedVarKeyScalar8(
                    rootRouterOffset,
                    maxKeyLength,
                    key,
                    encodedIdentity,
                    allowDuplicateKeys,
                    maxRouterHops);
            }

            return InsertIntoVarKeyScalar8TerminalIdentityRoute(
                target.Offset,
                terminalProfile,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                routeWalkTicks,
                terminalReadTicks,
                target.RouterDepth);
        }

        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS8 shelf.");
        }

        phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        long shelfReadStart = Stopwatch.GetTimestamp();
        bool targetIsDuplicateRun = IsVarKeyScalar8DuplicateRunShelf(target.Offset, maxKeyLength);
        long linkedShelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        RecordVarKeyScalar8PhaseAllocation("duplicate-probe", linkedShelfReadTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
        if (targetIsDuplicateRun)
        {
            return InsertIntoVarKeyScalar8DuplicateRun(
                target.Offset,
                maxKeyLength,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                routeWalkTicks,
                linkedShelfReadTicks,
                target.RouterDepth);
        }

        phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        VarKeyScalar8MutableShelf existingShelf = ReadVarKeyScalar8MutableShelf(target.Offset, maxKeyLength);
        VarKeyScalar8Profile profile = existingShelf.Profile;
        long shelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        RecordVarKeyScalar8PhaseAllocation("shelf-read", shelfReadTicks - linkedShelfReadTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
        bool sampleMutationHint = ShouldSampleVarKeyScalar8MutationHint(existingShelf.Bytes);
        phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        long mutationStart = Stopwatch.GetTimestamp();
        VarKeyScalar8InsertResult insertResult = existingShelf.InsertWithMutationHint(
            key,
            encodedIdentity,
            allowDuplicateKeys,
            hintStartDepth: target.RouterDepth,
            maxHintBytes: sampleMutationHint ? VarKeyScalar8MutationHintMaxBytes : 0,
            out VarKeyScalar8MutationHint mutationHint);
        long mutationTicks = Stopwatch.GetTimestamp() - mutationStart;
        RecordVarKeyScalar8PhaseAllocation("mutation", mutationTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
        if (insertResult == VarKeyScalar8InsertResult.Inserted)
        {
            phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
            long stageStart = Stopwatch.GetTimestamp();
            RecordVarKeyScalar8RouteMutationHint(pathTarget.ParentRouterOffset, pathTarget.RouteIndex, mutationHint);
            DataKernelCommitTelemetry telemetry = StageVarKeyScalar8ShelfRewrite(target.Offset, existingShelf);
            long stageTicks = Stopwatch.GetTimestamp() - stageStart;
            RecordVarKeyScalar8PhaseAllocation("stage", stageTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                telemetry,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, stageTicks, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.AlreadyPresent)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.KeyConflict)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        phaseAllocatedStart = StartVarKeyScalar8PhaseAllocatedBytes();
        long structuralStart = Stopwatch.GetTimestamp();
        if (insertResult == VarKeyScalar8InsertResult.Full &&
            VarKeyScalar8.TryGrowAndInsert(existingShelf.Bytes, profile, key, encodedIdentity, allowDuplicateKeys, out VarKeyScalar8Profile grownProfile, out byte[] grownShelf, out VarKeyScalar8InsertResult grownResult))
        {
            if (grownResult != VarKeyScalar8InsertResult.Inserted)
            {
                long grownNoOpStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
                return new VarKeyScalar8RoutedInsertResult(
                    grownResult == VarKeyScalar8InsertResult.KeyConflict ? VarKeyScalar8RoutedInsertKind.KeyConflict : VarKeyScalar8RoutedInsertKind.NoOp,
                    grownResult,
                    target.Offset,
                    0,
                    default,
                    new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, grownNoOpStructuralTicks),
                    existingShelf.ItemCount,
                    profile.ShelfExtentSize,
                    target.RouterDepth);
            }

            varKeyScalar8MutableBatchShelves.Remove(target.Offset);
            if (!TryPublishVarKeyScalar8DirectShelfGrowth(
                rootRouterOffset,
                pathTarget.ParentRouterOffset,
                pathTarget.RouteIndex,
                target.Offset,
                profile,
                grownProfile,
                grownShelf,
                out DataKernelCommitTelemetry telemetry,
                out long grownShelfOffset))
            {
                ReleaseVarKeyScalar8MutableShelf(existingShelf, clearShelfBytes: true);
                return InsertWalkedRoutedVarKeyScalar8(
                    rootRouterOffset,
                    maxKeyLength,
                    key,
                    encodedIdentity,
                    allowDuplicateKeys,
                    maxRouterHops);
            }

            ReleaseVarKeyScalar8MutableShelf(existingShelf, clearShelfBytes: true);
            long growStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            RecordVarKeyScalar8PhaseAllocation("grow", growStructuralTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedGrow,
                grownResult,
                target.Offset,
                grownShelfOffset,
                telemetry,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, growStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.Full)
        {
            if (AllVarKeyScalar8ShelfKeysEqual(existingShelf, key))
            {
                varKeyScalar8MutableBatchShelves.Remove(target.Offset);
                VarKeyScalar8RoutedInsertResult duplicateRunResult = InsertOrConvertVarKeyScalar8DuplicateRun(
                    target.Offset,
                    existingShelf,
                    key,
                    encodedIdentity,
                    allowDuplicateKeys,
                    routeWalkTicks,
                    shelfReadTicks,
                    mutationTicks,
                    structuralStart,
                    target.RouterDepth);
                ReleaseVarKeyScalar8MutableShelf(existingShelf, clearShelfBytes: true);
                RecordVarKeyScalar8PhaseAllocation("duplicate-convert", Stopwatch.GetTimestamp() - structuralStart, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
                return duplicateRunResult;
            }

            Span<byte> parentRouterBytes = stackalloc byte[RouterLayout.Size];
            ReadRouterPageUsingArenaCache(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid ||
                !TryGetVarKeyParentTargetRange(
                    parentReader,
                    pathTarget.RouteIndex,
                    target.Offset,
                    out bool parentHasDirectIndex,
                    out int parentRangeStart,
                    out int parentRangeEnd,
                    out ushort parentFinalKeyDepth))
            {
                varKeyScalar8MutableBatchShelves.Remove(target.Offset);
                ReleaseVarKeyScalar8MutableShelf(existingShelf, clearShelfBytes: true);
                return InsertWalkedRoutedVarKeyScalar8(
                    rootRouterOffset,
                    maxKeyLength,
                    key,
                    encodedIdentity,
                    allowDuplicateKeys,
                    maxRouterHops);
            }

            ushort childRouterKeyDepth = parentRangeStart < parentRangeEnd
                ? parentFinalKeyDepth
                : checked((ushort)(parentFinalKeyDepth + 1));
            byte rightPrefixByte = GetVarKeyScalar8Prefix(key, childRouterKeyDepth);
            VarKeyScalar8RouteMutationHint routeMutationHint = GetVarKeyScalar8RouteMutationHint(pathTarget.ParentRouterOffset, pathTarget.RouteIndex);
            varKeyScalar8MutableBatchShelves.Remove(target.Offset);
            long childRouterOffset;
            long leftShelfOffset;
            long rightShelfOffset;
            VarKeyScalar8InsertResult transformResult;
            bool transformPublished;
            DataKernelCommitTelemetry transformCommit;
            try
            {
                (
                    childRouterOffset,
                    leftShelfOffset,
                    rightShelfOffset,
                    _,
                    _,
                    transformResult,
                    transformPublished,
                    transformCommit) = SplitRoutedVarKeyScalar8ByShelfTransform(
                    rootRouterOffset,
                    pathTarget.ParentRouterOffset,
                    pathTarget.RouteIndex,
                    target.Offset,
                    parentHasDirectIndex,
                    parentRangeStart,
                    parentRangeEnd,
                    parentFinalKeyDepth,
                    existingShelf,
                    rightPrefixByte,
                    profile,
                    key,
                    encodedIdentity,
                    target.AllocationClassId,
                    childRouterKeyDepth,
                    routeMutationHint);
            }
            catch (InvalidDataException ex) when (ex.Message == "The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.")
            {
                childRouterKeyDepth = 0;
                rightPrefixByte = GetVarKeyScalar8Prefix(key, childRouterKeyDepth);
                (
                    childRouterOffset,
                    leftShelfOffset,
                    rightShelfOffset,
                    _,
                    _,
                    transformResult,
                    transformPublished,
                    transformCommit) = SplitRoutedVarKeyScalar8ByShelfTransform(
                    rootRouterOffset,
                    pathTarget.ParentRouterOffset,
                    pathTarget.RouteIndex,
                    target.Offset,
                    parentHasDirectIndex,
                    parentRangeStart,
                    parentRangeEnd,
                    parentFinalKeyDepth,
                    existingShelf,
                    rightPrefixByte,
                    profile,
                    key,
                    encodedIdentity,
                    target.AllocationClassId,
                    childRouterKeyDepth,
                    default);
            }

            ReleaseVarKeyScalar8MutableShelf(existingShelf, clearShelfBytes: true);
            if (!transformPublished)
            {
                return InsertWalkedRoutedVarKeyScalar8(
                    rootRouterOffset,
                    maxKeyLength,
                    key,
                    encodedIdentity,
                    allowDuplicateKeys,
                    maxRouterHops);
            }

            VarKeyScalar8RoutedInsertKind kind = transformResult == VarKeyScalar8InsertResult.Inserted
                ? VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit
                : VarKeyScalar8RoutedInsertKind.NoOp;
            long transformStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            RecordVarKeyScalar8PhaseAllocation("split", transformStructuralTicks, StartVarKeyScalar8PhaseAllocatedBytes() - phaseAllocatedStart);
            return new VarKeyScalar8RoutedInsertResult(
                kind,
                transformResult,
                childRouterOffset,
                transformResult == VarKeyScalar8InsertResult.Inserted ? rightShelfOffset : leftShelfOffset,
                transformCommit,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, transformStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth,
                childRouterKeyDepth);
        }

        return new VarKeyScalar8RoutedInsertResult(
            insertResult == VarKeyScalar8InsertResult.Invalid ? VarKeyScalar8RoutedInsertKind.Invalid : VarKeyScalar8RoutedInsertKind.Full,
            insertResult,
            target.Offset,
            0,
            default,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
            existingShelf.ItemCount,
            profile.ShelfExtentSize,
            target.RouterDepth);
    }

    /// <summary>
    /// Attempts one routed `VS8` insert through a writer-local ordinary-shelf context without allowing topology changes.<br/>
    /// The method supports warmed ordinary shelves, terminal identity shelves, and duplicate-run shelves where the tuple fits in an existing shelf image; growth, append, rebuild, and split/transform cases throw so callers can use the existing topology path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="key">The raw byte key to insert.<br/></param>
    /// <param name="encodedIdentity">The encoded 8-byte identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns>The storage-facing routed insert result for the writer-local attempt.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when the reached route needs topology work or another unsupported writer-context shape.<br/></exception>
    internal VarKeyScalar8RoutedInsertResult InsertWalkedRoutedVarKeyScalar8NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        long routeWalkStart = Stopwatch.GetTimestamp();
        VarKeyScalar8RoutePathTarget pathTarget;
        lock (routerReadCacheSync)
        {
            pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        }
        long routeWalkTicks = Stopwatch.GetTimestamp() - routeWalkStart;
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, pathTarget);
            byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
            if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
            {
                throw new InvalidDataException("The routed VS8 terminal identity insert root has the wrong shape.");
            }

            int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes);
            long terminalReadTicks = Stopwatch.GetTimestamp() - routeWalkStart - routeWalkTicks;
            if (TryInsertTerminalIdentity8ForWriteContext(
                writeContext,
                target.Offset,
                key,
                shelfExtentSize,
                encodedIdentity,
                allowDuplicateKeys,
                out Scalar8Scalar8RoutedInsertResult terminalResult))
            {
                return new VarKeyScalar8RoutedInsertResult(
                    terminalResult.Kind == Scalar8Scalar8RoutedInsertKind.KeyConflict
                        ? VarKeyScalar8RoutedInsertKind.KeyConflict
                        : terminalResult.Kind == Scalar8Scalar8RoutedInsertKind.NoOp
                            ? VarKeyScalar8RoutedInsertKind.NoOp
                            : VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                    terminalResult.InsertResult == Scalar8Scalar8InsertResult.KeyConflict
                        ? VarKeyScalar8InsertResult.KeyConflict
                        : terminalResult.InsertResult == Scalar8Scalar8InsertResult.AlreadyPresent
                            ? VarKeyScalar8InsertResult.AlreadyPresent
                            : VarKeyScalar8InsertResult.Inserted,
                    target.Offset,
                    terminalResult.LeftShelfOffset,
                    default,
                    new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, terminalReadTicks, 0, 0, 0),
                    0,
                    shelfExtentSize,
                    target.RouterDepth);
            }

            throw new InvalidOperationException("The VS8 writer-context path does not yet support terminal identity append or rebuild.");
        }

        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidOperationException("The VS8 writer-context path supports only ordinary warmed shelf routes.");
        }

        RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, pathTarget);
        long shelfReadStart = Stopwatch.GetTimestamp();
        if (IsVarKeyScalar8DuplicateRunShelf(target.Offset, maxKeyLength))
        {
            if (TryInsertVarKeyScalar8DuplicateRunForWriteContext(
                writeContext,
                target.Offset,
                maxKeyLength,
                key,
                encodedIdentity,
                allowDuplicateKeys,
                routeWalkTicks,
                Stopwatch.GetTimestamp() - shelfReadStart,
                target.RouterDepth,
                out VarKeyScalar8RoutedInsertResult duplicateRunResult))
            {
                return duplicateRunResult;
            }

            throw new InvalidOperationException("The VS8 writer-context path does not yet support duplicate-run append or rebuild.");
        }

        VarKeyScalar8MutableShelf existingShelf = ReadVarKeyScalar8MutableShelfForWriteContext(writeContext, target.Offset, maxKeyLength);
        VarKeyScalar8Profile profile = existingShelf.Profile;
        long shelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        long mutationStart = Stopwatch.GetTimestamp();
        VarKeyScalar8InsertResult insertResult = existingShelf.InsertWithMutationHint(
            key,
            encodedIdentity,
            allowDuplicateKeys,
            hintStartDepth: target.RouterDepth,
            maxHintBytes: 0,
            out _);
        long mutationTicks = Stopwatch.GetTimestamp() - mutationStart;
        if (insertResult == VarKeyScalar8InsertResult.Full)
        {
            throw new InvalidOperationException("The VS8 writer-context path does not yet support shelf growth or split transforms.");
        }

        if (insertResult == VarKeyScalar8InsertResult.Inserted)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        return new VarKeyScalar8RoutedInsertResult(
            insertResult == VarKeyScalar8InsertResult.KeyConflict ? VarKeyScalar8RoutedInsertKind.KeyConflict : VarKeyScalar8RoutedInsertKind.NoOp,
            insertResult,
            target.Offset,
            0,
            default,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
            existingShelf.ItemCount,
            profile.ShelfExtentSize,
            target.RouterDepth);
    }

    /// <summary>
    /// Attempts one `VS8` duplicate-run insert through an isolated writer context when the target identity fits inside an existing duplicate-run shelf.<br/>
    /// This deliberately excludes append, relink, and full-chain rebuild cases so duplicate-run insertion can use writer-local ownership without widening topology mutation semantics.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged duplicate-run shelf bytes until publish or abort.<br/></param>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset reached by the route walker.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="key">The exact raw duplicate-run key bytes.<br/></param>
    /// <param name="encodedIdentity">The encoded identity to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same key.<br/></param>
    /// <param name="routeWalkTicks">The route-walk tick count to preserve in result attribution.<br/></param>
    /// <param name="shelfReadTicks">The duplicate-run probe/read tick count to preserve in result attribution.<br/></param>
    /// <param name="routerDepth">The router depth reported by the route walker.<br/></param>
    /// <param name="result">Receives the routed insert result when this helper handles the insert.<br/></param>
    /// <returns><see langword="true"/> when the insert was handled or rejected as a no-op/key-conflict inside the duplicate-run chain; false when append or rebuild is required.</returns>
    private bool TryInsertVarKeyScalar8DuplicateRunForWriteContext(
        LibraDexWriteContext writeContext,
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        long routeWalkTicks,
        long shelfReadTicks,
        ushort routerDepth,
        out VarKeyScalar8RoutedInsertResult result)
    {
        result = default;
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = ReadVarKeyScalar8RawShelfBytesForWriteContext(writeContext, currentOffset, maxKeyLength, out VarKeyScalar8Profile profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The VS8 writer-context duplicate-run insert target is invalid.");
            }

            int count = shelf.ItemCount;
            if (!allowDuplicateKeys && count != 0)
            {
                result = new VarKeyScalar8RoutedInsertResult(
                    VarKeyScalar8RoutedInsertKind.KeyConflict,
                    VarKeyScalar8InsertResult.KeyConflict,
                    headShelfOffset,
                    0,
                    default,
                    new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                    count,
                    profile.ShelfExtentSize,
                    routerDepth);
                return true;
            }

            int keyLength = VarKeyScalar8Layout.ReadDuplicateRunKeyLength(shelfBytes);
            int insertIndex = 0;
            while (insertIndex < count)
            {
                ulong currentIdentity = VarKeyScalar8Layout.ReadDuplicateRunIdentity(shelfBytes, keyLength, insertIndex);
                if (currentIdentity == encodedIdentity)
                {
                    result = new VarKeyScalar8RoutedInsertResult(
                        VarKeyScalar8RoutedInsertKind.NoOp,
                        VarKeyScalar8InsertResult.AlreadyPresent,
                        headShelfOffset,
                        0,
                        default,
                        new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                        count,
                        profile.ShelfExtentSize,
                        routerDepth);
                    return true;
                }

                if (currentIdentity > encodedIdentity)
                {
                    break;
                }

                insertIndex++;
            }

            long nextOffset = shelf.DuplicateRunNextOffset;
            if (insertIndex == count && count != 0 && nextOffset != 0)
            {
                currentOffset = nextOffset;
                continue;
            }

            int capacity = VarKeyScalar8Layout.GetDuplicateRunCapacity(profile, key.Length);
            if (count >= capacity)
            {
                return false;
            }

            for (int i = count; i > insertIndex; i--)
            {
                VarKeyScalar8Layout.WriteDuplicateRunIdentity(
                    shelfBytes,
                    keyLength,
                    i,
                    VarKeyScalar8Layout.ReadDuplicateRunIdentity(shelfBytes, keyLength, i - 1));
            }

            VarKeyScalar8Layout.WriteDuplicateRunIdentity(shelfBytes, keyLength, insertIndex, encodedIdentity);
            VarKeyScalar8Layout.WriteItemCount(shelfBytes, count + 1);
            StageVarKeyScalar8RawShelfRewriteForWriteContext(writeContext, currentOffset, shelfBytes);
            result = new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                VarKeyScalar8InsertResult.Inserted,
                headShelfOffset,
                currentOffset,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, 0, 0, 0),
                count + 1,
                profile.ShelfExtentSize,
                routerDepth);
            return true;
        }

        return false;
    }

    /// <summary>
    /// Attempts one exact `VS8` tuple delete through a writer-local shelf context without allowing topology repair.<br/>
    /// The method supports warmed ordinary shelves and terminal identity shelves; duplicate-run shelves and future empty-shelf route cleanup stay on the existing durability-batch path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="key">The exact raw key bytes to delete.<br/></param>
    /// <param name="encodedIdentity">The exact encoded identity to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns><see langword="true"/> when one live tuple was marked deleted in the writer-local shelf.</returns>
    /// <exception cref="InvalidOperationException">Thrown when the reached route needs topology work or another unsupported writer-context shape.<br/></exception>
    internal bool DeleteVarKeyScalar8ExactTupleForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        VarKeyScalar8RoutePathTarget pathTarget;
        lock (routerReadCacheSync)
        {
            pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        }

        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, pathTarget);
            byte[] rootBytes = ReadTerminalIdentityRootBytes(target.Offset);
            if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
            {
                throw new InvalidDataException("The routed VS8 terminal identity delete root has the wrong shape.");
            }

            return TryDeleteVarKeyTerminalIdentity8ForWriteContext(
                writeContext,
                target.Offset,
                TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes),
                key,
                encodedIdentity);
        }

        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidOperationException("The VS8 writer-context exact delete path supports only ordinary warmed shelf routes and terminal identity roots.");
        }

        RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, pathTarget);
        if (IsVarKeyScalar8DuplicateRunShelf(target.Offset, maxKeyLength))
        {
            return TryDeleteVarKeyScalar8DuplicateRunForWriteContext(
                writeContext,
                target.Offset,
                maxKeyLength,
                key,
                encodedIdentity);
        }

        VarKeyScalar8MutableShelf shelf = ReadVarKeyScalar8MutableShelfForWriteContext(writeContext, target.Offset, maxKeyLength);
        return shelf.MarkTupleDeleted(key, encodedIdentity);
    }

    /// <summary>
    /// Deletes one identity from an existing `VS8` duplicate-run shelf chain through an isolated writer context.<br/>
    /// This helper rewrites only the duplicate-run shelf that contains the target identity and deliberately leaves empty duplicate-run shelves linked for later maintenance.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged duplicate-run shelf bytes until publish or abort.<br/></param>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset reached by the route walker.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="key">The exact raw key bytes to delete.<br/></param>
    /// <param name="encodedIdentity">The exact encoded identity to remove.<br/></param>
    /// <returns><see langword="true"/> when the identity was found and staged for deletion; otherwise <see langword="false"/>.</returns>
    private bool TryDeleteVarKeyScalar8DuplicateRunForWriteContext(
        LibraDexWriteContext writeContext,
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity)
    {
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = ReadVarKeyScalar8RawShelfBytesForWriteContext(writeContext, currentOffset, maxKeyLength, out VarKeyScalar8Profile profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(key))
            {
                throw new InvalidDataException("The VS8 writer-context duplicate-run delete target is invalid.");
            }

            int keyLength = VarKeyScalar8Layout.ReadDuplicateRunKeyLength(shelfBytes);
            int count = shelf.ItemCount;
            int deleteIndex = -1;
            for (int i = 0; i < count; i++)
            {
                ulong currentIdentity = VarKeyScalar8Layout.ReadDuplicateRunIdentity(shelfBytes, keyLength, i);
                if (currentIdentity == encodedIdentity)
                {
                    deleteIndex = i;
                    break;
                }

                if (currentIdentity > encodedIdentity)
                {
                    return false;
                }
            }

            long nextOffset = shelf.DuplicateRunNextOffset;
            if (deleteIndex >= 0)
            {
                for (int i = deleteIndex + 1; i < count; i++)
                {
                    VarKeyScalar8Layout.WriteDuplicateRunIdentity(
                        shelfBytes,
                        keyLength,
                        i - 1,
                        VarKeyScalar8Layout.ReadDuplicateRunIdentity(shelfBytes, keyLength, i));
                }

                VarKeyScalar8Layout.WriteItemCount(shelfBytes, count - 1);
                StageVarKeyScalar8RawShelfRewriteForWriteContext(writeContext, currentOffset, shelfBytes);
                return true;
            }

            currentOffset = nextOffset;
        }

        return false;
    }

    /// <summary>
    /// Deletes one identity from an existing `VS8` terminal identity route through an isolated writer context.<br/>
    /// This helper is shelf-local: it rewrites only the terminal identity shelf that contains the target identity and deliberately leaves empty terminal shelves or roots for later maintenance.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged terminal shelf bytes until publish or abort.<br/></param>
    /// <param name="rootOffset">The terminal identity root offset reached by the route walker.<br/></param>
    /// <param name="shelfExtentSize">The fixed extent size for every terminal identity shelf under this root.<br/></param>
    /// <param name="key">The encoded `VS8` key expected on the terminal identity root.<br/></param>
    /// <param name="encodedIdentity">The encoded scalar identity to remove.<br/></param>
    /// <returns><see langword="true"/> when the identity was found and staged for deletion; otherwise <see langword="false"/>.</returns>
    /// <exception cref="InvalidDataException">Thrown when the terminal root or shelf chain is structurally invalid.<br/></exception>
    /// <exception cref="LibraDexWriteContextTerminalIdentityShelfOwnershipException">Thrown when another writer context already owns the target terminal identity shelf.<br/></exception>
    private bool TryDeleteVarKeyTerminalIdentity8ForWriteContext(
        LibraDexWriteContext writeContext,
        long rootOffset,
        int shelfExtentSize,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey ||
            !IsTerminalIdentityRootForKey(rootBytes, key, out long shelfOffset))
        {
            throw new InvalidDataException("The routed VS8 terminal identity delete root does not match the encoded key.");
        }

        while (shelfOffset != 0)
        {
            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytesForWriteContext(writeContext, shelfOffset, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
            int deleteIndex = -1;
            for (int i = 0; i < count; i++)
            {
                ulong current = TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i);
                if (current == encodedIdentity)
                {
                    deleteIndex = i;
                    break;
                }

                if (current > encodedIdentity)
                {
                    return false;
                }
            }

            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
            if (deleteIndex >= 0)
            {
                for (int i = deleteIndex + 1; i < count; i++)
                {
                    TerminalIdentity8ShelfLayout.WriteIdentity(shelfBytes, i - 1, TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i));
                }

                TerminalIdentity8ShelfLayout.WriteItemCount(shelfBytes, count - 1);
                StageTerminalIdentity8ShelfRewriteForWriteContext(writeContext, shelfOffset, shelfExtentSize, shelfBytes);
                return true;
            }

            shelfOffset = nextOffset;
        }

        return false;
    }

    /// <summary>
    /// Checks whether every live tuple in a full `VS8` shelf has the same key as the incoming tuple.<br/>
    /// This is a cold structural-insert guard used before transform split so exhausted-key duplicate runs are routed by identity instead of trying to create another key router.<br/>
    /// </summary>
    /// <param name="shelf">The decoded mutable shelf that reached full capacity.</param>
    /// <param name="key">The incoming raw key bytes.</param>
    /// <returns><see langword="true"/> when the shelf is non-empty and every tuple key equals <paramref name="key"/>.</returns>
    private static bool AllVarKeyScalar8ShelfKeysEqual(VarKeyScalar8MutableShelf shelf, ReadOnlySpan<byte> key)
    {
        if (shelf.ItemCount == 0)
        {
            return false;
        }

        for (int i = 0; i < shelf.ItemCount; i++)
        {
            if (!shelf.ReadKeyAt(i).SequenceEqual(key))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Reads encoded identities for an inclusive raw-byte `VS8` key range across root-router prefixes.<br/>
    /// The reader enumerates the requested root-prefix span and recursively descends any transformed child routers created by full-shelf splits.<br/>
    /// Each distinct shelf reached by the route graph is scanned once, preserving the ordered-shelf range-scoop behavior while allowing varlen shelves to split beyond the first key byte.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="lowerKey">The inclusive lower raw key.</param>
    /// <param name="upperKey">The inclusive upper raw key.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching identities.</param>
    /// <returns>The number of identities copied.</returns>
    internal int ReadVarKeyScalar8IdentityRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentities)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The upper VS8 key must be greater than or equal to the lower key.", nameof(upperKey));
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, 0);
        int copied = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long shelfOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (shelfOffset == 0)
            {
                continue;
            }

            copied = CopyVarKeyScalar8RangeFromTarget(
                shelfOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedIdentities,
                copied,
                visitedShelves,
                visitedRouters,
                remainingRouterHops: DefaultVarKeyScalar8MaxRouterHops);
        }

        return copied;
    }

    /// <summary>
    /// Deletes encoded identities for an inclusive raw-byte `VS8` key range across the routed varlen-key tree.<br/>
    /// The traversal mirrors the range reader's target pruning, but shelf mutation uses the mutable sidecar view so active durability batches keep tombstones until commit-time slot normalization.<br/>
    /// Non-batch callers are also supported by normalizing the touched shelf before immediate publication, which preserves durable delete correctness without exposing tombstones in the persisted shelf format.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="lowerKey">The inclusive lower raw key.</param>
    /// <param name="upperKey">The inclusive upper raw key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns>The number of live tuples deleted.</returns>
    internal long DeleteVarKeyScalar8KeyRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, 0);
        long deleted = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long targetOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            deleted += DeleteVarKeyScalar8RangeFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                maxRouterHops);
        }

        return deleted;
    }

    /// <summary>
    /// Deletes one exact raw-key and encoded-identity tuple from a routed `VS8` index.<br/>
    /// The route walk targets the shelf that owns the key bytes, then the mutable shelf sidecar marks only the matching tuple slot.<br/>
    /// Active durability batches retain the tombstone until commit-time normalization; non-batch callers normalize immediately before publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="key">The exact raw key bytes.</param>
    /// <param name="encodedIdentity">The exact encoded identity.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns><see langword="true"/> when a live tuple was deleted.</returns>
    internal bool DeleteVarKeyScalar8ExactTuple(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        VarKeyScalar8RoutePathTarget pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            return DeleteFromVarKeyScalar8TerminalIdentityRoute(target.Offset, maxKeyLength, key, encodedIdentity) == 1;
        }

        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS8 shelf for exact tuple delete.");
        }

        if (IsVarKeyScalar8DuplicateRunShelf(target.Offset, maxKeyLength))
        {
            return DeleteFromVarKeyScalar8DuplicateRun(target.Offset, maxKeyLength, key, encodedIdentity) == 1;
        }

        VarKeyScalar8MutableShelf shelf = ReadVarKeyScalar8MutableShelf(target.Offset, maxKeyLength);
        if (!shelf.MarkTupleDeleted(key, encodedIdentity))
        {
            return false;
        }

        if (!durabilityBatchActive)
        {
            _ = shelf.NormalizeDeletedSlotsForPublication();
        }

        _ = StageVarKeyScalar8ShelfRewrite(target.Offset, shelf);
        return true;
    }

    internal VarKeyScalar16RoutedInsertResult InsertWalkedRoutedVarKeyScalar16(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        long routeWalkStart = Stopwatch.GetTimestamp();
        VarKeyScalar16RoutePathTarget pathTarget = WalkVarKeyScalar16RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        long routeWalkTicks = Stopwatch.GetTimestamp() - routeWalkStart;
        VarKeyScalar16RouteTarget target = pathTarget.Target;
        if (target.Kind == VarKeyScalar16RouteTargetKind.None)
        {
            if (TryInsertVarKeyScalar16DirectColdRoute(
                rootRouterOffset,
                pathTarget.ParentRouterOffset,
                pathTarget.RoutePrefixByte,
                VarKeyScalar16Profile.DefaultInitial,
                key,
                encodedIdentityHigh,
                encodedIdentityLow,
                allowDuplicateKeys,
                out VarKeyScalar16RoutedInsertResult coldResult))
            {
                return coldResult;
            }

            return InsertWalkedRoutedVarKeyScalar16(
                rootRouterOffset,
                maxKeyLength,
                key,
                encodedIdentityHigh,
                encodedIdentityLow,
                allowDuplicateKeys,
                maxRouterHops);
        }

        if (target.Kind != VarKeyScalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS16 shelf.");
        }

        long shelfReadStart = Stopwatch.GetTimestamp();
        VarKeyScalar16MutableShelf existingShelf = ReadVarKeyScalar16MutableShelf(target.Offset, maxKeyLength);
        VarKeyScalar16Profile profile = existingShelf.Profile;
        long shelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        long mutationStart = Stopwatch.GetTimestamp();
        VarKeyScalar16InsertResult insertResult = existingShelf.InsertWithMutationHint(
            key,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys,
            hintStartDepth: target.RouterDepth,
            maxHintBytes: 0,
            out _);
        long mutationTicks = Stopwatch.GetTimestamp() - mutationStart;
        if (insertResult == VarKeyScalar16InsertResult.Inserted)
        {
            long stageStart = Stopwatch.GetTimestamp();
            DataKernelCommitTelemetry telemetry = StageVarKeyScalar16ShelfRewrite(target.Offset, existingShelf);
            long stageTicks = Stopwatch.GetTimestamp() - stageStart;
            return new VarKeyScalar16RoutedInsertResult(
                VarKeyScalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                telemetry,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, stageTicks, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar16InsertResult.AlreadyPresent)
        {
            return new VarKeyScalar16RoutedInsertResult(
                VarKeyScalar16RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar16InsertResult.KeyConflict)
        {
            return new VarKeyScalar16RoutedInsertResult(
                VarKeyScalar16RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        long structuralStart = Stopwatch.GetTimestamp();
        if (insertResult == VarKeyScalar16InsertResult.Full &&
            VarKeyScalar16.TryGrowAndInsert(existingShelf.Bytes, profile, key, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out VarKeyScalar16Profile grownProfile, out byte[] grownShelf, out VarKeyScalar16InsertResult grownResult))
        {
            if (grownResult != VarKeyScalar16InsertResult.Inserted)
            {
                long grownNoOpStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
                return new VarKeyScalar16RoutedInsertResult(
                    grownResult == VarKeyScalar16InsertResult.KeyConflict ? VarKeyScalar16RoutedInsertKind.KeyConflict : VarKeyScalar16RoutedInsertKind.NoOp,
                    grownResult,
                    target.Offset,
                    0,
                    default,
                    new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, grownNoOpStructuralTicks),
                    existingShelf.ItemCount,
                    profile.ShelfExtentSize,
                    target.RouterDepth);
            }

            varKeyScalar16MutableBatchShelves.Remove(target.Offset);
            RawDataReservation grownReservation = kernel.Reserve(grownProfile.ShelfExtentSize);
            grownShelf.CopyTo(grownReservation.Span);
            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid)
            {
                throw new InvalidDataException("The VS16 growth parent router is invalid.");
            }

            RawDataReservation parentRouterRewrite = kernel.ReserveAt(pathTarget.ParentRouterOffset, RouterLayout.Size);
            parentRouterBytes.CopyTo(parentRouterRewrite.Span);
            RouterWriter parentWriter = new(parentRouterRewrite.Span);
            parentWriter.WriteRouteTarget(pathTarget.RouteIndex, grownReservation.Extent.Offset);

            InvalidateRouterReadCacheForRouterRewrite(pathTarget.ParentRouterOffset);
            DataKernelCommitTelemetry telemetry = CommitAndDeferRouterReadCacheInvalidation();
            kernel.ReleaseMemoryExtent(target.Offset, profile.ShelfExtentSize);
            ReleaseVarKeyScalar16MutableShelf(existingShelf, clearShelfBytes: true);
            long growStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar16RoutedInsertResult(
                VarKeyScalar16RoutedInsertKind.WalkedGrow,
                grownResult,
                target.Offset,
                grownReservation.Extent.Offset,
                telemetry,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, growStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar16InsertResult.Full)
        {
            Span<byte> parentRouterBytes = stackalloc byte[RouterLayout.Size];
            ReadRouterPageUsingArenaCache(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid ||
                !TryGetVarKeyParentTargetRange(
                    parentReader,
                    pathTarget.RouteIndex,
                    target.Offset,
                    out bool parentHasDirectIndex,
                    out int parentRangeStart,
                    out int parentRangeEnd,
                    out ushort parentFinalKeyDepth))
            {
                varKeyScalar16MutableBatchShelves.Remove(target.Offset);
                ReleaseVarKeyScalar16MutableShelf(existingShelf, clearShelfBytes: true);
                return InsertWalkedRoutedVarKeyScalar16(
                    rootRouterOffset,
                    maxKeyLength,
                    key,
                    encodedIdentityHigh,
                    encodedIdentityLow,
                    allowDuplicateKeys,
                    maxRouterHops);
            }

            ushort childRouterKeyDepth = parentRangeStart < parentRangeEnd
                ? parentFinalKeyDepth
                : checked((ushort)(parentFinalKeyDepth + 1));
            byte rightPrefixByte = GetVarKeyScalar16Prefix(key, childRouterKeyDepth);
            varKeyScalar16MutableBatchShelves.Remove(target.Offset);
            long childRouterOffset;
            long leftShelfOffset;
            long rightShelfOffset;
            VarKeyScalar16InsertResult transformResult;
            DataKernelCommitTelemetry transformCommit;
            try
            {
                (
                    childRouterOffset,
                    leftShelfOffset,
                    rightShelfOffset,
                    _,
                    _,
                    transformResult,
                    transformCommit) = SplitRoutedVarKeyScalar16ByShelfTransform(
                        pathTarget.ParentRouterOffset,
                        parentHasDirectIndex,
                        parentRangeStart,
                        parentRangeEnd,
                        parentFinalKeyDepth,
                        target.Offset,
                        existingShelf,
                        rightPrefixByte,
                        profile,
                        key,
                        encodedIdentityHigh,
                        encodedIdentityLow,
                        target.AllocationClassId,
                        childRouterKeyDepth);
            }
            catch (InvalidDataException ex) when (ex.Message.StartsWith("The VS16 transform split path requires at least two distinct prefixes in the remaining raw key bytes.", StringComparison.Ordinal))
            {
                childRouterKeyDepth = 0;
                rightPrefixByte = GetVarKeyScalar16Prefix(key, childRouterKeyDepth);
                (
                    childRouterOffset,
                    leftShelfOffset,
                    rightShelfOffset,
                    _,
                    _,
                    transformResult,
                    transformCommit) = SplitRoutedVarKeyScalar16ByShelfTransform(
                        pathTarget.ParentRouterOffset,
                        parentHasDirectIndex,
                        parentRangeStart,
                        parentRangeEnd,
                        parentFinalKeyDepth,
                        target.Offset,
                        existingShelf,
                        rightPrefixByte,
                        profile,
                        key,
                        encodedIdentityHigh,
                        encodedIdentityLow,
                        target.AllocationClassId,
                        childRouterKeyDepth);
            }

            ReleaseVarKeyScalar16MutableShelf(existingShelf, clearShelfBytes: true);

            VarKeyScalar16RoutedInsertKind kind = transformResult == VarKeyScalar16InsertResult.Inserted
                ? VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit
                : VarKeyScalar16RoutedInsertKind.NoOp;
            long transformStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar16RoutedInsertResult(
                kind,
                transformResult,
                childRouterOffset,
                transformResult == VarKeyScalar16InsertResult.Inserted ? rightShelfOffset : leftShelfOffset,
                transformCommit,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, transformStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth,
                childRouterKeyDepth);
        }

        return new VarKeyScalar16RoutedInsertResult(
            insertResult == VarKeyScalar16InsertResult.Invalid ? VarKeyScalar16RoutedInsertKind.Invalid : VarKeyScalar16RoutedInsertKind.Full,
            insertResult,
            target.Offset,
            0,
            default,
            new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
            existingShelf.ItemCount,
            profile.ShelfExtentSize,
            target.RouterDepth);
    }

    /// <summary>
    /// Attempts one routed `VS16` insert through a writer-local ordinary-shelf context without allowing topology changes.<br/>
    /// The method supports warmed ordinary shelves where the tuple fits in the current shelf image; growth and split/transform cases throw so callers can use the existing topology path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="key">The raw byte key to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The high 8 bytes of the encoded sortable 16-byte identity.<br/></param>
    /// <param name="encodedIdentityLow">The low 8 bytes of the encoded sortable 16-byte identity.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns>The storage-facing routed insert result for the writer-local attempt.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when the reached route needs topology work or another unsupported writer-context shape.<br/></exception>
    internal VarKeyScalar16RoutedInsertResult InsertWalkedRoutedVarKeyScalar16NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        long routeWalkStart = Stopwatch.GetTimestamp();
        VarKeyScalar16RoutePathTarget pathTarget;
        lock (routerReadCacheSync)
        {
            pathTarget = WalkVarKeyScalar16RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        }

        long routeWalkTicks = Stopwatch.GetTimestamp() - routeWalkStart;
        VarKeyScalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != VarKeyScalar16RouteTargetKind.Shelf)
        {
            throw new InvalidOperationException("The VS16 writer-context path supports only ordinary warmed shelf routes.");
        }

        long shelfReadStart = Stopwatch.GetTimestamp();
        RecordVarKeyScalar16RouteClaimForWriteContext(writeContext, pathTarget);
        VarKeyScalar16MutableShelf existingShelf = ReadVarKeyScalar16MutableShelfForWriteContext(writeContext, target.Offset, maxKeyLength);
        VarKeyScalar16Profile profile = existingShelf.Profile;
        long shelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        long mutationStart = Stopwatch.GetTimestamp();
        VarKeyScalar16InsertResult insertResult = existingShelf.InsertWithMutationHint(
            key,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys,
            hintStartDepth: target.RouterDepth,
            maxHintBytes: 0,
            out _);
        long mutationTicks = Stopwatch.GetTimestamp() - mutationStart;
        if (insertResult == VarKeyScalar16InsertResult.Full)
        {
            throw new InvalidOperationException("The VS16 writer-context path does not yet support shelf growth or split transforms.");
        }

        if (insertResult == VarKeyScalar16InsertResult.Inserted)
        {
            return new VarKeyScalar16RoutedInsertResult(
                VarKeyScalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                default,
                new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        return new VarKeyScalar16RoutedInsertResult(
            insertResult == VarKeyScalar16InsertResult.KeyConflict ? VarKeyScalar16RoutedInsertKind.KeyConflict : VarKeyScalar16RoutedInsertKind.NoOp,
            insertResult,
            target.Offset,
            0,
            default,
            new VarKeyScalar16WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
            existingShelf.ItemCount,
            profile.ShelfExtentSize,
            target.RouterDepth);
    }

    internal int ReadVarKeyScalar16IdentityRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentityHighs,
        Span<ulong> encodedIdentityLows)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The upper VS16 key must be greater than or equal to the lower key.", nameof(upperKey));
        }

        byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, 0);
        int copied = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long shelfOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (shelfOffset == 0)
            {
                continue;
            }

            copied = CopyVarKeyScalar16RangeFromTarget(
                shelfOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedIdentityHighs,
                encodedIdentityLows,
                copied,
                visitedShelves,
                visitedRouters,
                remainingRouterHops: DefaultVarKeyScalar16MaxRouterHops);
        }

        return copied;
    }

    /// <summary>
    /// Deletes encoded identities for an inclusive raw-byte `VS16` key range across the routed varlen-key tree.<br/>
    /// The traversal mirrors the range reader's target pruning, but shelf mutation uses the mutable sidecar view so active durability batches keep tombstones until commit-time slot normalization.<br/>
    /// Non-batch callers are also supported by normalizing the touched shelf before immediate publication, which preserves durable delete correctness without exposing tombstones in the persisted shelf format.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="lowerKey">The inclusive lower raw key.</param>
    /// <param name="upperKey">The inclusive upper raw key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns>The number of live tuples deleted.</returns>
    internal long DeleteVarKeyScalar16KeyRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxRouterHops = DefaultVarKeyScalar16MaxRouterHops)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, 0);
        long deleted = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long targetOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            deleted += DeleteVarKeyScalar16RangeFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                maxRouterHops);
        }

        return deleted;
    }

    /// <summary>
    /// Deletes one exact raw-key and encoded 16-byte identity tuple from a routed `VS16` index.<br/>
    /// The route walk targets the shelf that owns the key bytes, then the mutable shelf sidecar marks only the matching tuple slot.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="key">The exact raw key bytes.</param>
    /// <param name="encodedIdentityHigh">The high 8 bytes of the exact encoded identity.</param>
    /// <param name="encodedIdentityLow">The low 8 bytes of the exact encoded identity.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns><see langword="true"/> when a live tuple was deleted.</returns>
    internal bool DeleteVarKeyScalar16ExactTuple(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops = DefaultVarKeyScalar16MaxRouterHops)
    {
        VarKeyScalar16RoutePathTarget pathTarget = WalkVarKeyScalar16RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        VarKeyScalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != VarKeyScalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS16 shelf for exact tuple delete.");
        }

        VarKeyScalar16MutableShelf shelf = ReadVarKeyScalar16MutableShelf(target.Offset, maxKeyLength);
        if (!shelf.MarkTupleDeleted(key, encodedIdentityHigh, encodedIdentityLow))
        {
            return false;
        }

        if (!durabilityBatchActive)
        {
            _ = shelf.NormalizeDeletedSlotsForPublication();
        }

        _ = StageVarKeyScalar16ShelfRewrite(target.Offset, shelf);
        return true;
    }

    /// <summary>
    /// Attempts one exact `VS16` tuple delete through a writer-local shelf context without allowing topology repair.<br/>
    /// The method supports warmed ordinary shelves; cleanup and future topology-changing delete paths stay on the existing durability-batch path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="key">The exact raw key bytes to delete.<br/></param>
    /// <param name="encodedIdentityHigh">The high 8 bytes of the exact encoded identity to delete.<br/></param>
    /// <param name="encodedIdentityLow">The low 8 bytes of the exact encoded identity to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns><see langword="true"/> when one live tuple was marked deleted in the writer-local shelf.</returns>
    /// <exception cref="InvalidOperationException">Thrown when the reached route needs topology work or another unsupported writer-context shape.<br/></exception>
    internal bool DeleteVarKeyScalar16ExactTupleForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops = DefaultVarKeyScalar16MaxRouterHops)
    {
        VarKeyScalar16RoutePathTarget pathTarget;
        lock (routerReadCacheSync)
        {
            pathTarget = WalkVarKeyScalar16RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        }

        VarKeyScalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != VarKeyScalar16RouteTargetKind.Shelf)
        {
            throw new InvalidOperationException("The VS16 writer-context exact delete path supports only ordinary warmed shelf routes.");
        }

        RecordVarKeyScalar16RouteClaimForWriteContext(writeContext, pathTarget);
        VarKeyScalar16MutableShelf shelf = ReadVarKeyScalar16MutableShelfForWriteContext(writeContext, target.Offset, maxKeyLength);
        return shelf.MarkTupleDeleted(key, encodedIdentityHigh, encodedIdentityLow);
    }

    /// <summary>
    /// Deletes an inclusive raw-key `VS16` range through a writer-local ordinary-shelf context without allowing topology repair paths.<br/>
    /// This supports warmed shelf-local range tombstoning; unsupported route shapes throw so callers can fall back to the existing durability-batch range delete path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns>The number of live tuples marked deleted in writer-local shelves.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when the range reaches an unsupported writer-context route shape.<br/></exception>
    internal long DeleteVarKeyScalar16KeyRangeForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxRouterHops = DefaultVarKeyScalar16MaxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        lock (routerReadCacheSync)
        {
            byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, 0);
            byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, 0);
            long deleted = 0;
            using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
            using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
            for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
            {
                long targetOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
                if (targetOffset == 0)
                {
                    continue;
                }

                deleted += DeleteVarKeyScalar16RangeFromTargetForWriteContext(
                    writeContext,
                    rootRouterOffset,
                    prefix,
                    targetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    maxRouterHops);
            }

            return deleted;
        }
    }

    /// <summary>
    /// Recursively deletes one `VS16` range target through a writer-local ordinary-shelf context.<br/>
    /// Router targets are traversed, ordinary shelves are tombstoned, and non-router/non-shelf targets are rejected for fallback handling.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="parentRouterOffset">The parent router whose route slot selected <paramref name="targetOffset"/>.<br/></param>
    /// <param name="routeIndex">The parent-router route slot that selected <paramref name="targetOffset"/>.<br/></param>
    /// <param name="targetOffset">The routed target offset to process.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <param name="visitedShelves">The visited shelf set used to avoid repeated mutation of shared targets.<br/></param>
    /// <param name="visitedRouters">The visited router set used to avoid route cycles.<br/></param>
    /// <param name="remainingRouterHops">The remaining router hop budget.<br/></param>
    /// <returns>The number of live tuples marked deleted.<br/></returns>
    private long DeleteVarKeyScalar16RangeFromTargetForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        int routeIndex,
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Shelf)
        {
            RecordVarKeyScalar16RouteClaimForWriteContext(writeContext, parentRouterOffset, routeIndex, targetOffset);
            if (!visitedShelves.Add(targetOffset))
            {
                return 0;
            }

            VarKeyScalar16MutableShelf shelf = ReadVarKeyScalar16MutableShelfForWriteContext(writeContext, targetOffset, maxKeyLength);
            return shelf.MarkKeyRangeDeleted(lowerKey, upperKey);
        }

        if (kind != VarKeyScalar16RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS16 writer-context range delete target is not a shelf or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return 0;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS16 writer-context range delete exceeded the configured router hop count.");
        }

        long deletedFromChildren = 0;
        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS16 writer-context range delete router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int childRouteIndex = 0; childRouteIndex < reader.RouteCount; childRouteIndex++)
            {
                long childTargetOffset = reader.GetRouteTargetAt(childRouteIndex);
                if (childTargetOffset == 0)
                {
                    continue;
                }

                deletedFromChildren += DeleteVarKeyScalar16RangeFromTargetForWriteContext(
                    writeContext,
                    targetOffset,
                    childRouteIndex,
                    childTargetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return deletedFromChildren;
        }

        byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTargetOffset = reader.FindTarget((byte)prefix, out int childRouteIndex);
            if (childTargetOffset == 0)
            {
                continue;
            }

            deletedFromChildren += DeleteVarKeyScalar16RangeFromTargetForWriteContext(
                writeContext,
                targetOffset,
                childRouteIndex,
                childTargetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return deletedFromChildren;
    }

    private int CopyVarKeyScalar8RangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentities,
        int copied,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Shelf)
        {
            if (!visitedShelves.Add(targetOffset))
            {
                return copied;
            }

            byte[] shelfBytes = ReadVarKeyScalar8ShelfBytes(targetOffset, maxKeyLength, out VarKeyScalar8Profile profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid)
            {
                throw new InvalidDataException("The routed VS8 shelf bytes are invalid.");
            }

            copied += shelf.CopyIdentitiesInKeyRange(lowerKey, upperKey, encodedIdentities.Slice(copied));
            if (shelf.IsDuplicateRun && shelf.DuplicateRunNextOffset != 0)
            {
                copied = CopyVarKeyScalar8RangeFromTarget(
                    shelf.DuplicateRunNextOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    encodedIdentities,
                    copied,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return copied;
        }

        if (kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            return CopyVarKeyScalar8TerminalIdentityRangeFromRoot(
                targetOffset,
                lowerKey,
                upperKey,
                encodedIdentities,
                copied,
                visitedShelves);
        }

        if (kind != VarKeyScalar8RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS8 range target is not a shelf, terminal identity root, or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return copied;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS8 range read exceeded the configured router hop count.");
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS8 range router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int childRouteIndex = 0; childRouteIndex < reader.RouteCount; childRouteIndex++)
            {
                long childTargetOffset = reader.GetRouteTargetAt(childRouteIndex);
                if (childTargetOffset == 0)
                {
                    continue;
                }

                copied = CopyVarKeyScalar8RangeFromTarget(
                    childTargetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    encodedIdentities,
                    copied,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return copied;
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTargetOffset = reader.FindTarget((byte)prefix);
            if (childTargetOffset == 0)
            {
                continue;
            }

            copied = CopyVarKeyScalar8RangeFromTarget(
                childTargetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedIdentities,
                copied,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return copied;
    }

    /// <summary>
    /// Copies identities from one routed `VS8` terminal identity root when its exhausted key is inside the requested raw-key range.<br/>
    /// Terminal roots are point leaves: the key is stored once in the root, while identities live in linked terminal identity shelves.<br/>
    /// The caller's visited set is shared with shelf traversal so aliased or cyclic terminal chains cannot copy the same shelf twice.<br/>
    /// </summary>
    /// <param name="rootOffset">The terminal identity root offset selected by the route traversal.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching identities.<br/></param>
    /// <param name="copied">The number of identities already copied into <paramref name="encodedIdentities"/>.<br/></param>
    /// <param name="visitedShelves">The visited offset set shared by the range traversal.<br/></param>
    /// <returns>The updated copied identity count.<br/></returns>
    private int CopyVarKeyScalar8TerminalIdentityRangeFromRoot(
        long rootOffset,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentities,
        int copied,
        RouteVisitedOffsetSet visitedShelves)
    {
        if (!visitedShelves.Add(rootOffset))
        {
            return copied;
        }

        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
        {
            throw new InvalidDataException("The routed VS8 terminal identity root shape is invalid.");
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        ReadOnlySpan<byte> rootKey = rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, keyLength);
        if (rootKey.SequenceCompareTo(lowerKey) < 0 ||
            rootKey.SequenceCompareTo(upperKey) > 0)
        {
            return copied;
        }

        int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes);
        long shelfOffset = TerminalIdentityRootLayout.ReadFirstShelfOffset(rootBytes);
        while (shelfOffset != 0 && copied < encodedIdentities.Length)
        {
            if (!visitedShelves.Add(shelfOffset))
            {
                break;
            }

            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytes(shelfOffset, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
            int copyCount = Math.Min(count, encodedIdentities.Length - copied);
            for (int i = 0; i < copyCount; i++)
            {
                encodedIdentities[copied + i] = TerminalIdentity8ShelfLayout.ReadIdentity(shelfBytes, i);
            }

            copied += copyCount;
            shelfOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
        }

        return copied;
    }

    private long DeleteVarKeyScalar8RangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Shelf)
        {
            if (!visitedShelves.Add(targetOffset))
            {
                return 0;
            }

            byte[] targetBytes = ReadVarKeyScalar8ShelfBytes(targetOffset, maxKeyLength, out VarKeyScalar8Profile targetProfile);
            VarKeyScalar8ReadOnly targetReadOnly = new(targetBytes, targetProfile);
            if (!targetReadOnly.IsValid)
            {
                throw new InvalidDataException("The routed VS8 range delete target shelf is invalid.");
            }

            if (targetReadOnly.IsDuplicateRun)
            {
                ReadOnlySpan<byte> runKey = targetReadOnly.ReadKeyAt(0);
                return runKey.SequenceCompareTo(lowerKey) >= 0 && runKey.SequenceCompareTo(upperKey) <= 0
                    ? DeleteFromVarKeyScalar8DuplicateRun(targetOffset, maxKeyLength, runKey, encodedIdentity: null)
                    : 0;
            }

            VarKeyScalar8MutableShelf shelf = ReadVarKeyScalar8MutableShelf(targetOffset, maxKeyLength);
            int deleted = shelf.MarkKeyRangeDeleted(lowerKey, upperKey);
            if (deleted == 0)
            {
                return 0;
            }

            if (!durabilityBatchActive)
            {
                _ = shelf.NormalizeDeletedSlotsForPublication();
            }

            _ = StageVarKeyScalar8ShelfRewrite(targetOffset, shelf);
            return deleted;
        }

        if (kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            if (!visitedShelves.Add(targetOffset))
            {
                return 0;
            }

            byte[] rootBytes = ReadTerminalIdentityRootBytes(targetOffset);
            if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
            {
                throw new InvalidDataException("The routed VS8 terminal identity range delete target has the wrong shape.");
            }

            int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
            ReadOnlySpan<byte> rootKey = rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, keyLength);
            return rootKey.SequenceCompareTo(lowerKey) >= 0 && rootKey.SequenceCompareTo(upperKey) <= 0
                ? DeleteFromVarKeyScalar8TerminalIdentityRoute(targetOffset, maxKeyLength, rootKey, encodedIdentity: null)
                : 0;
        }

        if (kind != VarKeyScalar8RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS8 delete target is not a shelf, terminal identity root, or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return 0;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS8 range delete exceeded the configured router hop count.");
        }

        long deletedFromChildren = 0;
        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS8 range delete router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int childRouteIndex = 0; childRouteIndex < reader.RouteCount; childRouteIndex++)
            {
                long childTargetOffset = reader.GetRouteTargetAt(childRouteIndex);
                if (childTargetOffset == 0)
                {
                    continue;
                }

                deletedFromChildren += DeleteVarKeyScalar8RangeFromTarget(
                    childTargetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return deletedFromChildren;
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTargetOffset = reader.FindTarget((byte)prefix);
            if (childTargetOffset == 0)
            {
                continue;
            }

            deletedFromChildren += DeleteVarKeyScalar8RangeFromTarget(
                childTargetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return deletedFromChildren;
    }

    /// <summary>
    /// Deletes an inclusive raw-key `VS8` range through a writer-local ordinary-shelf context without allowing terminal, duplicate-run, or topology repair paths.<br/>
    /// This supports warmed shelf-local range tombstoning; unsupported route shapes throw so callers can fall back to the existing durability-batch range delete path.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="rootRouterOffset">The root router offset for the index.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.<br/></param>
    /// <returns>The number of live tuples marked deleted in writer-local shelves.<br/></returns>
    /// <exception cref="InvalidOperationException">Thrown when the range reaches an unsupported writer-context route shape.<br/></exception>
    internal long DeleteVarKeyScalar8KeyRangeForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        lock (routerReadCacheSync)
        {
            byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, 0);
            byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, 0);
            long deleted = 0;
            using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
            using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
            for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
            {
                long targetOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
                if (targetOffset == 0)
                {
                    continue;
                }

                deleted += DeleteVarKeyScalar8RangeFromTargetForWriteContext(
                    writeContext,
                    rootRouterOffset,
                    prefix,
                    targetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    maxRouterHops);
            }

            return deleted;
        }
    }

    /// <summary>
    /// Recursively deletes one `VS8` range target through a writer-local ordinary-shelf context.<br/>
    /// Router targets are traversed, ordinary shelves are tombstoned, and terminal or duplicate-run targets are rejected for fallback handling.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged ordinary shelf mutations.<br/></param>
    /// <param name="targetOffset">The routed target offset to process.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <param name="visitedShelves">The visited shelf set used to avoid repeated mutation of shared targets.<br/></param>
    /// <param name="visitedRouters">The visited router set used to avoid route cycles.<br/></param>
    /// <param name="remainingRouterHops">The remaining router hop budget.<br/></param>
    /// <returns>The number of live tuples marked deleted.<br/></returns>
    private long DeleteVarKeyScalar8RangeFromTargetForWriteContext(
        LibraDexWriteContext writeContext,
        long parentRouterOffset,
        int routeIndex,
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar8RouteTargetKind kind = ClassifyVarKeyScalar8RouteTarget(targetOffset);
        if (kind == VarKeyScalar8RouteTargetKind.Shelf)
        {
            RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, parentRouterOffset, routeIndex, targetOffset);
            if (!visitedShelves.Add(targetOffset))
            {
                return 0;
            }

            if (IsVarKeyScalar8DuplicateRunShelf(targetOffset, maxKeyLength))
            {
                return DeleteVarKeyScalar8DuplicateRunRangeForWriteContext(
                    writeContext,
                    targetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey);
            }

            VarKeyScalar8MutableShelf shelf = ReadVarKeyScalar8MutableShelfForWriteContext(writeContext, targetOffset, maxKeyLength);
            return shelf.MarkKeyRangeDeleted(lowerKey, upperKey);
        }

        if (kind == VarKeyScalar8RouteTargetKind.TerminalIdentityRoot)
        {
            RecordVarKeyScalar8RouteClaimForWriteContext(writeContext, parentRouterOffset, routeIndex, targetOffset);
            return DeleteVarKeyTerminalIdentity8RangeForWriteContext(
                writeContext,
                targetOffset,
                lowerKey,
                upperKey);
        }

        if (kind != VarKeyScalar8RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS8 writer-context range delete target is not a shelf, terminal identity root, or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return 0;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS8 writer-context range delete exceeded the configured router hop count.");
        }

        long deletedFromChildren = 0;
        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS8 writer-context range delete router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int childRouteIndex = 0; childRouteIndex < reader.RouteCount; childRouteIndex++)
            {
                long childTargetOffset = reader.GetRouteTargetAt(childRouteIndex);
                if (childTargetOffset == 0)
                {
                    continue;
                }

                deletedFromChildren += DeleteVarKeyScalar8RangeFromTargetForWriteContext(
                    writeContext,
                    targetOffset,
                    childRouteIndex,
                    childTargetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return deletedFromChildren;
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTargetOffset = reader.FindTarget((byte)prefix, out int childRouteIndex);
            if (childTargetOffset == 0)
            {
                continue;
            }

            deletedFromChildren += DeleteVarKeyScalar8RangeFromTargetForWriteContext(
                writeContext,
                targetOffset,
                childRouteIndex,
                childTargetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return deletedFromChildren;
    }

    /// <summary>
    /// Deletes every identity in a `VS8` duplicate-run chain when its run key is inside the requested range.<br/>
    /// The helper stages each duplicate-run shelf with zero item count and deliberately leaves the linked chain for later maintenance instead of relinking route topology.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged duplicate-run shelf bytes.<br/></param>
    /// <param name="headShelfOffset">The duplicate-run head shelf offset reached by the range traversal.<br/></param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index profile.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <returns>The number of live identities staged for deletion.<br/></returns>
    private long DeleteVarKeyScalar8DuplicateRunRangeForWriteContext(
        LibraDexWriteContext writeContext,
        long headShelfOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        byte[] headBytes = ReadVarKeyScalar8RawShelfBytesForWriteContext(writeContext, headShelfOffset, maxKeyLength, out VarKeyScalar8Profile profile);
        VarKeyScalar8ReadOnly head = new(headBytes, profile);
        if (!head.IsValid || !head.IsDuplicateRun)
        {
            throw new InvalidDataException("The VS8 writer-context duplicate-run range delete target is invalid.");
        }

        byte[] runKeyBytes = head.ReadKeyAt(0).ToArray();
        ReadOnlySpan<byte> runKey = runKeyBytes;
        if (runKey.SequenceCompareTo(lowerKey) < 0 ||
            runKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        long deleted = 0;
        long currentOffset = headShelfOffset;
        while (currentOffset != 0)
        {
            byte[] shelfBytes = currentOffset == headShelfOffset
                ? headBytes
                : ReadVarKeyScalar8RawShelfBytesForWriteContext(writeContext, currentOffset, maxKeyLength, out profile);
            VarKeyScalar8ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid || !shelf.IsDuplicateRun || !shelf.ReadKeyAt(0).SequenceEqual(runKey))
            {
                throw new InvalidDataException("The VS8 writer-context duplicate-run range delete chain is invalid.");
            }

            deleted += shelf.ItemCount;
            long nextOffset = shelf.DuplicateRunNextOffset;
            VarKeyScalar8Layout.WriteItemCount(shelfBytes, 0);
            StageVarKeyScalar8RawShelfRewriteForWriteContext(writeContext, currentOffset, shelfBytes);
            currentOffset = nextOffset;
        }

        return deleted;
    }

    /// <summary>
    /// Deletes every identity in a `VS8` terminal identity route when its terminal key is inside the requested range.<br/>
    /// The helper stages each terminal identity shelf with zero item count and deliberately leaves the root and shelf chain for later maintenance.<br/>
    /// </summary>
    /// <param name="writeContext">The writer context that owns staged terminal shelf bytes.<br/></param>
    /// <param name="rootOffset">The terminal identity root offset reached by the range traversal.<br/></param>
    /// <param name="lowerKey">The inclusive lower raw key.<br/></param>
    /// <param name="upperKey">The inclusive upper raw key.<br/></param>
    /// <returns>The number of live identities staged for deletion.<br/></returns>
    private long DeleteVarKeyTerminalIdentity8RangeForWriteContext(
        LibraDexWriteContext writeContext,
        long rootOffset,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey)
    {
        byte[] rootBytes = ReadTerminalIdentityRootBytes(rootOffset);
        if (TerminalIdentityRootLayout.ReadShape(rootBytes) != TerminalIdentityRootLayout.ShapeVarKey)
        {
            throw new InvalidDataException("The VS8 writer-context terminal range delete root has the wrong shape.");
        }

        int keyLength = TerminalIdentityRootLayout.ReadKeyLength(rootBytes);
        ReadOnlySpan<byte> rootKey = rootBytes.AsSpan(TerminalIdentityRootLayout.KeyBytesOffset, keyLength);
        if (rootKey.SequenceCompareTo(lowerKey) < 0 ||
            rootKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        int shelfExtentSize = TerminalIdentityRootLayout.ReadShelfExtentSize(rootBytes);
        long deleted = 0;
        long shelfOffset = TerminalIdentityRootLayout.ReadFirstShelfOffset(rootBytes);
        while (shelfOffset != 0)
        {
            byte[] shelfBytes = ReadTerminalIdentity8ShelfBytesForWriteContext(writeContext, shelfOffset, shelfExtentSize);
            int count = TerminalIdentity8ShelfLayout.ReadItemCount(shelfBytes);
            deleted += count;
            long nextOffset = TerminalIdentity8ShelfLayout.ReadNextShelfOffset(shelfBytes);
            TerminalIdentity8ShelfLayout.WriteItemCount(shelfBytes, 0);
            StageTerminalIdentity8ShelfRewriteForWriteContext(writeContext, shelfOffset, shelfExtentSize, shelfBytes);
            shelfOffset = nextOffset;
        }

        return deleted;
    }

    private int CopyVarKeyScalar16RangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentityHighs,
        Span<ulong> encodedIdentityLows,
        int copied,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Shelf)
        {
            if (!visitedShelves.Add(targetOffset))
            {
                return copied;
            }

            byte[] shelfBytes = ReadVarKeyScalar16ShelfBytes(targetOffset, maxKeyLength, out VarKeyScalar16Profile profile);
            VarKeyScalar16ReadOnly shelf = new(shelfBytes, profile);
            if (!shelf.IsValid)
            {
                throw new InvalidDataException("The routed VS16 shelf bytes are invalid.");
            }

            return copied + shelf.CopyIdentitiesInKeyRange(lowerKey, upperKey, encodedIdentityHighs.Slice(copied), encodedIdentityLows.Slice(copied));
        }

        if (kind != VarKeyScalar16RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS16 range target is not a shelf or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return copied;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS16 range read exceeded the configured router hop count.");
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS16 range target router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int routeIndex = 0; routeIndex < reader.RouteCount; routeIndex++)
            {
                long routeTarget = reader.GetRouteTargetAt(routeIndex);
                if (routeTarget == 0)
                {
                    continue;
                }

                copied = CopyVarKeyScalar16RangeFromTarget(
                    routeTarget,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    encodedIdentityHighs,
                    encodedIdentityLows,
                    copied,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return copied;
        }

        byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long routeTarget = reader.FindTarget((byte)prefix);
            if (routeTarget == 0)
            {
                continue;
            }

            copied = CopyVarKeyScalar16RangeFromTarget(
                routeTarget,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedIdentityHighs,
                encodedIdentityLows,
                copied,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return copied;
    }

    private long DeleteVarKeyScalar16RangeFromTarget(
        long targetOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        RouteVisitedOffsetSet visitedShelves,
        RouteVisitedOffsetSet visitedRouters,
        int remainingRouterHops)
    {
        VarKeyScalar16RouteTargetKind kind = ClassifyVarKeyScalar16RouteTarget(targetOffset);
        if (kind == VarKeyScalar16RouteTargetKind.Shelf)
        {
            if (!visitedShelves.Add(targetOffset))
            {
                return 0;
            }

            VarKeyScalar16MutableShelf shelf = ReadVarKeyScalar16MutableShelf(targetOffset, maxKeyLength);
            int deleted = shelf.MarkKeyRangeDeleted(lowerKey, upperKey);
            if (deleted == 0)
            {
                return 0;
            }

            if (!durabilityBatchActive)
            {
                _ = shelf.NormalizeDeletedSlotsForPublication();
            }

            _ = StageVarKeyScalar16ShelfRewrite(targetOffset, shelf);
            return deleted;
        }

        if (kind != VarKeyScalar16RouteTargetKind.Router)
        {
            throw new InvalidDataException("The routed VS16 delete target is not a shelf or router.");
        }

        if (!visitedRouters.Add(targetOffset))
        {
            return 0;
        }

        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The routed VS16 range delete exceeded the configured router hop count.");
        }

        long deletedFromChildren = 0;
        byte[] routerBytes = new byte[RouterLayout.Size];
        ReadRouterPageUsingArenaCache(targetOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The routed VS16 range delete router is invalid.");
        }

        if (reader.PrefixByteCount > 1)
        {
            for (int routeIndex = 0; routeIndex < reader.RouteCount; routeIndex++)
            {
                long childTargetOffset = reader.GetRouteTargetAt(routeIndex);
                if (childTargetOffset == 0)
                {
                    continue;
                }

                deletedFromChildren += DeleteVarKeyScalar16RangeFromTarget(
                    childTargetOffset,
                    maxKeyLength,
                    lowerKey,
                    upperKey,
                    visitedShelves,
                    visitedRouters,
                    remainingRouterHops - 1);
            }

            return deletedFromChildren;
        }

        byte lowerPrefix = GetVarKeyScalar16Prefix(lowerKey, reader.KeyDepth);
        byte upperPrefix = GetVarKeyScalar16Prefix(upperKey, reader.KeyDepth);
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long childTargetOffset = reader.FindTarget((byte)prefix);
            if (childTargetOffset == 0)
            {
                continue;
            }

            deletedFromChildren += DeleteVarKeyScalar16RangeFromTarget(
                childTargetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                remainingRouterHops - 1);
        }

        return deletedFromChildren;
    }

    private byte[] ReadVarKeyScalar8ShelfBytes(long shelfOffset, int maxKeyLength, out VarKeyScalar8Profile profile)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            profile = mutableShelf.Profile;
            return mutableShelf.Bytes;
        }

        if (!durabilityBatchActive &&
            varKeyScalar8ReadShelfCache.TryGetValue(shelfOffset, out byte[]? cachedShelfBytes))
        {
            int cachedShelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(cachedShelfBytes);
            profile = VarKeyScalar8Profile.Create(cachedShelfExtentSize, maxKeyLength);
            VarKeyScalar8ReadOnly cachedShelf = new(cachedShelfBytes, profile);
            if (!cachedShelf.IsValid)
            {
                throw new InvalidDataException("The session-local VS8 read shelf cache contained invalid shelf bytes.");
            }

            return cachedShelfBytes;
        }

        byte[] header = new byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS8 shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
        profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        byte[] shelfBytes = new byte[shelfExtentSize];
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes);
        if (!durabilityBatchActive)
        {
            varKeyScalar8ReadShelfCache[shelfOffset] = shelfBytes;
        }

        return shelfBytes;
    }

    /// <summary>
    /// Probes one `VS8` shelf header for duplicate-run format without allocating a full shelf image.<br/>
    /// The ordinary write path calls this before decoding the mutable shelf so common inserts avoid a full temporary shelf read followed by a second mutable read.<br/>
    /// Duplicate-run shelves are handled by their dedicated path, which performs the full validation/read only when the flag is actually present.<br/>
    /// </summary>
    /// <param name="shelfOffset">The routed shelf offset to inspect.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <returns>`true` when the shelf header declares duplicate-run format.</returns>
    private bool IsVarKeyScalar8DuplicateRunShelf(long shelfOffset, int maxKeyLength)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            return VarKeyScalar8Layout.HasDuplicateRunFlag(mutableShelf.Bytes);
        }

        Span<byte> header = stackalloc byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS8 shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
        _ = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        return VarKeyScalar8Layout.HasDuplicateRunFlag(header);
    }

    private byte[] ReadVarKeyScalar16ShelfBytes(long shelfOffset, int maxKeyLength, out VarKeyScalar16Profile profile)
    {
        if (durabilityBatchActive &&
            varKeyScalar16MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar16MutableShelf? mutableShelf))
        {
            profile = mutableShelf.Profile;
            return mutableShelf.Bytes;
        }

        if (!durabilityBatchActive &&
            varKeyScalar16ReadShelfCache.TryGetValue(shelfOffset, out byte[]? cachedShelfBytes))
        {
            int cachedShelfExtentSize = VarKeyScalar16Layout.ReadShelfExtentSize(cachedShelfBytes);
            profile = VarKeyScalar16Profile.Create(cachedShelfExtentSize, maxKeyLength);
            VarKeyScalar16ReadOnly cachedShelf = new(cachedShelfBytes, profile);
            if (!cachedShelf.IsValid)
            {
                throw new InvalidDataException("The session-local VS16 read shelf cache contained invalid shelf bytes.");
            }

            return cachedShelfBytes;
        }

        byte[] header = new byte[VarKeyScalar16Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar16Layout.ReadMagic(header) != VarKeyScalar16Layout.Magic ||
            VarKeyScalar16Layout.ReadFormatVersion(header) != VarKeyScalar16Layout.FormatVersion ||
            VarKeyScalar16Layout.ReadHeaderSize(header) != VarKeyScalar16Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS16 shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar16Layout.ReadShelfExtentSize(header);
        profile = VarKeyScalar16Profile.Create(shelfExtentSize, maxKeyLength);
        byte[] shelfBytes = new byte[shelfExtentSize];
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes);
        if (!durabilityBatchActive)
        {
            varKeyScalar16ReadShelfCache[shelfOffset] = shelfBytes;
        }

        return shelfBytes;
    }

    /// <summary>
    /// Reads one `VS8` shelf as a session-owned mutable view, reusing any dirty batch view already decoded for this shelf offset.<br/>
    /// The mutable view keeps the persisted byte image authoritative while caching decoded slot offsets and prefixes for repeated inserts into the same shelf.<br/>
    /// During a durability batch the view is retained immediately so subsequent mutations avoid repeat shelf validation and slot decoding; non-batch callers receive a temporary view.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset of the shelf to read.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the caller's `VS8` profile family.</param>
    /// <returns>The mutable shelf view for this session operation.</returns>
    /// <exception cref="InvalidDataException">Thrown when the loaded shelf bytes fail `VS8` validation.</exception>
    private VarKeyScalar8MutableShelf ReadVarKeyScalar8MutableShelf(long shelfOffset, int maxKeyLength)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            return mutableShelf;
        }

        byte[] shelfBytes;
        VarKeyScalar8Profile profile;
        bool ownsBytes = false;
        bool rentSidecars = false;
        if (durabilityBatchActive)
        {
            Span<byte> header = stackalloc byte[VarKeyScalar8Layout.HeaderSize];
            kernel.Read(shelfOffset, header);
            if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
                VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
                VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
            {
                throw new InvalidDataException("The routed VS8 shelf header is invalid.");
            }

            int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
            profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
            shelfBytes = RentMutableShelfBytes(shelfExtentSize, out ownsBytes);
            rentSidecars = true;
            kernel.Read(shelfOffset, shelfBytes.AsSpan(0, shelfExtentSize));
        }
        else
        {
            shelfBytes = ReadVarKeyScalar8ShelfBytes(shelfOffset, maxKeyLength, out profile);
        }

        if (!VarKeyScalar8MutableShelf.TryCreate(shelfBytes, profile, ownsBytes, rentSidecars, out VarKeyScalar8MutableShelf shelf))
        {
            if (!ownsBytes)
            {
                ReturnLargeMutableShelfBytes(shelfBytes);
            }

            throw new InvalidDataException("The routed VS8 mutable shelf bytes are invalid.");
        }

        if (durabilityBatchActive)
        {
            varKeyScalar8MutableBatchShelves[shelfOffset] = shelf;
        }

        return shelf;
    }

