    private DataKernelCommitTelemetry StageVarKeyScalar8ShelfRewrite(
        long shelfOffset,
        VarKeyScalar8MutableShelf shelf)
    {
        if (shelf.Bytes.Length < shelf.Profile.ShelfExtentSize)
        {
            throw new ArgumentException("The VS8 shelf rewrite image must match the profiled shelf extent size.", nameof(shelf));
        }

        if (durabilityBatchActive)
        {
            varKeyScalar8MutableBatchShelves[shelfOffset] = shelf;
            return CommitWithoutInvalidatingRouterReadCache();
        }

        PrepareVarKeyScalar8ShelfForPublication(shelf);
        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, shelf.Profile.ShelfExtentSize);
        shelf.Bytes.AsSpan(0, shelf.Profile.ShelfExtentSize).CopyTo(shelfRewrite.Span);
        varKeyScalar8ReadShelfCache.TryRemove(shelfOffset, out _);
        return CommitAndInvalidateRouterReadCache();
    }

    private DataKernelCommitTelemetry StageVarKeyScalar16ShelfRewrite(
        long shelfOffset,
        VarKeyScalar16MutableShelf shelf)
    {
        if (shelf.Bytes.Length < shelf.Profile.ShelfExtentSize)
        {
            throw new ArgumentException("The VS16 shelf rewrite image must match the profiled shelf extent size.", nameof(shelf));
        }

        if (durabilityBatchActive)
        {
            varKeyScalar16MutableBatchShelves[shelfOffset] = shelf;
            return CommitWithoutInvalidatingRouterReadCache();
        }

        PrepareVarKeyScalar16ShelfForPublication(shelf);
        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, shelf.Profile.ShelfExtentSize);
        shelf.Bytes.AsSpan(0, shelf.Profile.ShelfExtentSize).CopyTo(shelfRewrite.Span);
        varKeyScalar16ReadShelfCache.TryRemove(shelfOffset, out _);
        return CommitAndInvalidateRouterReadCache();
    }

    /// <summary>
    /// Prepares a dirty `VS8` mutable shelf for publication by normalizing deleted slots and applying the first conservative payload-repack policy.<br/>
    /// The policy requires both a minimum orphaned payload byte count and a minimum deleted-payload ratio so routine deletes do not rebuild record arenas too eagerly.<br/>
    /// </summary>
    /// <param name="shelf">The dirty `VS8` mutable shelf to prepare.</param>
    private static void PrepareVarKeyScalar8ShelfForPublication(VarKeyScalar8MutableShelf shelf)
    {
        _ = shelf.NormalizeDeletedSlotsForPublication();
        _ = shelf.RepackPayloadIfWorthwhile(VarKeyPayloadRepackMinimumDeletedBytes, VarKeyPayloadRepackMinimumDeletedPercent);
    }

    /// <summary>
    /// Prepares a dirty `VS16` mutable shelf for publication by normalizing deleted slots and applying the first conservative payload-repack policy.<br/>
    /// The policy requires both a minimum orphaned payload byte count and a minimum deleted-payload ratio so routine deletes do not rebuild record arenas too eagerly.<br/>
    /// </summary>
    /// <param name="shelf">The dirty `VS16` mutable shelf to prepare.</param>
    private static void PrepareVarKeyScalar16ShelfForPublication(VarKeyScalar16MutableShelf shelf)
    {
        _ = shelf.NormalizeDeletedSlotsForPublication();
        _ = shelf.RepackPayloadIfWorthwhile(VarKeyPayloadRepackMinimumDeletedBytes, VarKeyPayloadRepackMinimumDeletedPercent);
    }

    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        VarKeyScalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedVarKeyScalar16ByShelfTransform(
            long parentRouterOffset,
            bool parentHasDirectIndex,
            int parentRangeStart,
            int parentRangeEnd,
            ushort parentFinalKeyDepth,
            long childRouterOffset,
            VarKeyScalar16MutableShelf existingShelf,
            byte rightPrefixByte,
            VarKeyScalar16Profile profile,
            ReadOnlySpan<byte> key,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelf.Bytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled VS16 shelf extent size.", nameof(existingShelf));
        }

        if (!TryCreateVarKeyScalar16SplitShelves(
            existingShelf,
            childRouterKeyDepth,
            rightPrefixByte,
            profile,
            key,
            encodedIdentityHigh,
            encodedIdentityLow,
            out ushort splitKeyDepth,
            out byte selectedRightPrefixByte,
            out byte[] selectedPrefixStem,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out int leftItemCount,
            out int rightItemCount,
            out VarKeyScalar16InsertResult insertResult))
        {
            return (childRouterOffset, 0, 0, 0, 0, insertResult, default);
        }

        if (parentHasDirectIndex &&
            parentRangeStart < parentRangeEnd &&
            splitKeyDepth == parentFinalKeyDepth)
        {
            lock (writePublicationSync)
            {
                kernel.EnterExclusiveStoragePublication();
                try
                {
            if (selectedRightPrefixByte <= parentRangeStart || selectedRightPrefixByte > parentRangeEnd)
                throw new InvalidDataException($"The VS16 parent-range split boundary {selectedRightPrefixByte} is outside owning direct route run {parentRangeStart}-{parentRangeEnd} at depth {parentFinalKeyDepth}.");

            RawDataReservation leftRewrite = kernel.ReserveAt(childRouterOffset, profile.ShelfExtentSize);
            leftShelfBytes.CopyTo(leftRewrite.Span);
            RawDataReservation parentRightAppend = kernel.Reserve(profile.ShelfExtentSize);
            rightShelfBytes.CopyTo(parentRightAppend.Span);
            byte[] parentBytes = new byte[RouterLayout.Size];
            kernel.Read(parentRouterOffset, parentBytes);
            RouterReader currentParent = new(parentBytes);
            if (!currentParent.IsValid ||
                !TryGetVarKeyParentTargetRange(
                    currentParent,
                    parentRangeStart,
                    childRouterOffset,
                    out bool currentHasDirectIndex,
                    out int currentRangeStart,
                    out int currentRangeEnd,
                    out ushort currentFinalKeyDepth) ||
                !currentHasDirectIndex ||
                currentRangeStart != parentRangeStart ||
                currentRangeEnd != parentRangeEnd ||
                currentFinalKeyDepth != parentFinalKeyDepth)
            {
                throw new InvalidDataException("The VS16 parent route changed during shared-range transform publication.");
            }

            RawDataReservation parentRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
            parentBytes.CopyTo(parentRewrite.Span);
            RouterWriter parentWriter = new(parentRewrite.Span);
            for (int prefix = parentRangeStart; prefix <= parentRangeEnd; prefix++)
                parentWriter.WriteRouteTarget(prefix, prefix < selectedRightPrefixByte ? childRouterOffset : parentRightAppend.Extent.Offset);

            varKeyScalar16ReadShelfCache.TryRemove(childRouterOffset, out _);
            InvalidateRouterReadCacheForRouterRewrite(parentRouterOffset);
            DataKernelCommitTelemetry parentCommit = CommitAndDeferRouterReadCacheInvalidation();
            return (childRouterOffset, childRouterOffset, parentRightAppend.Extent.Offset, leftItemCount, rightItemCount, insertResult, parentCommit);
                }
                finally
                {
                    kernel.ExitExclusiveStoragePublication();
                }
            }
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        VarKeyScalar16TransformRouterPlan routerPlan = ChooseVarKeyScalar16TransformRouterPlan(childRouterKeyDepth, splitKeyDepth, selectedPrefixStem);
        if (routerPlan.Kind == VarKeyScalar16TransformRouterKind.ExpandedOneByte)
        {
            childWriter.InitializeExpandedOneByte(
                childRouterKeyDepth,
                allocationClassId,
                CreateUniformScalar8Scalar8RouteTargets(0, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        }
        else if (routerPlan.Kind == VarKeyScalar16TransformRouterKind.CompressedMultiByte)
        {
            RouterMultiByteRouteSnapshot[] routes =
            [
                new(routerPlan.PrefixStem, 0, checked((byte)(selectedRightPrefixByte - 1)), leftAppend.Extent.Offset),
                new(routerPlan.PrefixStem, selectedRightPrefixByte, byte.MaxValue, rightAppend.Extent.Offset)
            ];
            childWriter.InitializeCompressedMultiByte(
                routerPlan.PrefixByteCount,
                childRouterKeyDepth,
                maxRouteCount: 2,
                allocationClassId,
                routes);
        }
        else
        {
            int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
            long nextRouterOffset = 0;
            for (int i = appendedRouterCount - 1; i >= 0; i--)
            {
                ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
                long[] targets = routerDepth == splitKeyDepth
                    ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                    : CreateVarKeyScalar8IntermediateSplitRouteTargets(
                        nextRouterOffset,
                        leftAppend.Extent.Offset,
                        rightAppend.Extent.Offset,
                        selectedPrefixStem[routerDepth - childRouterKeyDepth]);
                RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                RouterWriter appendedWriter = new(appendedRouter.Span);
                appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
                nextRouterOffset = appendedRouter.Extent.Offset;
            }

            childWriter.InitializeExpandedOneByte(
                childRouterKeyDepth,
                allocationClassId,
                CreateVarKeyScalar8IntermediateSplitRouteTargets(
                    nextRouterOffset,
                    leftAppend.Extent.Offset,
                    rightAppend.Extent.Offset,
                    selectedPrefixStem[0]));
        }

        int routerArenaLength = profile.ShelfExtentSize;
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: routerArenaLength,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(routerArenaLength / RouterLayout.Size)),
            arenaFlags: routerArenaLength > ushort.MaxValue + 1 ? RouterLayout.ArenaLengthFromPageCountFlag : 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, routerArenaLength);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftItemCount, rightItemCount, insertResult, telemetry);
    }

    private static bool TryCreateVarKeyScalar16SplitShelves(
        VarKeyScalar16MutableShelf existingShelf,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        VarKeyScalar16Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out ushort splitKeyDepth,
        out byte selectedRightPrefixByte,
        out byte[] selectedPrefixStem,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out VarKeyScalar16InsertResult insertResult)
    {
        splitKeyDepth = 0;
        selectedRightPrefixByte = 0;
        selectedPrefixStem = [];
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        int existingCount = existingShelf.ItemCount;
        int totalCount = checked(existingCount + 1);
        int[] rentedKeyOffsets = ArrayPool<int>.Shared.Rent(totalCount);
        int[] rentedKeyLengths = ArrayPool<int>.Shared.Rent(totalCount);
        ulong[] rentedIdentityHighs = ArrayPool<ulong>.Shared.Rent(totalCount);
        ulong[] rentedIdentityLows = ArrayPool<ulong>.Shared.Rent(totalCount);
        try
        {
            Span<int> keyOffsets = rentedKeyOffsets.AsSpan(0, totalCount);
            Span<int> keyLengths = rentedKeyLengths.AsSpan(0, totalCount);
            Span<ulong> identityHighs = rentedIdentityHighs.AsSpan(0, totalCount);
            Span<ulong> identityLows = rentedIdentityLows.AsSpan(0, totalCount);
            bool inserted = false;
            int targetIndex = 0;
            for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
            {
                ReadOnlySpan<byte> currentKey = existingShelf.ReadKeyAt(sourceIndex);
                existingShelf.ReadIdentityAt(sourceIndex, out ulong currentIdentityHigh, out ulong currentIdentityLow);
                if (!inserted && CompareVarKeyScalar16Tuple(currentKey, currentIdentityHigh, currentIdentityLow, key, encodedIdentityHigh, encodedIdentityLow) > 0)
                {
                    keyOffsets[targetIndex] = -1;
                    keyLengths[targetIndex] = key.Length;
                    identityHighs[targetIndex] = encodedIdentityHigh;
                    identityLows[targetIndex] = encodedIdentityLow;
                    targetIndex++;
                    inserted = true;
                }

                if (currentKey.SequenceEqual(key) && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
                {
                    insertResult = VarKeyScalar16InsertResult.AlreadyPresent;
                    return false;
                }

                existingShelf.ReadKeyLocationAt(sourceIndex, out int currentKeyOffset, out int currentKeyLength);
                keyOffsets[targetIndex] = currentKeyOffset;
                keyLengths[targetIndex] = currentKeyLength;
                identityHighs[targetIndex] = currentIdentityHigh;
                identityLows[targetIndex] = currentIdentityLow;
                targetIndex++;
            }

            if (!inserted)
            {
                keyOffsets[targetIndex] = -1;
                keyLengths[targetIndex] = key.Length;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
            }

            if (targetIndex != totalCount)
            {
                throw new InvalidDataException("The VS16 transform split source map did not cover the complete tuple set.");
            }

            (splitKeyDepth, selectedRightPrefixByte) = ChooseVarKeyScalar16TransformSplitPlan(
                existingShelf.Bytes,
                keyOffsets,
                keyLengths,
                key,
                firstKeyDepth,
                hintRightPrefixByte,
                profile.MaxKeyLength);
            selectedPrefixStem = CreateVarKeyScalar16SplitPrefixStem(
                ReadVarKeyScalar16SplitSourceKey(existingShelf.Bytes, keyOffsets[0], keyLengths[0], key),
                firstKeyDepth,
                splitKeyDepth);
            if (!TryBuildVarKeyScalar16SplitShelvesFromSources(
                existingShelf.Bytes,
                keyOffsets,
                keyLengths,
                identityHighs,
                identityLows,
                key,
                splitKeyDepth,
                selectedRightPrefixByte,
                profile,
                out leftShelfBytes,
                out rightShelfBytes,
                out leftItemCount,
                out rightItemCount))
            {
                return false;
            }

            insertResult = VarKeyScalar16InsertResult.Inserted;
            return true;
        }
        finally
        {
            ArrayPool<int>.Shared.Return(rentedKeyOffsets, clearArray: false);
            ArrayPool<int>.Shared.Return(rentedKeyLengths, clearArray: false);
            ArrayPool<ulong>.Shared.Return(rentedIdentityHighs, clearArray: false);
            ArrayPool<ulong>.Shared.Return(rentedIdentityLows, clearArray: false);
        }
    }

    /// <summary>
    /// Builds the two replacement `VS16` shelves directly from predecoded split source descriptors.<br/>
    /// The method keeps raw key bytes in the existing shelf image and writes new disk-shaped shelf images without cloned key arrays or tuple lists.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="identityHighs">The sorted high identity words matching <paramref name="keyOffsets"/>.</param>
    /// <param name="identityLows">The sorted low identity words matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="splitKeyDepth">The raw-key byte depth selected for the split boundary.</param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.</param>
    /// <param name="profile">The `VS16` shelf profile used by both replacement shelves.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples written to the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples written to the right replacement shelf.</param>
    /// <returns>`true` when both replacement shelves were non-empty and fit the current profile.</returns>
    private static bool TryBuildVarKeyScalar16SplitShelvesFromSources(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<ulong> identityHighs,
        ReadOnlySpan<ulong> identityLows,
        ReadOnlySpan<byte> incomingKey,
        ushort splitKeyDepth,
        byte selectedRightPrefixByte,
        VarKeyScalar16Profile profile,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount)
    {
        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        VarKeyScalar16Layout.Initialize(leftShelfBytes, profile);
        VarKeyScalar16Layout.Initialize(rightShelfBytes, profile);

        int leftSlotCursor = VarKeyScalar16Layout.HeaderSize;
        int rightSlotCursor = VarKeyScalar16Layout.HeaderSize;
        int leftRecordCursor = VarKeyScalar16Layout.HeaderSize + VarKeyScalar16Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightRecordCursor = VarKeyScalar16Layout.HeaderSize + VarKeyScalar16Layout.ReadSlotCapacityBytes(rightShelfBytes);
        int leftSlotCapacityBytes = VarKeyScalar16Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightSlotCapacityBytes = VarKeyScalar16Layout.ReadSlotCapacityBytes(rightShelfBytes);
        leftItemCount = 0;
        rightItemCount = 0;

        for (int i = 0; i < keyOffsets.Length; i++)
        {
            ReadOnlySpan<byte> currentKey = ReadVarKeyScalar16SplitSourceKey(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey);
            bool goesRight = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, splitKeyDepth) >= selectedRightPrefixByte;
            byte[] targetBytes = goesRight ? rightShelfBytes : leftShelfBytes;
            int slotCursor = goesRight ? rightSlotCursor : leftSlotCursor;
            int recordCursor = goesRight ? rightRecordCursor : leftRecordCursor;
            int slotCapacityBytes = goesRight ? rightSlotCapacityBytes : leftSlotCapacityBytes;
            if (slotCursor + VarKeyScalar16Layout.SlotSize > VarKeyScalar16Layout.HeaderSize + slotCapacityBytes)
            {
                return false;
            }

            int recordLength = VarKeyScalar16Layout.GetNewRecordLength(currentKey.Length);
            if (recordCursor + recordLength > profile.ShelfExtentSize)
            {
                return false;
            }

            VarKeyScalar16Layout.WriteRecord(targetBytes, recordCursor, currentKey, identityHighs[i], identityLows[i]);
            VarKeyScalar16Layout.WriteSlotRecordOffset(targetBytes, slotCursor, recordCursor);
            VarKeyScalar16Layout.WriteSlotKeyPrefix(targetBytes, slotCursor, VarKeyScalar16Layout.CreateKeyPrefix(currentKey));
            slotCursor += VarKeyScalar16Layout.SlotSize;
            recordCursor += recordLength;
            if (goesRight)
            {
                rightSlotCursor = slotCursor;
                rightRecordCursor = recordCursor;
                rightItemCount++;
            }
            else
            {
                leftSlotCursor = slotCursor;
                leftRecordCursor = recordCursor;
                leftItemCount++;
            }
        }

        if (leftItemCount == 0 || rightItemCount == 0)
        {
            return false;
        }

        VarKeyScalar16Layout.WriteItemCount(leftShelfBytes, leftItemCount);
        VarKeyScalar16Layout.WriteSlotStreamLength(leftShelfBytes, leftSlotCursor - VarKeyScalar16Layout.HeaderSize);
        VarKeyScalar16Layout.WriteRecordArenaEnd(leftShelfBytes, leftRecordCursor);
        VarKeyScalar16Layout.WriteItemCount(rightShelfBytes, rightItemCount);
        VarKeyScalar16Layout.WriteSlotStreamLength(rightShelfBytes, rightSlotCursor - VarKeyScalar16Layout.HeaderSize);
        VarKeyScalar16Layout.WriteRecordArenaEnd(rightShelfBytes, rightRecordCursor);
        return true;
    }

    /// <summary>
    /// Reads a `VS16` key from predecoded split key-location arrays without decoding the shelf record header again.<br/>
    /// A negative key offset represents the incoming tuple; non-negative offsets point at raw key payload bytes in the existing shelf image.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <returns>The key bytes for the mapped source tuple.</returns>
    private static ReadOnlySpan<byte> ReadVarKeyScalar16SplitSourceKey(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey)
    {
        return keyOffset < 0 ? incomingKey : existingShelfBytes.AsSpan(keyOffset, keyLength);
    }

    /// <summary>
    /// Reads one `VS16` split-boundary prefix byte from predecoded key-location arrays without constructing a span.<br/>
    /// This keeps deep shared-prefix split scans cheap for the widened-identity varlen shape.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to read.</param>
    /// <returns>The prefix byte at <paramref name="keyDepth"/>, or zero when the depth is beyond the key length.</returns>
    private static byte GetVarKeyScalar16SplitSourcePrefix(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey,
        int keyDepth)
    {
        if (keyDepth < 0)
        {
            return 0;
        }

        if (keyOffset < 0)
        {
            return keyDepth < incomingKey.Length ? incomingKey[keyDepth] : (byte)0;
        }

        return keyDepth < keyLength ? existingShelfBytes[keyOffset + keyDepth] : (byte)0;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS16` transform split from predecoded key descriptors.<br/>
    /// The search starts at the router depth replacing the full shelf and advances until it finds a prefix transition near the median.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar16TransformSplitPlan(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (keyOffsets.Length < 2 || keyOffsets.Length != keyLengths.Length)
        {
            throw new InvalidDataException("The VS16 transform split boundary requires at least two complete key descriptors.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar16TransformSplitRightPrefix(existingShelfBytes, keyOffsets, keyLengths, incomingKey, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException(
            "The VS16 transform split path requires at least two distinct prefixes in the remaining raw key bytes. " +
            CreateVarKeyScalar16TransformSplitFailureDetail(existingShelfBytes, keyOffsets, keyLengths, incomingKey, firstKeyDepth, maxKeyLength));
    }

    private static string CreateVarKeyScalar16TransformSplitFailureDetail(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        int maxKeyLength)
    {
        ReadOnlySpan<byte> firstKey = ReadVarKeyScalar16SplitSourceKey(existingShelfBytes, keyOffsets[0], keyLengths[0], incomingKey);
        ReadOnlySpan<byte> middleKey = ReadVarKeyScalar16SplitSourceKey(existingShelfBytes, keyOffsets[keyOffsets.Length / 2], keyLengths[keyLengths.Length / 2], incomingKey);
        ReadOnlySpan<byte> lastKey = ReadVarKeyScalar16SplitSourceKey(existingShelfBytes, keyOffsets[^1], keyLengths[^1], incomingKey);
        return string.Concat(
            "firstKeyDepth=", firstKeyDepth.ToString(CultureInfo.InvariantCulture),
            " maxKeyLength=", maxKeyLength.ToString(CultureInfo.InvariantCulture),
            " count=", keyOffsets.Length.ToString(CultureInfo.InvariantCulture),
            " first=", Convert.ToHexString(firstKey),
            " middle=", Convert.ToHexString(middleKey),
            " last=", Convert.ToHexString(lastKey),
            " incoming=", Convert.ToHexString(incomingKey));
    }

    /// <summary>
    /// Chooses the right-side prefix byte for a `VS16` transform split from predecoded key descriptors.<br/>
    /// The search prefers a transition near the median and falls back to the incoming-prefix hint when it still divides the observed source range.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to evaluate.</param>
    /// <param name="hintRightPrefixByte">The incoming prefix byte at the initial child-router depth.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte.</param>
    /// <returns>`true` when the source range can be divided at <paramref name="keyDepth"/>.</returns>
    private static bool TryChooseVarKeyScalar16TransformSplitRightPrefix(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = keyOffsets.Length / 2;
        for (int i = desiredRightStart; i < keyOffsets.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[0], keyLengths[0], incomingKey, keyDepth);
        byte lastPrefix = GetVarKeyScalar16SplitSourcePrefix(existingShelfBytes, keyOffsets[^1], keyLengths[^1], incomingKey, keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Tries to split a full walked `SS8-8` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is a normal split path: the original shelf offset is rewritten for the left side, one right shelf is appended, and the parent router is rewritten to distinguish the two sides.<br/>
    /// It prevents unnecessary child-router transforms and is the required terminal split path once all eight scalar key bytes have been consumed.<br/>
    /// A durability-batch mutable shelf image for <paramref name="fullShelfOffset"/> must be discarded before the offset is reused, otherwise commit-time dirty-shelf flushing can overwrite the split result with the stale full shelf.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to preserve when rewriting the parent router.</param>
    /// <param name="result">The routed insert result when parent-route refinement is possible.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedScalar8Scalar8ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        ushort allocationClassId,
        out Scalar8Scalar8RoutedInsertResult result)
    {
        result = default;
        if (!TryCreateScalar8Scalar8SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetScalar8Scalar8Prefix(encodedKey, parentRouterKeyDepth),
            profile,
            encodedKey,
            encodedIdentity,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out int leftItemCount,
            out int rightItemCount,
            out Scalar8Scalar8InsertResult insertResult))
        {
            return false;
        }

        DiscardScalar8Scalar8MutableBatchShelfBytes(fullShelfOffset);
        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        result = new Scalar8Scalar8RoutedInsertResult(
            Scalar8Scalar8RoutedInsertKind.WalkedParentRouteSplit,
            insertResult,
            parentRouterOffset,
            leftRewrite.Extent.Offset,
            rightAppend.Extent.Offset,
            telemetry);
        _ = allocationClassId;
        _ = leftItemCount;
        _ = rightItemCount;
        return true;
    }

    /// <summary>
    /// Compares two encoded `SS8-8` tuples using key-first and identity-second persisted sort order.<br/>
    /// The inputs are already in canonical sortable scalar form, so this helper avoids per-compare byte-order conversion.<br/>
    /// </summary>
    /// <param name="leftKey">The left encoded scalar key.</param>
    /// <param name="leftIdentity">The left encoded scalar identity.</param>
    /// <param name="rightKey">The right encoded scalar key.</param>
    /// <param name="rightIdentity">The right encoded scalar identity.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when both tuple fields match.</returns>
    private static int CompareScalar8Scalar8Tuple(ulong leftKey, ulong leftIdentity, ulong rightKey, ulong rightIdentity)
    {
        if (leftKey < rightKey)
        {
            return -1;
        }

        if (leftKey > rightKey)
        {
            return 1;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        if (leftIdentity > rightIdentity)
        {
            return 1;
        }

        return 0;
    }

    /// <summary>
    /// Compares two encoded `SS16-8` tuples using the persisted shelf ordering.<br/>
    /// Keys compare by high half, then low half, then identity so this helper can merge an incoming split tuple without constructing a temporary shelf.<br/>
    /// </summary>
    /// <param name="leftKeyHigh">The left encoded high key half.</param>
    /// <param name="leftKeyLow">The left encoded low key half.</param>
    /// <param name="leftIdentity">The left encoded identity.</param>
    /// <param name="rightKeyHigh">The right encoded high key half.</param>
    /// <param name="rightKeyLow">The right encoded low key half.</param>
    /// <param name="rightIdentity">The right encoded identity.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareScalar16Scalar8Tuple(
        ulong leftKeyHigh,
        ulong leftKeyLow,
        ulong leftIdentity,
        ulong rightKeyHigh,
        ulong rightKeyLow,
        ulong rightIdentity)
    {
        if (leftKeyHigh < rightKeyHigh)
        {
            return -1;
        }

        if (leftKeyHigh > rightKeyHigh)
        {
            return 1;
        }

        if (leftKeyLow < rightKeyLow)
        {
            return -1;
        }

        if (leftKeyLow > rightKeyLow)
        {
            return 1;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        if (leftIdentity > rightIdentity)
        {
            return 1;
        }

        return 0;
    }

    /// <summary>
    /// Compares two encoded sixteen-byte scalar keys using persisted high-half then low-half order.<br/>
    /// This is the key-only form used by range validation before the router walk starts.<br/>
    /// </summary>
    /// <param name="leftHigh">The left encoded high key half.</param>
    /// <param name="leftLow">The left encoded low key half.</param>
    /// <param name="rightHigh">The right encoded high key half.</param>
    /// <param name="rightLow">The right encoded low key half.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when both key halves match.</returns>
    private static int CompareScalar16Key(ulong leftHigh, ulong leftLow, ulong rightHigh, ulong rightLow)
    {
        if (leftHigh != rightHigh)
        {
            return leftHigh < rightHigh ? -1 : 1;
        }

        if (leftLow != rightLow)
        {
            return leftLow < rightLow ? -1 : 1;
        }

        return 0;
    }

    /// <summary>
    /// Compares two encoded `FS32-8` tuples using the persisted shelf ordering.<br/>
    /// Keys compare by four fixed key parts, then identity, so this helper can merge an incoming split tuple without constructing a temporary shelf.<br/>
    /// </summary>
    /// <param name="left0">The left encoded key part 0.</param>
    /// <param name="left1">The left encoded key part 1.</param>
    /// <param name="left2">The left encoded key part 2.</param>
    /// <param name="left3">The left encoded key part 3.</param>
    /// <param name="leftIdentity">The left encoded identity.</param>
    /// <param name="right0">The right encoded key part 0.</param>
    /// <param name="right1">The right encoded key part 1.</param>
    /// <param name="right2">The right encoded key part 2.</param>
    /// <param name="right3">The right encoded key part 3.</param>
    /// <param name="rightIdentity">The right encoded identity.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareFixed32Scalar8Tuple(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong leftIdentity,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3,
        ulong rightIdentity)
    {
        if (left0 != right0)
        {
            return left0 < right0 ? -1 : 1;
        }

        if (left1 != right1)
        {
            return left1 < right1 ? -1 : 1;
        }

        if (left2 != right2)
        {
            return left2 < right2 ? -1 : 1;
        }

        if (left3 != right3)
        {
            return left3 < right3 ? -1 : 1;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        if (leftIdentity > rightIdentity)
        {
            return 1;
        }

        return 0;
    }

    private static int CompareFixed32Scalar8Key(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3)
    {
        if (left0 != right0)
        {
            return left0 < right0 ? -1 : 1;
        }

        if (left1 != right1)
        {
            return left1 < right1 ? -1 : 1;
        }

        if (left2 != right2)
        {
            return left2 < right2 ? -1 : 1;
        }

        if (left3 != right3)
        {
            return left3 < right3 ? -1 : 1;
        }

        return 0;
    }

    /// <summary>
    /// Compares two encoded `SS8-16` tuples using the persisted shelf ordering.<br/>
    /// Keys compare first, followed by the high identity half and then the low identity half so split merges preserve exact shelf ordering.<br/>
    /// </summary>
    /// <param name="leftKey">The left encoded key.</param>
    /// <param name="leftIdentityHigh">The left encoded high identity half.</param>
    /// <param name="leftIdentityLow">The left encoded low identity half.</param>
    /// <param name="rightKey">The right encoded key.</param>
    /// <param name="rightIdentityHigh">The right encoded high identity half.</param>
    /// <param name="rightIdentityLow">The right encoded low identity half.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareScalar8Scalar16Tuple(
        ulong leftKey,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ulong rightKey,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        if (leftKey < rightKey)
        {
            return -1;
        }

        if (leftKey > rightKey)
        {
            return 1;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        if (leftIdentityLow > rightIdentityLow)
        {
            return 1;
        }

        return 0;
    }

    /// <summary>
    /// Compares two encoded `SS16-16` tuples using the persisted shelf ordering.<br/>
    /// Keys compare by high half, then low half, followed by identity high half and identity low half so split merges preserve exact shelf ordering.<br/>
    /// </summary>
    /// <param name="leftKeyHigh">The left encoded high key half.</param>
    /// <param name="leftKeyLow">The left encoded low key half.</param>
    /// <param name="leftIdentityHigh">The left encoded high identity half.</param>
    /// <param name="leftIdentityLow">The left encoded low identity half.</param>
    /// <param name="rightKeyHigh">The right encoded high key half.</param>
    /// <param name="rightKeyLow">The right encoded low key half.</param>
    /// <param name="rightIdentityHigh">The right encoded high identity half.</param>
    /// <param name="rightIdentityLow">The right encoded low identity half.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareScalar16Scalar16Tuple(
        ulong leftKeyHigh,
        ulong leftKeyLow,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ulong rightKeyHigh,
        ulong rightKeyLow,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        if (leftKeyHigh < rightKeyHigh)
        {
            return -1;
        }

        if (leftKeyHigh > rightKeyHigh)
        {
            return 1;
        }

        if (leftKeyLow < rightKeyLow)
        {
            return -1;
        }

        if (leftKeyLow > rightKeyLow)
        {
            return 1;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        if (leftIdentityLow > rightIdentityLow)
        {
            return 1;
        }

        return 0;
    }

    /// <summary>
    /// Extracts the root-router prefix byte from an encoded scalar key.<br/>
    /// Unsigned `SS8-8` keys are stored in sortable big-endian order, so the high byte of the encoded integer is the first persisted key byte.<br/>
    /// </summary>
    /// <param name="encodedKey">The encoded scalar key.</param>
    /// <returns>The first persisted key byte used by the root router.</returns>
    private static byte GetScalar8Scalar8RootPrefix(ulong encodedKey)
    {
        return (byte)(encodedKey >> 56);
    }

    /// <summary>
    /// Extracts the root-router prefix byte from an encoded `SS16-8` high key half.<br/>
    /// Widened keys are persisted high half first, so the high byte of the encoded high half is the first routed key byte.<br/>
    /// </summary>
    /// <param name="encodedKeyHigh">The encoded high key half.</param>
    /// <returns>The first persisted widened-key byte used by the root router.</returns>
    private static byte GetScalar16Scalar8RootPrefix(ulong encodedKeyHigh)
    {
        return (byte)(encodedKeyHigh >> 56);
    }

    /// <summary>
    /// Extracts one persisted prefix byte from an encoded `SS16-8` key.<br/>
    /// The widened key is stored in canonical sortable byte order as high half then low half, so depths `0..7` read the high half and depths `8..15` read the low half.<br/>
    /// </summary>
    /// <param name="encodedKeyHigh">The encoded high key half.</param>
    /// <param name="encodedKeyLow">The encoded low key half.</param>
    /// <param name="keyDepth">The zero-based byte depth to extract.</param>
    /// <returns>The persisted key byte at the requested depth.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="keyDepth"/> is outside the 16-byte scalar key.</exception>
    private static byte GetScalar16Scalar8Prefix(ulong encodedKeyHigh, ulong encodedKeyLow, int keyDepth)
    {
        if ((uint)keyDepth >= Scalar16Scalar8Layout.KeySize)
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "SS16-8 scalar keys expose exactly sixteen routing bytes.");
        }

        if (keyDepth < sizeof(ulong))
        {
            return (byte)(encodedKeyHigh >> ((sizeof(ulong) - 1 - keyDepth) * 8));
        }

        int lowDepth = keyDepth - sizeof(ulong);
        return (byte)(encodedKeyLow >> ((sizeof(ulong) - 1 - lowDepth) * 8));
    }

    /// <summary>
    /// Extracts one persisted prefix byte from an encoded `FS32-8` key.<br/>
    /// The fixed key is stored in canonical sortable byte order as four 64-bit parts, so depths `0..31` read those parts from left to right.<br/>
    /// </summary>
    /// <param name="key0">The encoded fixed key part 0.</param>
    /// <param name="key1">The encoded fixed key part 1.</param>
    /// <param name="key2">The encoded fixed key part 2.</param>
    /// <param name="key3">The encoded fixed key part 3.</param>
    /// <param name="keyDepth">The zero-based byte depth to extract.</param>
    /// <returns>The persisted key byte at the requested depth.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="keyDepth"/> is outside the 32-byte fixed key.</exception>
    private static byte GetFixed32Scalar8Prefix(ulong key0, ulong key1, ulong key2, ulong key3, int keyDepth)
    {
        if ((uint)keyDepth >= Fixed32Scalar8Layout.KeySize)
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-8 fixed keys expose exactly thirty-two routing bytes.");
        }

        int partDepth = keyDepth % sizeof(ulong);
        int shift = (sizeof(ulong) - 1 - partDepth) * 8;
        return (keyDepth / sizeof(ulong)) switch
        {
            0 => (byte)(key0 >> shift),
            1 => (byte)(key1 >> shift),
            2 => (byte)(key2 >> shift),
            3 => (byte)(key3 >> shift),
            _ => throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-8 fixed keys expose exactly thirty-two routing bytes.")
        };
    }

    /// <summary>
    /// Finds the nearest earlier root prefix byte that currently routes to the same target as the incoming full shelf.<br/>
    /// Returning <paramref name="rootPrefixByte"/> means no earlier root prefix shares the target, so same-prefix transform is the conservative split path.<br/>
    /// </summary>
    /// <param name="rootReader">The already validated direct-index root router view.</param>
    /// <param name="rootPrefixByte">The incoming key's root prefix byte.</param>
    /// <param name="targetOffset">The full shelf offset reached by the incoming root prefix.</param>
    /// <returns>The nearest earlier prefix with the same target, or <paramref name="rootPrefixByte"/> when none exists.</returns>
    private static byte FindEarlierRootPrefixForSameTarget(RouterReader rootReader, byte rootPrefixByte, long targetOffset)
    {
        for (int i = rootPrefixByte - 1; i >= 0; i--)
        {
            byte candidate = (byte)i;
            if (rootReader.GetDirectTarget(candidate) == targetOffset)
            {
                return candidate;
            }
        }

        return rootPrefixByte;
    }

    /// <summary>
    /// Extracts one persisted prefix byte from an encoded scalar key.<br/>
    /// The encoded key is stored in canonical sortable byte order, so byte depth maps to high-to-low byte positions in the encoded integer.<br/>
    /// </summary>
    /// <param name="encodedKey">The encoded scalar key.</param>
    /// <param name="keyDepth">The zero-based byte depth to extract.</param>
    /// <returns>The persisted key byte at the requested depth.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="keyDepth"/> is outside the 8-byte scalar key.</exception>
    private static byte GetScalar8Scalar8Prefix(ulong encodedKey, int keyDepth)
    {
        if ((uint)keyDepth >= sizeof(ulong))
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "SS8-8 scalar keys expose exactly eight routing bytes.");
        }

        return (byte)(encodedKey >> ((sizeof(ulong) - 1 - keyDepth) * 8));
    }

    /// <summary>
    /// Maps internal `SS8-8` shelf insert outcomes to the encoded wrapper outcome vocabulary.<br/>
    /// Session-owned queued topology helpers need this without routing through the public index wrapper, because they publish under narrower session locks.<br/>
    /// </summary>
    /// <param name="result">The internal shelf insert result to map.<br/></param>
    /// <returns>The encoded operation-facing outcome.<br/></returns>
    /// <exception cref="InvalidDataException">Thrown when a full result escapes split handling or the value is unknown.<br/></exception>
    private static Scalar8Scalar8EncodedInsertOutcome MapScalar8Scalar8InsertOutcome(Scalar8Scalar8InsertResult result)
    {
        return result switch
        {
            Scalar8Scalar8InsertResult.Inserted => Scalar8Scalar8EncodedInsertOutcome.Inserted,
            Scalar8Scalar8InsertResult.AlreadyPresent => Scalar8Scalar8EncodedInsertOutcome.AlreadyPresent,
            Scalar8Scalar8InsertResult.KeyConflict => Scalar8Scalar8EncodedInsertOutcome.KeyConflict,
            Scalar8Scalar8InsertResult.Full => throw new InvalidDataException("The routed SS8-8 insert returned Full after split handling."),
            _ => throw new InvalidDataException($"Unknown SS8-8 insert result {result}.")
        };
    }

    /// <summary>
    /// Commits staged session writes and invalidates any cached router arena bytes.<br/>
    /// Router arena cache entries are read-only projections over persisted bytes, so every session commit is treated as a conservative structural invalidation point.<br/>
    /// </summary>
    /// <returns>Telemetry describing the committed write shape.</returns>
    private DataKernelCommitTelemetry CommitAndInvalidateRouterReadCache()
    {
        if (durabilityBatchActive)
        {
            deferredDurabilityCommitRequests++;
            routerReadCacheInvalidationPending = true;
            ClearRouterReadCaches();
            return default;
        }

        DataKernelCommitTelemetry telemetry = kernel.Commit();
        ClearRouterReadCaches();
        return telemetry;
    }

    /// <summary>
    /// Commits staged session writes while leaving broad router-cache invalidation until the enclosing durability batch publishes.<br/>
    /// Structural mutation callers must invalidate every router page they rewrote before calling this helper, because cached decoded views are otherwise allowed to survive inside the batch.<br/>
    /// This keeps long record-major var-key batches from rebuilding the whole routed path after each split or grow while still forcing a clean cache boundary after the batch is published.<br/>
    /// </summary>
    /// <returns>Telemetry describing the committed write shape.</returns>
    private DataKernelCommitTelemetry CommitAndDeferRouterReadCacheInvalidation()
    {
        if (durabilityBatchActive)
        {
            deferredDurabilityCommitRequests++;
            routerReadCacheInvalidationPending = true;
            return default;
        }

        DataKernelCommitTelemetry telemetry = kernel.Commit();
        ClearRouterReadCaches();
        return telemetry;
    }

    /// <summary>
    /// Commits staged session writes without invalidating session-local router projections.<br/>
    /// Shelf-only batch publication uses this because shelf bytes cannot change router topology, target kind, or promoted child-router RAM offsets.<br/>
    /// </summary>
    /// <returns>Telemetry describing the committed write shape.</returns>
    private DataKernelCommitTelemetry CommitWithoutInvalidatingRouterReadCache()
    {
        if (durabilityBatchActive)
        {
            deferredDurabilityCommitRequests++;
            return default;
        }

        return kernel.Commit();
    }

    /// <summary>
    /// Invalidates session-local router projections for one router page that has been rewritten structurally.<br/>
    /// The promoted router arena and route-target kind caches are cleared because they can contain parent-child accelerator state that is keyed by transient RAM offsets rather than only the rewritten file offset.<br/>
    /// </summary>
    /// <param name="routerOffset">The file offset of the rewritten router page.</param>
    private void InvalidateRouterReadCacheForRouterRewrite(long routerOffset)
    {
        lock (routerReadCacheSync)
        {
            routerReadCacheGeneration++;
            ClearRouterPageReadCache();
            ClearDirectRouterViewCache();
            nonDirectRouterViewOffsets.Clear();
            multiByteRouterViewCache.Clear();
            routerArenaReadCache.Clear();
            fixed32Scalar8BatchRouteHints.Clear();
            fixed32Scalar16BatchRouteHints.Clear();
            promotedRouterArena.Clear();
            ClearRouteTargetKindCaches();
        }
    }

    /// <summary>
    /// Clears target-kind memoization inside cached router views while retaining their decoded target-offset arrays.<br/>
    /// Structural writes can change a target offset from shelf to router without changing the parent route target offset, so cached kind slots must be refreshed independently from cached route slots.<br/>
    /// </summary>
    private void ClearCachedRouteTargetKinds()
    {
        lock (routerReadCacheSync)
        {
            foreach (DirectRouterView view in directRouterViewCache.Values)
            {
                view.ClearTargetKinds();
            }

            foreach (MultiByteRouterView view in multiByteRouterViewCache.Values)
            {
                view.ClearTargetKinds();
            }
        }
    }

    /// <summary>
    /// Clears all cached route-target classifications that depend on mutable route topology.<br/>
    /// These caches are intentionally smaller than decoded router-view caches, so structural callers can clear them without forcing every router page to be decoded again.<br/>
    /// </summary>
    private void ClearRouteTargetKindCaches()
    {
        ClearRouteTargetKindCache(varKeyScalar8RouteTargetKindCache);
        ClearRouteTargetKindCache(varKeyScalar16RouteTargetKindCache);
        ClearRouteTargetKindCache(varKeyVarIdentityRouteTargetKindCache);
        ClearRouteTargetKindCache(scalar16VarIdentityRouteTargetKindCache);
    }

    /// <summary>
    /// Publishes all writes staged while the active durability batch was open.<br/>
    /// This is the explicit durable boundary for batched mutation APIs; it uses the normal DataKernel commit path and resets the session router read cache.<br/>
    /// </summary>
    /// <returns>The commit telemetry, number of lower-level commit requests deferred into this publish, and session-local storage diagnostics.</returns>
    /// <exception cref="InvalidOperationException">Thrown when no durability batch is active.</exception>
    internal (DataKernelCommitTelemetry Commit, long DeferredCommitRequests, LibraDexBatchStorageDiagnostics StorageDiagnostics) CommitDurabilityBatch(LibraDexWriteContext writeContext)
    {
        if (!durabilityBatchActive)
        {
            throw new InvalidOperationException("No LibraDex session durability batch is active.");
        }

        lock (writePublicationSync)
        {
            VerifyActiveWriteContext(writeContext);
            LibraDexBatchStorageDiagnostics storageDiagnostics = CreateBatchStorageDiagnosticsSnapshot(writeContext);
            FlushDirtyScalar8Scalar8MutableBatchShelfBytes();
            FlushDirtyScalar16Scalar8MutableBatchShelfBytes();
            FlushDirtyScalar8Scalar16MutableBatchShelfBytes();
            FlushDirtyScalar16Scalar16MutableBatchShelfBytes();
            FlushDirtyFixed32Scalar8MutableBatchShelfBytes();
            FlushDirtyFixed32Scalar16MutableBatchShelfBytes();
            ValidateFixedNScalar8RouteClaimsForWriteContext(writeContext);
            ValidateFixedNScalar16RouteClaimsForWriteContext(writeContext);
            FlushDirtyFixedNScalar8MutableBatchShelfBytes(writeContext);
            FlushDirtyFixedNScalar16MutableBatchShelfBytes(writeContext);
            FlushDirtyVarKeyScalar8MutableBatchShelves();
            FlushDirtyVarKeyScalar16MutableBatchShelves();
            FlushDirtyVarKeyVarIdentityMutableBatchShelves();
            FlushDirtyScalar8VarIdentityMutableBatchShelves();
            FlushDirtyScalar16VarIdentityMutableBatchShelves();
            FlushDirtyTerminalVarIdentityMutableBatchShelves();
            long deferredRequests = deferredDurabilityCommitRequests;
            DataKernelCommitTelemetry telemetry = kernel.Commit();
            foreach (long shelfOffset in fixed32Scalar8RetainedBatchShelfOffsets)
            {
                fixed32Scalar8ReadCache.Remove(shelfOffset);
            }

            foreach (long shelfOffset in fixed32Scalar16RetainedBatchShelfOffsets)
            {
                fixed32Scalar16ReadCache.Remove(shelfOffset);
            }

            if (routerReadCacheInvalidationPending)
            {
                ClearRouterReadCaches();
            }

            durabilityBatchActive = false;
            ReleaseDiagnosticWriteWindow(writeContext.OperationToken);
            routerReadCacheInvalidationPending = false;
            deferredDurabilityCommitRequests = 0;
            currentWriteIntent = default;
            GetScalar8Scalar8MutableBatchShelfBytes().Clear();
            activeWriteContext = null;
            scalar16Scalar8MutableBatchShelfBytes.Clear();
            scalar8Scalar16MutableBatchShelfBytes.Clear();
            scalar16Scalar16MutableBatchShelfBytes.Clear();
            fixed32Scalar8MutableBatchShelfBytes.Clear();
            fixed32Scalar16MutableBatchShelfBytes.Clear();
            fixed32Scalar8RetainedBatchShelfOffsets.Clear();
            fixed32Scalar16RetainedBatchShelfOffsets.Clear();
            ReleaseFixedNScalar8ShelfOwnersForWriteContext(writeContext);
            ReleaseFixedNScalar16ShelfOwnersForWriteContext(writeContext);
            ReleaseFixedNScalar8ShelfBytesForWriteContext(writeContext);
            ReleaseFixedNScalar16ShelfBytesForWriteContext(writeContext);
            writeContext.FixedNScalar8RouteClaims.Clear();
            writeContext.FixedNScalar16RouteClaims.Clear();
            ReleaseVarKeyScalar8MutableBatchShelves(clearShelfBytes: true);
            ReleaseVarKeyScalar16MutableBatchShelves(clearShelfBytes: true);
            ReleaseVarKeyVarIdentityMutableBatchShelves(clearShelfBytes: true);
            ReleaseScalar8VarIdentityMutableBatchShelves(clearShelfBytes: true);
            ReleaseScalar16VarIdentityMutableBatchShelves(clearShelfBytes: true);
            terminalVarIdentityMutableBatchShelfBytes.Clear();
            return (telemetry, deferredRequests, storageDiagnostics);
        }
    }

    /// <summary>
    /// Captures dirty shelf and deferred commit counters before a durability batch is flushed.<br/>
    /// This is intentionally a shallow counter snapshot so diagnostics can explain commit growth without walking shelf contents or allocating per-shelf records.<br/>
    /// </summary>
    /// <returns>A diagnostic snapshot for the active durability batch.</returns>
    private LibraDexBatchStorageDiagnostics CreateBatchStorageDiagnosticsSnapshot(LibraDexWriteContext writeContext)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        return new LibraDexBatchStorageDiagnostics(
            GetScalar8Scalar8MutableBatchShelfBytes().Count,
            scalar16Scalar8MutableBatchShelfBytes.Count,
            scalar8Scalar16MutableBatchShelfBytes.Count,
            scalar16Scalar16MutableBatchShelfBytes.Count,
            fixed32Scalar8MutableBatchShelfBytes.Count + fixed32Scalar8RetainedBatchShelfOffsets.Count,
            fixed32Scalar16MutableBatchShelfBytes.Count + fixed32Scalar16RetainedBatchShelfOffsets.Count,
            writeContext.FixedNScalar8MutableBatchShelfBytes.Count,
            writeContext.FixedNScalar16MutableBatchShelfBytes.Count,
            varKeyScalar8MutableBatchShelves.Count,
            varKeyScalar16MutableBatchShelves.Count,
            varKeyVarIdentityMutableBatchShelves.Count,
            scalar8VarIdentityMutableBatchShelves.Count,
            scalar16VarIdentityMutableBatchShelves.Count,
            SumVarKeyScalar8MutableBatchShelfBytes(),
            SumVarKeyScalar16MutableBatchShelfBytes(),
            deferredDurabilityCommitRequests,
            routerReadCacheInvalidationPending);
    }

    /// <summary>
    /// Aborts the active durability batch by discarding staged DataKernel writes that were not published.<br/>
    /// This is an explicit revert-to-current-backing-state operation, not a SQL-style rollback after durable publication.<br/>
    /// </summary>
    /// <returns>The number of lower-level commit requests that were abandoned.</returns>
    /// <exception cref="InvalidOperationException">Thrown when no durability batch is active.</exception>
    internal long AbortDurabilityBatch(LibraDexWriteContext writeContext)
    {
        if (!durabilityBatchActive)
        {
            throw new InvalidOperationException("No LibraDex session durability batch is active.");
        }

        lock (writePublicationSync)
        {
            VerifyActiveWriteContext(writeContext);
            long deferredRequests = deferredDurabilityCommitRequests;
            kernel.DiscardPending();
            ClearRouterReadCaches();
            durabilityBatchActive = false;
            ReleaseDiagnosticWriteWindow(writeContext.OperationToken);
            routerReadCacheInvalidationPending = false;
            deferredDurabilityCommitRequests = 0;
            currentWriteIntent = default;
            GetScalar8Scalar8MutableBatchShelfBytes().Clear();
            activeWriteContext = null;
            scalar16Scalar8MutableBatchShelfBytes.Clear();
            scalar8Scalar16MutableBatchShelfBytes.Clear();
            scalar16Scalar16MutableBatchShelfBytes.Clear();
            fixed32Scalar8MutableBatchShelfBytes.Clear();
            fixed32Scalar16MutableBatchShelfBytes.Clear();
            fixed32Scalar8RetainedBatchShelfOffsets.Clear();
            fixed32Scalar16RetainedBatchShelfOffsets.Clear();
            ReleaseFixedNScalar8ShelfOwnersForWriteContext(writeContext);
            ReleaseFixedNScalar16ShelfOwnersForWriteContext(writeContext);
            ReleaseFixedNScalar8ShelfBytesForWriteContext(writeContext);
            ReleaseFixedNScalar16ShelfBytesForWriteContext(writeContext);
            writeContext.FixedNScalar8RouteClaims.Clear();
            writeContext.FixedNScalar16RouteClaims.Clear();
            ReleaseVarKeyScalar8MutableBatchShelves(clearShelfBytes: true);
            ReleaseVarKeyScalar16MutableBatchShelves(clearShelfBytes: true);
            ReleaseVarKeyVarIdentityMutableBatchShelves(clearShelfBytes: true);
            ReleaseScalar8VarIdentityMutableBatchShelves(clearShelfBytes: true);
            ReleaseScalar16VarIdentityMutableBatchShelves(clearShelfBytes: true);
            terminalVarIdentityMutableBatchShelfBytes.Clear();
            return deferredRequests;
        }
    }

    /// <summary>
    /// Flushes dirty `SS8-8` fixed-shelf batch images into DataKernel staging before the durability batch publishes.<br/>
    /// The image is normalized at this boundary so persisted fixed shelves remain compact even after future batch-local tombstone accumulation.<br/>
    /// </summary>
    private void FlushDirtyScalar8Scalar8MutableBatchShelfBytes()
    {
        foreach (KeyValuePair<long, byte[]> dirtyShelf in GetScalar8Scalar8MutableBatchShelfBytes())
        {
            Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Create(dirtyShelf.Value.Length);
            Scalar8Scalar8 shelf = new(dirtyShelf.Value, profile);
            _ = shelf.NormalizeDeletedSlotsForPublication();
            RewriteBatchShelfBytes(dirtyShelf.Key, dirtyShelf.Value.AsSpan(0, profile.ShelfExtentSize));
        }
    }

