    /// <summary>
    /// Publishes one dirty batch shelf image through the lowest-allocation path available for the active backing kind.<br/>
    /// Memory-backed catalogs copy directly into the volatile arena because there is no durable publication boundary to preserve.<br/>
    /// File-backed catalogs keep the staged `ReserveAt` path so durability, coalescing, and flush telemetry stay unchanged.<br/>
    /// </summary>
    /// <param name="shelfOffset">The absolute backing offset of the dirty shelf image.</param>
    /// <param name="shelfBytes">The normalized shelf bytes to publish.</param>
    private void RewriteBatchShelfBytes(long shelfOffset, ReadOnlySpan<byte> shelfBytes)
    {
        kernel.StageWriteAt(shelfOffset, shelfBytes);
    }

    /// <summary>
    /// Publishes one dirty ordinary `SV8` mutable shelf using tracked byte ranges when the mutation is an in-place insert.<br/>
    /// Replacement images and delete-normalization paths mark the shelf as full-dirty, preserving the older whole-shelf publication behavior for structural uncertainty.<br/>
    /// </summary>
    /// <param name="shelfOffset">The absolute backing offset of the dirty shelf image.</param>
    /// <param name="mutableShelf">The mutable shelf view whose bytes have already been normalized for publication.</param>
    private void RewriteScalar8VarIdentityMutableBatchShelfBytes(long shelfOffset, Scalar8VarIdentityMutableShelfView mutableShelf)
    {
        int shelfExtentSize = mutableShelf.Profile.ShelfExtentSize;
        if (mutableShelf.RequiresFullRewrite)
        {
            RewriteBatchShelfBytes(shelfOffset, mutableShelf.Bytes.AsSpan(0, shelfExtentSize));
            return;
        }

        if (mutableShelf.HeaderDirty)
        {
            RewriteBatchShelfBytes(shelfOffset, mutableShelf.Bytes.AsSpan(0, Scalar8VarIdentityLayout.HeaderSize));
        }

        if (mutableShelf.DirtySlotEnd > mutableShelf.DirtySlotStart)
        {
            int slotStart = mutableShelf.DirtySlotStart;
            int slotLength = mutableShelf.DirtySlotEnd - slotStart;
            RewriteBatchShelfBytes(shelfOffset + slotStart, mutableShelf.Bytes.AsSpan(slotStart, slotLength));
        }

        if (mutableShelf.DirtyRecordEnd > mutableShelf.DirtyRecordStart)
        {
            int recordStart = mutableShelf.DirtyRecordStart;
            int recordLength = mutableShelf.DirtyRecordEnd - recordStart;
            RewriteBatchShelfBytes(shelfOffset + recordStart, mutableShelf.Bytes.AsSpan(recordStart, recordLength));
        }

        if (!mutableShelf.HeaderDirty &&
            mutableShelf.DirtySlotEnd <= mutableShelf.DirtySlotStart &&
            mutableShelf.DirtyRecordEnd <= mutableShelf.DirtyRecordStart)
        {
            RewriteBatchShelfBytes(shelfOffset, mutableShelf.Bytes.AsSpan(0, shelfExtentSize));
        }
    }

    private void ReleaseVarKeyScalar8MutableBatchShelves(bool clearShelfBytes)
    {
        foreach (VarKeyScalar8MutableShelf mutableShelf in varKeyScalar8MutableBatchShelves.Values)
        {
            ReleaseVarKeyScalar8MutableShelf(mutableShelf, clearShelfBytes);
        }

        varKeyScalar8MutableBatchShelves.Clear();
    }

    private void ReleaseVarKeyScalar16MutableBatchShelves(bool clearShelfBytes)
    {
        foreach (VarKeyScalar16MutableShelf mutableShelf in varKeyScalar16MutableBatchShelves.Values)
        {
            ReleaseVarKeyScalar16MutableShelf(mutableShelf, clearShelfBytes);
        }

        varKeyScalar16MutableBatchShelves.Clear();
    }

    /// <summary>
    /// Releases one `VS8` mutable shelf and returns large non-shared-pool byte images to the session-local bounded reuse pool.<br/>
    /// Small pooled byte images are returned by the mutable shelf itself; large images use this explicit owner path to avoid unbounded LOH churn during batch indexing.<br/>
    /// </summary>
    /// <param name="mutableShelf">The mutable shelf to release.</param>
    /// <param name="clearShelfBytes">Whether reusable shelf bytes should be cleared before returning to their owner pool.</param>
    private void ReleaseVarKeyScalar8MutableShelf(VarKeyScalar8MutableShelf mutableShelf, bool clearShelfBytes)
    {
        byte[] bytes = mutableShelf.Bytes;
        bool returnLargeBytes = bytes.Length > PooledMutableShelfMaxBytes;
        if (clearShelfBytes && returnLargeBytes)
        {
            bytes.AsSpan(0, mutableShelf.Profile.ShelfExtentSize).Clear();
        }

        mutableShelf.Release(clearShelfBytes);
        if (returnLargeBytes)
        {
            ReturnLargeMutableShelfBytes(bytes);
        }
    }

    /// <summary>
    /// Releases one `VS16` mutable shelf and returns large non-shared-pool byte images to the session-local bounded reuse pool.<br/>
    /// Small pooled byte images are returned by the mutable shelf itself; large images use this explicit owner path to avoid unbounded LOH churn during batch indexing.<br/>
    /// </summary>
    /// <param name="mutableShelf">The mutable shelf to release.</param>
    /// <param name="clearShelfBytes">Whether reusable shelf bytes should be cleared before returning to their owner pool.</param>
    private void ReleaseVarKeyScalar16MutableShelf(VarKeyScalar16MutableShelf mutableShelf, bool clearShelfBytes)
    {
        byte[] bytes = mutableShelf.Bytes;
        bool returnLargeBytes = bytes.Length > PooledMutableShelfMaxBytes;
        if (clearShelfBytes && returnLargeBytes)
        {
            bytes.AsSpan(0, mutableShelf.Profile.ShelfExtentSize).Clear();
        }

        mutableShelf.Release(clearShelfBytes);
        if (returnLargeBytes)
        {
            ReturnLargeMutableShelfBytes(bytes);
        }
    }

    /// <summary>
    /// Rents small mutable shelf byte images and allocates large images as ordinary arrays.<br/>
    /// Large var-key shelves are transient batch working buffers, and returning them to `ArrayPool<byte>.Shared` can retain hundreds of megabytes or more in the shared pool after each commit.<br/>
    /// The returned <paramref name="ownsPooledBytes"/> flag tells the mutable shelf whether release should return the byte image to the pool, while non-pooled arrays are left for normal GC collection.<br/>
    /// </summary>
    /// <param name="shelfExtentSize">The exact persisted shelf extent size that must be readable and writable by the mutable view.</param>
    /// <param name="ownsPooledBytes">Receives `true` when the returned array came from the shared byte pool and must be returned by the mutable shelf.</param>
    /// <returns>A byte array at least <paramref name="shelfExtentSize"/> bytes long for use as the authoritative mutable shelf image.</returns>
    private byte[] RentMutableShelfBytes(int shelfExtentSize, out bool ownsPooledBytes)
    {
        if (shelfExtentSize <= PooledMutableShelfMaxBytes)
        {
            ownsPooledBytes = true;
            return ArrayPool<byte>.Shared.Rent(shelfExtentSize);
        }

        if (largeMutableShelfBytePool.TryGetValue(shelfExtentSize, out Stack<byte[]>? buffers) &&
            buffers.Count != 0)
        {
            ownsPooledBytes = false;
            largeMutableShelfBytePoolBytes -= shelfExtentSize;
            return buffers.Pop();
        }

        ownsPooledBytes = false;
        return GC.AllocateUninitializedArray<byte>(shelfExtentSize);
    }

    /// <summary>
    /// Rents an exact-size mutable fixed-N shelf byte image from the session-local large-shelf pool when possible.<br/>
    /// Unlike general var-key mutable shelves, fixed-N writer-context code stores raw arrays directly and therefore needs exact-length buffers for existing validation and publish contracts.<br/>
    /// </summary>
    /// <param name="shelfExtentSize">The exact fixed-N shelf extent size to rent.<br/></param>
    /// <returns>An exact-length mutable shelf byte image.<br/></returns>
    private byte[] RentFixedNMutableShelfBytes(int shelfExtentSize)
    {
        lock (largeMutableShelfBytePoolSync)
        {
            if (largeMutableShelfBytePool.TryGetValue(shelfExtentSize, out Stack<byte[]>? buffers) &&
                buffers.Count != 0)
            {
                largeMutableShelfBytePoolBytes -= shelfExtentSize;
                return buffers.Pop();
            }
        }

        return GC.AllocateUninitializedArray<byte>(shelfExtentSize);
    }

    /// <summary>
    /// Returns one exact-size fixed-N mutable shelf image to the session-local bounded reuse pool.<br/>
    /// Fixed-N writer contexts store raw arrays without an ownership sidecar, so this method deliberately accepts all exact fixed-N shelf sizes rather than applying the var-key shared-pool threshold.<br/>
    /// </summary>
    /// <param name="bytes">The fixed-N mutable shelf byte image to retain for reuse or drop for normal GC collection.<br/></param>
    private void ReturnFixedNMutableShelfBytes(byte[] bytes)
    {
        lock (largeMutableShelfBytePoolSync)
        {
            if (largeMutableShelfBytePoolBytes + bytes.Length > LargeMutableShelfPoolMaxBytes)
            {
                return;
            }

            if (!largeMutableShelfBytePool.TryGetValue(bytes.Length, out Stack<byte[]>? buffers))
            {
                buffers = new Stack<byte[]>();
                largeMutableShelfBytePool.Add(bytes.Length, buffers);
            }

            buffers.Push(bytes);
            largeMutableShelfBytePoolBytes += bytes.Length;
        }
    }

    /// <summary>
    /// Returns one large mutable shelf byte image to the session-local bounded reuse pool.<br/>
    /// The pool is deliberately small and exact-size keyed so FileSearch-style batch indexing reuses hot shelf images without letting process memory grow with the total number of batches.<br/>
    /// </summary>
    /// <param name="bytes">The large mutable shelf byte image to retain for reuse or drop for normal GC collection.</param>
    private void ReturnLargeMutableShelfBytes(byte[] bytes)
    {
        if (bytes.Length <= PooledMutableShelfMaxBytes ||
            largeMutableShelfBytePoolBytes + bytes.Length > LargeMutableShelfPoolMaxBytes)
        {
            return;
        }

        if (!largeMutableShelfBytePool.TryGetValue(bytes.Length, out Stack<byte[]>? buffers))
        {
            buffers = new Stack<byte[]>();
            largeMutableShelfBytePool.Add(bytes.Length, buffers);
        }

        buffers.Push(bytes);
        largeMutableShelfBytePoolBytes += bytes.Length;
    }

    /// <summary>
    /// Sums the profiled byte extent of all `VS8` mutable shelves retained by the active durability batch.<br/>
    /// This is diagnostic-only and intentionally walks the current batch dictionary without allocating per-shelf records.<br/>
    /// The value explains transient batch working-set pressure separately from DataKernel committed bytes and deferred write bytes.<br/>
    /// </summary>
    /// <returns>The total profiled `VS8` mutable shelf byte extent retained by the current batch.</returns>
    private long SumVarKeyScalar8MutableBatchShelfBytes()
    {
        long total = 0;
        foreach (VarKeyScalar8MutableShelf mutableShelf in varKeyScalar8MutableBatchShelves.Values)
        {
            total += mutableShelf.Profile.ShelfExtentSize;
        }

        return total;
    }

