        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        int identityCount = ReadFixed32Scalar16IdentityLowRange(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            DefaultFixed32Scalar16MaxRouterHops,
