            targetKindCache);
        return new Fixed32Scalar16RangeReadResult(
            identityCount,
            UsedRouteKindCache: true,
            targetKindCache.Count);
    }

    private int ReadFixed32Scalar16IdentityLowRangeFromRouter(
        long routerOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int remainingRouterHops,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentityLows,
        Span<byte> routerScratch,
        Span<byte> shelfScratch,
        long previousShelfOffset,
        RouteTargetKindCache targetKindCache)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The FS32-16 routed range traversal exceeded the configured maximum router hop count.");
        }

        ReadRouterPageForRangeScan(routerOffset, routerScratch);
        RouterReader reader = new(routerScratch);
        byte startPrefix = lowerEdge ? GetFixed32Scalar16Prefix(lower0, lower1, lower2, lower3, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetFixed32Scalar16Prefix(upper0, upper1, upper2, upper3, reader.KeyDepth) : byte.MaxValue;
        int routeCount = endPrefix - startPrefix + 1;
        Span<long> targetOffsets = routeCount <= 256
            ? stackalloc long[routeCount]
            : new long[routeCount];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            targetOffsets[prefix - startPrefix] = reader.FindTarget((byte)prefix);
        }

        int copied = 0;
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            byte prefixByte = (byte)prefix;
            long targetOffset = targetOffsets[prefix - startPrefix];
            if (targetOffset == 0)
            {
                continue;
            }

            Fixed32Scalar16RouteTargetKind kind = GetFixed32Scalar16RouteTargetKind(targetOffset, targetKindCache);
            if (kind == Fixed32Scalar16RouteTargetKind.Router)
            {
                copied += ReadFixed32Scalar16IdentityLowRangeFromRouter(
                    targetOffset,
                    profile,
                    lower0,
                    lower1,
                    lower2,
                    lower3,
                    upper0,
                    upper1,
                    upper2,
                    upper3,
                    remainingRouterHops - 1,
                    lowerEdge && prefixByte == startPrefix,
                    upperEdge && prefixByte == endPrefix,
                    encodedIdentityLows[copied..],
                    routerScratch,
                    shelfScratch,
                    previousShelfOffset,
                    targetKindCache);
                continue;
            }

            if (kind != Fixed32Scalar16RouteTargetKind.Shelf || targetOffset == previousShelfOffset)
            {
                continue;
            }

            ReadFixed32Scalar16ShelfForRangeScan(targetOffset, profile, shelfScratch);
            Fixed32Scalar16ReadOnly shelf = new(shelfScratch, profile);
            copied += shelf.CopyIdentitiesInKeyRange(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3, encodedIdentityLows[copied..]);
            previousShelfOffset = targetOffset;
        }

        return copied;
    }

    private Fixed32Scalar16RouteTargetKind GetFixed32Scalar16RouteTargetKind(long targetOffset, RouteTargetKindCache targetKindCache)
    {
        if (targetKindCache.TryGet(targetOffset, out int cachedKind))
        {
            return (Fixed32Scalar16RouteTargetKind)cachedKind;
        }

        Fixed32Scalar16RouteTargetKind kind = ClassifyFixed32Scalar16RouteTarget(targetOffset);
        targetKindCache.Set(targetOffset, (int)kind);
        return kind;
    }


    /// <summary>
    /// Appends a sorted `Fixed32Scalar16` shelf and links one root-router prefix byte to the new shelf in the same commit.<br/>
    /// The shelf is initialized with deterministic `(key0, key1, key2, key3, identity)` tuples where the key suffix plus identity equal the insert index.<br/>
    /// This mirrors the first `SS16-8` router-to-shelf primitive while keeping the fixed 32-byte key shelf isolated from split code.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte route to link to the new shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used to size and populate the shelf extent.</param>
    /// <param name="itemCount">The number of deterministic sorted tuples to insert into the shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="itemCount"/> is outside the profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid, not direct-index capable, or shelf population fails.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        int itemCount)
    {
        if (itemCount < 0 || itemCount > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(itemCount), itemCount, "FS32-16 shelf item count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < itemCount; i++)
        {
            Fixed32Scalar16Layout.EncodeFixed32FromUInt64((ulong)i, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
            Fixed32Scalar16InsertResult result = shelf.Insert(
                key0,
                key1,
                key2,
                key3,
                Fixed32Scalar16Layout.EncodeUnsignedScalar8((ulong)i),
                allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 routed shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRouteToShelf(rootRouterOffset, existingRouter, prefixByte, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Routes one prefix byte through a persisted root router and reads the targeted `FS32-16` shelf bytes into a caller buffer.<br/>
    /// This validation helper deliberately performs the two physical reads separately: root router first, then shelf extent.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte to route.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The routed shelf offset that was read into <paramref name="destination"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `FS32-16` shelf.</exception>
    internal long ReadRoutedFixed32Scalar16Shelf(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled FS32-16 shelf extent size.", nameof(destination));
        }

        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 shelf route is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar16ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed FS32-16 shelf bytes are invalid.");
        }

        return shelfOffset;
    }


    /// <summary>
    /// Inserts one tuple into a routed `FS32-16` shelf without performing split handling.<br/>
    /// The method routes through the root router, reads the target fixed-key shelf, stages a same-offset shelf rewrite, and commits only when the shelf insert mutates bytes.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the caller can choose the next structural path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte used to route to the shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The encoded sortable key part 0 to insert.</param>
    /// <param name="key1">The encoded sortable key part 1 to insert.</param>
    /// <param name="key2">The encoded sortable key part 2 to insert.</param>
    /// <param name="key3">The encoded sortable key part 3 to insert.</param>
    /// <param name="encodedIdentity">The encoded sortable identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The routed shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `FS32-16` shelf.</exception>
    internal (long ShelfOffset, Fixed32Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertRoutedFixed32Scalar16NoSplit(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult result = shelf.Insert(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys);
        if (result != Fixed32Scalar16InsertResult.Inserted)
        {
            return (shelfOffset, result, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfOffset, result, telemetry);
    }


    /// <summary>
    /// Appends a caller-populated `FS32-16` shelf and links multiple root-router prefix bytes to that same shelf in one commit.<br/>
    /// This helper exists for fixed-key split-path validation where a single full shelf initially owns more than one root prefix byte.<br/>
    /// The supplied key and identity vectors are inserted through the shelf view, so persisted ordering and duplicate rules match normal shelf behavior.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="key0s">The encoded key part 0 values to insert into the shelf.</param>
    /// <param name="key1s">The encoded key part 1 values to insert into the shelf.</param>
    /// <param name="key2s">The encoded key part 2 values to insert into the shelf.</param>
    /// <param name="key3s">The encoded key part 3 values to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <param name="prefixBytes">The root-router prefix bytes to point at the new shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfAndLinkRootRoutes(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ReadOnlySpan<ulong> key0s,
        ReadOnlySpan<ulong> key1s,
        ReadOnlySpan<ulong> key2s,
        ReadOnlySpan<ulong> key3s,
        ReadOnlySpan<ulong> encodedIdentities,
        ReadOnlySpan<byte> prefixBytes)
    {
        if (key0s.Length != key1s.Length || key0s.Length != key2s.Length || key0s.Length != key3s.Length || key0s.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("FS32-16 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (key0s.Length <= 0 || key0s.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(key0s), key0s.Length, "FS32-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRouter = ReadDirectRootRouterBytesForLink(rootRouterOffset);

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar16InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 setup shelf insert at {i}, got {result}.");
            }
        }

        DataKernelCommitTelemetry telemetry = LinkDirectRootRouterRoutesToShelf(rootRouterOffset, existingRouter, prefixBytes, shelfReservation.Extent.Offset);
        return (shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Splits a routed full `FS32-16` shelf by root prefix.<br/>
    /// This first fixed-key split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first fixed-key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require a later `FS32-16` shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both split shelves.</param>
    /// <param name="key0">The encoded key part 0 to insert during the split.</param>
    /// <param name="key1">The encoded key part 1 to insert during the split.</param>
    /// <param name="key2">The encoded key part 2 to insert during the split.</param>
    /// <param name="key3">The encoded key part 3 to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first FS32-16 split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first FS32-16 split path expects a valid full shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentity, key0, key1, key2, key3, encodedIdentity) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentity == encodedIdentity)
            {
                return (leftShelfOffset, 0, existingCount, 0, Fixed32Scalar16InsertResult.AlreadyPresent, default);
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = (byte)(key0s[i] >> 56) >= rightPrefixByte;
            Fixed32Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first FS32-16 split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Fixed32Scalar16InsertResult.Inserted, telemetry);
    }


    /// <summary>
    /// Splits a full routed `FS32-16` shelf by transforming the shelf's existing offset into a child router and appending two replacement shelves.<br/>
    /// This path covers same-root-prefix fixed-32-byte-key splits where the root route must stay stable and the next key byte decides left/right ownership.<br/>
    /// The parent root router is not dirtied; the former shelf location is structurally reused as a direct-index one-byte child router at key depth `1`.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root prefix byte that currently routes to the full shelf and will continue routing to the transformed child router.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByShelfTransform(
            long rootRouterOffset,
            byte rootPrefixByte,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity)
    {
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootRouterReader = new(rootRouterBytes);
        if (!rootRouterReader.IsValid || !rootRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        ushort allocationClassId = rootRouterReader.AllocationClassId;
        long childRouterOffset = rootRouterReader.FindTarget(rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 transform source route is unset.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(childRouterOffset, existingShelfBytes);
        return SplitRoutedFixed32Scalar16ByShelfTransform(
            childRouterOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            allocationClassId,
            childRouterKeyDepth: 1);
    }


    /// <summary>
    /// Builds the replacement shelf images and route split plan for an `FS32-16` same-prefix transform without touching storage publication state.<br/>
    /// The caller can run this under a root topology gate, then publish the returned bytes in a short storage-publication section.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full existing shelf bytes.<br/></param>
    /// <param name="rightPrefixByte">The incoming tuple prefix byte at <paramref name="childRouterKeyDepth"/>.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.<br/></param>
    /// <param name="key0">The first encoded key lane to insert during the split.<br/></param>
    /// <param name="key1">The second encoded key lane to insert during the split.<br/></param>
    /// <param name="key2">The third encoded key lane to insert during the split.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.<br/></param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.<br/></param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.<br/></param>
    /// <param name="build">The prepared split image and router plan when the method succeeds.<br/></param>
    /// <returns>True when a transform split plan was built; false for no-op/conflict results.<br/></returns>
    private static bool TryBuildFixed32Scalar16TransformSplit(
        ReadOnlySpan<byte> existingShelfBytes,
        byte rightPrefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        ushort allocationClassId,
        ushort childRouterKeyDepth,
        out Fixed32Scalar16TransformSplitBuild build)
    {
        build = default;
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled FS32-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full FS32-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentityHigh, currentIdentityLow, key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                build = new Fixed32Scalar16TransformSplitBuild(
                    0,
                    0,
                    [],
                    [],
                    existingCount,
                    0,
                    Fixed32Scalar16InsertResult.AlreadyPresent,
                    allocationClassId,
                    childRouterKeyDepth,
                    0);
                return false;
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseFixed32Scalar16TransformSplitPlan(key0s, key1s, key2s, key3s, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar16Prefix(key0s[i], key1s[i], key2s[i], key3s[i], splitKeyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar16InsertResult result = goesRight
                ? rightShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i])
                : leftShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i]);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split FS32-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        build = new Fixed32Scalar16TransformSplitBuild(
            splitKeyDepth,
            selectedRightPrefixByte,
            leftShelfBytes,
            rightShelfBytes,
            leftShelf.ItemCount,
            rightShelf.ItemCount,
            Fixed32Scalar16InsertResult.Inserted,
            allocationClassId,
            childRouterKeyDepth,
            profile.ShelfExtentSize);
        return true;
    }

    /// <summary>
    /// Splits an already-routed full `FS32-16` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled FS32-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full FS32-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        Fixed32BatchAttributionDiagnostics? transformAttribution = Fixed32BatchAttributionDiagnostics.Current;
        long transformPhaseStart = transformAttribution is null ? 0 : Stopwatch.GetTimestamp();
        int mergedCount = existingCount + 1;
        ulong[] key0Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key1Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key2Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] key3Buffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] identityHighBuffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        ulong[] identityLowBuffer = ArrayPool<ulong>.Shared.Rent(mergedCount);
        byte[] leftShelfBuffer = ArrayPool<byte>.Shared.Rent(profile.ShelfExtentSize);
        byte[] rightShelfBuffer = ArrayPool<byte>.Shared.Rent(profile.ShelfExtentSize);
        Span<ulong> key0s = key0Buffer.AsSpan(0, mergedCount);
        Span<ulong> key1s = key1Buffer.AsSpan(0, mergedCount);
        Span<ulong> key2s = key2Buffer.AsSpan(0, mergedCount);
        Span<ulong> key3s = key3Buffer.AsSpan(0, mergedCount);
        Span<ulong> identityHighs = identityHighBuffer.AsSpan(0, mergedCount);
        Span<ulong> identityLows = identityLowBuffer.AsSpan(0, mergedCount);
        Span<byte> leftShelfBytes = leftShelfBuffer.AsSpan(0, profile.ShelfExtentSize);
        Span<byte> rightShelfBytes = rightShelfBuffer.AsSpan(0, profile.ShelfExtentSize);
        try
        {
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentityHigh, currentIdentityLow, key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Fixed32Scalar16InsertResult.AlreadyPresent, default);
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        if (transformAttribution is not null)
        {
            long phaseEnd = Stopwatch.GetTimestamp();
            transformAttribution.TransformMergeTicks += phaseEnd - transformPhaseStart;
            transformPhaseStart = phaseEnd;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseFixed32Scalar16TransformSplitPlan(key0s, key1s, key2s, key3s, childRouterKeyDepth, rightPrefixByte);
        if (transformAttribution is not null)
        {
            long phaseEnd = Stopwatch.GetTimestamp();
            transformAttribution.TransformPlanTicks += phaseEnd - transformPhaseStart;
            transformPhaseStart = phaseEnd;
        }

        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar16Prefix(key0s[i], key1s[i], key2s[i], key3s[i], splitKeyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar16InsertResult result = goesRight
                ? rightShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i])
                : leftShelf.AppendKnownSorted(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i]);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split FS32-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        if (transformAttribution is not null)
        {
            long phaseEnd = Stopwatch.GetTimestamp();
            transformAttribution.TransformShelfBuildTicks += phaseEnd - transformPhaseStart;
            transformPhaseStart = phaseEnd;
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        if (transformAttribution is not null)
        {
            long phaseEnd = Stopwatch.GetTimestamp();
            transformAttribution.TransformShelfCopyTicks += phaseEnd - transformPhaseStart;
            transformPhaseStart = phaseEnd;
        }

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            if (routerDepth == splitKeyDepth)
                appendedWriter.InitializeExpandedOneByteSplit(routerDepth, allocationClassId, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte);
            else
                appendedWriter.InitializeExpandedOneByteUniform(routerDepth, allocationClassId, nextRouterOffset);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        if (nextRouterOffset != 0)
            childWriter.InitializeExpandedOneByteUniform(childRouterKeyDepth, allocationClassId, nextRouterOffset);
        else
            childWriter.InitializeExpandedOneByteSplit(childRouterKeyDepth, allocationClassId, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte);
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        if (transformAttribution is not null)
        {
            long phaseEnd = Stopwatch.GetTimestamp();
            transformAttribution.TransformRouterBuildTicks += phaseEnd - transformPhaseStart;
            transformPhaseStart = phaseEnd;
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        if (transformAttribution is not null)
            transformAttribution.TransformCommitTicks += Stopwatch.GetTimestamp() - transformPhaseStart;
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        int leftItemCount = leftShelf.ItemCount;
        int rightItemCount = rightShelf.ItemCount;
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftItemCount, rightItemCount, Fixed32Scalar16InsertResult.Inserted, telemetry);
        }
        finally
        {
            ArrayPool<ulong>.Shared.Return(key0Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key1Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key2Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(key3Buffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(identityHighBuffer, clearArray: false);
            ArrayPool<ulong>.Shared.Return(identityLowBuffer, clearArray: false);
            ArrayPool<byte>.Shared.Return(leftShelfBuffer, clearArray: false);
            ArrayPool<byte>.Shared.Return(rightShelfBuffer, clearArray: false);
        }
    }


    /// <summary>
    /// Appends a caller-populated `FS32-16` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the `SS16-8` deeper-route setup while keeping fixed-32-byte-key shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="key0s">The first encoded key lanes to insert into the shelf.</param>
    /// <param name="key1s">The second encoded key lanes to insert into the shelf.</param>
    /// <param name="key2s">The third encoded key lanes to insert into the shelf.</param>
    /// <param name="key3s">The fourth encoded key lanes to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        ReadOnlySpan<ulong> key0s,
        ReadOnlySpan<ulong> key1s,
        ReadOnlySpan<ulong> key2s,
        ReadOnlySpan<ulong> key3s,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (key0s.Length != key1s.Length || key0s.Length != key2s.Length || key0s.Length != key3s.Length || key0s.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("FS32-16 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (key0s.Length <= 0 || key0s.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(key0s), key0s.Length, "FS32-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar16InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Tries to build replacement `FS32-16` shelves for a parent-route refinement split at one encoded key byte depth.<br/>
    /// The incoming tuple is merged into sorted order first, then the selected route prefix boundary is used to populate left and right replacement shelves.<br/>
    /// Returning false means the parent route cannot distinguish the tuples at this depth or the incoming tuple was already present.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full source shelf bytes.</param>
    /// <param name="keyDepth">The parent router key byte depth used for partitioning.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix used as the initial boundary hint.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateFixed32Scalar16SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar16InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full FS32-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentityHigh, currentIdentityLow, key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                insertResult = Fixed32Scalar16InsertResult.AlreadyPresent;
                return false;
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        if (!TryChooseFixed32Scalar16TransformSplitRightPrefix(key0s, key1s, key2s, key3s, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar16Prefix(key0s[i], key1s[i], key2s[i], key3s[i], keyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar16InsertResult itemResult = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (itemResult != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-16 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Fixed32Scalar16InsertResult.Inserted;
        return true;
    }


    /// <summary>
    /// Chooses the key byte depth and right-side prefix boundary for an `FS32-16` transform split.<br/>
    /// The search starts at the immediate child-router depth and advances until it finds a prefix byte that can divide the full shelf plus incoming tuple into two replacement shelves.<br/>
    /// This mirrors the `SS16-8` transform planner while reading from all four fixed-key lanes.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="firstKeyDepth">The first encoded key byte depth that can be owned by the router being created at the transformed shelf offset.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <returns>The byte depth and first prefix byte that should route to the right replacement shelf.</returns>
    /// <exception cref="ArgumentException">Thrown when key lane vectors do not have the same length.</exception>
    /// <exception cref="InvalidDataException">Thrown when the key set has no usable prefix boundary in the encoded key.</exception>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseFixed32Scalar16TransformSplitPlan(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort firstKeyDepth,
        byte hintRightPrefixByte)
    {
        if (sortedKey0s.Length != sortedKey1s.Length || sortedKey0s.Length != sortedKey2s.Length || sortedKey0s.Length != sortedKey3s.Length)
        {
            throw new ArgumentException("FS32-16 key lane vectors must have the same length.", nameof(sortedKey1s));
        }

        if (sortedKey0s.Length < 2)
        {
            throw new InvalidDataException("The FS32-16 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < Fixed32Scalar16Layout.KeySize; keyDepth++)
        {
            if (TryChooseFixed32Scalar16TransformSplitRightPrefix(sortedKey0s, sortedKey1s, sortedKey2s, sortedKey3s, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The FS32-16 transform split path requires at least two distinct prefixes in the remaining encoded key bytes.");
    }


    /// <summary>
    /// Tries to choose the right-side prefix boundary for an `FS32-16` transform split at one encoded key depth.<br/>
    /// The chosen boundary is the nearest usable prefix transition around the median of the full shelf plus incoming tuple set.<br/>
    /// Returning false means all tuples share the same prefix at this byte depth and the caller must try a deeper router byte.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="keyDepth">The encoded key byte depth being evaluated.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte when a usable boundary exists.</param>
    /// <returns>True when a usable boundary exists at <paramref name="keyDepth"/>; otherwise false.</returns>
    private static bool TryChooseFixed32Scalar16TransformSplitRightPrefix(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKey0s.Length / 2;
        for (int i = desiredRightStart; i < sortedKey0s.Length; i++)
        {
            byte leftPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetFixed32Scalar16Prefix(sortedKey0s[0], sortedKey1s[0], sortedKey2s[0], sortedKey3s[0], keyDepth);
        byte lastPrefix = GetFixed32Scalar16Prefix(sortedKey0s[^1], sortedKey1s[^1], sortedKey2s[^1], sortedKey3s[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }


    /// <summary>
    /// Routes through a direct-index root router and one direct-index child router, then reads the targeted `FS32-16` shelf bytes into a caller buffer.<br/>
    /// This validation helper supports same-root-prefix fixed-32-byte-key split testing before a general multi-depth routing walker exists.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The child router offset and routed shelf offset.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when either route is unset or the shelf bytes are invalid.</exception>
    internal (long ChildRouterOffset, long ShelfOffset) ReadTwoLevelRoutedFixed32Scalar16Shelf(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled FS32-16 shelf extent size.", nameof(destination));
        }

        long childRouterOffset = FindRouterTarget(rootRouterOffset, rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The root route to the transformed child router is unset.");
        }

        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the FS32-16 shelf is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar16ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The two-level routed FS32-16 shelf bytes are invalid.");
        }

        return (childRouterOffset, shelfOffset);
    }


    /// <summary>
    /// Inserts one encoded tuple into an `FS32-16` shelf reached through a root router and one direct-index child router without performing split handling.<br/>
    /// This validates the first post-transform fixed-32-byte-key mutation path while deeper routed insert orchestration and generalized split selection are still shape-local.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the next structural path can be added later.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The child router offset, shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when either route is unset or the shelf bytes are invalid.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, Fixed32Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertTwoLevelRoutedFixed32Scalar16NoSplit(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long childRouterOffset = FindRouterTarget(rootRouterOffset, rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The root route to the transformed child router is unset.");
        }

        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the FS32-16 shelf is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The two-level routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult insertResult = shelf.Insert(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys);
        if (insertResult != Fixed32Scalar16InsertResult.Inserted)
        {
            return (childRouterOffset, shelfOffset, insertResult, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterOffset, shelfOffset, insertResult, telemetry);
    }


    /// <summary>
    /// Splits a full `FS32-16` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the fixed-32-byte-key counterpart to the validated `SS16-8` walked shelf-transform path and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-16` shelf or the transform cannot partition safely.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedFixed32Scalar16ByShelfTransform(
            long rootRouterOffset,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Fixed32Scalar16RouteTarget target = WalkFixed32Scalar16RouteTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        return SplitRoutedFixed32Scalar16ByShelfTransform(
            target.Offset,
            existingShelf,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            target.AllocationClassId,
            nextRouterKeyDepth);
    }


    /// <summary>
    /// Splits a full `FS32-16` shelf reached by the classified route walker by refining the parent router routes that already point at that shelf.<br/>
    /// This is the normal split counterpart to the transform path: the full shelf offset is rewritten for the left side, one right shelf is appended, and the parent router is rewritten.<br/>
    /// The method returns false when the parent router byte cannot distinguish the full shelf plus incoming tuple, allowing callers to choose a deeper transform instead.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>Whether the parent split occurred, the parent router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-16` shelf or the parent router is invalid.</exception>
    internal (
        bool DidSplit,
        long ParentRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedFixed32Scalar16ByParentRoute(
            long rootRouterOffset,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        if (!TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out int leftItemCount,
            out int rightItemCount,
            out Fixed32Scalar16InsertResult insertResult,
            out DataKernelCommitTelemetry telemetry))
        {
            return (false, pathTarget.ParentRouterOffset, target.Offset, 0, 0, 0, insertResult, default);
        }

        return (true, parentRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, telemetry);
    }


    /// <summary>
    /// Tries to split a full walked `FS32-16` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local fixed-32-byte-key counterpart to the `SS16-8` parent-route split helper.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    /// <summary>
    /// Tries the allocation-minimal `FS32-16` sorted-tail split while preserving the original shelf as the left child.<br/>
    /// The source must be a full, deletion-free, dense physical image ordered by the parent-route prefix, and the incoming tuple must append after its last tuple.<br/>
    /// On success only the left count, one appended right shelf, and the direct parent router are staged; the caller retains the truncated source image for unpublished left-prefix cells.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The direct parent router offset that selects the full shelf.<br/></param>
    /// <param name="fullShelfOffset">The existing shelf offset retained as the left split child.<br/></param>
    /// <param name="existingShelfBytes">The mutable batch-owned full shelf image to truncate in place.<br/></param>
    /// <param name="parentRouterKeyDepth">The key byte depth selected by the parent router.<br/></param>
    /// <param name="profile">The active `FS32-16` shelf profile.<br/></param>
    /// <param name="key0">The first incoming key lane.<br/></param>
    /// <param name="key1">The second incoming key lane.<br/></param>
    /// <param name="key2">The third incoming key lane.<br/></param>
    /// <param name="key3">The fourth incoming key lane.<br/></param>
    /// <param name="encodedIdentityHigh">The incoming high identity lane.<br/></param>
    /// <param name="encodedIdentityLow">The incoming low identity lane.<br/></param>
    /// <param name="allowDuplicateKeys">Whether an equal key with a strictly greater identity may append.<br/></param>
    /// <param name="parentDepthCannotSplit">True when the dense sorted shelf and incoming tuple all share one prefix at the parent depth, proving parent refinement cannot split them.<br/></param>
    /// <param name="rightShelfOffset">The appended right shelf offset on success.<br/></param>
    /// <param name="telemetry">The structural commit telemetry on success.<br/></param>
    /// <returns>True only when the sorted-tail split was proven safe and committed.<br/></returns>
    private bool TrySplitRoutedFixed32Scalar16SortedTail(
        long parentRouterOffset,
        long fullShelfOffset,
        Span<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        out bool parentDepthCannotSplit,
        out long rightShelfOffset,
        out DataKernelCommitTelemetry telemetry)
    {
        parentDepthCannotSplit = false;
        rightShelfOffset = 0;
        telemetry = default;
        Fixed32BatchAttributionDiagnostics? attribution = Fixed32BatchAttributionDiagnostics.Current;
        Fixed32Scalar16ReadOnly sortedShelf = new(existingShelfBytes, profile);
        if (!sortedShelf.IsValid ||
            sortedShelf.ItemCount != profile.MaxItemCount ||
            sortedShelf.DeletedItemCount != 0)
        {
            if (attribution is not null)
                attribution.SortedRejectedInvalidOrNotFull++;
            return false;
        }

        int lastSlotIndex = sortedShelf.ItemCount - 1;
        int incomingKeyComparison = CompareFixed32Scalar16Tuple(
            sortedShelf.ReadKeyPart0At(lastSlotIndex),
            sortedShelf.ReadKeyPart1At(lastSlotIndex),
            sortedShelf.ReadKeyPart2At(lastSlotIndex),
            sortedShelf.ReadKeyPart3At(lastSlotIndex),
            0,
            0,
            key0,
            key1,
            key2,
            key3,
            0,
            0);
        ulong lastIdentityHigh = sortedShelf.ReadIdentityHighAt(lastSlotIndex);
        ulong lastIdentityLow = sortedShelf.ReadIdentityLowAt(lastSlotIndex);
        bool identityAppends = lastIdentityHigh < encodedIdentityHigh ||
            (lastIdentityHigh == encodedIdentityHigh && lastIdentityLow < encodedIdentityLow);
        if (incomingKeyComparison > 0 ||
            (incomingKeyComparison == 0 && (!allowDuplicateKeys || !identityAppends)))
        {
            if (attribution is not null)
                attribution.SortedRejectedNotAppend++;
            return false;
        }

        int desiredRightStart = sortedShelf.ItemCount / 2;
        int rightStartSlot = 0;
        int lastTransitionBeforeMedian = 0;
        byte selectedRightPrefixByte = 0;
        byte transitionBeforeMedianPrefixByte = 0;
        byte previousPrefixByte = GetFixed32Scalar16Prefix(
            sortedShelf.ReadKeyPart0At(0),
            sortedShelf.ReadKeyPart1At(0),
            sortedShelf.ReadKeyPart2At(0),
            sortedShelf.ReadKeyPart3At(0),
            parentRouterKeyDepth);
        bool denseSortedPrefix = Fixed32Scalar16Layout.ReadSlot(existingShelfBytes, profile, 0) == Fixed32Scalar16Layout.GetItemOffset(profile, 0);
        for (int slotIndex = 1; denseSortedPrefix && slotIndex < sortedShelf.ItemCount; slotIndex++)
        {
            if (attribution is not null)
                attribution.SortedScannedSlots++;
            denseSortedPrefix = Fixed32Scalar16Layout.ReadSlot(existingShelfBytes, profile, slotIndex) == Fixed32Scalar16Layout.GetItemOffset(profile, slotIndex);
            byte prefixByte = GetFixed32Scalar16Prefix(
                sortedShelf.ReadKeyPart0At(slotIndex),
                sortedShelf.ReadKeyPart1At(slotIndex),
                sortedShelf.ReadKeyPart2At(slotIndex),
                sortedShelf.ReadKeyPart3At(slotIndex),
                parentRouterKeyDepth);
            if (prefixByte < previousPrefixByte)
            {
                if (attribution is not null)
                    attribution.SortedRejectedNoPrefixBoundary++;
                return false;
            }

            if (prefixByte > previousPrefixByte)
            {
                if (slotIndex >= desiredRightStart && rightStartSlot == 0)
                {
                    rightStartSlot = slotIndex;
                    selectedRightPrefixByte = prefixByte;
                }
                else if (slotIndex < desiredRightStart)
                {
                    lastTransitionBeforeMedian = slotIndex;
                    transitionBeforeMedianPrefixByte = prefixByte;
                }
            }

            previousPrefixByte = prefixByte;
        }

        if (rightStartSlot == 0 && lastTransitionBeforeMedian != 0)
        {
            rightStartSlot = lastTransitionBeforeMedian;
            selectedRightPrefixByte = transitionBeforeMedianPrefixByte;
        }

        byte incomingPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, parentRouterKeyDepth);
        parentDepthCannotSplit = denseSortedPrefix &&
            rightStartSlot == 0 &&
            lastTransitionBeforeMedian == 0 &&
            incomingPrefixByte == previousPrefixByte;
        if (parentDepthCannotSplit && attribution is not null)
            attribution.SortedParentDepthImpossibleFastRejects++;
        if (!denseSortedPrefix || rightStartSlot == 0 || incomingPrefixByte < selectedRightPrefixByte)
        {
            if (attribution is not null)
                attribution.SortedRejectedNoPrefixBoundary++;
            return false;
        }

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid ||
            !parentReader.HasDirectIndex ||
            parentReader.GetDirectTarget(incomingPrefixByte) != fullShelfOffset)
        {
            throw new InvalidDataException("The walked sorted FS32-16 parent route no longer points to the classified full shelf.");
        }

        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 rightShelf = new(rightAppend.Span, profile);
        rightShelf.Initialize();
        for (int slotIndex = rightStartSlot; slotIndex < sortedShelf.ItemCount; slotIndex++)
        {
            if (attribution is not null)
                attribution.SortedCopiedItems++;
            Fixed32Scalar16InsertResult movedResult = rightShelf.Insert(
                sortedShelf.ReadKeyPart0At(slotIndex),
                sortedShelf.ReadKeyPart1At(slotIndex),
                sortedShelf.ReadKeyPart2At(slotIndex),
                sortedShelf.ReadKeyPart3At(slotIndex),
                sortedShelf.ReadIdentityHighAt(slotIndex),
                sortedShelf.ReadIdentityLowAt(slotIndex),
                allowDuplicateKeys);
            if (movedResult != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected sorted-tail FS32-16 move at slot {slotIndex}, got {movedResult}.");
            }
        }

        Fixed32Scalar16InsertResult insertResult = rightShelf.Insert(key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys);
        if (insertResult != Fixed32Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected sorted-tail FS32-16 incoming insert, got {insertResult}.");
        }

        Fixed32Scalar16Layout.WriteItemCount(existingShelfBytes, checked((ushort)rightStartSlot));
        fixed32Scalar16CleanShelfCache.Remove(fullShelfOffset);
        RawDataReservation leftCountRewrite = kernel.ReserveAt(fullShelfOffset + Fixed32Scalar16Layout.ItemCountOffset, sizeof(ushort));
        existingShelfBytes.Slice(Fixed32Scalar16Layout.ItemCountOffset, sizeof(ushort)).CopyTo(leftCountRewrite.Span);

        RawDataReservation parentRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRewrite.Span);
        RouterWriter parentWriter = new(parentRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte ? fullShelfOffset : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }

    private bool TrySplitRoutedFixed32Scalar16ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar16InsertResult insertResult,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        telemetry = default;

        if (!TryCreateFixed32Scalar16SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetFixed32Scalar16Prefix(key0, key1, key2, key3, parentRouterKeyDepth),
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked FS32-16 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }


    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-16` route walker when the routed shelf has room for a no-split rewrite.<br/>
    /// The method supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// Full-shelf split selection remains deliberately outside this slice; walked transform and parent-route refinement are added as separate validated steps.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-16` shelf or when a full shelf requires a not-yet-selected walked split path.</exception>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        return InsertWalkedRoutedFixed32Scalar16(
            rootRouterOffset,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh: 0,
            encodedIdentityLow: encodedIdentity,
            allowDuplicateKeys,
            maxRouterHops);
    }

    /// <summary>
    /// Inserts one encoded full-identity tuple through the classified `FS32-16` route walker.<br/>
    /// This overload preserves both persisted identity lanes through no-split inserts and walked split paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-16` shelf or a split cannot preserve shape invariants.</exception>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out Fixed32Scalar16MutationBounds mutationBounds);
        if (insertResult == Fixed32Scalar16InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Fixed32Scalar16InsertResult.AlreadyPresent)
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Fixed32Scalar16InsertResult.KeyConflict)
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Fixed32Scalar16InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported FS32-16 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Fixed32Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar16ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                key0,
                key1,
                key2,
                key3,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Fixed32Scalar16RoutedInsertKind kind = transformResult == Fixed32Scalar16InsertResult.Inserted
            ? Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit
            : Fixed32Scalar16RoutedInsertKind.NoOp;
        return new Fixed32Scalar16RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-16` route walker using a caller-owned full shelf image as the split source.<br/>
    /// Batch-local write paths use this when a cached shelf reaches capacity before the active durability batch has published its pending shelf bytes.<br/>
    /// The method keeps those pending bytes in the structural split input and avoids staging the full shelf image over the router or replacement shelf written by the split.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent sizing.<br/></param>
    /// <param name="fullShelfOffset">The routed shelf offset represented by <paramref name="fullShelfBytes"/>.<br/></param>
    /// <param name="fullShelfBytes">The full batch-local shelf image to split or rewrite.<br/></param>
    /// <param name="key0">The first encoded key lane to insert.<br/></param>
    /// <param name="key1">The second encoded key lane to insert.<br/></param>
    /// <param name="key2">The third encoded key lane to insert.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation was staged.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing no longer resolves to <paramref name="fullShelfOffset"/>, the shelf image is invalid, or the split cannot be selected safely.<br/></exception>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16FromShelfImage(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        long fullShelfOffset,
        ReadOnlySpan<byte> fullShelfBytes,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The FS32-16 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf || target.Offset != fullShelfOffset)
            throw new InvalidDataException("The classified FS32-16 route no longer resolves to the supplied full shelf image.");

        Fixed32Scalar16ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied FS32-16 split source shelf image is invalid.");

        byte[] rewrittenShelf = fullShelfBytes.ToArray();
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
        if (insertResult == Fixed32Scalar16InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar16RoutedInsertResult(Fixed32Scalar16RoutedInsertKind.WalkedNoSplit, insertResult, target.Offset, target.Offset, 0, telemetry);
        }

        if (insertResult == Fixed32Scalar16InsertResult.AlreadyPresent)
            return new Fixed32Scalar16RoutedInsertResult(Fixed32Scalar16RoutedInsertKind.NoOp, insertResult, target.Offset, 0, 0, default);

        if (insertResult == Fixed32Scalar16InsertResult.KeyConflict)
            return new Fixed32Scalar16RoutedInsertResult(Fixed32Scalar16RoutedInsertKind.KeyConflict, insertResult, target.Offset, 0, 0, default);

        if (insertResult != Fixed32Scalar16InsertResult.Full)
            throw new InvalidDataException($"Unsupported FS32-16 shelf-image insert result {insertResult}.");

        if (TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar16RoutedInsertResult(Fixed32Scalar16RoutedInsertKind.WalkedParentRouteSplit, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Fixed32Scalar16InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar16ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Fixed32Scalar16RoutedInsertKind kind = transformResult == Fixed32Scalar16InsertResult.Inserted ? Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit : Fixed32Scalar16RoutedInsertKind.NoOp;
        return new Fixed32Scalar16RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Splits one full `FS32-16` shelf image through its already classified direct parent route.<br/>
    /// The caller must retain the path from the current single-writer topology and clear it after any structural mutation; this avoids a redundant root walk and a redundant full-shelf insertion retry.<br/>
    /// </summary>
    /// <param name="pathTarget">The current terminal shelf target and direct parent route that selected it.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile that owns the supplied image.<br/></param>
    /// <param name="fullShelfBytes">The validated full shelf image already tested by the caller's in-place insert.<br/></param>
    /// <param name="key0">The first encoded key lane to insert during the split.<br/></param>
    /// <param name="key1">The second encoded key lane to insert during the split.<br/></param>
    /// <param name="key2">The third encoded key lane to insert during the split.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert during the split.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert during the split.<br/></param>
    /// <param name="allowDuplicateKeys">Whether equal keys with distinct identities are permitted during the optimized split.<br/></param>
    /// <returns>The storage-facing routed split result and deferred or immediate commit telemetry.<br/></returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="fullShelfBytes"/> is not one profiled shelf extent.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when the retained target, route prefix, or shelf image is invalid.<br/></exception>
    internal Fixed32Scalar16RoutedInsertResult SplitRoutedFixed32Scalar16FromShelfImage(
        Fixed32Scalar16RoutePathTarget pathTarget,
        Fixed32Scalar16Profile profile,
        Span<byte> fullShelfBytes,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys)
    {
        if (fullShelfBytes.Length != profile.ShelfExtentSize)
            throw new ArgumentException("The FS32-16 split source shelf image must match the profiled shelf extent size.", nameof(fullShelfBytes));

        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf ||
            GetFixed32Scalar16Prefix(key0, key1, key2, key3, target.RouterDepth) != pathTarget.RoutePrefixByte)
        {
            throw new InvalidDataException("The retained FS32-16 path does not classify the supplied split key to a shelf.");
        }

        Fixed32Scalar16ReadOnly existingReadOnly = new(fullShelfBytes, profile);
        if (!existingReadOnly.IsValid)
            throw new InvalidDataException("The supplied FS32-16 split source shelf image is invalid.");

        if (TrySplitRoutedFixed32Scalar16SortedTail(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            allowDuplicateKeys,
            out bool parentDepthCannotSplit,
            out long sortedRightShelfOffset,
            out DataKernelCommitTelemetry sortedTailCommit))
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.WalkedSortedTailSplit,
                Fixed32Scalar16InsertResult.Inserted,
                pathTarget.ParentRouterOffset,
                target.Offset,
                sortedRightShelfOffset,
                sortedTailCommit);
        }

        if (!parentDepthCannotSplit && TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            fullShelfBytes,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar16RoutedInsertResult(Fixed32Scalar16RoutedInsertKind.WalkedParentRouteSplit, parentSplitResult, parentRouterOffset, leftShelfOffset, rightShelfOffset, parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (long childRouterOffset, long transformLeftShelfOffset, long transformRightShelfOffset, _, _, Fixed32Scalar16InsertResult transformResult, DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar16ByShelfTransform(
            target.Offset,
            fullShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            target.AllocationClassId,
            nextRouterKeyDepth);

        Fixed32Scalar16RoutedInsertKind kind = transformResult == Fixed32Scalar16InsertResult.Inserted ? Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit : Fixed32Scalar16RoutedInsertKind.NoOp;
        return new Fixed32Scalar16RoutedInsertResult(kind, transformResult, childRouterOffset, transformLeftShelfOffset, transformRightShelfOffset, transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-16` route walker using an isolated writer context.<br/>
    /// This method intentionally accepts only bounded local cases: the route must already resolve to a non-empty ordinary shelf that can fit the tuple without split or route publication work.<br/>
    /// Successful inserts stage the rewritten shelf in <paramref name="writeContext"/> and become visible only when <see cref="PublishFixed32Scalar16WriteContext"/> publishes that context.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="key0">The first encoded key lane to insert.<br/></param>
    /// <param name="key1">The second encoded key lane to insert.<br/></param>
    /// <param name="key2">The third encoded key lane to insert.<br/></param>
    /// <param name="key3">The fourth encoded key lane to insert.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert.<br/></param>
    /// <param name="allowDuplicateKeys">Whether multiple identities may share the same encoded key.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>The storage-facing routed insert result; commit telemetry is default because publication is deferred to the writer context.<br/></returns>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16NoSplitForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterFixed32Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
            Fixed32Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
            }

            byte[] existingShelf = ReadFixed32Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordFixed32Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
            if (!existingReadOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed FS32-16 shelf bytes are invalid.");
            }

            if (existingReadOnly.ItemCount == 0)
            {
                throw new InvalidOperationException("The FS32-16 writer-context insert cannot mutate an empty routed shelf because the current serialized path owns route initialization.");
            }

            Fixed32Scalar16 shelf = new(existingShelf, profile);
            Fixed32Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out _);
            if (insertResult == Fixed32Scalar16InsertResult.Inserted)
            {
                StageFixed32Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
                return new Fixed32Scalar16RoutedInsertResult(
                    Fixed32Scalar16RoutedInsertKind.WalkedNoSplit,
                    insertResult,
                    target.Offset,
                    target.Offset,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar16InsertResult.AlreadyPresent)
            {
                return new Fixed32Scalar16RoutedInsertResult(
                    Fixed32Scalar16RoutedInsertKind.NoOp,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar16InsertResult.KeyConflict)
            {
                return new Fixed32Scalar16RoutedInsertResult(
                    Fixed32Scalar16RoutedInsertKind.KeyConflict,
                    insertResult,
                    target.Offset,
                    0,
                    0,
                    default);
            }

            if (insertResult == Fixed32Scalar16InsertResult.Full)
            {
                throw new InvalidOperationException("The FS32-16 writer-context insert cannot split a full shelf because route topology publication is not writer-context isolated yet.");
            }

            throw new InvalidDataException($"Unsupported FS32-16 writer-context insert result {insertResult}.");
        }
        finally
        {
            ExitFixed32Scalar16WriterContextStaging(rootRouterOffset);
        }
    }

    /// <summary>
    /// Deletes one exact encoded `FS32-16` tuple through the classified route walker using an isolated writer context.<br/>
    /// The supported writer-local shape is bounded to a route that resolves to a non-empty shelf where the exact key/identity tuple is present in that shelf image.<br/>
    /// </summary>
    /// <param name="writeContext">The isolated writer context that owns staged shelf bytes until publish or abort.<br/></param>
    /// <param name="rootRouterOffset">The file offset where the root router starts.<br/></param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.<br/></param>
    /// <param name="key0">The first encoded key lane to delete.<br/></param>
    /// <param name="key1">The second encoded key lane to delete.<br/></param>
    /// <param name="key2">The third encoded key lane to delete.<br/></param>
    /// <param name="key3">The fourth encoded key lane to delete.<br/></param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to delete.<br/></param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to delete.<br/></param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.<br/></param>
    /// <returns>True when one tuple was staged for deletion; false when the exact tuple was not present.<br/></returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="writeContext"/> is null.<br/></exception>
    /// <exception cref="InvalidDataException">Thrown when routing or shelf bytes are invalid.<br/></exception>
    internal bool DeleteWalkedRoutedFixed32Scalar16ExactForWriteContext(
        LibraDexWriteContext writeContext,
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        int maxRouterHops)
    {
        ArgumentNullException.ThrowIfNull(writeContext);
        EnterFixed32Scalar16WriterContextStaging(rootRouterOffset);
        try
        {
            Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
            Fixed32Scalar16RouteTarget target = pathTarget.Target;
            if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
            {
                throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
            }

            byte[] existingShelf = ReadFixed32Scalar16ShelfBytesForWriteContext(writeContext, target.Offset, profile);
            RecordFixed32Scalar16RouteClaimForWriteContext(writeContext, pathTarget);
            Fixed32Scalar16ReadOnly readOnly = new(existingShelf, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException("The walked routed FS32-16 delete shelf bytes are invalid.");
            }

            int startSlot = readOnly.LowerBoundKey(key0, key1, key2, key3);
            int deleteSlot = -1;
            for (int slot = startSlot; slot < readOnly.ItemCount; slot++)
            {
                int compare = CompareFixed32Scalar8Key(
                    readOnly.ReadKeyPart0At(slot),
                    readOnly.ReadKeyPart1At(slot),
                    readOnly.ReadKeyPart2At(slot),
                    readOnly.ReadKeyPart3At(slot),
                    key0,
                    key1,
                    key2,
                    key3);
                if (compare != 0)
                {
                    break;
                }

                if (readOnly.ReadIdentityHighAt(slot) == encodedIdentityHigh &&
                    readOnly.ReadIdentityLowAt(slot) == encodedIdentityLow)
                {
                    deleteSlot = slot;
                    break;
                }
            }

            if (deleteSlot < 0)
            {
                return false;
            }

            Fixed32Scalar16 shelf = new(existingShelf, profile);
            int removed = shelf.RemoveSlotRange(deleteSlot, 1);
            if (removed != 1)
            {
                return false;
            }

            StageFixed32Scalar16ShelfRewriteForWriteContext(writeContext, target.Offset, profile, existingShelf);
            return true;
        }
        finally
        {
            ExitFixed32Scalar16WriterContextStaging(rootRouterOffset);
        }
    }


    /// <summary>
    /// Compares two encoded `FS32-16` tuples using the persisted shelf ordering.<br/>
    /// Keys compare by four fixed key parts, then identity, so this helper can merge an incoming split tuple without constructing a temporary shelf.<br/>
    /// </summary>
    /// <param name="left0">The left encoded key part 0.</param>
    /// <param name="left1">The left encoded key part 1.</param>
    /// <param name="left2">The left encoded key part 2.</param>
    /// <param name="left3">The left encoded key part 3.</param>
    /// <param name="leftIdentity">The left encoded identity.</param>
    /// <param name="right0">The right encoded key part 0.</param>
    /// <param name="right1">The right encoded key part 1.</param>
    /// <param name="right2">The right encoded key part 2.</param>
    /// <param name="right3">The right encoded key part 3.</param>
    /// <param name="rightIdentity">The right encoded identity.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareFixed32Scalar16Tuple(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong leftIdentity,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3,
        ulong rightIdentity)
    {
        return CompareFixed32Scalar16Tuple(
            left0,
            left1,
            left2,
            left3,
            0,
            leftIdentity,
            right0,
            right1,
            right2,
            right3,
            0,
            rightIdentity);
    }

    /// <summary>
    /// Compares two encoded `FS32-16` full-identity tuples using the persisted shelf ordering.<br/>
    /// Keys compare by four fixed key parts, then identity high and identity low, matching the physical slot order.<br/>
    /// </summary>
    /// <param name="left0">The left encoded key part 0.</param>
    /// <param name="left1">The left encoded key part 1.</param>
    /// <param name="left2">The left encoded key part 2.</param>
    /// <param name="left3">The left encoded key part 3.</param>
    /// <param name="leftIdentityHigh">The left encoded high identity lane.</param>
    /// <param name="leftIdentityLow">The left encoded low identity lane.</param>
    /// <param name="right0">The right encoded key part 0.</param>
    /// <param name="right1">The right encoded key part 1.</param>
    /// <param name="right2">The right encoded key part 2.</param>
    /// <param name="right3">The right encoded key part 3.</param>
    /// <param name="rightIdentityHigh">The right encoded high identity lane.</param>
    /// <param name="rightIdentityLow">The right encoded low identity lane.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareFixed32Scalar16Tuple(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        if (left0 != right0)
        {
            return left0 < right0 ? -1 : 1;
        }

        if (left1 != right1)
        {
            return left1 < right1 ? -1 : 1;
        }

        if (left2 != right2)
        {
            return left2 < right2 ? -1 : 1;
        }

        if (left3 != right3)
        {
            return left3 < right3 ? -1 : 1;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        if (leftIdentityLow > rightIdentityLow)
        {
            return 1;
        }

        return 0;
    }


    /// <summary>
    /// Extracts one persisted prefix byte from an encoded `FS32-16` key.<br/>
    /// The fixed key is stored in canonical sortable byte order as four 64-bit parts, so depths `0..31` read those parts from left to right.<br/>
    /// </summary>
    /// <param name="key0">The encoded fixed key part 0.</param>
    /// <param name="key1">The encoded fixed key part 1.</param>
    /// <param name="key2">The encoded fixed key part 2.</param>
    /// <param name="key3">The encoded fixed key part 3.</param>
    /// <param name="keyDepth">The zero-based byte depth to extract.</param>
    /// <returns>The persisted key byte at the requested depth.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="keyDepth"/> is outside the 32-byte fixed key.</exception>
    private static byte GetFixed32Scalar16Prefix(ulong key0, ulong key1, ulong key2, ulong key3, int keyDepth)
    {
        if ((uint)keyDepth >= Fixed32Scalar16Layout.KeySize)
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-16 fixed keys expose exactly thirty-two routing bytes.");
        }

        int partDepth = keyDepth % sizeof(ulong);
        int shift = (sizeof(ulong) - 1 - partDepth) * 8;
        return (keyDepth / sizeof(ulong)) switch
        {
            0 => (byte)(key0 >> shift),
            1 => (byte)(key1 >> shift),
            2 => (byte)(key2 >> shift),
            3 => (byte)(key3 >> shift),
            _ => throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-16 fixed keys expose exactly thirty-two routing bytes.")
        };
    }

    private sealed class VarKeyScalar8PhaseAllocationDiagnostics
    {
        private readonly Dictionary<string, VarKeyScalar8PhaseAllocationCounter> counters = new(StringComparer.Ordinal);

        internal void Record(string phaseName, long elapsedTicks, long allocatedBytes)
        {
            if (!counters.TryGetValue(phaseName, out VarKeyScalar8PhaseAllocationCounter? counter))
            {
                counter = new VarKeyScalar8PhaseAllocationCounter(phaseName);
                counters.Add(phaseName, counter);
            }

            counter.Record(elapsedTicks, allocatedBytes);
        }

        internal string CreateSummary()
        {
            if (counters.Count == 0)
            {
                return "none";
            }

            StringBuilder builder = new();
            foreach (VarKeyScalar8PhaseAllocationCounter counter in counters.Values.OrderByDescending(static item => item.AllocatedBytes))
            {
                if (builder.Length != 0)
                {
                    builder.Append(" | ");
                }

                builder
                    .Append(counter.Name)
                    .Append(": calls=")
                    .Append(counter.Calls.ToString("N0", CultureInfo.InvariantCulture))
                    .Append("; elapsed=")
                    .Append(FormatVarKeyScalar8PhaseDuration(counter.Elapsed))
                    .Append("; allocated=")
                    .Append(FormatVarKeyScalar8PhaseBytes(counter.AllocatedBytes));
            }

            return builder.ToString();
        }
    }

    private sealed class VarKeyScalar8PhaseAllocationCounter
    {
        internal VarKeyScalar8PhaseAllocationCounter(string name)
        {
            Name = name;
        }

        internal string Name { get; }

        internal long Calls { get; private set; }

        internal long ElapsedTicks { get; private set; }

        internal long AllocatedBytes { get; private set; }

        internal TimeSpan Elapsed => TimeSpan.FromTicks((long)(ElapsedTicks * (TimeSpan.TicksPerSecond / (double)Stopwatch.Frequency)));

        internal void Record(long elapsedTicks, long allocatedBytes)
        {
            Calls++;
            ElapsedTicks += elapsedTicks;
            AllocatedBytes += allocatedBytes;
        }
    }

    private static string FormatVarKeyScalar8PhaseDuration(TimeSpan elapsed)
    {
        return elapsed.TotalSeconds >= 1
            ? $"{elapsed.TotalSeconds:n2}s"
            : $"{elapsed.TotalMilliseconds:n0}ms";
    }

    private static string FormatVarKeyScalar8PhaseBytes(long bytes)
    {
        const double KiB = 1024;
        const double MiB = KiB * 1024;
        const double GiB = MiB * 1024;
        return bytes >= GiB
            ? $"{bytes / GiB:n1} GB"
            : bytes >= MiB
                ? $"{bytes / MiB:n1} MB"
                : bytes >= KiB
                    ? $"{bytes / KiB:n1} KB"
                    : $"{bytes:n0} B";
    }

    /// <summary>
    /// Stores one fixed-32 route prefix without retaining or allocating caller key objects.<br/>
    /// The prefix is shared by the `FS32-8` and `FS32-16` cross-batch route hints.<br/>
    /// </summary>
    /// <param name="Depth">The zero-based final encoded-key byte consumed by the route.<br/></param>
    /// <param name="Prefix0">The retained prefix bits from the first key lane.<br/></param>
    /// <param name="Prefix1">The retained prefix bits from the second key lane.<br/></param>
    /// <param name="Prefix2">The retained prefix bits from the third key lane.<br/></param>
    /// <param name="Prefix3">The retained prefix bits from the fourth key lane.<br/></param>
    private readonly record struct Fixed32BatchRouteHintPrefix(byte Depth, ulong Prefix0, ulong Prefix1, ulong Prefix2, ulong Prefix3)
    {
        /// <summary>
        /// Creates one retained fixed-32 prefix through a validated router depth.<br/>
        /// </summary>
        /// <param name="key0">The first encoded fixed-key lane.<br/></param>
        /// <param name="key1">The second encoded fixed-key lane.<br/></param>
        /// <param name="key2">The third encoded fixed-key lane.<br/></param>
        /// <param name="key3">The fourth encoded fixed-key lane.<br/></param>
        /// <param name="routerDepth">The zero-based final encoded-key byte consumed by the route.<br/></param>
        /// <returns>The allocation-free retained prefix.<br/></returns>
        internal static Fixed32BatchRouteHintPrefix Create(ulong key0, ulong key1, ulong key2, ulong key3, ushort routerDepth)
        {
            if (routerDepth > 31)
            {
                throw new InvalidDataException($"The fixed-32 route depth {routerDepth} cannot produce a cross-batch route hint.");
            }

            byte depth = (byte)routerDepth;
            int prefixBits = (depth + 1) * 8;
            ulong prefix0 = 0;
            ulong prefix1 = 0;
            ulong prefix2 = 0;
            ulong prefix3 = 0;
            if (prefixBits <= 64)
            {
                prefix0 = key0 >> (64 - prefixBits);
            }
            else if (prefixBits <= 128)
            {
                prefix0 = key0;
                prefix1 = key1 >> (128 - prefixBits);
            }
            else if (prefixBits <= 192)
            {
                prefix0 = key0;
                prefix1 = key1;
                prefix2 = key2 >> (192 - prefixBits);
            }
            else
            {
                prefix0 = key0;
                prefix1 = key1;
                prefix2 = key2;
                prefix3 = key3 >> (256 - prefixBits);
            }

            return new Fixed32BatchRouteHintPrefix(depth, prefix0, prefix1, prefix2, prefix3);
        }

        /// <summary>
        /// Tests whether one encoded key remains inside the retained routed prefix.<br/>
        /// </summary>
        /// <param name="key0">The first encoded fixed-key lane.<br/></param>
        /// <param name="key1">The second encoded fixed-key lane.<br/></param>
        /// <param name="key2">The third encoded fixed-key lane.<br/></param>
        /// <param name="key3">The fourth encoded fixed-key lane.<br/></param>
        /// <returns><see langword="true"/> when the encoded key shares every routed prefix byte.<br/></returns>
        internal bool Matches(ulong key0, ulong key1, ulong key2, ulong key3)
        {
            return this == Create(key0, key1, key2, key3, Depth);
        }
    }

    /// <summary>
    /// Counts equal leading bytes across two encoded fixed-32 keys using lane XOR and leading-zero counts.<br/>
    /// </summary>
    /// <param name="left0">The first lane of the retained encoded key.<br/></param>
    /// <param name="left1">The second lane of the retained encoded key.<br/></param>
    /// <param name="left2">The third lane of the retained encoded key.<br/></param>
    /// <param name="left3">The fourth lane of the retained encoded key.<br/></param>
    /// <param name="right0">The first lane of the candidate encoded key.<br/></param>
    /// <param name="right1">The second lane of the candidate encoded key.<br/></param>
    /// <param name="right2">The third lane of the candidate encoded key.<br/></param>
    /// <param name="right3">The fourth lane of the candidate encoded key.<br/></param>
    /// <returns>The number of equal leading encoded-key bytes from zero through thirty-two.<br/></returns>
    private static int GetFixed32BatchRouteHintCommonPrefixByteCount(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3)
    {
        ulong difference = left0 ^ right0;
        if (difference != 0) return System.Numerics.BitOperations.LeadingZeroCount(difference) / 8;
        difference = left1 ^ right1;
        if (difference != 0) return 8 + (System.Numerics.BitOperations.LeadingZeroCount(difference) / 8);
        difference = left2 ^ right2;
        if (difference != 0) return 16 + (System.Numerics.BitOperations.LeadingZeroCount(difference) / 8);
        difference = left3 ^ right3;
        return difference == 0 ? 32 : 24 + (System.Numerics.BitOperations.LeadingZeroCount(difference) / 8);
    }

    /// <summary>
    /// Retains one publication-safe `FS32-8` path under its routed prefix.<br/>
    /// </summary>
    /// <param name="Prefix">The encoded-key prefix selecting the route.<br/></param>
    /// <param name="PathTarget">The terminal shelf and its direct parent route.<br/></param>
    /// <param name="Key0">The first encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key1">The second encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key2">The third encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key3">The fourth encoded lane of the key that selected the route.<br/></param>
    /// <param name="PrefixRangeStart">The first parent-router prefix mapped to the retained shelf.<br/></param>
    /// <param name="PrefixRangeEnd">The last parent-router prefix mapped to the retained shelf.<br/></param>
    private readonly record struct Fixed32Scalar8BatchRouteHint(
        Fixed32BatchRouteHintPrefix Prefix,
        Fixed32Scalar8RoutePathTarget PathTarget,
        ulong Key0,
        ulong Key1,
        ulong Key2,
        ulong Key3,
        byte PrefixRangeStart,
        byte PrefixRangeEnd);

    /// <summary>
    /// Retains one publication-safe `FS32-16` path under its routed prefix.<br/>
    /// </summary>
    /// <param name="Prefix">The encoded-key prefix selecting the route.<br/></param>
    /// <param name="PathTarget">The terminal shelf and its direct parent route.<br/></param>
    /// <param name="Key0">The first encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key1">The second encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key2">The third encoded lane of the key that selected the route.<br/></param>
    /// <param name="Key3">The fourth encoded lane of the key that selected the route.<br/></param>
    /// <param name="PrefixRangeStart">The first parent-router prefix mapped to the retained shelf.<br/></param>
    /// <param name="PrefixRangeEnd">The last parent-router prefix mapped to the retained shelf.<br/></param>
    private readonly record struct Fixed32Scalar16BatchRouteHint(
        Fixed32BatchRouteHintPrefix Prefix,
        Fixed32Scalar16RoutePathTarget PathTarget,
        ulong Key0,
        ulong Key1,
        ulong Key2,
        ulong Key3,
        byte PrefixRangeStart,
        byte PrefixRangeEnd);

}
